def ensure_state_history_dir(path: Path) -> None:
    path.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(path, 0o2775)
    except PermissionError:
        pass
    try:
        os.chown(path, -1, grp.getgrnam(MODE_STATE_GROUP).gr_gid)
    except (KeyError, PermissionError):
        pass


def atomic_write_json(path: Path, data: dict[str, Any], mode: int = 0o644) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        "w",
        encoding="utf-8",
        dir=str(path.parent),
        prefix=f".{path.name}.",
        delete=False,
    ) as tmp:
        json.dump(data, tmp, indent=2, sort_keys=False)
        tmp.write("\n")
        tmp_name = tmp.name

    os.chmod(tmp_name, mode)
    try:
        os.chown(tmp_name, -1, grp.getgrnam(MODE_STATE_GROUP).gr_gid)
    except (KeyError, PermissionError):
        pass
    os.replace(tmp_name, path)


def safe_atomic_write_json(path: Path, data: dict[str, Any], mode: int = 0o664) -> dict[str, Any] | None:
    try:
        atomic_write_json(path, data, mode)
        return None
    except OSError as exc:
        return {"path": str(path), "error": str(exc)}


def safe_append_jsonl(path: Path, data: dict[str, Any], mode: int = 0o664) -> dict[str, Any] | None:
    try:
        ensure_state_history_dir(path.parent)
        payload = (json.dumps(data, sort_keys=False) + "\n").encode("utf-8")
        flags = os.O_WRONLY | os.O_CREAT | os.O_APPEND
        if hasattr(os, "O_CLOEXEC"):
            flags |= os.O_CLOEXEC
        fd = os.open(path, flags, mode)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX)
            view = memoryview(payload)
            while view:
                written = os.write(fd, view)
                if written <= 0:
                    raise OSError("short append write")
                view = view[written:]
        finally:
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            except OSError:
                pass
            os.close(fd)
        try:
            os.chmod(path, mode)
        except PermissionError:
            pass
        try:
            os.chown(path, -1, grp.getgrnam(MODE_STATE_GROUP).gr_gid)
        except (KeyError, PermissionError):
            pass
        return None
    except OSError as exc:
        return {"path": str(path), "error": str(exc)}


def safe_append_text(path: Path, text: str, mode: int = 0o664) -> dict[str, Any] | None:
    try:
        ensure_state_history_dir(path.parent)
        payload = text.encode("utf-8")
        flags = os.O_WRONLY | os.O_CREAT | os.O_APPEND
        if hasattr(os, "O_CLOEXEC"):
            flags |= os.O_CLOEXEC
        fd = os.open(path, flags, mode)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX)
            view = memoryview(payload)
            while view:
                written = os.write(fd, view)
                if written <= 0:
                    raise OSError("short append write")
                view = view[written:]
        finally:
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            except OSError:
                pass
            os.close(fd)
        try:
            os.chmod(path, mode)
        except PermissionError:
            pass
        try:
            os.chown(path, -1, grp.getgrnam(MODE_STATE_GROUP).gr_gid)
        except (KeyError, PermissionError):
            pass
        return None
    except OSError as exc:
        return {"path": str(path), "error": str(exc)}


def safe_atomic_write_text(path: Path, text: str, mode: int = 0o664) -> dict[str, Any] | None:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(
            "w",
            encoding="utf-8",
            dir=str(path.parent),
            prefix=f".{path.name}.",
            delete=False,
        ) as tmp:
            tmp.write(text)
            tmp_name = tmp.name
        os.chmod(tmp_name, mode)
        try:
            os.chown(tmp_name, -1, grp.getgrnam(MODE_STATE_GROUP).gr_gid)
        except (KeyError, PermissionError):
            pass
        os.replace(tmp_name, path)
        return None
    except OSError as exc:
        return {"path": str(path), "error": str(exc)}


