def env_override_bool(name: str, default: bool) -> bool:
    raw = os.environ.get(name)
    if raw is None:
        return default
    return raw.lower() not in {"0", "false", "no", "off"}


def env_override_float(name: str, default: float, lower: float, upper: float) -> float:
    raw = os.environ.get(name)
    if raw is None:
        return max(lower, min(upper, default))
    try:
        value = float(raw)
    except ValueError:
        return max(lower, min(upper, default))
    return max(lower, min(upper, value))


def env_override_int(name: str, default: int, lower: int, upper: int) -> int:
    raw = os.environ.get(name)
    if raw is None:
        return max(lower, min(upper, default))
    try:
        value = int(raw)
    except ValueError:
        return max(lower, min(upper, default))
    return max(lower, min(upper, value))


def bool_value(value: Any, default: bool) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.lower() not in {"0", "false", "no", "off"}
    if value is None:
        return default
    return bool(value)


