def ai_cpu_route(
    workload_class: str = "medium",
    latency: str = "balanced",
    force: bool = False,
    write_latest: bool = True,
    cpu_thermal_map: dict[str, Any] | None = None,
    policy_data: dict[str, Any] | None = None,
    mode_data: dict[str, Any] | None = None,
    battery_data: dict[str, Any] | None = None,
) -> dict[str, Any]:
    thermal_map = cpu_thermal_map if isinstance(cpu_thermal_map, dict) else ai_cpu_thermal_map(write_latest=True)
    policy = policy_data if isinstance(policy_data, dict) else ai_policy(write_latest=True, cpu_thermal_map=thermal_map)
    mode = mode_data if isinstance(mode_data, dict) else mode_status()
    battery = battery_data if isinstance(battery_data, dict) else nested_get(policy, ["current", "battery"]) or battery_summary()
    data = ai_cpu_routing.build_route(
        workload_class=workload_class,
        latency=latency,
        force=force,
        thermal_map=thermal_map,
        policy=policy,
        mode=mode,
        battery=battery,
        config=ai_config(),
        mode_policy=mode_policy_document(),
        source_refs={
            "topology_latest": str(AI_CPU_TOPOLOGY_LATEST_PATH),
            "thermal_map_latest": str(AI_CPU_THERMAL_MAP_LATEST_PATH),
            "route_latest": str(AI_CPU_ROUTE_LATEST_PATH),
            "ai_policy_latest": str(AI_POLICY_LATEST_PATH),
        },
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
    )
    if write_latest:
        error = safe_atomic_write_json(AI_CPU_ROUTE_LATEST_PATH, data, 0o664)
        if error:
            data["write_error"] = error
    return data


def ai_cpu_test_profile(profile: str, seconds: float = 1.0, force: bool = False, write_latest: bool = True) -> dict[str, Any]:
    routing_config = ai_config().get("cpu_routing", {})
    if not isinstance(routing_config, dict):
        routing_config = {}
    max_seconds = float(routing_config.get("test_max_seconds", 5.0))
    duration = max(0.1, min(float(seconds), max_seconds))
    thermal_before = ai_cpu_thermal_map(write_latest=True)
    topology = ai_cpu_topology(write_latest=True)
    groups = topology.get("groups", {}) if isinstance(topology.get("groups"), dict) else {}
    profile_value = str(profile or "mixed-safe").strip().lower()
    route: dict[str, Any] | None = None
    if profile_value == "lp-e":
        cpus = [int(cpu) for cpu in groups.get("lp_e_cores", [])]
        basis = "direct_lp_e_group"
    elif profile_value == "e-cores":
        cpus = [int(cpu) for cpu in groups.get("e_cores", [])]
        basis = "direct_e_core_group"
    elif profile_value == "cool-p":
        available = thermal_before.get("available_by_role", {}) if isinstance(thermal_before.get("available_by_role"), dict) else {}
        cpus = [int(cpu) for cpu in available.get("p_cores", [])][:1]
        basis = "direct_one_available_p_core"
    elif profile_value == "background":
        route = ai_cpu_route("background", "background", force=force, write_latest=True)
        cpus = [int(cpu) for cpu in nested_get(route, ["route", "cpus"]) or []]
        basis = "route_background"
    else:
        route = ai_cpu_route("medium", "balanced", force=force, write_latest=True)
        cpus = [int(cpu) for cpu in nested_get(route, ["route", "cpus"]) or []]
        basis = "route_medium_balanced"
    avoid = {int(cpu) for cpu in nested_get(thermal_before, ["summary", "hard_avoid_cpus"]) or []}
    cpus = [cpu for cpu in sorted(set(cpus)) if cpu not in avoid]
    cpuset = compress_cpu_list(cpus)
    if not cpus:
        data = {
            "schema": f"{SCHEMA_PREFIX}_ai_cpu_affinity_test_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "profile": profile_value,
            "basis": basis,
            "error": "no CPU set available after thermal hard-avoid filtering",
            "thermal_before": thermal_before,
        }
        if write_latest:
            error = safe_atomic_write_json(AI_CPU_TEST_LATEST_PATH, data, 0o664)
            if error:
                data["write_error"] = error
        return data

    script = (
        "import json, os, time\n"
        "before=sorted(os.sched_getaffinity(0))\n"
        "deadline=time.monotonic()+float(os.environ.get('ABYSS_CPU_TEST_SECONDS','1'))\n"
        "ticks=0\n"
        "while time.monotonic()<deadline:\n"
        "    ticks+=1\n"
        "    time.sleep(0.02)\n"
        "after=sorted(os.sched_getaffinity(0))\n"
        "print(json.dumps({'ok': True, 'affinity_before': before, 'affinity_after': after, 'ticks': ticks}, sort_keys=False))\n"
    )
    env = ai_subprocess_env(ai_cpu_env_for_threads(max(1, min(len(cpus), 2))))
    env["ABYSS_CPU_TEST_SECONDS"] = str(duration)
    before_snapshot = ai_resource_snapshot()
    started = time.monotonic()
    out = run(["taskset", "-c", cpuset, sys.executable, "-c", script], timeout=duration + 5.0, env=env)
    elapsed = round(time.monotonic() - started, 3)
    after_snapshot = ai_resource_snapshot()
    parsed = parse_json_stdout(out["stdout"]) if out["stdout"] else None
    actual_after = parsed.get("affinity_after") if isinstance(parsed, dict) else []
    expected = set(cpus)
    actual = {int(cpu) for cpu in actual_after} if isinstance(actual_after, list) else set()
    affinity_ok = bool(actual) and actual.issubset(expected)
    data = {
        "schema": f"{SCHEMA_PREFIX}_ai_cpu_affinity_test_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(out["ok"] and affinity_ok),
        "profile": profile_value,
        "basis": basis,
        "duration_sec": duration,
        "elapsed_sec": elapsed,
        "cpus": cpus,
        "cpuset": cpuset,
        "returncode": out["returncode"],
        "affinity_ok": affinity_ok,
        "result": parsed,
        "stderr": out["stderr"][-1000:],
        "resource_profile": ai_resource_profile(before_snapshot, after_snapshot, "cpu_affinity_smoke", "taskset affinity verification with sleep-biased loop"),
        "thermal_before": thermal_before,
        "thermal_after": ai_cpu_thermal_map(write_latest=True),
        "route": route,
        "policy": {
            "facts_only": True,
            "load_profile": "sleep-biased affinity smoke; not a heavy thermal stress test",
        },
    }
    if write_latest:
        latest_error = safe_atomic_write_json(AI_CPU_TEST_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(AI_CPU_TEST_ROOT), data, 0o664)
        errors = [error for error in (latest_error, daily_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


def read_text_result(path: Path) -> dict[str, Any]:
    try:
        value = path.read_text(encoding="utf-8", errors="replace").strip()
        return {"ok": True, "path": str(path), "value": value}
    except OSError as exc:
        return {"ok": False, "path": str(path), "error": str(exc)}


def write_text_result(path: Path, value: str) -> dict[str, Any]:
    try:
        path.write_text(value, encoding="utf-8")
        return {"ok": True, "path": str(path), "value": value.strip(), "changed": True}
    except OSError as exc:
        return {"ok": False, "path": str(path), "value": value.strip(), "error": str(exc)}


