def cooling_thermal_audit(seconds: float = 10.0, interval: float = 2.0, write_latest: bool = True) -> dict[str, Any]:
    samples = cooling_sample_series(seconds, interval)
    series = cooling_series_summary(samples)
    latest = samples[-1] if samples else cooling_temperature_sample()
    summary = latest.get("summary", {})
    thermal_config = ai_config().get("thermal_policy", {})
    audit_window: list[dict[str, Any]] = []
    for sample in samples:
        temp_value = nested_get(sample, ["summary", "temperature_c_max"])
        if isinstance(temp_value, (int, float)):
            audit_window.append({
                "generated_at": sample.get("at"),
                "temperature_c_max": round(float(temp_value), 1),
                "source": "cooling_thermal_audit",
            })
    temp_delta = nested_get(series, ["temperature_c_max", "delta"])
    if isinstance(temp_delta, (int, float)) and temp_delta <= -3.0:
        audit_trend = "falling"
    elif isinstance(temp_delta, (int, float)) and temp_delta >= 3.0:
        audit_trend = "rising"
    else:
        audit_trend = "stable" if audit_window else "unknown"
    episode = thermal_episode_classification(
        audit_window,
        thresholds=thermal_config,
        trend=audit_trend,
        current=summary.get("temperature_c_max") if isinstance(summary.get("temperature_c_max"), (int, float)) else None,
        recent_peak=nested_get(series, ["temperature_c_max", "max"]),
        rolling_avg=None,
        direct_current=summary.get("temperature_c_max") if isinstance(summary.get("temperature_c_max"), (int, float)) else None,
        source="cooling_thermal_audit",
    )
    hwmon_max = summary.get("hwmon_temperature_c_max")
    zone_max = summary.get("thermal_zone_temperature_c_max")
    package_max = summary.get("package_temperature_c_max")
    deltas: dict[str, Any] = {
        "thermal_zone_minus_hwmon_c": round(float(zone_max) - float(hwmon_max), 1)
        if isinstance(zone_max, (int, float)) and isinstance(hwmon_max, (int, float)) else None,
        "package_minus_hwmon_max_c": round(float(package_max) - float(hwmon_max), 1)
        if isinstance(package_max, (int, float)) and isinstance(hwmon_max, (int, float)) else None,
    }
    findings: list[dict[str, Any]] = []
    class_value = str(summary.get("class") or "unknown")
    hotspot = summary.get("cpu_hotspot", {}) if isinstance(summary.get("cpu_hotspot"), dict) else {}
    if class_value in {"hot", "critical"}:
        findings.append({
            "severity": "warn",
            "code": "thermal_policy_hot",
            "message": "Current conservative thermal class is hot/critical; avoid adding synthetic load during validation.",
        })
    if hotspot.get("distribution") in {"localized_hot_core_hotspot", "localized_critical_core_hotspot"}:
        findings.append({
            "severity": "info",
            "code": "localized_core_hotspot",
            "message": "Per-core evidence shows a localized hot core; route new CPU work away from listed cores instead of globally blocking operator-controlled work.",
            "distribution": hotspot.get("distribution"),
            "hottest_core": hotspot.get("hottest_core"),
            "hot_core_count": hotspot.get("hot_core_count"),
            "critical_core_count": hotspot.get("critical_core_count"),
            "core_temperature_spread_c": hotspot.get("core_temperature_spread_c"),
        })
    if isinstance(deltas.get("thermal_zone_minus_hwmon_c"), (int, float)) and abs(float(deltas["thermal_zone_minus_hwmon_c"])) >= 10.0:
        findings.append({
            "severity": "info",
            "code": "thermal_zone_hwmon_spread",
            "message": "Firmware thermal zones and hwmon CPU/component readings differ materially; keep both as separate evidence classes.",
            "delta_c": deltas["thermal_zone_minus_hwmon_c"],
        })
    findings.append({
        "severity": "ok",
        "code": "trusted_sources_defined",
        "message": "Use coretemp for CPU execution evidence, firmware thermal zones for conservative policy, and component hwmon for NVMe/Wi-Fi support evidence.",
    })

    data = {
        "schema": f"{SCHEMA_PREFIX}_cooling_thermal_audit_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "duration_seconds": max(0.0, min(float(seconds), 120.0)),
        "interval_seconds": max(0.5, min(float(interval), 10.0)),
        "summary": {
            "latest": summary,
            "series": series,
            "episode": episode,
            "deltas": deltas,
            "findings": findings,
        },
        "trusted_sensor_map": latest.get("trusted_sensor_map", {}),
        "samples": samples,
        "paths": cooling_paths(),
        "policy": {
            "temperature_decision": "Conservative policy uses max(hwmon temps, thermal zones); workload routing should inspect per-core/coretemp evidence before restricting all CPU work.",
            "hotspot_distribution": "A single hot core is a routing signal, not proof that every CPU should be disabled. Fan/power safety still follows conservative max and firmware zones.",
            "display_note": "A desktop widget may show a lower single CPU number than abyss-machine because abyss-machine keeps firmware zones and hottest core/package evidence separate.",
        },
    }
    if write_latest:
        latest_error = safe_atomic_write_json(COOLING_THERMAL_AUDIT_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(COOLING_THERMAL_AUDIT_ROOT), data, 0o664)
        errors = [error for error in (latest_error, daily_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


