def cooling_recent_emergency(seconds: float, origin_min_temperature_c: float = 86.0) -> dict[str, Any]:
    data: dict[str, Any] = {
        "active": False,
        "seconds": seconds,
        "elapsed_seconds": None,
        "generated_at": None,
        "path": str(ai_daily_jsonl_path(COOLING_ACTION_ROOT)),
        "origin_filter": "thermal_trigger_or_hold_only",
        "origin_min_temperature_c": origin_min_temperature_c,
        "ignored_self_extension_records": 0,
    }
    if seconds <= 0:
        return data
    path = ai_daily_jsonl_path(COOLING_ACTION_ROOT)
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError as exc:
        data["error"] = str(exc)
        return data
    now = dt.datetime.now(dt.timezone.utc).astimezone()
    for line in reversed(lines[-500:]):
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue
        if not isinstance(record, dict) or record.get("applied_profile") != "emergency":
            continue
        reasons = nested_get(record, ["recommendation", "reasons"]) or []
        if not isinstance(reasons, list):
            reasons = []
        reason_texts = [str(reason) for reason in reasons]
        status_before_temp = nested_get(record, ["status_before", "temperature"]) or {}
        before_class = str(status_before_temp.get("class") or "")
        before_max = status_before_temp.get("temperature_c_max")
        try:
            before_max_float = float(before_max)
        except (TypeError, ValueError):
            before_max_float = None
        thermal_origin = (
            any(reason.startswith("temperature_c_max>=") for reason in reason_texts)
            or any(reason.startswith("hold_emergency_until_below_") for reason in reason_texts)
            or before_class in {"hot", "critical"}
            or (before_max_float is not None and before_max_float >= origin_min_temperature_c)
        )
        if not thermal_origin:
            data["ignored_self_extension_records"] = int(data.get("ignored_self_extension_records") or 0) + 1
            continue
        generated_at = str(record.get("generated_at") or "")
        try:
            timestamp = dt.datetime.fromisoformat(generated_at)
        except ValueError:
            continue
        if timestamp.tzinfo is None:
            timestamp = timestamp.replace(tzinfo=now.tzinfo)
        elapsed = max(0.0, (now - timestamp).total_seconds())
        data.update({
            "active": elapsed < seconds,
            "elapsed_seconds": round(elapsed, 1),
            "generated_at": generated_at,
            "origin_reasons": reason_texts[:8],
            "origin_temperature_class": before_class,
            "origin_temperature_c_max": before_max_float,
        })
        return data
    return data


def cooling_recommend(write_latest: bool = False, status_data: dict[str, Any] | None = None) -> dict[str, Any]:
    status_data = status_data if isinstance(status_data, dict) else cooling_status(write_latest=write_latest)
    config = cooling_config()
    auto = config.get("auto", {}) if isinstance(config.get("auto"), dict) else {}
    temp = nested_get(status_data, ["temperature", "summary", "temperature_c_max"])
    selected_mode = cooling_contracts.selected_mode_for_recommendation(
        selected_mode=str(load_mode_state().get("selected_mode", "balanced")),
        power_profile_name=power_profile(),
        ac_online=bool(battery_summary().get("ac_online")),
    )
    recent_emergency: dict[str, Any] = {}
    if isinstance(temp, (int, float)):
        hold = float(auto.get("hold_emergency_above_c", 100.0))
        min_hold_seconds = float(auto.get("min_emergency_hold_seconds", 0.0))
        recent_emergency = cooling_recent_emergency(min_hold_seconds, origin_min_temperature_c=hold)
    return cooling_contracts.recommendation_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        status_data=status_data,
        config=config,
        selected_mode=selected_mode,
        recent_emergency=recent_emergency,
        config_path=str(COOLING_CONFIG_PATH),
    )


def cooling_profile_targets(profile: str, status_data: dict[str, Any] | None = None) -> tuple[str, dict[str, Any], dict[str, Any] | None]:
    normalized = str(profile or "auto").strip().lower()
    if normalized not in VALID_COOLING_PROFILES:
        normalized = "auto"
    recommendation = cooling_recommend(write_latest=False, status_data=status_data) if normalized == "auto" else None
    config = cooling_config()
    normalized, target = cooling_contracts.profile_targets(
        profile=normalized,
        config=config,
        recommendation=recommendation,
    )
    return normalized, target, recommendation


