def pci_devices() -> list[str]:
    if not command_exists("lspci"):
        return []
    out = run(["lspci", "-D"], timeout=3.0)
    if not out["ok"]:
        return []
    interesting = []
    needles = ("vga", "3d", "display", "npu", "neural", "processing accelerators")
    for line in out["stdout"].splitlines():
        if any(needle in line.lower() for needle in needles):
            interesting.append(line)
    return interesting


def ai_devices() -> dict[str, Any]:
    dri = sorted(str(p) for p in Path("/dev/dri").glob("*")) if Path("/dev/dri").exists() else []
    accel = sorted(str(p) for p in Path("/dev/accel").glob("*")) if Path("/dev/accel").exists() else []
    return {
        "dev_dri_present": bool(dri),
        "dev_dri_nodes": dri,
        "dev_accel_present": bool(accel),
        "dev_accel_nodes": accel,
        "pci": pci_devices(),
        "openvino_python": shutil.which("abyss-openvino-python"),
        "openvino_benchmark": shutil.which("abyss-openvino-benchmark"),
        "openvino_venv": str(ABYSS_AI_HOME / "openvino-2026.2"),
        "openvino_venv_exists": (ABYSS_AI_HOME / "openvino-2026.2").exists(),
    }


def parse_json_stdout(stdout: str) -> dict[str, Any] | None:
    stdout = stdout.strip()
    if not stdout:
        return None
    try:
        data = json.loads(stdout)
    except json.JSONDecodeError:
        for line in reversed(stdout.splitlines()):
            line = line.strip()
            if not line.startswith("{"):
                continue
            try:
                data = json.loads(line)
            except json.JSONDecodeError:
                continue
            return data if isinstance(data, dict) else None
        marker = stdout.rfind("\n{")
        if marker < 0:
            return None
        try:
            data = json.loads(stdout[marker + 1 :])
        except json.JSONDecodeError:
            return None
    return data if isinstance(data, dict) else None


def parse_json_object_argument(raw: str, *, argument_name: str) -> dict[str, Any] | None:
    text = str(raw or "").strip()
    if not text:
        return None
    if text.startswith("@"):
        text = Path(text[1:]).read_text(encoding="utf-8")
    data = json.loads(text)
    if not isinstance(data, dict):
        raise ValueError(f"{argument_name} must decode to a JSON object")
    return data


