def proc_meminfo_summary() -> dict[str, Any]:
    fields = {
        "MemTotal": "mem_total_mib",
        "MemAvailable": "mem_available_mib",
        "MemFree": "mem_free_mib",
        "SwapTotal": "swap_total_mib",
        "SwapFree": "swap_free_mib",
    }
    data: dict[str, Any] = {"available": Path("/proc/meminfo").exists()}
    if not data["available"]:
        return data
    try:
        for line in Path("/proc/meminfo").read_text(encoding="utf-8", errors="replace").splitlines():
            key, _, rest = line.partition(":")
            if key not in fields:
                continue
            parts = rest.strip().split()
            if not parts:
                continue
            value_kib = int(parts[0])
            data[fields[key]] = round(value_kib / 1024.0, 1)
    except (OSError, ValueError) as exc:
        data["error"] = str(exc)
    return data


