def memory_residency_hotpath_evidence(max_age_sec: float = 3600.0) -> dict[str, Any]:
    data, error = load_json_document(MEMORY_HOTPATH_LATEST_PATH)
    evidence: dict[str, Any] = {
        "available": False,
        "fresh": False,
        "path": str(MEMORY_HOTPATH_LATEST_PATH),
        "error": error,
    }
    if not isinstance(data, dict):
        return evidence

    generated_at = data.get("generated_at")
    age_sec: float | None = None
    if generated_at:
        try:
            generated = dt.datetime.fromisoformat(str(generated_at))
            if generated.tzinfo is None:
                generated = generated.replace(tzinfo=dt.datetime.now().astimezone().tzinfo)
            age_sec = (dt.datetime.now(dt.timezone.utc).astimezone() - generated).total_seconds()
        except ValueError:
            age_sec = None

    summary = data.get("summary", {}) if isinstance(data.get("summary"), dict) else {}
    issues = summary.get("issues") if isinstance(summary.get("issues"), list) else []
    findings = summary.get("findings") if isinstance(summary.get("findings"), list) else []
    fresh = bool(age_sec is not None and age_sec <= max_age_sec)
    if not data.get("ok"):
        measurement_status = "latest_failed"
    elif not fresh:
        measurement_status = "stale"
    elif summary.get("status") == "ok":
        measurement_status = "fresh_ok"
    elif issues:
        measurement_status = "fresh_watch"
    else:
        measurement_status = "fresh_unknown"

    return {
        "available": True,
        "fresh": fresh,
        "path": str(MEMORY_HOTPATH_LATEST_PATH),
        "generated_at": generated_at,
        "age_sec": round(age_sec, 1) if age_sec is not None else None,
        "max_age_sec": float(max_age_sec),
        "ok": bool(data.get("ok")),
        "status": data.get("status"),
        "measurement_status": measurement_status,
        "issues": issues,
        "findings": findings,
        "summary": {
            "first_tts_wall_sec": summary.get("first_tts_wall_sec"),
            "last_tts_wall_sec": summary.get("last_tts_wall_sec"),
            "command_stt_client_sec": summary.get("command_stt_client_sec"),
            "quality_stt_client_sec": summary.get("quality_stt_client_sec"),
            "swap_used_percent_before": summary.get("swap_used_percent_before"),
            "swap_used_percent_after": summary.get("swap_used_percent_after"),
        },
    }


def memory_residency_hotpath_action(hotpath: dict[str, Any]) -> dict[str, Any]:
    status = str(hotpath.get("measurement_status") or "missing_required_before_persistent_cgroup_policy")
    if status == "fresh_ok":
        action_status = "fresh_ok"
        rule = "Fresh canonical hot-path probe exists; use it as the current latency baseline before any persistent cgroup decision."
    elif status == "fresh_watch":
        action_status = "fresh_watch_requires_latency_followup"
        rule = "Fresh canonical hot-path probe exists but has watch issues; do not promote persistent cgroup policy until the latency issue is understood."
    elif status == "stale":
        action_status = "stale_remeasure_before_persistent_cgroup_policy"
        rule = "Latest hot-path probe is stale for residency decisions; rerun it before persistent cgroup policy."
    elif status == "latest_failed":
        action_status = "failed_remeasure_before_persistent_cgroup_policy"
        rule = "Latest hot-path probe failed; fix or rerun it before persistent cgroup policy."
    else:
        action_status = "missing_required_before_persistent_cgroup_policy"
        rule = "No canonical hot-path probe evidence is available; run it before persistent cgroup policy."
    return {
        "id": "measure_hot_path_latency",
        "status": action_status,
        "command": "abyss-machine memory hotpath-probe --json",
        "legacy_manual_commands": [
            "abyss-machine ai tts server status --json",
            "abyss-machine ai tts synth --profile quality-compact --text 'Проверка горячего пути синтеза.' --json",
            "abyss-machine dictation validate --json",
        ],
        "evidence": hotpath,
        "rule": rule,
    }


def memory_hotpath_probe_route(hotpath: dict[str, Any]) -> dict[str, Any]:
    hotpath = hotpath if isinstance(hotpath, dict) else {}
    measurement_status = str(hotpath.get("measurement_status") or "missing_required_before_persistent_cgroup_policy")
    summary = hotpath.get("summary") if isinstance(hotpath.get("summary"), dict) else {}
    issues = [str(item) for item in (hotpath.get("issues") if isinstance(hotpath.get("issues"), list) else []) if item]
    findings = [str(item) for item in (hotpath.get("findings") if isinstance(hotpath.get("findings"), list) else []) if item]
    safe_next = {
        "kind": "memory_hotpath_measurement_review",
        "owner_route": "abyss-machine:memory",
        "review_command": "abyss-machine memory residency --json",
        "remeasure_command": "abyss-machine memory hotpath-probe --json",
        "post_verifiers": [
            "abyss-machine memory residency --json",
            "abyss-machine memory validate --json",
            "abyss-machine reactions validate --json",
            "abyss-machine responses validate --json",
        ],
        "condition": "repeat measurement or inspect latency only under operator review; do not apply persistent cgroup policy from a stale/failed/watch hot-path probe",
        "requires_operator": True,
        "requires_human_approval": True,
        "automatic": False,
        "executes_commands": False,
        "host_layer_mutates_stack": False,
        "action_execution": False,
        "does_not_apply_cgroup_properties": True,
        "does_not_restart_services": True,
    }
    route = {
        "schema": f"{SCHEMA_PREFIX}_memory_hotpath_probe_route_v1",
        "route_id": "memhotpath-" + stable_hash_json({
            "generated_at": hotpath.get("generated_at"),
            "measurement_status": measurement_status,
            "issues": issues,
            "summary": summary,
        }, length=24),
        "measurement_status": measurement_status,
        "status": hotpath.get("status"),
        "available": hotpath.get("available") is True,
        "fresh": hotpath.get("fresh") is True,
        "generated_at": hotpath.get("generated_at"),
        "age_sec": hotpath.get("age_sec"),
        "max_age_sec": hotpath.get("max_age_sec"),
        "ok": hotpath.get("ok") is True,
        "issues": issues,
        "findings": findings,
        "latency": {
            "first_tts_wall_sec": summary.get("first_tts_wall_sec"),
            "last_tts_wall_sec": summary.get("last_tts_wall_sec"),
            "command_stt_client_sec": summary.get("command_stt_client_sec"),
            "quality_stt_client_sec": summary.get("quality_stt_client_sec"),
        },
        "swap": {
            "used_percent_before": summary.get("swap_used_percent_before"),
            "used_percent_after": summary.get("swap_used_percent_after"),
        },
        "safe_next_action": safe_next,
        "evidence_refs": [
            {"path": str(MEMORY_HOTPATH_LATEST_PATH), "generated_at": hotpath.get("generated_at")},
            {"path": str(MEMORY_RESIDENCY_LATEST_PATH), "section": "summary.hotpath_probe"},
            {"path": str(MEMORY_PRESSURE_LATEST_PATH), "section": "swap/psi"},
            {"path": str(AI_TTS_LATEST_PATH), "section": "latest_tts_probe"},
        ],
        "policy": {
            "read_model": True,
            "measurement_only": True,
            "automatic_execution": False,
            "executes_commands": False,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "does_not_apply_cgroup_properties": True,
            "does_not_stop_disable_restart_or_throttle_services": True,
            "raw_audio_stored": False,
            "raw_private_content": False,
        },
    }
    route["complete"] = memory_hotpath_probe_route_complete(route)
    return route


def memory_hotpath_probe_route_complete(route: Any) -> bool:
    if not isinstance(route, dict):
        return False
    safe_next = route.get("safe_next_action") if isinstance(route.get("safe_next_action"), dict) else {}
    policy = route.get("policy") if isinstance(route.get("policy"), dict) else {}
    return (
        route.get("schema") == f"{SCHEMA_PREFIX}_memory_hotpath_probe_route_v1"
        and bool(route.get("route_id"))
        and bool(route.get("measurement_status"))
        and bool(route.get("evidence_refs"))
        and isinstance(route.get("latency"), dict)
        and isinstance(route.get("swap"), dict)
        and safe_next.get("requires_operator") is True
        and safe_next.get("requires_human_approval") is True
        and safe_next.get("automatic") is False
        and safe_next.get("executes_commands") is False
        and safe_next.get("host_layer_mutates_stack") is False
        and safe_next.get("does_not_apply_cgroup_properties") is True
        and safe_next.get("does_not_restart_services") is True
        and bool(safe_next.get("remeasure_command"))
        and policy.get("measurement_only") is True
        and policy.get("automatic_execution") is False
        and policy.get("executes_commands") is False
        and policy.get("host_layer_mutates_stack") is False
        and policy.get("does_not_apply_cgroup_properties") is True
        and policy.get("does_not_stop_disable_restart_or_throttle_services") is True
        and policy.get("raw_audio_stored") is False
        and policy.get("raw_private_content") is False
    )


def memory_residency(top: int = 40, write_latest: bool = True) -> dict[str, Any]:
    policy = memory_policy_document()
    residency_policy = policy.get("residency", {}) if isinstance(policy.get("residency"), dict) else memory_default_residency_policy()
    pressure = memory_pressure(top=top, write_latest=True)
    status = pressure.get("status", {}) if isinstance(pressure.get("status"), dict) else {}
    zram_summary = nested_get(status, ["zram", "summary"]) or {}
    swap_summary = nested_get(status, ["swap", "summary"]) or {}
    psi_some = memory_float(nested_get(status, ["psi", "some", "avg10"]), 0.0) or 0.0
    psi_full = memory_float(nested_get(status, ["psi", "full", "avg10"]), 0.0) or 0.0
    thresholds = residency_policy.get("thresholds", {}) if isinstance(residency_policy.get("thresholds"), dict) else {}

    services = [memory_residency_service_status(item, residency_policy) for item in memory_residency_services(policy)]
    service_issue_count = sum(len(item.get("issues") or []) for item in services)
    runtime_pilot_active_units = [
        item.get("unit")
        for item in services
        if nested_get(item, ["target", "runtime_pilot_active"]) is True
    ]
    runtime_pilot_missing_units = [
        item.get("unit")
        for item in services
        if item.get("protected")
        and item.get("systemd", {}).get("active_state") == "active"
        and nested_get(item, ["target", "runtime_pilot_active"]) is not True
    ]
    protected_high_swap = [
        item.get("unit")
        for item in services
        if any(isinstance(issue, dict) and issue.get("code") == "high_cgroup_swap" for issue in item.get("issues", []))
    ]
    zram_ratio = memory_float(zram_summary.get("logical_to_memory_ratio"), None)
    zram_free_mib = None
    if zram_summary.get("disk_mib") is not None and zram_summary.get("data_mib") is not None:
        zram_free_mib = round(max(0.0, float(zram_summary.get("disk_mib") or 0.0) - float(zram_summary.get("data_mib") or 0.0)), 1)
    hotpath_evidence = memory_residency_hotpath_evidence()

    environment_issues: list[dict[str, Any]] = []
    if zram_ratio is not None and zram_ratio < float(thresholds.get("zram_ratio_warn_below", 1.5)):
        environment_issues.append(
            {
                "level": "warn",
                "code": "low_zram_compression_ratio",
                "message": "zram logical-to-resident ratio is low; more zram capacity will cost more real RAM/CPU",
                "threshold": thresholds.get("zram_ratio_warn_below", 1.5),
            }
        )
    if zram_free_mib is not None and zram_free_mib < float(thresholds.get("zram_free_warn_below_mib", 2048)):
        environment_issues.append(
            {
                "level": "warn",
                "code": "low_zram_free_headroom",
                "message": "zram logical free headroom is below policy target",
                "threshold_mib": thresholds.get("zram_free_warn_below_mib", 2048),
            }
        )
    if psi_some > float(thresholds.get("psi_some_warn_above", 2.0)) or psi_full > float(thresholds.get("psi_full_warn_above", 0.5)):
        environment_issues.append(
            {
                "level": "warn",
                "code": "active_memory_stalls",
                "message": "memory PSI indicates active stalls; do not start residency mutation under this pressure",
            }
        )

    runtime_candidates = [
        {
            "unit": item.get("unit"),
            "scope": item.get("scope"),
            "class": item.get("class"),
            "target_slice": nested_get(item, ["target", "slice"]),
            "runtime_pilot": nested_get(item, ["target", "runtime_pilot"]),
            "status": nested_get(item, ["target", "runtime_pilot_status"]),
        }
        for item in services
        if item.get("protected") and item.get("systemd", {}).get("active_state") == "active"
    ]
    if environment_issues:
        residency_status = "environment_guarded"
    elif runtime_pilot_missing_units:
        residency_status = "needs_residency_pilot"
    elif service_issue_count:
        residency_status = "runtime_pilot_active_needs_warmup"
    else:
        residency_status = "observed_clean"

    data = {
        "schema": f"{SCHEMA_PREFIX}_memory_residency_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "status": residency_status,
        "summary": {
            "services": len(services),
            "service_issues": service_issue_count,
            "environment_issues": len(environment_issues),
            "runtime_pilot_active_units": runtime_pilot_active_units,
            "runtime_pilot_missing_units": runtime_pilot_missing_units,
            "protected_high_swap_units": protected_high_swap,
            "memory_class": pressure.get("class"),
            "zram_disk_mib": zram_summary.get("disk_mib"),
            "zram_data_mib": zram_summary.get("data_mib"),
            "zram_resident_mib": zram_summary.get("total_memory_mib"),
            "zram_logical_free_mib": zram_free_mib,
            "zram_logical_to_memory_ratio": zram_ratio,
            "swap_used_percent": swap_summary.get("used_percent"),
            "psi_some_avg10": psi_some,
            "psi_full_avg10": psi_full,
            "hotpath_probe_status": hotpath_evidence.get("measurement_status"),
            "hotpath_probe_generated_at": hotpath_evidence.get("generated_at"),
            "hotpath_probe_age_sec": hotpath_evidence.get("age_sec"),
            "hotpath_probe_issues": hotpath_evidence.get("issues"),
        },
        "policy": {
            "source": str(MEMORY_POLICY_PATH),
            "residency": residency_policy,
            "facts_only": True,
            "does_not_stop_disable_restart_or_throttle_services": True,
            "does_not_apply_cgroup_properties": True,
        },
        "services": services,
        "environment_issues": environment_issues,
        "runtime_pilot_candidates": runtime_candidates,
        "next_actions": [
            memory_residency_hotpath_action(hotpath_evidence),
            {
                "id": "runtime_memorylow_pilot",
                "status": "applied_runtime_only" if runtime_pilot_active_units and not runtime_pilot_missing_units else "candidate_after_operator_approval",
                "rule": "Apply MemoryLow/MemoryHigh runtime-only to the target slice and service, then re-run residency and latency probes.",
            },
            {
                "id": "defer_swapmax",
                "status": "active_guardrail",
                "rule": "Do not set MemorySwapMax on currently high-swap live services until restart/warmup measurement exists.",
            },
        ],
        "paths": {
            "latest": str(MEMORY_RESIDENCY_LATEST_PATH),
            "daily_glob": str(MEMORY_RESIDENCY_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "pressure_latest": str(MEMORY_PRESSURE_LATEST_PATH),
        },
        "non_claims": [
            "Residency observation is not proof of a leak.",
            "This command observes runtime pilot state; it does not apply candidates by itself.",
            "High cgroup swap on a protected service means measure/warm/protect; it is not a stop recommendation.",
        ],
    }
    if write_latest:
        latest_error = safe_atomic_write_json(MEMORY_RESIDENCY_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(MEMORY_RESIDENCY_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(MEMORY_INDEX_PATH, memory_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


