def memory_status(write_latest: bool = True) -> dict[str, Any]:
    mem = memory_meminfo_details()
    psi = memory_parse_pressure_file(Path("/proc/pressure/memory"))
    swap = memory_swap_status()
    zram = memory_zram_status()
    zswap = memory_zswap_status()
    cgroups = memory_cgroup_status()
    policy = memory_policy_document()
    pressure_class, reasons = memory_pressure_class(mem, psi, swap, policy)
    data = {
        "schema": f"{SCHEMA_PREFIX}_memory_status_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "class": pressure_class,
        "reasons": reasons,
        "meminfo": mem,
        "psi": psi,
        "swap": swap,
        "zram": zram,
        "zswap": zswap,
        "vmstat": memory_vmstat_snapshot(),
        "sysctl": memory_sysctl_snapshot(),
        "cgroups": cgroups,
        "oomd": {
            "system": systemd_unit("systemd-oomd.service"),
            "socket": systemd_unit("systemd-oomd.socket"),
            "policy": "observe_only_until_memory_policy_explicitly_promotes_oomd",
        },
        "policy": {
            "config": str(MEMORY_POLICY_PATH),
            "config_exists": policy.get("config_exists"),
            "automatic_kill": False,
            "automatic_tuning": False,
        },
        "paths": memory_paths(),
    }
    if write_latest:
        latest_error = safe_atomic_write_json(MEMORY_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(MEMORY_STATUS_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(MEMORY_INDEX_PATH, memory_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def memory_pressure(top: int = 30, write_latest: bool = True) -> dict[str, Any]:
    status_data = memory_status(write_latest=True)
    processes = memory_process_snapshot(top=top, smaps=True, write_latest=True)
    mem_summary = nested_get(status_data, ["meminfo", "summary"]) or {}
    zram_summary = nested_get(status_data, ["zram", "summary"]) or {}
    process_summary = processes.get("summary", {}) if isinstance(processes.get("summary"), dict) else {}
    data = {
        "schema": f"{SCHEMA_PREFIX}_memory_pressure_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(status_data.get("ok")) and bool(processes.get("ok")),
        "class": status_data.get("class"),
        "reasons": status_data.get("reasons"),
        "summary": {
            "class": status_data.get("class"),
            "mem_available_mib": mem_summary.get("mem_available_mib"),
            "mem_available_percent": mem_summary.get("mem_available_percent"),
            "swap_used_mib": mem_summary.get("swap_used_mib"),
            "swap_used_percent": mem_summary.get("swap_used_percent"),
            "psi_some_avg10": nested_get(status_data, ["psi", "some", "avg10"]),
            "psi_full_avg10": nested_get(status_data, ["psi", "full", "avg10"]),
            "zram_data_mib": zram_summary.get("data_mib"),
            "zram_resident_mib": zram_summary.get("total_memory_mib"),
            "zram_logical_to_memory_ratio": zram_summary.get("logical_to_memory_ratio"),
            "top_pss_total_mib": kib_to_mib(process_summary.get("top_pss_total_kib")),
            "top_cgroup_memory_total_mib": kib_to_mib(process_summary.get("top_cgroup_memory_total_kib")),
            "top_swap_total_mib": kib_to_mib(process_summary.get("top_swap_total_kib")),
            "top_cgroup_swap_total_mib": kib_to_mib(process_summary.get("top_cgroup_swap_total_kib")),
            "cgroup_memory_read": process_summary.get("cgroup_memory_read"),
            "cgroup_swap_read": process_summary.get("cgroup_swap_read"),
            "processes": process_summary.get("processes"),
        },
        "status": {
            "latest": str(MEMORY_LATEST_PATH),
            "class": status_data.get("class"),
            "meminfo": status_data.get("meminfo"),
            "psi": status_data.get("psi"),
            "swap": status_data.get("swap"),
            "zram": status_data.get("zram"),
            "zswap": status_data.get("zswap"),
            "oomd": status_data.get("oomd"),
        },
        "processes": {
            "latest": str(MEMORY_PROCESS_LATEST_PATH),
            "summary": process_summary,
            "top": processes.get("top"),
        },
        "paths": memory_paths(),
        "policy": {
            "facts_only": True,
            "do_not_kill_or_tune_from_this_result": True,
            "launchers_should_consume_memory_plan": True,
        },
        "non_claims": [
            "MemAvailable and PSI are pressure signals, not proof of a leak.",
            "RSS overcounts shared memory; PSS is preferred where smaps_rollup was readable.",
            "OOM counters are cumulative unless a caller compares snapshots over time.",
            "High zram swap with healthy MemAvailable and near-zero PSI is a launch-risk signal, not a standalone OOM claim.",
        ],
    }
    if write_latest:
        latest_error = safe_atomic_write_json(MEMORY_PRESSURE_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(MEMORY_PRESSURE_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(MEMORY_INDEX_PATH, memory_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


