def memory_orchestrate_action_candidates(
    cgroup_memory_top: list[dict[str, Any]],
    cgroup_swap_top: list[dict[str, Any]],
    limit: int = 12,
) -> list[dict[str, Any]]:
    return memory_adapters.orchestrate_action_candidates(
        cgroup_memory_top,
        cgroup_swap_top,
        protected_roles=PROTECTED_CAPABILITY_ROLES,
        limit=limit,
    )


def memory_orchestrate_plan(top: int = 40, write_latest: bool = True) -> dict[str, Any]:
    top = max(10, min(int(top), 120))
    pressure = memory_pressure(top=top, write_latest=True)
    residency = memory_residency(top=top, write_latest=True)
    policy = memory_policy_document()
    status = pressure.get("status", {}) if isinstance(pressure.get("status"), dict) else {}
    mem_summary = nested_get(status, ["meminfo", "summary"]) or {}
    mem_raw = nested_get(status, ["meminfo", "raw_kib"]) or {}
    zram_summary = nested_get(status, ["zram", "summary"]) or {}
    process_summary = nested_get(pressure, ["processes", "summary"]) or {}
    process_top = nested_get(pressure, ["processes", "top"]) or {}
    cgroup_memory_top = process_top.get("cgroup_memory") if isinstance(process_top.get("cgroup_memory"), list) else []
    cgroup_swap_top = process_top.get("cgroup_swap") if isinstance(process_top.get("cgroup_swap"), list) else []

    mem_total_mib = memory_float(mem_summary.get("mem_total_mib"), 0.0) or 0.0
    mem_available_mib = memory_float(mem_summary.get("mem_available_mib"), 0.0) or 0.0
    unavailable_mib = round(max(0.0, mem_total_mib - mem_available_mib), 1)
    cached_mib = kib_to_mib(int(mem_raw.get("Cached") or 0))
    buffers_mib = kib_to_mib(int(mem_raw.get("Buffers") or 0))
    sreclaimable_mib = memory_float(mem_summary.get("sreclaimable_mib"), 0.0) or 0.0
    shmem_mib = memory_float(mem_summary.get("shmem_mib"), 0.0) or 0.0
    file_cache_reclaimable_estimate = round(max(0.0, float(cached_mib or 0.0) + float(buffers_mib or 0.0) + sreclaimable_mib - shmem_mib), 1)
    zram_resident_mib = memory_float(zram_summary.get("total_memory_mib"), 0.0) or 0.0
    top_cgroup_memory_mib = memory_float(kib_to_mib(process_summary.get("top_cgroup_memory_total_kib")), 0.0) or 0.0
    top_cgroup_swap_mib = memory_float(kib_to_mib(process_summary.get("top_cgroup_swap_total_kib")), 0.0) or 0.0

    psi_some = memory_float(nested_get(status, ["psi", "some", "avg10"]), 0.0) or 0.0
    psi_full = memory_float(nested_get(status, ["psi", "full", "avg10"]), 0.0) or 0.0
    active_stalls = psi_some > 2.0 or psi_full > 0.5
    candidates = memory_orchestrate_action_candidates(cgroup_memory_top, cgroup_swap_top, limit=top)
    protected_candidates = [item for item in candidates if bool(nested_get(item, ["target", "protected"]))]

    services = []
    for item in residency.get("services", []) if isinstance(residency.get("services"), list) else []:
        issues = [issue.get("code") for issue in item.get("issues", []) if isinstance(issue, dict)]
        services.append(
            {
                "unit": item.get("unit"),
                "class": item.get("class"),
                "active_state": nested_get(item, ["systemd", "active_state"]),
                "memory_current_mib": nested_get(item, ["controls", "memory_current", "mib"]),
                "memory_swap_mib": nested_get(item, ["controls", "memory_swap_current", "mib"]),
                "sampled_process_pss_mib": nested_get(item, ["derived", "sampled_process_pss_mib"]),
                "issues": issues,
                "protected": item.get("protected", True),
            }
        )

    if active_stalls:
        decision = "block_new_pressure_and_investigate_active_stalls"
    elif protected_candidates:
        decision = "plan_operator_confirmed_dehydrate_rehydrate_candidates"
    elif str(pressure.get("class") or "") in {"warm", "hot", "critical"}:
        decision = "gate_new_work_and_keep_observing"
    else:
        decision = "observe_only"

    next_actions = [
        {
            "id": "keep_resource_gate_for_new_work",
            "kind": "automation",
            "status": "active",
            "reason": "Use launch gates for semantic-build/indexing and other new medium/heavy work instead of mutating live capabilities.",
            "command": "abyss-machine resource launch --class medium --kind indexing --unattended --success-on-block --json -- COMMAND...",
            "mutates_existing_processes": False,
        },
        {
            "id": "review_dehydrate_candidates",
            "kind": "operator_review",
            "status": "candidate" if candidates else "not_needed",
            "reason": "Managed dehydrate/rehydrate has dry-run, confirm-preflight, and podman-managed live routes; this command ranks candidates without mutating them.",
            "candidate_count": len(candidates),
            "mutates_existing_processes": False,
        },
        {
            "id": "verify_hotpath_before_and_after_any_restart",
            "kind": "verification",
            "status": "available",
            "reason": "Synthetic TTS/STT and resident LLM evidence should bracket any future managed restart.",
            "command": "abyss-machine memory hotpath-probe --json",
            "mutates_existing_processes": False,
        },
    ]
    if zram_resident_mib >= 8192:
        next_actions.append(
            {
                "id": "downtime_zram_policy_review",
                "kind": "policy_review",
                "status": "candidate",
                "reason": "zram resident pool is a large physical RAM component; review sizing/compression during downtime, not as live relief.",
                "mutates_existing_processes": False,
            }
        )

    data = {
        "schema": f"{SCHEMA_PREFIX}_memory_orchestrate_plan_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(pressure.get("ok", True)) and bool(residency.get("ok", True)),
        "status": "plan_only",
        "decision": decision,
        "class": pressure.get("class"),
        "reasons": pressure.get("reasons"),
        "summary": {
            "ram_unavailable_mib": unavailable_mib,
            "mem_available_mib": round(mem_available_mib, 1),
            "mem_available_percent": mem_summary.get("mem_available_percent"),
            "zram_resident_mib": round(zram_resident_mib, 1),
            "top_cgroup_memory_total_mib": round(top_cgroup_memory_mib, 1),
            "top_cgroup_swap_total_mib": round(top_cgroup_swap_mib, 1),
            "psi_some_avg10": psi_some,
            "psi_full_avg10": psi_full,
            "candidate_count": len(candidates),
            "protected_candidate_count": len(protected_candidates),
        },
        "ram_attribution": {
            "method": "MemTotal-MemAvailable plus non-additive physical RAM components and cgroup memory.current",
            "not_additive": True,
            "components": [
                {
                    "id": "ram_unavailable",
                    "mib": unavailable_mib,
                    "meaning": "MemTotal minus MemAvailable; close to what desktop tools call used RAM.",
                },
                {
                    "id": "top_cgroup_memory_current",
                    "mib": round(top_cgroup_memory_mib, 1),
                    "meaning": "Sum of top cgroup memory.current entries captured for direct RAM attribution.",
                },
                {
                    "id": "top_process_pss",
                    "mib": pressure.get("summary", {}).get("top_pss_total_mib") if isinstance(pressure.get("summary"), dict) else None,
                    "meaning": "PSS for sampled top processes; avoids most shared-memory double counting but is not complete system RAM.",
                },
                {
                    "id": "zram_pool_resident",
                    "mib": round(zram_resident_mib, 1),
                    "counts_in_ram_used": True,
                    "meaning": "Compressed swap pool resident in physical RAM; separate from logical swap used.",
                },
                {
                    "id": "shmem",
                    "mib": round(shmem_mib, 1),
                    "meaning": "tmpfs/shared memory from meminfo; may overlap with cache-facing views.",
                },
                {
                    "id": "slab_unreclaimable",
                    "mib": mem_summary.get("sunreclaim_mib"),
                    "meaning": "Kernel slab that is not readily reclaimable.",
                },
                {
                    "id": "file_cache_reclaimable_estimate",
                    "mib": file_cache_reclaimable_estimate,
                    "meaning": "Approximate Cached+Buffers+SReclaimable-Shmem; available memory already accounts for reclaimability.",
                },
            ],
            "top_cgroup_memory": [memory_orchestrate_cgroup_entry(item) for item in cgroup_memory_top[: min(top, 20)]],
            "top_cgroup_swap": [memory_orchestrate_cgroup_entry(item) for item in cgroup_swap_top[: min(top, 20)]],
        },
        "protected_capabilities": {
            "residency_status": residency.get("status"),
            "services": services,
            "policy": nested_get(policy, ["residency", "safety"]),
        },
        "candidates": candidates,
        "next_actions": next_actions,
        "commands": {
            "plan": "abyss-machine memory orchestrate plan --json",
            "pressure": "abyss-machine memory pressure --json",
            "processes": "abyss-machine memory processes --json",
            "residency": "abyss-machine memory residency --json",
            "hotpath_probe": "abyss-machine memory hotpath-probe --json",
            "resource_plan_medium_indexing": "abyss-machine resource plan --class medium --kind indexing --unattended --no-thermal-sample --json",
        },
        "paths": {
            "latest": str(MEMORY_ORCHESTRATE_LATEST_PATH),
            "daily_glob": str(MEMORY_ORCHESTRATE_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "pressure_latest": str(MEMORY_PRESSURE_LATEST_PATH),
            "processes_latest": str(MEMORY_PROCESS_LATEST_PATH),
            "residency_latest": str(MEMORY_RESIDENCY_LATEST_PATH),
        },
        "policy": {
            "facts_only": True,
            "plan_command_mutates_existing_processes": False,
            "apply_supported": True,
            "apply_default_is_dry_run": True,
            "apply_confirm_preflight_supported": True,
            "live_executor_supported": True,
            "live_executor_requires_confirm_execute_live_acknowledgement_operator_reason": True,
            "live_executor_scope": "podman_managed_model_container_or_registered_rerank_api_only",
            "existing_process_mutation": False,
            "operator_confirmation_required_for_dehydrate": True,
            "do_not_tune_zram_or_sysctl_from_plan": True,
            "do_not_stop_disable_throttle_reaffinitize_or_cap_live_services": True,
        },
        "non_claims": [
            "This is not a leak verdict.",
            "zram pool is reported as physical RAM attribution, not as a replacement for direct RAM attribution.",
            "Candidates are not commands to restart services; they require an idle-aware apply route and explicit operator confirmation.",
            "Cgroup memory.current and process PSS are complementary point-in-time views and may not sum to MemTotal-MemAvailable.",
        ],
    }
    if write_latest:
        latest_error = safe_atomic_write_json(MEMORY_ORCHESTRATE_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(MEMORY_ORCHESTRATE_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(MEMORY_INDEX_PATH, memory_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


