def memory_orchestrate_is_resident_model_candidate(candidate: dict[str, Any]) -> bool:
    target = candidate.get("target", {}) if isinstance(candidate.get("target"), dict) else {}
    role = str(target.get("capability_role") or "")
    kind = str(candidate.get("kind") or "")
    label = str(target.get("label") or target.get("unit") or target.get("cgroup") or "").lower()
    names = " ".join(str(name or "") for name in target.get("names", []) if isinstance(target.get("names"), list)).lower()
    return (
        memory_orchestrate_is_rerank_api_target(target)
        or
        role == "persistent_model"
        or kind == "managed_model_dehydrate_rehydrate_candidate"
        or "llama" in label
        or "gemma" in label
        or "llama" in names
        or "gemma" in names
    )


