def memory_orchestrate_candidate_idle_probe(
    candidate: dict[str, Any],
    snapshot: dict[str, Any],
    sample_sec: float = 0.5,
) -> dict[str, Any]:
    target = candidate.get("target", {}) if isinstance(candidate.get("target"), dict) else {}
    cgroup = str(target.get("cgroup") or "")
    resident_model = memory_orchestrate_is_resident_model_candidate(candidate)
    rerank_api = memory_orchestrate_is_rerank_api_target(target)
    ovms = memory_orchestrate_is_ovms_target(target)
    cpu = memory_orchestrate_cgroup_cpu_sample(cgroup, sample_sec=sample_sec)
    endpoint = memory_orchestrate_podman_http_endpoint(snapshot)
    if rerank_api:
        http_idle = memory_orchestrate_rerank_http_idle(endpoint)
    elif ovms:
        http_idle = memory_orchestrate_ovms_http_idle(endpoint)
    elif resident_model:
        http_idle = memory_orchestrate_llama_http_idle(endpoint)
    else:
        http_idle = {"available": False, "reason": "not_resident_model_candidate"}
    http_available = bool(http_idle.get("available"))
    if (rerank_api or ovms) and cpu.get("available"):
        cpu_cores = memory_float(cpu.get("cpu_cores"), 0.0) or 0.0
        cpu_idle = cpu_cores <= 0.5
    else:
        cpu_idle = bool(cpu.get("idle")) if cpu.get("available") else None
    http_slots_idle = bool(nested_get(http_idle, ["slots", "idle"])) if http_available else None
    if http_available:
        idle = bool(http_idle.get("idle")) and (cpu_idle is not False)
        status = "idle" if idle else "busy"
        confidence = "high" if cpu.get("available") else str(http_idle.get("confidence") or "medium")
        registered = True
        if rerank_api:
            reason = "rerank-api health shows no active requests and cgroup CPU is below the idle threshold." if idle else "rerank-api active requests or cgroup CPU indicate active work."
        elif ovms:
            reason = "OVMS live/ready health and model config are available, and cgroup CPU is below the idle threshold." if idle else "OVMS health/config or cgroup CPU indicate active work."
        else:
            reason = "llama.cpp HTTP slots show no processing and cgroup CPU is below the idle threshold." if idle else "llama.cpp HTTP slots or cgroup CPU indicate active work."
    elif resident_model and cpu.get("available"):
        idle = False
        status = "unknown_low_cpu" if cpu_idle else "busy"
        confidence = "low"
        registered = False
        reason = "Only cgroup CPU is visible; no model-specific in-flight request signal is registered."
    else:
        idle = False
        status = "not_registered"
        confidence = "none"
        registered = False
        reason = "No target-specific idle detector is registered for this candidate."
    return {
        "registered": registered,
        "status": status,
        "idle": idle,
        "confidence": confidence,
        "reason": reason,
        "resident_model_candidate": resident_model,
        "signals": {
            "llama_http": http_idle if not rerank_api and not ovms else {"available": False, "reason": "non_llama_target"},
            "rerank_http": http_idle if rerank_api else {"available": False, "reason": "not_rerank_api_target"},
            "ovms_http": http_idle if ovms else {"available": False, "reason": "not_ovms_target"},
            "cgroup_cpu": cpu,
        },
        "thresholds": {
            "cgroup_cpu_cores_idle_at_or_below": 0.15,
            "llama_slots_processing_count_idle_equals": 0,
            "llama_slots_ignore_stale_n_remain_without_processing": True,
            "rerank_active_requests_idle_equals": 0,
            "rerank_cgroup_cpu_cores_idle_at_or_below": 0.5,
            "ovms_cgroup_cpu_cores_idle_at_or_below": 0.5,
        },
        "policy": {
            "read_only": True,
            "does_not_generate_tokens": True,
            "does_not_record_prompts": True,
            "does_not_stop_restart_or_throttle": True,
        },
    }


def memory_orchestrate_idle(
    candidate_id: str,
    top: int = 40,
    sample_sec: float = 0.5,
    write_latest: bool = True,
) -> dict[str, Any]:
    top = max(10, min(int(top), 120))
    sample_sec = max(0.1, min(float(sample_sec or 0.5), 3.0))
    plan = memory_orchestrate_plan(top=top, write_latest=True)
    candidate = memory_orchestrate_find_candidate(plan, candidate_id)
    if candidate is None:
        data = {
            "schema": f"{SCHEMA_PREFIX}_memory_orchestrate_idle_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "status": "rejected",
            "decision": "candidate_not_found",
            "requested": {
                "candidate_id": str(candidate_id or ""),
                "top": top,
                "sample_sec": sample_sec,
            },
            "available_candidates": [
                item.get("id")
                for item in plan.get("candidates", []) if isinstance(item, dict)
            ],
            "policy": {
                "read_only": True,
                "existing_process_mutation": False,
            },
        }
        if write_latest:
            latest_error = safe_atomic_write_json(MEMORY_ORCHESTRATE_IDLE_LATEST_PATH, data, 0o664)
            daily_error = safe_append_jsonl(ai_daily_jsonl_path(MEMORY_ORCHESTRATE_IDLE_ROOT), data, 0o664)
            index_error = safe_atomic_write_json(MEMORY_INDEX_PATH, memory_paths(), 0o664)
            errors = [error for error in (latest_error, daily_error, index_error) if error]
            if errors:
                data["write_errors"] = errors
        return data
    snapshot = memory_orchestrate_target_snapshot(candidate)
    idle_gate = memory_orchestrate_candidate_idle_probe(candidate, snapshot, sample_sec=sample_sec)
    decision = "idle_gate_passed" if idle_gate.get("idle") else "idle_gate_not_passed"
    data = {
        "schema": f"{SCHEMA_PREFIX}_memory_orchestrate_idle_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "status": idle_gate.get("status"),
        "decision": decision,
        "requested": {
            "candidate_id": str(candidate_id or ""),
            "top": top,
            "sample_sec": sample_sec,
        },
        "candidate": candidate,
        "plan_summary": plan.get("summary"),
        "target_snapshot": snapshot,
        "idle_gate": idle_gate,
        "commands": {
            "plan": "abyss-machine memory orchestrate plan --json",
            "idle": "abyss-machine memory orchestrate idle --candidate ID --json",
            "apply_dry_run": "abyss-machine memory orchestrate apply --candidate ID --dry-run --json",
        },
        "paths": {
            "latest": str(MEMORY_ORCHESTRATE_IDLE_LATEST_PATH),
            "daily_glob": str(MEMORY_ORCHESTRATE_IDLE_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "plan_latest": str(MEMORY_ORCHESTRATE_LATEST_PATH),
        },
        "policy": {
            "facts_only": True,
            "read_only": True,
            "existing_process_mutation": False,
            "does_not_generate_tokens": True,
            "does_not_record_prompts": True,
            "do_not_tune_zram_or_sysctl_from_plan": True,
            "do_not_stop_disable_throttle_reaffinitize_or_cap_live_services": True,
        },
    }
    if write_latest:
        latest_error = safe_atomic_write_json(MEMORY_ORCHESTRATE_IDLE_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(MEMORY_ORCHESTRATE_IDLE_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(MEMORY_INDEX_PATH, memory_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


