def memory_orchestrate_confirm(
    candidate_id: str,
    operator: str,
    reason: str,
    acknowledge_protected: bool = False,
    dry_run: bool = True,
    window_sec: int = 300,
    top: int = 40,
    write_latest: bool = True,
) -> dict[str, Any]:
    top = max(10, min(int(top), 120))
    plan = memory_orchestrate_plan(top=top, write_latest=True)
    candidate = memory_orchestrate_find_candidate(plan, candidate_id)
    if candidate is None:
        data = {
            "schema": f"{SCHEMA_PREFIX}_memory_orchestrate_confirm_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "status": "rejected",
            "decision": "candidate_not_found",
            "requested": {
                "candidate_id": str(candidate_id or ""),
                "operator": str(operator or "").strip() or None,
                "dry_run": bool(dry_run),
                "top": top,
            },
            "available_candidates": [
                item.get("id")
                for item in plan.get("candidates", []) if isinstance(item, dict)
            ],
            "policy": {
                "dry_run_only": True,
                "effective_confirmation": False,
                "grant_valid_for_confirm": False,
                "existing_process_mutation": False,
            },
        }
        if write_latest:
            latest_error = safe_atomic_write_json(MEMORY_ORCHESTRATE_CONFIRM_LATEST_PATH, data, 0o664)
            daily_error = safe_append_jsonl(ai_daily_jsonl_path(MEMORY_ORCHESTRATE_CONFIRM_ROOT), data, 0o664)
            index_error = safe_atomic_write_json(MEMORY_INDEX_PATH, memory_paths(), 0o664)
            errors = [error for error in (latest_error, daily_error, index_error) if error]
            if errors:
                data["write_errors"] = errors
        return data

    snapshot = memory_orchestrate_target_snapshot(candidate)
    idle_gate = memory_orchestrate_candidate_idle_probe(candidate, snapshot, sample_sec=0.5)
    health = memory_orchestrate_health_route(candidate, snapshot)
    future_executor = memory_orchestrate_future_executor(candidate, snapshot)
    checks = memory_orchestrate_confirmation_checks(candidate, idle_gate, health, operator, reason, acknowledge_protected)
    blockers = [
        item.get("id")
        for item in checks
        if isinstance(item, dict) and str(item.get("status") or "").startswith("block")
    ]
    contract = memory_orchestrate_confirmation_contract(
        candidate=candidate,
        snapshot=snapshot,
        idle_gate=idle_gate,
        health=health,
        future_executor=future_executor,
        operator=operator,
        reason=reason,
        window_sec=window_sec,
    )
    status = "contract_ready" if not blockers else "contract_incomplete"
    decision = "protected_confirmation_contract_ready" if not blockers else "protected_confirmation_contract_blocked"
    data = {
        "schema": f"{SCHEMA_PREFIX}_memory_orchestrate_confirm_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "status": status,
        "decision": decision,
        "requested": {
            "candidate_id": str(candidate_id or ""),
            "operator": str(operator or "").strip() or None,
            "reason": str(reason or "").strip() or None,
            "acknowledge_protected": bool(acknowledge_protected),
            "dry_run": bool(dry_run),
            "window_sec": max(60, min(int(window_sec or 300), 3600)),
            "top": top,
        },
        "candidate": candidate,
        "plan_summary": plan.get("summary"),
        "target_snapshot": snapshot,
        "idle_gate": idle_gate,
        "health_route": health,
        "confirmation_contract": contract,
        "checks": checks,
        "check_summary": {
            "counts": memory_orchestrate_guard_summary(checks).get("counts"),
            "blockers": blockers,
            "warnings": [item.get("id") for item in checks if isinstance(item, dict) and item.get("status") == "warn"],
        },
        "commands": {
            "plan": "abyss-machine memory orchestrate plan --json",
            "idle": "abyss-machine memory orchestrate idle --candidate ID --json",
            "confirm_dry_run": "abyss-machine memory orchestrate confirm --candidate ID --operator NAME --reason TEXT --acknowledge-protected --dry-run --json",
            "apply_dry_run": "abyss-machine memory orchestrate apply --candidate ID --dry-run --json",
            "hotpath_probe": "abyss-machine memory hotpath-probe --json",
        },
        "paths": {
            "latest": str(MEMORY_ORCHESTRATE_CONFIRM_LATEST_PATH),
            "daily_glob": str(MEMORY_ORCHESTRATE_CONFIRM_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "plan_latest": str(MEMORY_ORCHESTRATE_LATEST_PATH),
            "idle_latest": str(MEMORY_ORCHESTRATE_IDLE_LATEST_PATH),
            "apply_latest": str(MEMORY_ORCHESTRATE_APPLY_LATEST_PATH),
        },
        "policy": {
            "facts_only": True,
            "dry_run_only": True,
            "effective_confirmation": False,
            "grant_valid_for_confirm": False,
            "existing_process_mutation": False,
            "does_not_generate_tokens": True,
            "does_not_record_prompts": True,
            "do_not_tune_zram_or_sysctl_from_plan": True,
            "do_not_stop_disable_throttle_reaffinitize_or_cap_live_services": True,
        },
        "non_claims": [
            "This contract is not an effective authorization for live mutation.",
            "This command did not restart, stop, disable, throttle, re-affinitize, cap, swapoff, drop caches, tune sysctl, or reconfigure zram.",
            "A future confirmed executor must re-check idle, health, and target identity immediately before mutation.",
        ],
    }
    if write_latest:
        latest_error = safe_atomic_write_json(MEMORY_ORCHESTRATE_CONFIRM_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(MEMORY_ORCHESTRATE_CONFIRM_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(MEMORY_INDEX_PATH, memory_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


