def memory_orchestrate_confirmed_executor_preflight(
    plan: dict[str, Any],
    candidate: dict[str, Any],
    snapshot: dict[str, Any],
    idle_gate: dict[str, Any],
    health: dict[str, Any],
    confirmation_status: dict[str, Any],
    future_executor: dict[str, Any],
) -> dict[str, Any]:
    lock_status = memory_orchestrate_executor_lock_status()
    checks = memory_orchestrate_executor_preflight_checks(
        plan=plan,
        candidate=candidate,
        snapshot=snapshot,
        idle_gate=idle_gate,
        health=health,
        confirmation_status=confirmation_status,
        future_executor=future_executor,
        lock_status=lock_status,
    )
    summary = memory_orchestrate_guard_summary(checks)
    live_disabled_only = summary.get("confirm_blockers") == ["live_executor_stage_disabled"]
    preflight_ready_except_live_stage = all(
        item.get("status") == "pass" or item.get("id") == "live_executor_stage_disabled"
        for item in checks
        if isinstance(item, dict)
    )
    if preflight_ready_except_live_stage:
        decision = "ready_until_live_executor_stage_disabled"
        status = "preflight_ready_blocked_live_stage"
    else:
        decision = "blocked_before_live_executor_stage"
        status = "preflight_blocked"
    return {
        "schema": f"{SCHEMA_PREFIX}_memory_orchestrate_executor_preflight_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": False,
        "status": status,
        "decision": decision,
        "preflight_ready_except_live_stage": preflight_ready_except_live_stage,
        "blocked_only_by_live_stage_disabled": bool(live_disabled_only),
        "candidate_id": candidate.get("id"),
        "target_identity_digest": memory_orchestrate_target_identity_digest(candidate, snapshot),
        "checks": checks,
        "check_summary": summary,
        "future_executor": future_executor,
        "commands": {
            "plan": "abyss-machine memory orchestrate plan --json",
            "idle": "abyss-machine memory orchestrate idle --candidate ID --json",
            "confirm_dry_run": "abyss-machine memory orchestrate confirm --candidate ID --operator NAME --reason TEXT --acknowledge-protected --dry-run --json",
            "apply_confirm_preflight": "abyss-machine memory orchestrate apply --candidate ID --confirm --json",
            "apply_live": "abyss-machine memory orchestrate apply --candidate ID --confirm --execute-live --acknowledge-live-restart --operator NAME --reason TEXT --json",
        },
        "paths": {
            "latest": str(MEMORY_ORCHESTRATE_EXECUTOR_LATEST_PATH),
            "daily_glob": str(MEMORY_ORCHESTRATE_EXECUTOR_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "confirm_latest": str(MEMORY_ORCHESTRATE_CONFIRM_LATEST_PATH),
            "apply_latest": str(MEMORY_ORCHESTRATE_APPLY_LATEST_PATH),
            "live_latest": str(MEMORY_ORCHESTRATE_LIVE_LATEST_PATH),
        },
        "policy": {
            "facts_only": True,
            "confirmed_executor_preflight_only": True,
            "live_executor_supported": True,
            "live_executor_requires_separate_interlock": True,
            "existing_process_mutation": False,
            "does_not_generate_tokens": True,
            "does_not_record_prompts": True,
            "do_not_tune_zram_or_sysctl_from_plan": True,
            "do_not_stop_disable_throttle_reaffinitize_or_cap_live_services": True,
        },
    }


