def storage_policy_env() -> dict[str, Any]:
    errors: list[str] = []
    try:
        lines = STORAGE_POLICY_ENV_PATH.read_text(encoding="utf-8").splitlines()
    except FileNotFoundError:
        lines = []
        errors.append("missing")
    except OSError as exc:
        lines = []
        errors.append(str(exc))
    return storage_contracts.policy_env_document(
        STORAGE_POLICY_ENV_PATH,
        exists=STORAGE_POLICY_ENV_PATH.exists(),
        lines=lines,
        errors=errors,
    )


def storage_policy_document() -> dict[str, Any]:
    document, error = load_json_document(STORAGE_POLICY_PATH)
    return storage_contracts.policy_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        path=STORAGE_POLICY_PATH,
        exists=STORAGE_POLICY_PATH.exists(),
        document=document,
        load_error=error,
        env=storage_policy_env(),
    )


