def storage_status(write_latest: bool = True, full_ai_scan: bool = False) -> dict[str, Any]:
    policy = storage_policy_document()
    root_usage = disk_usage_summary(Path("/"))
    srv_usage = disk_usage_summary(Path("/srv"))
    direct_paths = [
        ABYSS_MACHINE_ROOT,
        ABYSS_MACHINE_CACHE_ROOT,
        AI_CACHE_ROOT,
        AI_OPENVINO_CACHE_ROOT,
        AI_TTS_CACHE_ROOT,
        ABYSS_MACHINE_RUNTIME_ROOT,
        ABYSS_AI_HOME,
        ABYSS_MACHINE_STORAGE_ROOT,
        ABYSS_MACHINE_TMP_ROOT,
    ]
    document = policy.get("document", {}) if isinstance(policy.get("document"), dict) else {}
    for item in document.get("direct_paths", []) if isinstance(document.get("direct_paths"), list) else []:
        if isinstance(item, dict) and item.get("path"):
            candidate = Path(str(item["path"]))
            if candidate not in direct_paths:
                direct_paths.append(candidate)
    direct_status = [path_storage_status(path, include_size=full_ai_scan and path.exists()) for path in direct_paths]

    home = Path.home()
    podman_store, podman_store_error = podman_store_summary(timeout=8.0)
    podman_graphroot = podman_graphroot_from_store(podman_store)
    podman_target = rootless_podman_target_graphroot()
    podman_on_large_root = is_relative_to_path(podman_graphroot, ABYSS_MACHINE_STORAGE_ROOT)
    if podman_on_large_root:
        podman_direct = path_storage_status(podman_graphroot, include_size=full_ai_scan and podman_graphroot.exists())
        podman_direct["name"] = "rootless_podman_graphroot"
        podman_direct["podman_store_error"] = podman_store_error
        direct_status.append(podman_direct)
    residual_specs = [
        ("home_huggingface", home / ".cache/huggingface", AI_CACHE_ROOT / "huggingface"),
        ("home_pip", home / ".cache/pip", ABYSS_MACHINE_CACHE_ROOT / "home/dionysus/cache/pip"),
        ("home_torch", home / ".cache/torch", AI_CACHE_ROOT / "torch"),
        ("home_torch_extensions", home / ".cache/torch_extensions", AI_CACHE_ROOT / "torch_extensions"),
        ("home_triton", home / ".triton", AI_CACHE_ROOT / "triton"),
        ("home_ms_playwright", home / ".cache/ms-playwright", ABYSS_MACHINE_CACHE_ROOT / "home/dionysus/cache/ms-playwright"),
        ("home_puppeteer", home / ".cache/puppeteer", ABYSS_MACHINE_CACHE_ROOT / "home/dionysus/cache/puppeteer"),
        ("home_npu_cache", home / ".cache/ze_intel_npu_cache", ABYSS_MACHINE_CACHE_ROOT / "home/dionysus/cache/ze_intel_npu_cache"),
        ("home_nltk_data", home / "nltk_data", AI_CACHE_ROOT / "nltk_data"),
    ]
    if not podman_on_large_root:
        residual_specs.append(("rootless_podman", podman_graphroot, podman_target))
    residual_status = []
    for name, path, target in residual_specs:
        item = path_storage_status(path, target, include_size=full_ai_scan and path.exists())
        item["name"] = name
        item["migration_required"] = bool(path.exists() and not path.is_symlink())
        residual_status.append(item)

    if full_ai_scan:
        ai_storage = ai_storage_status(write_latest=True)
    else:
        ai_storage, _ = load_json_document(AI_STORAGE_LATEST_PATH)
    hooks = storage_hooks_status()
    process_latest = process_latest_summary()
    podman_latest, _ = load_json_document(PODMAN_PREFLIGHT_LATEST_PATH)
    inventory_latest, _ = load_json_document(STORAGE_INVENTORY_LATEST_PATH)
    pressure_latest, _ = load_json_document(STORAGE_PRESSURE_LATEST_PATH)
    cleanup_plan_latest, _ = load_json_document(STORAGE_CLEANUP_PLAN_LATEST_PATH)
    monitor_latest, _ = load_json_document(STORAGE_MONITOR_LATEST_PATH)
    write_preflight_latest, _ = load_json_document(STORAGE_WRITE_PREFLIGHT_LATEST_PATH)
    apply_latest, _ = load_json_document(STORAGE_APPLY_LATEST_PATH)
    root_used = root_usage.get("used_percent")
    policy_doc = policy.get("document", {}) if isinstance(policy.get("document"), dict) else {}
    system_root = policy_doc.get("system_root", {}) if isinstance(policy_doc.get("system_root"), dict) else {}
    warning_threshold = float(system_root.get("warning_threshold_percent", 80))
    critical_threshold = float(system_root.get("critical_threshold_percent", 90))
    residual_bytes = (
        sum(int(item.get("size_bytes") or 0) for item in residual_status if item.get("migration_required"))
        if full_ai_scan
        else None
    )
    data = {
        "schema": f"{SCHEMA_PREFIX}_storage_status_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(policy.get("ok")) and not (isinstance(root_used, (int, float)) and root_used >= critical_threshold),
        "policy": {
            "path": str(STORAGE_POLICY_PATH),
            "ok": policy.get("ok"),
            "load_error": policy.get("load_error"),
            "version": policy_doc.get("version"),
            "env": policy.get("env"),
        },
        "roots": {
            "system": root_usage,
            "srv": srv_usage,
            "abyss_machine": disk_usage_summary(ABYSS_MACHINE_ROOT),
        },
        "direct_paths": direct_status,
        "residual_paths": residual_status,
        "environment_routes": storage_cache_env_routes(),
        "hooks": {
            "root_dirs": hooks.get("root_dirs"),
            "summary": hooks.get("summary"),
            "command": "abyss-machine storage hooks --json",
            "run_command": "abyss-machine storage run-hooks STAGE --json",
        },
        "processes": process_latest,
        "podman_preflight": {
            "latest": str(PODMAN_PREFLIGHT_LATEST_PATH),
            "exists": PODMAN_PREFLIGHT_LATEST_PATH.exists(),
            "generated_at": podman_latest.get("generated_at") if isinstance(podman_latest, dict) else None,
            "status": podman_latest.get("status") if isinstance(podman_latest, dict) else None,
            "migration_required": podman_latest.get("migration_required") if isinstance(podman_latest, dict) else None,
            "migration_ready": podman_latest.get("migration_ready") if isinstance(podman_latest, dict) else None,
            "blocked_reasons": podman_latest.get("blocked_reasons") if isinstance(podman_latest, dict) else None,
        },
        "inventory": {
            "latest": str(STORAGE_INVENTORY_LATEST_PATH),
            "exists": STORAGE_INVENTORY_LATEST_PATH.exists(),
            "generated_at": inventory_latest.get("generated_at") if isinstance(inventory_latest, dict) else None,
            "summary": inventory_latest.get("summary") if isinstance(inventory_latest, dict) else None,
        },
        "pressure": {
            "latest": str(STORAGE_PRESSURE_LATEST_PATH),
            "exists": STORAGE_PRESSURE_LATEST_PATH.exists(),
            "generated_at": pressure_latest.get("generated_at") if isinstance(pressure_latest, dict) else None,
            "summary": pressure_latest.get("summary") if isinstance(pressure_latest, dict) else None,
        },
        "cleanup_plan": {
            "latest": str(STORAGE_CLEANUP_PLAN_LATEST_PATH),
            "exists": STORAGE_CLEANUP_PLAN_LATEST_PATH.exists(),
            "generated_at": cleanup_plan_latest.get("generated_at") if isinstance(cleanup_plan_latest, dict) else None,
            "summary": cleanup_plan_latest.get("summary") if isinstance(cleanup_plan_latest, dict) else None,
        },
        "monitor": {
            "latest": str(STORAGE_MONITOR_LATEST_PATH),
            "exists": STORAGE_MONITOR_LATEST_PATH.exists(),
            "generated_at": monitor_latest.get("generated_at") if isinstance(monitor_latest, dict) else None,
            "summary": monitor_latest.get("summary") if isinstance(monitor_latest, dict) else None,
            "timer": "abyss-storage-monitor.timer",
            "service": "abyss-storage-monitor.service",
        },
        "write_preflight": {
            "latest": str(STORAGE_WRITE_PREFLIGHT_LATEST_PATH),
            "exists": STORAGE_WRITE_PREFLIGHT_LATEST_PATH.exists(),
            "generated_at": write_preflight_latest.get("generated_at") if isinstance(write_preflight_latest, dict) else None,
            "decision": write_preflight_latest.get("decision") if isinstance(write_preflight_latest, dict) else None,
            "reasons": write_preflight_latest.get("reasons") if isinstance(write_preflight_latest, dict) else None,
        },
        "apply": {
            "latest": str(STORAGE_APPLY_LATEST_PATH),
            "exists": STORAGE_APPLY_LATEST_PATH.exists(),
            "generated_at": apply_latest.get("generated_at") if isinstance(apply_latest, dict) else None,
            "action_id": apply_latest.get("action_id") if isinstance(apply_latest, dict) else None,
            "dry_run": apply_latest.get("dry_run") if isinstance(apply_latest, dict) else None,
            "ok": apply_latest.get("ok") if isinstance(apply_latest, dict) else None,
        },
        "ai_storage": {
            "source": "fresh_scan" if full_ai_scan else "latest_file",
            "latest_path": str(AI_STORAGE_LATEST_PATH),
            "summary": ai_storage.get("summary") if isinstance(ai_storage, dict) else None,
            "host_cache": ai_storage.get("host_cache") if isinstance(ai_storage, dict) else None,
        },
        "summary": {
            "root_used_percent": root_used,
            "root_warning": isinstance(root_used, (int, float)) and root_used >= warning_threshold,
            "root_critical": isinstance(root_used, (int, float)) and root_used >= critical_threshold,
            "srv_used_percent": srv_usage.get("used_percent"),
            "direct_paths": len(direct_status),
            "residual_paths_present": sum(1 for item in residual_status if item.get("exists")),
            "residual_paths_requiring_migration": sum(1 for item in residual_status if item.get("migration_required")),
            "residual_bytes_requiring_migration": residual_bytes,
            "executable_hooks": hooks.get("summary", {}).get("executable_hooks"),
            "latest_process_snapshot": process_latest.get("generated_at"),
            "podman_migration_required": podman_latest.get("migration_required") if isinstance(podman_latest, dict) else None,
            "podman_migration_ready": podman_latest.get("migration_ready") if isinstance(podman_latest, dict) else None,
            "podman_migration_status": podman_latest.get("status") if isinstance(podman_latest, dict) else None,
            "inventory_latest": inventory_latest.get("generated_at") if isinstance(inventory_latest, dict) else None,
            "pressure_latest": pressure_latest.get("generated_at") if isinstance(pressure_latest, dict) else None,
            "cleanup_plan_latest": cleanup_plan_latest.get("generated_at") if isinstance(cleanup_plan_latest, dict) else None,
            "monitor_latest": monitor_latest.get("generated_at") if isinstance(monitor_latest, dict) else None,
            "write_preflight_latest": write_preflight_latest.get("generated_at") if isinstance(write_preflight_latest, dict) else None,
            "apply_latest": apply_latest.get("generated_at") if isinstance(apply_latest, dict) else None,
        },
        "commands": {
            "policy": ["abyss-machine", "storage", "policy", "--json"],
            "status": ["abyss-machine", "storage", "status", "--json"],
            "status_full": ["abyss-machine", "storage", "status", "--full", "--json"],
            "hooks": ["abyss-machine", "storage", "hooks", "--json"],
            "process_snapshot": ["abyss-machine", "processes", "snapshot", "--json"],
            "podman_preflight": ["abyss-machine", "storage", "podman-preflight", "--json"],
            "inventory": ["abyss-machine", "storage", "inventory", "--json"],
            "inventory_full": ["abyss-machine", "storage", "inventory", "--full", "--json"],
            "pressure": ["abyss-machine", "storage", "pressure", "--json"],
            "pressure_refresh": ["abyss-machine", "storage", "pressure", "--refresh-inventory", "--json"],
            "cleanup_plan": ["abyss-machine", "storage", "cleanup-plan", "--json"],
            "cleanup_plan_refresh": ["abyss-machine", "storage", "cleanup-plan", "--refresh-inventory", "--json"],
            "monitor": ["abyss-machine", "storage", "monitor", "--json"],
            "write_preflight": ["abyss-machine", "storage", "write-preflight", "--kind", "KIND", "--bytes", "BYTES", "--target", "PATH", "--json"],
            "apply_dry_run": ["abyss-machine", "storage", "apply", "--action-id", "ID", "--dry-run", "--json"],
            "apply_confirm": ["abyss-machine", "storage", "apply", "--action-id", "ID", "--confirm", "--json"],
        },
        "rules": [
            "Large generated data belongs under /srv/abyss-machine, not /work and not the system root.",
            "Do not mutate abyss-stack repositories from this host storage layer.",
            "Do not write to or clean /srv/AbyssOS, /srv/GAMES, /srv/games, /srv/work, /work, or unknown /srv/* paths.",
            "Do not leave compatibility symlink tails for machine-owned caches or runtimes.",
            "Call pre/post hooks around large writes, runtime creation, cache cleanup, and process investigations when building new host automation.",
        ],
    }
    if write_latest:
        latest_error = safe_atomic_write_json(STORAGE_LATEST_PATH, data, 0o664)
        index_error = safe_atomic_write_json(STORAGE_INDEX_PATH, storage_paths(), 0o664)
        errors = [error for error in (latest_error, index_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


def podman_json(cmd: list[str], timeout: float = 10.0) -> tuple[Any, str | None]:
    out = run(["podman", *cmd], timeout=timeout)
    if not out["ok"]:
        return None, out["stderr"] or out["stdout"] or f"podman exited {out['returncode']}"
    try:
        return json.loads(out["stdout"] or "null"), None
    except json.JSONDecodeError as exc:
        return None, f"invalid podman JSON: {exc}"


def podman_text(cmd: list[str], timeout: float = 10.0) -> tuple[str, str | None]:
    out = run(["podman", *cmd], timeout=timeout)
    if not out["ok"]:
        return "", out["stderr"] or out["stdout"] or f"podman exited {out['returncode']}"
    return out["stdout"], None


def rootless_podman_target_graphroot() -> Path:
    return ABYSS_MACHINE_STORAGE_ROOT / "home/dionysus/containers/storage"


def podman_store_summary(timeout: float = 8.0) -> tuple[dict[str, Any], str | None]:
    if not command_exists("podman"):
        return {}, "podman is not installed"
    store_raw, store_error = podman_json(["info", "--format", "{{json .Store}}"], timeout=timeout)
    store = store_raw if isinstance(store_raw, dict) else {}
    return store, store_error


def podman_graphroot_from_store(store: dict[str, Any] | None = None) -> Path:
    store = store if isinstance(store, dict) else {}
    return Path(str(store.get("graphRoot") or Path.home() / ".local/share/containers/storage"))


