def work_context_docs(root: Path = Path("/srv/work"), max_docs: int = 120) -> list[str]:
    names = {"AGENTS.md", "README.md", "README.txt", "compose.yml", "compose.yaml", "docker-compose.yml", "docker-compose.yaml"}
    results: list[str] = []
    if not root.exists():
        return results
    try:
        for current, dirnames, filenames in os.walk(root):
            current_path = Path(current)
            try:
                depth = len(current_path.relative_to(root).parts)
            except ValueError:
                depth = 0
            if depth >= 5:
                dirnames[:] = []
            if any(part in {".git", "node_modules", "runtime", "logs", "uploads", "credentials", "secrets"} for part in current_path.parts):
                dirnames[:] = []
                continue
            for filename in filenames:
                lowered = filename.lower()
                if filename in names or lowered.startswith("readme") or "compose" in lowered:
                    results.append(str(current_path / filename))
                    if len(results) >= max_docs:
                        return sorted(results)
    except OSError:
        return sorted(results)
    return sorted(results)


def podman_migration_preflight(full: bool = False, write_latest: bool = True) -> dict[str, Any]:
    if not command_exists("podman"):
        return {
            "schema": f"{SCHEMA_PREFIX}_storage_podman_preflight_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "migration_ready": False,
            "error": "podman is not installed",
        }
    store, store_error = podman_store_summary(timeout=10.0)
    ps_text, ps_error = podman_text(["ps", "--format", "{{.Names}}"], timeout=8.0)
    running_names = [line.strip() for line in ps_text.splitlines() if line.strip()]
    all_text, all_error = podman_text(["ps", "-a", "--format", "{{.Names}}"], timeout=8.0)
    all_names = [line.strip() for line in all_text.splitlines() if line.strip()]

    containers: list[dict[str, Any]] = []
    inspect_error = None
    if all_names:
        out = run(["podman", "inspect", *all_names], timeout=20.0)
        if out["ok"]:
            try:
                raw_containers = json.loads(out["stdout"])
            except json.JSONDecodeError as exc:
                raw_containers = []
                inspect_error = f"invalid podman inspect JSON: {exc}"
            if isinstance(raw_containers, list):
                containers = [safe_container_summary(item) for item in raw_containers if isinstance(item, dict)]
        else:
            inspect_error = out["stderr"] or out["stdout"] or f"podman inspect exited {out['returncode']}"

    active = [item for item in containers if item.get("running")]
    work_mounts = [
        {"container": item.get("name"), **mount}
        for item in containers
        for mount in item.get("work_mounts", [])
        if isinstance(mount, dict)
    ]
    named_volume_mounts = [
        {"container": item.get("name"), **mount}
        for item in containers
        for mount in item.get("named_volumes", [])
        if isinstance(mount, dict)
    ]
    graph_root = podman_graphroot_from_store(store)
    target_graphroot = rootless_podman_target_graphroot()
    migration_required = str(graph_root) != str(target_graphroot)
    blocked_reasons: list[str] = []
    if migration_required and active:
        blocked_reasons.append("running_containers")
    if migration_required and ((Path.home() / ".local/share/containers").is_symlink() or graph_root.is_symlink()):
        blocked_reasons.append("existing_symlink_route")
    if migration_required and not graph_root.exists():
        blocked_reasons.append("graphroot_missing")
    if migration_required:
        hooks = run_storage_hooks(
            "pre_podman_migration",
            {
                "graphroot": str(graph_root),
                "target_graphroot": str(target_graphroot),
                "running_containers": [item.get("name") for item in active],
                "work_mounts": work_mounts,
                "named_volume_mounts": named_volume_mounts,
            },
            enforce=False,
        )
    else:
        hooks = {
            "schema": f"{SCHEMA_PREFIX}_storage_hooks_run_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": True,
            "stage": "pre_podman_migration",
            "skipped": True,
            "reason": "already_migrated",
            "summary": {"hooks": 0, "failed": 0},
        }
    if migration_required and hooks.get("summary", {}).get("failed"):
        blocked_reasons.append("pre_podman_migration_hook_failed")
    migration_ready = not blocked_reasons
    data = {
        "schema": f"{SCHEMA_PREFIX}_storage_podman_preflight_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": not store_error and not ps_error and not inspect_error,
        "migration_required": migration_required,
        "migration_ready": migration_ready,
        "status": "ready" if migration_required and migration_ready else ("blocked" if migration_required else "already_migrated"),
        "blocked_reasons": blocked_reasons,
        "informational_reasons": [] if migration_required else ["already_migrated"],
        "paths": {
            "latest": str(PODMAN_PREFLIGHT_LATEST_PATH),
            "daily_glob": str(PODMAN_PREFLIGHT_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "migration_script": str(ABYSS_MACHINE_STORAGE_ROOT / "migrate-podman-rootless.sh"),
            "storage_conf": str(Path.home() / ".config/containers/storage.conf"),
            "source_graphroot": str(graph_root),
            "target_graphroot": str(target_graphroot),
            "work_context_root": "/srv/work",
        },
        "store": {
            "config_file": store.get("configFile"),
            "graph_driver": store.get("graphDriverName"),
            "graph_root": store.get("graphRoot"),
            "run_root": store.get("runRoot"),
            "volume_path": store.get("volumePath"),
            "image_copy_tmp_dir": store.get("imageCopyTmpDir"),
            "containers": store.get("containerStore"),
            "images": store.get("imageStore"),
            "graph_status": store.get("graphStatus"),
        },
        "containers": containers,
        "work_context": {
            "docs": work_context_docs(),
            "work_mounts": work_mounts,
            "rules": [
                "Read relevant /srv/work project AGENTS.md before stopping or migrating work-related containers.",
                "Do not mutate /srv/work from host storage migration preflight.",
                "Do not use symlinks for Podman graphroot migration.",
            ],
        },
        "volumes": {
            "named_volume_mounts": named_volume_mounts,
            "active_named_volume_mounts": [item for item in named_volume_mounts if item.get("container") in {c.get("name") for c in active}],
        },
        "symlinks": {
            "containers_base_is_symlink": (Path.home() / ".local/share/containers").is_symlink(),
            "graphroot_is_symlink": graph_root.is_symlink(),
        },
        "hooks": {
            "pre_podman_migration": hooks,
        },
        "errors": [item for item in (store_error, ps_error, all_error, inspect_error) if item],
        "policy": {
            "migration_method": "direct rootless Podman storage.conf graphroot migration; no symlink tail",
            "requires_all_containers_stopped": True,
            "requires_work_context_read": bool(work_mounts),
            "redaction": "container env and create commands are omitted because they can contain secrets",
        },
    }
    if full:
        data["sizes"] = {
            "source_graphroot_bytes": directory_size(graph_root) if graph_root.exists() else None,
            "target_graphroot_bytes": directory_size(target_graphroot) if target_graphroot.exists() else None,
        }
    if write_latest:
        latest_error = safe_atomic_write_json(PODMAN_PREFLIGHT_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(PODMAN_PREFLIGHT_ROOT), data, 0o664)
        errors = [error for error in (latest_error, daily_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


