def storage_inventory_item(spec: dict[str, Any], measure: bool = True) -> dict[str, Any]:
    return storage_adapters.inventory_item_status(spec, measure=measure, size_bytes=du_size_bytes)


def storage_inventory_drift(items: list[dict[str, Any]], previous: dict[str, Any] | None) -> dict[str, Any]:
    return storage_contracts.inventory_drift(items, previous)


def storage_inventory(full: bool = False, include_home_review: bool = False, write_latest: bool = True) -> dict[str, Any]:
    previous, _ = load_json_document(STORAGE_INVENTORY_LATEST_PATH)
    specs = storage_inventory_specs(include_home_review=include_home_review or full)
    items = [
        storage_inventory_item(spec, measure=bool(full or spec.get("measure_light", True)))
        for spec in specs
    ]
    by_category: dict[str, dict[str, Any]] = {}
    for item in items:
        category = str(item.get("category") or "unknown")
        bucket = by_category.setdefault(
            category,
            {"items": 0, "existing": 0, "measured": 0, "unmeasured_existing": 0, "size_bytes": 0},
        )
        bucket["items"] = int(bucket["items"]) + 1
        if item.get("exists"):
            bucket["existing"] = int(bucket["existing"]) + 1
        if isinstance(item.get("size_bytes"), int):
            bucket["measured"] = int(bucket["measured"]) + 1
            bucket["size_bytes"] = int(bucket["size_bytes"]) + int(item["size_bytes"])
        elif item.get("exists"):
            bucket["unmeasured_existing"] = int(bucket["unmeasured_existing"]) + 1
    pressure_candidates = [
        item for item in items
        if item.get("exists") and item.get("category") in {
            "cleanup_candidate",
            "rebuildable_cache",
            "redownloadable_heavy",
            "package_cache",
            "stale_archive_candidate",
        }
    ]
    manual_only = [
        item for item in items
        if item.get("exists") and item.get("category") in {
            "operator_review",
            "project_source",
            "stale_archive_candidate",
        }
    ]
    migrate = [item for item in items if item.get("exists") and item.get("category") == "migrate_not_delete"]
    root_usage = disk_usage_summary(Path("/"))
    srv_usage = disk_usage_summary(Path("/srv"))
    drift = storage_inventory_drift(items, previous)
    recommendations: list[dict[str, Any]] = []
    if migrate:
        recommendations.append({
            "priority": 1,
            "action": "migrate_not_delete",
            "target": "rootless Podman graphroot",
            "reason": "Largest known root pressure item; must be moved through direct storage.conf migration after containers are stopped.",
            "command": "abyss-machine storage podman-preflight --json",
        })
    root_used = root_usage.get("used_percent")
    if isinstance(root_used, (int, float)) and root_used >= 80:
        recommendations.append({
            "priority": 2,
            "action": "review_root_pressure",
            "target": "/",
            "reason": "Root filesystem crossed warning threshold.",
        })
    for item in sorted(pressure_candidates, key=lambda value: int(value.get("size_bytes") or 0), reverse=True)[:8]:
        recommendations.append({
            "priority": 3,
            "action": "review_cleanup_candidate",
            "id": item.get("id"),
            "path": item.get("path"),
            "category": item.get("category"),
            "size_bytes": item.get("size_bytes"),
            "reason": item.get("reason"),
        })
    data = {
        "schema": f"{SCHEMA_PREFIX}_storage_inventory_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "mode": "full" if full else "light",
        "paths": {
            "latest": str(STORAGE_INVENTORY_LATEST_PATH),
            "daily_glob": str(STORAGE_INVENTORY_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "policy": str(STORAGE_POLICY_PATH),
        },
        "classification": {
            "must_keep_external_work": "Work/project data; never machine-clean automatically.",
            "active_agent_state": "Agent state; keep unless operator reviews manually.",
            "host_runtime": "Host runtime/toolchains; keep current, review obsolete experiments manually.",
            "active_ai_artifacts": "Current AI artifacts; cleanup needs profile/model awareness.",
            "project_source": "Source trees; no machine cleanup from this layer.",
            "rebuildable_cache": "Useful cache; can be regenerated when storage pressure matters.",
            "redownloadable_heavy": "Can be downloaded again but has network/offline/time cost.",
            "package_cache": "Clean through package manager only.",
            "cleanup_candidate": "Generated temporary data; cleanup by age after confirming no active process uses it.",
            "stale_archive_candidate": "Likely old archive; operator review before move/delete.",
            "migrate_not_delete": "Move to better storage route; do not delete.",
            "operator_review": "Mixed or personal data; no automatic action.",
        },
        "roots": {
            "system": root_usage,
            "srv": srv_usage,
        },
        "memory": proc_meminfo_summary(),
        "summary": {
            "items": len(items),
            "existing_items": sum(1 for item in items if item.get("exists")),
            "measured_items": sum(1 for item in items if item.get("measured")),
            "unmeasured_existing_items": sum(1 for item in items if item.get("exists") and not item.get("measured")),
            "measured_bytes": sum(int(item.get("size_bytes") or 0) for item in items),
            "pressure_candidate_bytes": sum(int(item.get("size_bytes") or 0) for item in pressure_candidates),
            "pressure_candidate_unmeasured_items": sum(1 for item in pressure_candidates if not item.get("measured")),
            "manual_review_bytes": sum(int(item.get("size_bytes") or 0) for item in manual_only),
            "manual_review_unmeasured_items": sum(1 for item in manual_only if not item.get("measured")),
            "migrate_not_delete_bytes": sum(int(item.get("size_bytes") or 0) for item in migrate),
            "migrate_not_delete_unmeasured_items": sum(1 for item in migrate if not item.get("measured")),
            "categories": by_category,
            "drift_new": len(drift.get("new", [])),
            "drift_grown": len(drift.get("grown", [])),
        },
        "items": items,
        "drift": drift,
        "recommendations": recommendations,
        "policy": {
            "facts_only": True,
            "automatic_deletion": False,
            "no_work_cleanup": True,
            "no_abyss_stack_mutation": True,
            "cleanup_requires_explicit_operator_action": True,
        },
    }
    if write_latest:
        latest_error = safe_atomic_write_json(STORAGE_INVENTORY_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(STORAGE_INVENTORY_ROOT), data, 0o664)
        errors = [error for error in (latest_error, daily_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


def storage_inventory_latest_or_refresh(refresh: bool = False) -> tuple[dict[str, Any], str | None]:
    if refresh:
        return storage_inventory(full=False, include_home_review=False, write_latest=True), None
    latest, error = load_json_document(STORAGE_INVENTORY_LATEST_PATH)
    if latest is None:
        latest = storage_inventory(full=False, include_home_review=False, write_latest=True)
        return latest, error
    return latest, None


