def storage_pressure_recommendations(
    candidates: list[dict[str, Any]],
    root_class: str,
    srv_class: str,
) -> list[dict[str, Any]]:
    return storage_contracts.pressure_recommendations(
        candidates,
        root_class,
        srv_class,
        abyss_machine_root=ABYSS_MACHINE_ROOT,
    )


def storage_pressure(refresh_inventory: bool = False, write_latest: bool = True) -> dict[str, Any]:
    inventory, inventory_load_error = storage_inventory_latest_or_refresh(refresh=refresh_inventory)
    status = storage_status(write_latest=False, full_ai_scan=False)
    thresholds = storage_policy_thresholds()
    root_usage = status.get("roots", {}).get("system", {}) if isinstance(status.get("roots"), dict) else {}
    srv_usage = status.get("roots", {}).get("srv", {}) if isinstance(status.get("roots"), dict) else {}
    watch_margin = thresholds["watch_margin_percent"]
    root_class = storage_pressure_class(
        root_usage.get("used_percent"),
        thresholds["system_warning_percent"],
        thresholds["system_critical_percent"],
        watch_margin,
    )
    srv_class = storage_pressure_class(
        srv_usage.get("used_percent"),
        thresholds["srv_warning_percent"],
        thresholds["srv_critical_percent"],
        watch_margin,
    )
    items = [item for item in inventory.get("items", []) if isinstance(item, dict)]
    candidates = [item for item in items if storage_item_is_pressure_candidate(item)]
    by_scope: dict[str, dict[str, Any]] = {}
    by_category: dict[str, dict[str, Any]] = {}
    for item in candidates:
        scope = storage_item_scope(item)
        category = str(item.get("category") or "unknown")
        for key, bucket_map in ((scope, by_scope), (category, by_category)):
            bucket = bucket_map.setdefault(key, {"items": 0, "measured_items": 0, "size_bytes": 0, "unmeasured_items": 0})
            bucket["items"] = int(bucket["items"]) + 1
            if isinstance(item.get("size_bytes"), int):
                bucket["measured_items"] = int(bucket["measured_items"]) + 1
                bucket["size_bytes"] = int(bucket["size_bytes"]) + int(item["size_bytes"])
            else:
                bucket["unmeasured_items"] = int(bucket["unmeasured_items"]) + 1
    root_thresholds = {
        "warning": storage_threshold_bytes(root_usage, thresholds["system_warning_percent"]),
        "critical": storage_threshold_bytes(root_usage, thresholds["system_critical_percent"]),
    }
    srv_thresholds = {
        "warning": storage_threshold_bytes(srv_usage, thresholds["srv_warning_percent"]),
        "critical": storage_threshold_bytes(srv_usage, thresholds["srv_critical_percent"]),
    }
    data = {
        "schema": f"{SCHEMA_PREFIX}_storage_pressure_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(status.get("ok")) and bool(inventory.get("ok", True)),
        "paths": {
            "latest": str(STORAGE_PRESSURE_LATEST_PATH),
            "daily_glob": str(STORAGE_PRESSURE_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "inventory_latest": str(STORAGE_INVENTORY_LATEST_PATH),
            "cleanup_plan_latest": str(STORAGE_CLEANUP_PLAN_LATEST_PATH),
        },
        "inputs": {
            "inventory_generated_at": inventory.get("generated_at"),
            "inventory_mode": inventory.get("mode"),
            "inventory_load_error_before_refresh": inventory_load_error,
            "status_generated_at": status.get("generated_at"),
            "refreshed_inventory": bool(refresh_inventory),
        },
        "thresholds": thresholds,
        "roots": {
            "system": {
                **root_usage,
                "pressure_class": root_class,
                "thresholds": root_thresholds,
            },
            "srv": {
                **srv_usage,
                "pressure_class": srv_class,
                "thresholds": srv_thresholds,
            },
        },
        "summary": {
            "root_pressure_class": root_class,
            "srv_pressure_class": srv_class,
            "pressure_candidates": len(candidates),
            "pressure_candidate_bytes": sum(storage_item_size_bytes(item) for item in candidates),
            "root_pressure_candidate_bytes": by_scope.get("root", {}).get("size_bytes", 0),
            "srv_pressure_candidate_bytes": by_scope.get("srv", {}).get("size_bytes", 0),
            "work_protected_candidate_bytes": by_scope.get("work", {}).get("size_bytes", 0),
            "unmeasured_pressure_candidates": sum(1 for item in candidates if item.get("exists") and not isinstance(item.get("size_bytes"), int)),
        },
        "candidates": [
            {
                "id": item.get("id"),
                "path": item.get("path"),
                "scope": storage_item_scope(item),
                "category": item.get("category"),
                "disposition": item.get("disposition"),
                "reclaimability": item.get("reclaimability"),
                "confidence": item.get("confidence"),
                "size_bytes": item.get("size_bytes"),
                "measured": item.get("measured"),
                "reason": item.get("reason"),
                "safe_automatic_cleanup": bool(item.get("safe_automatic_cleanup")),
            }
            for item in sorted(candidates, key=storage_item_size_bytes, reverse=True)
        ],
        "by_scope": by_scope,
        "by_category": by_category,
        "drift": inventory.get("drift"),
        "recommendations": storage_pressure_recommendations(candidates, root_class, srv_class),
        "policy": {
            "facts_only": True,
            "automatic_deletion": False,
            "cleanup_requires_cleanup_plan": True,
            "no_work_cleanup": True,
            "no_abyss_stack_mutation": True,
            "no_symlink_tail": True,
        },
    }
    if write_latest:
        latest_error = safe_atomic_write_json(STORAGE_PRESSURE_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(STORAGE_PRESSURE_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(STORAGE_INDEX_PATH, storage_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


def storage_match_path_text(candidate: str, text: str | None) -> bool:
    return storage_adapters.path_text_matches(candidate, text)


def storage_process_path_usage(paths: list[str], interval: float = 0.5, top: int = 30) -> dict[str, Any]:
    return storage_adapters.process_path_usage_document(
        paths=paths,
        process_snapshot=lambda snapshot_top, snapshot_interval: process_snapshot(
            top=snapshot_top,
            interval=snapshot_interval,
            write_latest=True,
        ),
        generated_at=now_iso(),
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        process_latest_path=PROCESS_LATEST_PATH,
        interval=interval,
        top=top,
    )


def storage_cleanup_action_for_item(
    item: dict[str, Any],
    pressure: dict[str, Any],
    guard_by_path: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    _ = pressure
    return storage_contracts.cleanup_action_for_item(
        item,
        guard_by_path=guard_by_path,
        abyss_machine_root=ABYSS_MACHINE_ROOT,
    )


def storage_cleanup_plan(
    refresh_inventory: bool = False,
    process_guard: bool = True,
    interval: float = 0.5,
    top: int = 30,
    write_latest: bool = True,
    pressure_input: dict[str, Any] | None = None,
) -> dict[str, Any]:
    interval = max(0.0, min(float(interval), 5.0))
    top = max(5, min(int(top), 200))
    pressure = pressure_input if isinstance(pressure_input, dict) else storage_pressure(refresh_inventory=refresh_inventory, write_latest=True)
    inventory, inventory_load_error = storage_inventory_latest_or_refresh(refresh=False)
    items = [item for item in inventory.get("items", []) if isinstance(item, dict)]
    candidates = [item for item in items if storage_item_is_pressure_candidate(item)]
    candidate_paths = [str(item.get("path")) for item in candidates if item.get("path") and item.get("exists")]
    if process_guard:
        guard = storage_process_path_usage(candidate_paths, interval=interval, top=top)
        guard_by_path = {str(item.get("path")): item for item in guard.get("paths", []) if isinstance(item, dict)}
    else:
        guard = {
            "schema": f"{SCHEMA_PREFIX}_storage_process_path_usage_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": True,
            "skipped": True,
            "reason": "process_guard_disabled_by_operator",
            "paths": [],
            "summary": {"paths": len(candidate_paths), "active_paths": None, "active_process_refs": None},
        }
        guard_by_path = {}
    actions = [
        storage_cleanup_action_for_item(item, pressure=pressure, guard_by_path=guard_by_path)
        for item in candidates
    ]
    root_pressure = str(pressure.get("summary", {}).get("root_pressure_class") or "unknown")
    srv_pressure = str(pressure.get("summary", {}).get("srv_pressure_class") or "unknown")

    def action_sort_key(action: dict[str, Any]) -> tuple[int, int, int]:
        scope = str(action.get("scope") or "")
        category = str(action.get("category") or "")
        size = int(action.get("estimated_bytes") or 0)
        scope_rank = 0 if scope == "root" and root_pressure in {"watch", "warning", "critical"} else (1 if scope == "root" else 2)
        category_rank = {
            "package_cache": 0,
            "cleanup_candidate": 1,
            "rebuildable_cache": 2,
            "redownloadable_heavy": 3,
            "stale_archive_candidate": 4,
            "migrate_not_delete": 5,
        }.get(category, 9)
        return (scope_rank, category_rank, -size)

    actions = sorted(actions, key=action_sort_key)
    hooks = {
        "pre_cache_cleanup": storage_hooks_status(stage="pre_cache_cleanup"),
        "post_cache_cleanup": storage_hooks_status(stage="post_cache_cleanup"),
    }
    data = {
        "schema": f"{SCHEMA_PREFIX}_storage_cleanup_plan_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(pressure.get("ok")) and bool(inventory.get("ok", True)) and bool(guard.get("ok", True)),
        "paths": {
            "latest": str(STORAGE_CLEANUP_PLAN_LATEST_PATH),
            "daily_glob": str(STORAGE_CLEANUP_PLAN_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "pressure_latest": str(STORAGE_PRESSURE_LATEST_PATH),
            "inventory_latest": str(STORAGE_INVENTORY_LATEST_PATH),
            "process_snapshot_latest": str(PROCESS_LATEST_PATH),
        },
        "inputs": {
            "pressure_generated_at": pressure.get("generated_at"),
            "inventory_generated_at": inventory.get("generated_at"),
            "inventory_load_error": inventory_load_error,
            "refresh_inventory": bool(refresh_inventory),
            "process_guard": bool(process_guard),
            "process_guard_interval_sec": interval,
            "process_guard_top": top,
        },
        "pressure": {
            "summary": pressure.get("summary"),
            "roots": pressure.get("roots"),
        },
        "guard": guard,
        "actions": actions,
        "summary": {
            "actions": len(actions),
            "operator_review_ready": sum(1 for item in actions if item.get("readiness") == "operator_review_ready"),
            "blocked": sum(1 for item in actions if item.get("readiness") == "blocked"),
            "blocked_by_active_process": sum(1 for item in actions if "active_process_reference" in item.get("blocked_reasons", [])),
            "root_candidate_bytes": sum(int(item.get("estimated_bytes") or 0) for item in actions if item.get("scope") == "root"),
            "srv_candidate_bytes": sum(int(item.get("estimated_bytes") or 0) for item in actions if item.get("scope") == "srv"),
            "ready_candidate_bytes": sum(int(item.get("estimated_bytes") or 0) for item in actions if item.get("readiness") == "operator_review_ready"),
            "unmeasured_actions": sum(1 for item in actions if not isinstance(item.get("estimated_bytes"), int)),
        },
        "hooks": hooks,
        "policy": {
            "facts_only": True,
            "automatic_deletion": False,
            "this_command_does_not_delete": True,
            "cleanup_apply_requires_explicit_operator_action": True,
            "no_work_cleanup": True,
            "no_abyss_stack_mutation": True,
            "no_symlink_tail": True,
        },
        "next_contract": [
            "A future apply command must consume this plan, re-run process guard, run pre_cache_cleanup hooks with --enforce, execute one explicit action, then run post_cache_cleanup hooks.",
            "This plan is valid evidence, not permission to delete by itself.",
        ],
    }
    if write_latest:
        latest_error = safe_atomic_write_json(STORAGE_CLEANUP_PLAN_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(STORAGE_CLEANUP_PLAN_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(STORAGE_INDEX_PATH, storage_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


def storage_monitor(
    process_guard: bool = True,
    interval: float = 0.0,
    top: int = 30,
    write_latest: bool = True,
) -> dict[str, Any]:
    interval = max(0.0, min(float(interval), 5.0))
    top = max(5, min(int(top), 200))
    started = time.monotonic()
    steps: list[dict[str, Any]] = []

    def step_summary(name: str, command: list[str], before: float, document: dict[str, Any]) -> None:
        steps.append({
            "name": name,
            "command": command,
            "ok": bool(document.get("ok", True)),
            "schema": document.get("schema"),
            "generated_at": document.get("generated_at"),
            "duration_sec": round(time.monotonic() - before, 3),
            "summary": document.get("summary"),
            "write_errors": document.get("write_errors"),
        })

    step_started = time.monotonic()
    inventory = storage_inventory(full=False, include_home_review=False, write_latest=True)
    step_summary("inventory_light", ["abyss-machine", "storage", "inventory", "--json"], step_started, inventory)

    step_started = time.monotonic()
    pressure = storage_pressure(refresh_inventory=False, write_latest=True)
    step_summary("pressure", ["abyss-machine", "storage", "pressure", "--json"], step_started, pressure)

    step_started = time.monotonic()
    cleanup = storage_cleanup_plan(
        refresh_inventory=False,
        process_guard=process_guard,
        interval=interval,
        top=top,
        write_latest=True,
        pressure_input=pressure,
    )
    step_summary("cleanup_plan", ["abyss-machine", "storage", "cleanup-plan", "--json"], step_started, cleanup)

    step_started = time.monotonic()
    status = storage_status(write_latest=True, full_ai_scan=False)
    step_summary("status", ["abyss-machine", "storage", "status", "--json"], step_started, status)

    step_started = time.monotonic()
    artifact_snapshot = artifacts_snapshot(scope="ai-cache", history_days=14, write_latest=True)
    step_summary(
        "artifacts_snapshot_ai_cache",
        ["abyss-machine", "artifacts", "snapshot", "--scope", "ai-cache", "--history-days", "14", "--json"],
        step_started,
        artifact_snapshot,
    )

    guard_summary = cleanup.get("guard", {}).get("summary", {}) if isinstance(cleanup.get("guard"), dict) else {}
    active_paths = [
        {
            "path": item.get("path"),
            "active_processes": len(item.get("active_processes", [])) if isinstance(item.get("active_processes"), list) else None,
        }
        for item in cleanup.get("guard", {}).get("paths", [])
        if isinstance(item, dict) and item.get("active")
    ] if isinstance(cleanup.get("guard"), dict) else []
    data = {
        "schema": f"{SCHEMA_PREFIX}_storage_monitor_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": all(bool(item.get("ok", True)) for item in steps),
        "paths": {
            "latest": str(STORAGE_MONITOR_LATEST_PATH),
            "daily_glob": str(STORAGE_MONITOR_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "storage_status_latest": str(STORAGE_LATEST_PATH),
            "inventory_latest": str(STORAGE_INVENTORY_LATEST_PATH),
            "pressure_latest": str(STORAGE_PRESSURE_LATEST_PATH),
            "cleanup_plan_latest": str(STORAGE_CLEANUP_PLAN_LATEST_PATH),
            "artifact_snapshot_latest": str(ARTIFACTS_SNAPSHOT_LATEST_PATH),
            "index": str(STORAGE_INDEX_PATH),
        },
        "timer": {
            "service": "abyss-storage-monitor.service",
            "timer": "abyss-storage-monitor.timer",
            "scope": "user",
            "recommended_interval": "1h",
            "full_inventory_on_timer": False,
        },
        "inputs": {
            "process_guard": bool(process_guard),
            "process_guard_interval_sec": interval,
            "process_guard_top": top,
            "facts_only": True,
            "automatic_deletion": False,
        },
        "steps": steps,
        "summary": {
            "duration_sec": round(time.monotonic() - started, 3),
            "root_used_percent": nested_get(status, ["summary", "root_used_percent"]),
            "srv_used_percent": nested_get(status, ["summary", "srv_used_percent"]),
            "root_pressure_class": nested_get(pressure, ["summary", "root_pressure_class"]),
            "srv_pressure_class": nested_get(pressure, ["summary", "srv_pressure_class"]),
            "pressure_candidates": nested_get(pressure, ["summary", "pressure_candidates"]),
            "pressure_candidate_bytes": nested_get(pressure, ["summary", "pressure_candidate_bytes"]),
            "cleanup_actions": nested_get(cleanup, ["summary", "actions"]),
            "cleanup_operator_review_ready": nested_get(cleanup, ["summary", "operator_review_ready"]),
            "cleanup_blocked": nested_get(cleanup, ["summary", "blocked"]),
            "cleanup_blocked_by_active_process": nested_get(cleanup, ["summary", "blocked_by_active_process"]),
            "artifact_snapshot_records": nested_get(artifact_snapshot, ["summary", "records"]),
            "artifact_snapshot_current_live_records": nested_get(artifact_snapshot, ["summary", "current_live_records"]),
            "artifact_snapshot_backed_records": nested_get(artifact_snapshot, ["summary", "backed_records"]),
            "artifact_snapshot_classes": nested_get(artifact_snapshot, ["summary", "by_classification"]),
            "process_guard_paths": guard_summary.get("paths"),
            "process_guard_active_paths": guard_summary.get("active_paths"),
            "active_paths": active_paths,
        },
        "policy": {
            "facts_only": True,
            "automatic_deletion": False,
            "no_work_cleanup": True,
            "no_abyss_stack_mutation": True,
            "no_symlink_tail": True,
            "timer_uses_light_inventory_only": True,
            "timer_refreshes_artifact_snapshot": True,
            "artifact_snapshot_is_facts_only": True,
            "cleanup_plan_is_not_permission_to_delete": True,
        },
    }
    if write_latest:
        latest_error = safe_atomic_write_json(STORAGE_MONITOR_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(STORAGE_MONITOR_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(STORAGE_INDEX_PATH, storage_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


