def storage_apply(
    action_id: str,
    dry_run: bool = True,
    confirm: bool = False,
    age_days: float = 7.0,
    write_latest: bool = True,
) -> dict[str, Any]:
    dry_run = bool(dry_run or not confirm)
    monitor = storage_monitor(process_guard=True, interval=0.0, top=30, write_latest=True)
    cleanup, _ = load_json_document(STORAGE_CLEANUP_PLAN_LATEST_PATH)
    cleanup = cleanup if isinstance(cleanup, dict) else {}
    action = storage_apply_find_action(cleanup, action_id)
    blocked_reasons: list[str] = []
    if action is None:
        blocked_reasons.append("action_id_not_found")
    else:
        if action.get("readiness") == "blocked":
            blocked_reasons.extend(str(item) for item in action.get("blocked_reasons", []) if item)
        path = Path(str(action.get("path") or ""))
        protection = storage_path_protection(path)
        if protection.get("decision") == "deny" and protection.get("class") != "host_owned_allowed":
            blocked_reasons.append("protected_target")
    pre_hooks = None
    post_hooks = None
    execution: dict[str, Any]
    if action is None:
        execution = {"ok": False, "blocked": True, "reason": "action_id_not_found"}
    elif blocked_reasons:
        execution = {"ok": False, "blocked": True, "reason": "blocked_by_policy_or_process_guard"}
    elif dry_run:
        execution = storage_apply_dry_run_result(action, age_days=age_days)
        execution["ok"] = True
        execution["dry_run"] = True
    else:
        payload = {"action": action, "action_id": action_id, "dry_run": False}
        pre_hooks = run_storage_hooks("pre_cache_cleanup", payload, enforce=True)
        if not pre_hooks.get("ok"):
            execution = {"ok": False, "blocked": True, "reason": "pre_cache_cleanup_hook_failed"}
        else:
            execution = storage_apply_execute_action(action, age_days=age_days)
            post_hooks = run_storage_hooks("post_cache_cleanup", {"action": action, "execution": execution}, enforce=False)
            storage_monitor(process_guard=True, interval=0.0, top=30, write_latest=True)
    data = {
        "schema": f"{SCHEMA_PREFIX}_storage_apply_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(execution.get("ok")) and not blocked_reasons,
        "dry_run": dry_run,
        "confirmed": bool(confirm),
        "action_id": action_id,
        "action": action,
        "blocked_reasons": blocked_reasons,
        "execution": execution,
        "paths": {
            "latest": str(STORAGE_APPLY_LATEST_PATH),
            "daily_glob": str(STORAGE_APPLY_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
            "monitor_latest": str(STORAGE_MONITOR_LATEST_PATH),
            "cleanup_plan_latest": str(STORAGE_CLEANUP_PLAN_LATEST_PATH),
        },
        "monitor": {
            "generated_at": monitor.get("generated_at"),
            "summary": monitor.get("summary"),
        },
        "hooks": {
            "pre_cache_cleanup": pre_hooks,
            "post_cache_cleanup": post_hooks,
        },
        "policy": {
            "default_is_dry_run": True,
            "actual_apply_requires_confirm": True,
            "single_action_only": True,
            "process_guard_rerun": True,
            "no_work_cleanup": True,
            "no_abyss_stack_mutation": True,
            "no_games_mutation": True,
            "protected_roots": storage_protected_roots(),
        },
    }
    if write_latest:
        latest_error = safe_atomic_write_json(STORAGE_APPLY_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(STORAGE_APPLY_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(STORAGE_INDEX_PATH, storage_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


