def process_game_classifier_regression_cases() -> list[dict[str, Any]]:
    cases = [
        {
            "name": "bottles_adobecc_explorer_is_not_active_game",
            "cmdline": r"C:\windows\system32\explorer.exe /desktop",
            "comm": "explorer.exe",
            "cwd": str(Path.home() / ".local/share/bottles/bottles/AdobeCC/drive_c/windows/system32"),
            "exe": str(Path.home() / ".local/share/bottles/runners/wine-11.9-staging-amd64-wow64/lib/wine/x86_64-unix/wine-preloader"),
            "expected_role": "none",
            "expected_workload": "normal",
        },
        {
            "name": "steam_client_is_platform_not_active_game",
            "cmdline": f"{PATH_POLICY.home / '.var/app/com.valvesoftware.Steam/.local/share/Steam/ubuntu12_32/steam'} -no-cef-sandbox",
            "comm": "steam",
            "cwd": str(Path.home() / ".var/app/com.valvesoftware.Steam/.local/share/Steam"),
            "exe": str(Path.home() / ".var/app/com.valvesoftware.Steam/.local/share/Steam/ubuntu12_32/steam"),
            "expected_role": "game_platform",
            "expected_workload": "game_platform",
        },
        {
            "name": "protected_game_root_is_active_game",
            "cmdline": "/srv/games/example/game.exe",
            "comm": "game.exe",
            "cwd": "/srv/games/example",
            "exe": "/srv/games/example/game.exe",
            "expected_role": "active_game",
            "expected_workload": "game",
        },
        {
            "name": "steamapps_common_proton_runtime_is_active_game",
            "cmdline": windows_z_path(PATH_POLICY.home / ".var/app/com.valvesoftware.Steam/.local/share/Steam/steamapps/common/Example/Example.exe"),
            "comm": "Example.exe",
            "cwd": str(Path.home() / ".var/app/com.valvesoftware.Steam/.local/share/Steam/steamapps/common/Example"),
            "exe": str(Path.home() / ".var/app/com.valvesoftware.Steam/.local/share/Steam/compatibilitytools.d/GE-Proton/files/bin/wine-preloader"),
            "expected_role": "active_game",
            "expected_workload": "game",
        },
        {
            "name": "dragon_age_daorigins_wine_window_is_active_game",
            "cmdline": windows_z_path(PATH_POLICY.home / "Games/Dragon Age Origins/bin_ship/DAOrigins.exe"),
            "comm": "DAOrigins.exe",
            "cwd": str(Path.home() / ".local/share/bottles/bottles/Games/drive_c/Games/Dragon Age Origins"),
            "exe": str(Path.home() / ".local/share/bottles/runners/wine-11.9-staging-amd64-wow64/lib/wine/x86_64-unix/wine-preloader"),
            "expected_role": "active_game",
            "expected_workload": "game",
        },
    ]
    for case in cases:
        role = process_game_role(case["cmdline"], case["comm"], case["cwd"], case["exe"])
        workload = process_workload_hint(case["cmdline"], case["comm"], case["cwd"], case["exe"])
        case["observed_role"] = role
        case["observed_workload"] = workload
        case["ok"] = role == case["expected_role"] and workload == case["expected_workload"]
    return cases


