def gamemode_simple_config(path: Path) -> dict[str, Any]:
    if not path.exists() or not path.is_file():
        return {"path": str(path), "exists": False}
    sections: dict[str, dict[str, str]] = {}
    current = "default"
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError as exc:
        return {"path": str(path), "exists": True, "error": str(exc)}
    for raw_line in lines:
        line = raw_line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            current = line[1:-1].strip() or "default"
            sections.setdefault(current, {})
            continue
        key, sep, value = line.partition("=")
        if sep:
            sections.setdefault(current, {})[key.strip()] = value.strip()
    general = sections.get("general", {})
    cpu = sections.get("cpu", {})
    custom = sections.get("custom", {})
    return {
        "path": str(path),
        "exists": True,
        "sections": sorted(sections),
        "effective_keys": {
            "desiredgov": general.get("desiredgov"),
            "igpu_desiredgov": general.get("igpu_desiredgov"),
            "igpu_power_threshold": general.get("igpu_power_threshold"),
            "softrealtime": general.get("softrealtime"),
            "renice": general.get("renice"),
            "ioprio": general.get("ioprio"),
            "inhibit_screensaver": general.get("inhibit_screensaver"),
            "disable_splitlock": general.get("disable_splitlock"),
            "park_cores": cpu.get("park_cores"),
            "pin_cores": cpu.get("pin_cores"),
            "custom_start": custom.get("start"),
            "custom_end": custom.get("end"),
        },
    }


def gamemode_status() -> dict[str, Any]:
    available = command_exists("gamemoded") and command_exists("gamemoderun")
    status_run = run(["gamemoded", "-s"], timeout=2.0) if command_exists("gamemoded") else {"ok": False, "stdout": "", "stderr": "gamemoded not found", "returncode": 127}
    status_text = str(status_run.get("stdout") or status_run.get("stderr") or "")
    lowered = status_text.lower()
    global_active = False
    if "inactive" in lowered or "deactivated" in lowered:
        global_active = False
    elif "active" in lowered or "activated" in lowered:
        global_active = True
    config_candidates = [
        Path(os.environ.get("XDG_CONFIG_HOME", str(Path.home() / ".config"))) / "gamemode.ini",
        Path("/etc/gamemode.ini"),
        Path("/usr/share/gamemode/gamemode.ini"),
    ]
    configs = [gamemode_simple_config(path) for path in config_candidates]
    effective_config = next((item for item in configs if item.get("exists")), None)
    group_entry = run(["getent", "group", "gamemode"], timeout=2.0)
    user_groups = run(["id", "-nG", str(Path.home().name)], timeout=2.0)
    user_in_group = "gamemode" in str(user_groups.get("stdout") or "").split()
    return {
        "available": available,
        "commands": {
            "gamemoded": shutil.which("gamemoded"),
            "gamemoderun": shutil.which("gamemoderun"),
            "gamemode-simulate-game": shutil.which("gamemode-simulate-game"),
        },
        "service": user_systemd_unit("gamemoded.service"),
        "global_active": global_active,
        "global_status_text": status_text,
        "status_command": {
            "ok": status_run.get("ok"),
            "returncode": status_run.get("returncode"),
        },
        "group": {
            "exists": bool(group_entry.get("ok")),
            "operator_user_in_gamemode_group": user_in_group,
        },
        "config": {
            "effective": effective_config,
            "candidates": configs,
            "notes": [
                "User config takes precedence over system defaults for safe sections.",
                "GameMode activation is external; abyss-machine observes and protects routes around games.",
            ],
        },
    }


