def process_desktop_compositor(seconds: float = 3.0, interval: float = 0.5, write_latest: bool = True) -> dict[str, Any]:
    seconds = max(1.0, min(float(seconds), 90.0))
    interval = max(0.2, min(float(interval), 5.0))
    pid = process_adapters.process_gnome_shell_pid()
    command_probes = process_adapters.process_desktop_compositor_command_probes(
        seconds=seconds,
        command_exists=command_exists,
        runner=run,
    )
    atspi_windows = process_atspi_window_snapshot_bounded(timeout_sec=1.5)
    samples: list[dict[str, Any]] = []
    process_info_data = process_adapters.process_info(pid) if pid is not None else None
    if pid is not None:
        samples = process_adapters.process_gnome_shell_cpu_samples(
            pid,
            seconds=seconds,
            interval=interval,
            units=[
                NERVOUS_PASSIVE_CHRONICLE_SERVICE,
                NERVOUS_BROWSER_CONTENT_CAPTURE_SERVICE,
                NERVOUS_SEARCH_INDEX_SERVICE,
                NERVOUS_DERIVED_REFRESH_SERVICE,
            ],
            command_exists=command_exists,
            runner=run,
        )
    panel_telemetry = process_atspi_panel_telemetry_churn(seconds)

    data = process_adapters.process_desktop_compositor_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        paths=process_paths(),
        seconds=seconds,
        interval=interval,
        pid=pid,
        process_info_data=process_info_data,
        samples=samples,
        display=command_probes["display"],
        shell_bus=command_probes["shell_bus"],
        shell_signals=command_probes["shell_signals"],
        panel_telemetry=panel_telemetry,
        atspi_windows=atspi_windows,
        vitals=command_probes["vitals"],
        gnome_extensions=command_probes["gnome_extensions"],
        x11_windows=command_probes["x11_windows"],
        wayland_clients=command_probes["wayland_clients"],
        desktop_processes=command_probes["desktop_processes"],
        status_notifiers=command_probes["status_notifiers"],
        screen_cast=command_probes["screencast"],
        remote_desktop=command_probes["remote_desktop"],
    )
    if write_latest:
        latest_error = safe_atomic_write_json(PROCESS_DESKTOP_COMPOSITOR_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(PROCESS_DESKTOP_COMPOSITOR_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(PROCESS_INDEX_PATH, process_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["write_errors"] = errors
    return data


def process_desktop_compositor_bounded(seconds: float = 2.0, interval: float = 0.5, timeout_sec: float = 8.0) -> dict[str, Any]:
    seconds = max(1.0, min(float(seconds), 20.0))
    interval = max(0.2, min(float(interval), 5.0))
    timeout_sec = max(3.0, min(float(timeout_sec), 30.0))
    env = dict(os.environ)
    env["ABYSS_MACHINE_DESKTOP_COMPOSITOR_DIRECT"] = "1"
    command = [
        "abyss-machine",
        "processes",
        "desktop-compositor",
        "--seconds",
        f"{seconds:.3f}",
        "--interval",
        f"{interval:.3f}",
        "--json",
    ]
    fresh = run_command_json(command, timeout=timeout_sec, env=env)
    if fresh.get("ok"):
        fresh["_bounded_source"] = "fresh_subprocess"
        fresh["_bounded_timeout_sec"] = timeout_sec
        return fresh

    latest, latest_error = load_json_document(PROCESS_DESKTOP_COMPOSITOR_LATEST_PATH)
    data = dict(latest) if isinstance(latest, dict) else {
        "schema": f"{SCHEMA_PREFIX}_process_desktop_compositor_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "summary": {"classification": "unavailable"},
    }
    data["ok"] = bool(latest.get("ok")) if isinstance(latest, dict) else False
    data["degraded"] = True
    data["fresh_timeout"] = fresh.get("returncode") == 124
    data["fresh_error"] = fresh.get("error")
    data["fresh_returncode"] = fresh.get("returncode")
    data["fresh_command"] = fresh.get("command") or command
    data["fallback"] = {
        "source": "latest",
        "path": str(PROCESS_DESKTOP_COMPOSITOR_LATEST_PATH),
        "load_error": latest_error,
        "ok": latest.get("ok") if isinstance(latest, dict) else None,
        "generated_at": latest.get("generated_at") if isinstance(latest, dict) else None,
        "summary": latest.get("summary") if isinstance(latest, dict) else None,
    }
    data["_bounded_source"] = "latest_fallback_after_subprocess_failure"
    data["_bounded_timeout_sec"] = timeout_sec
    return data


