def resource_gate_regression_cases() -> list[dict[str, Any]]:
    policy = resource_policy_document()
    active_range_plan = {
        "thermal": {
            "class": "warm",
            "summary": {
                "sensor_temperature_c_max": 101.0,
                "package_temperature_c_max": 101.0,
                "core_temperature_c_max": 101.0,
            },
            "episode": {
                "class": "active_high_brief",
                "band": "active_high",
                "current_temperature_c": 101.0,
                "routing_guidance": "allow_work_with_observation_stable_100_105_is_expected_active_range",
            },
        },
        "recommended_new_work": {
            "medium": {
                "allowed": True,
                "unattended_allowed": True,
                "cpuset": "0-1,6-9,14-15",
                "thread_limit": 4,
            },
        },
    }
    stale_game_plan = {
        "thermal": {
            "class": "warm",
            "summary": {
                "sensor_temperature_c_max": 101.0,
                "package_temperature_c_max": 101.0,
                "core_temperature_c_max": 101.0,
            },
        },
        "recommended_new_work": {
            "medium": {
                "allowed": True,
                "unattended_allowed": False,
                "cpuset": "0-1,6-9,14-15",
                "thread_limit": 4,
                "game_guarded": True,
            },
        },
    }
    critical_plan = {
        "thermal": {
            "class": "critical",
            "summary": {
                "sensor_temperature_c_max": 109.0,
                "package_temperature_c_max": 109.0,
                "core_temperature_c_max": 109.0,
            },
        },
        "recommended_new_work": {
            "medium": {
                "allowed": True,
                "unattended_allowed": True,
                "cpuset": "14-15",
                "thread_limit": 2,
            },
        },
    }

    cases: list[dict[str, Any]] = []
    blocked, warnings = resource_thermal_plan_gate_reasons(
        active_range_plan,
        "medium",
        unattended=True,
        force=False,
        active_game=False,
        sample_thermal=True,
    )
    cases.append({
        "name": "thermal_active_range_101c_allows_medium_unattended",
        "ok": not blocked and "thermal_plan_unattended_denied" not in blocked,
        "blocked": blocked,
        "warnings": warnings,
        "expected": "100-105C active range must not block medium unattended indexing",
    })

    blocked, warnings = resource_thermal_plan_gate_reasons(
        stale_game_plan,
        "medium",
        unattended=True,
        force=False,
        active_game=False,
        sample_thermal=False,
    )
    cases.append({
        "name": "stale_unsampled_game_guarded_thermal_plan_does_not_emit_thermal_block",
        "ok": not blocked and "ignored_stale_thermal_plan_game_guard" in warnings,
        "blocked": blocked,
        "warnings": warnings,
        "expected": "inactive current game guard ignores old game_guarded thermal recommendation without a thermal block",
    })

    game_blocks = resource_game_guard_block_reasons(policy, "medium", unattended=True, active_game=True, force=False)
    blocked, warnings = resource_thermal_plan_gate_reasons(
        stale_game_plan,
        "medium",
        unattended=True,
        force=False,
        active_game=True,
        sample_thermal=False,
    )
    cases.append({
        "name": "current_active_game_still_blocks_medium_unattended_as_game_guard",
        "ok": "game_guard_unattended_medium_or_heavier" in game_blocks and not any(str(item).startswith("thermal_plan") for item in blocked),
        "blocked": game_blocks + blocked,
        "warnings": warnings,
        "expected": "current game guard remains authoritative, but is not mislabeled as a thermal block",
    })

    blocked, warnings = resource_thermal_plan_gate_reasons(
        critical_plan,
        "medium",
        unattended=True,
        force=False,
        active_game=False,
        sample_thermal=True,
    )
    cases.append({
        "name": "critical_thermal_cap_still_blocks_medium_unattended",
        "ok": "thermal_critical_unattended_cap_probe" in blocked,
        "blocked": blocked,
        "warnings": warnings,
        "expected": "critical thermal class still caps unattended work at probe",
    })
    return cases


def resource_plan(
    workload_class: str = "medium",
    kind: str = "generic",
    latency: str = "balanced",
    unattended: bool = False,
    force: bool = False,
    bytes_required: int | None = None,
    target: str | None = None,
    unit_type: str = "service",
    sample_thermal: bool | None = None,
    write_latest: bool = True,
    policy_data: dict[str, Any] | None = None,
    mode_data: dict[str, Any] | None = None,
    memory_data: dict[str, Any] | None = None,
    storage_data: dict[str, Any] | None = None,
    game_guard_data: dict[str, Any] | None = None,
    route_data: dict[str, Any] | None = None,
    thermal_plan_data: dict[str, Any] | None = None,
) -> dict[str, Any]:
    normalized_class = resource_valid_class(workload_class)
    normalized_kind = resource_valid_kind(kind)
    policy = policy_data if isinstance(policy_data, dict) else resource_policy_document()
    mode = mode_data if isinstance(mode_data, dict) else mode_plan(write_latest=True)
    memory = memory_data if isinstance(memory_data, dict) else memory_plan(write_latest=True)
    storage = storage_data if isinstance(storage_data, dict) else storage_pressure(refresh_inventory=False, write_latest=True)
    game_guard = game_guard_data if isinstance(game_guard_data, dict) else process_game_guard(write_latest=True)
    route = route_data if isinstance(route_data, dict) else ai_cpu_route(workload_class=normalized_class, latency=latency, force=force, write_latest=True)
    if sample_thermal is None:
        sample_thermal = resource_planning.should_sample_thermal(normalized_class)
    thermal_plan: dict[str, Any] | None = None
    if sample_thermal:
        thermal_policy = policy.get("gates", {}).get("thermal", {}) if isinstance(policy.get("gates"), dict) else {}
        seconds = float(thermal_policy.get("sample_seconds_for_medium_or_above", 2.0)) if isinstance(thermal_policy, dict) else 2.0
        interval = float(thermal_policy.get("sample_interval_sec", 0.5)) if isinstance(thermal_policy, dict) else 0.5
        thermal_plan = process_thermal_plan(seconds=seconds, interval=interval, top=20, write_latest=True)
    else:
        if isinstance(thermal_plan_data, dict):
            thermal_plan = thermal_plan_data
        else:
            latest, _ = load_json_document(PROCESS_THERMAL_PLAN_LATEST_PATH)
            thermal_plan = latest if isinstance(latest, dict) else None
    write_preflight = None
    if bytes_required is not None and target:
        write_preflight = storage_write_preflight(kind="artifact", bytes_required=int(bytes_required), target=str(target), write_latest=True)

    thermal_class = str(nested_get(thermal_plan, ["thermal", "class"]) or "") if isinstance(thermal_plan, dict) else ""
    data = resource_planning.build_plan(
        workload_class=workload_class,
        kind=kind,
        latency=latency,
        unattended=unattended,
        force=force,
        bytes_required=bytes_required,
        target=target,
        unit_type=unit_type,
        sample_thermal=bool(sample_thermal),
        policy=policy,
        mode=mode,
        memory=memory,
        storage=storage,
        game_guard=game_guard,
        route=route,
        thermal_plan=thermal_plan,
        write_preflight=write_preflight,
        paths=resource_paths(),
        input_latest_paths={
            "mode": str(MODE_PLAN_LATEST_PATH),
            "memory": str(MEMORY_PLAN_LATEST_PATH),
            "storage": str(STORAGE_PRESSURE_LATEST_PATH),
            "game_guard": str(PROCESS_GAME_GUARD_LATEST_PATH),
            "thermal_plan": str(PROCESS_THERMAL_PLAN_LATEST_PATH),
        },
        thermal_unattended_cap=ai_cpu_thermal_unattended_cap(thermal_class),
        total_mem_kib=meminfo().get("MemTotal"),
        environ=os.environ,
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
    )
    if write_latest:
        latest_error = safe_atomic_write_json(RESOURCE_PLAN_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(RESOURCE_PLAN_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(RESOURCE_INDEX_PATH, resource_paths(), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


