def nervous_derived_refresh_status() -> dict[str, Any]:
    passive_unit = user_systemd_unit(NERVOUS_PASSIVE_CHRONICLE_SERVICE)
    derived_unit = user_systemd_unit(NERVOUS_DERIVED_REFRESH_SERVICE)
    passive_show = systemd_unit_properties(NERVOUS_PASSIVE_CHRONICLE_SERVICE, ["OnSuccess", "FragmentPath"], user=True)
    derived_show = systemd_unit_properties(NERVOUS_DERIVED_REFRESH_SERVICE, ["LoadState", "FragmentPath", "ExecStart"], user=True)
    return nervous_quality_contracts.derived_refresh_status_document(
        passive_unit=passive_unit,
        derived_unit=derived_unit,
        passive_show=passive_show,
        derived_show=derived_show,
        passive_service=NERVOUS_PASSIVE_CHRONICLE_SERVICE,
        derived_service=NERVOUS_DERIVED_REFRESH_SERVICE,
        dropin_path=str(NERVOUS_PASSIVE_CHRONICLE_DERIVED_DROPIN_PATH),
        dropin_exists=NERVOUS_PASSIVE_CHRONICLE_DERIVED_DROPIN_PATH.exists(),
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
    )


