def nervous_config_document(path: Path, defaults: dict[str, Any]) -> dict[str, Any]:
    loaded, error = load_json_document(path)
    if loaded is None:
        doc = defaults
        if error != "missing":
            doc["_load_error"] = error
        doc["_config_exists"] = False
    else:
        doc = deep_merge(defaults, loaded)
        doc["_config_exists"] = True
    doc["_config_path"] = str(path)
    return doc


def nervous_policy(write_latest: bool = True) -> dict[str, Any]:
    data = nervous_config_document(NERVOUS_POLICY_CONFIG_PATH, default_nervous_policy())
    data["generated_at"] = now_iso()
    data["ok"] = data.get("_load_error") is None
    if write_latest:
        error = safe_atomic_write_json(NERVOUS_POLICY_LATEST_PATH, data, 0o664)
        if error:
            data["write_errors"] = [error]
    return data


