def nervous_change_id(prefix: str) -> str:
    raw = f"{prefix}:{now_iso()}:{os.getpid()}:{time.monotonic_ns()}"
    return f"{prefix}-{hashlib.sha256(raw.encode('utf-8')).hexdigest()[:16]}"


