def nervous_browser_live_content_capture(write_latest: bool = True) -> dict[str, Any]:
    accessibility = nervous_browser_accessibility_capture(write_latest=False)
    bidi: dict[str, Any] | None = None
    if nervous_tcp_open("127.0.0.1", 9222):
        bidi = nervous_browser_content_capture(write_latest=False)
    data = {
        "schema": f"{SCHEMA_PREFIX}_nervous_browser_content_capture_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(accessibility.get("ok")) or bool(bidi and bidi.get("ok")),
        "source_id": "browser_active_tab",
        "capture_source": "firefox_accessibility_tree_primary",
        "storage_root": str(NERVOUS_BROWSER_CONTENT_ROOT),
        "firefox_runtime": accessibility.get("firefox_runtime"),
        "accessibility": {
            "ok": accessibility.get("ok"),
            "skipped": accessibility.get("skipped"),
            "skip_reason": accessibility.get("skip_reason"),
            "summary": accessibility.get("summary"),
            "capture_settings": accessibility.get("capture_settings"),
            "firefox_runtime": accessibility.get("firefox_runtime"),
            "error": accessibility.get("error"),
        },
        "capture_settings": accessibility.get("capture_settings"),
        "bidi": {
            "attempted": bidi is not None,
            "ok": bidi.get("ok") if isinstance(bidi, dict) else None,
            "summary": bidi.get("summary") if isinstance(bidi, dict) else None,
            "error": bidi.get("error") if isinstance(bidi, dict) else None,
        },
        "captures": list(accessibility.get("captures") or []) + list(bidi.get("captures") if isinstance(bidi, dict) else []),
        "errors": list(accessibility.get("errors") or []) + list(bidi.get("errors") if isinstance(bidi, dict) else []),
    }
    data["summary"] = {
        "captures": len(data["captures"]),
        "errors": len(data["errors"]),
        "skipped_text": sum(1 for item in data["captures"] if nested_get(item, ["record", "skipped_text"])),
        "text_records": sum(1 for item in data["captures"] if not nested_get(item, ["record", "skipped_text"])),
        "accessibility_ok": bool(accessibility.get("ok")),
        "accessibility_skipped": bool(accessibility.get("skipped")),
        "bidi_attempted": bidi is not None,
        "bidi_ok": bool(bidi and bidi.get("ok")),
        "web_context_quality": nervous_browser_capture_web_context_summary(data["captures"]),
    }
    if accessibility.get("skipped") and not data["captures"] and bidi is None:
        data["skipped"] = True
        data["skip_reason"] = accessibility.get("skip_reason")
    if not data["ok"]:
        data["error"] = accessibility.get("error") or (bidi.get("error") if isinstance(bidi, dict) else None) or "no browser content captured"
    if write_latest:
        error = safe_atomic_write_json(NERVOUS_BROWSER_CONTENT_LATEST_PATH, data, 0o664)
        if error:
            data.setdefault("write_errors", []).append(error)
            data["ok"] = False
    return data


