def nervous_browser_recent_history_fact(sources: dict[str, Any], trigger: str = "manual") -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    source_id = "browser_active_tab"
    if not nervous_source_enabled(sources, source_id):
        return None, {"source": source_id, "reason": "disabled_by_source_policy"}
    direct_atspi = os.environ.get("ABYSS_MACHINE_NERVOUS_BROWSER_DIRECT_ATSPI") == "1"
    recurring_trigger = trigger in {"timer", "typing_nervous_refresh"}
    if recurring_trigger and not direct_atspi:
        latest_capture, latest_error = load_json_document(NERVOUS_BROWSER_CONTENT_LATEST_PATH)
        latest_data = latest_capture if isinstance(latest_capture, dict) else {}
        latest_summary = latest_data.get("summary") if isinstance(latest_data.get("summary"), dict) else {}
        latest_generated_at = latest_data.get("generated_at")
        live_capture = {
            "schema": f"{SCHEMA_PREFIX}_nervous_browser_content_capture_reuse_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": bool(isinstance(latest_capture, dict) and (latest_data.get("ok") is True or latest_data.get("skipped") is True)),
            "skipped": True,
            "skip_reason": "direct_atspi_suppressed_for_recurring_timer",
            "trigger": trigger,
            "latest": {
                "path": str(NERVOUS_BROWSER_CONTENT_LATEST_PATH),
                "exists": isinstance(latest_capture, dict),
                "error": latest_error,
                "generated_at": latest_generated_at,
                "age_sec": age_seconds_from_iso(latest_generated_at),
                "ok": latest_data.get("ok") if isinstance(latest_capture, dict) else None,
                "status": latest_data.get("status") if isinstance(latest_capture, dict) else None,
                "skipped": latest_data.get("skipped") if isinstance(latest_capture, dict) else None,
                "skip_reason": latest_data.get("skip_reason") if isinstance(latest_capture, dict) else None,
                "summary": latest_summary,
            },
            "policy": {
                "direct_atspi_client_created": False,
                "uses_persisted_browser_content_latest": True,
                "manual_direct_override_env": "ABYSS_MACHINE_NERVOUS_BROWSER_DIRECT_ATSPI=1",
            },
        }
    else:
        live_capture = nervous_browser_live_content_capture(write_latest=True)
    coverage = (
        "recent_history_plus_persisted_browser_content_for_recurring_timers"
        if recurring_trigger and not direct_atspi
        else "recent_history_plus_live_browser_content_capture"
    )
    home = Path(os.environ.get("HOME", str(PATH_POLICY.home)))
    return nervous_browser_content_adapters.browser_recent_history_fact(
        home=home,
        tmp_root=NERVOUS_BROWSER_TMP_ROOT,
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        now_iso=now_iso,
        uid=os.getuid(),
        gid=os.getgid(),
        live_capture=live_capture,
        coverage=coverage,
        content_recent_records=lambda hours, limit: nervous_browser_content_recent_records(hours=hours, limit=limit),
        read_history_rows=nervous_read_browser_history_rows,
    )


def nervous_terminal_activity_fact(sources: dict[str, Any]) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    source_id = "terminal_stdout_stderr"
    if not nervous_source_enabled(sources, source_id):
        return None, {"source": source_id, "reason": "disabled_by_source_policy"}
    home = Path(os.environ.get("HOME", str(PATH_POLICY.home)))
    history_path = home / ".zsh_history"
    commands: list[dict[str, Any]] = []
    if history_path.exists():
        try:
            lines = history_path.read_text(encoding="utf-8", errors="replace").splitlines()[-80:]
            for line in lines:
                raw = line.split(";", 1)[1] if line.startswith(": ") and ";" in line else line
                payload = nervous_text_payload(raw, max_chars=1200)
                commands.append({
                    "command": payload["text"],
                    "command_sha256": payload["text_sha256"],
                    "redaction": payload["redaction"],
                })
        except OSError:
            pass
    ps = run(["ps", "-eo", "pid=,ppid=,comm=,args="], timeout=2.0)
    processes: list[dict[str, Any]] = []
    if ps.get("ok"):
        terminal_terms = ("zsh", "bash", "fish", "gnome-terminal", "ptyxis", "kgx", "konsole", "codex", "ssh")
        for line in str(ps.get("stdout") or "").splitlines():
            if not any(term in line for term in terminal_terms):
                continue
            parts = line.strip().split(None, 3)
            if len(parts) < 3:
                continue
            args_payload = nervous_text_payload(parts[3] if len(parts) > 3 else parts[2], max_chars=1200)
            processes.append({
                "pid": parts[0],
                "ppid": parts[1],
                "comm": parts[2],
                "args": args_payload["text"],
                "args_sha256": args_payload["text_sha256"],
            })
            if len(processes) >= 40:
                break
    payload = {"commands": commands, "processes": processes, "coverage": "history_and_process_metadata_no_stdout_stderr"}
    return {
        "name": "terminal_activity",
        "source_id": source_id,
        "ok": True,
        "observed_at": now_iso(),
        "sensitivity": "local_private_redacted",
        "coverage": "history_and_process_metadata_no_stdout_stderr",
        "summary": {
            "history_commands": len(commands),
            "terminal_processes": len(processes),
            "stdout_stderr_captured": False,
        },
        "commands": commands[-40:],
        "processes": processes,
        "source": nervous_virtual_source(source_id, payload),
    }, None


