def nervous_dictation_text_from_record(record: dict[str, Any]) -> str:
    for key in ("text", "transcript", "final_text", "cleaned_text", "inserted_text"):
        value = record.get(key)
        if isinstance(value, str) and value.strip():
            return value
    for key in ("result", "payload", "dictation"):
        value = record.get(key)
        if isinstance(value, dict):
            nested = nervous_dictation_text_from_record(value)
            if nested:
                return nested
    return ""


def nervous_audio_transcript_fact(sources: dict[str, Any]) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    source_id = "audio_transcript_autolog"
    if not nervous_source_enabled(sources, source_id):
        return None, {"source": source_id, "reason": "disabled_by_source_policy"}
    today = nervous_today_path(DICTATION_TRANSCRIPT_JSONL_ROOT)
    readable = nervous_today_path(DICTATION_TRANSCRIPT_READABLE_ROOT, suffix=".md")
    records, errors = nervous_parse_jsonl_records(today) if today.exists() else ([], [])
    entries: list[dict[str, Any]] = []
    for record in records[-30:]:
        if not isinstance(record, dict):
            continue
        text = nervous_dictation_text_from_record(record)
        text_payload = nervous_text_payload(text, max_chars=3000) if text else None
        entries.append({
            "generated_at": record.get("generated_at") or record.get("created_at") or record.get("started_at"),
            "profile": record.get("profile") or record.get("model_profile"),
            "language": record.get("language"),
            "duration_sec": record.get("duration_sec") or record.get("audio_duration_sec"),
            "text": text_payload["text"] if text_payload else None,
            "text_sha256": text_payload["text_sha256"] if text_payload else None,
            "redaction": text_payload["redaction"] if text_payload else None,
        })
    payload = {
        "jsonl": str(today),
        "readable": str(readable),
        "entries": entries,
        "parse_errors": errors[:10],
    }
    return {
        "name": "audio_transcript_autolog",
        "source_id": source_id,
        "ok": today.exists(),
        "observed_at": now_iso(),
        "sensitivity": "local_private_redacted",
        "summary": {
            "jsonl_exists": today.exists(),
            "readable_exists": readable.exists(),
            "records": len(records),
            "entries_indexed": len(entries),
            "microphone_opened": False,
        },
        "jsonl_path": str(today),
        "readable_path": str(readable),
        "entries": entries,
        "parse_errors": errors[:10],
        "source": nervous_file_source(today) if today.exists() else nervous_virtual_source(source_id, payload),
    }, None


def nervous_collect_capture_facts(sources: dict[str, Any], trigger: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    facts: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []
    collectors = [
        nervous_filesystem_metadata_fact,
        nervous_git_explicit_repositories_fact,
        nervous_podman_metadata_fact,
        lambda active_sources: nervous_browser_recent_history_fact(active_sources, trigger),
        nervous_terminal_activity_fact,
        lambda active_sources: nervous_clipboard_fact(active_sources, trigger),
        lambda active_sources: nervous_screenshot_fact(active_sources, trigger),
        nervous_audio_transcript_fact,
        nervous_typed_text_fact,
    ]
    for collector in collectors:
        try:
            fact, skip = collector(sources)
        except Exception as exc:  # defensive boundary: one connector must not break the chronicle.
            fact = {
                "name": getattr(collector, "__name__", "capture_connector"),
                "source_id": "abyss_machine_facts",
                "ok": False,
                "observed_at": now_iso(),
                "sensitivity": "machine_metadata",
                "error": str(exc),
                "source": nervous_virtual_source("capture_connector_error", {"error": str(exc)}),
            }
            skip = None
        if fact is not None:
            facts.append(fact)
        if skip is not None:
            skipped.append(skip)
    return facts, skipped


def nervous_snapshot(write_latest: bool = True, trigger: str | None = None) -> dict[str, Any]:
    trigger = trigger or os.environ.get("ABYSS_NERVOUS_CAPTURE_TRIGGER") or "manual"
    if trigger not in {"manual", "timer", "test", "typing_nervous_refresh", "typing_end_to_end"}:
        trigger = "manual"
    policy = nervous_policy(write_latest=write_latest)
    sources = nervous_effective_sources(write_latest=write_latest)
    privacy = nervous_effective_privacy(write_latest=write_latest)
    global_pause = bool(privacy.get("global_pause"))
    private_mode = bool(privacy.get("private_mode"))
    facts: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []

    if global_pause:
        skipped.append({
            "source": "all",
            "reason": "global_pause",
            "global_pause": True,
            "private_mode": private_mode,
        })
    elif private_mode:
        skipped.append({
            "source": "all",
            "reason": "private_mode_minimal_heartbeat",
            "global_pause": False,
            "private_mode": True,
        })
    else:
        if nervous_source_enabled(sources, "abyss_machine_facts"):
            facts.extend([
                nervous_json_fact("storage_latest", STORAGE_LATEST_PATH),
                nervous_json_fact("storage_inventory_latest", STORAGE_INVENTORY_LATEST_PATH),
                nervous_json_fact("memory_pressure_latest", MEMORY_PRESSURE_LATEST_PATH),
                nervous_json_fact("process_latest", PROCESS_LATEST_PATH),
                nervous_observability_fact(),
                nervous_json_fact("ai_capabilities_latest", AI_CAPABILITIES_LATEST_PATH),
                nervous_json_fact("ai_workload_latest", AI_WORKLOAD_LATEST_PATH),
                nervous_json_fact("ai_policy_latest", AI_POLICY_LATEST_PATH),
                nervous_ai_llm_registry_fact(),
                nervous_ai_llm_resident_status_fact(),
                nervous_ai_llm_resident_candidates_fact(),
                nervous_dictation_status_fact(),
                nervous_ai_tts_server_status_fact(),
            ])
        else:
            skipped.append({"source": "abyss_machine_facts", "reason": "disabled_by_source_policy"})

        if nervous_source_enabled(sources, "systemd_metadata"):
            facts.extend(nervous_systemd_facts())
        else:
            skipped.append({"source": "systemd_metadata", "reason": "disabled_by_source_policy"})

        if nervous_source_enabled(sources, "manual_notes"):
            skipped.append({"source": "manual_notes", "reason": "operator-provided-only"})

        capture_facts, capture_skipped = nervous_collect_capture_facts(sources, trigger)
        facts.extend(capture_facts)
        skipped.extend(capture_skipped)

    capture_sources = sorted({
        str(fact.get("source_id") or nervous_fact_source_id(fact))
        for fact in facts
        if isinstance(fact, dict)
    } | {
        str(item.get("source"))
        for item in skipped
        if isinstance(item, dict) and item.get("source") and item.get("reason") == "operator-provided-only"
    })

    data = {
        "schema": f"{SCHEMA_PREFIX}_nervous_fact_snapshot_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "phase": "stage-9-passive-local-capture",
        "capture": {
            "trigger": trigger,
            "manual": trigger == "manual",
            "timer": trigger in {"timer", "typing_nervous_refresh"},
            "test": trigger == "test",
            "typing_nervous_refresh": trigger == "typing_nervous_refresh",
            "daemon": False,
            "facts_only": True,
            "raw_private_content": False,
            "private_artifacts_local_only": True,
            "redaction_before_index": True,
            "blocked": global_pause,
            "heartbeat": global_pause or private_mode,
            "sources": capture_sources,
        },
        "policy": {
            "mode": policy.get("mode"),
            "active_daemon": bool(policy.get("active_daemon")),
            "activation": policy.get("activation", {}),
        },
        "privacy": {
            "mode": privacy.get("mode"),
            "global_pause": global_pause,
            "private_mode": private_mode,
            "state": privacy.get("state", {}),
        },
        "summary": {
            "facts": len(facts),
            "facts_ok": sum(1 for item in facts if item.get("ok", True)),
            "facts_missing_or_failed": sum(1 for item in facts if item.get("ok") is False),
            "skipped": len(skipped),
        },
        "facts": facts,
        "skipped": skipped,
        "non_claims": [
            "This command is a passive snapshot, not a watcher daemon.",
            "Terminal capture records shell history/process metadata only; it does not capture existing stdout/stderr streams.",
            "Browser facts use recent local history metadata and persisted browser-content captures; direct AT-SPI browser capture is limited to manual or specialized capture routes.",
            "Screenshot pixels are local private artifacts under /srv; the index stores only metadata/path/hash.",
            "Typed-text capture consumes explicit committed-text journal events only; it does not install a raw keylogger or capture password fields.",
            "This command does not start a watcher or service.",
        ],
    }
    if write_latest:
        if global_pause:
            audit = nervous_privacy_audit({
                "event": "snapshot_suppressed",
                "trigger": trigger,
                "reason": "global_pause",
                "private_mode": private_mode,
            })
            data["audit"] = audit
            fact_error = None
            latest_error = None
            index_error = None
        else:
            fact_error = safe_append_jsonl(nervous_today_path(NERVOUS_FACTS_ROOT), data, 0o664)
            latest_error = safe_atomic_write_json(NERVOUS_FACTS_LATEST_PATH, data, 0o664)
            index_error = safe_atomic_write_json(NERVOUS_INDEX_PATH, nervous_index_document(data), 0o664)
            capture_error = safe_atomic_write_json(NERVOUS_CAPTURE_LATEST_PATH, {
                "schema": f"{SCHEMA_PREFIX}_nervous_capture_latest_v1",
                "version": VERSION,
                "generated_at": data["generated_at"],
                "ok": data["ok"],
                "snapshot": str(NERVOUS_FACTS_LATEST_PATH),
                "sources": capture_sources,
                "summary": data["summary"],
                "private_artifact_root": str(NERVOUS_PRIVATE_CAPTURE_ROOT),
                "screenshots": [
                    fact.get("artifact", {}).get("path")
                    for fact in facts
                    if (
                        isinstance(fact, dict)
                        and fact.get("name") == "screenshot"
                        and fact.get("ok") is True
                        and isinstance(fact.get("artifact"), dict)
                        and fact.get("artifact", {}).get("exists") is True
                    )
                ],
            }, 0o664)
        errors = [error for error in (fact_error, latest_error, index_error, locals().get("capture_error")) if error]
        if errors:
            data["write_errors"] = errors
    return data


def nervous_validate_snapshot(path: Path = NERVOUS_FACTS_LATEST_PATH) -> dict[str, Any]:
    data, error = load_json_document(path)
    checks: list[dict[str, Any]] = []

    def add(level: str, key: str, message: str, details: dict[str, Any] | None = None) -> None:
        item: dict[str, Any] = {"level": level, "key": key, "message": message}
        if details is not None:
            item["details"] = details
        checks.append(item)

    if data is None:
        return {
            "schema": f"{SCHEMA_PREFIX}_nervous_validate_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "path": str(path),
            "error": error or "missing",
            "checks": [{
                "level": "fail",
                "key": "snapshot_load",
                "message": "latest passive snapshot is missing or invalid",
            }],
            "summary": {"fails": 1, "warnings": 0, "checks": 1},
        }

    schema = data.get("schema")
    add(
        "ok" if schema == f"{SCHEMA_PREFIX}_nervous_fact_snapshot_v1" else "fail",
        "schema",
        f"snapshot schema {schema}",
    )
    capture = data.get("capture") if isinstance(data.get("capture"), dict) else {}
    add("ok" if capture.get("facts_only") is True else "fail", "facts_only", "snapshot is facts-only")
    add("ok" if capture.get("raw_private_content") is False else "fail", "raw_private_content", "raw private content disabled")
    add("ok" if capture.get("daemon") is False else "fail", "daemon", "snapshot was not captured by a daemon")

    used_sources = set(capture.get("sources", [])) if isinstance(capture.get("sources"), list) else set()
    sources = nervous_effective_sources(write_latest=False)
    allowed_sources = nervous_allowed_source_ids(sources)
    disallowed_used = sorted(used_sources - allowed_sources)
    private_used = sorted(used_sources & nervous_deferred_source_ids(sources))
    add(
        "ok" if not disallowed_used else "fail",
        "source_policy",
        "all captured sources are enabled and allowed by policy",
        {"disallowed_used": disallowed_used, "private_used": private_used},
    )
    add(
        "ok" if capture.get("private_artifacts_local_only") is True or not private_used else "warn",
        "private_artifacts_local_only",
        "private connector artifacts are local-only and excluded from indexed raw content",
        {"private_used": private_used, "artifact_root": str(NERVOUS_PRIVATE_CAPTURE_ROOT)},
    )

    facts = data.get("facts")
    if not isinstance(facts, list):
        add("fail", "facts_list", "facts must be a list")
        facts = []
    summary = data.get("summary") if isinstance(data.get("summary"), dict) else {}
    add(
        "ok" if int(summary.get("facts") or -1) == len(facts) else "fail",
        "summary_count",
        "summary fact count matches fact list",
        {"summary_facts": summary.get("facts"), "actual_facts": len(facts)},
    )

    provenance_missing = []
    source_hash_warnings = []
    for idx, fact in enumerate(facts):
        if not isinstance(fact, dict):
            provenance_missing.append({"index": idx, "reason": "fact_not_object"})
            continue
        if fact.get("name") == "systemd_unit":
            if not fact.get("scope") or not fact.get("observed_at") or not isinstance(fact.get("state"), dict):
                provenance_missing.append({"index": idx, "name": fact.get("name"), "reason": "systemd_provenance_incomplete"})
            continue
        if str(fact.get("sensitivity") or "").startswith("raw_private"):
            provenance_missing.append({"index": idx, "name": fact.get("name"), "reason": "raw_private_sensitivity_forbidden"})
            continue
        source = fact.get("source")
        if not isinstance(source, dict) or not source.get("path") or "sha256" not in source:
            provenance_missing.append({"index": idx, "name": fact.get("name"), "reason": "file_source_provenance_incomplete"})
            continue
        if source.get("sha256"):
            current = nervous_file_source(Path(str(source["path"])))
            if current.get("sha256") and current.get("sha256") != source.get("sha256"):
                source_hash_warnings.append({
                    "index": idx,
                    "name": fact.get("name"),
                    "path": source.get("path"),
                    "recorded_sha256": source.get("sha256"),
                    "current_sha256": current.get("sha256"),
                })
    add(
        "ok" if not provenance_missing else "fail",
        "provenance",
        "every fact has enough provenance for audit",
        {"missing": provenance_missing[:20], "missing_count": len(provenance_missing)},
    )
    add(
        "ok",
        "source_hash_provenance",
        "recorded source hashes are present; current source drift is informational",
        {"current_drift": source_hash_warnings[:20], "current_drift_count": len(source_hash_warnings)},
    )

    fails = sum(1 for item in checks if item["level"] == "fail")
    warnings = sum(1 for item in checks if item["level"] == "warn")
    return {
        "schema": f"{SCHEMA_PREFIX}_nervous_validate_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": fails == 0,
        "path": str(path),
        "snapshot_generated_at": data.get("generated_at"),
        "checks": checks,
        "summary": {
            "fails": fails,
            "warnings": warnings,
            "checks": len(checks),
            "facts": len(facts),
        },
    }


