def nervous_semantic_status(write_latest: bool = True) -> dict[str, Any]:
    semantic = nervous_semantic_config()
    embedding = semantic.get("embedding") if isinstance(semantic.get("embedding"), dict) else {}
    model_dir = Path(str(embedding.get("model_dir") or ""))
    counts = nervous_semantic_counts()
    source_counts = nervous_index_db_counts()
    semantic_meta = counts.get("meta") if isinstance(counts.get("meta"), dict) else {}
    cache_dir = Path(str(semantic_meta.get("cache_dir") or ai_openvino_cache_path(ai_model_cache_label(model_dir, "semantic-embedding"))))
    data = build_nervous_semantic_status(
        semantic=semantic,
        counts=counts,
        source_counts=source_counts,
        model_dir=str(model_dir),
        model_exists=model_dir.exists(),
        cache_dir=str(cache_dir),
        cache_exists=cache_dir.exists(),
        source_index_db_exists=NERVOUS_SEARCH_INDEX_DB_PATH.exists(),
        semantic_index_db_exists=NERVOUS_SEMANTIC_INDEX_DB_PATH.exists(),
        paths={
            "db": str(NERVOUS_SEMANTIC_INDEX_DB_PATH),
            "root": str(NERVOUS_SEMANTIC_INDEX_ROOT),
            "latest": str(NERVOUS_SEMANTIC_INDEX_LATEST_PATH),
            "source_index_db": str(NERVOUS_SEARCH_INDEX_DB_PATH),
        },
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
    )
    if write_latest:
        return nervous_semantic_write_latest(data)
    return data


