def nervous_latest_record_from_history(root: Path) -> dict[str, Any] | None:
    latest_record: dict[str, Any] | None = None
    latest_time: dt.datetime | None = None
    for path in nervous_jsonl_files(root):
        records, _errors = nervous_parse_jsonl_records(path)
        for record in records:
            record_time = parse_time(record.get("observed_at") or record.get("start_at") or record.get("generated_at"))
            if record_time is None:
                continue
            if latest_time is None or record_time > latest_time:
                latest_time = record_time
                latest_record = record
    return latest_record


def nervous_latest_fact_from_history() -> dict[str, Any] | None:
    return nervous_latest_record_from_history(NERVOUS_FACTS_ROOT)


def nervous_rebuild_fact_latest() -> dict[str, Any]:
    latest = nervous_latest_fact_from_history()
    if latest is None:
        empty = {
            "schema": f"{SCHEMA_PREFIX}_nervous_fact_snapshot_empty_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": True,
            "empty": True,
            "reason": "no remaining fact snapshots",
        }
        error = safe_atomic_write_json(NERVOUS_FACTS_LATEST_PATH, empty, 0o664)
        if error:
            empty["write_errors"] = [error]
            empty["ok"] = False
        return empty
    error = safe_atomic_write_json(NERVOUS_FACTS_LATEST_PATH, latest, 0o664)
    if error:
        latest = dict(latest)
        latest["write_errors"] = [error]
        latest["ok"] = False
    return latest


def nervous_forget(minutes: float, dry_run: bool = False, reason: str | None = None) -> dict[str, Any]:
    minutes = max(0.1, min(float(minutes), 24 * 60.0))
    cutoff = dt.datetime.now(dt.timezone.utc).astimezone() - dt.timedelta(minutes=minutes)
    files: list[dict[str, Any]] = []
    artifact_files: list[dict[str, Any]] = []
    removed_total = 0
    kept_total = 0
    artifact_removed_total = 0
    parse_errors: list[dict[str, Any]] = []
    for path in nervous_fact_jsonl_files():
        records, errors = nervous_parse_jsonl_records(path)
        parse_errors.extend(errors)
        kept: list[dict[str, Any]] = []
        removed: list[dict[str, Any]] = []
        for record in records:
            record_time = parse_time(record.get("generated_at"))
            if record_time is not None and record_time >= cutoff:
                removed.append(record)
            else:
                kept.append(record)
        removed_total += len(removed)
        kept_total += len(kept)
        file_report = {
            "path": str(path),
            "records_before": len(records),
            "records_removed": len(removed),
            "records_kept": len(kept),
        }
        if removed and not dry_run:
            try:
                with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=str(path.parent), prefix=f".{path.name}.", delete=False) as tmp:
                    for record in kept:
                        json.dump(record, tmp, sort_keys=False)
                        tmp.write("\n")
                    tmp_name = tmp.name
                os.chmod(tmp_name, 0o664)
                try:
                    os.chown(tmp_name, -1, grp.getgrnam(MODE_STATE_GROUP).gr_gid)
                except (KeyError, PermissionError):
                    pass
                os.replace(tmp_name, path)
                file_report["rewritten"] = True
            except OSError as exc:
                file_report["rewrite_error"] = str(exc)
        files.append(file_report)
    if NERVOUS_PRIVATE_CAPTURE_ROOT.exists():
        for path in sorted(item for item in NERVOUS_PRIVATE_CAPTURE_ROOT.rglob("*") if item.is_file()):
            mtime = nervous_file_record_time(path)
            if mtime is None or mtime < cutoff:
                continue
            artifact_report = {
                "path": str(path),
                "mtime": mtime.isoformat(timespec="seconds"),
                "size_bytes": path.stat().st_size if path.exists() else None,
                "removed": False,
            }
            if not dry_run:
                try:
                    path.unlink()
                    artifact_report["removed"] = True
                    artifact_removed_total += 1
                except OSError as exc:
                    artifact_report["remove_error"] = str(exc)
            artifact_files.append(artifact_report)
    latest = None if dry_run else nervous_rebuild_fact_latest()
    derived_rebuild = None
    index_rebuild = None
    if not dry_run:
        events_rebuild = nervous_events_build(write_latest=True)
        episodes_rebuild = nervous_episodes_build(write_latest=True, refresh_events=False)
        index_rebuild = nervous_index_build(write_latest=True, refresh_derived=False)
        derived_rebuild = {
            "events": {
                "ok": events_rebuild.get("ok"),
                "events": nested_get(events_rebuild, ["summary", "events"]),
                "error": events_rebuild.get("error"),
            },
            "episodes": {
                "ok": episodes_rebuild.get("ok"),
                "episodes": nested_get(episodes_rebuild, ["summary", "episodes"]),
                "error": episodes_rebuild.get("error"),
            },
        }
    audit = nervous_privacy_audit({
        "event": "forget_window",
        "change_id": nervous_change_id("forget"),
        "minutes": minutes,
        "cutoff": cutoff.isoformat(timespec="seconds"),
        "dry_run": dry_run,
        "records_removed": removed_total,
        "records_kept": kept_total,
        "artifact_files_removed": artifact_removed_total,
        "reason": reason,
    }, write=not dry_run)
    return {
        "schema": f"{SCHEMA_PREFIX}_nervous_forget_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": not any(item.get("rewrite_error") for item in files) and not parse_errors,
        "dry_run": dry_run,
        "minutes": minutes,
        "cutoff": cutoff.isoformat(timespec="seconds"),
        "summary": {
            "files": len(files),
            "records_removed": removed_total,
            "records_kept": kept_total,
            "artifact_files_seen": len(artifact_files),
            "artifact_files_removed": artifact_removed_total,
            "parse_errors": len(parse_errors),
        },
        "files": files,
        "artifact_files": artifact_files[:200],
        "parse_errors": parse_errors[:20],
        "latest": {
            "path": str(NERVOUS_FACTS_LATEST_PATH),
            "schema": latest.get("schema") if isinstance(latest, dict) else None,
            "generated_at": latest.get("generated_at") if isinstance(latest, dict) else None,
        } if not dry_run else None,
        "derived_rebuild": derived_rebuild,
        "index_rebuild": {
            "ok": index_rebuild.get("ok"),
            "records_indexed": nested_get(index_rebuild, ["summary", "records_indexed"]),
            "chunks_indexed": nested_get(index_rebuild, ["summary", "chunks_indexed"]),
            "error": index_rebuild.get("error"),
        } if isinstance(index_rebuild, dict) else None,
        "audit": audit,
    }


def nervous_redaction_patterns() -> list[dict[str, Any]]:
    return nervous_redaction.redaction_patterns()


def nervous_token_entropy(token: str) -> float:
    return nervous_redaction.token_entropy(token)


def nervous_high_entropy_token_candidates(text: str) -> list[dict[str, Any]]:
    return nervous_redaction.high_entropy_token_candidates(text)


def nervous_redact_text(text: str) -> dict[str, Any]:
    return nervous_redaction.redact_text(
        text,
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
    )


def nervous_redact_file(path: Path, dry_run: bool = True, max_bytes: int = 1_000_000) -> dict[str, Any]:
    expanded = path.expanduser()
    if not dry_run:
        return {
            "schema": f"{SCHEMA_PREFIX}_nervous_redact_file_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": "redact-file only supports --dry-run at this stage",
            "path": str(expanded),
        }
    source = nervous_file_source(expanded)
    try:
        stat = expanded.stat()
    except OSError as exc:
        return {
            "schema": f"{SCHEMA_PREFIX}_nervous_redact_file_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "path": str(expanded),
            "source": source,
            "error": str(exc),
        }
    if stat.st_size > max_bytes:
        return {
            "schema": f"{SCHEMA_PREFIX}_nervous_redact_file_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "path": str(expanded),
            "source": source,
            "error": f"file too large for dry-run redaction limit {max_bytes} bytes",
        }
    try:
        text = expanded.read_text(encoding="utf-8", errors="replace")
    except OSError as exc:
        return {
            "schema": f"{SCHEMA_PREFIX}_nervous_redact_file_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "path": str(expanded),
            "source": source,
            "error": str(exc),
        }
    result = nervous_redact_text(text)
    return {
        "schema": f"{SCHEMA_PREFIX}_nervous_redact_file_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "dry_run": True,
        "path": str(expanded),
        "source": source,
        "summary": result.get("summary", {}),
        "matches": result.get("matches", []),
        "redacted_text_omitted": True,
    }


def typing_today_path(root: Path, suffix: str = ".jsonl") -> Path:
    return nervous_today_path(root, suffix=suffix)


def typing_paths_contract_snapshot() -> dict[str, Any]:
    constants = TYPING_NERVOUS_POLICY.as_cli_constants()
    return {
        key: globals().get(key, value)
        for key, value in constants.items()
        if key.startswith("TYPING_")
    }


def typing_paths(generated_at: str | None = None) -> dict[str, Any]:
    return build_typing_paths_document(
        typing_paths_contract_snapshot(),
        generated_at=generated_at or now_iso(),
        events_today_path=typing_today_path(TYPING_EVENTS_ROOT),
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
    )

