def typing_codex_prompt_hook_ingest_event(event: dict[str, Any], write_latest: bool = True) -> dict[str, Any]:
    plan = typing_codex_semantics.prompt_hook_ingest_plan(event)
    prompt = str(plan.get("prompt") or "")
    session_id = str(plan.get("session_id") or "")
    turn_id = str(plan.get("turn_id") or "")
    cwd = str(plan.get("cwd") or "")
    data = {
        "schema": f"{SCHEMA_PREFIX}_typing_codex_prompt_hook_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "status": "skipped_no_prompt",
        "adapter": "codex_user_prompt_submit",
        "hook_event_name": str(event.get("hook_event_name") or "UserPromptSubmit"),
        "session_id": session_id or None,
        "turn_id": turn_id or None,
        "cwd": cwd or None,
        "typing_event": None,
        "policy": {
            "raw_keylogging": False,
            "native_codex_submit_hook": True,
            "session_postprocessing": False,
            "hook_fail_open": True,
        },
    }
    if not prompt:
        return data
    metadata = plan.get("metadata") if isinstance(plan.get("metadata"), dict) else {}
    event_data = typing_ingest(
        prompt,
        source=str(plan.get("source") or "codex_user_prompt_submit"),
        app=str(plan.get("app") or "codex"),
        window_title=str(plan.get("window_title") or (f"codex:{session_id[:8]}" if session_id else "codex")),
        context=str(plan.get("context") or ""),
        write_latest=write_latest,
        skip_duplicate=True,
        metadata=metadata,
    )
    data["ok"] = bool(event_data.get("ok"))
    data["status"] = "ingested" if event_data.get("ok") else "ingest_failed"
    data["typing_event"] = typing_codex_semantics.typing_event_brief(event_data)
    return data


def typing_codex_prompt_hook(raw: str, write_latest: bool = True) -> dict[str, Any]:
    try:
        parsed = json.loads(raw) if str(raw or "").strip() else {}
    except json.JSONDecodeError as exc:
        data = {
            "schema": f"{SCHEMA_PREFIX}_typing_codex_prompt_hook_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "status": "invalid_json",
            "error": str(exc),
            "adapter": "codex_user_prompt_submit",
            "policy": {
                "raw_keylogging": False,
                "native_codex_submit_hook": True,
                "hook_fail_open": True,
            },
        }
    else:
        data = typing_codex_prompt_hook_ingest_event(parsed if isinstance(parsed, dict) else {"payload": parsed}, write_latest=write_latest)
    if write_latest:
        errors = write_latest_and_history(data, TYPING_CODEX_HOOK_EVENTS_LATEST_PATH, TYPING_CODEX_HOOK_EVENTS_ROOT)
        index_error = safe_atomic_write_json(TYPING_INDEX_PATH, typing_index_document(), 0o664)
        errors = errors + ([index_error] if index_error else [])
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def typing_codex_hook_find_probe_event(text_sha256: str, limit: int = 120) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
    records, errors = typing_records(limit)
    for record in records:
        if not isinstance(record, dict):
            continue
        text_payload = record.get("text") if isinstance(record.get("text"), dict) else {}
        if record.get("source_adapter") == "codex_user_prompt_submit" and text_payload.get("text_sha256") == text_sha256:
            return {
                "event_id": record.get("event_id"),
                "status": record.get("status"),
                "source_adapter": record.get("source_adapter"),
                "capture_gate_decision": nested_get(record, ["capture_gate", "decision"]),
            }, errors
    return None, errors


def typing_codex_prompt_hook_selftest(write_latest: bool = True) -> dict[str, Any]:
    status_before = typing_codex_prompt_hook_status(write_latest=False)
    probe_text = "abyss codex prompt hook selftest"
    probe_hash = hashlib.sha256(probe_text.encode("utf-8", errors="replace")).hexdigest()
    event = {
        "session_id": "codex-hook-selftest",
        "turn_id": "codex-hook-selftest-turn",
        "transcript_path": str(Path.home() / ".codex/sessions/selftest.jsonl"),
        "cwd": str(Path.home()),
        "hook_event_name": "UserPromptSubmit",
        "model": "selftest",
        "permission_mode": "selftest",
        "prompt": probe_text,
    }
    hook_result = typing_codex_prompt_hook(json.dumps(event, ensure_ascii=False), write_latest=True)
    found_event, parse_errors = typing_codex_hook_find_probe_event(probe_hash)
    data = {
        "schema": f"{SCHEMA_PREFIX}_typing_codex_prompt_hook_selftest_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(status_before.get("ok") and hook_result.get("ok") and found_event),
        "status": "passed" if status_before.get("ok") and hook_result.get("ok") and found_event else "failed",
        "probe": {
            "text_sha256": probe_hash,
            "text_length": len(probe_text),
        },
        "summary": {
            "hook_ready_before": bool(status_before.get("ok")),
            "hook_invoked": bool(hook_result.get("ok")),
            "event_detected": bool(found_event),
            "parse_errors": len(parse_errors),
        },
        "hook_status": status_before,
        "hook_result": hook_result,
        "event": found_event,
        "parse_errors": parse_errors[:20],
        "policy": {
            "raw_keylogging": False,
            "native_codex_submit_hook": True,
            "session_postprocessing": False,
            "password_fields_captured": False,
        },
    }
    if write_latest:
        errors = write_latest_and_history(data, TYPING_CODEX_HOOK_SELFTEST_LATEST_PATH, TYPING_CODEX_HOOK_SELFTEST_ROOT)
        status_after = typing_codex_prompt_hook_status(write_latest=True)
        index_error = safe_atomic_write_json(TYPING_INDEX_PATH, typing_index_document(), 0o664)
        errors = errors + ([index_error] if index_error else [])
        data["status_after"] = status_after
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


