def typing_codex_session_tail(
    write_latest: bool = True,
    files_limit: int = 4,
    initial_tail_lines: int = 12000,
    recovery_tail_lines: int = 12000,
    prime_state: bool = False,
) -> dict[str, Any]:
    generated_at = now_iso()
    state, state_error = load_json_document(TYPING_CODEX_SESSION_TAIL_STATE_PATH)
    if not isinstance(state, dict):
        state = {"schema": f"{SCHEMA_PREFIX}_typing_codex_session_tail_state_v1", "version": VERSION, "files": {}}
    route_version = str(state.get("user_message_routes_version") or "")
    response_item_route_migration = route_version != "v2_response_item_user"
    files_state = state.get("files") if isinstance(state.get("files"), dict) else {}
    files = typing_codex_session_tail_files(files_limit, state=state)
    events: list[dict[str, Any]] = []
    parse_errors: list[dict[str, Any]] = []
    file_reports: list[dict[str, Any]] = []
    for path in files:
        path_text = str(path)
        previous = files_state.get(path_text) if isinstance(files_state.get(path_text), dict) else {}
        since_line = safe_int(previous.get("line_count"), 0)
        recovery_scan = bool(
            since_line > 0
            and (
                not previous.get("last_user_line")
                or response_item_route_migration
            )
        )
        candidate_lines, read_report, read_errors = typing_nervous_adapters.codex_session_tail_path_candidates(
            path,
            previous,
            initial_tail_lines=initial_tail_lines,
            recovery_tail_lines=recovery_tail_lines,
            recovery_scan=recovery_scan,
        )
        parse_errors.extend(read_errors)
        if read_report.get("scan_mode") == "stat_failed":
            file_reports.append({
                "path": path_text,
                "line_count": since_line,
                "since_line": since_line,
                "scan_mode": "stat_failed",
                "candidate_lines": 0,
                "user_candidates": 0,
                "ingested": 0,
                "primed": prime_state,
                "error": str(read_report.get("error") or "stat failed"),
            })
            continue
        line_count = safe_int(read_report.get("line_count"), since_line)
        file_size = safe_int(read_report.get("file_size"), 0)
        mtime_ns = safe_int(read_report.get("mtime_ns"), 0)
        byte_offset = safe_int(read_report.get("byte_offset"), file_size)
        scan_mode = str(read_report.get("scan_mode") or "unknown")
        session_id = typing_codex_session_id_from_path(path)
        current_turn: dict[str, Any] = {}
        user_candidates = 0
        raw_user_candidates = 0
        normalized_skipped = 0
        raw_route_duplicates_skipped = 0
        ingested = 0
        seen_prompt_lines: dict[str, int] = {}
        last_user_line = safe_int(previous.get("last_user_line"), 0)
        last_user_timestamp = str(previous.get("last_user_timestamp") or "")
        for line_no, line in candidate_lines:
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                parse_errors.append({"path": path_text, "line": line_no, "error": str(exc)[:240]})
                continue
            if not isinstance(record, dict):
                continue
            if record.get("type") == "turn_context" and isinstance(record.get("payload"), dict):
                current_turn = record.get("payload") or {}
                continue
            user_messages = typing_codex_session_tail_user_messages(record)
            if not user_messages:
                continue
            for user_message in user_messages:
                raw_user_candidates += 1
                timestamp = str(record.get("timestamp") or "")
                last_user_line = max(last_user_line, line_no)
                last_user_timestamp = timestamp or last_user_timestamp
                normalized = typing_codex_user_message_normalize(str(user_message.get("raw_text") or ""))
                text = str(normalized.get("text") or "")
                if not text.strip():
                    normalized_skipped += 1
                    continue
                user_candidates += 1
                dedupe_key = typing_codex_semantics.session_tail_dedupe_key(session_id, text)
                if typing_codex_semantics.session_tail_should_skip_duplicate(seen_prompt_lines, dedupe_key, line_no):
                    raw_route_duplicates_skipped += 1
                    continue
                plan = typing_codex_semantics.session_tail_ingest_plan(
                    session_id=session_id,
                    transcript_path=path_text,
                    line_no=line_no,
                    timestamp=timestamp,
                    turn_context=current_turn,
                    user_message=user_message,
                    normalized_message=normalized,
                )
                metadata = plan.get("metadata") if isinstance(plan.get("metadata"), dict) else {}
                event_data = typing_ingest(
                    str(plan.get("text") or ""),
                    source=str(plan.get("source") or "codex_session_jsonl_prompt_tail"),
                    app=str(plan.get("app") or "codex"),
                    window_title=str(plan.get("window_title") or f"codex-session:{session_id[:8]}"),
                    context=str(plan.get("context") or ""),
                    write_latest=write_latest and not prime_state,
                    skip_duplicate=True,
                    metadata=metadata,
                )
                ingested += 1 if event_data.get("ok") else 0
                events.append(typing_codex_semantics.session_tail_event_summary(plan, event_data))
        file_reports.append({
            "path": path_text,
            "line_count": line_count,
            "since_line": since_line,
            "scan_mode": scan_mode,
            "file_size": file_size,
            "byte_offset": byte_offset,
            "candidate_lines": len(candidate_lines),
            "raw_user_candidates": raw_user_candidates,
            "user_candidates": user_candidates,
            "normalized_skipped": normalized_skipped,
            "raw_route_duplicates_skipped": raw_route_duplicates_skipped,
            "ingested": ingested,
            "primed": prime_state,
            "last_user_line": last_user_line or None,
            "last_user_timestamp": last_user_timestamp or None,
        })
        files_state[path_text] = {
            "line_count": line_count,
            "updated_at": generated_at,
            "session_id": session_id,
            "file_size": file_size,
            "mtime_ns": mtime_ns,
            "byte_offset": byte_offset,
            "last_user_line": last_user_line or None,
            "last_user_timestamp": last_user_timestamp or None,
        }
    state["schema"] = f"{SCHEMA_PREFIX}_typing_codex_session_tail_state_v1"
    state["version"] = VERSION
    state["updated_at"] = generated_at
    state["user_message_routes_version"] = "v2_response_item_user"
    state["files"] = files_state
    data = {
        "schema": f"{SCHEMA_PREFIX}_typing_codex_session_tail_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": not parse_errors,
        "status": "primed" if prime_state else ("processed" if files else "missing_sessions_root"),
        "adapter": "codex_session_jsonl_prompt_tail",
        "sessions_root": str(TYPING_CODEX_SESSIONS_ROOT),
        "summary": {
            "files": len(files),
            "requested_files_limit": max(1, min(int(files_limit or 1), 16)),
            "selection_includes_recent_state_files": len(files) > max(1, min(int(files_limit or 1), 16)),
            "events": len(events),
            "captured": sum(1 for item in events if item.get("status") == "captured"),
            "metadata_only": sum(1 for item in events if item.get("status") == "metadata_only"),
            "duplicate_skipped": sum(1 for item in events if item.get("status") == "duplicate_skipped"),
            "raw_user_candidates": sum(safe_int(item.get("raw_user_candidates"), 0) for item in file_reports),
            "normalized_skipped": sum(safe_int(item.get("normalized_skipped"), 0) for item in file_reports),
            "raw_route_duplicates_skipped": sum(safe_int(item.get("raw_route_duplicates_skipped"), 0) for item in file_reports),
            "response_item_route_migration": response_item_route_migration,
            "parse_errors": len(parse_errors),
            "prime_state": prime_state,
        },
        "files": file_reports,
        "events": events[:60],
        "parse_errors": parse_errors[:40],
        "policy": {
            "raw_keylogging": False,
            "native_codex_submit_hook": False,
            "session_jsonl_tail_fallback": True,
            "raw_record_routes": ["event_msg.user_message", "response_item.message.role_user"],
            "committed_user_messages_only": True,
            "normalizes_codex_context_envelopes": True,
            "password_fields_captured": False,
            "capture_gate_required": True,
            "session_postprocessing": False,
        },
        "non_claims": [
            "This fallback reads Codex raw JSONL committed user message records, not draft keystrokes.",
            "Native UserPromptSubmit remains the preferred immediate adapter; this route is near-live fallback evidence.",
        ],
    }
    if write_latest:
        errors = write_latest_and_history(data, TYPING_CODEX_SESSION_TAIL_LATEST_PATH, TYPING_CODEX_SESSION_TAIL_ROOT)
        state_error_write = safe_atomic_write_json(TYPING_CODEX_SESSION_TAIL_STATE_PATH, state, 0o664)
        index_error = safe_atomic_write_json(TYPING_INDEX_PATH, typing_index_document(), 0o664)
        errors = errors + ([state_error_write] if state_error_write else []) + ([index_error] if index_error else [])
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    if state_error:
        data["state_load_error"] = state_error
    return data


