def typing_terminate_processes_with_arg_token(token: str) -> list[dict[str, Any]]:
    token_text = str(token or "")
    if not token_text:
        return []
    current_pid = os.getpid()
    actions: list[dict[str, Any]] = []

    def matching_pids() -> list[int]:
        raw = run(["ps", "-eo", "pid=,args="], timeout=3.0)
        pids: list[int] = []
        if not raw.get("ok"):
            actions.append({"phase": "scan", "ok": False, "error": str(raw.get("stderr") or raw.get("error") or "")[:240]})
            return pids
        for line in str(raw.get("stdout") or "").splitlines():
            stripped = line.strip()
            if not stripped or token_text not in stripped:
                continue
            parts = stripped.split(None, 1)
            if not parts:
                continue
            try:
                pid = int(parts[0])
            except ValueError:
                continue
            if pid == current_pid:
                continue
            pids.append(pid)
        return sorted(set(pids))

    for sig, phase, delay in ((signal.SIGTERM, "term", 1.0), (signal.SIGKILL, "kill", 0.0)):
        pids = matching_pids()
        if not pids:
            break
        for pid in pids:
            try:
                os.kill(pid, sig)
                actions.append({"phase": phase, "pid": pid, "ok": True})
            except ProcessLookupError:
                actions.append({"phase": phase, "pid": pid, "ok": True, "note": "already_exited"})
            except Exception as exc:
                actions.append({"phase": phase, "pid": pid, "ok": False, "error": repr(exc)[:240]})
        if delay:
            time.sleep(delay)
    remaining = matching_pids()
    if remaining:
        actions.append({"phase": "remaining", "pids": remaining[:20], "ok": False})
    return actions


