def typing_context_text(source: str, app: str | None, window_title: str | None, context: str | None, text: str, include_text: bool = True) -> str:
    return "\n".join(
        part for part in (
            str(source or ""),
            str(app or ""),
            str(window_title or ""),
            str(context or ""),
            str(text or "")[:600] if include_text else "",
        )
        if part
    )


