def typing_causal_active_changes(surface_paths: list[str], policy: dict[str, Any], allow_contextual: bool = True) -> list[dict[str, Any]]:
    causal_policy = policy.get("causal_context") if isinstance(policy.get("causal_context"), dict) else {}
    if causal_policy.get("bind_active_changes") is False:
        return []
    max_changes = max(1, min(safe_int(causal_policy.get("max_active_changes"), 4), 12))
    include_contextual = (
        causal_policy.get("include_contextual_active_changes") is True
        or causal_policy.get("contextual_active_change_task_binding") is True
    )
    contextual_max_age_sec = max(60, min(safe_int(causal_policy.get("contextual_active_change_max_age_sec"), 21600), 86400 * 7))
    try:
        index = changes_index(write_latest=False)
    except Exception as exc:
        return [{"id": None, "ok": False, "error": repr(exc)[:240]}]
    active = index.get("active") if isinstance(index.get("active"), list) else []
    bindings: list[dict[str, Any]] = []
    for item in active[:max_changes]:
        if not isinstance(item, dict):
            continue
        surfaces = item.get("surfaces") if isinstance(item.get("surfaces"), list) else []
        matched = [
            str(surface)
            for surface in surfaces
            if any(typing_path_under(path, str(surface)) for path in surface_paths)
        ][:5]
        if not matched:
            if not allow_contextual or not include_contextual:
                continue
            contextual_timestamp = item.get("updated_at") or item.get("created_at")
            contextual_age_sec = age_seconds_from_iso(contextual_timestamp)
            if isinstance(contextual_age_sec, (int, float)) and contextual_age_sec > contextual_max_age_sec:
                continue
        else:
            contextual_age_sec = None
        if not matched and not allow_contextual:
            continue
        bindings.append({
            "id": item.get("id"),
            "title": item.get("title"),
            "status": item.get("status"),
            "created_at": item.get("created_at"),
            "updated_at": item.get("updated_at"),
            "match": "surface_match" if matched else "active_machine_change",
            "matched_surfaces": matched,
            "contextual_age_sec": contextual_age_sec,
            "contextual_max_age_sec": contextual_max_age_sec if not matched else None,
        })
    return bindings


