def typing_build_causal_context(
    event_id: str,
    generated_at: str,
    source_id: str,
    text_sha256: str,
    text_length: int,
    context_payload: dict[str, Any],
    metadata: dict[str, Any] | None,
    policy: dict[str, Any],
    signal_text: str | None = None,
) -> dict[str, Any]:
    causal_policy = policy.get("causal_context") if isinstance(policy.get("causal_context"), dict) else {}
    enabled = causal_policy.get("enabled") is not False
    app_text = typing_context_payload_text(context_payload, "app")
    window_title = typing_context_payload_text(context_payload, "window_title")
    context_text = typing_context_payload_text(context_payload, "context")
    file_meta = metadata.get("file") if isinstance(metadata, dict) and isinstance(metadata.get("file"), dict) else {}
    binding_signal_text = "\n".join(
        item
        for item in (
            str(signal_text or ""),
            app_text,
            window_title,
            context_text,
            str(file_meta.get("path") or ""),
            str(file_meta.get("root") or ""),
        )
        if item
    )
    topic_signal_text = "\n".join(
        item
        for item in (
            str(signal_text or ""),
            app_text,
            window_title,
        )
        if item
    )
    surface_paths = typing_causal_surface_paths(context_payload, metadata, binding_signal_text)
    primary_path = str(file_meta.get("path") or typing_causal_extract_shell_cwd(context_text) or (surface_paths[0] if surface_paths else ""))
    path_project = typing_causal_project_for_paths(surface_paths, policy)
    if not path_project and primary_path:
        path_project = typing_causal_project_for_path(primary_path, policy)
        if isinstance(path_project, dict):
            path_project["basis"] = "primary_path"
    topic_project = typing_causal_topic_project_for_text(topic_signal_text, policy)
    controlled_project = typing_causal_controlled_probe_project(source_id, context_payload, metadata)
    project = controlled_project or typing_causal_resolve_project(path_project, topic_project, policy, source_id)
    active_changes = typing_causal_active_changes(surface_paths, policy, allow_contextual=source_id != "saved_text_snapshot") if enabled else []
    surface_active_changes = [item for item in active_changes if isinstance(item, dict) and item.get("match") == "surface_match"]
    url_text = typing_context_payload_text(context_payload, "url")
    browser_metadata = typing_causal_browser_metadata_context(metadata)
    if not url_text:
        url_text = browser_metadata.get("url") or ""
    if not window_title:
        window_title = browser_metadata.get("title") or ""
    transcript_meta = metadata.get("ai_transcript") if isinstance(metadata, dict) and isinstance(metadata.get("ai_transcript"), dict) else {}
    transcript_identity = transcript_meta.get("page_identity") if isinstance(transcript_meta.get("page_identity"), dict) else {}
    ai_counterpart = (
        transcript_identity
        if transcript_identity.get("is_ai") is True
        else browser_ai_counterpart_identity(url_text, window_title)
    )
    interaction = typing_causal_interaction_identity(source_id, context_payload, metadata)
    context_anchor = (
        typing_ai_counterpart_context_anchor(ai_counterpart)
        if not project and ai_counterpart.get("is_ai") is True
        else typing_context_anchor_from_parts(source_id, app_text, window_title, url_text, primary_path, project)
    )
    contextual_task_binding = causal_policy.get("contextual_active_change_task_binding") is True
    task_anchor: dict[str, Any]
    if surface_active_changes or (contextual_task_binding and active_changes):
        source_changes = surface_active_changes or active_changes
        first_change = source_changes[0] if isinstance(source_changes[0], dict) else {}
        task_anchor = {
            "kind": "active_change",
            "id": str(first_change.get("id") or "active_change"),
            "label": first_change.get("title") or first_change.get("id"),
            "confidence": first_change.get("match") or "active_machine_change",
            "stores_extra_text": False,
        }
    elif isinstance(project, dict) and project.get("id"):
        task_anchor = {
            "kind": "project_root",
            "id": f"project:{project.get('id')}",
            "label": project.get("id"),
            "confidence": "project_root_match",
            "stores_extra_text": False,
        }
    else:
        task_anchor = {
            "kind": context_anchor.get("kind"),
            "id": context_anchor.get("id"),
            "label": context_anchor.get("label"),
            "confidence": context_anchor.get("confidence"),
            "stores_extra_text": False,
        }
    if surface_active_changes or (contextual_task_binding and active_changes):
        task_binding = "active_change"
    elif isinstance(project, dict) and project.get("id"):
        task_binding = "project_or_surface_context"
    elif context_anchor.get("id") != "unknown":
        task_binding = "context_anchor"
    else:
        task_binding = "unbound"
    recipient = typing_causal_recipient(source_id, context_payload, metadata)
    correlation_seed = "\n".join(
        str(item or "")
        for item in (
            event_id,
            generated_at,
            source_id,
            recipient.get("id"),
            interaction.get("id"),
            context_anchor.get("id"),
            task_anchor.get("id"),
            project.get("id") if isinstance(project, dict) else None,
        )
    )
    correlation_id = "typing-causal-" + hashlib.sha256(correlation_seed.encode("utf-8", errors="replace")).hexdigest()[:20]
    return {
        "schema": f"{SCHEMA_PREFIX}_typing_causal_context_v1",
        "enabled": enabled,
        "input": {
            "event_id": event_id,
            "generated_at": generated_at,
            "source_adapter": source_id,
            "text_sha256": text_sha256,
            "text_length": text_length,
            "stores_text": False,
        },
        "correlation": {
            "id": correlation_id,
            "timeline_key": f"{generated_at}|{event_id}",
            "event_id": event_id,
            "source_adapter": source_id,
            "recipient_id": recipient.get("id"),
            "recipient_kind": recipient.get("kind"),
            "interaction_id": interaction.get("id"),
            "context_anchor_id": context_anchor.get("id"),
            "task_anchor_id": task_anchor.get("id"),
            "project_id": project.get("id") if isinstance(project, dict) else None,
            "active_change_ids": [
                item.get("id")
                for item in active_changes
                if isinstance(item, dict) and item.get("id")
            ],
            "time_basis": "event_generated_at",
            "stores_text": False,
        },
        "where": {
            "kind": typing_causal_surface_kind(source_id),
            "app": app_text or None,
            "window_title": window_title or None,
            "context": context_text or None,
            "url": url_text or None,
            "path": primary_path or None,
            "surface_paths": surface_paths,
            "project": project,
            "context_anchor": context_anchor,
            "page_identity": ai_counterpart if ai_counterpart.get("is_ai") is True else None,
            "interaction": interaction,
            "binding_signals": {
                "surface_path_count": len(surface_paths),
                "project_basis": project.get("basis") if isinstance(project, dict) else None,
                "path_project": typing_causal_project_binding_summary(path_project),
                "topic_hint": {
                    "id": topic_project.get("id"),
                    "matched_keywords": topic_project.get("matched_keywords"),
                    "confidence": topic_project.get("confidence"),
                } if isinstance(topic_project, dict) else None,
                "project_binding": typing_causal_project_binding_summary(project),
                "stores_extra_text": False,
            },
        },
        "recipient": recipient,
        "task": {
            "binding": task_binding,
            "active_changes": active_changes,
            "project": project,
            "context_anchor": task_anchor,
            "confidence": "active_change_surface_match"
            if surface_active_changes
            else "project_topic_inferred" if isinstance(project, dict) and project.get("basis") == "topic_hint"
            else "project_path_inferred" if isinstance(project, dict) and project.get("basis") in {"explicit_path", "primary_path"}
            else "active_change_contextual" if contextual_task_binding and active_changes else "surface_inferred",
            "active_change_task_policy": "surface_match_only" if not contextual_task_binding else "contextual_allowed",
        },
        "policy": {
            "facts_only": True,
            "automatic_action": False,
            "intent_claim": False,
            "stores_text": False,
            "basis": "observable_adapter_context_only",
        },
        "non_claims": [
            "causal_context links observable source, surface, recipient route, and task context; it does not prove final user intent.",
            "causal_context is read-only evidence and does not authorize action.",
        ],
    }


def typing_event_id(source: str, generated_at: str, text_sha256: str, context_hash: str) -> str:
    raw = f"{source}\n{generated_at}\n{text_sha256}\n{context_hash}"
    return "typing-" + hashlib.sha256(raw.encode("utf-8", errors="replace")).hexdigest()[:24]


def typing_sanitize_context_value(value: str | None, max_chars: int) -> dict[str, Any]:
    return typing_capture_contracts.sanitize_context_value(
        value,
        max_chars,
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
    )


def typing_recent_duplicate(source_adapter: str, text_sha256: str, context_sha256: str, max_records: int = 80) -> dict[str, Any] | None:
    records, errors = typing_records(max_records)
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            continue
        text_payload = record.get("text") if isinstance(record.get("text"), dict) else {}
        if (
            record.get("source_adapter") == source_adapter
            and text_payload.get("text_sha256") == text_sha256
            and record.get("context_sha256") == context_sha256
        ):
            return {
                "duplicate": True,
                "matched_recent_index": index,
                "matched_event_id": record.get("event_id"),
                "matched_generated_at": record.get("generated_at"),
                "parse_errors": len(errors),
            }
    return None


def typing_ingest(
    text: str,
    source: str = "manual_cli_stdin",
    app: str | None = None,
    window_title: str | None = None,
    context: str | None = None,
    url: str | None = None,
    write_latest: bool = True,
    skip_duplicate: bool = False,
    force_metadata_only_reason: str | None = None,
    metadata: dict[str, Any] | None = None,
    include_text_in_context_probe: bool = True,
) -> dict[str, Any]:
    policy = typing_policy(write_latest=False)
    generated_at = now_iso()
    raw_text = str(text or "")
    limits = policy.get("limits") if isinstance(policy.get("limits"), dict) else {}
    max_text_chars = max(120, int(limits.get("max_text_chars") or 4000))
    max_context_chars = max(40, int(limits.get("max_context_chars") or 240))
    source_id = re.sub(r"[^A-Za-z0-9_.:-]+", "_", str(source or "manual_cli_stdin")).strip("_")[:80] or "manual_cli_stdin"
    if source_id == "browser_ai_transcript":
        transcript_policy = typing_browser_ai_transcript_policy(policy)
        max_text_chars = max(120, min(safe_int(transcript_policy.get("max_text_chars"), max_text_chars), 12000))
    text_sha256 = hashlib.sha256(raw_text.encode("utf-8", errors="replace")).hexdigest()
    context_payload = {
        "app": typing_sanitize_context_value(app, max_context_chars),
        "window_title": typing_sanitize_context_value(window_title, max_context_chars),
        "context": typing_sanitize_context_value(context, max_context_chars),
        "url": typing_sanitize_context_value(url, max_context_chars),
    }
    context_hash_raw = json.dumps(context_payload, ensure_ascii=False, sort_keys=True)
    context_hash = hashlib.sha256(context_hash_raw.encode("utf-8", errors="replace")).hexdigest()
    duplicate = typing_recent_duplicate(source_id, text_sha256, context_hash, safe_int(nested_get(policy, ["focused_snapshot", "duplicate_window_records"]), 80)) if skip_duplicate else None
    metadata_payload = metadata if isinstance(metadata, dict) else {}
    capture_gate = typing_capture_gate_decision(
        source_id,
        app=app,
        window_title=window_title,
        context=context,
        url=url,
        metadata=metadata_payload,
        policy=policy,
        write_latest=False,
    )
    sensitive_context_probe = "\n".join(item for item in (str(context or ""), f"url={url}" if url else "") if item)
    sensitive_matches = typing_sensitive_matches(source_id, app, window_title, sensitive_context_probe, raw_text, policy, include_text_in_context_probe=include_text_in_context_probe)
    if force_metadata_only_reason:
        sensitive_matches.append({"kind": "forced_metadata_only", "reason": str(force_metadata_only_reason)})
    gate_decision = str(capture_gate.get("decision") or "metadata_only")
    gate_forced_metadata = gate_decision in {"metadata_only", "needs_review", "skip"}
    if gate_decision in {"metadata_only", "needs_review", "skip"}:
        sensitive_matches.append({
            "kind": f"capture_gate_{gate_decision}",
            "decision": gate_decision,
            "reason": ",".join(str(item) for item in capture_gate.get("reasons", [])[:3]) or "capture_gate",
        })
    redacted = nervous_redact_text(raw_text)
    redacted_text = str(redacted.get("redacted_text") or "")
    redaction_summary = redacted.get("summary") if isinstance(redacted.get("summary"), dict) else {}
    secret_matches = [item for item in sensitive_matches if item.get("kind") == "redaction_match"]
    deny_context_matches = [item for item in sensitive_matches if item.get("kind") in {"deny_context_token", "forced_metadata_only", "capture_gate_metadata_only", "capture_gate_needs_review", "capture_gate_skip"}]
    metadata_only = bool(deny_context_matches or secret_matches)
    metadata_only_reason = None
    if metadata_only:
        if force_metadata_only_reason:
            metadata_only_reason = str(force_metadata_only_reason)
        elif gate_forced_metadata:
            metadata_only_reason = f"capture_gate:{gate_decision}"
        elif secret_matches:
            metadata_only_reason = "secret_like_text"
        else:
            metadata_only_reason = "sensitive_context"
    truncated = len(redacted_text) > max_text_chars
    captured_text = "" if metadata_only else (redacted_text[:max_text_chars] if truncated else redacted_text)
    event_id = typing_event_id(source_id, generated_at, text_sha256, context_hash)
    causal_context = typing_build_causal_context(
        event_id,
        generated_at,
        source_id,
        text_sha256,
        len(raw_text),
        context_payload,
        metadata_payload,
        policy,
        signal_text=raw_text,
    )
    status = "skipped_by_capture_gate" if gate_decision == "skip" else ("metadata_only" if metadata_only else ("redacted" if secret_matches else "captured"))
    data = {
        "schema": f"{SCHEMA_PREFIX}_typing_event_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": True,
        "event_id": event_id,
        "status": status,
        "source_id": "typed_text_autolog",
        "source_adapter": source_id,
        "context": context_payload,
        "context_sha256": context_hash,
        "duplicate": duplicate or {"duplicate": False},
        "metadata": metadata_payload,
        "capture_gate": capture_gate,
        "causal_context": causal_context,
        "sensitivity": "metadata_only_sensitive" if metadata_only else "local_private_redacted",
        "text": {
            "captured": not metadata_only,
            "text": captured_text if captured_text else None,
            "text_sha256": text_sha256,
            "text_length": len(raw_text),
            "text_chars_stored": len(captured_text),
            "truncated": truncated and not metadata_only,
            "redaction": redaction_summary,
            "redaction_matches": redacted.get("matches", []),
            "metadata_only_reason": metadata_only_reason,
        },
        "classification": {
            "sensitive_context": bool(deny_context_matches),
            "secret_like_text": bool(secret_matches),
            "capture_gate_decision": gate_decision,
            "capture_gate": capture_gate,
            "matches": sensitive_matches,
        },
        "policy": {
            "raw_keylogging": False,
            "committed_text_only": True,
            "password_fields_captured": False,
            "raw_private_content": False,
            "automatic_action": False,
            "action_execution": False,
            "metadata_only_on_sensitive_context": True,
            "capture_gate_required": True,
            "capture_gate_decision": gate_decision,
        },
        "paths": {
            "latest": str(TYPING_EVENTS_LATEST_PATH),
            "daily_glob": str(TYPING_EVENTS_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
        },
        "non_claims": [
            "This event came from an explicit committed-text adapter, not a global keylogger.",
            "Redaction patterns reduce secret persistence risk but are not a complete DLP proof.",
        ],
    }
    if duplicate:
        data["status"] = "duplicate_skipped"
        data["sensitivity"] = "duplicate_existing_event"
        data["text"]["captured"] = False
        data["text"]["text"] = None
        data["text"]["text_chars_stored"] = 0
        data["text"]["metadata_only_reason"] = "duplicate_recent_event"
        data["policy"]["duplicate_gate"] = True
        return data
    if write_latest:
        ensure_typing_docs()
        errors = nervous_write_json_latest_and_daily(TYPING_EVENTS_LATEST_PATH, TYPING_EVENTS_ROOT, data)
        index_error = safe_atomic_write_json(TYPING_INDEX_PATH, typing_index_document(), 0o664)
        errors = errors + ([index_error] if index_error else [])
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


