def typing_omit_private_text_fields(value: Any) -> Any:
    if isinstance(value, dict):
        return {
            key: typing_omit_private_text_fields(item)
            for key, item in value.items()
            if not str(key).startswith("_")
        }
    if isinstance(value, list):
        return [typing_omit_private_text_fields(item) for item in value]
    return value


def typing_safe_process_tail(text: Any, max_chars: int = 1000) -> str:
    raw = str(text or "")[-4000:]
    redacted = re.sub(
        r"(?i)([?&](?:key|token|api[_-]?key|apikey|client[_-]?secret)=)[^\s&]+",
        r"\1[REDACTED:url_query_secret]",
        raw,
    )
    return str(nervous_text_payload(redacted, max_chars=max_chars).get("text") or "")


