def typing_atspi_compact_history_contract(limit: int = 200) -> dict[str, Any]:
    path = ai_daily_jsonl_path(TYPING_ATSPI_TEXT_EVENTS_ROOT)
    lines = read_recent_jsonl_lines(path, max_lines=max(20, min(int(limit), 1000)), max_bytes=4 * 1024 * 1024)
    records: list[dict[str, Any]] = []
    parse_errors: list[dict[str, Any]] = []
    for index, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except (TypeError, ValueError) as exc:
            parse_errors.append({"line_offset": index, "error": str(exc)[:240]})
            continue
        if isinstance(item, dict):
            records.append(item)
    return typing_capture_contracts.typing_atspi_compact_history_contract_document(
        records=records,
        parse_errors=parse_errors,
        path=str(path),
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        lines_scanned=len(lines),
    )


