def typing_atspi_text_event_handle(
    obj: Any,
    pyatspi_module: Any,
    event_type: str,
    event_detail1: Any,
    event_detail2: Any,
    event_any_data: Any,
    policy: dict[str, Any],
    events_policy: dict[str, Any],
    last_by_context: dict[str, dict[str, Any]],
    write_latest: bool,
) -> dict[str, Any]:
    source = typing_atspi_adapters.AT_SPI_TEXT_EVENT_SOURCE
    generated_at = now_iso()
    context_data = typing_atspi_object_context(obj, pyatspi_module)
    app = str(context_data.get("app") or "")
    window_title = str(context_data.get("window_title") or "")
    url = str(context_data.get("url") or "")
    document_title = str(context_data.get("document_title") or "")
    content_type = str(context_data.get("content_type") or "")
    source_atspi_path = str(context_data.get("atspi_path") or "")
    document_atspi_path = str(context_data.get("document_path") or "")
    browser_context_inference: dict[str, Any] = {}
    if not url and "firefox" in app.lower():
        browser_context_inference = typing_browser_context_from_recent_atspi_path(
            source_atspi_path,
            document_atspi_path,
            events_policy,
            allow_attention_fallback=True,
        )
        if browser_context_inference.get("ok") is True and browser_context_inference.get("url"):
            url = str(browser_context_inference.get("url") or "")
            if not document_title and browser_context_inference.get("title"):
                document_title = typing_atspi_safe_string(browser_context_inference.get("title"), 240)
            if not content_type and browser_context_inference.get("content_type"):
                content_type = typing_atspi_safe_string(browser_context_inference.get("content_type"), 120)
    app_process_id = context_data.get("app_process_id")
    app_toolkit_name = str(context_data.get("app_toolkit_name") or "")
    app_toolkit_version = str(context_data.get("app_toolkit_version") or "")
    role = str(context_data.get("role") or "")
    name = str(context_data.get("name") or "")
    description = str(context_data.get("description") or "")
    states = context_data.get("states") if isinstance(context_data.get("states"), dict) else {}
    role_lower = role.lower()
    text_roles = {str(item).lower() for item in events_policy.get("text_roles", []) if str(item).strip()}
    sensitive_roles = {str(item).lower() for item in events_policy.get("sensitive_roles", []) if str(item).strip()}
    text_role = role_lower in text_roles or bool(states.get("editable")) or role_lower in {"entry", "text"}
    context = typing_atspi_adapters.atspi_text_event_context(context_data, event_type=event_type, url=url)
    context_probe = "\n".join([app, window_title, document_title, url, role, name, description, event_type])
    deny_matches = typing_deny_context_matches(context_probe, policy)
    controlled_sensitive_override = typing_atspi_controlled_browser_selftest_override(
        app,
        window_title,
        url,
        role,
        name,
        document_title,
        content_type,
        states,
    )
    sensitive_state = bool(states.get("sensitive")) and not controlled_sensitive_override.get("allowed")
    role_sensitive = role_lower in sensitive_roles or "password" in role_lower or sensitive_state
    sensitive_context = bool(role_sensitive or deny_matches)
    gate = typing_capture_gate_decision(
        source,
        app=app,
        window_title=window_title,
        context=context,
        url=url,
        metadata={
            "atspi": {
                "role": role,
                "states": states,
                "name": name,
                "document_title": document_title,
                "content_type": content_type,
            }
        },
        policy=policy,
        write_latest=False,
    )
    gate_decision = str(gate.get("decision") or "metadata_only")
    sensitive_matches = ([{"kind": "sensitive_role_or_state", "role": role}] if role_sensitive else []) + deny_matches
    base: dict[str, Any] = typing_atspi_adapters.atspi_text_event_sample_base(
        context_data,
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=generated_at,
        event_type=event_type,
        event_detail1=event_detail1,
        event_detail2=event_detail2,
        event_any_data=event_any_data,
        url=url,
        document_title=document_title,
        content_type=content_type,
        source_atspi_path=source_atspi_path,
        document_atspi_path=document_atspi_path,
        browser_context_inference=browser_context_inference,
        text_role=bool(text_role),
        sensitive_context=sensitive_context,
        sensitive_matches=sensitive_matches,
        controlled_sensitive_override=controlled_sensitive_override,
        capture_gate=gate,
    )
    if not text_role:
        base["status"] = "skipped_non_text_event_source"
        return base
    if sensitive_context or gate_decision != "allow_text":
        event = typing_ingest(
            "",
            source=source,
            app=app,
            window_title=window_title,
            context=context,
            url=url,
            write_latest=write_latest,
            skip_duplicate=True,
            force_metadata_only_reason="atspi_sensitive_context" if sensitive_context else f"capture_gate:{gate_decision}",
            include_text_in_context_probe=False,
            metadata=typing_atspi_adapters.atspi_text_event_metadata(
                context_data,
                event_type=event_type,
                url=url,
                document_title=document_title,
                content_type=content_type,
                source_atspi_path=source_atspi_path,
                document_atspi_path=document_atspi_path,
                gate_decision=gate_decision,
                text_read=False,
                controlled_sensitive_override=controlled_sensitive_override,
                browser_context_inference=browser_context_inference,
            ),
        )
        base["status"] = "metadata_only_or_skipped_before_text_read"
        base["typing_event"] = typing_atspi_adapters.atspi_typing_event_summary(event)
        return base
    limits = policy.get("limits") if isinstance(policy.get("limits"), dict) else {}
    max_chars = max(120, min(safe_int(limits.get("max_text_chars"), 4000), 12000))
    text, text_length, caret, text_error = typing_atspi_text_payload(obj, max_chars=max_chars)
    base["text_length"] = text_length
    base["caret_offset"] = caret
    if text_error:
        base["ok"] = False
        base["status"] = "text_read_failed"
        base["error"] = text_error
        return base
    if not text.strip():
        base["status"] = "skipped_empty_text"
        return base
    context_key = typing_atspi_adapters.atspi_context_key(context_data, source=source)
    text_sha = typing_atspi_adapters.text_sha256(text)
    now_ts = time.monotonic()
    previous = last_by_context.get(context_key) if isinstance(last_by_context.get(context_key), dict) else {}
    min_interval = max(0.2, min(float(events_policy.get("min_interval_sec") or 0.8), 5.0))
    debounce_status = typing_atspi_adapters.atspi_text_event_debounce_status(
        previous,
        now_ts=now_ts,
        text_hash=text_sha,
        text_length=text_length,
        min_interval_sec=min_interval,
        capture_length_change_updates=bool(events_policy.get("capture_length_change_updates", True)),
    )
    if debounce_status:
        base["status"] = debounce_status
        return base
    event = typing_ingest(
        text,
        source=source,
        app=app,
        window_title=window_title,
        context=context,
        url=url,
        write_latest=write_latest,
        skip_duplicate=True,
        metadata=typing_atspi_adapters.atspi_text_event_metadata(
            context_data,
            event_type=event_type,
            url=url,
            document_title=document_title,
            content_type=content_type,
            source_atspi_path=source_atspi_path,
            document_atspi_path=document_atspi_path,
            text_read=True,
            caret_offset=caret,
            controlled_sensitive_override=controlled_sensitive_override,
            browser_context_inference=browser_context_inference,
        ),
        include_text_in_context_probe=True,
    )
    last_by_context[context_key] = {"ts": now_ts, "sha256": text_sha, "text_length": text_length, "event_id": event.get("event_id")}
    base["status"] = "captured" if event.get("status") in {"captured", "redacted"} else str(event.get("status") or "ingested")
    base["typing_event"] = typing_atspi_adapters.atspi_typing_event_summary(event, include_text=True)
    return base


def typing_atspi_text_events(seconds: float | None = 5.0, forever: bool = False, write_latest: bool = True) -> dict[str, Any]:
    policy = typing_policy(write_latest=False)
    events_policy = typing_atspi_text_events_policy(policy)
    generated_at = now_iso()
    if events_policy.get("enabled") is False:
        return typing_atspi_text_events_store(
            typing_atspi_adapters.atspi_text_events_disabled_document(
                schema_prefix=SCHEMA_PREFIX,
                version=VERSION,
                generated_at=generated_at,
            ),
            write_latest,
        )

    def write_latest_only(data: dict[str, Any]) -> list[dict[str, Any]]:
        latest_error = safe_atomic_write_json(TYPING_ATSPI_TEXT_EVENTS_LATEST_PATH, data, 0o664)
        index_error = safe_atomic_write_json(TYPING_INDEX_PATH, typing_index_document(), 0o664)
        return [item for item in (latest_error, index_error) if item]

    def append_compact_history(
        data: dict[str, Any],
        sample: dict[str, Any] | None,
        listener_status: str,
        error: str | None,
    ) -> dict[str, Any] | None:
        return typing_atspi_text_events_append_compact_history(data, sample, listener_status, error=error)

    def handle_event(
        event: Any,
        pyatspi_module: Any,
        last_by_context: dict[str, dict[str, Any]],
        write_latest_value: bool,
    ) -> dict[str, Any]:
        event_type = typing_atspi_safe_string(getattr(event, "type", "unknown"), 160)
        return typing_atspi_text_event_handle(
            event.source,
            pyatspi_module,
            event_type,
            getattr(event, "detail1", None),
            getattr(event, "detail2", None),
            getattr(event, "any_data", None),
            policy,
            events_policy,
            last_by_context,
            write_latest_value,
        )

    return typing_atspi_adapters.run_atspi_text_events_listener(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=generated_at,
        events_policy=events_policy,
        seconds=seconds,
        forever=forever,
        write_latest=write_latest,
        handle_event=handle_event,
        store_latest_history=typing_atspi_text_events_store,
        write_latest_only=write_latest_only,
        append_compact_history=append_compact_history,
        now_iso=now_iso,
    )


