def typing_generic_gui_find_probe_event(text_sha256: str, limit: int = 220) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
    records, errors = typing_records(limit)
    for record in records:
        if not isinstance(record, dict):
            continue
        text_payload = record.get("text") if isinstance(record.get("text"), dict) else {}
        if record.get("source_adapter") != "atspi_text_changed_event":
            continue
        if text_payload.get("text_sha256") != text_sha256:
            continue
        return {
            "event_id": record.get("event_id"),
            "generated_at": record.get("generated_at"),
            "status": record.get("status"),
            "source_adapter": record.get("source_adapter"),
            "capture_gate_decision": nested_get(record, ["capture_gate", "decision"]),
            "capture_gate_confidence": nested_get(record, ["capture_gate", "confidence"]),
            "text_length": text_payload.get("text_length"),
            "text_chars_stored": text_payload.get("text_chars_stored"),
            "text_sha256": text_payload.get("text_sha256"),
            "recipient": nested_get(record, ["causal_context", "recipient"]),
            "where": nested_get(record, ["causal_context", "where"]),
            "task": nested_get(record, ["causal_context", "task"]),
        }, errors
    return None, errors


def typing_generic_gui_selftest(write_latest: bool = True) -> dict[str, Any]:
    generated_at = now_iso()
    run_id = typing_atspi_adapters.generic_gui_selftest_run_id(generated_at, os.getpid())
    plan = typing_atspi_adapters.generic_gui_selftest_plan(run_id)
    safe_ingest = plan.get("safe_ingest") if isinstance(plan.get("safe_ingest"), dict) else {}
    sensitive_ingest = plan.get("sensitive_ingest") if isinstance(plan.get("sensitive_ingest"), dict) else {}
    ingest = typing_ingest(**safe_ingest, write_latest=write_latest)
    sensitive = typing_ingest(**sensitive_ingest, write_latest=write_latest)
    event, parse_errors = typing_generic_gui_find_probe_event(str(plan.get("probe_hash") or ""))
    data = typing_atspi_adapters.generic_gui_selftest_document(
        plan=plan,
        ingest=ingest,
        sensitive=sensitive,
        event=event,
        parse_errors=parse_errors,
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=generated_at,
    )
    return typing_generic_gui_selftest_store(data, write_latest)


