def typing_saved_text_scan(write_latest: bool = True, roots_override: list[str] | None = None, prime_state: bool = False) -> dict[str, Any]:
    policy = typing_policy(write_latest=False)
    saved_policy = typing_saved_text_policy(policy)
    generated_at = now_iso()
    if roots_override is not None:
        saved_policy["roots"] = roots_override
    if saved_policy.get("enabled") is False:
        return typing_saved_text_adapters.saved_text_disabled_document(
            schema_prefix=SCHEMA_PREFIX,
            version=VERSION,
            generated_at=generated_at,
        )
    state, state_error = load_json_document(TYPING_SAVED_TEXT_STATE_PATH)
    state_data = state if isinstance(state, dict) else {}
    candidates, skips = typing_saved_text_scan_candidates(saved_policy, state_data)

    def ingest_item(item: Mapping[str, Any]) -> Mapping[str, Any]:
        ingest_kwargs = typing_saved_text_adapters.saved_text_ingest_kwargs(item)
        return typing_ingest(
            ingest_kwargs.pop("text"),
            **ingest_kwargs,
            write_latest=write_latest,
        )

    events, file_updates = typing_saved_text_adapters.saved_text_process_scan_candidates(
        candidates,
        generated_at=generated_at,
        prime_state=prime_state,
        ingest_item=ingest_item,
    )
    data = typing_saved_text_adapters.saved_text_scan_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=generated_at,
        candidates=candidates,
        events=events,
        skips=skips,
        saved_policy=saved_policy,
        state_error=state_error,
        paths={
            "latest": str(TYPING_SAVED_TEXT_LATEST_PATH),
            "state": str(TYPING_SAVED_TEXT_STATE_PATH),
            "events_latest": str(TYPING_EVENTS_LATEST_PATH),
        },
        prime_state=prime_state,
    )
    if write_latest:
        state_document = typing_saved_text_adapters.saved_text_state_document(
            state_data,
            schema_prefix=SCHEMA_PREFIX,
            version=VERSION,
            generated_at=generated_at,
            file_updates=file_updates,
        )
        data = typing_saved_text_adapters.saved_text_write_scan_outputs(
            state=state_document,
            data=data,
            state_path=TYPING_SAVED_TEXT_STATE_PATH,
            latest_path=TYPING_SAVED_TEXT_LATEST_PATH,
            index_path=TYPING_INDEX_PATH,
            write_json=safe_atomic_write_json,
            index_document=typing_index_document,
        )
    return data


