def typing_xpi_signature_status(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {"exists": False, "signed": False, "error": "missing"}
    try:
        with zipfile.ZipFile(path) as archive:
            names = [str(name) for name in archive.namelist()]
    except Exception as exc:
        return {"exists": True, "signed": False, "error": repr(exc)[:240]}
    upper_names = {name.upper() for name in names}
    signature_files = sorted(
        name for name in names
        if name.upper().startswith("META-INF/") and name.upper().endswith((".RSA", ".DSA", ".EC", ".SF"))
    )
    return {
        "exists": True,
        "signed": bool(signature_files) and "META-INF/MANIFEST.MF" in upper_names,
        "signature_files": signature_files[:12],
        "manifest_present": "META-INF/MANIFEST.MF" in upper_names,
        "error": None,
    }


def typing_browser_extension_activation_profiles() -> list[dict[str, Any]]:
    results: list[dict[str, Any]] = []
    for profile in typing_browser_extension_profiles():
        ext_path = Path(str(profile.get("extensions_json") or ""))
        sideload_xpi = Path(str(profile.get("sideload_xpi") or ""))
        active = False
        registered = False
        signed_state = None
        user_disabled = None
        app_disabled = None
        error = None
        data, load_error = load_json_document(ext_path)
        if isinstance(data, dict):
            addons = data.get("addons") if isinstance(data.get("addons"), list) else []
            for addon in addons:
                if not isinstance(addon, dict) or addon.get("id") != TYPING_BROWSER_EXTENSION_ID:
                    continue
                registered = True
                active = addon.get("active") is True
                signed_state = addon.get("signedState")
                user_disabled = addon.get("userDisabled")
                app_disabled = addon.get("appDisabled")
                break
        else:
            error = load_error
        results.append({
            **profile,
            "installed": registered,
            "registered": registered,
            "active": active,
            "xpi_present": sideload_xpi.exists(),
            "sideload_xpi_exists": sideload_xpi.exists(),
            "signed_state": signed_state,
            "user_disabled": user_disabled,
            "app_disabled": app_disabled,
            "error": error,
        })
    return results


