def typing_browser_extension_status(write_latest: bool = True) -> dict[str, Any]:
    manifest = TYPING_BROWSER_EXTENSION_ROOT / "manifest.json"
    content = TYPING_BROWSER_EXTENSION_ROOT / "content.js"
    background = TYPING_BROWSER_EXTENSION_ROOT / "background.js"
    native_manifest, native_manifest_error = load_json_document(TYPING_BROWSER_NATIVE_HOST_USER_MANIFEST)
    policies, policies_error = load_json_document(TYPING_FIREFOX_POLICIES_PATH)
    profile_activation = typing_browser_extension_activation_profiles()
    active_profiles = [item for item in profile_activation if item.get("active")]
    registered_profiles = [item for item in profile_activation if item.get("registered")]
    xpi_present_profiles = [item for item in profile_activation if item.get("xpi_present")]
    policy_settings = nested_get(policies, ["policies", "ExtensionSettings", TYPING_BROWSER_EXTENSION_ID]) if isinstance(policies, dict) else None
    source_xpi_signature = typing_xpi_signature_status(TYPING_BROWSER_EXTENSION_XPI_PATH)
    profile_xpi_signatures = {
        str(item.get("name") or item.get("path")): typing_xpi_signature_status(Path(str(item.get("sideload_xpi") or "")))
        for item in profile_activation
        if item.get("xpi_present")
    }
    if active_profiles:
        status = "active"
    elif registered_profiles:
        status = "registered_waiting_for_firefox_activation"
    elif xpi_present_profiles:
        status = "xpi_present_unregistered"
    else:
        status = "not_installed"
    data = {
        "schema": f"{SCHEMA_PREFIX}_typing_browser_extension_status_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "status": status,
        "source_adapter": "browser_extension_explicit",
        "extension_id": TYPING_BROWSER_EXTENSION_ID,
        "paths": {
            "extension": str(TYPING_BROWSER_EXTENSION_ROOT),
            "manifest": str(manifest),
            "content": str(content),
            "background": str(background),
            "xpi": str(TYPING_BROWSER_EXTENSION_XPI_PATH),
            "native_host": str(TYPING_BROWSER_NATIVE_HOST_PATH),
            "native_manifest": str(TYPING_BROWSER_NATIVE_HOST_USER_MANIFEST),
            "firefox_policies": str(TYPING_FIREFOX_POLICIES_PATH),
        },
        "files": {
            "manifest": manifest.exists(),
            "content": content.exists(),
            "background": background.exists(),
            "xpi": TYPING_BROWSER_EXTENSION_XPI_PATH.exists(),
            "native_host": TYPING_BROWSER_NATIVE_HOST_PATH.exists() and os.access(TYPING_BROWSER_NATIVE_HOST_PATH, os.X_OK),
            "native_manifest": isinstance(native_manifest, dict),
            "firefox_policies": isinstance(policies, dict),
        },
        "activation": {
            "active_profiles": len(active_profiles),
            "registered_profiles": len(registered_profiles),
            "xpi_present_profiles": len(xpi_present_profiles),
            "release_profile_route_ready": bool(active_profiles),
            "profile_xpi_copy_is_not_registration": True,
            "likely_blocker": "unsigned_or_unregistered_local_xpi_in_firefox_release_profile" if not active_profiles else None,
            "passwordless_next_routes": [
                "temporary-profile WebExtension selftest",
                "AT-SPI browser committed-text fallback",
                "signed AMO/self-distributed XPI",
                "Firefox ESR/Developer/Nightly with signing policy configured",
            ],
        },
        "xpi_signature": {
            "source_xpi": source_xpi_signature,
            "profile_xpis": profile_xpi_signatures,
        },
        "native_manifest": {
            "ok": isinstance(native_manifest, dict)
            and native_manifest.get("name") == TYPING_BROWSER_NATIVE_HOST_NAME
            and TYPING_BROWSER_EXTENSION_ID in (native_manifest.get("allowed_extensions") or []),
            "error": native_manifest_error,
        },
        "firefox_policy": {
            "ok": isinstance(policy_settings, dict)
            and policy_settings.get("installation_mode") == "force_installed"
            and str(policy_settings.get("install_url") or "").startswith("file://"),
            "settings": policy_settings,
            "error": policies_error,
        },
        "profiles": profile_activation,
        "policy": {
            "raw_keylogging": False,
            "password_fields_captured": False,
            "keydown_keyup_keypress_captured": False,
            "requires_safe_url": True,
            "requires_safe_field": True,
            "automatic_action": False,
            "network_access": False,
        },
        "non_claims": [
            "Firefox may require restart before enterprise policy installs a local XPI.",
            "Firefox release builds may reject unsigned local XPIs; this status reports actual profile activation separately from installed files.",
        ],
    }
    required_files = {key: value for key, value in data["files"].items() if key != "firefox_policies"}
    if not all(bool(value) for value in required_files.values()):
        data["ok"] = False
        data["status"] = "files_incomplete"
    return typing_browser_extension_store(data, write_latest)


