def typing_virtual_type_text(text: str, timeout: float = 5.0) -> dict[str, Any]:
    attempts: list[dict[str, Any]] = []
    wtype_bin = shutil.which("wtype")
    if wtype_bin:
        result = run([wtype_bin, text], timeout=timeout)
        attempt = {
            "method": "wtype",
            "binary": wtype_bin,
            "ok": result.get("ok"),
            "returncode": result.get("returncode"),
            "stderr": str(result.get("stderr") or "")[-500:],
        }
        attempts.append(attempt)
        if result.get("ok"):
            return {
                "ok": True,
                "method": "wtype",
                "returncode": result.get("returncode"),
                "stderr": str(result.get("stderr") or "")[-500:],
                "attempts": attempts,
            }

    ydotool_bin = shutil.which("ydotool")
    if ydotool_bin:
        env = os.environ.copy()
        env.setdefault("YDOTOOL_SOCKET", f"/run/user/{os.getuid()}/.ydotool_socket")
        result = run(
            [ydotool_bin, "type", "--key-delay", "35", "--key-hold", "20", text],
            timeout=timeout,
            env=env,
        )
        attempt = {
            "method": "ydotool",
            "binary": ydotool_bin,
            "socket": env.get("YDOTOOL_SOCKET"),
            "ok": result.get("ok"),
            "returncode": result.get("returncode"),
            "stderr": str(result.get("stderr") or "")[-500:],
        }
        attempts.append(attempt)
        if result.get("ok"):
            return {
                "ok": True,
                "method": "ydotool",
                "returncode": result.get("returncode"),
                "stderr": str(result.get("stderr") or "")[-500:],
                "attempts": attempts,
            }

    return {
        "ok": False,
        "method": None,
        "returncode": attempts[-1].get("returncode") if attempts else 127,
        "stderr": attempts[-1].get("stderr") if attempts else "wtype and ydotool unavailable",
        "attempts": attempts,
    }


def typing_browser_atspi_natural_route_host() -> str | None:
    hosts: list[str] = []
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as probe:
            probe.connect(("1.1.1.1", 80))
            hosts.append(str(probe.getsockname()[0] or ""))
    except OSError:
        pass
    try:
        for item in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            address = item[4][0] if item and item[4] else ""
            hosts.append(str(address or ""))
    except OSError:
        pass
    for host in hosts:
        if host and not host.startswith("127."):
            return host
    return None


