def typing_process(limit: int = 240, write_latest: bool = True) -> dict[str, Any]:
    bounded_limit = max(1, min(int(limit), 1000))
    policy = typing_policy(write_latest=False)
    records, errors = typing_records(bounded_limit)
    data = typing_process_from_records(records, errors, policy)
    if write_latest:
        write_errors = write_latest_and_history(data, TYPING_PROCESS_LATEST_PATH, TYPING_PROCESS_ROOT)
        index_error = safe_atomic_write_json(TYPING_INDEX_PATH, typing_index_document(), 0o664)
        write_errors = write_errors + ([index_error] if index_error else [])
        if write_errors:
            data["ok"] = False
            data["write_errors"] = write_errors
    return data


def typing_causal_awareness(limit: int = 240, write_latest: bool = True) -> dict[str, Any]:
    process = typing_process(limit=limit, write_latest=write_latest)
    summary = process.get("summary") if isinstance(process.get("summary"), dict) else {}
    awareness = process.get("awareness") if isinstance(process.get("awareness"), dict) else {}
    data = {
        "schema": f"{SCHEMA_PREFIX}_typing_causal_awareness_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(process.get("ok") and isinstance(awareness, dict)),
        "status": process.get("status"),
        "summary": {
            "records_processed": summary.get("records_processed"),
            "lanes": summary.get("lanes"),
            "average_score": awareness.get("average_score"),
            "complete": summary.get("awareness_complete"),
            "guarded": summary.get("awareness_guarded"),
            "incomplete": summary.get("awareness_incomplete"),
            "project_bound": summary.get("project_bound"),
            "unknown_project": summary.get("unknown_project"),
            "interaction_records": summary.get("interaction_records"),
            "continuity_promoted": summary.get("continuity_promoted"),
            "duplicate_event_rows_collapsed": summary.get("duplicate_event_rows_collapsed"),
        },
        "awareness": awareness,
        "by_project": process.get("by_project"),
        "by_project_basis": process.get("by_project_basis"),
        "by_recipient": process.get("by_recipient"),
        "by_interaction_kind": process.get("by_interaction_kind"),
        "quality_gaps": process.get("quality_gaps"),
        "context_notes": process.get("context_notes"),
        "policy": {
            "facts_only": True,
            "stores_extra_text": False,
            "widens_capture": False,
            "automatic_action": False,
            "intent_claim": False,
        },
        "non_claims": [
            "Causal awareness summarizes evidence coverage for already-stored typing events.",
            "It does not capture more text, infer final intent, or authorize automatic action.",
        ],
    }
    return data


