def typing_coverage_from_records(
    records: list[dict[str, Any]],
    parse_errors: list[dict[str, Any]],
    policy: dict[str, Any],
    latest: dict[str, Any] | None = None,
    generated_at: str | None = None,
) -> dict[str, Any]:
    generated = generated_at or now_iso()
    return typing_capture_contracts.typing_coverage_document_from_records(
        records,
        parse_errors,
        policy,
        latest=latest,
        generated_at=generated,
        coverage_snapshot=typing_coverage_input_snapshot(policy),
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        home_path=str(Path.home()),
    )


def typing_coverage(limit: int = 500, write_latest: bool = True) -> dict[str, Any]:
    policy = typing_policy(write_latest=False)
    latest = typing_latest()
    records, errors = typing_records(limit)
    data = typing_coverage_from_records(records, errors, policy, latest=latest)
    if write_latest:
        write_errors = write_latest_and_history(data, TYPING_COVERAGE_LATEST_PATH, TYPING_COVERAGE_ROOT)
        index_error = safe_atomic_write_json(TYPING_INDEX_PATH, typing_index_document(), 0o664)
        write_errors = write_errors + ([index_error] if index_error else [])
        if write_errors:
            data["ok"] = False
            data["write_errors"] = write_errors
    return data


def typing_gnome_accessibility_status() -> dict[str, Any]:
    raw = run(["gsettings", "get", "org.gnome.desktop.interface", "toolkit-accessibility"], timeout=2.0)
    value = str(raw.get("stdout") or "").strip()
    enabled = value == "true"
    return {
        "schema": f"{SCHEMA_PREFIX}_typing_gnome_accessibility_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": bool(raw.get("ok") and value in {"true", "false"}),
        "enabled": enabled,
        "value": value or None,
        "command": "gsettings get org.gnome.desktop.interface toolkit-accessibility",
        "error": None if raw.get("ok") else str(raw.get("stderr") or raw.get("error") or "")[:240],
        "policy": {
            "raw_keylogging": False,
            "password_fields_captured": False,
            "automatic_action": False,
            "accessibility_events_only": True,
        },
    }


def typing_find_source_facts(document: Any, source_id: str) -> list[dict[str, Any]]:
    return typing_nervous_source_facts(document, source_id)


def typing_nervous_processing_status() -> dict[str, Any]:
    source_id = "typed_text_autolog"
    source = nervous_source_lookup(source_id) or {}
    facts_latest, facts_error = load_json_document(NERVOUS_FACTS_LATEST_PATH)
    index_latest, index_error = load_json_document(NERVOUS_SEARCH_INDEX_LATEST_PATH)
    index_sources = nested_get(index_latest, ["sources", "enabled_private_connector_sources"]) if isinstance(index_latest, dict) else []
    if not isinstance(index_sources, list):
        index_sources = nested_get(index_latest, ["sources", "enabled_sources"]) if isinstance(index_latest, dict) else []
    if not isinstance(index_sources, list):
        index_sources = []
    index_source_ids = {str(item) for item in index_sources if str(item or "").strip()}
    counts = index_latest.get("counts") if isinstance(index_latest, dict) and isinstance(index_latest.get("counts"), dict) else {}
    if not counts or counts.get("fts_chunks") is None:
        counts = nervous_index_db_counts()
    sqlite_index_source_ids: set[str] = set()
    if source_id not in index_source_ids and NERVOUS_SEARCH_INDEX_DB_PATH.exists():
        try:
            scan = nervous_index_scan(NERVOUS_SEARCH_INDEX_DB_PATH, smoke_match_query='"typed"')
            sqlite_index_source_ids = {str(item) for item in scan.get("indexed_source_ids", []) if str(item or "").strip()}
        except sqlite3.Error:
            pass
    return build_typing_nervous_processing_status_document(
        source=source,
        facts_latest=facts_latest,
        facts_error=facts_error,
        index_latest=index_latest,
        index_error=index_error,
        facts_latest_path=NERVOUS_FACTS_LATEST_PATH,
        index_latest_path=NERVOUS_SEARCH_INDEX_LATEST_PATH,
        counts_fallback=counts,
        extra_index_source_ids=sqlite_index_source_ids,
        source_id=source_id,
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
    )


