def fingerprint_status() -> dict[str, Any]:
    status: dict[str, Any] = {"fprintd_available": command_exists("fprintd-list")}
    if not status["fprintd_available"]:
        return status
    user = os.environ.get("SUDO_USER") or os.environ.get("USER") or ""
    if not user:
        return status
    out = run(["fprintd-list", user], timeout=4.0)
    status["query_ok"] = out["ok"]
    status["user"] = user
    status["enrolled_count"] = sum(1 for line in out["stdout"].splitlines() if line.strip().startswith("- #"))
    if out["stderr"]:
        status["stderr"] = out["stderr"]
    return status


def gnome_extensions() -> dict[str, Any]:
    result: dict[str, Any] = {"gnome_extensions_available": command_exists("gnome-extensions")}
    if not result["gnome_extensions_available"]:
        return result
    out = run(["gnome-extensions", "list", "--enabled"], timeout=3.0)
    result["query_ok"] = out["ok"]
    enabled = [line.strip() for line in out["stdout"].splitlines() if line.strip()]
    result["enabled"] = enabled
    result["vitals_enabled"] = "Vitals@CoreCoding.com" in enabled
    return result


