def stack_bridge_validate_document_from_checks(
    checks: list[dict[str, Any]],
    *,
    strict: bool,
    export_summary: dict[str, Any] | None,
    paths: dict[str, Any],
    generated_at: str | None = None,
) -> dict[str, Any]:
    return stack_bridge_contracts.validate_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=generated_at or now_iso(),
        checks=checks,
        strict=strict,
        export_summary=export_summary,
        paths=paths,
    )


