def stack_bridge_config() -> dict[str, Any]:
    data, error = load_json_document(STACK_BRIDGE_CONFIG_PATH)
    if data is None:
        data = stack_bridge_default_manifest()
        data["config_exists"] = False
        data["config_error"] = error or "missing"
        return data
    data = dict(data)
    data["config_exists"] = True
    data["config_error"] = None
    data.setdefault("paths", stack_bridge_paths())
    artifacts = data.setdefault("artifacts", {})
    if isinstance(artifacts, dict):
        for layer, routes in stack_bridge_artifact_routes().items():
            layer_routes = artifacts.setdefault(layer, {})
            if isinstance(layer_routes, dict):
                for name, route in routes.items():
                    layer_routes.setdefault(name, route)
    data.setdefault("protected_roots", storage_protected_roots())
    data.setdefault("stack_roots", stack_paths())
    commands = data.setdefault("commands", {})
    if isinstance(commands, dict):
        commands.update(stack_bridge_extension_commands())
    resource_bridge = data.setdefault("resource_bridge", {})
    if isinstance(resource_bridge, dict):
        resource_bridge.setdefault("orchestrator_latest", str(RESOURCE_ORCHESTRATOR_LATEST_PATH))
        resource_bridge.setdefault("commands", {})
        if isinstance(resource_bridge.get("commands"), dict):
            resource_bridge["commands"].update({
                "orchestrator": "abyss-machine resource orchestrator --json",
                "orchestrator_refresh_nervous": "abyss-machine resource orchestrator --refresh-nervous --json",
            })
    data.setdefault("heartbeat_bridge", stack_bridge_heartbeat_bridge_contract())
    data.setdefault("stack_observability_bridge", stack_bridge_observability_bridge_contract())
    self_awareness_bridge = data.setdefault("self_awareness_bridge", {})
