def stack_observability_prometheus_query(expression: str, timeout: float = 2.5) -> dict[str, Any]:
    base_url = STACK_OBSERVABILITY_PROMETHEUS_URL.rstrip("/")
    query = urllib.parse.urlencode({"query": expression})
    url = f"{base_url}/api/v1/query?{query}"
    response = memory_orchestrate_http_json(url, timeout=timeout)
    payload = response.get("json") if isinstance(response.get("json"), dict) else {}
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    results = data.get("result") if isinstance(data.get("result"), list) else []
    summarized: list[dict[str, Any]] = []
    for item in results[:64]:
        if not isinstance(item, dict):
            continue
        metric = item.get("metric") if isinstance(item.get("metric"), dict) else {}
        value = item.get("value") if isinstance(item.get("value"), list) else []
        summarized.append({
            "metric": {
                "job": metric.get("job"),
                "instance": metric.get("instance"),
            },
            "value": value[1] if len(value) > 1 else None,
        })
    return {
        "ok": bool(response.get("ok") and payload.get("status") == "success"),
        "expression": expression,
        "url": url,
        "status": payload.get("status"),
        "result_type": data.get("resultType"),
        "result_count": len(results),
        "results": summarized,
        "http": {
            "ok": response.get("ok"),
            "status_code": response.get("status_code"),
            "elapsed_ms": response.get("elapsed_ms"),
            "error": response.get("error"),
        },
    }


def stack_observability_grafana_health(timeout: float = 2.5) -> dict[str, Any]:
    base_url = STACK_OBSERVABILITY_GRAFANA_URL.rstrip("/")
    response = memory_orchestrate_http_json(f"{base_url}/api/health", timeout=timeout)
    payload = response.get("json") if isinstance(response.get("json"), dict) else {}
    return {
        "ok": bool(response.get("ok")),
        "url": f"{base_url}/api/health",
        "status_code": response.get("status_code"),
        "database": payload.get("database"),
        "version": payload.get("version"),
        "commit": payload.get("commit"),
        "elapsed_ms": response.get("elapsed_ms"),
        "error": response.get("error"),
    }


def stack_observability_expected_containers(container_health: dict[str, Any]) -> dict[str, Any]:
    containers = container_health.get("containers") if isinstance(container_health.get("containers"), list) else []
    by_name: dict[str, dict[str, Any]] = {}
    for item in containers:
        if not isinstance(item, dict):
            continue
        names = [str(item.get("name") or "")]
        names.extend(str(name) for name in item.get("names", []) if isinstance(item.get("names"), list))
        for name in names:
            if name:
                by_name[name] = item

    expected = {
        "prometheus": {"aliases": ["prometheus", "abyss_prometheus_1"], "required": True},
        "grafana": {"aliases": ["grafana", "abyss_grafana_1"], "required": True},
        "loki": {"aliases": ["loki", "abyss_loki_1"], "required": True},
        "alloy": {"aliases": ["alloy", "abyss_alloy_1"], "required": True},
        "cadvisor": {"aliases": ["cadvisor", "abyss_cadvisor_1"], "required": False},
        "alertmanager": {"aliases": ["alertmanager", "abyss_alertmanager_1"], "required": False},
    }
    status: dict[str, Any] = {}
    missing_required: list[str] = []
    not_running_required: list[str] = []
    for name, spec in expected.items():
        found = None
        for alias in spec["aliases"]:
            if alias in by_name:
                found = by_name[alias]
                break
        if found is None:
            for candidate_name, item in by_name.items():
                if candidate_name.endswith(f"_{name}_1") or candidate_name == name:
                    found = item
                    break
        running = bool(found.get("running")) if isinstance(found, dict) else False
        status[name] = {
            "present": isinstance(found, dict),
            "required": bool(spec["required"]),
            "running": running,
            "state": found.get("state") if isinstance(found, dict) else None,
            "health": found.get("health") if isinstance(found, dict) else None,
            "attention_reasons": found.get("attention_reasons") if isinstance(found, dict) else None,
        }
        if spec["required"] and not isinstance(found, dict):
            missing_required.append(name)
        if spec["required"] and isinstance(found, dict) and not running:
            not_running_required.append(name)
    return {
        "ok": not missing_required and not not_running_required,
        "expected": status,
        "missing_required": missing_required,
        "not_running_required": not_running_required,
        "process_summary": container_health.get("summary"),
    }


def stack_observability_exec_candidates(container_health: dict[str, Any]) -> list[str]:
    preferred = ["rag-api", "route-api", "langchain-api", "prometheus", "grafana"]
    containers = container_health.get("containers") if isinstance(container_health.get("containers"), list) else []
    running_names: set[str] = set()
    for item in containers:
        if not isinstance(item, dict) or not item.get("running"):
            continue
        if item.get("name"):
            running_names.add(str(item.get("name")))
        if isinstance(item.get("names"), list):
            running_names.update(str(name) for name in item["names"] if name)
    ordered = [name for name in preferred if name in running_names]
    ordered.extend(sorted(name for name in running_names if name not in ordered))
    return ordered


def stack_observability_podman_http(
    url: str,
    candidates: list[str],
    accept_json: bool = True,
    timeout: float = 5.0,
    max_bytes: int = 262144,
) -> dict[str, Any]:
    if not command_exists("podman"):
        return {"ok": False, "url": url, "error": "podman is not installed", "attempts": []}
    code = r'''
import json
import sys
import time
import urllib.error
import urllib.request

url = sys.argv[1]
accept_json = sys.argv[2] == "1"
max_bytes = int(sys.argv[3])
timeout = float(sys.argv[4])
started = time.monotonic()
headers = {"Accept": "application/json" if accept_json else "*/*"}
request = urllib.request.Request(url, headers=headers)

def emit(payload):
    payload["elapsed_ms"] = round((time.monotonic() - started) * 1000.0, 1)
    print(json.dumps(payload, sort_keys=False))

try:
    with urllib.request.urlopen(request, timeout=timeout) as response:
        raw = response.read(max_bytes + 1)
        truncated = len(raw) > max_bytes
        if truncated:
            raw = raw[:max_bytes]
        text = raw.decode("utf-8", errors="replace")
        payload = {
            "ok": 200 <= int(getattr(response, "status", 0)) < 300,
            "url": url,
            "status_code": getattr(response, "status", None),
            "content_type": response.headers.get("content-type"),
            "truncated": truncated,
            "text_preview": text[:400],
        }
        if accept_json:
            try:
                payload["json"] = json.loads(text)
            except json.JSONDecodeError as exc:
                payload["ok"] = False
                payload["error"] = "invalid JSON: " + str(exc)
        emit(payload)
except urllib.error.HTTPError as exc:
    try:
        text = exc.read(max_bytes).decode("utf-8", errors="replace")
    except Exception:
        text = ""
    emit({"ok": False, "url": url, "status_code": exc.code, "error": str(exc), "text_preview": text[:400]})
except Exception as exc:
    emit({"ok": False, "url": url, "error": str(exc)})
'''
    attempts: list[dict[str, Any]] = []
    for container in candidates[:12]:
        for binary in ("python3", "python"):
            out = run([
                "podman",
                "exec",
                container,
                binary,
                "-c",
                code,
                url,
                "1" if accept_json else "0",
                str(int(max_bytes)),
                str(float(timeout)),
            ], timeout=timeout + 3.0)
            attempt = {
                "container": container,
                "python": binary,
                "ok": out.get("ok"),
                "returncode": out.get("returncode"),
            }
            if not out.get("ok"):
                attempt["error"] = (out.get("stderr") or out.get("stdout") or "")[-400:]
                attempts.append(attempt)
                continue
            try:
                parsed = json.loads(str(out.get("stdout") or "{}"))
            except json.JSONDecodeError as exc:
                attempt["error"] = f"invalid helper JSON: {exc}"
                attempt["stdout_preview"] = str(out.get("stdout") or "")[:400]
                attempts.append(attempt)
                continue
            if not isinstance(parsed, dict):
                attempt["error"] = "helper output is not a JSON object"
                attempts.append(attempt)
                continue
            parsed["container"] = container
            parsed["python"] = binary
            parsed["attempts"] = attempts + [attempt]
            return parsed
    return {
        "ok": False,
        "url": url,
        "error": "no running stack container with python could query the internal endpoint",
        "attempts": attempts,
    }


def stack_observability_loki_labels(candidates: list[str], start_ns: int, end_ns: int) -> dict[str, Any]:
    params = urllib.parse.urlencode({"start": str(start_ns), "end": str(end_ns)})
    url = f"{STACK_OBSERVABILITY_LOKI_URL.rstrip('/')}/loki/api/v1/labels?{params}"
    response = stack_observability_podman_http(url, candidates, accept_json=True)
    payload = response.get("json") if isinstance(response.get("json"), dict) else {}
    labels = payload.get("data") if isinstance(payload.get("data"), list) else []
    return {
        "ok": bool(response.get("ok") and payload.get("status") == "success"),
        "url": url,
        "container": response.get("container"),
        "status": payload.get("status"),
        "labels": sorted(str(item) for item in labels if isinstance(item, str))[:128],
        "label_count": len(labels),
        "error": response.get("error"),
        "http": {
            "status_code": response.get("status_code"),
            "elapsed_ms": response.get("elapsed_ms"),
        },
    }


def stack_observability_logql_query(query: str, candidates: list[str], start_ns: int, end_ns: int) -> dict[str, Any]:
    params = urllib.parse.urlencode({
        "query": query,
        "start": str(start_ns),
        "end": str(end_ns),
        "limit": "3",
        "direction": "backward",
    })
    url = f"{STACK_OBSERVABILITY_LOKI_URL.rstrip('/')}/loki/api/v1/query_range?{params}"
    response = stack_observability_podman_http(url, candidates, accept_json=True)
    payload = response.get("json") if isinstance(response.get("json"), dict) else {}
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    streams = data.get("result") if isinstance(data.get("result"), list) else []
    samples: list[dict[str, Any]] = []
    entries = 0
    for stream in streams[:5]:
        if not isinstance(stream, dict):
            continue
        labels = stream.get("stream") if isinstance(stream.get("stream"), dict) else {}
        values = stream.get("values") if isinstance(stream.get("values"), list) else []
        entries += len(values)
        for value in values[:3]:
            if not isinstance(value, list) or len(value) < 2:
                continue
            line = str(value[1])
            samples.append({
                "ts": value[0],
                "labels": {key: labels.get(key) for key in sorted(labels)[:8]},
                "line_hash": stable_hash_json(line, length=16),
                "line_preview": line[:180],
            })
    return {
        "ok": bool(response.get("ok") and payload.get("status") == "success"),
        "query": query,
        "url": url,
        "container": response.get("container"),
        "status": payload.get("status"),
        "result_type": data.get("resultType"),
        "stream_count": len(streams),
        "entry_count": entries,
        "samples": samples[:5],
        "error": response.get("error"),
        "http": {
            "status_code": response.get("status_code"),
            "elapsed_ms": response.get("elapsed_ms"),
        },
    }


def stack_bridge_observability(write_latest: bool = True) -> dict[str, Any]:
    global STACK_BRIDGE_OBSERVABILITY_CACHE
    if STACK_BRIDGE_OBSERVABILITY_CACHE is not None:
        return json.loads(json.dumps(STACK_BRIDGE_OBSERVABILITY_CACHE))
    generated_at = now_iso()
    container_health = process_container_health(write_latest=False)
    container_status = stack_observability_expected_containers(container_health)
    exec_candidates = stack_observability_exec_candidates(container_health)
    end_ns = int(time.time() * 1_000_000_000)
    start_ns = end_ns - 15 * 60 * 1_000_000_000

    promql_targets = stack_observability_prometheus_query('up{job=~"loki|alloy|grafana|prometheus"}')
    promql_jobs: dict[str, Any] = {}
    for item in promql_targets.get("results", []):
        if not isinstance(item, dict):
            continue
        metric = item.get("metric") if isinstance(item.get("metric"), dict) else {}
        job = metric.get("job")
        if job:
            promql_jobs[str(job)] = item.get("value")
    expected_jobs = {"prometheus", "grafana", "loki", "alloy"}
    promql_missing = sorted(expected_jobs - set(promql_jobs))
    promql_down = sorted(job for job in expected_jobs if str(promql_jobs.get(job)) not in {"1", "1.0"})

    grafana = stack_observability_grafana_health()
    loki_ready = stack_observability_podman_http(
        f"{STACK_OBSERVABILITY_LOKI_URL.rstrip('/')}/ready",
        exec_candidates,
        accept_json=False,
        timeout=4.0,
        max_bytes=32768,
    )
    loki_labels = stack_observability_loki_labels(exec_candidates, start_ns, end_ns)
    logql_samples = [
        stack_observability_logql_query('{container="route-api"}', exec_candidates, start_ns, end_ns),
        stack_observability_logql_query('{source="podman-journal-event"}', exec_candidates, start_ns, end_ns),
    ]
    traceparent_logql = stack_observability_logql_query(
        '{container=~"route-api|rag-api|langchain-api"} |= "traceparent"',
        exec_candidates,
        start_ns,
        end_ns,
    )

    required_failures = []
    if not container_status.get("ok"):
        required_failures.append("required_containers")
    if not promql_targets.get("ok") or promql_missing or promql_down:
        required_failures.append("promql_targets")
    if not grafana.get("ok"):
        required_failures.append("grafana_health")
    if not loki_ready.get("ok"):
        required_failures.append("loki_ready")
    if not loki_labels.get("ok"):
        required_failures.append("loki_labels")
    if not any(sample.get("ok") and safe_int(sample.get("entry_count"), 0) > 0 for sample in logql_samples):
        required_failures.append("logql_samples")

    data = {
        "schema": f"{SCHEMA_PREFIX}_stack_observability_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": not required_failures,
        "status": "ready" if not required_failures else "degraded",
        "owner_boundary": {
            "stack_owner": "abyss-stack",
            "machine_role": "read_only_consumer",
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
        },
        "paths": {
            "latest": str(STACK_OBSERVABILITY_LATEST_PATH),
            "daily_glob": str(STACK_OBSERVABILITY_ROOT / "YYYY" / "MM" / "YYYY-MM-DD.jsonl"),
        },
        "endpoints": {
            "prometheus_host": STACK_OBSERVABILITY_PROMETHEUS_URL.rstrip("/"),
            "grafana_host": STACK_OBSERVABILITY_GRAFANA_URL.rstrip("/"),
            "loki_internal": STACK_OBSERVABILITY_LOKI_URL.rstrip("/"),
            "loki_internal_probe_container": loki_ready.get("container"),
        },
        "containers": container_status,
        "prometheus": {
            "promql": [promql_targets],
            "expected_jobs": sorted(expected_jobs),
            "jobs": promql_jobs,
            "missing_jobs": promql_missing,
            "down_jobs": promql_down,
        },
        "grafana": grafana,
        "loki": {
            "ready": {
                "ok": loki_ready.get("ok"),
                "status_code": loki_ready.get("status_code"),
                "container": loki_ready.get("container"),
                "text_preview": loki_ready.get("text_preview"),
                "error": loki_ready.get("error"),
            },
            "labels": loki_labels,
            "logql": logql_samples,
            "trace_context": traceparent_logql,
        },
        "alloy": {
            "evidence": "Prometheus up{job=\"alloy\"} plus Loki labels/log streams from journald ingestion.",
            "prometheus_value": promql_jobs.get("alloy"),
        },
        "summary": {
            "status": "ready" if not required_failures else "degraded",
            "required_failures": required_failures,
            "promql_jobs_up": sorted(job for job, value in promql_jobs.items() if str(value) in {"1", "1.0"}),
            "logql_queries_ok": sum(1 for item in logql_samples if item.get("ok")),
            "logql_entries_seen": sum(safe_int(item.get("entry_count"), 0) for item in logql_samples),
            "traceparent_log_query_ok": bool(traceparent_logql.get("ok")),
            "traceparent_log_entries_seen": safe_int(traceparent_logql.get("entry_count"), 0),
            "exec_candidates": exec_candidates[:8],
        },
        "non_claims": [
            "This command does not start, stop, restart, or reconfigure abyss-stack containers.",
            "This command does not read Grafana credentials or query authenticated Grafana datasource APIs.",
            "LogQL samples are truncated local evidence, not a full log export.",
        ],
    }
    if write_latest:
        errors = write_latest_and_history(data, STACK_OBSERVABILITY_LATEST_PATH, STACK_OBSERVABILITY_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
        STACK_BRIDGE_OBSERVABILITY_CACHE = json.loads(json.dumps(data))
    return data


