def self_awareness_container_http_probe(
    service: str,
    container: str,
    probe: str,
    url: str,
    *,
    method: str = "GET",
    request_json: dict[str, Any] | None = None,
    timeout: float = 4.0,
    max_bytes: int = 65536,
    expected_statuses: set[int] | None = None,
) -> dict[str, Any]:
    started = time.monotonic()
    if not command_exists("podman"):
        return {
            "service": service,
            "probe": probe,
            "container": container,
            "kind": "container_http_json",
            "ok": False,
            "url": url,
            "method": method.upper(),
            "error": "podman is not installed",
            "body_stored": False,
            "raw_private_content": False,
        }
    expected = expected_statuses or set(range(200, 400))
    script = r'''
import hashlib, json, sys, time, urllib.error, urllib.parse, urllib.request

url = sys.argv[1]
method = sys.argv[2].upper()
payload = sys.argv[3]
timeout = float(sys.argv[4])
max_bytes = int(sys.argv[5])

def compact_shape(value):
    if isinstance(value, dict):
        shape = {"type": "dict", "keys": sorted(str(key) for key in value.keys())[:32]}
        if isinstance(value.get("ok"), bool):
            shape["ok"] = value.get("ok")
        if isinstance(value.get("results"), list):
            results = value.get("results") or []
            shape["results"] = {
                "type": "list",
                "length": len(results),
                "item_keys": sorted(str(key) for key in results[0].keys())[:16] if results and isinstance(results[0], dict) else [],
            }
        if isinstance(value.get("url"), str):
            parsed = urllib.parse.urlparse(value.get("url"))
            shape["url_scheme"] = parsed.scheme
            shape["url_host_hash"] = hashlib.sha256((parsed.hostname or "").encode()).hexdigest()[:16]
        if isinstance(value.get("title"), str):
            shape["title_hash"] = hashlib.sha256(value.get("title", "").encode()).hexdigest()[:16]
        if isinstance(value.get("text"), str):
            text = value.get("text", "")
            shape["text_chars"] = len(text)
            shape["text_hash"] = hashlib.sha256(text.encode()).hexdigest()[:16]
        return shape
    if isinstance(value, list):
        return {"type": "list", "length": len(value)}
    return {"type": type(value).__name__}

headers = {"Accept": "application/json"}
data = None
if payload and payload != "null":
    data = payload.encode("utf-8")
    headers["Content-Type"] = "application/json"
started = time.monotonic()
result = {"url": url, "method": method}
try:
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    with urllib.request.urlopen(request, timeout=timeout) as response:
        body = response.read(max_bytes + 1)
        truncated = len(body) > max_bytes
        body = body[:max_bytes]
        text = body.decode("utf-8", "replace")
        result.update({
            "ok": 200 <= int(response.status) < 400,
            "status_code": int(response.status),
            "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1),
            "truncated": truncated,
            "content_hash": hashlib.sha256(body).hexdigest()[:24],
        })
        try:
            result["json_shape"] = compact_shape(json.loads(text))
        except Exception:
            result["text_preview_hash"] = hashlib.sha256(text[:512].encode()).hexdigest()[:16]
except urllib.error.HTTPError as exc:
    body = exc.read(max_bytes)
    text = body.decode("utf-8", "replace")
    result.update({
        "ok": False,
        "status_code": int(exc.code),
        "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1),
        "truncated": False,
        "error": str(exc),
        "content_hash": hashlib.sha256(body).hexdigest()[:24],
    })
    try:
        result["json_shape"] = compact_shape(json.loads(text))
    except Exception:
        result["text_preview_hash"] = hashlib.sha256(text[:512].encode()).hexdigest()[:16]
except Exception as exc:
    result.update({
        "ok": False,
        "status_code": None,
        "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1),
        "truncated": False,
        "error": str(exc)[:400],
    })
print(json.dumps(result, sort_keys=True))
'''
    payload = json.dumps(request_json, sort_keys=True) if request_json is not None else "null"
    out = run(
        ["podman", "exec", container, "python", "-c", script, url, method.upper(), payload, str(float(timeout)), str(int(max_bytes))],
        timeout=timeout + 8.0,
    )
    if not out.get("ok"):
        return {
            "service": service,
            "probe": probe,
            "container": container,
            "kind": "container_http_json",
            "ok": False,
            "url": url,
            "method": method.upper(),
            "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1),
            "error": self_awareness_redact_text(str(out.get("stderr") or out.get("stdout") or "podman exec failed"), 400),
            "returncode": out.get("returncode"),
            "body_stored": False,
            "raw_private_content": False,
            "policy": {
                "host_layer_mutates_stack": False,
                "writes_project_roots": False,
                "response_body_stored": False,
            },
        }
    try:
        response = json.loads(str(out.get("stdout") or "{}"))
    except json.JSONDecodeError as exc:
        response = {"ok": False, "error": f"invalid container probe JSON: {exc}", "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1)}
    status_code = safe_int(response.get("status_code"), 0)
    response["ok"] = bool(status_code in expected) if status_code else bool(response.get("ok"))
    return {
        "service": service,
        "probe": probe,
        "container": container,
        **self_awareness_http_probe_summary(response, "container_http_json"),
        "method": method.upper(),
        "expected_status_codes": sorted(expected),
        "raw_http_ok": bool(response.get("ok")) if status_code in set(range(200, 400)) else None,
        "content_hash": response.get("content_hash"),
        "execution_route": "podman_exec_container_loopback_http",
        "policy": {
            "semantic_read_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "response_body_stored": False,
            "raw_private_content": False,
        },
    }


def self_awareness_container_python_smoke(
    service: str,
    container: str,
    probe: str,
    script: str,
    *,
    timeout: float = 10.0,
) -> dict[str, Any]:
    started = time.monotonic()
    out = run(["podman", "exec", container, "python", "-c", script], timeout=timeout)
    stdout = str(out.get("stdout") or "")
    stderr = str(out.get("stderr") or "")
    return {
        "service": service,
        "probe": probe,
        "container": container,
        "kind": "container_runtime_smoke",
        "ok": bool(out.get("ok")),
        "url": f"container://{container}/{probe}",
        "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1),
        "returncode": out.get("returncode"),
        "stdout_hash": stable_hash_json(stdout, length=16) if stdout else None,
        "stderr_hash": stable_hash_json(stderr, length=16) if stderr else None,
        "error": self_awareness_redact_text(stderr or stdout, 400) if not out.get("ok") else None,
        "body_stored": False,
        "raw_private_content": False,
        "execution_route": "podman_exec_container_runtime_smoke",
        "policy": {
            "semantic_read_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "response_body_stored": False,
            "raw_private_content": False,
        },
    }


def self_awareness_tcp_probe(service: str, host: str, port: int, timeout: float = 1.2) -> dict[str, Any]:
    started = time.monotonic()
    ok = False
    error = None
    try:
        with socket.create_connection((host, int(port)), timeout=timeout):
            ok = True
    except OSError as exc:
        error = str(exc)
    return {
        "service": service,
        "probe": f"tcp:{host}:{port}",
        "kind": "tcp_ready",
        "ok": ok,
        "url": f"tcp://{host}:{port}",
        "elapsed_ms": round((time.monotonic() - started) * 1000.0, 1),
        "error": error,
        "body_stored": False,
        "raw_private_content": False,
    }


def self_awareness_working_stack_endpoint_probes(enabled: bool = True) -> list[dict[str, Any]]:
    if not enabled:
        return []
    probes: list[dict[str, Any]] = []

    def add_http_json(service: str, probe: str, url: str, timeout: float = 1.5, max_bytes: int = 131072) -> None:
        response = memory_orchestrate_http_json(url, timeout=timeout, max_bytes=max_bytes)
        probes.append({"service": service, "probe": probe, **self_awareness_http_probe_summary(response, "http_json")})

    def add_http_status(service: str, probe: str, url: str, timeout: float = 1.5) -> None:
        response = memory_orchestrate_http_status(url, timeout=timeout, max_bytes=65536)
        probes.append({"service": service, "probe": probe, **self_awareness_http_probe_summary(response, "http_status")})

    add_http_status("prometheus", "ready", f"{STACK_OBSERVABILITY_PROMETHEUS_URL.rstrip('/')}/-/ready")
    add_http_json("grafana", "health", f"{STACK_OBSERVABILITY_GRAFANA_URL.rstrip('/')}/api/health")
    add_http_status("tempo", "ready", "http://127.0.0.1:3200/ready")
    add_http_status("alertmanager", "ready", f"{SELF_AWARENESS_ALERTMANAGER_URL.rstrip('/')}/-/ready")
    add_http_json("alertmanager", "status", f"{SELF_AWARENESS_ALERTMANAGER_URL.rstrip('/')}/api/v2/status")
    add_http_json("route-api", "health", f"{SELF_AWARENESS_ROUTE_API_URL.rstrip('/')}/health")
    add_http_json("rag-api", "health", f"{SELF_AWARENESS_RAG_API_URL.rstrip('/')}/health")
    add_http_json("langchain-api", "health", f"{SELF_AWARENESS_LANGCHAIN_API_URL.rstrip('/')}/health")
    add_http_json("rerank-api", "health", "http://127.0.0.1:5405/health")
    add_http_json("qdrant", "collections", "http://127.0.0.1:6333/collections")
    add_http_json("ovms", "config", "http://127.0.0.1:8200/v1/config")
    add_http_status("ovms", "live", "http://127.0.0.1:8200/v2/health/live")
    add_http_json("llama-cpp", "health", "http://127.0.0.1:11435/health")
    probes.append(self_awareness_tcp_probe("postgres", SELF_AWARENESS_POSTGRES_HOST, SELF_AWARENESS_POSTGRES_PORT))
    probes.append(self_awareness_tcp_probe("redis", "127.0.0.1", 6379))
    probes.append(self_awareness_tcp_probe("neo4j", "127.0.0.1", 7687))
    return probes


def self_awareness_working_stack_container_tool_probes(runtime_by_service: dict[str, dict[str, Any]], enabled: bool = True) -> list[dict[str, Any]]:
    if not enabled:
        return []
    probes: list[dict[str, Any]] = []

    def container_for(service: str) -> str | None:
        runtime = runtime_by_service.get(service) if isinstance(runtime_by_service.get(service), dict) else {}
        if not runtime.get("running"):
            return None
        return str(runtime.get("container") or runtime.get("service") or "").strip() or None

    docs_container = container_for("docs-api")
    if docs_container:
        probes.append(self_awareness_container_http_probe(
            "docs-api",
            docs_container,
            "health",
            "http://127.0.0.1:5000/health",
            timeout=3.0,
        ))
        probes.append(self_awareness_container_http_probe(
            "docs-api",
            docs_container,
            "search:n8n-workflow",
            "http://127.0.0.1:5000/search?q=workflow",
            timeout=4.0,
        ))

    browser_container = container_for("aoa-browser")
    if browser_container:
        probes.append(self_awareness_container_http_probe(
            "aoa-browser",
            browser_container,
            "health",
            "http://127.0.0.1:8000/health",
            timeout=3.0,
        ))
        probes.append(self_awareness_container_http_probe(
            "aoa-browser",
            browser_container,
            "private-host-guard",
            "http://127.0.0.1:8000/read",
            method="POST",
            request_json={"url": "http://127.0.0.1:8000/health", "wait_ms": 50, "max_chars": 100},
            timeout=6.0,
            expected_statuses={403},
        ))
        probes.append(self_awareness_container_python_smoke(
            "aoa-browser",
            browser_container,
            "playwright-chromium-launch",
            "from playwright.sync_api import sync_playwright\nwith sync_playwright() as p:\n    browser = p.chromium.launch(headless=True)\n    browser.close()\nprint('launch_ok')",
            timeout=18.0,
        ))

    return probes


def self_awareness_working_stack_tts_smoke_evidence(max_age_seconds: int = 24 * 60 * 60) -> dict[str, Any]:
    paths = stack_paths()
    stack_root = Path(str(paths.get("srv_abyss_stack") or ""))
    tts_log_root = stack_root / "Logs" / "tts"
    base = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_working_stack_tts_smoke_evidence_v1",
        "ok": False,
        "root": str(tts_log_root),
        "policy": {
            "read_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "raw_text_stored": False,
            "raw_audio_stored": False,
        },
    }
    if not tts_log_root.exists():
        return {**base, "reason": "tts_log_root_missing"}

    sidecars = sorted(
        (path for path in tts_log_root.rglob("*.json") if path.is_file()),
        key=lambda path: path.stat().st_mtime if path.exists() else 0.0,
        reverse=True,
    )
    now_ts = time.time()
    for sidecar in sidecars[:64]:
        try:
            raw = sidecar.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        try:
            parsed = yaml.safe_load(raw) if yaml is not None else json.loads(raw)
        except Exception:
            continue
        if not isinstance(parsed, dict):
            continue
        model_id = str(parsed.get("model_id") or "")
        saved_path = str(parsed.get("saved_path") or "")
        if "Qwen3-TTS" not in model_id or not saved_path:
            continue
        wav_path = sidecar.with_suffix(".wav")
        if not wav_path.exists():
            continue
        try:
            sidecar_stat = sidecar.stat()
            wav_stat = wav_path.stat()
        except OSError:
            continue
        age_seconds = max(0.0, now_ts - max(sidecar_stat.st_mtime, wav_stat.st_mtime))
        if age_seconds > max_age_seconds:
            continue
        wav_format: dict[str, Any] = {}
        try:
            with wave.open(str(wav_path), "rb") as wav:
                wav_format = {
                    "channels": wav.getnchannels(),
                    "sample_width": wav.getsampwidth(),
                    "framerate": wav.getframerate(),
                    "frames": wav.getnframes(),
                }
        except (OSError, EOFError, wave.Error):
            continue
        if wav_stat.st_size <= 44 or wav_format.get("frames", 0) <= 0:
            continue
        return {
            **base,
            "ok": True,
            "sidecar_path": str(sidecar),
            "wav_path": str(wav_path),
            "age_seconds": round(age_seconds, 1),
            "wav_bytes": wav_stat.st_size,
            "wav_format": wav_format,
            "sidecar": {
                "agent_id": parsed.get("agent_id"),
                "voice_id": parsed.get("voice_id"),
                "model_id": model_id,
                "language": parsed.get("language"),
                "speaker": parsed.get("speaker"),
                "saved_path": saved_path,
                "host_rel_path": str(wav_path.relative_to(tts_log_root)) if is_relative_to_path(wav_path, tts_log_root) else wav_path.name,
                "text_hash": stable_hash_json(str(parsed.get("text") or ""), length=16) if parsed.get("text") else None,
                "ts": parsed.get("ts"),
            },
            "evidence_refs": [
                {"path": str(sidecar), "schema": "tts_router_sidecar_yaml", "service": "tts-router"},
                {"path": str(wav_path), "schema": "riff_wav_audio", "service": "qwen-tts"},
            ],
        }
    return {**base, "reason": "fresh_qwen_tts_sidecar_wav_pair_missing"}


def self_awareness_working_stack_tts_smoke_probes(enabled: bool = True) -> list[dict[str, Any]]:
    if not enabled:
        return []
    evidence = self_awareness_working_stack_tts_smoke_evidence()
    if evidence.get("ok") is not True:
        return []
    probes: list[dict[str, Any]] = []
    for service in ("qwen-tts", "tts-router"):
        probes.append({
            "service": service,
            "probe": "tts-synthesis-artifact",
            "kind": "artifact_receipt",
            "ok": True,
            "url": f"file://{evidence.get('wav_path')}",
            "body_stored": False,
            "raw_private_content": False,
            "semantic_read_only": True,
            "evidence": evidence,
            "evidence_refs": evidence.get("evidence_refs") if isinstance(evidence.get("evidence_refs"), list) else [],
            "policy": evidence.get("policy"),
        })
    return probes


def self_awareness_working_stack_probe_ok(probes: list[dict[str, Any]], service: str, probe: str) -> bool:
    return any(
        isinstance(item, dict)
        and item.get("service") == service
        and item.get("probe") == probe
        and item.get("ok") is True
        for item in probes
    )


def self_awareness_working_stack_tool_status(service: str, status: str, probes: list[dict[str, Any]]) -> str:
    if service in {"qwen-tts", "tts-router"}:
        if self_awareness_working_stack_probe_ok(probes, service, "tts-synthesis-artifact"):
            return "recent_on_demand_tool_signal"
    if service == "docs-api":
        if self_awareness_working_stack_probe_ok(probes, service, "health") and self_awareness_working_stack_probe_ok(probes, service, "search:n8n-workflow"):
            return "active_machine_tool_signal"
    if service == "aoa-browser":
        health_ok = self_awareness_working_stack_probe_ok(probes, service, "health")
        guard_ok = self_awareness_working_stack_probe_ok(probes, service, "private-host-guard")
        launch_probe_present = any(isinstance(item, dict) and item.get("service") == service and item.get("probe") == "playwright-chromium-launch" for item in probes)
        launch_ok = self_awareness_working_stack_probe_ok(probes, service, "playwright-chromium-launch")
        if health_ok and guard_ok and launch_ok:
            return "active_machine_tool_signal"
        if health_ok and guard_ok and launch_probe_present:
            return "tool_runtime_degraded"
        if health_ok and guard_ok:
            return "tool_guard_visible_unproven_deep_use"
    return status


def self_awareness_collect_stack_model_path_refs(value: Any, *, limit: int = 48) -> list[dict[str, Any]]:
    roots = tuple(str(path) for path in AI_MODEL_ROOTS)
    refs: list[dict[str, Any]] = []
    seen: set[str] = set()

    def visit(item: Any, depth: int = 0) -> None:
        if len(refs) >= limit or depth > 8:
            return
        if isinstance(item, dict):
            for key in ("path", "model_dir", "root", "local_path"):
                value = item.get(key)
                if isinstance(value, str):
                    visit(value, depth + 1)
            for value in item.values():
                if isinstance(value, (dict, list)):
                    visit(value, depth + 1)
            return
        if isinstance(item, list):
            for value in item:
                visit(value, depth + 1)
            return
        if not isinstance(item, str):
            return
        path = item.strip()
        if not path.startswith(roots) or path in seen:
            return
        seen.add(path)
        refs.append(self_awareness_stack_owned_source_ref(Path(path), "ai_capability_source_model"))

    visit(value)
    return refs


def self_awareness_model_row_paths(model_rows: list[dict[str, Any]]) -> list[str]:
    paths: list[str] = []
    seen: set[str] = set()
    for row in model_rows:
        if not isinstance(row, dict):
            continue
        candidates: list[Any] = [row.get("path")]
        candidates.extend(ref.get("path") for ref in row.get("stack_source_refs", []) if isinstance(ref, dict))
        for value in candidates:
            path = str(value or "").strip()
            if path and path not in seen:
                seen.add(path)
                paths.append(path)
    return paths


def self_awareness_paths_overlap(left: str, right: str) -> bool:
    left = left.rstrip("/")
    right = right.rstrip("/")
    if not left or not right:
        return False
    return left == right or left.startswith(right + "/") or right.startswith(left + "/")


def self_awareness_working_stack_model_bridge(
    service: str,
    model_rows: list[dict[str, Any]],
    ai_caps: dict[str, Any],
) -> dict[str, Any]:
    capability_key_by_service = {
        "embeddings": "embeddings",
        "stt": "stt",
        "tts": "tts",
        "llm-registry": "llm_text",
    }
    capability_key = capability_key_by_service.get(service)
    if not capability_key:
        return {}
    capabilities = ai_caps.get("capabilities") if isinstance(ai_caps.get("capabilities"), dict) else {}
    capability = capabilities.get(capability_key) if isinstance(capabilities.get(capability_key), dict) else {}
    status = str(capability.get("status") or "")
    ready_statuses = {"ready", "runtime-ready", "runtime-proven", "resident-running", "executable"}
    source_refs = self_awareness_collect_stack_model_path_refs(capability)
    source_paths = [str(ref.get("path")) for ref in source_refs if ref.get("path")]
    model_paths = self_awareness_model_row_paths(model_rows)
    linked_paths = [
        source_path for source_path in source_paths
        if any(self_awareness_paths_overlap(source_path, model_path) for model_path in model_paths)
    ]
    runtime_ready = status in ready_statuses or nested_get(capability, ["runtime", "ready"]) is True
    active = bool(runtime_ready and linked_paths)
    evidence_refs: list[dict[str, Any]] = [
        {"path": str(AI_CAPABILITIES_LATEST_PATH), "schema": ai_caps.get("schema"), "capability": capability_key},
    ]
    if service == "llm-registry":
        evidence_refs.append({"path": str(AI_LLM_REGISTRY_LATEST_PATH), "schema": f"{SCHEMA_PREFIX}_ai_llm_registry_v1"})
    if service == "tts":
        evidence_refs.extend([
            {"path": str(AI_TTS_PROFILES_LATEST_PATH), "schema": f"{SCHEMA_PREFIX}_ai_tts_profiles_v1"},
            {"path": str(AI_TTS_EVAL_LATEST_SUCCESS_PATH), "schema": f"{SCHEMA_PREFIX}_ai_tts_eval_v1"},
        ])
    return {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_working_stack_model_bridge_v1",
        "service": service,
        "capability": capability_key,
        "status": status,
        "active": active,
        "runtime_ready": runtime_ready,
        "primary_bridge": capability.get("primary_bridge") or capability.get("resident_bridge") or capability.get("eval_bridge"),
        "host_recommended_backend": capability.get("host_recommended_backend"),
        "model_root_count": len(model_rows),
        "stack_source_model_refs": source_refs[:12],
        "linked_stack_model_source_paths": linked_paths[:12],
        "evidence_refs": evidence_refs,
        "policy": {
            "read_only_source": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "model_promotion_decision": False,
        },
    }


