def self_awareness_langchain_api_probe() -> dict[str, Any]:
    base_url = SELF_AWARENESS_LANGCHAIN_API_URL.rstrip("/")
    health = memory_orchestrate_http_json(f"{base_url}/health", timeout=1.5, max_bytes=65536)
    openapi = memory_orchestrate_http_json(f"{base_url}/openapi.json", timeout=1.5, max_bytes=131072)
    openapi_json = openapi.get("json") if isinstance(openapi.get("json"), dict) else {}
    openapi_summary = self_awareness_openapi_summary(openapi_json)
    path_rows = openapi_summary.get("paths") if isinstance(openapi_summary.get("paths"), list) else []
    schema_names = openapi_summary.get("schema_names") if isinstance(openapi_summary.get("schema_names"), list) else []
    checkpoint_paths = openapi_summary.get("checkpoint_paths") if isinstance(openapi_summary.get("checkpoint_paths"), list) else []
    trace_paths = openapi_summary.get("trace_paths") if isinstance(openapi_summary.get("trace_paths"), list) else []
    health_json = health.get("json") if isinstance(health.get("json"), dict) else {}

    def route_matches(pattern: str) -> list[dict[str, Any]]:
        return [
            row for row in path_rows
            if isinstance(row, dict) and re.search(pattern, str(row.get("path") or ""), re.IGNORECASE)
        ]

    run_paths = [
        row for row in path_rows
        if isinstance(row, dict) and str(row.get("path") or "").rstrip("/") == "/run"
    ]
    federated_run_paths = [
        row for row in path_rows
        if isinstance(row, dict) and str(row.get("path") or "").rstrip("/") == "/run/federated"
    ]
    embeddings_paths = route_matches(r"embed")
    thread_paths = route_matches(r"thread")
    runtime_request_schema_names = [
        name for name in schema_names
        if re.search(r"RunReq|FederatedRunReq|EmbeddingsReq|Thread|Checkpoint|Trace", str(name), re.IGNORECASE)
    ][:32]
    missing_replay_inventory = [
        label for label, present in [
            ("threads", bool(thread_paths)),
            ("checkpoints", bool(checkpoint_paths)),
            ("traces", bool(trace_paths)),
        ]
        if not present
    ]
    runtime_surface = {
        "service": health_json.get("service"),
        "embeddings_provider": health_json.get("embeddings_provider"),
        "ovms_auth_enabled": health_json.get("ovms_auth_enabled"),
        "federated_run_enabled": health_json.get("federated_run_enabled"),
        "run_route_present": bool(run_paths),
        "federated_run_route_present": bool(federated_run_paths),
        "embeddings_route_present": bool(embeddings_paths),
        "runtime_request_schema_names": runtime_request_schema_names,
        "runnable_route_count": len(run_paths) + len(federated_run_paths),
        "usable_runtime_surface": bool(run_paths and embeddings_paths),
    }
    route_classes = {
        "run_paths": run_paths[:16],
        "federated_run_paths": federated_run_paths[:16],
        "embeddings_paths": embeddings_paths[:16],
        "thread_paths": thread_paths[:16],
        "checkpoint_paths": checkpoint_paths[:32],
        "trace_paths": trace_paths[:32],
    }
    replay_inventory = {
        "thread_inventory_present": bool(thread_paths),
        "checkpoint_inventory_present": bool(checkpoint_paths),
        "trace_inventory_present": bool(trace_paths),
        "inventory_complete": not missing_replay_inventory,
        "missing_inventory": missing_replay_inventory,
    }
    return {
        "schema": f"{SCHEMA_PREFIX}_stack_langchain_api_probe_v1",
        "base_url": base_url,
        "ok": bool(health.get("ok") and openapi.get("ok")),
        "health": {
            "url": health.get("url"),
            "ok": health.get("ok"),
            "status_code": health.get("status_code"),
            "service": health_json.get("service"),
            "embeddings_provider": health_json.get("embeddings_provider"),
            "ovms_auth_enabled": health_json.get("ovms_auth_enabled"),
            "federated_run_enabled": health_json.get("federated_run_enabled"),
            "error": health.get("error"),
        },
        "openapi": {
            "url": openapi.get("url"),
            "ok": openapi.get("ok"),
            "status_code": openapi.get("status_code"),
            "path_count": len(path_rows),
            "paths": path_rows[:64],
            "schema_names": schema_names[:64],
            "runtime_request_schema_names": runtime_request_schema_names,
            "thread_paths": thread_paths[:32],
            "checkpoint_paths": checkpoint_paths[:32],
            "trace_paths": trace_paths[:32],
            "error": openapi.get("error"),
            "truncated": openapi.get("truncated"),
        },
        "runtime_surface": runtime_surface,
        "route_classes": route_classes,
        "replay_inventory": replay_inventory,
        "trace_backend_coupling": {
            "required_for_trace_join": True,
            "candidate_ready_url": f"{SELF_AWARENESS_TEMPO_URL.rstrip()}/ready",
            "machine_checks_trace_backend_separately": True,
            "stack_owned_trace_backend_requirement": "stack.trace-backend",
        },
        "observability": {
            "health_readable": bool(health.get("ok")),
            "openapi_readable": bool(openapi.get("ok")),
            "runtime_surface_usable": runtime_surface["usable_runtime_surface"],
            "thread_inventory_present": replay_inventory["thread_inventory_present"],
            "checkpoint_inventory_present": replay_inventory["checkpoint_inventory_present"],
            "trace_inventory_present": replay_inventory["trace_inventory_present"],
            "missing_replay_inventory": missing_replay_inventory,
            "graph_observability_complete": bool(health.get("ok") and openapi.get("ok") and replay_inventory["inventory_complete"]),
        },
        "redaction": {
            "stores_openapi_summary_only": True,
            "stores_runtime_route_shape_only": True,
            "raw_prompt_payloads_stored": False,
            "raw_message_payloads_stored": False,
            "raw_tool_payloads_stored": False,
            "raw_trace_payloads_stored": False,
        },
        "evidence_refs": [
            {"url": health.get("url"), "status_code": health.get("status_code")},
            {"url": openapi.get("url"), "status_code": openapi.get("status_code")},
        ],
        "policy": {
            "read_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "raw_private_content": False,
        },
    }


def self_awareness_stack_closure_external_evidence(
    path: Path | None = None,
) -> dict[str, Any]:
    source_path = path or SELF_AWARENESS_STACK_CLOSURE_EVIDENCE_CONFIG_PATH
    schema = f"{SCHEMA_PREFIX}_self_awareness_stack_closure_external_evidence_v1"
    row_schema = f"{SCHEMA_PREFIX}_stack_requirement_closure_evidence_v1"
    exists = source_path.exists()
    if not exists:
        return {
            "schema": schema,
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": True,
            "status": "missing_optional_config",
            "config_path": str(source_path),
            "entries": {},
            "summary": {"entries": 0, "accepted": 0, "rejected": 0, "missing_optional_config": True},
            "policy": {
                "read_only": True,
                "host_layer_mutates_stack": False,
                "missing_config_is_not_failure": True,
                "raw_payloads_included": False,
                "raw_secrets_included": False,
            },
        }
    try:
        size_bytes = source_path.stat().st_size
    except OSError:
        size_bytes = None
    if size_bytes is not None and size_bytes > 512 * 1024:
        return {
            "schema": schema,
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": True,
            "status": "ignored_oversized_config",
            "config_path": str(source_path),
            "entries": {},
            "summary": {"entries": 0, "accepted": 0, "rejected": 1, "size_bytes": size_bytes},
            "policy": {
                "read_only": True,
                "host_layer_mutates_stack": False,
                "oversized_config_is_ignored": True,
                "raw_payloads_included": False,
                "raw_secrets_included": False,
            },
        }
    doc, error = load_json_document(source_path)
    if error:
        return {
            "schema": schema,
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": True,
            "status": "ignored_invalid_config",
            "config_path": str(source_path),
            "entries": {},
            "summary": {"entries": 0, "accepted": 0, "rejected": 1, "error": error},
            "policy": {
                "read_only": True,
                "host_layer_mutates_stack": False,
                "invalid_config_is_ignored": True,
                "raw_payloads_included": False,
                "raw_secrets_included": False,
            },
        }
    raw_entries: list[dict[str, Any]] = []
    if isinstance(doc.get("requirements"), dict):
        for key, value in doc["requirements"].items():
            if isinstance(value, dict):
                row = dict(value)
                row.setdefault("requirement_id", key)
                raw_entries.append(row)
    if isinstance(doc.get("entries"), dict):
        for key, value in doc["entries"].items():
            if isinstance(value, dict):
                row = dict(value)
                row.setdefault("requirement_id", key)
                raw_entries.append(row)
    elif isinstance(doc.get("entries"), list):
        raw_entries.extend(item for item in doc["entries"] if isinstance(item, dict))

    def compact_refs(refs: Any) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        if not isinstance(refs, list):
            return out
        for ref in refs[:24]:
            if not isinstance(ref, dict):
                continue
            clean: dict[str, Any] = {}
            for key in ("path", "url", "schema", "status_code", "probe", "locator", "sha256", "generated_at"):
                if key in ref:
                    clean[key] = ref.get(key)
            if clean:
                out.append(clean)
        return out

    def compact_current_state(state: Any) -> dict[str, Any]:
        if not isinstance(state, dict):
            return {}
        allowed = {
            "backend", "ready_status", "ready_status_code", "ready_url",
            "trace_id_query_supported", "traceparent_supported", "trace_backend_ready",
            "trace_search_readable", "trace_span_search_readable", "span_log_metric_join_supported",
            "alloy_pipeline_status", "loki_traceparent_query_status", "freshness_or_retention",
            "datasource_inventory_present", "datasource_inventory_count",
            "database_graph_inventory_route_present", "inventory_complete",
            "postgres_schema_inventory_present", "neo4j_graph_inventory_present",
            "stack_owned_postgres_schema_inventory_present",
            "stack_owned_neo4j_graph_inventory_present",
            "stack_owned_inventory_route_present",
            "thread_inventory_present", "checkpoint_inventory_present", "trace_inventory_present",
            "langchain_trace_backend_coupled", "langchain_langgraph_inventory_readable",
            "generated_at", "freshness", "source", "route", "export_path",
        }
        return {
            str(key): value
            for key, value in state.items()
            if str(key) in allowed and isinstance(value, (str, int, float, bool, type(None), list, dict))
        }

    entries: dict[str, dict[str, Any]] = {}
    for raw in raw_entries:
        requirement_id = str(raw.get("requirement_id") or raw.get("id") or "")
        if not requirement_id:
            continue
        policy = raw.get("policy") if isinstance(raw.get("policy"), dict) else {}
        checks = raw.get("checks") if isinstance(raw.get("checks"), dict) else {}
        current_state = compact_current_state(raw.get("current_state") if isinstance(raw.get("current_state"), dict) else raw.get("state"))
        evidence_refs = compact_refs(raw.get("evidence_refs"))
        preview = json.dumps(
            {
                "requirement_id": requirement_id,
                "checks": checks,
                "current_state": current_state,
                "evidence_refs": evidence_refs,
            },
            sort_keys=True,
            default=str,
        )[:50000]
        secret_like = bool(SELF_AWARENESS_SECRET_RE.search(preview))
        owner_ok = str(raw.get("owner_route") or raw.get("source_owner") or raw.get("owner") or "") == "abyss-stack"
        schema_ok = raw.get("schema") in {row_schema, f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_closure_evidence_v1"}
        policy_ok = (
            policy.get("host_layer_mutates_stack") is False
            and policy.get("raw_secrets_included") is False
            and policy.get("raw_payloads_included") is False
            and (policy.get("bounded") is True or policy.get("bounded_evidence") is True or policy.get("read_only") is True)
        )
        checks_ok = isinstance(checks, dict) and bool(checks)
        accepted = bool(schema_ok and owner_ok and policy_ok and checks_ok and not secret_like)
        rejection_reasons = [
            reason for reason, ok in (
                ("schema", schema_ok),
                ("owner_route", owner_ok),
                ("policy", policy_ok),
                ("checks", checks_ok),
                ("no_secret_like_content", not secret_like),
            )
            if not ok
        ]
        entries[requirement_id] = {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_closure_external_evidence_row_v1",
            "requirement_id": requirement_id,
            "accepted": accepted,
            "rejection_reasons": rejection_reasons,
            "checks": checks if accepted else {},
            "current_state": current_state if accepted else {},
            "evidence_refs": evidence_refs,
            "source": {
                "config_path": str(source_path),
                "schema": raw.get("schema"),
                "owner_route": raw.get("owner_route") or raw.get("source_owner") or raw.get("owner"),
                "generated_at": raw.get("generated_at"),
            },
            "policy": {
                "read_only": True,
                "host_layer_mutates_stack": False,
                "raw_payloads_included": False,
                "raw_secrets_included": False,
                "accepted_only_after_policy_and_redaction_checks": True,
            },
        }
    return {
        "schema": schema,
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "status": "loaded",
        "config_path": str(source_path),
        "entries": entries,
        "summary": {
            "entries": len(entries),
            "accepted": sum(1 for row in entries.values() if row.get("accepted") is True),
            "rejected": sum(1 for row in entries.values() if row.get("accepted") is not True),
            "missing_optional_config": False,
            "size_bytes": size_bytes,
        },
        "policy": {
            "read_only": True,
            "host_layer_mutates_stack": False,
            "missing_config_is_not_failure": True,
            "raw_payloads_included": False,
            "raw_secrets_included": False,
        },
    }


def self_awareness_external_closure_row(raw: dict[str, Any], requirement_id: str) -> dict[str, Any]:
    external = raw.get("stack_closure_external_evidence") if isinstance(raw.get("stack_closure_external_evidence"), dict) else {}
    entries = external.get("entries") if isinstance(external.get("entries"), dict) else {}
    row = entries.get(requirement_id) if isinstance(entries.get(requirement_id), dict) else {}
    return row if row.get("accepted") is True else row


def self_awareness_trace_backend_probe(
    tempo_ready: dict[str, Any],
    stack_observability: dict[str, Any],
    closure_evidence: dict[str, Any] | None = None,
) -> dict[str, Any]:
    base_url = SELF_AWARENESS_TEMPO_URL.rstrip("/")
    search = memory_orchestrate_http_json(f"{base_url}/api/search?limit=1", timeout=1.2, max_bytes=65536)
    stack_summary = stack_observability.get("summary") if isinstance(stack_observability.get("summary"), dict) else {}
    prometheus = stack_observability.get("prometheus") if isinstance(stack_observability.get("prometheus"), dict) else {}
    loki = stack_observability.get("loki") if isinstance(stack_observability.get("loki"), dict) else {}
    alloy = stack_observability.get("alloy") if isinstance(stack_observability.get("alloy"), dict) else {}
    labels = nested_get(loki, ["labels", "labels"]) or []
    trace_context = loki.get("trace_context") if isinstance(loki.get("trace_context"), dict) else {}
    promql_jobs_up = stack_summary.get("promql_jobs_up") if isinstance(stack_summary.get("promql_jobs_up"), list) else []
    alloy_value = alloy.get("prometheus_value")
    alloy_seen = str(alloy_value) in {"1", "1.0"} or "alloy" in {str(item) for item in promql_jobs_up}
    loki_ready = bool(nested_get(loki, ["ready", "ok"]))
    loki_labels_readable = bool(nested_get(loki, ["labels", "ok"]))
    traceparent_query_ok = bool(trace_context.get("ok"))
    traceparent_entries = safe_int(trace_context.get("entry_count"), 0)
    trace_context_query_safe_empty = bool(traceparent_query_ok and traceparent_entries == 0)
    metrics_log_pipeline_readable = bool(alloy_seen and loki_ready and loki_labels_readable)
    trace_search_readable = bool(search.get("ok"))
    tempo_ready_status_code = safe_int(tempo_ready.get("status_code"), 0)
    tempo_ready_by_http_status = tempo_ready_status_code in {200, 204}
    backend_ready = bool(tempo_ready.get("ok") or tempo_ready_by_http_status)
    backend_ready_error = tempo_ready.get("error")
    external_entries = closure_evidence.get("entries") if isinstance(closure_evidence, dict) and isinstance(closure_evidence.get("entries"), dict) else {}
    external_trace = external_entries.get("stack.trace-backend") if isinstance(external_entries.get("stack.trace-backend"), dict) else {}
    external_accepted = external_trace.get("accepted") is True
    external_checks = external_trace.get("checks") if external_accepted and isinstance(external_trace.get("checks"), dict) else {}
    external_state = external_trace.get("current_state") if external_accepted and isinstance(external_trace.get("current_state"), dict) else {}
    if external_accepted:
        backend_ready = bool(
            backend_ready
            or external_checks.get("trace_backend_ready")
            or external_state.get("trace_backend_ready")
        )
        trace_search_readable = bool(
            trace_search_readable
            or external_checks.get("trace_span_search_readable")
            or external_checks.get("trace_search_readable")
            or external_state.get("trace_search_readable")
            or external_state.get("trace_span_search_readable")
        )
    span_log_metric_join_supported = bool(backend_ready and trace_search_readable and traceparent_query_ok)
    if external_accepted:
        span_log_metric_join_supported = bool(
            span_log_metric_join_supported
            or external_checks.get("span_log_metric_join_supported")
            or external_state.get("span_log_metric_join_supported")
        )
    external_evidence_refs = external_trace.get("evidence_refs") if isinstance(external_trace.get("evidence_refs"), list) else []
    return {
        "schema": f"{SCHEMA_PREFIX}_stack_trace_backend_probe_v1",
        "backend": {
            "kind": "tempo_or_compatible",
            "base_url": base_url,
            "ready": {
                "url": external_state.get("ready_url") or external_state.get("route") or tempo_ready.get("url") or f"{base_url}/ready",
                "ok": backend_ready,
                "status_code": external_state.get("ready_status_code") or tempo_ready.get("status_code"),
                "error": None if tempo_ready_by_http_status else backend_ready_error,
                "accepted_by_http_status": tempo_ready_by_http_status,
            },
            "search": {
                "url": search.get("url"),
                "ok": trace_search_readable,
                "status_code": search.get("status_code"),
                "error": search.get("error"),
                "truncated": search.get("truncated"),
            },
            "external_closure_evidence": {
                "accepted": external_accepted,
                "config_path": nested_get(external_trace, ["source", "config_path"]),
                "rejection_reasons": external_trace.get("rejection_reasons") if isinstance(external_trace.get("rejection_reasons"), list) else [],
            },
        },
        "pipeline_evidence": {
            "prometheus_jobs_up": [str(item) for item in promql_jobs_up[:32]],
            "alloy_seen": alloy_seen,
            "alloy_prometheus_value": alloy_value,
            "loki_ready": loki_ready,
            "loki_labels_readable": loki_labels_readable,
            "loki_label_count": safe_int(nested_get(loki, ["labels", "label_count"]), len(labels)),
            "loki_labels": [str(item) for item in labels[:32]],
            "logql_entries_seen": safe_int(stack_summary.get("logql_entries_seen"), 0),
            "metrics_log_pipeline_readable": metrics_log_pipeline_readable,
        },
        "trace_context": {
            "w3c_traceparent_parser_present": True,
            "traceparent_log_query": trace_context.get("query"),
            "traceparent_log_query_ok": traceparent_query_ok,
            "traceparent_log_entries_seen": traceparent_entries,
            "trace_context_query_safe_empty": trace_context_query_safe_empty,
            "trace_context_samples": [
                {
                    "ts": sample.get("ts"),
                    "labels": sample.get("labels"),
                    "line_hash": sample.get("line_hash"),
                }
                for sample in (trace_context.get("samples") if isinstance(trace_context.get("samples"), list) else [])[:3]
                if isinstance(sample, dict)
            ],
        },
        "join_readiness": {
            "trace_backend_ready": backend_ready,
            "trace_search_readable": trace_search_readable,
            "traceparent_queryable_in_logs": traceparent_query_ok,
            "span_log_metric_join_supported": span_log_metric_join_supported,
            "explicit_empty_traceparent_result": trace_context_query_safe_empty,
            "missing": [
                label for label, present in [
                    ("trace_backend_ready", backend_ready),
                    ("trace_search_readable", trace_search_readable),
                    ("span_log_metric_join_supported", span_log_metric_join_supported),
                ]
                if not present
            ],
        },
        "redaction": {
            "stores_backend_status_only": True,
            "stores_log_line_hashes_only": True,
            "raw_span_payloads_stored": False,
            "raw_log_exports_stored": False,
            "raw_trace_payloads_stored": False,
            "raw_secrets_stored": False,
        },
            "evidence_refs": [
                {"url": tempo_ready.get("url") or f"{base_url}/ready", "status_code": tempo_ready.get("status_code"), "error": None if tempo_ready_by_http_status else backend_ready_error, "probe": "tempo_ready"},
                {"url": search.get("url"), "status_code": search.get("status_code"), "error": search.get("error"), "probe": "tempo_search"},
                {"path": str(STACK_OBSERVABILITY_LATEST_PATH), "schema": stack_observability.get("schema"), "locator": "alloy"},
                {"path": str(STACK_OBSERVABILITY_LATEST_PATH), "schema": stack_observability.get("schema"), "locator": "loki.trace_context"},
            ] + external_evidence_refs,
        "policy": {
            "read_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "starts_trace_backend": False,
            "raw_private_content": False,
        },
    }


def self_awareness_trace_context_links_from_doc(
    name: str,
    doc: dict[str, Any],
    *,
    limit: int = 16,
) -> list[dict[str, Any]]:
    links: list[dict[str, Any]] = []
    seen: set[str] = set()

    def add_link(path: str, item: dict[str, Any]) -> None:
        context = item.get("context") if isinstance(item.get("context"), dict) else item
        traceparent = context.get("traceparent")
        trace_id = context.get("trace_id")
        span_id = context.get("span_id")
        synthetic_run_id = context.get("synthetic_run_id") or item.get("run_id")
        if not any((traceparent, trace_id, span_id, synthetic_run_id)):
            return
        row = {
            "source": name,
            "json_path": path,
            "event_id": item.get("event_id"),
            "episode_id": item.get("episode_id") or item.get("id"),
            "thread_id": item.get("thread_id") or context.get("thread_id"),
            "checkpoint_id": item.get("checkpoint_id") or context.get("checkpoint_id"),
            "signal": item.get("signal"),
            "service": nested_get(item, ["resource", "service"]) or item.get("service"),
            "traceparent": traceparent,
            "trace_id": trace_id,
            "span_id": span_id,
            "synthetic_run_id": synthetic_run_id,
        }
        digest = stable_hash_json(row, length=16)
        if digest in seen:
            return
        seen.add(digest)
        links.append({key: value for key, value in row.items() if value not in (None, "")})

    def visit(value: Any, path: str, depth: int = 0) -> None:
        if len(links) >= limit or depth > 8:
            return
        if isinstance(value, dict):
            if any(key in value for key in ("traceparent", "trace_id", "span_id", "synthetic_run_id")):
                add_link(path, value)
            context = value.get("context") if isinstance(value.get("context"), dict) else {}
            if any(key in context for key in ("traceparent", "trace_id", "span_id", "synthetic_run_id")):
                add_link(path, value)
            for key, child in value.items():
                if isinstance(child, (dict, list)):
                    visit(child, f"{path}.{key}" if path else str(key), depth + 1)
        elif isinstance(value, list):
            for index, child in enumerate(value[:128]):
                if isinstance(child, (dict, list)):
                    visit(child, f"{path}[{index}]", depth + 1)

    visit(doc, name)
    return links


def self_awareness_trace_context_fallback_complete(data: Any) -> bool:
    return (
        isinstance(data, dict)
        and data.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_trace_context_fallback_v1"
        and data.get("stack_requirement_id") == "stack.trace-backend"
        and nested_get(data, ["summary", "traceparent_log_query_ok"]) is True
        and nested_get(data, ["summary", "stack_requirement_not_closed_by_fallback"]) is True
        and nested_get(data, ["fallback", "loki_trace_context", "raw_log_exports_stored"]) is False
        and nested_get(data, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(data, ["policy", "writes_project_roots"]) is False
        and nested_get(data, ["policy", "closes_stack_requirement"]) is False
        and nested_get(data, ["policy", "adds_loki_labels"]) is False
        and nested_get(data, ["policy", "raw_span_payloads_stored"]) is False
        and nested_get(data, ["policy", "raw_log_exports_stored"]) is False
        and bool(data.get("evidence_refs"))
        and bool(data.get("safe_next_action"))
    )


def self_awareness_trace_context_fallback(
    write_latest: bool = True,
    *,
    stack_observability_doc: dict[str, Any] | None = None,
    requirement_probes_doc: dict[str, Any] | None = None,
    probe_doc: dict[str, Any] | None = None,
    context_doc: dict[str, Any] | None = None,
    timeline_doc: dict[str, Any] | None = None,
    episodes_doc: dict[str, Any] | None = None,
) -> dict[str, Any]:
    generated_at = now_iso()
    stack_observability_doc = (
        stack_observability_doc
        if isinstance(stack_observability_doc, dict)
        else stack_bridge_observability(write_latest=True)
    )
    requirement_probes_doc = (
        requirement_probes_doc
        if isinstance(requirement_probes_doc, dict)
        else self_awareness_requirement_probes(write_latest=True)
    )
    probe_doc = probe_doc if isinstance(probe_doc, dict) else load_latest_json(SELF_AWARENESS_PROBE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_probe_v1")
    context_doc = context_doc if isinstance(context_doc, dict) else load_latest_json(SELF_AWARENESS_CONTEXT_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_context_v1")
    timeline_doc = timeline_doc if isinstance(timeline_doc, dict) else load_latest_json(SELF_AWARENESS_TIMELINE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_timeline_v1")
    episodes_doc = episodes_doc if isinstance(episodes_doc, dict) else load_latest_json(SELF_AWARENESS_EPISODES_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_episodes_v1")

    probes = requirement_probes_doc.get("probes") if isinstance(requirement_probes_doc.get("probes"), list) else []
    trace_probe = next(
        (
            probe
            for probe in probes
            if isinstance(probe, dict)
            and str(probe.get("id") or probe.get("requirement_id") or "") == "stack.trace-backend"
        ),
        {},
    )
    current_state = trace_probe.get("current_state") if isinstance(trace_probe.get("current_state"), dict) else {}
    closure_readiness = trace_probe.get("closure_readiness") if isinstance(trace_probe.get("closure_readiness"), dict) else {}
    trace_checks = {
        str(check.get("key")): check
        for check in (trace_probe.get("checks") if isinstance(trace_probe.get("checks"), list) else [])
        if isinstance(check, dict) and check.get("key")
    }
    if not current_state:
        capabilities_doc = load_latest_json(SELF_AWARENESS_CAPABILITIES_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_capabilities_v1")
        trace_backend = nested_get(capabilities_doc, ["raw", "trace_backend"])
        trace_backend = trace_backend if isinstance(trace_backend, dict) else {}
        join = trace_backend.get("join_readiness") if isinstance(trace_backend.get("join_readiness"), dict) else {}
        pipeline = trace_backend.get("pipeline_evidence") if isinstance(trace_backend.get("pipeline_evidence"), dict) else {}
        trace_ctx = trace_backend.get("trace_context") if isinstance(trace_backend.get("trace_context"), dict) else {}
        if join:
            current_state = {
                "requirement_status": "closed_by_current_probe" if join.get("span_log_metric_join_supported") is True else "open",
                "trace_backend_ready": join.get("trace_backend_ready"),
                "trace_search_readable": join.get("trace_search_readable"),
                "span_log_metric_join_supported": join.get("span_log_metric_join_supported"),
                "metrics_log_pipeline_readable": pipeline.get("metrics_log_pipeline_readable"),
                "traceparent_log_query_ok": trace_ctx.get("traceparent_log_query_ok"),
                "traceparent_log_entries_seen": trace_ctx.get("traceparent_log_entries_seen"),
                "trace_context_query_safe_empty": trace_ctx.get("trace_context_query_safe_empty"),
                "alloy_seen": pipeline.get("alloy_seen"),
                "loki_ready": pipeline.get("loki_ready"),
                "loki_labels_readable": pipeline.get("loki_labels_readable"),
            }
            trace_probe = {
                "id": "stack.trace-backend",
                "owner": "abyss-stack",
                "status": current_state["requirement_status"],
                "closed_by_current_probe": join.get("span_log_metric_join_supported") is True,
                "probe_kind": "capability_trace_backend",
                "current_state": current_state,
                "checks": [],
                "closure_readiness": {"missing_checks": join.get("missing") if isinstance(join.get("missing"), list) else []},
            }
            closure_readiness = trace_probe["closure_readiness"]
    stack_summary = stack_observability_doc.get("summary") if isinstance(stack_observability_doc.get("summary"), dict) else {}
    loki_trace = nested_get(stack_observability_doc, ["loki", "trace_context"])
    loki_trace = loki_trace if isinstance(loki_trace, dict) else {}
    traceparent_query_ok = bool(current_state.get("traceparent_log_query_ok") or loki_trace.get("ok"))
    traceparent_entries = safe_int(
        current_state.get("traceparent_log_entries_seen"),
        safe_int(loki_trace.get("entry_count"), 0),
    )
    trace_context_query_safe_empty = bool(
        current_state.get("trace_context_query_safe_empty")
        or (traceparent_query_ok and traceparent_entries == 0)
    )
    trace_backend_ready = bool(current_state.get("trace_backend_ready"))
    trace_search_readable = bool(current_state.get("trace_search_readable"))
    span_log_metric_join_supported = bool(current_state.get("span_log_metric_join_supported"))
    metrics_log_pipeline_readable = bool(current_state.get("metrics_log_pipeline_readable"))
    if not metrics_log_pipeline_readable:
        metrics_log_pipeline_readable = bool(
            "alloy" in {str(item) for item in (stack_summary.get("promql_jobs_up") if isinstance(stack_summary.get("promql_jobs_up"), list) else [])}
            and safe_int(stack_summary.get("logql_queries_ok"), 0) > 0
        )
    coverage_impact = self_awareness_stack_requirement_coverage_impact("stack.trace-backend")
    bounded_trace_links = (
        self_awareness_trace_context_links_from_doc("probe", probe_doc, limit=8)
        + self_awareness_trace_context_links_from_doc("context", context_doc, limit=8)
        + self_awareness_trace_context_links_from_doc("timeline", timeline_doc, limit=8)
        + self_awareness_trace_context_links_from_doc("episodes", episodes_doc, limit=8)
    )
    bounded_trace_links = bounded_trace_links[:24]
    probe_trace_context = {
        "run_id": probe_doc.get("run_id"),
        "traceparent": probe_doc.get("traceparent"),
        "trace_id": None,
        "span_id": None,
        "schema": probe_doc.get("schema"),
        "ok": probe_doc.get("ok"),
        "generated_at": probe_doc.get("generated_at"),
    }
    if probe_trace_context.get("traceparent"):
        parts = str(probe_trace_context["traceparent"]).split("-")
        if len(parts) >= 4:
            probe_trace_context["trace_id"] = parts[1]
            probe_trace_context["span_id"] = parts[2]
    status = (
        "stack_trace_backend_ready_observed"
        if trace_backend_ready and trace_search_readable and span_log_metric_join_supported
        else "fallback_ready_stack_trace_backend_open"
        if traceparent_query_ok and metrics_log_pipeline_readable
        else "fallback_degraded_stack_trace_backend_open"
    )
    trace_context_samples = [
        {
            "ts": sample.get("ts"),
            "labels": sample.get("labels"),
            "line_hash": sample.get("line_hash"),
        }
        for sample in (loki_trace.get("samples") if isinstance(loki_trace.get("samples"), list) else [])[:3]
        if isinstance(sample, dict)
    ]
    missing_checks = closure_readiness.get("missing_checks") if isinstance(closure_readiness.get("missing_checks"), list) else []
    open_requirements = requirement_probes_doc.get("open_requirements") if isinstance(requirement_probes_doc.get("open_requirements"), list) else []

    def open_requirement_id(row: dict[str, Any]) -> str:
        return str(row.get("id") or row.get("requirement_id") or "")

    def next_open_stack_requirement() -> dict[str, Any]:
        candidates = [
            row for row in open_requirements
            if isinstance(row, dict)
            and str(row.get("owner") or "abyss-stack") == "abyss-stack"
            and open_requirement_id(row)
        ]
        preferred_order = (
            "stack.grafana.datasource-read",
            "stack.database-graph.read-route",
            "stack.langchain-api.graph-observability",
            "stack.trace-backend",
        )
        for requirement_id in preferred_order:
            for row in candidates:
                if open_requirement_id(row) == requirement_id:
                    return row
        return candidates[0] if candidates else {}

    next_requirement = next_open_stack_requirement() if span_log_metric_join_supported else {}
    next_requirement_safe_action = (
        next_requirement.get("safe_next_action")
        if isinstance(next_requirement.get("safe_next_action"), dict)
        else {}
    )
    next_requirement_id = open_requirement_id(next_requirement)
    next_requirement_command_by_id = {
        "stack.grafana.datasource-read": "expose a stack-owned bounded Grafana datasource inventory route or read-only datasource export with secrets redacted",
        "stack.database-graph.read-route": "expose stack-owned bounded Postgres schema/freshness and Neo4j label/relationship/freshness inventory routes",
        "stack.langchain-api.graph-observability": "wire LangGraph/langchain-api thread, checkpoint, and trace inventory to the readable trace backend",
    }
    safe_next_requirement_id = (
        next_requirement_id
        if span_log_metric_join_supported and next_requirement_id
        else "stack.trace-backend"
    )
    safe_next_stack_command = (
        str(next_requirement_safe_action.get("stack_command_candidate") or next_requirement.get("summary") or next_requirement.get("title") or next_requirement_command_by_id.get(next_requirement_id) or "continue with the next open stack-owned self-awareness inventory route")
        if span_log_metric_join_supported and next_requirement_id
        else "configure/provide Tempo or compatible trace backend, W3C traceparent propagation, and bounded search route inside abyss-stack"
    )
    data = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_trace_context_fallback_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": bool(trace_probe and traceparent_query_ok and metrics_log_pipeline_readable),
        "status": status,
        "stack_requirement_id": "stack.trace-backend",
        "stack_requirement_status": trace_probe.get("status"),
        "closed_by_current_probe": trace_probe.get("closed_by_current_probe"),
        "closes_stack_requirement": False,
        "summary": {
            "status": status,
            "trace_backend_ready": trace_backend_ready,
            "trace_search_readable": trace_search_readable,
            "span_log_metric_join_supported": span_log_metric_join_supported,
            "metrics_log_pipeline_readable": metrics_log_pipeline_readable,
            "traceparent_log_query_ok": traceparent_query_ok,
            "traceparent_log_entries_seen": traceparent_entries,
            "trace_context_query_safe_empty": trace_context_query_safe_empty,
            "bounded_trace_context_links": len(bounded_trace_links),
            "stack_requirement_not_closed_by_fallback": True,
            "blocked_coverage_planes": [] if span_log_metric_join_supported else coverage_impact.get("coverage_planes"),
            "missing_checks": missing_checks,
            "next_open_stack_requirement_id": next_requirement_id if span_log_metric_join_supported else "stack.trace-backend",
        },
        "trace_backend_requirement": {
            "id": trace_probe.get("id") or "stack.trace-backend",
            "owner": trace_probe.get("owner") or "abyss-stack",
            "probe_kind": trace_probe.get("probe_kind"),
            "current_state": current_state,
            "checks": {
                key: {
                    "ok": value.get("ok"),
                    "level": value.get("level"),
                    "message": value.get("message"),
                }
                for key, value in trace_checks.items()
            },
            "closure_readiness": closure_readiness,
            "coverage_impact": coverage_impact,
        },
        "fallback": {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_trace_context_fallback_surface_v1",
            "loki_trace_context": {
                "query": loki_trace.get("query") or current_state.get("loki_traceparent_query"),
                "query_ok": traceparent_query_ok,
                "entries_seen": traceparent_entries,
                "safe_empty_result": trace_context_query_safe_empty,
                "samples": trace_context_samples,
                "stores_line_hashes_only": True,
                "raw_log_exports_stored": False,
            },
            "alloy_loki_pipeline": {
                "promql_jobs_up": stack_summary.get("promql_jobs_up") if isinstance(stack_summary.get("promql_jobs_up"), list) else [],
                "logql_queries_ok": stack_summary.get("logql_queries_ok"),
                "logql_entries_seen": stack_summary.get("logql_entries_seen"),
                "alloy_seen": bool(current_state.get("alloy_seen") or "alloy" in {str(item) for item in (stack_summary.get("promql_jobs_up") if isinstance(stack_summary.get("promql_jobs_up"), list) else [])}),
                "metrics_log_pipeline_readable": metrics_log_pipeline_readable,
            },
            "self_awareness_probe_trace": probe_trace_context,
            "bounded_trace_links": bounded_trace_links,
            "fallback_limit": (
                "Trace backend readiness and bounded search are observed; this surface remains a context packet, not the stack backend itself."
                if span_log_metric_join_supported
                else "Log/context trace evidence is readable, but span/log/metric joins remain unproven until stack.trace-backend closes."
            ),
        },
        "safe_next_action": {
            "owner_route": next_requirement_safe_action.get("owner_route") or "abyss-stack",
            "requirement_id": safe_next_requirement_id,
            "command": next_requirement_safe_action.get("command") or "abyss-machine self-awareness requirement-probes --json",
            "stack_command_candidate": safe_next_stack_command,
            "requires_human_approval": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "automatic": False,
        },
        "evidence_refs": [
            {"path": str(STACK_OBSERVABILITY_LATEST_PATH), "schema": stack_observability_doc.get("schema"), "section": "loki.trace_context"},
            {"path": str(SELF_AWARENESS_REQUIREMENT_PROBES_LATEST_PATH), "schema": requirement_probes_doc.get("schema"), "requirement_id": "stack.trace-backend"},
            {"path": str(SELF_AWARENESS_PROBE_LATEST_PATH), "schema": probe_doc.get("schema"), "run_id": probe_doc.get("run_id")},
            {"path": str(SELF_AWARENESS_CONTEXT_LATEST_PATH), "schema": context_doc.get("schema"), "section": "trace_contexts"},
            {"path": str(SELF_AWARENESS_TIMELINE_LATEST_PATH), "schema": timeline_doc.get("schema"), "section": "trace_contexts"},
            {"path": str(SELF_AWARENESS_EPISODES_LATEST_PATH), "schema": episodes_doc.get("schema"), "section": "trace_contexts"},
        ],
        "policy": {
            "read_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "closes_stack_requirement": False,
            "adds_loki_labels": False,
            "high_cardinality_labels_added": False,
            "raw_span_payloads_stored": False,
            "raw_log_exports_stored": False,
            "raw_trace_payloads_stored": False,
            "raw_private_content": False,
            "fallback_is_not_backend": True,
        },
        "tests": {
            "smoke": "abyss-machine self-awareness trace-context --json",
            "requirement_probe": "abyss-machine self-awareness requirement-probes --json",
            "cycle": "abyss-machine self-awareness cycle --json includes trace_context_fallback in chain",
            "validator": "abyss-machine self-awareness validate --json includes trace_context_fallback_depth",
        },
    }
    if write_latest:
        errors = write_latest_and_history(data, SELF_AWARENESS_TRACE_CONTEXT_LATEST_PATH, SELF_AWARENESS_TRACE_CONTEXT_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def self_awareness_redact_url_userinfo(value: Any) -> str | None:
    if not value:
        return None
    text = str(value)
    try:
        parsed = urllib.parse.urlsplit(text)
    except Exception:
        return text
    if not parsed.netloc or "@" not in parsed.netloc:
        return text
    host = parsed.hostname or ""
    if parsed.port:
        host = f"{host}:{parsed.port}"
    return urllib.parse.urlunsplit((parsed.scheme, host, parsed.path, parsed.query, parsed.fragment))


def self_awareness_grafana_datasource_entry(entry: dict[str, Any]) -> dict[str, Any]:
    safe_keys = {
        "id", "uid", "name", "type", "access", "url", "isDefault",
        "readOnly", "basicAuth", "database", "jsonData",
    }
    safe_json = entry.get("jsonData") if isinstance(entry.get("jsonData"), dict) else {}
    return {
        "id": entry.get("id") if "id" in safe_keys else None,
        "uid": entry.get("uid"),
        "name": entry.get("name"),
        "type": entry.get("type"),
        "access": entry.get("access"),
        "url": self_awareness_redact_url_userinfo(entry.get("url")),
        "is_default": entry.get("isDefault"),
        "read_only": entry.get("readOnly"),
        "basic_auth_enabled": bool(entry.get("basicAuth")),
        "json_data_keys": sorted(str(key) for key in safe_json.keys())[:32],
    }


def self_awareness_grafana_datasource_probe(
    grafana_health: dict[str, Any],
    grafana_datasources: dict[str, Any],
    stack_observability: dict[str, Any],
    alertmanager_status: dict[str, Any],
    trace_backend: dict[str, Any],
) -> dict[str, Any]:
    base_url = STACK_OBSERVABILITY_GRAFANA_URL.rstrip("/")
    stack_owned_inventory = memory_orchestrate_http_json(
        f"{SELF_AWARENESS_ROUTE_API_URL.rstrip()}/observability/datasources",
        timeout=1.5,
        max_bytes=131072,
    )
    extra_routes = {
        "search": "/api/search",
        "frontend_settings": "/api/frontend/settings",
        "dashboards_home": "/api/dashboards/home",
        "org": "/api/org",
    }
    route_probes = {
        key: memory_orchestrate_http_json(f"{base_url}{path}", timeout=1.5, max_bytes=65536)
        for key, path in extra_routes.items()
    }
    health_json = grafana_health.get("json") if isinstance(grafana_health.get("json"), dict) else {}
    datasource_payload = grafana_datasources.get("json")
    datasource_entries: list[dict[str, Any]] = []
    if isinstance(datasource_payload, list):
        datasource_entries = [
            self_awareness_grafana_datasource_entry(item)
            for item in datasource_payload[:256]
            if isinstance(item, dict)
        ]
    elif isinstance(datasource_payload, dict) and isinstance(datasource_payload.get("datasources"), list):
        datasource_entries = [
            self_awareness_grafana_datasource_entry(item)
            for item in datasource_payload["datasources"][:256]
            if isinstance(item, dict)
        ]
    stack_inventory_payload = stack_owned_inventory.get("json") if isinstance(stack_owned_inventory.get("json"), dict) else {}
    stack_inventory = stack_inventory_payload.get("datasource_inventory") if isinstance(stack_inventory_payload.get("datasource_inventory"), dict) else {}
    stack_inventory_entries = stack_inventory.get("entries") if isinstance(stack_inventory.get("entries"), list) else []
    stack_inventory_entries = [
        item for item in stack_inventory_entries[:256]
        if isinstance(item, dict)
    ]
    stack_inventory_redaction = stack_inventory_payload.get("redaction") if isinstance(stack_inventory_payload.get("redaction"), dict) else {}
    stack_inventory_safe = bool(
        stack_owned_inventory.get("ok")
        and stack_inventory.get("present")
        and safe_int(stack_inventory.get("count"), 0) > 0
        and stack_inventory_redaction.get("secure_json_data_included") is False
        and stack_inventory_redaction.get("passwords_included") is False
        and stack_inventory_redaction.get("tokens_included") is False
        and stack_inventory_redaction.get("raw_credentials_included") is False
    )
    if not datasource_entries and stack_inventory_safe:
        datasource_entries = stack_inventory_entries
    stack_summary = stack_observability.get("summary") if isinstance(stack_observability.get("summary"), dict) else {}
    jobs_up = {str(item) for item in (stack_summary.get("promql_jobs_up") if isinstance(stack_summary.get("promql_jobs_up"), list) else [])}
    loki = stack_observability.get("loki") if isinstance(stack_observability.get("loki"), dict) else {}
    trace_ready = bool(nested_get(trace_backend, ["join_readiness", "trace_backend_ready"]))
    inferred_candidates = [
        {
            "type": "prometheus",
            "name_hint": "Prometheus",
            "source": "live_prometheus_job",
            "route": STACK_OBSERVABILITY_PROMETHEUS_URL.rstrip("/"),
            "source_readable": "prometheus" in jobs_up,
            "closure_kind": "candidate_not_grafana_inventory",
        },
        {
            "type": "loki",
            "name_hint": "Loki",
            "source": "live_loki_internal_route",
            "route": STACK_OBSERVABILITY_LOKI_URL.rstrip("/"),
            "source_readable": bool(nested_get(loki, ["ready", "ok"])),
            "closure_kind": "candidate_not_grafana_inventory",
        },
        {
            "type": "alertmanager",
            "name_hint": "Alertmanager",
            "source": "live_alertmanager_api",
            "route": SELF_AWARENESS_ALERTMANAGER_URL.rstrip("/"),
            "source_readable": bool(alertmanager_status.get("ok")),
            "closure_kind": "candidate_not_grafana_inventory",
        },
        {
            "type": "tempo",
            "name_hint": "Tempo",
            "source": "trace_backend_requirement",
            "route": SELF_AWARENESS_TEMPO_URL.rstrip("/"),
            "source_readable": trace_ready,
            "closure_kind": "candidate_not_grafana_inventory",
        },
    ]
    route_statuses = {
        "datasources": {
            "url": grafana_datasources.get("url"),
            "ok": grafana_datasources.get("ok"),
            "status_code": grafana_datasources.get("status_code"),
            "error": grafana_datasources.get("error"),
        },
        "stack_owned_export": {
            "url": stack_owned_inventory.get("url"),
            "ok": stack_owned_inventory.get("ok"),
            "status_code": stack_owned_inventory.get("status_code"),
            "error": stack_owned_inventory.get("error"),
        },
        **{
            key: {
                "url": probe.get("url"),
                "ok": probe.get("ok"),
                "status_code": probe.get("status_code"),
                "error": probe.get("error"),
            }
            for key, probe in route_probes.items()
        },
    }
    denied_routes = [
        key for key, row in route_statuses.items()
        if safe_int(row.get("status_code"), 0) in {401, 403}
    ]
    readable_routes = [
        key for key, row in route_statuses.items()
        if row.get("ok") and safe_int(row.get("status_code"), 0) in range(200, 300)
    ]
    inventory_present = bool(datasource_entries)
    return {
        "schema": f"{SCHEMA_PREFIX}_stack_grafana_datasource_probe_v1",
        "base_url": base_url,
        "ok": bool(grafana_health.get("ok")),
        "health": {
            "url": grafana_health.get("url"),
            "ok": grafana_health.get("ok"),
            "status_code": grafana_health.get("status_code"),
            "database": health_json.get("database"),
            "version": health_json.get("version"),
            "commit": health_json.get("commit"),
            "error": grafana_health.get("error"),
        },
        "api_access": {
            "routes": route_statuses,
            "denied_routes": denied_routes,
            "readable_routes": readable_routes,
            "datasource_api_auth_denied": "datasources" in denied_routes,
            "all_inventory_routes_denied": bool(denied_routes) and not readable_routes,
        },
        "datasource_inventory": {
            "present": inventory_present,
            "count": len(datasource_entries),
            "entries": datasource_entries,
            "source": "stack_owned_route_api_export" if stack_inventory_safe else "grafana_api",
            "stack_owned_route_readable": bool(stack_owned_inventory.get("ok")),
            "stack_owned_route_safe": stack_inventory_safe,
        },
        "stack_owned_inventory": {
            "url": stack_owned_inventory.get("url"),
            "ok": stack_owned_inventory.get("ok"),
            "status_code": stack_owned_inventory.get("status_code"),
            "schema": stack_inventory_payload.get("schema"),
            "count": stack_inventory.get("count"),
            "types": stack_inventory.get("types") if isinstance(stack_inventory.get("types"), list) else [],
            "safe": stack_inventory_safe,
            "error": stack_owned_inventory.get("error"),
        },
        "inferred_datasource_candidates": inferred_candidates,
        "handoff": {
            "stack_owned_inventory_required": not inventory_present,
            "inferred_candidates_are_not_inventory": True,
            "acceptable_routes": [
                f"{base_url}/api/datasources with stack-owned read-only auth",
                f"{SELF_AWARENESS_ROUTE_API_URL.rstrip()}/observability/datasources",
            ],
        },
        "redaction": {
            "secure_json_data_stored": False,
            "passwords_stored": False,
            "tokens_stored": False,
            "url_userinfo_redacted": True,
            "raw_credentials_stored": False,
        },
        "evidence_refs": [
            {"url": grafana_health.get("url"), "status_code": grafana_health.get("status_code"), "probe": "grafana_health"},
            {"url": grafana_datasources.get("url"), "status_code": grafana_datasources.get("status_code"), "error": grafana_datasources.get("error"), "probe": "grafana_datasources"},
            {"url": stack_owned_inventory.get("url"), "status_code": stack_owned_inventory.get("status_code"), "error": stack_owned_inventory.get("error"), "probe": "stack_owned_grafana_datasource_inventory"},
            {"path": str(STACK_OBSERVABILITY_LATEST_PATH), "schema": stack_observability.get("schema"), "locator": "prometheus.jobs"},
            {"path": str(STACK_OBSERVABILITY_LATEST_PATH), "schema": stack_observability.get("schema"), "locator": "loki.ready"},
        ],
        "policy": {
            "read_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "stores_grafana_credentials": False,
            "uses_operator_token": False,
        },
    }


def self_awareness_requirement_item(
    requirement_id: str,
    title: str,
    *,
    owner: str = "abyss-stack",
    severity: str = "gap",
    reason: str,
    detection: dict[str, Any],
    expected_shape: dict[str, Any],
) -> dict[str, Any]:
    return {
        "id": requirement_id,
        "title": title,
        "owner": owner,
        "severity": severity,
        "reason": reason,
        "detection": detection,
        "expected_shape": expected_shape,
        "machine_action": "record_requirement_only",
        "host_layer_mutates_stack": False,
        "status": "open",
        "evidence_refs": detection.get("evidence_refs") if isinstance(detection.get("evidence_refs"), list) else [],
    }


def self_awareness_requirement_acceptance_contract(requirement: dict[str, Any]) -> dict[str, Any]:
    requirement_id = str(requirement.get("id") or "")
    expected_shape = requirement.get("expected_shape") if isinstance(requirement.get("expected_shape"), dict) else {}
    common_verifiers = [
        {
            "command": "abyss-machine self-awareness capabilities --json",
            "must": [
                f"open requirements exclude {requirement_id}",
                "the corresponding capability is available or explicitly optional",
                "evidence_refs cite the stack-owned route that closed the gap",
            ],
        },
        {
            "command": "abyss-machine self-awareness requirements --json",
            "must": [
                f"stack_handoff excludes {requirement_id}",
                "closed evidence does not contain raw credentials, tokens, prompts, row payloads, or private message bodies",
            ],
        },
        {
            "command": "abyss-machine self-awareness cycle --json",
            "must": [
                "open_stack_requirements decreases only after the stack-owned route is readable",
                "automatic_responses remains 0",
                "routes_with_mutating_command_if_run remains 0",
            ],
        },
        {
            "command": "abyss-machine self-awareness validate --json",
            "must": [
                "capability_map_and_requirements passes",
                "no_secret_leakage passes",
                "no_protected_root_writes passes",
            ],
        },
        {
            "command": "abyss-machine stack-bridge validate --json",
            "must": [
                "static bridge routes still expose self-awareness artifacts",
                "protected_write_claims remains empty",
            ],
        },
    ]
    common_must_not = [
        "abyss-machine must not write abyss-stack repos, dashboards, datasources, service configs, model roots, or runtime containers",
        "abyss-machine must not persist stack credentials or private payloads in latest/history artifacts",
        "abyss-machine must not treat an HTTP 2xx response as closure unless required fields and redaction rules also pass",
        "abyss-machine must not introduce high-cardinality Loki labels such as trace_id, request_id, session_id, span_id, or task_id",
    ]
    probe_plan: dict[str, Any] = {
        "kind": "generic_bounded_readonly_stack_inventory",
        "candidate_routes": ["stack-owned bounded read-only inventory endpoint"],
        "required_fields": ["status", "generated_at_or_freshness", "evidence_refs"],
        "success_predicates": [
            "route is read-only and stack-owned",
            "payload is bounded",
            "payload has evidence refs and freshness",
            "payload does not expose secrets or private raw data",
        ],
        "redaction_rules": ["no secrets", "no raw private payloads"],
    }
    if requirement_id == "stack.grafana.datasource-read":
        probe_plan = {
            "kind": "grafana_datasource_inventory",
            "candidate_routes": [
                f"{STACK_OBSERVABILITY_GRAFANA_URL.rstrip('/')}/api/health",
                f"{STACK_OBSERVABILITY_GRAFANA_URL.rstrip('/')}/api/search",
                f"{STACK_OBSERVABILITY_GRAFANA_URL.rstrip('/')}/api/frontend/settings",
                "http://127.0.0.1:3000/api/datasources with stack-owned read-only auth",
                "stack-owned bounded datasource inventory export consumed by abyss-machine",
            ],
            "required_fields": [
                "grafana.version",
                "grafana.database",
                "api_access.denied_routes",
                "inferred_candidates",
                "datasource_uid_or_id",
                "name",
                "type",
                "access_or_route",
                "is_default",
                "freshness_or_version",
                "readable_status",
            ],
            "success_predicates": [
                "Grafana health remains readable as liveness evidence",
                "source candidates inferred from Prometheus/Loki/Alertmanager are marked candidate-only and cannot close the requirement",
                "inventory route returns 2xx or a stack-owned exported artifact with at least one datasource",
                "datasource identity, type, and freshness can be cited by self-awareness correlation outputs",
                "secureJsonData, passwords, tokens, basic auth material, and raw URLs with credentials are absent or redacted",
            ],
            "redaction_rules": ["redact url userinfo", "omit secureJsonData", "omit passwords", "omit tokens"],
            "boundedness": {"max_datasources": 256, "raw_credentials_allowed": False},
        }
    elif requirement_id == "stack.trace-backend":
        probe_plan = {
            "kind": "trace_backend_inventory",
            "candidate_routes": [
                f"{SELF_AWARENESS_TEMPO_URL.rstrip()}/ready or equivalent ready endpoint",
                f"{SELF_AWARENESS_TEMPO_URL.rstrip()}/api/search or equivalent bounded trace search route",
                "Prometheus up{job=\"alloy\"} pipeline evidence",
                "bounded Loki LogQL traceparent query",
                "stack-owned bounded trace search/export route",
            ],
            "required_fields": [
                "backend",
                "ready_status",
                "trace_id_query_supported",
                "traceparent_supported",
                "alloy_pipeline_status",
                "loki_traceparent_query_status",
                "span_log_metric_join_supported",
                "freshness_or_retention",
            ],
            "success_predicates": [
                "ready endpoint reports healthy",
                "Alloy/Prometheus/Loki pipeline evidence remains readable as the metric/log side of the join",
                "W3C traceparent can be queried in logs with a bounded result or an explicit empty safe result",
                "W3C traceparent can connect at least one span/log/metric evidence chain after the trace backend is present",
                "trace evidence can be cited without changing stack runtime config",
            ],
            "redaction_rules": ["omit span attributes known to contain secrets", "hash log lines", "bound trace search result count"],
            "boundedness": {"max_spans_per_probe": 200, "max_log_samples": 3, "raw_payloads_allowed": False},
        }
    elif requirement_id == "stack.database-graph.read-route":
        probe_plan = {
            "kind": "database_graph_semantic_inventory",
            "candidate_routes": [
                f"{SELF_AWARENESS_ROUTE_API_URL.rstrip('/')}/health",
                f"{SELF_AWARENESS_ROUTE_API_URL.rstrip('/')}/openapi.json",
                f"{SELF_AWARENESS_RAG_API_URL.rstrip('/')}/health",
                f"{SELF_AWARENESS_RAG_API_URL.rstrip('/')}/openapi.json",
                f"{SELF_AWARENESS_RAG_API_URL.rstrip('/')}/collections",
                f"{SELF_AWARENESS_RAG_API_URL.rstrip('/')}/sources",
                f"{SELF_AWARENESS_RAG_API_URL.rstrip('/')}/agentic-rag/graph",
                f"{SELF_AWARENESS_NEO4J_URL.rstrip('/')}/",
                f"tcp://{SELF_AWARENESS_POSTGRES_HOST}:{SELF_AWARENESS_POSTGRES_PORT}",
                "stack-owned read-only Postgres schema/freshness inventory endpoint or export",
                "stack-owned read-only Neo4j label/relationship/freshness inventory endpoint or export",
            ],
            "required_fields": [
                "route_api.openapi_paths",
                "rag_api.collection_names",
                "rag_api.source_count",
                "rag_api.agentic_graph_shape",
                "postgres.tcp_ready",
                "postgres.schemas",
                "postgres.tables_or_relations",
                "postgres.freshness",
                "neo4j.version",
                "neo4j.labels",
                "neo4j.relationship_types",
                "neo4j.freshness",
                "inventory_generated_at",
            ],
            "success_predicates": [
                "route-api health and bounded OpenAPI remain readable as route/federation context",
                "rag-api health, bounded OpenAPI, collections, sources, and agentic graph shape remain readable",
                "Postgres service readiness and Neo4j root metadata are visible without storing credentials",
                "Postgres inventory exposes schema shape and freshness without row payloads by default",
                "Neo4j inventory exposes labels, relationship types, and freshness without private property values by default",
                "inventory is bounded and safe for self-awareness spatial graph overlays",
            ],
            "redaction_rules": ["omit row payloads", "omit private property values", "redact connection strings"],
            "boundedness": {"max_objects_per_store": 1000, "raw_rows_allowed": False, "raw_graph_properties_allowed": False},
        }
    elif requirement_id == "stack.langchain-api.graph-observability":
        probe_plan = {
            "kind": "langchain_langgraph_observability_inventory",
            "candidate_routes": [
                f"{SELF_AWARENESS_LANGCHAIN_API_URL.rstrip('/')}/health",
                f"{SELF_AWARENESS_LANGCHAIN_API_URL.rstrip('/')}/openapi.json",
                f"{SELF_AWARENESS_LANGCHAIN_API_URL.rstrip('/')}/run",
                f"{SELF_AWARENESS_LANGCHAIN_API_URL.rstrip('/')}/run/federated",
                f"{SELF_AWARENESS_LANGCHAIN_API_URL.rstrip('/')}/embeddings",
                f"{SELF_AWARENESS_TEMPO_URL.rstrip()}/ready",
                "stack-owned /threads inventory",
                "stack-owned /checkpoints inventory",
                "stack-owned /traces inventory",
            ],
            "required_fields": [
                "health.service",
                "health.embeddings_provider",
                "health.federated_run_enabled",
                "health.ovms_auth_enabled",
                "openapi_paths",
                "run_routes",
                "federated_run_routes",
                "embeddings_routes",
                "thread_count_or_ids",
                "checkpoint_count_or_ids",
                "latest_checkpoint_at",
                "thread_inventory_status",
                "checkpoint_inventory_status",
                "trace_inventory_status",
                "trace_backend_coupling",
                "freshness",
            ],
            "success_predicates": [
                "health endpoint reports langchain-api is serving",
                "OpenAPI inventory exposes bounded runtime route shape for run, federated run, and embeddings routes",
                "trace backend readiness or explicit equivalent trace inventory is visible for span/log/metric joins",
                "thread/checkpoint/trace inventories are read-only and bounded",
                "self-awareness investigation/replay can cite checkpoint inventory without storing prompt or message bodies",
            ],
            "redaction_rules": ["omit prompts", "omit messages", "omit tool payload bodies", "redact secrets in trace metadata"],
            "boundedness": {
                "max_threads": 200,
                "max_checkpoints": 500,
                "max_traces": 200,
                "raw_prompt_payloads_allowed": False,
                "raw_message_payloads_allowed": False,
                "raw_tool_payloads_allowed": False,
            },
        }
    return {
        "schema": f"{SCHEMA_PREFIX}_stack_requirement_acceptance_contract_v1",
        "requirement_id": requirement_id,
        "owner": requirement.get("owner") or "abyss-stack",
        "machine_role": "read_only_consumer",
        "status": requirement.get("status") or "open",
        "expected_shape": expected_shape,
        "probe_plan": probe_plan,
        "machine_verifiers": common_verifiers,
        "closure_semantics": {
            "no_partial_credit": True,
            "requires_current_evidence_refs": True,
            "requires_redaction_pass": True,
            "requires_stack_owned_route": True,
            "host_layer_mutates_stack": False,
        },
        "must_not": common_must_not,
    }


def self_awareness_stack_requirement_compat_contract(
    requirement: dict[str, Any],
    *,
    acceptance_contract: dict[str, Any] | None = None,
    readiness: dict[str, Any] | None = None,
    current_state: dict[str, Any] | None = None,
    coverage_impact: dict[str, Any] | None = None,
    dependency_requirement_ids: list[str] | None = None,
    unblocks_requirement_ids: list[str] | None = None,
) -> dict[str, Any]:
    requirement_id = str(requirement.get("id") or requirement.get("requirement_id") or "")
    owner = str(requirement.get("owner") or "abyss-stack")
    expected_shape = requirement.get("expected_shape") if isinstance(requirement.get("expected_shape"), dict) else {}
    acceptance_contract = acceptance_contract if isinstance(acceptance_contract, dict) else self_awareness_requirement_acceptance_contract(requirement)
    readiness = readiness if isinstance(readiness, dict) else {}
    current_state = current_state if isinstance(current_state, dict) else {}
    coverage_impact = coverage_impact if isinstance(coverage_impact, dict) else self_awareness_stack_requirement_coverage_impact(requirement_id)
    probe_plan = acceptance_contract.get("probe_plan") if isinstance(acceptance_contract.get("probe_plan"), dict) else {}
    machine_verifiers = acceptance_contract.get("machine_verifiers") if isinstance(acceptance_contract.get("machine_verifiers"), list) else []
    required_fields = probe_plan.get("required_fields") if isinstance(probe_plan.get("required_fields"), list) else []
    success_predicates = probe_plan.get("success_predicates") if isinstance(probe_plan.get("success_predicates"), list) else []
    redaction_rules = probe_plan.get("redaction_rules") if isinstance(probe_plan.get("redaction_rules"), list) else []
    boundedness = probe_plan.get("boundedness") if isinstance(probe_plan.get("boundedness"), dict) else {}
    candidate_routes = probe_plan.get("candidate_routes") if isinstance(probe_plan.get("candidate_routes"), list) else []
    blocking_check_keys = readiness.get("blocking_check_keys") if isinstance(readiness.get("blocking_check_keys"), list) else []
    if not blocking_check_keys:
        missing_checks = readiness.get("missing_checks") if isinstance(readiness.get("missing_checks"), list) else []
        blocking_check_keys = [str(item.get("key")) for item in missing_checks if isinstance(item, dict) and item.get("key")]
    dependency_requirement_ids = [str(item) for item in (dependency_requirement_ids if isinstance(dependency_requirement_ids, list) else readiness.get("dependency_requirement_ids") if isinstance(readiness.get("dependency_requirement_ids"), list) else [])]
    unblocks_requirement_ids = [str(item) for item in (unblocks_requirement_ids if isinstance(unblocks_requirement_ids, list) else [])]
    return {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_compat_contract_v1",
        "requirement_id": requirement_id,
        "owner_route": owner,
        "status": requirement.get("status") or readiness.get("status") or "open",
        "surface_kind": probe_plan.get("kind") or "bounded_stack_inventory",
        "expected_shape": expected_shape,
        "route_or_export_options": [str(item) for item in candidate_routes],
        "minimum_response_contract": {
            "required_fields": [str(item) for item in required_fields],
            "success_predicates": [str(item) for item in success_predicates],
            "current_blocking_check_keys": [str(item) for item in blocking_check_keys],
            "current_state_digest": stable_hash_json(current_state, length=24) if current_state else None,
        },
        "redaction_contract": {
            "rules": [str(item) for item in redaction_rules],
            "boundedness": boundedness,
            "forbidden_payloads": [
                "credentials",
                "tokens",
                "passwords",
                "raw prompts",
                "raw messages",
                "row payloads",
                "private graph property values",
                "raw trace payloads",
            ],
            "raw_secrets_allowed": False,
            "raw_private_payloads_allowed": False,
        },
        "machine_consumer_contract": {
            "consumer": "abyss-machine:self-awareness",
            "read_command": "abyss-machine self-awareness stack-closure-dossier --json",
            "probe_command": "abyss-machine self-awareness requirement-probes --json",
            "post_close_verifiers": machine_verifiers,
            "closure_requires_current_evidence": True,
            "closure_requires_redaction_pass": True,
            "no_partial_credit": True,
        },
        "dependency_contract": {
            "depends_on_requirement_ids": dependency_requirement_ids,
            "unblocks_requirement_ids": unblocks_requirement_ids,
            "dependency_order_is_handoff_guidance": True,
        },
        "coverage_contract": {
            "organ": coverage_impact.get("organ"),
            "coverage_planes": coverage_impact.get("coverage_planes") if isinstance(coverage_impact.get("coverage_planes"), list) else [],
            "closure_value": coverage_impact.get("closure_value"),
            "proof_commands": coverage_impact.get("proof_commands") if isinstance(coverage_impact.get("proof_commands"), list) else [],
        },
        "operator_boundary": {
            "stack_owner_may_mutate_stack_after_operator_approval": True,
            "abyss_machine_executes_stack_change": False,
            "host_layer_mutates_stack": False,
            "automatic_remediation": False,
        },
        "policy": {
            "handoff_only": True,
            "read_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "action_execution": False,
            "raw_secrets_included": False,
        },
    }


def self_awareness_stack_compat_contract_complete(contract: Any) -> bool:
    return (
        isinstance(contract, dict)
        and contract.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_stack_compat_contract_v1"
        and bool(contract.get("requirement_id"))
        and contract.get("owner_route") == "abyss-stack"
        and bool(contract.get("route_or_export_options"))
        and isinstance(nested_get(contract, ["minimum_response_contract", "required_fields"]), list)
        and bool(nested_get(contract, ["minimum_response_contract", "required_fields"]))
        and isinstance(nested_get(contract, ["minimum_response_contract", "success_predicates"]), list)
        and bool(nested_get(contract, ["minimum_response_contract", "success_predicates"]))
        and isinstance(nested_get(contract, ["redaction_contract", "rules"]), list)
        and bool(nested_get(contract, ["redaction_contract", "rules"]))
        and nested_get(contract, ["redaction_contract", "raw_secrets_allowed"]) is False
        and nested_get(contract, ["redaction_contract", "raw_private_payloads_allowed"]) is False
        and isinstance(nested_get(contract, ["machine_consumer_contract", "post_close_verifiers"]), list)
        and bool(nested_get(contract, ["machine_consumer_contract", "post_close_verifiers"]))
        and nested_get(contract, ["machine_consumer_contract", "closure_requires_current_evidence"]) is True
        and nested_get(contract, ["machine_consumer_contract", "closure_requires_redaction_pass"]) is True
        and nested_get(contract, ["coverage_contract", "organ"])
        and isinstance(nested_get(contract, ["coverage_contract", "coverage_planes"]), list)
        and bool(nested_get(contract, ["coverage_contract", "coverage_planes"]))
        and nested_get(contract, ["operator_boundary", "abyss_machine_executes_stack_change"]) is False
        and nested_get(contract, ["operator_boundary", "host_layer_mutates_stack"]) is False
        and nested_get(contract, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(contract, ["policy", "executes_commands"]) is False
        and nested_get(contract, ["policy", "raw_secrets_included"]) is False
    )


def self_awareness_stack_requirement_negative_controls(requirement_id: str) -> list[dict[str, Any]]:
    controls = [
        {
            "key": "http_2xx_without_required_fields_does_not_close",
            "must_fail_closure_when": "a route answers but omits required fields, freshness, evidence refs, or redaction status",
        },
        {
            "key": "host_inference_without_stack_owned_route_does_not_close",
            "must_fail_closure_when": "abyss-machine can infer a candidate route but no stack-owned bounded route/export exists",
        },
        {
            "key": "secret_or_private_payload_rejects_closure",
            "must_fail_closure_when": "credentials, tokens, raw prompts, row payloads, graph property values, or raw trace payloads appear",
        },
    ]
    per_requirement: dict[str, list[dict[str, Any]]] = {
        "stack.grafana.datasource-read": [
            {
                "key": "inferred_datasource_candidates_do_not_close",
                "must_fail_closure_when": "Prometheus/Loki/Alertmanager/Tempo candidates are inferred but Grafana datasource inventory is absent",
            },
            {
                "key": "grafana_secret_fields_do_not_close",
                "must_fail_closure_when": "secureJsonData, passwords, tokens, or URL userinfo are present in stored evidence",
            },
        ],
        "stack.trace-backend": [
            {
                "key": "ready_only_without_trace_search_does_not_close",
                "must_fail_closure_when": "backend readiness exists but bounded trace search/export or traceparent join evidence is absent",
            },
            {
                "key": "raw_span_or_log_payload_rejects_closure",
                "must_fail_closure_when": "raw span attributes or raw log exports are stored instead of bounded/redacted evidence",
            },
        ],
        "stack.database-graph.read-route": [
            {
                "key": "tcp_and_root_metadata_do_not_close",
                "must_fail_closure_when": "Postgres TCP and Neo4j root metadata are visible but bounded schema/label/freshness inventory is absent",
            },
            {
                "key": "raw_rows_or_graph_properties_reject_closure",
                "must_fail_closure_when": "row payloads or private graph property values are included in stored evidence",
            },
        ],
        "stack.langchain-api.graph-observability": [
            {
                "key": "health_openapi_run_routes_do_not_close",
                "must_fail_closure_when": "health/OpenAPI/run routes exist but thread, checkpoint, trace inventory, or trace coupling is missing",
            },
            {
                "key": "prompt_message_tool_payloads_reject_closure",
                "must_fail_closure_when": "prompts, messages, tool payload bodies, or raw trace payloads are included",
            },
        ],
    }
    return controls + per_requirement.get(requirement_id, [])


def self_awareness_stack_requirement_closure_acceptance(entry: dict[str, Any], generated_at: str) -> dict[str, Any]:
    requirement_id = str(entry.get("requirement_id") or entry.get("id") or "")
    readiness = entry.get("closure_readiness") if isinstance(entry.get("closure_readiness"), dict) else {}
    compat = entry.get("compat_contract") if isinstance(entry.get("compat_contract"), dict) else {}
    acceptance_contract = entry.get("acceptance_contract") if isinstance(entry.get("acceptance_contract"), dict) else {}
    coverage = entry.get("coverage_impact") if isinstance(entry.get("coverage_impact"), dict) else {}
    current_state = entry.get("current_state") if isinstance(entry.get("current_state"), dict) else {}
    missing_checks = entry.get("missing_checks") if isinstance(entry.get("missing_checks"), list) else readiness.get("missing_checks") if isinstance(readiness.get("missing_checks"), list) else []
    fulfilled_checks = entry.get("fulfilled_checks") if isinstance(entry.get("fulfilled_checks"), list) else readiness.get("fulfilled_checks") if isinstance(readiness.get("fulfilled_checks"), list) else []
    blocking_keys = entry.get("blocking_check_keys") if isinstance(entry.get("blocking_check_keys"), list) else readiness.get("blocking_check_keys") if isinstance(readiness.get("blocking_check_keys"), list) else []
    verifier_commands = entry.get("verifier_commands") if isinstance(entry.get("verifier_commands"), list) else readiness.get("verifier_commands") if isinstance(readiness.get("verifier_commands"), list) else []
    post_close_verifiers = nested_get(compat, ["machine_consumer_contract", "post_close_verifiers"])
    if not isinstance(post_close_verifiers, list):
        post_close_verifiers = acceptance_contract.get("machine_verifiers") if isinstance(acceptance_contract.get("machine_verifiers"), list) else []
    success_predicates = nested_get(compat, ["minimum_response_contract", "success_predicates"])
    if not isinstance(success_predicates, list):
        success_predicates = entry.get("success_predicates") if isinstance(entry.get("success_predicates"), list) else []
    route_or_export_options = compat.get("route_or_export_options") if isinstance(compat.get("route_or_export_options"), list) else []
    expected_post_close_facts = [
        f"{requirement_id} is absent from stack_handoff.open_requirement_ids after current stack-owned evidence is readable",
        f"{requirement_id} has closed_by_current_probe=true in requirement-probes or is no longer emitted as open",
        "self-awareness validate has 0 fails and no new warnings for this closure surface",
    ]
    packet = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_closure_acceptance_v1",
        "acceptance_id": "saclose-" + stable_hash_json({"requirement_id": requirement_id, "current_state": current_state, "blocking_keys": blocking_keys}, length=20),
        "requirement_id": requirement_id,
        "owner": entry.get("owner") or "abyss-stack",
        "status": "closed_by_current_probe" if entry.get("closed_by_current_probe") is True else "awaiting_stack_owner_change",
        "requirement_status": entry.get("status"),
        "surface_kind": compat.get("surface_kind") or entry.get("probe_kind"),
        "generated_at": generated_at,
        "pre_close_identity": {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_pre_close_identity_v1",
            "requirement_id": requirement_id,
            "status": entry.get("status"),
            "closed_by_current_probe": entry.get("closed_by_current_probe") is True,
            "current_state_digest": entry.get("current_state_digest") or stable_hash_json(current_state, length=24),
            "current_state_keys": sorted(str(key) for key in current_state.keys())[:80],
            "missing_check_keys": [str(item) for item in blocking_keys],
            "fulfilled_check_keys": [str(item.get("key")) for item in fulfilled_checks if isinstance(item, dict) and item.get("key")],
            "depends_on_requirement_ids": entry.get("depends_on_requirement_ids") if isinstance(entry.get("depends_on_requirement_ids"), list) else entry.get("dependency_requirement_ids") if isinstance(entry.get("dependency_requirement_ids"), list) else [],
            "unblocks_requirement_ids": entry.get("unblocks_requirement_ids") if isinstance(entry.get("unblocks_requirement_ids"), list) else [],
            "coverage_planes": coverage.get("coverage_planes") if isinstance(coverage.get("coverage_planes"), list) else [],
        },
        "stack_compat_requirement": {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_compat_requirement_v1",
            "requirement_id": requirement_id,
            "owner": "abyss-stack",
            "consumer": "abyss-machine:self-awareness",
            "surface_kind": compat.get("surface_kind") or entry.get("probe_kind") or "bounded_stack_inventory",
            "source_compat_contract_schema": compat.get("schema"),
            "source_compat_contract_digest": stable_hash_json(compat, length=24) if compat else None,
            "route_or_export_options": [str(item) for item in route_or_export_options],
            "minimum_response_contract": compat.get("minimum_response_contract") if isinstance(compat.get("minimum_response_contract"), dict) else {},
            "machine_consumer_contract": {
                "read_command": "abyss-machine self-awareness stack-closure-dossier --json",
                "probe_command": "abyss-machine self-awareness requirement-probes --json",
                "post_close_verifiers": post_close_verifiers,
                "expected_post_close_facts": expected_post_close_facts,
            },
            "dependency_contract": compat.get("dependency_contract") if isinstance(compat.get("dependency_contract"), dict) else {},
            "coverage_contract": compat.get("coverage_contract") if isinstance(compat.get("coverage_contract"), dict) else {},
            "redaction_contract": compat.get("redaction_contract") if isinstance(compat.get("redaction_contract"), dict) else {},
            "operator_boundary": {
                "operator_approval_required": True,
                "stack_owner_may_mutate_stack_after_operator_approval": True,
                "abyss_machine_executes_stack_change": False,
                "host_layer_mutates_stack": False,
                "automatic_remediation": False,
            },
        },
        "closure_diff_contract": {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_closure_diff_contract_v1",
            "before_missing_check_keys": [str(item) for item in blocking_keys],
            "after_required_state": [
                "blocking_check_keys is empty for this requirement or the requirement is not emitted as open",
                "closed_by_current_probe is true only when required fields, success predicates, redaction, boundedness, and evidence refs pass",
                "coverage planes previously blocked by this requirement have current evidence refs before they move to covered",
            ],
            "no_partial_credit_conditions": [
                "HTTP 2xx alone is not closure",
                "candidate-only inference is not closure",
                "health-only liveness is not closure unless the acceptance contract says so and verifier evidence is present",
                "secret/private/raw payload leakage rejects closure",
            ],
            "current_state_digest_before": entry.get("current_state_digest") or stable_hash_json(current_state, length=24),
        },
        "post_close_success_predicates": [str(item) for item in success_predicates],
        "post_close_verifier_chain": [
            {"command": command, "must": ["current bounded evidence proves this requirement closed without stack mutation"]}
            for command in verifier_commands
        ] + [
            item for item in post_close_verifiers
            if isinstance(item, dict)
        ],
        "negative_controls": self_awareness_stack_requirement_negative_controls(requirement_id),
        "safe_next_action": entry.get("safe_next_action") if isinstance(entry.get("safe_next_action"), dict) else {},
        "evidence_refs": entry.get("evidence_refs") if isinstance(entry.get("evidence_refs"), list) else [],
        "policy": {
            "handoff_only": entry.get("closed_by_current_probe") is not True,
            "read_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "action_execution": False,
            "automatic_remediation": False,
            "raw_secrets_included": False,
            "raw_private_payloads_included": False,
        },
    }
    packet["complete"] = self_awareness_stack_requirement_closure_acceptance_complete(packet)
    return packet


def self_awareness_stack_requirement_closure_acceptance_complete(packet: Any) -> bool:
    pre_close = packet.get("pre_close_identity") if isinstance(packet, dict) and isinstance(packet.get("pre_close_identity"), dict) else {}
    compat = packet.get("stack_compat_requirement") if isinstance(packet, dict) and isinstance(packet.get("stack_compat_requirement"), dict) else {}
    diff = packet.get("closure_diff_contract") if isinstance(packet, dict) and isinstance(packet.get("closure_diff_contract"), dict) else {}
    return (
        isinstance(packet, dict)
        and packet.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_closure_acceptance_v1"
        and bool(packet.get("requirement_id"))
        and packet.get("owner") == "abyss-stack"
        and pre_close.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_pre_close_identity_v1"
        and pre_close.get("requirement_id") == packet.get("requirement_id")
        and isinstance(pre_close.get("missing_check_keys"), list)
        and compat.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_compat_requirement_v1"
        and compat.get("requirement_id") == packet.get("requirement_id")
        and compat.get("owner") == "abyss-stack"
        and bool(compat.get("route_or_export_options"))
        and isinstance(nested_get(compat, ["machine_consumer_contract", "post_close_verifiers"]), list)
        and bool(nested_get(compat, ["machine_consumer_contract", "post_close_verifiers"]))
        and isinstance(nested_get(compat, ["machine_consumer_contract", "expected_post_close_facts"]), list)
        and bool(nested_get(compat, ["machine_consumer_contract", "expected_post_close_facts"]))
        and nested_get(compat, ["operator_boundary", "abyss_machine_executes_stack_change"]) is False
        and nested_get(compat, ["operator_boundary", "host_layer_mutates_stack"]) is False
        and nested_get(compat, ["operator_boundary", "automatic_remediation"]) is False
        and nested_get(compat, ["redaction_contract", "raw_secrets_allowed"]) is False
        and nested_get(compat, ["redaction_contract", "raw_private_payloads_allowed"]) is False
        and diff.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_closure_diff_contract_v1"
        and isinstance(packet.get("post_close_success_predicates"), list)
        and bool(packet.get("post_close_success_predicates"))
        and isinstance(packet.get("post_close_verifier_chain"), list)
        and bool(packet.get("post_close_verifier_chain"))
        and isinstance(packet.get("negative_controls"), list)
        and bool(packet.get("negative_controls"))
        and isinstance(packet.get("evidence_refs"), list)
        and bool(packet.get("evidence_refs"))
        and nested_get(packet, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(packet, ["policy", "executes_commands"]) is False
        and nested_get(packet, ["policy", "action_execution"]) is False
        and nested_get(packet, ["policy", "automatic_remediation"]) is False
        and nested_get(packet, ["policy", "raw_secrets_included"]) is False
    )


def self_awareness_requirement_handoff(requirement: dict[str, Any]) -> dict[str, Any]:
    requirement_id = str(requirement.get("id") or "")
    expected_shape = requirement.get("expected_shape") if isinstance(requirement.get("expected_shape"), dict) else {}
    acceptance_contract = self_awareness_requirement_acceptance_contract(requirement)
    compat_contract = self_awareness_stack_requirement_compat_contract(requirement, acceptance_contract=acceptance_contract)
    base = {
        "id": requirement_id,
        "requirement_id": requirement_id,
        "owner": requirement.get("owner"),
        "status": requirement.get("status"),
        "machine_read_command": "abyss-machine self-awareness requirements --json",
        "evidence_commands": [
            "abyss-machine self-awareness capabilities --json",
            "abyss-machine self-awareness failure-matrix --json",
            "abyss-machine self-awareness cycle --json",
            "abyss-machine self-awareness validate --json",
        ],
        "expected_shape": expected_shape,
        "acceptance_contract": acceptance_contract,
        "compat_contract": compat_contract,
        "machine_closure_probe": acceptance_contract.get("probe_plan"),
        "host_layer_mutates_stack": False,
        "acceptance_after_stack_change": [
            "abyss-machine self-awareness capabilities --json reports no open requirement for this id",
            "abyss-machine self-awareness requirements --json keeps evidence refs and owner route current",
            "abyss-machine self-awareness cycle --json preserves closed requirement state and non-mutating response policy",
            "abyss-machine self-awareness validate --json passes without new warnings",
            "abyss-machine stack-bridge validate --json passes without static bridge drift",
        ],
    }
    per_requirement: dict[str, Any] = {
        "stack.grafana.datasource-read": {
            "stack_acceptance": [
                "Grafana datasource inventory is available through a stack-owned read-only token or bounded inventory endpoint",
                "No Grafana credential is stored in abyss-machine latest/history artifacts",
                "Datasource identity and freshness can be cited by machine correlation outputs",
            ],
        },
        "stack.trace-backend": {
            "stack_acceptance": [
                "Tempo or compatible trace backend exposes a read-only health endpoint",
                "W3C traceparent joins can be searched or exported for span/log/metric correlation",
                "Trace backend evidence is available without abyss-machine modifying stack runtime config",
            ],
        },
        "stack.database-graph.read-route": {
            "stack_acceptance": [
                "route-api health and bounded OpenAPI remain readable as route/federation context",
                "rag-api health, bounded OpenAPI, collections, sources, and agentic graph shape remain readable without raw source documents",
                "Postgres service readiness and Neo4j root metadata are visible without storing database credentials",
                "Postgres schema/freshness inventory is exposed through a bounded read-only stack route",
                "Neo4j label/relationship/freshness inventory is exposed through a bounded read-only stack route",
                "Database and graph inventories are safe for machine correlation and do not expose private row payloads by default",
            ],
        },
        "stack.langchain-api.graph-observability": {
            "stack_acceptance": [
                "langchain-api health, OpenAPI, run, federated run, and embeddings route shape remain readable through stack-owned routes",
                "LangChain/LangGraph API exposes read-only thread, checkpoint, and trace inventory with freshness",
                "Trace backend or equivalent trace route is available for span/log/metric joins",
                "Checkpoint inventory can be cited by self-awareness investigation/replay outputs",
                "The API route is stack-owned and bounded; abyss-machine remains a read-only consumer and stores no prompts, messages, tool payloads, or raw trace payloads",
            ],
        },
    }
    base.update(per_requirement.get(requirement_id, {"stack_acceptance": ["Stack-owned route exposes the expected shape through a bounded read-only interface"]}))
    return base


def self_awareness_requirements_with_probe_readiness(
    requirements_doc: dict[str, Any],
    requirement_probes_doc: dict[str, Any],
) -> dict[str, Any]:
    if not isinstance(requirements_doc, dict) or not isinstance(requirement_probes_doc, dict):
        return requirements_doc
    if requirement_probes_doc.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_requirement_probes_v1":
        return requirements_doc
    if not self_awareness_requirement_probes_cover_requirements(requirements_doc, requirement_probes_doc):
        return requirements_doc

    probes = requirement_probes_doc.get("probes") if isinstance(requirement_probes_doc.get("probes"), list) else []
    probe_by_id = {
        str(probe.get("requirement_id") or probe.get("id")): probe
        for probe in probes
        if isinstance(probe, dict) and (probe.get("requirement_id") or probe.get("id"))
    }
    action_map = self_awareness_brief_stack_handoff_action_map(requirement_probes_doc)
    action_by_id = {
        str(action.get("requirement_id")): action
        for action in (action_map.get("actions") if isinstance(action_map.get("actions"), list) else [])
        if isinstance(action, dict) and action.get("requirement_id")
    }
    handoff_by_id = {
        str(handoff.get("requirement_id") or handoff.get("id")): handoff
        for handoff in (requirements_doc.get("stack_handoff") if isinstance(requirements_doc.get("stack_handoff"), list) else [])
        if isinstance(handoff, dict) and (handoff.get("requirement_id") or handoff.get("id"))
    }

    def compact_check(check: Any) -> dict[str, Any] | None:
        if not isinstance(check, dict):
            return None
        return {
            "key": check.get("key"),
            "level": check.get("level"),
            "ok": check.get("ok"),
            "message": check.get("message"),
        }

    def compact_readiness(requirement_id: str, probe: dict[str, Any], action: dict[str, Any]) -> dict[str, Any]:
        readiness = probe.get("closure_readiness") if isinstance(probe.get("closure_readiness"), dict) else {}
        missing_checks = [
            item for item in (compact_check(check) for check in (readiness.get("missing_checks") if isinstance(readiness.get("missing_checks"), list) else []))
            if item is not None
        ]
        fulfilled_checks = [
            item for item in (compact_check(check) for check in (readiness.get("fulfilled_checks") if isinstance(readiness.get("fulfilled_checks"), list) else []))
            if item is not None
        ]
        return {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_requirement_readiness_summary_v1",
            "requirement_id": requirement_id,
            "status": readiness.get("status") or probe.get("status"),
            "closed_by_current_probe": probe.get("closed_by_current_probe") is True,
            "readiness_score": readiness.get("readiness_score"),
            "fulfilled_check_count": safe_int(readiness.get("fulfilled_check_count"), len(fulfilled_checks)),
            "missing_check_count": safe_int(readiness.get("open_blocker_count"), len(missing_checks)),
            "blocking_check_keys": readiness.get("blocking_check_keys") if isinstance(readiness.get("blocking_check_keys"), list) else [],
            "missing_checks": missing_checks,
            "fulfilled_checks": fulfilled_checks,
            "dependency_requirement_ids": readiness.get("dependency_requirement_ids") if isinstance(readiness.get("dependency_requirement_ids"), list) else [],
            "runbook_candidate_id": readiness.get("runbook_candidate_id") or nested_get(probe, ["runbook_candidate", "id"]) or action.get("runbook_candidate_id"),
            "verifier_commands": readiness.get("verifier_commands") if isinstance(readiness.get("verifier_commands"), list) else action.get("verifier_commands") if isinstance(action.get("verifier_commands"), list) else [],
            "safe_next_action": readiness.get("safe_next_action") if isinstance(readiness.get("safe_next_action"), dict) else action.get("safe_next_action") if isinstance(action.get("safe_next_action"), dict) else {},
            "coverage_impact": action.get("coverage_impact") if isinstance(action.get("coverage_impact"), dict) else self_awareness_stack_requirement_coverage_impact(requirement_id),
            "evidence_refs": probe.get("evidence_refs") if isinstance(probe.get("evidence_refs"), list) else [],
            "policy": {
                "handoff_only": True,
                "host_layer_mutates_stack": False,
                "executes_commands": False,
                "raw_secrets_included": False,
            },
        }

    def first_list(*values: Any) -> list[Any]:
        for value in values:
            if isinstance(value, list) and value:
                return value
        return []

    def first_dict(*values: Any) -> dict[str, Any]:
        for value in values:
            if isinstance(value, dict) and value:
                return value
        return {}

    def current_state_digest(probe: dict[str, Any]) -> dict[str, Any]:
        current_state = probe.get("current_state") if isinstance(probe.get("current_state"), dict) else {}
        evidence_refs = probe.get("evidence_refs") if isinstance(probe.get("evidence_refs"), list) else []
        return {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_requirement_current_state_digest_v1",
            "has_current_state": bool(current_state),
            "keys": sorted(str(key) for key in current_state.keys())[:80],
            "evidence_refs": len(evidence_refs),
            "policy": {
                "raw_payloads_included": False,
                "raw_secrets_included": False,
                "host_layer_mutates_stack": False,
            },
        }

    def probe_effective_status(probe: dict[str, Any]) -> str:
        status = str(probe.get("status") or "")
        if probe.get("closed_by_current_probe") is True or status in {"closed", "closed_by_current_probe"}:
            return "closed"
        return status or "open"

    def probe_current_state_snapshot(probe: dict[str, Any]) -> dict[str, Any]:
        current_state = probe.get("current_state") if isinstance(probe.get("current_state"), dict) else {}
        if not current_state:
            return {}
        preview = json.dumps(current_state, sort_keys=True, default=str)[:50000]
        if SELF_AWARENESS_SECRET_RE.search(preview):
            return {
                "schema": f"{SCHEMA_PREFIX}_self_awareness_requirement_current_state_redacted_v1",
                "redacted_due_to_secret_pattern": True,
                "keys": sorted(str(key) for key in current_state.keys())[:80],
                "policy": {
                    "raw_payloads_included": False,
                    "raw_secrets_included": False,
                    "host_layer_mutates_stack": False,
                },
            }
        return current_state

    def add_direct_handoff_contract_fields(
        item: dict[str, Any],
        *,
        requirement_id: str,
        probe: dict[str, Any],
        action: dict[str, Any],
        source_handoff: dict[str, Any],
        readiness_summary: dict[str, Any],
    ) -> None:
        runbook = first_dict(
            probe.get("runbook_candidate"),
            action.get("runbook_candidate"),
        )
        fresh_requirement = dict(source_handoff)
        fresh_requirement.update(item)
        fresh_requirement["id"] = requirement_id
        fresh_requirement["requirement_id"] = requirement_id
        fresh_requirement["owner"] = fresh_requirement.get("owner") or "abyss-stack"
        effective_status = probe_effective_status(probe)
        fresh_requirement["status"] = effective_status
        fresh_contract = self_awareness_requirement_acceptance_contract(fresh_requirement)
        fresh_handoff = self_awareness_requirement_handoff(fresh_requirement)
        item["status"] = effective_status
        item["probe_status"] = str(probe.get("status") or effective_status)
        item["current_state"] = probe_current_state_snapshot(probe)
        item["evidence_refs"] = probe.get("evidence_refs") if isinstance(probe.get("evidence_refs"), list) else item.get("evidence_refs", [])
        item["acceptance_contract"] = fresh_contract
        item["machine_closure_probe"] = fresh_contract.get("probe_plan") if isinstance(fresh_contract.get("probe_plan"), dict) else {}
        item["acceptance_verifiers"] = fresh_contract.get("machine_verifiers") if isinstance(fresh_contract.get("machine_verifiers"), list) else []
        item["acceptance_after_stack_change"] = fresh_handoff.get("acceptance_after_stack_change") if isinstance(fresh_handoff.get("acceptance_after_stack_change"), list) else []
        item["stack_acceptance"] = first_list(
            fresh_handoff.get("stack_acceptance"),
            source_handoff.get("stack_acceptance"),
            nested_get(runbook, ["problem", "stack_acceptance"]),
        )
        item["coverage_impact"] = readiness_summary.get("coverage_impact") if isinstance(readiness_summary.get("coverage_impact"), dict) else self_awareness_stack_requirement_coverage_impact(requirement_id)
        item["safe_next_action"] = readiness_summary.get("safe_next_action") if isinstance(readiness_summary.get("safe_next_action"), dict) else {}
        item["current_state_digest"] = current_state_digest(probe)
        item["closed_by_current_probe"] = probe.get("closed_by_current_probe") is True
        item["handoff_contract_complete"] = (
            bool(item.get("acceptance_contract"))
            and bool(item.get("machine_closure_probe"))
            and bool(item.get("acceptance_verifiers"))
            and bool(item.get("coverage_impact"))
            and nested_get(item, ["policy", "host_layer_mutates_stack"]) is not True
        )

    enriched = dict(requirements_doc)
    requirements = []
    for requirement in requirements_doc.get("requirements", []) if isinstance(requirements_doc.get("requirements"), list) else []:
        if not isinstance(requirement, dict):
            requirements.append(requirement)
            continue
        requirement_id = str(requirement.get("id") or requirement.get("requirement_id") or "")
        probe = probe_by_id.get(requirement_id, {})
        action = action_by_id.get(requirement_id, {})
        source_handoff = handoff_by_id.get(requirement_id, {})
        item = dict(requirement)
        if isinstance(probe, dict) and probe:
            readiness_summary = compact_readiness(requirement_id, probe, action if isinstance(action, dict) else {})
            fresh_acceptance_contract = self_awareness_requirement_acceptance_contract(item)
            compat_contract = self_awareness_stack_requirement_compat_contract(
                item,
                acceptance_contract=fresh_acceptance_contract,
                readiness=probe.get("closure_readiness") if isinstance(probe.get("closure_readiness"), dict) else readiness_summary,
                current_state=probe.get("current_state") if isinstance(probe.get("current_state"), dict) else {},
                coverage_impact=readiness_summary.get("coverage_impact") if isinstance(readiness_summary.get("coverage_impact"), dict) else None,
                dependency_requirement_ids=readiness_summary.get("dependency_requirement_ids") if isinstance(readiness_summary.get("dependency_requirement_ids"), list) else [],
            )
            item["closure_readiness"] = readiness_summary
            item["missing_checks"] = readiness_summary["missing_checks"]
            item["blocking_check_keys"] = readiness_summary["blocking_check_keys"]
            item["runbook_candidate_id"] = readiness_summary["runbook_candidate_id"]
            item["verifier_commands"] = readiness_summary["verifier_commands"]
            item["compat_contract"] = compat_contract
            add_direct_handoff_contract_fields(
                item,
                requirement_id=requirement_id,
                probe=probe,
                action=action if isinstance(action, dict) else {},
                source_handoff=source_handoff if isinstance(source_handoff, dict) else {},
                readiness_summary=readiness_summary,
            )
        requirements.append(item)
    enriched["requirements"] = requirements

    stack_handoff = []
    for handoff in requirements_doc.get("stack_handoff", []) if isinstance(requirements_doc.get("stack_handoff"), list) else []:
        if not isinstance(handoff, dict):
            stack_handoff.append(handoff)
            continue
        requirement_id = str(handoff.get("id") or handoff.get("requirement_id") or "")
        probe = probe_by_id.get(requirement_id, {})
        action = action_by_id.get(requirement_id, {})
        item = dict(handoff)
        if isinstance(probe, dict) and probe:
            readiness_summary = compact_readiness(requirement_id, probe, action if isinstance(action, dict) else {})
            item["closure_readiness"] = readiness_summary
            item["missing_checks"] = readiness_summary["missing_checks"]
            item["blocking_check_keys"] = readiness_summary["blocking_check_keys"]
            item["runbook_candidate_id"] = readiness_summary["runbook_candidate_id"]
            item["verifier_commands"] = readiness_summary["verifier_commands"]
            item["safe_next_action"] = readiness_summary["safe_next_action"]
            item["coverage_impact"] = readiness_summary["coverage_impact"]
            fresh_acceptance_contract = self_awareness_requirement_acceptance_contract(item)
            item["compat_contract"] = self_awareness_stack_requirement_compat_contract(
                item,
                acceptance_contract=fresh_acceptance_contract,
                readiness=probe.get("closure_readiness") if isinstance(probe.get("closure_readiness"), dict) else readiness_summary,
                current_state=probe.get("current_state") if isinstance(probe.get("current_state"), dict) else {},
                coverage_impact=readiness_summary.get("coverage_impact") if isinstance(readiness_summary.get("coverage_impact"), dict) else None,
                dependency_requirement_ids=readiness_summary.get("dependency_requirement_ids") if isinstance(readiness_summary.get("dependency_requirement_ids"), list) else [],
            )
            add_direct_handoff_contract_fields(
                item,
                requirement_id=requirement_id,
                probe=probe,
                action=action if isinstance(action, dict) else {},
                source_handoff=handoff,
                readiness_summary=readiness_summary,
            )
        stack_handoff.append(item)
    enriched["stack_handoff"] = stack_handoff

    summary = dict(enriched.get("summary") if isinstance(enriched.get("summary"), dict) else {})
    closure_packets = [item.get("closure_readiness") for item in stack_handoff if isinstance(item, dict) and isinstance(item.get("closure_readiness"), dict)]
    open_stack_ids = [
        str(item.get("requirement_id") or item.get("id"))
        for item in stack_handoff
        if isinstance(item, dict)
        and (item.get("requirement_id") or item.get("id"))
        and item.get("owner") == "abyss-stack"
        and item.get("closed_by_current_probe") is not True
    ]
    closed_stack_ids = [
        str(item.get("requirement_id") or item.get("id"))
        for item in stack_handoff
        if isinstance(item, dict)
        and (item.get("requirement_id") or item.get("id"))
        and item.get("owner") == "abyss-stack"
        and item.get("closed_by_current_probe") is True
    ]
    summary.update({
        "open_stack_requirements": len(open_stack_ids),
        "closed_stack_requirements": len(closed_stack_ids),
        "stack_handoff_acceptance_verifiers": sum(1 for item in stack_handoff if isinstance(item, dict) and item.get("acceptance_verifiers")),
        "stack_handoff_acceptance_verifier_steps": sum(len(item.get("acceptance_verifiers") if isinstance(item.get("acceptance_verifiers"), list) else []) for item in stack_handoff if isinstance(item, dict)),
        "stack_handoff_closure_readiness_packets": len(closure_packets),
        "stack_handoff_closure_readiness_missing_checks": sum(safe_int(packet.get("missing_check_count"), 0) for packet in closure_packets),
        "stack_handoff_closure_readiness_fulfilled_checks": sum(safe_int(packet.get("fulfilled_check_count"), 0) for packet in closure_packets),
        "stack_handoff_runbook_candidates": sum(1 for item in stack_handoff if isinstance(item, dict) and item.get("runbook_candidate_id")),
        "stack_handoff_safe_next_actions": sum(1 for item in stack_handoff if isinstance(item, dict) and isinstance(item.get("safe_next_action"), dict) and item.get("safe_next_action")),
        "stack_handoff_coverage_impact_entries": sum(1 for item in stack_handoff if isinstance(item, dict) and isinstance(item.get("coverage_impact"), dict) and item.get("coverage_impact")),
        "stack_handoff_verifier_commands": len(sorted({
            str(command)
            for item in stack_handoff
            if isinstance(item, dict)
            for command in (item.get("verifier_commands") if isinstance(item.get("verifier_commands"), list) else [])
            if command
        })),
        "top_stack_handoff_requirement": nested_get(action_map, ["summary", "top_requirement_id"]),
    })
    enriched["summary"] = summary
    enriched["status"] = "open_requirements" if open_stack_ids else "satisfied"
    enriched["open_stack_ids"] = open_stack_ids
    enriched["open_stack_requirement_ids"] = open_stack_ids
    enriched["closed_stack_ids"] = closed_stack_ids
    enriched["closed_stack_requirement_ids"] = closed_stack_ids
    enriched["stack_handoff_closure_order"] = [
        {
            "rank": action.get("priority_rank"),
            "requirement_id": action.get("requirement_id"),
            "priority_class": action.get("priority_class"),
            "blocking_check_keys": action.get("closure_blocker_keys"),
            "runbook_candidate_id": action.get("runbook_candidate_id"),
            "verifier_commands": action.get("verifier_commands") if isinstance(action.get("verifier_commands"), list) else [],
            "acceptance_verifiers": action.get("acceptance_verifiers") if isinstance(action.get("acceptance_verifiers"), list) else [],
            "dependency_requirement_ids": action.get("dependency_requirement_ids") if isinstance(action.get("dependency_requirement_ids"), list) else [],
            "coverage_impact": action.get("coverage_impact") if isinstance(action.get("coverage_impact"), dict) else {},
            "safe_next_action": action.get("safe_next_action"),
        }
        for action in (action_map.get("actions") if isinstance(action_map.get("actions"), list) else [])
        if isinstance(action, dict)
    ]
    enriched["stack_handoff_action_summary"] = action_map.get("summary") if isinstance(action_map.get("summary"), dict) else {}
    enriched["evidence_refs"] = list(enriched.get("evidence_refs") if isinstance(enriched.get("evidence_refs"), list) else []) + [
        {"path": str(SELF_AWARENESS_REQUIREMENT_PROBES_LATEST_PATH), "schema": requirement_probes_doc.get("schema")},
    ]
    return enriched


def self_awareness_requirements_document(requirements: list[dict[str, Any]], generated_at: str) -> dict[str, Any]:
    by_owner = dict(collections.Counter(str(item.get("owner") or "unknown") for item in requirements))
    stack_handoff = [self_awareness_requirement_handoff(item) for item in requirements if item.get("owner") == "abyss-stack"]
    handoff_identity_ok = all(
        item.get("id") and item.get("requirement_id") == item.get("id")
        for item in stack_handoff
    )
    handoff_acceptance_ok = all(
        isinstance(item.get("acceptance_contract"), dict)
        and item["acceptance_contract"].get("schema") == f"{SCHEMA_PREFIX}_stack_requirement_acceptance_contract_v1"
        and isinstance(item.get("machine_closure_probe"), dict)
        and bool(item["machine_closure_probe"].get("required_fields"))
        and bool(item["machine_closure_probe"].get("success_predicates"))
        and item["acceptance_contract"].get("closure_semantics", {}).get("host_layer_mutates_stack") is False
        and self_awareness_stack_compat_contract_complete(item.get("compat_contract"))
        for item in stack_handoff
    )
    return {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_requirements_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": all(item.get("owner") and item.get("expected_shape") for item in requirements) and handoff_identity_ok and handoff_acceptance_ok,
        "status": "open_requirements" if requirements else "satisfied",
        "summary": {
            "requirements": len(requirements),
            "by_owner": by_owner,
            "stack_owned": sum(1 for item in requirements if item.get("owner") == "abyss-stack"),
            "machine_owned": sum(1 for item in requirements if item.get("owner") == "abyss-machine"),
            "stack_handoff_acceptance_contracts": sum(1 for item in stack_handoff if isinstance(item.get("acceptance_contract"), dict)),
            "stack_handoff_compat_contracts": sum(1 for item in stack_handoff if self_awareness_stack_compat_contract_complete(item.get("compat_contract"))),
        },
        "requirements": requirements,
        "stack_handoff": stack_handoff,
        "failure_matrix_latest": str(SELF_AWARENESS_FAILURE_MATRIX_LATEST_PATH),
        "cycle_latest": str(SELF_AWARENESS_CYCLE_LATEST_PATH),
        "policy": {
            "requirements_are_not_stack_mutations": True,
            "owner_route_required_before_runtime_change": True,
            "stack_handoff_is_machine_checkable": True,
        },
    }


def self_awareness_requirements(write_latest: bool = True) -> dict[str, Any]:
    if write_latest:
        self_awareness_capabilities(write_latest=True)
    data = load_latest_json(SELF_AWARENESS_REQUIREMENTS_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_requirements_v1")
    if not data.get("schema"):
        data = self_awareness_requirements_document([], now_iso())
    data = dict(data)
    requirement_probes = load_latest_json(SELF_AWARENESS_REQUIREMENT_PROBES_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_requirement_probes_v1")
    data = self_awareness_requirements_with_probe_readiness(data, requirement_probes)
    data["read_at"] = now_iso()
    data["command"] = "abyss-machine self-awareness requirements --json"
    data["ok"] = bool(data.get("ok")) and all(
        isinstance(item, dict)
        and item.get("owner")
        and item.get("expected_shape")
        and item.get("host_layer_mutates_stack") is False
        for item in data.get("requirements", [])
        if isinstance(item, dict)
    )
    if write_latest:
        errors = write_latest_and_history(data, SELF_AWARENESS_REQUIREMENTS_LATEST_PATH, SELF_AWARENESS_REQUIREMENTS_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def self_awareness_stack_requirement_runbook_candidate(
    requirement_id: str,
    handoff: dict[str, Any],
    probe_plan: dict[str, Any],
    current_state: dict[str, Any],
    evidence_refs: list[dict[str, Any]],
) -> dict[str, Any]:
    title = str(handoff.get("title") or requirement_id)
    contract = handoff.get("acceptance_contract") if isinstance(handoff.get("acceptance_contract"), dict) else {}
    stack_acceptance = handoff.get("stack_acceptance") if isinstance(handoff.get("stack_acceptance"), list) else []
    acceptance_after = handoff.get("acceptance_after_stack_change") if isinstance(handoff.get("acceptance_after_stack_change"), list) else []
    machine_verifiers = contract.get("machine_verifiers") if isinstance(contract.get("machine_verifiers"), list) else []
    affected_surfaces = ["abyss-stack runtime/config", "abyss-stack read-only API/export surface"]
    risks = ["stack-owned route may expose more evidence than intended if not bounded and redacted"]
    rollback_steps = [
        "revert the stack-owned endpoint, export, datasource auth policy, or service route that introduced the capability",
        "rerun abyss-machine self-awareness capabilities --json",
        "rerun abyss-machine self-awareness requirement-probes --json",
        "rerun abyss-machine self-awareness validate --json",
    ]
    if requirement_id == "stack.grafana.datasource-read":
        affected_surfaces = ["Grafana datasource inventory route", "Grafana read-only auth policy", "stack bridge datasource export"]
        risks = [
            "read-only auth token could be over-scoped",
            "datasource URLs could leak credentials if userinfo or secure fields are not stripped",
            "unbounded datasource export could include plugin-specific secret fields",
        ]
        rollback_steps.insert(0, "remove the stack-owned datasource inventory export or read-only token")
    elif requirement_id == "stack.trace-backend":
        affected_surfaces = ["Tempo or trace backend service", "OTel/Alloy trace pipeline", "trace retention storage"]
        risks = [
            "trace backend can increase storage and resource pressure",
            "span attributes can contain private payload fragments if instrumentation is not filtered",
            "partial trace propagation can create false confidence in causality",
        ]
        rollback_steps.insert(0, "disable the stack-owned trace backend route or trace pipeline change")
    elif requirement_id == "stack.database-graph.read-route":
        affected_surfaces = ["Postgres schema/freshness inventory route", "Neo4j label/relationship inventory route", "RAG/graph semantic inventory export"]
        risks = [
            "database inventory could accidentally include row payloads",
            "graph inventory could expose private property values",
            "large schema/graph exports can become expensive if not bounded",
        ]
        rollback_steps.insert(0, "remove the stack-owned database/graph inventory export or read-only route")
    elif requirement_id == "stack.langchain-api.graph-observability":
        affected_surfaces = ["langchain-api runtime route shape", "LangGraph thread/checkpoint inventory", "trace/checkpoint metadata export", "Tempo or equivalent trace backend coupling"]
        risks = [
            "checkpoint inventory could expose prompts, messages, or tool payload bodies",
            "trace inventory could expose raw span attributes or private payload fragments",
            "thread/checkpoint listing can become high-cardinality without limits",
            "health-only success can hide missing checkpoint, thread, trace, or backend inventory",
        ]
        rollback_steps.insert(0, "remove the stack-owned LangChain/LangGraph inventory route")
    acceptance_steps = [
        {"command": command.get("command"), "must": command.get("must")}
        for command in machine_verifiers
        if isinstance(command, dict)
    ] + [
        {"command": "abyss-machine self-awareness capabilities --json", "must": ["requirement is no longer open after stack-owned route is readable"]},
        {"command": "abyss-machine self-awareness requirement-probes --json", "must": ["closed_by_current_probe is true for this requirement or stack_handoff excludes it"]},
        {"command": "abyss-machine self-awareness validate --json", "must": ["0 fails and 0 new warnings"]},
        {"command": "abyss-machine stack-bridge validate --json", "must": ["0 fails and 0 new warnings"]},
    ]
    return {
        "schema": f"{SCHEMA_PREFIX}_stack_requirement_runbook_candidate_v1",
        "id": "stack-runbook-" + re.sub(r"[^a-z0-9]+", "-", requirement_id.lower()).strip("-"),
        "requirement_id": requirement_id,
        "title": title,
        "owner_route": "abyss-stack",
        "status": "candidate",
        "machine_action": "handoff_only",
        "source_command": "abyss-machine self-awareness requirement-probes --json",
        "host_layer_mutates_stack": False,
        "machine_executes_stack_change": False,
        "stack_owner_may_mutate_stack": True,
        "operator_approval_required": True,
        "problem": {
            "current_state": current_state,
            "stack_acceptance": stack_acceptance,
        },
        "proposed_stack_work": {
            "kind": probe_plan.get("kind"),
            "candidate_routes": probe_plan.get("candidate_routes") if isinstance(probe_plan.get("candidate_routes"), list) else [],
            "required_fields": probe_plan.get("required_fields") if isinstance(probe_plan.get("required_fields"), list) else [],
            "success_predicates": probe_plan.get("success_predicates") if isinstance(probe_plan.get("success_predicates"), list) else [],
            "redaction_rules": probe_plan.get("redaction_rules") if isinstance(probe_plan.get("redaction_rules"), list) else [],
            "boundedness": probe_plan.get("boundedness") if isinstance(probe_plan.get("boundedness"), dict) else {},
        },
        "acceptance_steps": acceptance_steps,
        "acceptance_verifiers": acceptance_steps,
        "acceptance_after_stack_change": acceptance_after,
        "risk": {
            "level": "medium",
            "risks": risks,
            "required_mitigations": [
                "bounded result size",
                "redaction rules enforced before abyss-machine stores evidence",
                "read-only route or exported inventory only",
                "no raw credentials, prompts, row payloads, or private graph properties",
            ],
        },
        "blast_radius": {
            "owner": "abyss-stack",
            "affected_surfaces": affected_surfaces,
            "not_affected": [
                "/usr/local/libexec/abyss-machine",
                "/var/lib/abyss-machine/self-awareness",
                "/srv/abyss-machine/tests",
            ],
        },
        "rollback": {
            "owner": "abyss-stack",
            "steps": rollback_steps,
            "machine_recovery": "discard/regenerate machine-owned latest artifacts; no stack rollback is executed by abyss-machine",
        },
        "evidence_refs": evidence_refs,
        "policy": {
            "automatic_execution": False,
            "requires_owner_gate": True,
            "abyss_machine_writes_stack": False,
            "raw_secret_storage": False,
        },
    }


def self_awareness_stack_requirement_runbook_complete(candidate: dict[str, Any], requirement_id: str) -> bool:
    if not isinstance(candidate, dict):
        return False
    return (
        candidate.get("schema") == f"{SCHEMA_PREFIX}_stack_requirement_runbook_candidate_v1"
        and candidate.get("requirement_id") == requirement_id
        and candidate.get("owner_route") == "abyss-stack"
        and candidate.get("machine_action") == "handoff_only"
        and candidate.get("host_layer_mutates_stack") is False
        and candidate.get("machine_executes_stack_change") is False
        and candidate.get("stack_owner_may_mutate_stack") is True
        and candidate.get("operator_approval_required") is True
        and bool(candidate.get("risk"))
        and bool(candidate.get("blast_radius"))
        and bool(candidate.get("rollback"))
        and bool(candidate.get("acceptance_steps"))
        and bool(candidate.get("acceptance_verifiers"))
        and bool(candidate.get("evidence_refs"))
    )


def self_awareness_stack_handoff_closure_readiness(
    *,
    requirement_id: str,
    status: str,
    probe_kind: Any,
    checks: list[dict[str, Any]],
    acceptance_verifiers: list[Any],
    closure_semantics: dict[str, Any],
    machine_closure_probe: dict[str, Any],
    current_state: dict[str, Any],
    runbook_candidate: dict[str, Any],
    evidence_refs: list[dict[str, Any]],
) -> dict[str, Any]:
    check_rows = [check for check in checks if isinstance(check, dict)]
    fulfilled = [
        {
            "key": check.get("key"),
            "message": check.get("message"),
            "evidence_hint": check.get("data"),
        }
        for check in check_rows
        if check.get("ok") is True and str(check.get("level") or "ok").lower() == "ok"
    ]
    missing = [
        {
            "key": check.get("key"),
            "level": check.get("level"),
            "message": check.get("message"),
            "evidence_hint": check.get("data"),
        }
        for check in check_rows
        if check.get("ok") is not True or str(check.get("level") or "").lower() in {"open", "warn", "fail"}
    ]
    readiness_total = max(1, len(fulfilled) + len(missing))
    readiness_score = round(len(fulfilled) / readiness_total, 2)
    verifier_commands = [
        str(item.get("command"))
        for item in acceptance_verifiers
        if isinstance(item, dict) and item.get("command")
    ]
    dependency_requirement_ids: list[str] = []
    dependency_reasons: list[str] = []
    missing_keys = {str(item.get("key")) for item in missing if item.get("key")}
    if requirement_id == "stack.langchain-api.graph-observability" and "langchain_trace_backend_coupled" in missing_keys:
        dependency_requirement_ids.append("stack.trace-backend")
        dependency_reasons.append("LangGraph trace/checkpoint replay needs the trace backend coupling first.")
    if requirement_id == "stack.trace-backend":
        dependency_reasons.append("Trace backend unlocks span/log/metric joins and also unblocks LangGraph trace coupling.")
    required_fields = machine_closure_probe.get("required_fields") if isinstance(machine_closure_probe.get("required_fields"), list) else []
    success_predicates = machine_closure_probe.get("success_predicates") if isinstance(machine_closure_probe.get("success_predicates"), list) else []
    redaction_rules = machine_closure_probe.get("redaction_rules") if isinstance(machine_closure_probe.get("redaction_rules"), list) else []
    boundedness = machine_closure_probe.get("boundedness") if isinstance(machine_closure_probe.get("boundedness"), dict) else {}
    closure_evidence_needed = [
        {
            "kind": "missing_check",
            "key": item.get("key"),
            "message": item.get("message"),
            "expected_evidence": item.get("evidence_hint"),
        }
        for item in missing
        if item.get("key") not in {"acceptance_contract_probeable", "host_layer_non_mutating", "no_secret_leakage", "runbook_candidate_complete"}
    ]
    safe_next_command = "abyss-machine self-awareness export --json" if status != "closed" else "abyss-machine self-awareness validate --json"
    return {
        "schema": f"{SCHEMA_PREFIX}_stack_handoff_closure_readiness_v1",
        "requirement_id": requirement_id,
        "status": status,
        "probe_kind": probe_kind,
        "readiness_score": readiness_score,
        "fulfilled_checks": fulfilled,
        "missing_checks": missing,
        "blocking_check_keys": [str(item.get("key")) for item in missing if item.get("key")],
        "open_blocker_count": len(missing),
        "fulfilled_check_count": len(fulfilled),
        "dependency_requirement_ids": dependency_requirement_ids,
        "dependency_reasons": dependency_reasons,
        "closure_evidence_needed": closure_evidence_needed,
        "required_fields": required_fields,
        "success_predicates": success_predicates,
        "redaction_rules": redaction_rules,
        "boundedness": boundedness,
        "verifier_commands": verifier_commands,
        "runbook_candidate_id": runbook_candidate.get("id"),
        "safe_next_action": {
            "kind": "stack_owner_closure_readiness_review" if status != "closed" else "machine_verifier_confirmation",
            "owner_route": "abyss-stack" if status != "closed" else "abyss-machine:self-awareness",
            "command": safe_next_command,
            "requirement_probe_command": "abyss-machine self-awareness requirement-probes --json",
            "automatic": False,
            "requires_human_approval": True,
            "executes_commands": False,
            "host_layer_mutates_stack": False,
            "action_execution": False,
        },
        "current_state_digest": {
            "keys": sorted(str(key) for key in current_state.keys())[:80],
            "has_current_state": bool(current_state),
            "evidence_refs": len(evidence_refs),
        },
        "evidence_refs": evidence_refs[:24],
        "policy": {
            "handoff_only": status != "closed",
            "read_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "automatic_remediation": False,
            "open_stack_requirements_are_blockers_not_host_failures": True,
            "closure_requires_probe_success": True,
            "no_partial_credit": closure_semantics.get("no_partial_credit") is True,
            "raw_secrets_included": False,
        },
    }


def self_awareness_requirement_probe_evaluate(
    handoff: dict[str, Any],
    capabilities: dict[str, Any],
    requirement: dict[str, Any] | None = None,
) -> dict[str, Any]:
    requirement = requirement if isinstance(requirement, dict) else {}
    requirement_id = str(handoff.get("requirement_id") or handoff.get("id") or requirement.get("id") or "")
    contract_source = dict(handoff)
    contract_source.update(requirement)
    contract_source["id"] = requirement_id
    contract_source["requirement_id"] = requirement_id
    contract_source["owner"] = contract_source.get("owner") or "abyss-stack"
    contract_source["status"] = contract_source.get("status") or "open"
    contract = self_awareness_requirement_acceptance_contract(contract_source)
    probe_plan = contract.get("probe_plan") if isinstance(contract.get("probe_plan"), dict) else {}
    raw = capabilities.get("raw") if isinstance(capabilities.get("raw"), dict) else {}
    capability_items = capabilities.get("capabilities") if isinstance(capabilities.get("capabilities"), list) else []
    cap_by_id = {
        str(item.get("id")): item
        for item in capability_items
        if isinstance(item, dict) and item.get("id")
    }
    checks: list[dict[str, Any]] = []
    evidence_refs: list[dict[str, Any]] = []

    def add_check(key: str, ok: bool, message: str, data: dict[str, Any] | None = None, *, open_check: bool = False) -> None:
        checks.append({
            "key": key,
            "ok": bool(ok),
            "level": "ok" if ok else ("open" if open_check else "fail"),
            "message": message,
            "data": data or {},
        })

    def add_ref(ref: dict[str, Any] | None) -> None:
        if isinstance(ref, dict) and ref:
            evidence_refs.append(ref)

    for ref in requirement.get("evidence_refs", []) if isinstance(requirement.get("evidence_refs"), list) else []:
        add_ref(ref)
    for ref in handoff.get("evidence_refs", []) if isinstance(handoff.get("evidence_refs"), list) else []:
        add_ref(ref)

    contract_ok = (
        contract.get("schema") == f"{SCHEMA_PREFIX}_stack_requirement_acceptance_contract_v1"
        and contract.get("requirement_id") == requirement_id
        and isinstance(probe_plan.get("required_fields"), list)
        and bool(probe_plan.get("required_fields"))
        and isinstance(probe_plan.get("success_predicates"), list)
        and bool(probe_plan.get("success_predicates"))
        and nested_get(contract, ["closure_semantics", "host_layer_mutates_stack"]) is False
    )
    add_check(
        "acceptance_contract_probeable",
        contract_ok,
        "acceptance contract has schema, identity, required fields, success predicates, and non-mutating closure semantics",
        {
            "contract_schema": contract.get("schema"),
            "requirement_id": requirement_id,
            "required_fields": probe_plan.get("required_fields") if isinstance(probe_plan.get("required_fields"), list) else [],
            "success_predicates": len(probe_plan.get("success_predicates") if isinstance(probe_plan.get("success_predicates"), list) else []),
        },
    )
    mutating_route = (
        handoff.get("host_layer_mutates_stack") is not False
        or nested_get(contract, ["closure_semantics", "host_layer_mutates_stack"]) is not False
    )
    add_check(
        "host_layer_non_mutating",
        not mutating_route,
        "machine probe remains read-only and does not mutate abyss-stack",
        {"host_layer_mutates_stack": bool(mutating_route)},
    )

    current_state: dict[str, Any] = {"requirement_status": requirement.get("status") or handoff.get("status")}
    external_row = self_awareness_external_closure_row(raw, requirement_id)
    external_accepted = external_row.get("accepted") is True
    external_checks = external_row.get("checks") if external_accepted and isinstance(external_row.get("checks"), dict) else {}
    external_state = external_row.get("current_state") if external_accepted and isinstance(external_row.get("current_state"), dict) else {}
    if external_row:
        current_state.update({
            "external_closure_evidence_present": True,
            "external_closure_evidence_accepted": external_accepted,
            "external_closure_evidence_rejection_reasons": external_row.get("rejection_reasons") if isinstance(external_row.get("rejection_reasons"), list) else [],
            "external_closure_evidence_config_path": nested_get(external_row, ["source", "config_path"]),
        })
        for ref in external_row.get("evidence_refs", []) if isinstance(external_row.get("evidence_refs"), list) else []:
            add_ref(ref)
    closure_predicate = False
    if requirement_id == "stack.grafana.datasource-read":
        grafana_probe = raw.get("grafana_datasource_inventory") if isinstance(raw.get("grafana_datasource_inventory"), dict) else {}
        grafana_raw = raw.get("grafana_datasources") if isinstance(raw.get("grafana_datasources"), dict) else {}
        grafana_cap = cap_by_id.get("grafana.health", {})
        detail = grafana_cap.get("detail") if isinstance(grafana_cap.get("detail"), dict) else {}
        if not grafana_probe and isinstance(detail.get("datasource_probe"), dict):
            grafana_probe = detail.get("datasource_probe")
        health = grafana_probe.get("health") if isinstance(grafana_probe.get("health"), dict) else {}
        api_access = grafana_probe.get("api_access") if isinstance(grafana_probe.get("api_access"), dict) else {}
        inventory = grafana_probe.get("datasource_inventory") if isinstance(grafana_probe.get("datasource_inventory"), dict) else {}
        handoff = grafana_probe.get("handoff") if isinstance(grafana_probe.get("handoff"), dict) else {}
        candidates = grafana_probe.get("inferred_datasource_candidates") if isinstance(grafana_probe.get("inferred_datasource_candidates"), list) else []
        if not grafana_raw and isinstance(api_access.get("routes"), dict):
            grafana_raw = api_access["routes"].get("datasources") if isinstance(api_access["routes"].get("datasources"), dict) else {}
        current_state.update({
            "health_ok": health.get("ok"),
            "health_status_code": health.get("status_code"),
            "grafana_version": health.get("version"),
            "grafana_database": health.get("database"),
            "route": grafana_raw.get("url"),
            "ok": grafana_raw.get("ok"),
            "status_code": grafana_raw.get("status_code"),
            "error": grafana_raw.get("error"),
            "denied_routes": api_access.get("denied_routes") if isinstance(api_access.get("denied_routes"), list) else [],
            "readable_routes": api_access.get("readable_routes") if isinstance(api_access.get("readable_routes"), list) else [],
            "datasource_api_auth_denied": api_access.get("datasource_api_auth_denied"),
            "all_inventory_routes_denied": api_access.get("all_inventory_routes_denied"),
            "datasource_inventory_present": inventory.get("present"),
            "datasource_inventory_count": inventory.get("count"),
            "inferred_datasource_candidate_count": len(candidates),
            "inferred_datasource_candidate_types": sorted(str(item.get("type")) for item in candidates if isinstance(item, dict) and item.get("type")),
            "inferred_candidates_are_not_inventory": handoff.get("inferred_candidates_are_not_inventory"),
            "stack_owned_inventory_required": handoff.get("stack_owned_inventory_required"),
        })
        if external_accepted:
            external_inventory_readable = bool(
                external_checks.get("grafana_datasource_inventory_readable")
                or external_checks.get("datasource_inventory_readable")
                or external_state.get("datasource_inventory_present")
            )
            current_state.update({
                "external_datasource_inventory_readable": external_inventory_readable,
                "datasource_inventory_present": bool(current_state.get("datasource_inventory_present") or external_inventory_readable),
                "datasource_inventory_count": safe_int(external_state.get("datasource_inventory_count"), safe_int(current_state.get("datasource_inventory_count"), 0)),
                "stack_owned_inventory_required": False if external_inventory_readable else current_state.get("stack_owned_inventory_required"),
            })
        for ref in grafana_probe.get("evidence_refs", []) if isinstance(grafana_probe.get("evidence_refs"), list) else []:
            add_ref(ref)
        if not grafana_probe:
            add_ref({"url": grafana_raw.get("url"), "status_code": grafana_raw.get("status_code"), "probe": "grafana_datasource_inventory"})
        closure_predicate = bool(current_state.get("datasource_inventory_present") and safe_int(current_state.get("datasource_inventory_count"), 0) > 0)
        add_check(
            "grafana_health_readable",
            bool(current_state.get("health_ok")),
            "Grafana health endpoint is readable as liveness evidence",
            {"status_code": current_state.get("health_status_code"), "version": current_state.get("grafana_version"), "database": current_state.get("grafana_database")},
        )
        add_check(
            "grafana_datasource_candidates_inferred",
            bool(candidates),
            "Prometheus/Loki/Alertmanager/Tempo datasource candidates are inferred from live stack evidence but do not close inventory",
            {
                "candidate_count": current_state.get("inferred_datasource_candidate_count"),
                "candidate_types": current_state.get("inferred_datasource_candidate_types"),
                "inferred_candidates_are_not_inventory": current_state.get("inferred_candidates_are_not_inventory"),
            },
        )
        add_check(
            "grafana_datasource_api_auth_denied",
            bool(current_state.get("datasource_api_auth_denied")),
            "Grafana datasource inventory route is auth-denied from the host layer",
            {"status_code": grafana_raw.get("status_code"), "url": grafana_raw.get("url"), "denied_routes": current_state.get("denied_routes")},
            open_check=bool(current_state.get("datasource_api_auth_denied")),
        )
        add_check(
            "grafana_datasource_inventory_readable",
            closure_predicate,
            "Grafana datasource inventory is readable through a stack-owned bounded route",
            {"status_code": grafana_raw.get("status_code"), "url": grafana_raw.get("url"), "inventory_count": current_state.get("datasource_inventory_count")},
            open_check=True,
        )
    elif requirement_id == "stack.trace-backend":
        trace_raw = raw.get("trace_backend") if isinstance(raw.get("trace_backend"), dict) else {}
        tempo_raw = raw.get("tempo_ready") if isinstance(raw.get("tempo_ready"), dict) else {}
        trace_backend_raw = raw.get("trace_backend") if isinstance(raw.get("trace_backend"), dict) else {}
        backend = trace_raw.get("backend") if isinstance(trace_raw.get("backend"), dict) else {}
        pipeline = trace_raw.get("pipeline_evidence") if isinstance(trace_raw.get("pipeline_evidence"), dict) else {}
        trace_context = trace_raw.get("trace_context") if isinstance(trace_raw.get("trace_context"), dict) else {}
        join = trace_raw.get("join_readiness") if isinstance(trace_raw.get("join_readiness"), dict) else {}
        ready = backend.get("ready") if isinstance(backend.get("ready"), dict) else {}
        search = backend.get("search") if isinstance(backend.get("search"), dict) else {}
        if not ready:
            ready = tempo_raw
        current_state.update({
            "route": ready.get("url"),
            "ok": ready.get("ok"),
            "status_code": ready.get("status_code"),
            "error": ready.get("error"),
            "search_route": search.get("url"),
            "search_ok": search.get("ok"),
            "search_status_code": search.get("status_code"),
            "search_error": search.get("error"),
            "alloy_seen": pipeline.get("alloy_seen"),
            "alloy_prometheus_value": pipeline.get("alloy_prometheus_value"),
            "loki_ready": pipeline.get("loki_ready"),
            "loki_labels_readable": pipeline.get("loki_labels_readable"),
            "logql_entries_seen": pipeline.get("logql_entries_seen"),
            "metrics_log_pipeline_readable": pipeline.get("metrics_log_pipeline_readable"),
            "traceparent_log_query_ok": trace_context.get("traceparent_log_query_ok"),
            "traceparent_log_entries_seen": trace_context.get("traceparent_log_entries_seen"),
            "trace_context_query_safe_empty": trace_context.get("trace_context_query_safe_empty"),
            "trace_backend_ready": join.get("trace_backend_ready") if "trace_backend_ready" in join else ready.get("ok"),
            "trace_search_readable": join.get("trace_search_readable") if "trace_search_readable" in join else search.get("ok"),
            "span_log_metric_join_supported": join.get("span_log_metric_join_supported"),
            "join_missing": join.get("missing") if isinstance(join.get("missing"), list) else [],
        })
        if external_accepted:
            current_state.update({
                "external_trace_backend_evidence_accepted": True,
                "trace_backend_ready": bool(current_state.get("trace_backend_ready") or external_checks.get("trace_backend_ready") or external_state.get("trace_backend_ready")),
                "trace_search_readable": bool(current_state.get("trace_search_readable") or external_checks.get("trace_span_search_readable") or external_checks.get("trace_search_readable") or external_state.get("trace_search_readable")),
                "span_log_metric_join_supported": bool(current_state.get("span_log_metric_join_supported") or external_checks.get("span_log_metric_join_supported") or external_state.get("span_log_metric_join_supported")),
            })
            current_state["join_missing"] = [
                label for label in ("trace_backend_ready", "trace_search_readable", "span_log_metric_join_supported")
                if not current_state.get(label)
            ]
        for ref in trace_raw.get("evidence_refs", []) if isinstance(trace_raw.get("evidence_refs"), list) else []:
            add_ref(ref)
        if not trace_raw:
            add_ref({"url": tempo_raw.get("url"), "status_code": tempo_raw.get("status_code"), "probe": "trace_backend_ready"})
        closure_predicate = bool(current_state.get("trace_backend_ready") and current_state.get("trace_search_readable") and current_state.get("span_log_metric_join_supported"))
        add_check(
            "trace_pipeline_evidence_readable",
            bool(current_state.get("metrics_log_pipeline_readable")),
            "Prometheus/Alloy/Loki metric-log pipeline evidence is readable",
            {
                "alloy_seen": current_state.get("alloy_seen"),
                "loki_ready": current_state.get("loki_ready"),
                "loki_labels_readable": current_state.get("loki_labels_readable"),
                "logql_entries_seen": current_state.get("logql_entries_seen"),
            },
            open_check=not bool(current_state.get("metrics_log_pipeline_readable")),
        )
        add_check(
            "traceparent_log_context_queryable",
            bool(current_state.get("traceparent_log_query_ok")),
            "W3C traceparent can be queried in logs through a bounded LogQL route",
            {
                "traceparent_log_entries_seen": current_state.get("traceparent_log_entries_seen"),
                "trace_context_query_safe_empty": current_state.get("trace_context_query_safe_empty"),
            },
            open_check=not bool(current_state.get("traceparent_log_query_ok")),
        )
        add_check(
            "trace_backend_ready",
            bool(current_state.get("trace_backend_ready")),
            "Trace backend ready endpoint is readable",
            {"status_code": ready.get("status_code"), "url": ready.get("url"), "error": ready.get("error")},
            open_check=True,
        )
        add_check(
            "trace_span_search_readable",
            bool(current_state.get("trace_search_readable")),
            "Trace backend search/export route is readable for bounded span lookup",
            {"status_code": search.get("status_code"), "url": search.get("url"), "error": search.get("error")},
            open_check=True,
        )
        add_check(
            "span_log_metric_join_supported",
            closure_predicate,
            "Trace backend can support span/log/metric joins for self-awareness replay",
            {
                "trace_backend_ready": current_state.get("trace_backend_ready"),
                "trace_search_readable": current_state.get("trace_search_readable"),
                "traceparent_log_query_ok": current_state.get("traceparent_log_query_ok"),
                "join_missing": current_state.get("join_missing"),
            },
            open_check=True,
        )
    elif requirement_id == "stack.database-graph.read-route":
        active_services = cap_by_id.get("stack.active.services", {})
        detail = active_services.get("detail") if isinstance(active_services.get("detail"), dict) else {}
        memory_routes = raw.get("memory_space_routes") if isinstance(raw.get("memory_space_routes"), dict) else {}
        memory_cap = cap_by_id.get("stack.memory-space.live-routes", {})
        memory_detail = memory_cap.get("detail") if isinstance(memory_cap.get("detail"), dict) else {}
        if not memory_routes:
            memory_routes = memory_detail
        route_api = memory_routes.get("route_api") if isinstance(memory_routes.get("route_api"), dict) else {}
        rag_api = memory_routes.get("rag_api") if isinstance(memory_routes.get("rag_api"), dict) else {}
        postgres = memory_routes.get("postgres") if isinstance(memory_routes.get("postgres"), dict) else {}
        neo4j = memory_routes.get("neo4j") if isinstance(memory_routes.get("neo4j"), dict) else {}
        semantic_inventory = memory_routes.get("semantic_inventory") if isinstance(memory_routes.get("semantic_inventory"), dict) else {}
        route_openapi = route_api.get("openapi") if isinstance(route_api.get("openapi"), dict) else {}
        route_health = route_api.get("health") if isinstance(route_api.get("health"), dict) else {}
        rag_openapi = rag_api.get("openapi") if isinstance(rag_api.get("openapi"), dict) else {}
        rag_health = rag_api.get("health") if isinstance(rag_api.get("health"), dict) else {}
        rag_collections = rag_api.get("collections") if isinstance(rag_api.get("collections"), dict) else {}
        rag_sources = rag_api.get("sources") if isinstance(rag_api.get("sources"), dict) else {}
        rag_graph = rag_api.get("agentic_graph") if isinstance(rag_api.get("agentic_graph"), dict) else {}
        neo4j_root = neo4j.get("root") if isinstance(neo4j.get("root"), dict) else {}
        route_readable = bool(route_health.get("ok") and route_openapi.get("ok"))
        rag_readable = bool(rag_health.get("ok") and rag_openapi.get("ok") and rag_collections.get("ok") and rag_sources.get("ok"))
        db_endpoint_readable = bool(postgres.get("tcp_ready") and neo4j_root.get("ok"))
        closure_predicate = bool(semantic_inventory.get("inventory_complete"))
        current_state.update({
            "postgres_seen": detail.get("postgres_seen"),
            "neo4j_seen": detail.get("neo4j_seen"),
            "route_api_health_ok": route_health.get("ok"),
            "route_api_openapi_ok": route_openapi.get("ok"),
            "route_api_openapi_path_count": route_openapi.get("path_count"),
            "route_api_openapi_paths": route_openapi.get("paths", [])[:40] if isinstance(route_openapi.get("paths"), list) else [],
            "rag_api_health_ok": rag_health.get("ok"),
            "rag_api_openapi_ok": rag_openapi.get("ok"),
            "rag_api_openapi_path_count": rag_openapi.get("path_count"),
            "rag_api_openapi_paths": rag_openapi.get("paths", [])[:40] if isinstance(rag_openapi.get("paths"), list) else [],
            "rag_collection_names": rag_collections.get("collection_names", []),
            "rag_source_count": rag_sources.get("source_count"),
            "rag_agentic_graph_node_count": rag_graph.get("node_count"),
            "rag_agentic_graph_edge_count": rag_graph.get("edge_count"),
            "postgres_tcp_ready": postgres.get("tcp_ready"),
            "postgres_schema_inventory_present": postgres.get("schema_inventory_present"),
            "neo4j_root_readable": neo4j_root.get("ok"),
            "neo4j_version": neo4j_root.get("neo4j_version"),
            "neo4j_query_endpoint_present": neo4j_root.get("query_endpoint_present"),
            "neo4j_graph_inventory_present": neo4j.get("graph_inventory_present"),
            "stack_owned_postgres_schema_inventory_present": semantic_inventory.get("stack_owned_postgres_schema_inventory_present"),
            "stack_owned_neo4j_graph_inventory_present": semantic_inventory.get("stack_owned_neo4j_graph_inventory_present"),
            "stack_owned_inventory_route_present": closure_predicate,
            "container_names": detail.get("container_names", []),
        })
        if external_accepted:
            external_inventory_complete = bool(
                external_checks.get("database_graph_inventory_route_present")
                or external_checks.get("inventory_complete")
                or external_state.get("inventory_complete")
            )
            current_state.update({
                "external_database_graph_inventory_accepted": True,
                "postgres_schema_inventory_present": bool(current_state.get("postgres_schema_inventory_present") or external_state.get("postgres_schema_inventory_present")),
                "neo4j_graph_inventory_present": bool(current_state.get("neo4j_graph_inventory_present") or external_state.get("neo4j_graph_inventory_present")),
                "stack_owned_postgres_schema_inventory_present": bool(current_state.get("stack_owned_postgres_schema_inventory_present") or external_state.get("postgres_schema_inventory_present") or external_state.get("stack_owned_postgres_schema_inventory_present")),
                "stack_owned_neo4j_graph_inventory_present": bool(current_state.get("stack_owned_neo4j_graph_inventory_present") or external_state.get("neo4j_graph_inventory_present") or external_state.get("stack_owned_neo4j_graph_inventory_present")),
                "stack_owned_inventory_route_present": bool(current_state.get("stack_owned_inventory_route_present") or external_inventory_complete),
            })
            closure_predicate = bool(closure_predicate or external_inventory_complete)
        for ref in active_services.get("evidence_refs", []) if isinstance(active_services.get("evidence_refs"), list) else []:
            add_ref(ref)
        for ref in memory_routes.get("evidence_refs", []) if isinstance(memory_routes.get("evidence_refs"), list) else []:
            add_ref(ref)
        for ref in memory_cap.get("evidence_refs", []) if isinstance(memory_cap.get("evidence_refs"), list) else []:
            add_ref(ref)
        add_check(
            "route_api_health_openapi_readable",
            route_readable,
            "route-api health and bounded OpenAPI are readable as stack route/federation context",
            {"health_ok": route_health.get("ok"), "openapi_ok": route_openapi.get("ok"), "path_count": route_openapi.get("path_count")},
            open_check=not route_readable,
        )
        add_check(
            "rag_api_inventory_routes_readable",
            rag_readable,
            "rag-api health, bounded OpenAPI, collections, and sources are readable without raw source documents",
            {
                "health_ok": rag_health.get("ok"),
                "openapi_ok": rag_openapi.get("ok"),
                "collection_count": rag_collections.get("collection_count"),
                "source_count": rag_sources.get("source_count"),
                "graph_route_ok": rag_graph.get("ok"),
            },
            open_check=not rag_readable,
        )
        add_check(
            "database_endpoint_metadata_readable",
            db_endpoint_readable,
            "Postgres service readiness and Neo4j root metadata are readable without database credentials",
            {"postgres_tcp_ready": postgres.get("tcp_ready"), "neo4j_root_readable": neo4j_root.get("ok"), "neo4j_version": neo4j_root.get("neo4j_version")},
            open_check=not db_endpoint_readable,
        )
        add_check(
            "database_graph_inventory_route_present",
            closure_predicate,
            "Stack-owned bounded Postgres schema/freshness and Neo4j label/relationship/freshness inventory is readable",
            {
                "postgres_schema_inventory_present": current_state.get("stack_owned_postgres_schema_inventory_present"),
                "neo4j_graph_inventory_present": current_state.get("stack_owned_neo4j_graph_inventory_present"),
                "inventory_complete": current_state.get("stack_owned_inventory_route_present"),
            },
            open_check=True,
        )
    elif requirement_id == "stack.langchain-api.graph-observability":
        langchain_raw = raw.get("langchain_api") if isinstance(raw.get("langchain_api"), dict) else {}
        langchain_cap = cap_by_id.get("stack.langchain-api.health-openapi", {})
        detail = langchain_cap.get("detail") if isinstance(langchain_cap.get("detail"), dict) else {}
        observability = langchain_raw.get("observability") if isinstance(langchain_raw.get("observability"), dict) else {}
        if not observability and isinstance(detail.get("observability"), dict):
            observability = detail.get("observability")
        openapi = langchain_raw.get("openapi") if isinstance(langchain_raw.get("openapi"), dict) else {}
        if not openapi and isinstance(detail.get("openapi"), dict):
            openapi = detail.get("openapi")
        health = langchain_raw.get("health") if isinstance(langchain_raw.get("health"), dict) else {}
        if not health and isinstance(detail.get("health"), dict):
            health = detail.get("health")
        runtime_surface = langchain_raw.get("runtime_surface") if isinstance(langchain_raw.get("runtime_surface"), dict) else {}
        if not runtime_surface and isinstance(detail.get("runtime_surface"), dict):
            runtime_surface = detail.get("runtime_surface")
        route_classes = langchain_raw.get("route_classes") if isinstance(langchain_raw.get("route_classes"), dict) else {}
        if not route_classes and isinstance(detail.get("route_classes"), dict):
            route_classes = detail.get("route_classes")
        replay_inventory = langchain_raw.get("replay_inventory") if isinstance(langchain_raw.get("replay_inventory"), dict) else {}
        if not replay_inventory and isinstance(detail.get("replay_inventory"), dict):
            replay_inventory = detail.get("replay_inventory")
        trace_coupling = langchain_raw.get("trace_backend_coupling") if isinstance(langchain_raw.get("trace_backend_coupling"), dict) else {}
        if not trace_coupling and isinstance(detail.get("trace_backend_coupling"), dict):
            trace_coupling = detail.get("trace_backend_coupling")
        tempo_raw = raw.get("tempo_ready") if isinstance(raw.get("tempo_ready"), dict) else {}
        trace_backend_raw = raw.get("trace_backend") if isinstance(raw.get("trace_backend"), dict) else {}
        path_rows = openapi.get("paths") if isinstance(openapi.get("paths"), list) else []
        run_paths = route_classes.get("run_paths") if isinstance(route_classes.get("run_paths"), list) else []
        federated_run_paths = route_classes.get("federated_run_paths") if isinstance(route_classes.get("federated_run_paths"), list) else []
        embeddings_paths = route_classes.get("embeddings_paths") if isinstance(route_classes.get("embeddings_paths"), list) else []
        thread_paths = route_classes.get("thread_paths") if isinstance(route_classes.get("thread_paths"), list) else []
        checkpoint_paths = route_classes.get("checkpoint_paths") if isinstance(route_classes.get("checkpoint_paths"), list) else []
        trace_paths = route_classes.get("trace_paths") if isinstance(route_classes.get("trace_paths"), list) else []
        thread_present = bool(replay_inventory.get("thread_inventory_present") or observability.get("thread_inventory_present") or thread_paths)
        checkpoint_present = bool(replay_inventory.get("checkpoint_inventory_present") or observability.get("checkpoint_inventory_present") or checkpoint_paths)
        trace_present = bool(replay_inventory.get("trace_inventory_present") or observability.get("trace_inventory_present") or trace_paths)
        graph_complete = bool(observability.get("graph_observability_complete"))
        runtime_routes_readable = bool(runtime_surface.get("run_route_present") and runtime_surface.get("embeddings_route_present"))
        trace_backend_ready = bool(
            nested_get(trace_backend_raw, ["join_readiness", "trace_backend_ready"])
            if isinstance(trace_backend_raw, dict)
            else tempo_raw.get("ok")
        )
        current_state.update({
            "langchain_api_base_url": langchain_raw.get("base_url") or detail.get("base_url"),
            "health_service": health.get("service") or runtime_surface.get("service"),
            "embeddings_provider": health.get("embeddings_provider") or runtime_surface.get("embeddings_provider"),
            "ovms_auth_enabled": health.get("ovms_auth_enabled") if health.get("ovms_auth_enabled") is not None else runtime_surface.get("ovms_auth_enabled"),
            "federated_run_enabled": health.get("federated_run_enabled") if health.get("federated_run_enabled") is not None else runtime_surface.get("federated_run_enabled"),
            "api_health_ok": health.get("ok") or observability.get("health_readable"),
            "openapi_ok": openapi.get("ok") or observability.get("openapi_readable"),
            "openapi_path_count": openapi.get("path_count"),
            "openapi_paths": path_rows[:32],
            "run_route_present": bool(runtime_surface.get("run_route_present") or run_paths),
            "federated_run_route_present": bool(runtime_surface.get("federated_run_route_present") or federated_run_paths),
            "embeddings_route_present": bool(runtime_surface.get("embeddings_route_present") or embeddings_paths),
            "runtime_request_schema_names": runtime_surface.get("runtime_request_schema_names") or openapi.get("runtime_request_schema_names") or [],
            "runtime_surface_usable": bool(runtime_surface.get("usable_runtime_surface") or runtime_routes_readable),
            "thread_inventory_present": thread_present,
            "checkpoint_inventory_present": checkpoint_present,
            "trace_inventory_present": trace_present,
            "missing_replay_inventory": replay_inventory.get("missing_inventory") or observability.get("missing_replay_inventory") or [],
            "trace_backend_ready": trace_backend_ready,
            "trace_backend_url": nested_get(trace_backend_raw, ["backend", "ready", "url"]) or tempo_raw.get("url") or trace_coupling.get("candidate_ready_url"),
            "trace_backend_status_code": nested_get(trace_backend_raw, ["backend", "ready", "status_code"]) or tempo_raw.get("status_code"),
            "trace_backend_error": nested_get(trace_backend_raw, ["backend", "ready", "error"]) or tempo_raw.get("error"),
            "trace_backend_coupling_required": trace_coupling.get("required_for_trace_join") is not False,
            "stack_owned_checkpoint_inventory_present": checkpoint_present,
            "stack_owned_trace_inventory_present": trace_present,
        })
        if external_accepted:
            external_trace_coupled = bool(
                external_checks.get("langchain_trace_backend_coupled")
                or external_state.get("langchain_trace_backend_coupled")
                or external_state.get("trace_backend_ready")
            )
            external_inventory_readable = bool(
                external_checks.get("langchain_langgraph_inventory_readable")
                or external_state.get("langchain_langgraph_inventory_readable")
                or (
                    external_state.get("thread_inventory_present")
                    and external_state.get("checkpoint_inventory_present")
                    and external_state.get("trace_inventory_present")
                )
            )
            thread_present = bool(thread_present or external_state.get("thread_inventory_present"))
            checkpoint_present = bool(checkpoint_present or external_state.get("checkpoint_inventory_present"))
            trace_present = bool(trace_present or external_state.get("trace_inventory_present"))
            trace_backend_ready = bool(trace_backend_ready or external_trace_coupled)
            graph_complete = bool(graph_complete or external_inventory_readable)
            current_state.update({
                "external_langgraph_inventory_accepted": True,
                "thread_inventory_present": thread_present,
                "checkpoint_inventory_present": checkpoint_present,
                "trace_inventory_present": trace_present,
                "trace_backend_ready": trace_backend_ready,
                "stack_owned_checkpoint_inventory_present": checkpoint_present,
                "stack_owned_trace_inventory_present": trace_present,
                "missing_replay_inventory": [
                    label for label, present in (
                        ("threads", thread_present),
                        ("checkpoints", checkpoint_present),
                        ("traces", trace_present),
                    )
                    if not present
                ],
            })
        for ref in langchain_raw.get("evidence_refs", []) if isinstance(langchain_raw.get("evidence_refs"), list) else []:
            add_ref(ref)
        for ref in langchain_cap.get("evidence_refs", []) if isinstance(langchain_cap.get("evidence_refs"), list) else []:
            add_ref(ref)
        if current_state.get("trace_backend_url"):
            add_ref({"url": current_state.get("trace_backend_url"), "status_code": current_state.get("trace_backend_status_code"), "error": current_state.get("trace_backend_error"), "probe": "trace_backend_for_langgraph"})
        closure_predicate = bool(graph_complete and trace_backend_ready)
        add_check(
            "langchain_api_health_readable",
            bool(health.get("ok") or observability.get("health_readable")),
            "langchain-api health endpoint is readable from the machine",
            {"url": health.get("url"), "status_code": health.get("status_code")},
        )
        add_check(
            "langchain_api_openapi_readable",
            bool(openapi.get("ok") or observability.get("openapi_readable")),
            "langchain-api bounded OpenAPI inventory is readable from the machine",
            {"url": openapi.get("url"), "status_code": openapi.get("status_code"), "path_count": openapi.get("path_count")},
        )
        add_check(
            "langchain_runtime_routes_readable",
            runtime_routes_readable,
            "langchain-api runtime route shape is readable for run and embeddings surfaces",
            {
                "run_route_present": current_state.get("run_route_present"),
                "federated_run_route_present": current_state.get("federated_run_route_present"),
                "embeddings_route_present": current_state.get("embeddings_route_present"),
                "runtime_request_schema_names": current_state.get("runtime_request_schema_names"),
            },
        )
        add_check(
            "langchain_trace_backend_coupled",
            trace_backend_ready,
            "Trace backend readiness is visible for LangGraph span/log/metric joins",
            {
                "trace_backend_url": current_state.get("trace_backend_url"),
                "trace_backend_ready": trace_backend_ready,
                "trace_backend_error": current_state.get("trace_backend_error"),
            },
            open_check=not trace_backend_ready,
        )
        add_check(
            "langchain_langgraph_inventory_readable",
            closure_predicate,
            "Stack-owned LangChain/LangGraph thread/checkpoint/trace inventory is readable",
            {
                "api_health_ok": current_state.get("api_health_ok"),
                "openapi_ok": current_state.get("openapi_ok"),
                "thread_inventory_present": thread_present,
                "checkpoint_inventory_present": checkpoint_present,
                "trace_inventory_present": trace_present,
                "trace_backend_ready": trace_backend_ready,
                "missing_replay_inventory": current_state.get("missing_replay_inventory"),
            },
            open_check=True,
        )
    else:
        add_check(
            "generic_stack_requirement_probe",
            False,
            "No specialized machine probe exists yet for this requirement id",
            {"requirement_id": requirement_id, "probe_kind": probe_plan.get("kind")},
            open_check=True,
        )

    deduped_refs: list[dict[str, Any]] = []
    seen_refs: set[str] = set()
    for ref in evidence_refs:
        digest = stable_hash_json(ref, length=20)
        if digest in seen_refs:
            continue
        seen_refs.add(digest)
        deduped_refs.append(ref)

    preview = json.dumps(
        {
            "requirement_id": requirement_id,
            "probe_kind": probe_plan.get("kind"),
            "current_state": current_state,
            "evidence_refs": deduped_refs,
        },
        sort_keys=True,
        default=str,
    )[:50000]
    secret_leak = bool(SELF_AWARENESS_SECRET_RE.search(preview))
    add_check(
        "no_secret_leakage",
        not secret_leak,
        "Probe evidence preview does not contain obvious secrets or private payloads",
    )
    runbook_candidate = self_awareness_stack_requirement_runbook_candidate(
        requirement_id,
        handoff,
        probe_plan,
        current_state,
        deduped_refs,
    )
    add_check(
        "runbook_candidate_complete",
        self_awareness_stack_requirement_runbook_complete(runbook_candidate, requirement_id),
        "Stack-owned open requirement has an owner-gated runbook candidate with risk, blast radius, rollback, acceptance steps, and evidence refs",
        {"runbook_candidate_id": runbook_candidate.get("id")},
    )
    status = "closed" if closure_predicate and contract_ok and not secret_leak and not mutating_route else "open"
    acceptance_verifiers = contract.get("machine_verifiers") if isinstance(contract.get("machine_verifiers"), list) else []
    closure_semantics = contract.get("closure_semantics") if isinstance(contract.get("closure_semantics"), dict) else {}
    closure_readiness = self_awareness_stack_handoff_closure_readiness(
        requirement_id=requirement_id,
        status=status,
        probe_kind=probe_plan.get("kind"),
        checks=checks,
        acceptance_verifiers=acceptance_verifiers,
        closure_semantics=closure_semantics,
        machine_closure_probe=probe_plan,
        current_state=current_state,
        runbook_candidate=runbook_candidate,
        evidence_refs=deduped_refs,
    )
    probe_policy = {
        "handoff_only": True,
        "read_only": True,
        "host_layer_mutates_stack": False,
        "writes_project_roots": False,
        "executes_commands": False,
        "action_execution": False,
        "automatic_remediation": False,
        "open_stack_requirements_are_blockers_not_host_failures": True,
        "closure_requires_probe_success": True,
        "raw_secrets_included": False,
        "raw_private_payloads_included": False,
    }
    return {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_requirement_probe_v1",
        "id": requirement_id,
        "requirement_id": requirement_id,
        "owner": handoff.get("owner") or requirement.get("owner") or "abyss-stack",
        "status": status,
        "stack_handoff": True,
        "closed_by_current_probe": status == "closed",
        "host_layer_mutates_stack": False,
        "probe_kind": probe_plan.get("kind"),
        "machine_read_command": "abyss-machine self-awareness requirement-probes --json",
        "source_handoff_command": handoff.get("machine_read_command") or "abyss-machine self-awareness requirements --json",
        "acceptance_contract": contract,
        "machine_closure_probe": probe_plan,
        "acceptance_verifiers": acceptance_verifiers,
        "closure_semantics": closure_semantics,
        "required_fields": probe_plan.get("required_fields") if isinstance(probe_plan.get("required_fields"), list) else [],
        "success_predicates": probe_plan.get("success_predicates") if isinstance(probe_plan.get("success_predicates"), list) else [],
        "redaction_rules": probe_plan.get("redaction_rules") if isinstance(probe_plan.get("redaction_rules"), list) else [],
        "machine_verifiers": contract.get("machine_verifiers") if isinstance(contract.get("machine_verifiers"), list) else [],
        "must_not": contract.get("must_not") if isinstance(contract.get("must_not"), list) else [],
        "current_state": current_state,
        "checks": checks,
        "closure_readiness": closure_readiness,
        "evidence_refs": deduped_refs,
        "runbook_candidate": runbook_candidate,
        "policy": probe_policy,
    }


def self_awareness_requirement_probes(
    write_latest: bool = True,
    requirements_doc: dict[str, Any] | None = None,
    capabilities: dict[str, Any] | None = None,
) -> dict[str, Any]:
    generated_at = now_iso()
    capabilities = capabilities if isinstance(capabilities, dict) else self_awareness_capabilities(write_latest=True)
    explicit_requirements_doc = isinstance(requirements_doc, dict)
    requirements_doc = requirements_doc if explicit_requirements_doc else self_awareness_requirements(write_latest=write_latest)
    requirements = requirements_doc.get("requirements") if isinstance(requirements_doc.get("requirements"), list) else []
    stack_handoff = requirements_doc.get("stack_handoff") if isinstance(requirements_doc.get("stack_handoff"), list) else []
    requirement_by_id = {
        str(item.get("id")): item
        for item in requirements
        if isinstance(item, dict) and item.get("id")
    }
    probes = [
        self_awareness_requirement_probe_evaluate(handoff, capabilities, requirement_by_id.get(str(handoff.get("id") or handoff.get("requirement_id") or "")))
        for handoff in stack_handoff
        if isinstance(handoff, dict)
    ]
    internal_contract_failures = [
        probe.get("id") for probe in probes
        if any(check.get("level") == "fail" for check in probe.get("checks", []) if isinstance(check, dict))
    ]
    secret_leaks = [
        probe.get("id") for probe in probes
        if any(check.get("key") == "no_secret_leakage" and check.get("ok") is False for check in probe.get("checks", []) if isinstance(check, dict))
    ]
    mutating_routes = [
        probe.get("id") for probe in probes
        if probe.get("host_layer_mutates_stack") is not False
    ]
    open_probes = [probe for probe in probes if probe.get("status") != "closed"]
    closed_probes = [probe for probe in probes if probe.get("closed_by_current_probe")]
    runbook_candidates = [
        probe.get("runbook_candidate")
        for probe in probes
        if isinstance(probe, dict) and isinstance(probe.get("runbook_candidate"), dict)
    ]
    closure_readiness_packets = [
        probe.get("closure_readiness")
        for probe in probes
        if isinstance(probe, dict) and isinstance(probe.get("closure_readiness"), dict)
    ]
    missing_check_total = sum(
        safe_int(nested_get(packet, ["open_blocker_count"]), 0)
        for packet in closure_readiness_packets
        if isinstance(packet, dict)
    )
    fulfilled_check_total = sum(
        safe_int(nested_get(packet, ["fulfilled_check_count"]), 0)
        for packet in closure_readiness_packets
        if isinstance(packet, dict)
    )
    dependency_edges = sum(
        len(packet.get("dependency_requirement_ids") if isinstance(packet.get("dependency_requirement_ids"), list) else [])
        for packet in closure_readiness_packets
        if isinstance(packet, dict)
    )
    data = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_requirement_probes_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": not internal_contract_failures and not secret_leaks and not mutating_routes,
        "status": "open_requirements" if open_probes else "satisfied",
        "summary": {
            "probes": len(probes),
            "open": len(open_probes),
            "closed_by_current_probe": len(closed_probes),
            "stack_handoff": len(stack_handoff),
            "internal_contract_failures": internal_contract_failures,
            "secret_leaks": len(secret_leaks),
            "mutating_routes": len(mutating_routes),
            "runbook_candidates": len(runbook_candidates),
            "machine_closure_probes": sum(1 for probe in probes if isinstance(probe.get("machine_closure_probe"), dict)),
            "acceptance_verifier_steps": sum(len(probe.get("acceptance_verifiers") if isinstance(probe.get("acceptance_verifiers"), list) else []) for probe in probes),
            "closure_readiness_packets": len(closure_readiness_packets),
            "closure_readiness_fulfilled_checks": fulfilled_check_total,
            "closure_readiness_missing_checks": missing_check_total,
            "closure_readiness_dependency_edges": dependency_edges,
        },
        "probes": probes,
        "runbook_candidates": runbook_candidates,
        "closure_readiness": closure_readiness_packets,
        "open_requirements": [
            {
                "id": probe.get("id"),
                "owner": probe.get("owner"),
                "probe_kind": probe.get("probe_kind"),
                "current_state": probe.get("current_state"),
                "closure_readiness": probe.get("closure_readiness"),
                "evidence_refs": probe.get("evidence_refs"),
                "runbook_candidate_id": nested_get(probe, ["runbook_candidate", "id"]),
            }
            for probe in open_probes
        ],
        "closed_requirements": [
            {
                "id": probe.get("id"),
                "owner": probe.get("owner"),
                "probe_kind": probe.get("probe_kind"),
                "evidence_refs": probe.get("evidence_refs"),
            }
            for probe in closed_probes
        ],
        "policy": {
            "read_only": True,
            "host_layer_mutates_stack": False,
            "requirements_are_not_stack_mutations": True,
            "open_stack_requirements_are_blockers_not_host_failures": True,
            "closure_requires_probe_success": True,
            "runbook_candidates_are_handoff_only": True,
            "no_runtime_changes": True,
        },
        "evidence_refs": [
            {"path": str(SELF_AWARENESS_REQUIREMENTS_LATEST_PATH), "schema": requirements_doc.get("schema")},
            {"path": str(SELF_AWARENESS_CAPABILITIES_LATEST_PATH), "schema": capabilities.get("schema")},
        ],
        "tests": {
            "contract": "stack_handoff acceptance_contract and machine_closure_probe are evaluated for every open stack-owned requirement",
            "live": "abyss-machine self-awareness requirement-probes --json runs read-only against latest capability evidence",
        },
    }
    if write_latest:
        errors = write_latest_and_history(data, SELF_AWARENESS_REQUIREMENT_PROBES_LATEST_PATH, SELF_AWARENESS_REQUIREMENT_PROBES_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
        if not explicit_requirements_doc:
            enriched_requirements = self_awareness_requirements_with_probe_readiness(requirements_doc, data)
            write_latest_and_history(enriched_requirements, SELF_AWARENESS_REQUIREMENTS_LATEST_PATH, SELF_AWARENESS_REQUIREMENTS_ROOT)
    return data


def self_awareness_latest_artifact_ref(name: str, path: Path, schema: str) -> dict[str, Any]:
    data = load_latest_json(path, schema)
    exists = path.exists()
    return {
        "name": name,
        "path": str(path),
        "history_path": str(ai_daily_jsonl_path(path.parent)),
        "exists": exists,
        "schema": data.get("schema") or schema,
        "expected_schema": schema,
        "schema_ok": data.get("schema") == schema if data.get("schema") else False,
        "ok": data.get("ok"),
        "status": data.get("status"),
        "generated_at": data.get("generated_at"),
        "summary": data.get("summary"),
        "sha256": sha256_path(path) if exists else None,
    }


def self_awareness_stack_requirement_coverage_impact(requirement_id: str) -> dict[str, Any]:
    mapping: dict[str, dict[str, Any]] = {
        "stack.trace-backend": {
            "organ": "trace_join_backbone",
            "coverage_planes": ["signal_fabric", "causal_timeline", "spatial_graph", "langgraph_replay"],
            "affected_stack_surfaces": ["Tempo or compatible trace backend", "Alloy/OTel trace pipeline", "Loki traceparent log query", "Prometheus metric side of joins"],
            "affected_machine_surfaces": ["self-awareness correlation", "timeline", "spatial-graph", "investigate", "replay", "cycle"],
            "blocks_stack_usage_requirements": ["span/log/metric correlation", "trace-backed replay", "LangGraph trace coupling"],
            "closure_value": "turns metric/log evidence into structural span/log/metric joins for replayable self-awareness",
            "proof_commands": [
                "abyss-machine self-awareness requirement-probes --json",
                "abyss-machine self-awareness stack-closure-dossier --json",
                "abyss-machine self-awareness cycle --json",
                "abyss-machine self-awareness validate --json",
            ],
        },
        "stack.langchain-api.graph-observability": {
            "organ": "checkpointed_reasoning_runtime",
            "coverage_planes": ["langgraph_loop", "resident_worker", "investigation_replay", "response_governance"],
            "affected_stack_surfaces": ["langchain-api", "LangGraph thread inventory", "checkpoint inventory", "trace inventory"],
            "affected_machine_surfaces": ["self-awareness investigate", "replay", "brief", "reactions", "responses"],
            "blocks_stack_usage_requirements": ["checkpointed investigation", "resume/replay conclusion diff", "thread/checkpoint/trace spatial joins"],
            "closure_value": "makes the reasoning loop inspectable as stack runtime state instead of only machine-side replay state",
            "proof_commands": [
                "abyss-machine self-awareness requirement-probes --json",
                "abyss-machine self-awareness investigate --query latest --json",
                "abyss-machine self-awareness replay --json",
                "abyss-machine self-awareness validate --json",
            ],
        },
        "stack.database-graph.read-route": {
            "organ": "semantic_space_inventory",
            "coverage_planes": ["memory_space", "spatial_graph", "rag_retrieval", "freshness_gates"],
            "affected_stack_surfaces": ["Postgres", "Neo4j", "rag-api", "route-api semantic inventory"],
            "affected_machine_surfaces": ["self-awareness context", "spatial-graph", "query", "rag trace", "graph validate"],
            "blocks_stack_usage_requirements": ["bounded Postgres schema/freshness inventory", "Neo4j labels/relationships/freshness inventory", "memory-space proof before reasoning"],
            "closure_value": "lets machine bind retrieved evidence to database and graph space without treating raw rows or private graph properties as truth",
            "proof_commands": [
                "abyss-machine self-awareness requirement-probes --json",
                "abyss-machine self-awareness context --json",
                "abyss-machine rag validate --json",
                "abyss-machine graph validate --json",
                "abyss-machine self-awareness validate --json",
            ],
        },
        "stack.grafana.datasource-read": {
            "organ": "dashboard_source_authority",
            "coverage_planes": ["observability_inventory", "operator_dashboard_truth", "export_handoff", "redaction_governance"],
            "affected_stack_surfaces": ["Grafana datasources", "Prometheus datasource", "Loki datasource", "Alertmanager datasource", "Tempo datasource"],
            "affected_machine_surfaces": ["self-awareness capabilities", "requirements", "export", "stack-bridge"],
            "blocks_stack_usage_requirements": ["authoritative datasource identity", "read-only datasource type/default/freshness inventory", "redacted dashboard-source export"],
            "closure_value": "separates inferred datasource candidates from authoritative dashboard-source truth without storing Grafana secrets",
            "proof_commands": [
                "abyss-machine self-awareness capabilities --json",
                "abyss-machine self-awareness requirement-probes --json",
                "abyss-machine self-awareness export --json",
                "abyss-machine stack-bridge validate --json",
            ],
        },
    }
    impact = dict(mapping.get(requirement_id, {
        "organ": "stack_owned_capability",
        "coverage_planes": ["stack_handoff"],
        "affected_stack_surfaces": [],
        "affected_machine_surfaces": ["self-awareness requirements", "requirement-probes", "stack-closure-dossier"],
        "blocks_stack_usage_requirements": ["open stack-owned requirement"],
        "closure_value": "keeps the stack-owned capability visible until owner-routed evidence closes it",
        "proof_commands": [
            "abyss-machine self-awareness requirement-probes --json",
            "abyss-machine self-awareness validate --json",
        ],
    }))
    impact.update({
        "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_coverage_impact_v1",
        "requirement_id": requirement_id,
        "policy": {
            "handoff_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "raw_secrets_included": False,
        },
    })
    return impact


def self_awareness_stack_coverage_impact_complete(impact: Any) -> bool:
    return (
        isinstance(impact, dict)
        and impact.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_stack_coverage_impact_v1"
        and bool(impact.get("organ"))
        and bool(impact.get("closure_value"))
        and isinstance(impact.get("coverage_planes"), list)
        and bool(impact.get("coverage_planes"))
        and isinstance(impact.get("proof_commands"), list)
        and bool(impact.get("proof_commands"))
        and nested_get(impact, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(impact, ["policy", "executes_commands"]) is False
        and nested_get(impact, ["policy", "raw_secrets_included"]) is False
    )


def self_awareness_stack_closure_dossier(
    write_latest: bool = True,
    requirements_doc: dict[str, Any] | None = None,
    requirement_probes_doc: dict[str, Any] | None = None,
    working_stack_doc: dict[str, Any] | None = None,
) -> dict[str, Any]:
    generated_at = now_iso()
    requirements_doc = requirements_doc if isinstance(requirements_doc, dict) else self_awareness_requirements(write_latest=write_latest)
    requirement_probes_doc = requirement_probes_doc if isinstance(requirement_probes_doc, dict) else self_awareness_requirement_probes(write_latest=write_latest, requirements_doc=requirements_doc)
    working_stack_activation_dossier = self_awareness_working_stack_activation_dossier(
        working_stack_doc,
        generated_at=generated_at,
        write_latest=write_latest,
    )
    working_stack_activation_entries = working_stack_activation_dossier.get("entries") if isinstance(working_stack_activation_dossier.get("entries"), list) else []
    working_stack_activation_summary = working_stack_activation_dossier.get("summary") if isinstance(working_stack_activation_dossier.get("summary"), dict) else {}
    working_stack_activation_handoff = working_stack_activation_dossier.get("working_stack_activation_handoff") if isinstance(working_stack_activation_dossier.get("working_stack_activation_handoff"), dict) else {}
    action_map = self_awareness_brief_stack_handoff_action_map(requirement_probes_doc)
    actions = action_map.get("actions") if isinstance(action_map.get("actions"), list) else []
    action_by_requirement = {
        str(action.get("requirement_id")): action
        for action in actions
        if isinstance(action, dict) and action.get("requirement_id")
    }
    probes = requirement_probes_doc.get("probes") if isinstance(requirement_probes_doc.get("probes"), list) else []
    requirements = requirements_doc.get("requirements") if isinstance(requirements_doc.get("requirements"), list) else []
    requirement_by_id = {
        str(item.get("id")): item
        for item in requirements
        if isinstance(item, dict) and item.get("id")
    }
    ordered_probe_ids = [str(action.get("requirement_id")) for action in actions if isinstance(action, dict) and action.get("requirement_id")]
    ordered_probe_ids.extend(
        str(probe.get("requirement_id") or probe.get("id"))
        for probe in probes
        if isinstance(probe, dict)
        and str(probe.get("requirement_id") or probe.get("id") or "") not in ordered_probe_ids
    )
    probe_by_id = {
        str(probe.get("requirement_id") or probe.get("id")): probe
        for probe in probes
        if isinstance(probe, dict) and (probe.get("requirement_id") or probe.get("id"))
    }

    artifact_refs = {
        "requirements": self_awareness_latest_artifact_ref("requirements", SELF_AWARENESS_REQUIREMENTS_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_requirements_v1"),
        "requirement_probes": self_awareness_latest_artifact_ref("requirement_probes", SELF_AWARENESS_REQUIREMENT_PROBES_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_requirement_probes_v1"),
        "failure_matrix": self_awareness_latest_artifact_ref("failure_matrix", SELF_AWARENESS_FAILURE_MATRIX_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_failure_matrix_v1"),
        "brief": self_awareness_latest_artifact_ref("brief", SELF_AWARENESS_BRIEF_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_brief_v1"),
        "investigate": self_awareness_latest_artifact_ref("investigate", SELF_AWARENESS_INVESTIGATE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_investigation_v1"),
        "replay": self_awareness_latest_artifact_ref("replay", SELF_AWARENESS_REPLAY_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_replay_v1"),
        "export": self_awareness_latest_artifact_ref("export", SELF_AWARENESS_EXPORT_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_export_v1"),
        "validate": self_awareness_latest_artifact_ref("validate", SELF_AWARENESS_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_validate_v1"),
        "working_stack": self_awareness_latest_artifact_ref("working_stack", SELF_AWARENESS_WORKING_STACK_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_working_stack_inventory_v1"),
    }

    entries: list[dict[str, Any]] = []
    dependency_edges: list[dict[str, Any]] = []
    for index, requirement_id in enumerate(ordered_probe_ids, start=1):
        probe = probe_by_id.get(requirement_id)
        if not isinstance(probe, dict):
            continue
        requirement = requirement_by_id.get(requirement_id, {})
        readiness = probe.get("closure_readiness") if isinstance(probe.get("closure_readiness"), dict) else {}
        action = action_by_requirement.get(requirement_id, {})
        current_state = probe.get("current_state") if isinstance(probe.get("current_state"), dict) else {}
        runbook = probe.get("runbook_candidate") if isinstance(probe.get("runbook_candidate"), dict) else {}
        dependency_ids = readiness.get("dependency_requirement_ids") if isinstance(readiness.get("dependency_requirement_ids"), list) else []
        for dependency_id in dependency_ids:
            dependency_edges.append({
                "from": requirement_id,
                "to": dependency_id,
                "kind": "requires_stack_requirement",
                "reason": readiness.get("dependency_reasons"),
            })
        missing_checks = readiness.get("missing_checks") if isinstance(readiness.get("missing_checks"), list) else []
        fulfilled_checks = readiness.get("fulfilled_checks") if isinstance(readiness.get("fulfilled_checks"), list) else []
        fallback_requirement = {"id": requirement_id, "owner": "abyss-stack", "status": probe.get("status"), "expected_shape": {}}
        requirement_for_contract = requirement if isinstance(requirement, dict) and requirement else fallback_requirement
        acceptance_contract = probe.get("acceptance_contract") if isinstance(probe.get("acceptance_contract"), dict) else self_awareness_requirement_acceptance_contract(requirement_for_contract)
        coverage_impact = self_awareness_stack_requirement_coverage_impact(requirement_id)
        compat_contract = self_awareness_stack_requirement_compat_contract(
            requirement_for_contract,
            acceptance_contract=acceptance_contract,
            readiness=readiness,
            current_state=current_state,
            coverage_impact=coverage_impact,
            dependency_requirement_ids=[str(item) for item in dependency_ids],
        )
        entry = {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_closure_dossier_entry_v1",
            "order": index,
            "requirement_id": requirement_id,
            "title": requirement.get("title") or probe.get("id") or requirement_id,
            "owner": probe.get("owner") or requirement.get("owner") or "abyss-stack",
            "status": probe.get("status"),
            "closed_by_current_probe": probe.get("closed_by_current_probe"),
            "priority_class": action.get("priority_class"),
            "readiness_score": readiness.get("readiness_score"),
            "probe_kind": probe.get("probe_kind"),
            "source_handoff_command": probe.get("source_handoff_command"),
            "machine_read_command": "abyss-machine self-awareness stack-closure-dossier --json",
            "requirement_probe_command": "abyss-machine self-awareness requirement-probes --json",
            "current_state": current_state,
            "current_state_digest": stable_hash_json(current_state, length=24),
            "fulfilled_checks": fulfilled_checks,
            "missing_checks": missing_checks,
            "blocking_check_keys": readiness.get("blocking_check_keys") if isinstance(readiness.get("blocking_check_keys"), list) else [],
            "dependency_requirement_ids": dependency_ids,
            "dependency_reasons": readiness.get("dependency_reasons") if isinstance(readiness.get("dependency_reasons"), list) else [],
            "closure_evidence_needed": readiness.get("closure_evidence_needed") if isinstance(readiness.get("closure_evidence_needed"), list) else [],
            "required_fields": readiness.get("required_fields") if isinstance(readiness.get("required_fields"), list) else [],
            "success_predicates": readiness.get("success_predicates") if isinstance(readiness.get("success_predicates"), list) else [],
            "redaction_rules": readiness.get("redaction_rules") if isinstance(readiness.get("redaction_rules"), list) else [],
            "boundedness": readiness.get("boundedness") if isinstance(readiness.get("boundedness"), dict) else {},
            "acceptance_verifiers": probe.get("acceptance_verifiers") if isinstance(probe.get("acceptance_verifiers"), list) else [],
            "verifier_commands": readiness.get("verifier_commands") if isinstance(readiness.get("verifier_commands"), list) else [],
            "safe_next_action": readiness.get("safe_next_action") if isinstance(readiness.get("safe_next_action"), dict) else {},
            "acceptance_contract": acceptance_contract,
            "compat_contract": compat_contract,
            "runbook_candidate": runbook,
            "closure_readiness": readiness,
            "coverage_impact": coverage_impact,
            "evidence_refs": probe.get("evidence_refs") if isinstance(probe.get("evidence_refs"), list) else [],
            "artifact_refs": {
                "requirements": artifact_refs["requirements"],
                "requirement_probes": artifact_refs["requirement_probes"],
            },
            "policy": {
                "handoff_only": True,
                "read_only": True,
                "executes_commands": False,
                "action_execution": False,
                "host_layer_mutates_stack": False,
                "writes_project_roots": False,
                "raw_secrets_included": False,
            },
            "complete": (
                bool(readiness.get("schema") == f"{SCHEMA_PREFIX}_stack_handoff_closure_readiness_v1")
                and bool(runbook)
                and self_awareness_stack_compat_contract_complete(compat_contract)
                and bool(probe.get("acceptance_verifiers"))
                and bool(readiness.get("verifier_commands"))
                and nested_get(readiness, ["policy", "host_layer_mutates_stack"]) is False
                and nested_get(readiness, ["policy", "executes_commands"]) is False
            ),
        }
        entries.append(entry)

    entry_order_by_id = {str(entry.get("requirement_id")): safe_int(entry.get("order"), 999999) for entry in entries if entry.get("requirement_id")}
    reverse_dependency_edges: list[dict[str, Any]] = []
    unblocks_by_requirement: dict[str, list[dict[str, Any]]] = {}
    blocked_by_requirement: dict[str, list[dict[str, Any]]] = {}
    for edge in dependency_edges:
        dependent_id = str(edge.get("from") or "")
        dependency_id = str(edge.get("to") or "")
        if not dependent_id or not dependency_id:
            continue
        blocked_by_requirement.setdefault(dependent_id, []).append(edge)
        reverse_edge = {
            "from": dependency_id,
            "to": dependent_id,
            "kind": "unblocks_stack_requirement",
            "reason": edge.get("reason"),
        }
        reverse_dependency_edges.append(reverse_edge)
        unblocks_by_requirement.setdefault(dependency_id, []).append(reverse_edge)
    reverse_dependency_edges = sorted(
        reverse_dependency_edges,
        key=lambda edge: (
            entry_order_by_id.get(str(edge.get("from") or ""), 999999),
            entry_order_by_id.get(str(edge.get("to") or ""), 999999),
            str(edge.get("to") or ""),
        ),
    )
    for entry in entries:
        requirement_id = str(entry.get("requirement_id") or "")
        blocked_edges = sorted(
            blocked_by_requirement.get(requirement_id, []),
            key=lambda edge: (entry_order_by_id.get(str(edge.get("to") or ""), 999999), str(edge.get("to") or "")),
        )
        unblock_edges = sorted(
            unblocks_by_requirement.get(requirement_id, []),
            key=lambda edge: (entry_order_by_id.get(str(edge.get("to") or ""), 999999), str(edge.get("to") or "")),
        )
        depends_on_ids = [str(edge.get("to")) for edge in blocked_edges if edge.get("to")]
        unblocks_ids = [str(edge.get("to")) for edge in unblock_edges if edge.get("to")]
        entry["depends_on_requirement_ids"] = depends_on_ids
        entry["blocked_by_dependency_edges"] = blocked_edges
        entry["unblocks_requirement_ids"] = unblocks_ids
        entry["unblocks_dependency_edges"] = unblock_edges
        entry["closure_impact"] = {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_closure_impact_v1",
            "requirement_id": requirement_id,
            "depends_on_requirement_ids": depends_on_ids,
            "unblocks_requirement_ids": unblocks_ids,
            "downstream_open_requirements": len(unblocks_ids),
            "is_dependency_root": not depends_on_ids,
            "is_unblocking_requirement": bool(unblocks_ids),
            "policy": {
                "handoff_only": True,
                "host_layer_mutates_stack": False,
                "executes_commands": False,
            },
        }
        if isinstance(entry.get("compat_contract"), dict):
            entry["compat_contract"].setdefault("dependency_contract", {})
            entry["compat_contract"]["dependency_contract"]["depends_on_requirement_ids"] = depends_on_ids
            entry["compat_contract"]["dependency_contract"]["unblocks_requirement_ids"] = unblocks_ids
        entry["closure_acceptance"] = self_awareness_stack_requirement_closure_acceptance(entry, generated_at)
        entry["complete"] = bool(
            entry.get("complete") is True
            and self_awareness_stack_requirement_closure_acceptance_complete(entry.get("closure_acceptance"))
        )

    open_entries = [entry for entry in entries if entry.get("closed_by_current_probe") is not True]
    closed_entries = [entry for entry in entries if entry.get("closed_by_current_probe") is True]
    missing_check_total = sum(len(entry.get("missing_checks") if isinstance(entry.get("missing_checks"), list) else []) for entry in entries)
    fulfilled_check_total = sum(len(entry.get("fulfilled_checks") if isinstance(entry.get("fulfilled_checks"), list) else []) for entry in entries)
    unblocking_requirement_ids = [
        str(entry.get("requirement_id"))
        for entry in entries
        if entry.get("unblocks_requirement_ids")
    ]
    dependent_requirement_ids = [
        str(entry.get("requirement_id"))
        for entry in entries
        if entry.get("depends_on_requirement_ids")
    ]
    dependency_root_requirement_ids = [
        str(entry.get("requirement_id"))
        for entry in entries
        if not entry.get("depends_on_requirement_ids")
    ]
    coverage_impact_entries = [
        entry.get("coverage_impact")
        for entry in entries
        if isinstance(entry.get("coverage_impact"), dict)
    ]
    compat_contract_entries = [
        entry.get("compat_contract")
        for entry in entries
        if self_awareness_stack_compat_contract_complete(entry.get("compat_contract"))
    ]
    closure_acceptance_packets = [
        entry.get("closure_acceptance")
        for entry in entries
        if isinstance(entry.get("closure_acceptance"), dict)
    ]
    closure_acceptance_by_requirement = {
        str(packet.get("requirement_id")): packet
        for packet in closure_acceptance_packets
        if packet.get("requirement_id")
    }
    closure_acceptance_matrix = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_requirement_closure_acceptance_matrix_v1",
        "generated_at": generated_at,
        "ok": len(closure_acceptance_packets) == len(entries) and all(self_awareness_stack_requirement_closure_acceptance_complete(packet) for packet in closure_acceptance_packets),
        "requirement_ids": sorted(closure_acceptance_by_requirement),
        "packets": closure_acceptance_packets,
        "packet_by_requirement": closure_acceptance_by_requirement,
        "summary": {
            "packets": len(closure_acceptance_packets),
            "complete": sum(1 for packet in closure_acceptance_packets if packet.get("complete") is True),
            "requirements": len(closure_acceptance_by_requirement),
            "compat_requirements": len({
                str(nested_get(packet, ["stack_compat_requirement", "requirement_id"]))
                for packet in closure_acceptance_packets
                if nested_get(packet, ["stack_compat_requirement", "requirement_id"])
            }),
        },
        "policy": {
            "handoff_only": True,
            "read_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "action_execution": False,
        },
    }
    blocked_coverage_planes = sorted({
        str(plane)
        for impact in coverage_impact_entries
        for plane in (impact.get("coverage_planes") if isinstance(impact.get("coverage_planes"), list) else [])
        if plane
    })
    verifier_commands = sorted({
        command
        for entry in entries
        for command in (entry.get("verifier_commands") if isinstance(entry.get("verifier_commands"), list) else [])
        if command
    })
    verifier_chain = [
        {"command": "abyss-machine self-awareness requirement-probes --json", "must": ["current checks and closure_readiness packets are present"]},
        {"command": "abyss-machine self-awareness stack-closure-dossier --json", "must": ["dossier entries match open stack handoff requirements and preserve dependency order"]},
        {"command": "abyss-machine self-awareness export --json", "must": ["portable export includes stack_closure_dossier artifact and top-level stack handoff"]},
        {"command": "abyss-machine self-awareness validate --json", "must": ["0 fails and 0 new warnings, including stack_closure_dossier_depth"]},
        {"command": "abyss-machine stack-bridge validate --json", "must": ["bridge exposes the dossier route without stack mutation"]},
        {"command": "abyss-machine self-awareness cycle --json", "must": ["full E2E cycle keeps dossier evidence and non-mutating response policy"]},
    ]
    probe_summary = requirement_probes_doc.get("summary") if isinstance(requirement_probes_doc.get("summary"), dict) else {}
    internal_contract_failures = probe_summary.get("internal_contract_failures") if isinstance(probe_summary.get("internal_contract_failures"), list) else []
    secret_leaks = safe_int(probe_summary.get("secret_leaks"), 0)
    mutating_routes = safe_int(probe_summary.get("mutating_routes"), 0)
    open_activation_gaps = safe_int(working_stack_activation_summary.get("open_activation_gaps"), len(working_stack_activation_entries))
    activation_complete = (
        working_stack_activation_dossier.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_working_stack_activation_dossier_v1"
        and working_stack_activation_dossier.get("ok") is True
        and safe_int(working_stack_activation_summary.get("activation_entries_complete"), 0) == len(working_stack_activation_entries)
    )
    if open_entries and open_activation_gaps:
        dossier_status = "open_requirements_and_activation_gaps"
    elif open_entries:
        dossier_status = "open_requirements"
    elif open_activation_gaps:
        dossier_status = "open_activation_gaps"
    else:
        dossier_status = "satisfied"
    data = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_closure_dossier_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": not internal_contract_failures and secret_leaks == 0 and mutating_routes == 0 and all(entry.get("complete") for entry in entries) and activation_complete,
        "status": dossier_status,
        "summary": {
            "stack_owned_requirements": safe_int(nested_get(requirements_doc, ["summary", "stack_owned"]), len(requirements)),
            "probes": len(entries),
            "open_stack_requirements": len(open_entries),
            "closed_by_current_probe": len(closed_entries),
            "missing_checks": missing_check_total,
            "fulfilled_checks": fulfilled_check_total,
            "dependency_edges": len(dependency_edges),
            "reverse_dependency_edges": len(reverse_dependency_edges),
            "unblocking_requirements": len(unblocking_requirement_ids),
            "coverage_impact_entries": len(coverage_impact_entries),
            "compat_contract_entries": len(compat_contract_entries),
            "closure_acceptance_packets": len(closure_acceptance_packets),
            "closure_acceptance_packets_complete": sum(1 for packet in closure_acceptance_packets if packet.get("complete") is True),
            "stack_requirement_compat_requirements": safe_int(nested_get(closure_acceptance_matrix, ["summary", "compat_requirements"]), 0),
            "blocked_coverage_planes": blocked_coverage_planes,
            "runbook_candidates": sum(1 for entry in entries if isinstance(entry.get("runbook_candidate"), dict)),
            "acceptance_verifier_steps": sum(len(entry.get("acceptance_verifiers") if isinstance(entry.get("acceptance_verifiers"), list) else []) for entry in entries),
            "verifier_commands": len(verifier_commands),
            "dossier_entries_complete": sum(1 for entry in entries if entry.get("complete") is True),
            "internal_contract_failures": internal_contract_failures,
            "secret_leaks": secret_leaks,
            "mutating_routes": mutating_routes,
            "top_requirement_id": open_entries[0].get("requirement_id") if open_entries else None,
            "top_unblocking_requirement_id": unblocking_requirement_ids[0] if unblocking_requirement_ids else None,
            "working_stack_usage_gaps": safe_int(working_stack_activation_summary.get("working_stack_usage_gaps"), len(working_stack_activation_entries)),
            "working_stack_activation_entries": len(working_stack_activation_entries),
            "open_working_stack_activation_gaps": open_activation_gaps,
            "working_stack_activation_missing_checks": safe_int(working_stack_activation_summary.get("missing_checks"), 0),
            "working_stack_activation_fulfilled_checks": safe_int(working_stack_activation_summary.get("fulfilled_checks"), 0),
            "working_stack_activation_verifier_commands": safe_int(working_stack_activation_summary.get("verifier_commands"), 0),
            "working_stack_activation_entries_complete": safe_int(working_stack_activation_summary.get("activation_entries_complete"), 0),
            "working_stack_activation_synthetic_scenarios": safe_int(working_stack_activation_summary.get("synthetic_scenarios"), 0),
            "working_stack_activation_synthetic_scenarios_complete": safe_int(working_stack_activation_summary.get("synthetic_scenarios_complete"), 0),
            "working_stack_activation_closure_acceptance_packets": safe_int(working_stack_activation_summary.get("closure_acceptance_packets"), 0),
            "working_stack_activation_closure_acceptance_packets_complete": safe_int(working_stack_activation_summary.get("closure_acceptance_packets_complete"), 0),
            "working_stack_activation_compat_requirements": safe_int(working_stack_activation_summary.get("activation_compat_requirements"), 0),
            "working_stack_activation_coverage_planes": working_stack_activation_summary.get("coverage_planes") if isinstance(working_stack_activation_summary.get("coverage_planes"), list) else [],
            "top_working_stack_activation_service": working_stack_activation_summary.get("top_service"),
        },
        "dependency_graph": {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_closure_dependency_graph_v1",
            "ordered_requirement_ids": [entry["requirement_id"] for entry in entries],
            "open_requirement_ids": [entry["requirement_id"] for entry in open_entries],
            "closed_requirement_ids": [entry["requirement_id"] for entry in closed_entries],
            "edges": dependency_edges,
            "reverse_edges": reverse_dependency_edges,
            "dependency_root_requirement_ids": dependency_root_requirement_ids,
            "dependent_requirement_ids": dependent_requirement_ids,
            "unblocking_requirement_ids": unblocking_requirement_ids,
            "policy": {
                "dependency_order_is_handoff_guidance": True,
                "host_layer_mutates_stack": False,
                "executes_commands": False,
            },
        },
        "compat_contracts": {
            str(entry["requirement_id"]): entry.get("compat_contract")
            for entry in entries
            if entry.get("requirement_id") and isinstance(entry.get("compat_contract"), dict)
        },
        "stack_owner_handoff": {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_stack_owner_handoff_dossier_v1",
            "owner": "abyss-stack",
            "open_requirement_ids": [entry["requirement_id"] for entry in open_entries],
            "closure_order": [
                {
                    "requirement_id": entry["requirement_id"],
                    "order": entry["order"],
                    "blocking_check_keys": entry.get("blocking_check_keys"),
                    "dependency_requirement_ids": entry.get("dependency_requirement_ids"),
                    "depends_on_requirement_ids": entry.get("depends_on_requirement_ids"),
                    "unblocks_requirement_ids": entry.get("unblocks_requirement_ids"),
                    "closure_acceptance_id": nested_get(entry, ["closure_acceptance", "acceptance_id"]),
                    "compat_requirement_id": nested_get(entry, ["closure_acceptance", "stack_compat_requirement", "requirement_id"]),
                    "safe_next_action": entry.get("safe_next_action"),
                    "runbook_candidate_id": nested_get(entry, ["runbook_candidate", "id"]),
                    "closure_acceptance": entry.get("closure_acceptance"),
                    "compat_contract": entry.get("compat_contract"),
                    "verifier_commands": entry.get("verifier_commands"),
                }
                for entry in open_entries
            ],
            "closure_acceptance_matrix": closure_acceptance_matrix,
            "closure_acceptance_packets": closure_acceptance_packets,
            "verifier_chain": verifier_chain,
            "policy": {
                "handoff_only": True,
                "read_only": True,
                "operator_approval_required_before_stack_mutation": True,
                "abyss_machine_executes_stack_change": False,
                "host_layer_mutates_stack": False,
            },
        },
        "working_stack_activation_dossier": working_stack_activation_dossier,
        "working_stack_activation_handoff": working_stack_activation_handoff,
        "working_stack_activation_entries": working_stack_activation_entries,
        "closure_acceptance_packets": closure_acceptance_packets,
        "closure_acceptance_matrix": closure_acceptance_matrix,
        "entries": entries,
        "open_requirements": open_entries,
        "closed_requirements": closed_entries,
        "verifier_commands": verifier_commands,
        "verifier_chain": verifier_chain,
        "artifact_refs": artifact_refs,
        "source_commands": [
            "abyss-machine self-awareness requirements --json",
            "abyss-machine self-awareness requirement-probes --json",
            "abyss-machine self-awareness stack-closure-dossier --json",
            "abyss-machine self-awareness export --json",
            "abyss-machine self-awareness validate --json",
            "abyss-machine stack-bridge validate --json",
            "abyss-machine self-awareness cycle --json",
        ],
        "policy": {
            "handoff_only": True,
            "read_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "executes_commands": False,
            "action_execution": False,
            "raw_secrets_included": False,
            "open_stack_requirements_are_blockers_not_host_failures": True,
            "stack_owner_may_mutate_stack_after_operator_approval": True,
        },
        "evidence_refs": [
            {"path": str(SELF_AWARENESS_REQUIREMENTS_LATEST_PATH), "schema": requirements_doc.get("schema")},
            {"path": str(SELF_AWARENESS_REQUIREMENT_PROBES_LATEST_PATH), "schema": requirement_probes_doc.get("schema")},
            {"path": str(SELF_AWARENESS_WORKING_STACK_LATEST_PATH), "schema": f"{SCHEMA_PREFIX}_self_awareness_working_stack_inventory_v1"},
        ],
        "tests": {
            "contract": "dossier preserves requirement probes, closure readiness, dependency order, runbooks, verifier commands, compat contracts, and no-mutation policy",
            "working_stack_activation": "every working-stack usage gap is an owner-routed activation entry with smoke/probe evidence, runbook candidate, verifier chain, and no stack mutation",
            "live": "abyss-machine self-awareness stack-closure-dossier --json is read-only and agrees with requirement-probes/latest.json plus working-stack/latest.json usage gaps",
        },
    }
    if write_latest:
        errors = write_latest_and_history(data, SELF_AWARENESS_STACK_CLOSURE_DOSSIER_LATEST_PATH, SELF_AWARENESS_STACK_CLOSURE_DOSSIER_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def self_awareness_failure_matrix(write_latest: bool = True) -> dict[str, Any]:
    generated_at = now_iso()
    capabilities = load_latest_json(SELF_AWARENESS_CAPABILITIES_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_capabilities_v1")
    if not capabilities.get("schema"):
        capabilities = self_awareness_capabilities(write_latest=True)
    requirements = load_latest_json(SELF_AWARENESS_REQUIREMENTS_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_requirements_v1")
    requirement_probes = load_latest_json(SELF_AWARENESS_REQUIREMENT_PROBES_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_requirement_probes_v1")
    stack = load_latest_json(STACK_OBSERVABILITY_LATEST_PATH, f"{SCHEMA_PREFIX}_stack_observability_v1")
    collect = load_latest_json(SELF_AWARENESS_COLLECT_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_collect_v1")
    rag_validation = load_latest_json(RAG_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_rag_validate_v1")
    llm_resident_status = load_latest_json(AI_LLM_RESIDENT_ROOT / "status" / "latest.json", f"{SCHEMA_PREFIX}_gemma4_spark_resident_status_v1")
    nervous = load_latest_json(NERVOUS_BRIEF_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_brief_v1")
    semantic_maintain = load_latest_json(NERVOUS_SEMANTIC_MAINTAIN_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_semantic_maintain_v1")
    typing_validation = load_latest_json(TYPING_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_typing_validate_v1")
    rows: list[dict[str, Any]] = []

    def evidence_ref(path: Path, schema: str | None = None, **extra: Any) -> dict[str, Any]:
        item = {"path": str(path)}
        if schema:
            item["schema"] = schema
        item.update(extra)
        return item

    def add_row(
        row_id: str,
        title: str,
        *,
        owner: str,
        failure_kind: str,
        detector: dict[str, Any],
        expected_behavior: list[str],
        covered_by: list[str],
        evidence_refs: list[dict[str, Any]],
        current_state: dict[str, Any] | None = None,
        severity: str = "guard",
    ) -> None:
        rows.append({
            "id": row_id,
            "title": title,
            "owner": owner,
            "severity": severity,
            "failure_kind": failure_kind,
            "detector": detector,
            "expected_machine_behavior": expected_behavior,
            "covered_by": covered_by,
            "current_state": current_state or {},
            "evidence_refs": evidence_refs,
            "machine_action": "record_route_validate_only",
            "host_layer_mutates_stack": False,
            "automatic_remediation": False,
            "owner_route_required_before_mutation": owner == "abyss-stack",
        })

    requirement_items = requirements.get("requirements") if isinstance(requirements.get("requirements"), list) else []
    probe_items = requirement_probes.get("probes") if isinstance(requirement_probes.get("probes"), list) else []
    probe_by_id = {
        str(probe.get("requirement_id") or probe.get("id")): probe
        for probe in probe_items
        if isinstance(probe, dict) and (probe.get("requirement_id") or probe.get("id"))
    }
    requirement_by_id = {
        str(requirement.get("id") or requirement.get("requirement_id")): requirement
        for requirement in requirement_items
        if isinstance(requirement, dict) and (requirement.get("id") or requirement.get("requirement_id"))
    }
    known_stack_requirement_ids = {
        "stack.trace-backend",
        "stack.grafana.datasource-read",
        "stack.database-graph.read-route",
        "stack.langchain-api.graph-observability",
    }

    def add_requirement_row(requirement_id: str, requirement: dict[str, Any] | None = None) -> None:
        requirement = requirement if isinstance(requirement, dict) else {}
        probe = probe_by_id.get(requirement_id, {})
        requirement_present = bool(requirement)
        probe_status = str(probe.get("status") or "") if isinstance(probe, dict) else ""
        closed_by_probe = isinstance(probe, dict) and (probe.get("closed_by_current_probe") is True or probe_status == "closed")
        row_status = str(requirement.get("status") or ("closed" if closed_by_probe else "not_current_requirement"))
        closed = row_status == "closed" or closed_by_probe
        failure_kind = "open_requirement" if requirement_present and not closed else "closed_requirement_regression_guard"
        if failure_kind == "open_requirement":
            expected_behavior = [
                "keep the gap visible in requirements/latest.json",
                "do not mark the stack capability as host-owned",
                "do not write stack runtime/config from abyss-machine",
            ]
            severity = str(requirement.get("severity") or "gap")
        else:
            expected_behavior = [
                "preserve the regression guard for this stack-owned requirement",
                "re-open the owner-routed requirement if bounded evidence disappears or fails redaction",
                "do not write stack runtime/config from abyss-machine",
            ]
            severity = "watch"
        evidence_refs = list(requirement.get("evidence_refs") if isinstance(requirement.get("evidence_refs"), list) else [])
        evidence_refs.extend([
            evidence_ref(SELF_AWARENESS_REQUIREMENTS_LATEST_PATH, requirements.get("schema"), requirement_id=requirement_id),
            evidence_ref(SELF_AWARENESS_REQUIREMENT_PROBES_LATEST_PATH, requirement_probes.get("schema"), requirement_id=requirement_id),
        ])
        add_row(
            "requirement:" + requirement_id,
            str(requirement.get("title") or requirement_id),
            owner=str(requirement.get("owner") or nested_get(probe, ["owner"]) or "abyss-stack"),
            failure_kind=failure_kind,
            detector={
                "source": "self-awareness capabilities",
                "command": "abyss-machine self-awareness capabilities --json",
                "detection": requirement.get("detection"),
            },
            expected_behavior=expected_behavior,
            covered_by=[
                "abyss-machine self-awareness validate --json:capability_map_and_requirements",
                "abyss-machine stack-bridge validate --json:self_awareness_artifacts",
                "abyss-machine self-awareness requirement-probes --json",
            ],
            evidence_refs=evidence_refs,
            current_state={
                "status": row_status,
                "severity": requirement.get("severity"),
                "requirement_present": requirement_present,
                "probe_present": bool(probe),
                "probe_status": probe_status or None,
                "closed_by_current_probe": closed_by_probe,
                "not_current_requirement_is_not_open": not requirement_present,
            },
            severity=severity,
        )

    for requirement_id, requirement in requirement_by_id.items():
        add_requirement_row(requirement_id, requirement)
    for requirement_id in sorted(known_stack_requirement_ids - set(requirement_by_id)):
        add_requirement_row(requirement_id)

    jobs_up = set(str(item) for item in (nested_get(stack, ["summary", "promql_jobs_up"]) or []))
    add_row(
        "stack.prometheus-or-promql-missing",
        "Prometheus/PromQL target discovery missing or stale",
        owner="abyss-stack",
        failure_kind="missing_or_stale_observability",
        detector={"command": "abyss-machine stack-bridge observability --json", "signals": ["prometheus.targets", "promql up{}"]},
        expected_behavior=["mark stack observability degraded", "keep machine read-only", "route stack repair through abyss-stack"],
        covered_by=["abyss-machine stack-bridge validate --json", "abyss-machine self-awareness validate --json:full_stack_capability_planes"],
        evidence_refs=[evidence_ref(STACK_OBSERVABILITY_LATEST_PATH, stack.get("schema"))],
        current_state={"jobs_up": sorted(jobs_up), "ok": stack.get("ok")},
    )
    add_row(
        "stack.loki-logql-missing-or-cardinality-risk",
        "Loki/LogQL missing or unsafe high-cardinality labels detected",
        owner="abyss-stack",
        failure_kind="missing_or_cardinality_risk",
        detector={"command": "abyss-machine self-awareness context --json", "forbidden_labels": sorted(SELF_AWARENESS_UNBOUNDED_LABELS)},
        expected_behavior=["reject trace/request/session/task IDs as Loki labels", "keep IDs in event context/body", "fail validation on unsafe labels"],
        covered_by=["abyss-machine self-awareness validate --json:no_unbounded_loki_labels", "abyss-machine self-awareness validate --json:fixture_unbounded_label_rejected"],
        evidence_refs=[evidence_ref(SELF_AWARENESS_CONTEXT_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_context_v1")],
        current_state={"forbidden_loki_labels": nested_get(load_latest_json(SELF_AWARENESS_CONTEXT_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_context_v1"), ["summary", "forbidden_loki_labels"])},
    )
    add_row(
        "stack.grafana-health-or-auth-gap",
        "Grafana health or datasource inventory unavailable",
        owner="abyss-stack",
        failure_kind="missing_or_auth_gap",
        detector={"command": "abyss-machine self-awareness capabilities --json", "endpoint": "/api/health and /api/datasources"},
        expected_behavior=["use unauthenticated health as limited evidence", "record datasource auth gap as stack-owned requirement", "do not store Grafana credentials in abyss-machine"],
        covered_by=["abyss-machine self-awareness validate --json:capability_map_and_requirements"],
        evidence_refs=[evidence_ref(SELF_AWARENESS_CAPABILITIES_LATEST_PATH, capabilities.get("schema"))],
        current_state=nested_get(capabilities, ["raw", "grafana_datasources"]) or {},
    )
    add_row(
        "stack.alloy-otel-pipeline-missing",
        "Alloy/OTel log and metric pipeline missing",
        owner="abyss-stack",
        failure_kind="missing_pipeline",
        detector={"command": "abyss-machine stack-bridge observability --json", "signals": ["up{job=\"alloy\"}", "loki labels/log samples"]},
        expected_behavior=["mark observability source degraded", "do not edit Alloy config", "route pipeline repair to abyss-stack"],
        covered_by=["abyss-machine stack-bridge validate --json", "abyss-machine self-awareness validate --json:full_stack_observation_sources"],
        evidence_refs=[evidence_ref(STACK_OBSERVABILITY_LATEST_PATH, stack.get("schema"), locator="alloy")],
        current_state={"alloy_seen": "alloy" in jobs_up, "collect_degraded_sources": nested_get(collect, ["summary", "degraded_sources"])},
    )
    add_row(
        "stack.alertmanager-lifecycle-unavailable",
        "Alertmanager lifecycle unavailable",
        owner="abyss-stack",
        failure_kind="optional_lifecycle_unavailable",
        detector={"command": "abyss-machine self-awareness collect --json", "endpoint": "/api/v2/status and /api/v2/alerts"},
        expected_behavior=["keep Prometheus ALERTS and synthetic alerts usable", "record optional degradation when unavailable", "do not mutate alert rules"],
        covered_by=["abyss-machine self-awareness collect --json", "abyss-machine self-awareness alerts --json"],
        evidence_refs=[evidence_ref(SELF_AWARENESS_COLLECT_LATEST_PATH, collect.get("schema"))],
        current_state={"alert_events": nested_get(collect, ["summary", "alert_events"])},
    )
    add_row(
        "machine.rag-validation-missing-or-stale",
        "RAG trace/eval validation missing or stale",
        owner="abyss-machine",
        failure_kind="validation_gate",
        detector={"command": "abyss-machine rag validate --json", "latest": str(RAG_VALIDATE_LATEST_PATH)},
        expected_behavior=["block treating retrieval as proof", "surface raw evidence refs only", "refresh RAG before deep reasoning"],
        covered_by=["abyss-machine rag validate --json", "abyss-machine self-awareness validate --json:full_stack_observation_sources"],
        evidence_refs=[evidence_ref(RAG_VALIDATE_LATEST_PATH, rag_validation.get("schema"))],
        current_state={"ok": rag_validation.get("ok"), "summary": rag_validation.get("summary")},
    )
    add_row(
        "machine.warm-e2b-resident-unavailable",
        "warm-E2B/gemma4 resident worker unavailable",
        owner="abyss-machine",
        failure_kind="resident_worker_unavailable",
        detector={"command": "abyss-machine ai llm resident status --json", "latest": str(AI_LLM_RESIDENT_ROOT / "status" / "latest.json")},
        expected_behavior=["keep deterministic investigation/replay available", "do not claim model-backed synthesis", "escalate only through resource/mode gates"],
        covered_by=["abyss-machine ai validate --json", "abyss-machine self-awareness probe --json:warm_e2b"],
        evidence_refs=[evidence_ref(AI_LLM_RESIDENT_ROOT / "status" / "latest.json", llm_resident_status.get("schema"))],
        current_state={"status": llm_resident_status.get("status"), "ok": llm_resident_status.get("ok")},
    )
    add_row(
        "machine.nervous-semantic-stale",
        "Nervous semantic sidecar stale before reasoning",
        owner="abyss-machine",
        failure_kind="freshness_gate",
        detector={
            "command": "abyss-machine nervous brief --scope now --json",
            "maintenance_review": NERVOUS_SEMANTIC_MAINTAIN_REVIEW_COMMAND,
            "maintenance_retry": NERVOUS_SEMANTIC_MAINTAIN_RETRY_COMMAND,
        },
        expected_behavior=["surface semantic_maintenance_needed", "keep raw/session evidence separate from truth", "run maintainer only through resource gates"],
        covered_by=["abyss-machine nervous validate --json", "abyss-machine self-awareness capabilities --json:nervous.freshness-gate"],
        evidence_refs=[evidence_ref(NERVOUS_BRIEF_LATEST_PATH, nervous.get("schema")), evidence_ref(NERVOUS_SEMANTIC_MAINTAIN_LATEST_PATH, semantic_maintain.get("schema"))],
        current_state={
            "readiness": nervous.get("readiness"),
            "semantic_maintain_decision": semantic_maintain.get("decision"),
            "blocked_reasons": nested_get(semantic_maintain, ["launch", "blocked_reasons"]),
        },
    )
    add_row(
        "machine.resource-denial",
        "Resource or game guard denies indexing/model escalation",
        owner="abyss-machine",
        failure_kind="resource_denial",
        detector={"command": "abyss-machine resource plan --class medium --kind indexing --unattended --json"},
        expected_behavior=["treat denial as safe gate, not validation failure", "record blocked_reasons", "do not override without explicit operator route"],
        covered_by=["abyss-machine resource validate --json", NERVOUS_SEMANTIC_MAINTAIN_REVIEW_COMMAND],
        evidence_refs=[evidence_ref(NERVOUS_SEMANTIC_MAINTAIN_LATEST_PATH, semantic_maintain.get("schema"))],
        current_state={"decision": semantic_maintain.get("decision"), "reason": semantic_maintain.get("reason")},
    )
    add_row(
        "machine.secret-redaction",
        "Secret-like content in events, queries, or briefs",
        owner="abyss-machine",
        failure_kind="redaction_risk",
        detector={"command": "abyss-machine self-awareness validate --json", "regex": "SELF_AWARENESS_SECRET_RE"},
        expected_behavior=["redact previews", "store hashes/previews only", "fail validation if secret-like preview remains"],
        covered_by=["abyss-machine self-awareness validate --json:no_secret_leakage", "abyss-machine self-awareness validate --json:fixture_redaction"],
        evidence_refs=[evidence_ref(SELF_AWARENESS_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_validate_v1")],
        current_state={"typing_validate": typing_validation.get("summary")},
    )
    add_row(
        "stack.downtime-bounded-readonly",
        "Stack service downtime during read-only collection",
        owner="abyss-stack",
        failure_kind="downtime",
        detector={"command": "abyss-machine self-awareness collect --json", "sources": ["prometheus", "loki", "grafana", "alloy", "containers"]},
        expected_behavior=["mark degraded_sources", "preserve latest evidence refs", "do not start/stop/reload stack services"],
        covered_by=["abyss-machine stack-bridge observability --json", "abyss-machine self-awareness collect --json"],
        evidence_refs=[evidence_ref(SELF_AWARENESS_COLLECT_LATEST_PATH, collect.get("schema"))],
        current_state={"degraded_sources": nested_get(collect, ["summary", "degraded_sources"]), "status": collect.get("status")},
    )
    base_required_rows = {
        "stack.prometheus-or-promql-missing",
        "stack.loki-logql-missing-or-cardinality-risk",
        "stack.grafana-health-or-auth-gap",
        "stack.alloy-otel-pipeline-missing",
        "stack.alertmanager-lifecycle-unavailable",
        "machine.rag-validation-missing-or-stale",
        "machine.warm-e2b-resident-unavailable",
        "machine.nervous-semantic-stale",
        "machine.resource-denial",
        "machine.secret-redaction",
        "stack.downtime-bounded-readonly",
    }
    required_rows = base_required_rows | {
        "requirement:" + requirement_id
        for requirement_id in sorted(known_stack_requirement_ids | set(requirement_by_id))
    }
    present_rows = {str(row.get("id")) for row in rows}
    malformed = [
        row.get("id") for row in rows
        if not row.get("id")
        or not row.get("owner")
        or not row.get("failure_kind")
        or not row.get("detector")
        or not row.get("expected_machine_behavior")
        or row.get("host_layer_mutates_stack") is not False
        or row.get("automatic_remediation") is not False
        or not row.get("evidence_refs")
    ]
    missing_required = sorted(required_rows - present_rows)
    by_owner = dict(collections.Counter(str(row.get("owner") or "unknown") for row in rows))
    by_failure_kind = dict(collections.Counter(str(row.get("failure_kind") or "unknown") for row in rows))
    data = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_failure_matrix_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": not malformed and not missing_required,
        "status": "covered" if not malformed and not missing_required else "incomplete",
        "summary": {
            "failure_modes": len(rows),
            "requirements_rows": sum(1 for row in rows if str(row.get("id")).startswith("requirement:")),
            "by_owner": by_owner,
            "by_failure_kind": by_failure_kind,
            "missing_required": missing_required,
            "malformed": malformed,
        },
        "rows": rows,
        "required_rows": sorted(required_rows),
        "policy": {
            "host_layer_mutates_stack": False,
            "automatic_remediation": False,
            "owner_route_required_before_mutation": True,
            "resource_denial_is_safe_gate": True,
            "freshness_precedes_reasoning": True,
        },
        "evidence_refs": [
            evidence_ref(SELF_AWARENESS_CAPABILITIES_LATEST_PATH, capabilities.get("schema")),
            evidence_ref(SELF_AWARENESS_REQUIREMENTS_LATEST_PATH, requirements.get("schema")),
            evidence_ref(SELF_AWARENESS_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_validate_v1"),
        ],
    }
    if write_latest:
        errors = write_latest_and_history(data, SELF_AWARENESS_FAILURE_MATRIX_LATEST_PATH, SELF_AWARENESS_FAILURE_MATRIX_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def self_awareness_failure_matrix_row_is_open_requirement(row: Any) -> bool:
    if not isinstance(row, dict) or not str(row.get("id") or "").startswith("requirement:"):
        return False
    failure_kind = str(row.get("failure_kind") or "")
    if failure_kind == "open_requirement":
        return True
    if failure_kind == "closed_requirement_regression_guard":
        return False
    current_state = row.get("current_state") if isinstance(row.get("current_state"), dict) else {}
    status = str(current_state.get("status") or row.get("status") or "")
    if current_state.get("closed_by_current_probe") is True:
        return False
    if status in {"closed", "not_current_requirement"}:
        return False
    return current_state.get("requirement_present") is True


def self_awareness_resident_worker_detail(
    status_doc: dict[str, Any],
    monitor_doc: dict[str, Any],
    digest_doc: dict[str, Any],
    micro_doc: dict[str, Any],
    evals_doc: dict[str, Any],
    candidates_doc: dict[str, Any],
) -> dict[str, Any]:
    def as_dict(value: Any) -> dict[str, Any]:
        return value if isinstance(value, dict) else {}

    def first_dict(values: Any) -> dict[str, Any]:
        if not isinstance(values, list):
            return {}
        return next((item for item in values if isinstance(item, dict)), {})

    health = as_dict(status_doc.get("health"))
    monitor_status = as_dict(monitor_doc.get("status"))
    serving = as_dict(health.get("serving")) or as_dict(status_doc.get("serving")) or as_dict(monitor_status.get("serving"))
    health_check = as_dict(health.get("health"))
    health_http = as_dict(health_check.get("_http"))
    models_health = as_dict(health.get("models"))
    models_http = as_dict(models_health.get("_http"))
    primary_model = first_dict(models_health.get("data")) or first_dict(models_health.get("models"))
    model_meta = as_dict(primary_model.get("meta"))
    service = as_dict(monitor_status.get("service")) or as_dict(status_doc.get("service"))
    metrics = as_dict(monitor_status.get("metrics")) or as_dict(status_doc.get("metrics"))
    micro_summary = as_dict(micro_doc.get("summary"))
    eval_summary = as_dict(evals_doc.get("summary"))
    candidates_summary = as_dict(candidates_doc.get("summary"))

    monitor_ok = monitor_doc.get("ok")
    if monitor_ok is None:
        monitor_ok = monitor_status.get("ok")
    if monitor_ok is None:
        monitor_ok = bool(status_doc.get("ok") and monitor_status.get("status") == "running")

    health_ok = health.get("ok")
    if health_ok is None:
        health_ok = bool(health_http.get("ok") or health_check.get("status") == "ok")

    candidate_action_execution = candidates_summary.get("action_execution")
    worker_ok = bool(
        status_doc.get("ok")
        and status_doc.get("status") == "running"
        and monitor_ok is not False
        and digest_doc.get("ok")
        and micro_doc.get("ok")
        and evals_doc.get("ok")
        and candidates_doc.get("ok")
        and candidate_action_execution is False
    )

    return {
        "status": status_doc.get("status") or monitor_status.get("status"),
        "ok": worker_ok,
        "profile": status_doc.get("profile") or monitor_status.get("profile") or "gemma4.spark",
        "model": status_doc.get("model") if isinstance(status_doc.get("model"), dict) else None,
        "serving": {
            "owner": serving.get("owner"),
            "base_url": serving.get("base_url"),
            "external_endpoint": serving.get("external_endpoint"),
            "local_fallback_allowed": serving.get("local_fallback_allowed"),
            "stack_owned_serving": serving.get("owner") == "abyss-stack",
        },
        "health": {
            "ok": bool(health_ok),
            "health_status_code": health_http.get("status"),
            "health_latency_ms": safe_float(health_http.get("latency_ms")),
            "models_status_code": models_http.get("status"),
            "models_latency_ms": safe_float(models_http.get("latency_ms")),
            "model_id": primary_model.get("id") or primary_model.get("name") or primary_model.get("model"),
            "n_ctx": safe_int(model_meta.get("n_ctx"), 0) or None,
            "n_ctx_train": safe_int(model_meta.get("n_ctx_train"), 0) or None,
            "n_embd": safe_int(model_meta.get("n_embd"), 0) or None,
            "n_params": safe_int(model_meta.get("n_params"), 0) or None,
            "served_model_size_bytes": safe_int(model_meta.get("size"), 0) or None,
        },
        "monitor": {
            "ok": bool(monitor_ok),
            "status": monitor_status.get("status"),
            "service_unit": service.get("service"),
            "service_active": service.get("active"),
            "service_enabled": service.get("enabled"),
            "legacy_start_timer_active": nested_get(service, ["timer", "active"]),
            "monitor_timer_active": nested_get(service, ["monitor_timer", "active"]),
            "digest_timer_active": nested_get(service, ["digest_timer", "active"]),
            "jobs_timer_active": nested_get(service, ["jobs_timer", "active"]),
            "micro_timer_active": nested_get(service, ["micro_timer", "active"]),
            "stack_owned_mode_legacy_service_expected_inactive": serving.get("owner") == "abyss-stack" and service.get("active") == "inactive",
        },
        "resource_thermal": {
            "package_temp_c": safe_float(metrics.get("package_temp_c")),
            "loadavg": metrics.get("loadavg"),
            "power_profile": nested_get(metrics, ["power", "profile"]),
            "on_ac": nested_get(metrics, ["power", "on_ac"]),
        },
        "candidate_context": {
            "digest_ok": digest_doc.get("ok"),
            "digest_status": digest_doc.get("status"),
            "micro_ok": micro_doc.get("ok"),
            "micro_status": micro_summary.get("status"),
            "micro_selected_job": micro_summary.get("selected_job"),
            "micro_next_job": micro_summary.get("next_job"),
            "micro_elapsed_ms": safe_float(micro_summary.get("elapsed_ms")),
            "micro_model_used": micro_summary.get("model_used"),
            "micro_fallback_used": micro_summary.get("fallback_used"),
            "candidate_readmodel": micro_summary.get("candidate_readmodel") if isinstance(micro_summary.get("candidate_readmodel"), dict) else None,
            "candidates": safe_int(candidates_summary.get("candidates"), 0) or None,
            "review_required": safe_int(candidates_summary.get("review_required"), 0),
            "selected": safe_int(candidates_summary.get("selected"), 0),
            "selected_for_heartbeat": safe_int(candidates_summary.get("selected_for_heartbeat"), 0),
            "selected_for_e4b_review": safe_int(candidates_summary.get("selected_for_e4b_review"), 0),
            "action_execution": candidate_action_execution,
        },
        "evals": {
            "overall_score": safe_float(eval_summary.get("overall_score")),
            "checks": safe_int(eval_summary.get("checks"), 0),
            "fails": safe_int(eval_summary.get("fails"), 0),
            "warnings": safe_int(eval_summary.get("warnings"), 0),
            "candidates": safe_int(eval_summary.get("candidates"), 0),
            "selected_for_e4b_review": safe_int(eval_summary.get("selected_for_e4b_review"), 0),
            "degraded_or_fallback_jobs": safe_int(eval_summary.get("degraded_or_fallback_jobs"), 0),
            "elapsed_ms": safe_float(eval_summary.get("elapsed_ms")),
        },
        "policy": {
            "model_execution_in_self_awareness_graph": False,
            "candidate_synthesis_only": True,
            "action_execution": candidate_action_execution is True,
            "resource_mode_gated": True,
            "host_layer_mutates_stack": False,
            "serving_owner": serving.get("owner"),
            "abyss_machine_writes_stack": False,
            "candidate_output_is_owner_truth": False,
        },
        "cognitive_contract": {
            "schema": f"{SCHEMA_PREFIX}_self_awareness_resident_cognitive_contract_v1",
            "worker": "warm-e2b/gemma4.spark",
            "bounded_context_packet_required": True,
            "read_only_tool_inventory_required": True,
            "hypothesis_testing_required": True,
            "contradiction_notes_required": True,
            "evidence_cited_summary_required": True,
            "resource_mode_gated_escalation_required": True,
            "direct_model_generation_in_self_awareness": False,
            "candidate_synthesis_only": True,
            "candidate_output_is_owner_truth": False,
            "host_layer_mutates_stack": False,
            "allowed_tool_kinds": [
                "promql_read",
                "logql_read",
                "self_awareness_query",
                "self_awareness_context",
                "self_awareness_spatial_graph",
                "rag_validate",
                "nervous_brief",
                "requirements_handoff",
                "resource_mode_gate",
            ],
        },
        "role": "monitored resident reasoning worker; candidate synthesis is not owner truth",
    }


def self_awareness_resident_worker_detail_complete(detail: dict[str, Any]) -> bool:
    if not isinstance(detail, dict):
        return False
    monitor_timer = str(nested_get(detail, ["monitor", "monitor_timer_active"]) or "")
    digest_timer = str(nested_get(detail, ["monitor", "digest_timer_active"]) or "")
    micro_timer = str(nested_get(detail, ["monitor", "micro_timer_active"]) or "")
    return (
        detail.get("ok") is True
        and detail.get("status") == "running"
        and nested_get(detail, ["serving", "owner"]) in {"abyss-stack", "abyss-machine"}
        and nested_get(detail, ["serving", "stack_owned_serving"]) is True
        and nested_get(detail, ["health", "ok"]) is True
        and nested_get(detail, ["health", "health_latency_ms"]) is not None
        and nested_get(detail, ["health", "model_id"]) is not None
        and nested_get(detail, ["monitor", "ok"]) is True
        and monitor_timer == "active"
        and digest_timer == "active"
        and micro_timer == "active"
        and nested_get(detail, ["resource_thermal", "package_temp_c"]) is not None
        and nested_get(detail, ["candidate_context", "digest_ok"]) is True
        and nested_get(detail, ["candidate_context", "micro_ok"]) is True
        and nested_get(detail, ["candidate_context", "candidates"]) is not None
        and nested_get(detail, ["candidate_context", "action_execution"]) is False
        and nested_get(detail, ["evals", "overall_score"]) is not None
        and nested_get(detail, ["policy", "model_execution_in_self_awareness_graph"]) is False
        and nested_get(detail, ["policy", "candidate_synthesis_only"]) is True
        and nested_get(detail, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(detail, ["policy", "abyss_machine_writes_stack"]) is False
        and nested_get(detail, ["policy", "candidate_output_is_owner_truth"]) is False
        and nested_get(detail, ["cognitive_contract", "schema"]) == f"{SCHEMA_PREFIX}_self_awareness_resident_cognitive_contract_v1"
        and nested_get(detail, ["cognitive_contract", "bounded_context_packet_required"]) is True
        and nested_get(detail, ["cognitive_contract", "read_only_tool_inventory_required"]) is True
        and nested_get(detail, ["cognitive_contract", "hypothesis_testing_required"]) is True
        and nested_get(detail, ["cognitive_contract", "contradiction_notes_required"]) is True
        and nested_get(detail, ["cognitive_contract", "resource_mode_gated_escalation_required"]) is True
        and nested_get(detail, ["cognitive_contract", "direct_model_generation_in_self_awareness"]) is False
        and nested_get(detail, ["cognitive_contract", "host_layer_mutates_stack"]) is False
    )


def self_awareness_ai_multimodal_detail(
    ai_caps: dict[str, Any],
    ai_devices_latest: dict[str, Any],
    ai_models_latest: dict[str, Any],
    ai_tts_profiles_latest: dict[str, Any],
    ai_tts_success_latest: dict[str, Any],
    ai_llm: dict[str, Any],
) -> dict[str, Any]:
    caps = ai_caps.get("capabilities") if isinstance(ai_caps.get("capabilities"), dict) else {}

    def cap(name: str) -> dict[str, Any]:
        value = caps.get(name)
        return value if isinstance(value, dict) else {}

    def compact_source_models(source_models: Any, limit: int = 4) -> list[dict[str, Any]]:
        models = source_models if isinstance(source_models, list) else []
        compact: list[dict[str, Any]] = []
        for item in models[:limit]:
            if not isinstance(item, dict):
                continue
            compact.append({
                "profile": item.get("profile"),
                "kind": item.get("kind"),
                "category": item.get("category"),
                "name": item.get("name"),
                "path": item.get("path") or item.get("model_dir"),
                "root": item.get("root"),
                "relative_path": item.get("relative_path"),
                "device": item.get("device"),
                "read_only_source": item.get("read_only_source"),
                "artifacts": item.get("artifacts") if isinstance(item.get("artifacts"), dict) else None,
                "file_summary": item.get("file_summary") if isinstance(item.get("file_summary"), dict) else None,
            })
        return compact

    def compact_llm_profiles(profiles: dict[str, Any]) -> dict[str, dict[str, Any]]:
        compact: dict[str, dict[str, Any]] = {}
        for name, profile in profiles.items():
            if not isinstance(profile, dict):
                continue
            compact[str(name)] = {
                "status": profile.get("status"),
                "role": profile.get("role"),
                "backend": profile.get("backend"),
                "declared_class": profile.get("declared_class"),
                "warm_policy": profile.get("warm_policy"),
                "local_exists": profile.get("local_exists"),
                "size_bytes": profile.get("size_bytes"),
                "local_path": profile.get("local_path"),
                "runtime_ok": nested_get(profile, ["runtime", "ok"]),
                "under_host_cache": nested_get(profile, ["storage", "under_host_cache"]),
                "host_layer_mutates_stack": nested_get(profile, ["policy", "host_layer_mutates_stack"]),
                "resource_gated": profile.get("declared_class") in {"heavy", "sustained"},
            }
        return compact

    def compact_tts_profiles(profiles: dict[str, Any]) -> dict[str, dict[str, Any]]:
        compact: dict[str, dict[str, Any]] = {}
        for name, profile in profiles.items():
            if not isinstance(profile, dict):
                continue
            compact[str(name)] = {
                "status": profile.get("status"),
                "engine": profile.get("engine"),
                "declared_class": profile.get("declared_class"),
                "device": profile.get("device"),
                "precision": profile.get("precision"),
                "model_path": nested_get(profile, ["model", "path"]),
                "model_exists": nested_get(profile, ["model", "exists"]),
                "model_complete": nested_get(profile, ["model", "complete"]),
                "model_read_only_source": nested_get(profile, ["model", "read_only_source"]),
                "openvino_path": nested_get(profile, ["openvino", "path"]),
                "openvino_complete": nested_get(profile, ["openvino", "complete"]),
                "openvino_host_managed": nested_get(profile, ["openvino", "host_managed"]),
                "runtime_ready": nested_get(profile, ["runtime", "ready"]),
                "synth_supported": nested_get(profile, ["runtime", "synth_supported"]),
                "host_layer_mutates_stack": nested_get(profile, ["policy", "host_layer_mutates_stack"]),
            }
        return compact

    stt = cap("stt")
    embeddings = cap("embeddings")
    llm_text = cap("llm_text")
    tts = cap("tts")
    npu = cap("npu")
    llm_profiles = ai_llm.get("profiles") if isinstance(ai_llm.get("profiles"), dict) else {}
    tts_profiles = ai_tts_profiles_latest.get("profiles") if isinstance(ai_tts_profiles_latest.get("profiles"), dict) else {}
    device_ready = ai_devices_latest.get("ready") if isinstance(ai_devices_latest.get("ready"), dict) else {}
    openvino = ai_devices_latest.get("openvino") if isinstance(ai_devices_latest.get("openvino"), dict) else {}
    model_summary = ai_models_latest.get("summary") if isinstance(ai_models_latest.get("summary"), dict) else {}
    model_roots = ai_models_latest.get("roots") if isinstance(ai_models_latest.get("roots"), list) else []
    stack_model_roots = [
        {
            "path": item.get("path"),
            "exists": item.get("exists"),
            "entries_seen": item.get("entries_seen"),
            "read_only_source": str(item.get("path") or "").startswith(("/srv/AbyssOS/abyss-stack", str(ABYSS_STACK_USER_SOURCE_ROOT))),
        }
        for item in model_roots
        if isinstance(item, dict)
    ]
    tts_executable = [
        name for name, profile in tts_profiles.items()
        if isinstance(profile, dict) and profile.get("status") == "executable"
    ]
    tts_latest_success = {
        "ok": ai_tts_success_latest.get("ok"),
        "generated_at": ai_tts_success_latest.get("generated_at"),
        "profile": ai_tts_success_latest.get("profile"),
        "summary": ai_tts_success_latest.get("summary") if isinstance(ai_tts_success_latest.get("summary"), dict) else None,
    }
    return {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_ai_multimodal_detail_v1",
        "status": "ready" if all(
            str(cap(name).get("status") or "") in accepted
            for name, accepted in {
                "stt": {"ready"},
                "embeddings": {"ready"},
                "llm_text": {"resident-running", "llama-cpp-ready"},
                "tts": {"runtime-proven", "bridge-ready"},
                "npu": {"runtime-ready"},
            }.items()
        ) else "degraded",
        "devices": {
            "openvino_ok": openvino.get("ok"),
            "openvino_version": openvino.get("openvino_version"),
            "available_devices": openvino.get("available_devices") if isinstance(openvino.get("available_devices"), list) else [],
            "ready": device_ready,
            "npu": nested_get(openvino, ["device_properties", "NPU"]),
            "gpu": nested_get(openvino, ["device_properties", "GPU"]),
            "cpu": nested_get(openvino, ["device_properties", "CPU"]),
        },
        "model_inventory": {
            "entries": model_summary.get("entries"),
            "by_category": model_summary.get("by_category"),
            "truncated": model_summary.get("truncated"),
            "roots": stack_model_roots,
        },
        "modalities": {
            "stt": {
                "status": stt.get("status"),
                "host_recommended_backend": stt.get("host_recommended_backend"),
                "primary_bridge": stt.get("primary_bridge"),
                "source_model_count": len(stt.get("source_models") if isinstance(stt.get("source_models"), list) else []),
                "source_models": compact_source_models(stt.get("source_models")),
                "non_claims": stt.get("non_claims") if isinstance(stt.get("non_claims"), list) else [],
            },
            "embeddings": {
                "status": embeddings.get("status"),
                "host_recommended_backend": embeddings.get("host_recommended_backend"),
                "primary_bridge": embeddings.get("primary_bridge"),
                "source_model_count": len(embeddings.get("source_models") if isinstance(embeddings.get("source_models"), list) else []),
                "source_models": compact_source_models(embeddings.get("source_models")),
                "stack_bridge_hint": embeddings.get("stack_bridge_hint"),
            },
            "llm_text": {
                "status": llm_text.get("status"),
                "host_recommended_backend": llm_text.get("host_recommended_backend"),
                "primary_bridge": llm_text.get("primary_bridge"),
                "resident_bridge": llm_text.get("resident_bridge"),
                "eval_bridge": llm_text.get("eval_bridge"),
                "source_model_count": len(llm_text.get("source_models") if isinstance(llm_text.get("source_models"), list) else []),
                "source_models": compact_source_models(llm_text.get("source_models"), limit=3),
                "registry_summary": ai_llm.get("summary"),
                "profiles": compact_llm_profiles(llm_profiles),
                "stack_bridge_hint": llm_text.get("stack_bridge_hint"),
            },
            "tts": {
                "status": tts.get("status"),
                "host_recommended_backend": tts.get("host_recommended_backend"),
                "primary_bridge": tts.get("primary_bridge"),
                "eval_bridge": tts.get("eval_bridge"),
                "server_bridge": tts.get("server_bridge"),
                "source_model_count": len(tts.get("source_models") if isinstance(tts.get("source_models"), list) else []),
                "source_models": compact_source_models(tts.get("source_models"), limit=4),
                "profile_summary": ai_tts_profiles_latest.get("summary"),
                "executable_profiles": sorted(tts_executable),
                "profiles": compact_tts_profiles(tts_profiles),
                "latest_success_eval": tts_latest_success,
                "non_claims": tts.get("non_claims") if isinstance(tts.get("non_claims"), list) else [],
            },
            "npu": {
                "status": npu.get("status"),
                "host_recommended_backend": npu.get("host_recommended_backend"),
                "primary_bridge": npu.get("primary_bridge"),
                "source_model_count": len(npu.get("source_models") if isinstance(npu.get("source_models"), list) else []),
                "device_ready": device_ready.get("npu"),
                "device_properties": nested_get(openvino, ["device_properties", "NPU"]),
                "non_claims": npu.get("non_claims") if isinstance(npu.get("non_claims"), list) else [],
            },
        },
        "source_refs": {
            "ai_capabilities": str(AI_CAPABILITIES_LATEST_PATH),
            "ai_devices": str(AI_DEVICES_LATEST_PATH),
            "ai_models": str(AI_MODELS_LATEST_PATH),
            "ai_tts_profiles": str(AI_TTS_PROFILES_LATEST_PATH),
            "ai_tts_latest_success": str(AI_TTS_EVAL_LATEST_SUCCESS_PATH),
            "ai_llm_registry": str(AI_LLM_REGISTRY_LATEST_PATH),
        },
        "policy": {
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "capability_presence_is_stack_promotion": False,
            "stack_model_roots_read_only": all(root.get("read_only_source") is True for root in stack_model_roots if root.get("path")),
            "host_caches_under_srv_abyss_machine": True,
            "future_stack_must_run_own_promotion_gates": True,
        },
    }


def self_awareness_ai_multimodal_detail_complete(detail: dict[str, Any]) -> bool:
    if not isinstance(detail, dict):
        return False
    modalities = detail.get("modalities") if isinstance(detail.get("modalities"), dict) else {}
    return (
        detail.get("status") == "ready"
        and nested_get(detail, ["devices", "openvino_ok"]) is True
        and {"CPU", "GPU", "NPU"}.issubset(set(nested_get(detail, ["devices", "available_devices"]) or []))
        and safe_int(nested_get(detail, ["model_inventory", "entries"]), 0) > 0
        and bool(nested_get(detail, ["model_inventory", "roots"]))
        and safe_int(nested_get(modalities, ["stt", "source_model_count"]), 0) > 0
        and safe_int(nested_get(modalities, ["embeddings", "source_model_count"]), 0) > 0
        and safe_int(nested_get(modalities, ["llm_text", "registry_summary", "ready_profiles"]), 0) > 0
        and bool(nested_get(modalities, ["llm_text", "profiles"]))
        and safe_int(nested_get(modalities, ["tts", "profile_summary", "executable"]), 0) > 0
        and bool(nested_get(modalities, ["tts", "profiles"]))
        and nested_get(modalities, ["npu", "device_ready"]) is True
        and nested_get(detail, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(detail, ["policy", "writes_project_roots"]) is False
        and nested_get(detail, ["policy", "capability_presence_is_stack_promotion"]) is False
        and nested_get(detail, ["policy", "future_stack_must_run_own_promotion_gates"]) is True
    )


def self_awareness_llm_escalation_detail(
    ai_llm: dict[str, Any],
    workhorse_pack: dict[str, Any],
    workhorse_review: dict[str, Any],
    workhorse_validate: dict[str, Any],
    workhorse_preflight: dict[str, Any],
    resource_latest: dict[str, Any],
    mode_latest: dict[str, Any],
) -> dict[str, Any]:
    profiles = ai_llm.get("profiles") if isinstance(ai_llm.get("profiles"), dict) else {}
    escalation_names = ("gemma4.workhorse", "qwen36.ordinary", "qwen36.heretic")

    def profile(name: str) -> dict[str, Any]:
        value = profiles.get(name)
        return value if isinstance(value, dict) else {}

    def command_ctx(command: Any) -> int | None:
        if not isinstance(command, str) or not command:
            return None
        try:
            parts = shlex.split(command)
        except ValueError:
            parts = command.split()
        for index, part in enumerate(parts):
            if part in {"--ctx", "-c"} and index + 1 < len(parts):
                ctx = safe_int(parts[index + 1], 0)
                return ctx or None
        return None

    def compact_escalation_profile(name: str) -> dict[str, Any]:
        item = profile(name)
        lazy_load = item.get("lazy_load") if isinstance(item.get("lazy_load"), dict) else {}
        server = item.get("server") if isinstance(item.get("server"), dict) else {}
        launch = item.get("launch") if isinstance(item.get("launch"), dict) else {}
        default_context = (
            command_ctx(lazy_load.get("request_command"))
            or command_ctx(lazy_load.get("start_command"))
            or safe_int(item.get("context_size"), 0)
            or safe_int(item.get("max_context_size"), 0)
            or None
        )
        return {
            "status": item.get("status"),
            "role": item.get("role"),
            "backend": item.get("backend"),
            "declared_class": item.get("declared_class"),
            "warm_policy": item.get("warm_policy"),
            "local_exists": item.get("local_exists"),
            "size_bytes": item.get("size_bytes"),
            "local_path": item.get("local_path"),
            "runtime_ok": nested_get(item, ["runtime", "ok"]),
            "under_host_cache": nested_get(item, ["storage", "under_host_cache"]),
            "host_layer_mutates_stack": nested_get(item, ["policy", "host_layer_mutates_stack"]),
            "resource_gated": item.get("declared_class") in {"heavy", "sustained"},
            "max_context_size": item.get("max_context_size"),
            "default_context_size": default_context,
            "launch": {
                "cli_smoke": launch.get("cli_smoke") if isinstance(launch.get("cli_smoke"), list) else None,
                "server_base": launch.get("server_base") if isinstance(launch.get("server_base"), list) else None,
            },
            "server": {
                "host": server.get("host"),
                "port_base": server.get("port_base"),
                "threads": server.get("threads"),
                "batch": server.get("batch"),
                "ubatch": server.get("ubatch"),
                "flash_attention": server.get("flash_attention"),
                "kv_cache": server.get("kv_cache"),
                "slot_cache_root": server.get("slot_cache_root"),
                "prefill_evidence_root": server.get("prefill_evidence_root"),
                "sleep_idle_seconds": server.get("sleep_idle_seconds"),
                "resource_class": server.get("resource_class") or item.get("declared_class"),
                "resource_kind": server.get("resource_kind"),
                "cpuset": server.get("cpuset"),
            },
            "lazy_load": {
                "tool": lazy_load.get("tool"),
                "start_command": lazy_load.get("start_command"),
                "prefill_command": lazy_load.get("prefill_command"),
                "restore_command": lazy_load.get("restore_command"),
                "request_command": lazy_load.get("request_command"),
                "stop_command": lazy_load.get("stop_command"),
            },
        }

    qwen_profiles = {
        name: compact_escalation_profile(name)
        for name in ("qwen36.ordinary", "qwen36.heretic")
    }
    workhorse_profile = compact_escalation_profile("gemma4.workhorse")
    validate_failed = [
        item.get("key")
        for item in workhorse_validate.get("checks", [])
        if isinstance(item, dict) and item.get("level") == "fail"
    ] if isinstance(workhorse_validate.get("checks"), list) else []
    latest_plan = resource_latest.get("latest_plan") if isinstance(resource_latest.get("latest_plan"), dict) else {}
    launch_policy = mode_latest.get("launch_policy") if isinstance(mode_latest.get("launch_policy"), dict) else {}
    cpu_routed_heavy = launch_policy.get("cpu_routed_heavy") if isinstance(launch_policy.get("cpu_routed_heavy"), dict) else {}
    preflight_resource = workhorse_preflight.get("resource") if isinstance(workhorse_preflight.get("resource"), dict) else {}
    preflight_decision = workhorse_preflight.get("decision")
    preflight_blocked_reasons = list(workhorse_preflight.get("blocked_reasons") if isinstance(workhorse_preflight.get("blocked_reasons"), list) else [])
    preflight_warnings = list(workhorse_preflight.get("warnings") if isinstance(workhorse_preflight.get("warnings"), list) else [])
    review_pipeline_ready = bool(
        workhorse_pack.get("ok")
        and workhorse_review.get("ok")
        and workhorse_validate.get("ok")
        and safe_int(nested_get(workhorse_validate, ["summary", "fails"]), -1) == 0
        and nested_get(workhorse_review, ["summary", "model_used"]) is False
        and nested_get(workhorse_review, ["policy", "action_execution"]) is False
        and nested_get(workhorse_review, ["policy", "starts_llama_server"]) is False
        and nested_get(workhorse_review, ["policy", "resident_service"]) is False
    )
    qwen_ready = all(
        qwen_profiles[name].get("status") == "ready"
        and qwen_profiles[name].get("local_exists") is True
        and qwen_profiles[name].get("runtime_ok") is True
        and qwen_profiles[name].get("declared_class") == "heavy"
        and qwen_profiles[name].get("host_layer_mutates_stack") is False
        and nested_get(qwen_profiles[name], ["lazy_load", "start_command"])
        and nested_get(qwen_profiles[name], ["lazy_load", "request_command"])
        and nested_get(qwen_profiles[name], ["server", "cpuset"])
        for name in qwen_profiles
    )
    qwen_default_contexts = [
        safe_int(item.get("default_context_size"), 0)
        for item in qwen_profiles.values()
        if safe_int(item.get("default_context_size"), 0) > 0
    ]
    qwen_max_contexts = [
        safe_int(item.get("max_context_size"), 0)
        for item in qwen_profiles.values()
        if safe_int(item.get("max_context_size"), 0) > 0
    ]
    route_ready = bool(
        ai_llm.get("ok")
        and all(profile(name).get("status") == "ready" for name in escalation_names)
        and review_pipeline_ready
        and qwen_ready
    )
    model_execution_allowed = bool(
        workhorse_preflight.get("ok") is True
        and preflight_decision in {"allow", "ready"}
        and preflight_resource.get("decision") in {"allow", "routed"}
    )
    if model_execution_allowed:
        execution_status = "allowed_now"
    elif preflight_decision == "block" or preflight_blocked_reasons:
        execution_status = "blocked_by_preflight"
    elif preflight_resource.get("decision") == "force_required" or latest_plan.get("decision") == "force_required":
        execution_status = "operator_force_required"
    else:
        execution_status = "gated_unknown"

    return {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_llm_escalation_detail_v1",
        "status": "ready_review_only" if route_ready else "degraded",
        "route_ready": route_ready,
        "review_pipeline_ready": review_pipeline_ready,
        "registry": {
            "ok": ai_llm.get("ok"),
            "summary": ai_llm.get("summary") if isinstance(ai_llm.get("summary"), dict) else {},
            "profiles": {
                name: {
                    "status": profile(name).get("status"),
                    "role": profile(name).get("role"),
                    "declared_class": profile(name).get("declared_class"),
                    "local_exists": profile(name).get("local_exists"),
                    "runtime_ok": nested_get(profile(name), ["runtime", "ok"]),
                }
                for name in escalation_names
            },
        },
        "workhorse": {
            "profile": "gemma4.workhorse",
            "profile_detail": workhorse_profile,
            "pack": {
                "ok": workhorse_pack.get("ok"),
                "generated_at": workhorse_pack.get("generated_at"),
                "summary": workhorse_pack.get("summary") if isinstance(workhorse_pack.get("summary"), dict) else {},
                "allowed_source_ids": len(workhorse_pack.get("allowed_source_ids") if isinstance(workhorse_pack.get("allowed_source_ids"), list) else []),
                "policy": workhorse_pack.get("policy") if isinstance(workhorse_pack.get("policy"), dict) else {},
            },
            "review": {
                "ok": workhorse_review.get("ok"),
                "generated_at": workhorse_review.get("generated_at"),
                "summary": workhorse_review.get("summary") if isinstance(workhorse_review.get("summary"), dict) else {},
                "policy": workhorse_review.get("policy") if isinstance(workhorse_review.get("policy"), dict) else {},
            },
            "validate": {
                "ok": workhorse_validate.get("ok"),
                "generated_at": workhorse_validate.get("generated_at"),
                "summary": workhorse_validate.get("summary") if isinstance(workhorse_validate.get("summary"), dict) else {},
                "failed_keys": validate_failed,
            },
            "preflight": {
                "ok": workhorse_preflight.get("ok"),
                "generated_at": workhorse_preflight.get("generated_at"),
                "decision": preflight_decision,
                "blocked_reasons": preflight_blocked_reasons,
                "warnings": preflight_warnings,
                "resource_decision": preflight_resource.get("decision"),
                "resource_blocked_reasons": list(preflight_resource.get("blocked_reasons") if isinstance(preflight_resource.get("blocked_reasons"), list) else []),
                "memory": workhorse_preflight.get("memory") if isinstance(workhorse_preflight.get("memory"), dict) else {},
                "model": workhorse_preflight.get("model") if isinstance(workhorse_preflight.get("model"), dict) else {},
                "policy": workhorse_preflight.get("policy") if isinstance(workhorse_preflight.get("policy"), dict) else {},
            },
            "policy": {
                "review_default_runs_model": False,
                "run_model_requires_explicit_flag": True,
                "non_resident": True,
                "starts_llama_server": False,
                "action_execution": False,
                "final_safety_gate": False,
                "requires_downstream_validator": True,
            },
        },
        "qwen_lazy_load": {
            "profiles": qwen_profiles,
            "ready": qwen_ready,
            "default_context_size": min(qwen_default_contexts) if qwen_default_contexts else None,
            "max_context_size": max(qwen_max_contexts) if qwen_max_contexts else None,
            "rare_deep_contexts": sorted({
                value
                for item in qwen_profiles.values()
                for value in (safe_int(item.get("max_context_size"), 0),)
                if value and value > safe_int(item.get("default_context_size"), 0)
            }),
        },
        "gates": {
            "model_execution_now": {
                "allowed": model_execution_allowed,
                "status": execution_status,
                "preflight_ok": workhorse_preflight.get("ok"),
                "preflight_decision": preflight_decision,
                "blocked_reasons": preflight_blocked_reasons,
                "resource_decision": preflight_resource.get("decision"),
                "resource_latest_plan_decision": latest_plan.get("decision"),
            },
            "mode": {
                "selected_mode": mode_latest.get("selected_mode"),
                "effective_mode": mode_latest.get("effective_mode"),
                "degraded": bool(mode_latest.get("degraded")),
                "max_unattended_class": launch_policy.get("max_unattended_class"),
                "can_start_heavy_unattended": launch_policy.get("can_start_heavy_unattended"),
                "operator_force_supported": launch_policy.get("operator_force_supported"),
                "cpu_routed_heavy": {
                    "can_start": cpu_routed_heavy.get("can_start"),
                    "can_start_unattended": cpu_routed_heavy.get("can_start_unattended"),
                    "requires_route_application": cpu_routed_heavy.get("requires_route_application"),
                    "command": cpu_routed_heavy.get("command"),
                    "cpuset": nested_get(cpu_routed_heavy, ["policy", "route", "cpuset"]),
                    "thread_limit": nested_get(cpu_routed_heavy, ["policy", "route", "thread_limit"]),
                    "thermal_class": nested_get(cpu_routed_heavy, ["policy", "distribution", "thermal_class"]),
                    "package_temperature_c_max": nested_get(cpu_routed_heavy, ["policy", "distribution", "package_temperature_c_max"]),
                },
            },
            "resource": {
                "latest_plan_decision": latest_plan.get("decision"),
                "latest_plan_request": latest_plan.get("request") if isinstance(latest_plan.get("request"), dict) else {},
                "preflight_decision": preflight_resource.get("decision"),
                "preflight_blocked_reasons": list(preflight_resource.get("blocked_reasons") if isinstance(preflight_resource.get("blocked_reasons"), list) else []),
                "systemd": preflight_resource.get("systemd") if isinstance(preflight_resource.get("systemd"), dict) else {},
            },
        },
        "evidence_paths": {
            "registry": str(AI_LLM_REGISTRY_LATEST_PATH),
            "workhorse_preflight": str(AI_LLM_WORKHORSE_PREFLIGHT_LATEST_PATH),
            "workhorse_pack": str(AI_LLM_WORKHORSE_PACK_LATEST_PATH),
            "workhorse_review": str(AI_LLM_WORKHORSE_REVIEW_LATEST_PATH),
            "workhorse_validate": str(AI_LLM_WORKHORSE_VALIDATE_LATEST_PATH),
            "resource": str(RESOURCE_LATEST_PATH),
            "mode": str(MODE_LATEST_PATH),
        },
        "policy": {
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "capability_presence_is_stack_promotion": False,
            "model_execution_in_self_awareness_graph": False,
            "default_model_execution": False,
            "human_approval_before_mutation": True,
            "operator_force_required_for_model_execution": not model_execution_allowed,
            "candidate_output_is_owner_truth": False,
            "action_execution": False,
            "qwen_lazy_load_is_not_resident_brain": True,
            "review_route_is_not_final_safety_gate": True,
        },
    }


def self_awareness_llm_escalation_detail_complete(detail: dict[str, Any]) -> bool:
    if not isinstance(detail, dict):
        return False
    profiles = nested_get(detail, ["registry", "profiles"]) or {}
    qwen_profiles = nested_get(detail, ["qwen_lazy_load", "profiles"]) or {}
    return (
        detail.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_llm_escalation_detail_v1"
        and detail.get("route_ready") is True
        and detail.get("review_pipeline_ready") is True
        and detail.get("status") == "ready_review_only"
        and all(
            isinstance(profiles.get(name), dict) and profiles[name].get("status") == "ready"
            for name in ("gemma4.workhorse", "qwen36.ordinary", "qwen36.heretic")
        )
        and nested_get(detail, ["workhorse", "pack", "ok"]) is True
        and nested_get(detail, ["workhorse", "pack", "allowed_source_ids"]) is not None
        and safe_int(nested_get(detail, ["workhorse", "pack", "summary", "source_ids"]), 0) > 0
        and nested_get(detail, ["workhorse", "pack", "policy", "e4b_may_review_only"]) is True
        and nested_get(detail, ["workhorse", "review", "ok"]) is True
        and nested_get(detail, ["workhorse", "review", "summary", "model_used"]) is False
        and safe_int(nested_get(detail, ["workhorse", "review", "summary", "fails"]), -1) == 0
        and nested_get(detail, ["workhorse", "review", "policy", "action_execution"]) is False
        and nested_get(detail, ["workhorse", "review", "policy", "starts_llama_server"]) is False
        and nested_get(detail, ["workhorse", "review", "policy", "resident_service"]) is False
        and nested_get(detail, ["workhorse", "validate", "ok"]) is True
        and safe_int(nested_get(detail, ["workhorse", "validate", "summary", "fails"]), -1) == 0
        and nested_get(detail, ["workhorse", "preflight", "decision"]) in {"allow", "ready", "block"}
        and nested_get(detail, ["workhorse", "preflight", "policy", "default_review_runs_model"]) is False
        and nested_get(detail, ["workhorse", "preflight", "policy", "starts_llama_server"]) is False
        and nested_get(detail, ["workhorse", "preflight", "policy", "resident_service"]) is False
        and nested_get(detail, ["qwen_lazy_load", "ready"]) is True
        and all(
            isinstance(qwen_profiles.get(name), dict)
            and qwen_profiles[name].get("status") == "ready"
            and qwen_profiles[name].get("declared_class") == "heavy"
            and qwen_profiles[name].get("local_exists") is True
            and qwen_profiles[name].get("runtime_ok") is True
            and qwen_profiles[name].get("host_layer_mutates_stack") is False
            and nested_get(qwen_profiles[name], ["lazy_load", "start_command"])
            and nested_get(qwen_profiles[name], ["lazy_load", "request_command"])
            and nested_get(qwen_profiles[name], ["server", "cpuset"])
            for name in ("qwen36.ordinary", "qwen36.heretic")
        )
        and nested_get(detail, ["gates", "model_execution_now", "status"]) in {"allowed_now", "blocked_by_preflight", "operator_force_required", "gated_unknown"}
        and nested_get(detail, ["gates", "model_execution_now", "allowed"]) in {True, False}
        and nested_get(detail, ["gates", "mode", "operator_force_supported"]) is not None
        and nested_get(detail, ["gates", "mode", "cpu_routed_heavy", "command"]) is not None
        and nested_get(detail, ["gates", "resource", "preflight_decision"]) is not None
        and nested_get(detail, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(detail, ["policy", "writes_project_roots"]) is False
        and nested_get(detail, ["policy", "capability_presence_is_stack_promotion"]) is False
        and nested_get(detail, ["policy", "model_execution_in_self_awareness_graph"]) is False
        and nested_get(detail, ["policy", "default_model_execution"]) is False
        and nested_get(detail, ["policy", "human_approval_before_mutation"]) is True
        and nested_get(detail, ["policy", "action_execution"]) is False
        and nested_get(detail, ["policy", "qwen_lazy_load_is_not_resident_brain"]) is True
        and nested_get(detail, ["policy", "review_route_is_not_final_safety_gate"]) is True
    )


def self_awareness_capabilities(write_latest: bool = True) -> dict[str, Any]:
    generated_at = now_iso()
    stack = stack_bridge_observability(write_latest=True)
    container_health = process_container_health(write_latest=True)
    prom_targets = memory_orchestrate_http_json(f"{STACK_OBSERVABILITY_PROMETHEUS_URL.rstrip()}/api/v1/targets", timeout=2.5)
    prom_rules = memory_orchestrate_http_json(f"{STACK_OBSERVABILITY_PROMETHEUS_URL.rstrip()}/api/v1/rules", timeout=2.5)
    prom_alerts = memory_orchestrate_http_json(f"{STACK_OBSERVABILITY_PROMETHEUS_URL.rstrip()}/api/v1/alerts", timeout=2.5)
    grafana_health = memory_orchestrate_http_json(f"{STACK_OBSERVABILITY_GRAFANA_URL.rstrip()}/api/health", timeout=2.0, max_bytes=65536)
    grafana_datasources = memory_orchestrate_http_json(f"{STACK_OBSERVABILITY_GRAFANA_URL.rstrip()}/api/datasources", timeout=2.0, max_bytes=131072)
    alertmanager_status = memory_orchestrate_http_json(f"{SELF_AWARENESS_ALERTMANAGER_URL.rstrip()}/api/v2/status", timeout=2.0)
    alertmanager_alerts = memory_orchestrate_http_json(f"{SELF_AWARENESS_ALERTMANAGER_URL.rstrip()}/api/v2/alerts", timeout=2.0)
    tempo_ready = memory_orchestrate_http_json(f"{SELF_AWARENESS_TEMPO_URL.rstrip()}/ready", timeout=1.2, max_bytes=65536)
    langgraph_api = memory_orchestrate_http_json(f"{SELF_AWARENESS_LANGGRAPH_URL.rstrip()}/health", timeout=1.2, max_bytes=65536)
    langchain_api = self_awareness_langchain_api_probe()
    stack_closure_external_evidence = self_awareness_stack_closure_external_evidence()
    trace_backend = self_awareness_trace_backend_probe(tempo_ready, stack, stack_closure_external_evidence)
    grafana_datasource_probe = self_awareness_grafana_datasource_probe(
        grafana_health,
        grafana_datasources,
        stack,
        alertmanager_status,
        trace_backend,
    )
    memory_space_routes = self_awareness_stack_memory_space_probe()
    langgraph_python = importlib.util.find_spec("langgraph") is not None
    ai_caps = ai_capabilities_latest()
    ai_cap_map = ai_caps.get("capabilities") if isinstance(ai_caps.get("capabilities"), dict) else {}
    ai_llm = ai_llm_registry(write_latest=True)
    ai_devices_latest = load_latest_json(AI_DEVICES_LATEST_PATH, f"{SCHEMA_PREFIX}_ai_devices_v1")
    ai_models_latest = load_latest_json(AI_MODELS_LATEST_PATH, f"{SCHEMA_PREFIX}_ai_models_v1")
    ai_tts_profiles_latest = load_latest_json(AI_TTS_PROFILES_LATEST_PATH, f"{SCHEMA_PREFIX}_ai_tts_profiles_v1")
    ai_tts_success_latest = load_latest_json(AI_TTS_EVAL_LATEST_SUCCESS_PATH, f"{SCHEMA_PREFIX}_ai_tts_eval_v1")
    llm_profiles = ai_llm.get("profiles") if isinstance(ai_llm.get("profiles"), dict) else {}
    llm_resident_status = load_latest_json(AI_LLM_RESIDENT_ROOT / "status" / "latest.json", f"{SCHEMA_PREFIX}_gemma4_spark_resident_status_v1")
    llm_resident_monitor = load_latest_json(AI_LLM_RESIDENT_ROOT / "monitor" / "latest.json", f"{SCHEMA_PREFIX}_gemma4_spark_resident_monitor_v1")
    llm_resident_digest = load_latest_json(AI_LLM_RESIDENT_ROOT / "digests" / "latest.json", f"{SCHEMA_PREFIX}_gemma4_spark_resident_digest_v1")
    llm_resident_micro = load_latest_json(AI_LLM_RESIDENT_ROOT / "jobs" / "micro" / "latest.json", f"{SCHEMA_PREFIX}_gemma4_spark_resident_micro_tick_v1")
    llm_resident_evals = load_latest_json(AI_LLM_RESIDENT_EVALS_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_spark_resident_heartbeat_evals_v1")
    llm_resident_candidates = load_latest_json(AI_LLM_RESIDENT_CANDIDATES_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_spark_resident_candidate_readmodel_v2")
    llm_workhorse_preflight = load_latest_json(AI_LLM_WORKHORSE_PREFLIGHT_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_workhorse_harness_preflight_v1")
    llm_workhorse_pack = load_latest_json(AI_LLM_WORKHORSE_PACK_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_workhorse_harness_e4b_review_pack_v2")
    llm_workhorse_review = load_latest_json(AI_LLM_WORKHORSE_REVIEW_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_workhorse_harness_review_v1")
    llm_workhorse_validate = load_latest_json(AI_LLM_WORKHORSE_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_workhorse_harness_validate_v1")
    rag_validation = rag_validate(strict=False, write_latest=True)
    nervous = nervous_brief(scope="now", limit=6, refresh=False, write_latest=True)
    memory_latest = load_latest_json(MEMORY_LATEST_PATH, f"{SCHEMA_PREFIX}_memory_status_v1")
    resource_latest = load_latest_json(RESOURCE_LATEST_PATH, f"{SCHEMA_PREFIX}_resource_status_v1")
    mode_latest = load_latest_json(MODE_LATEST_PATH, f"{SCHEMA_PREFIX}_mode_status_v1")
    reactions_latest = load_latest_json(REACTIONS_LATEST_PATH, f"{SCHEMA_PREFIX}_reactions_status_v1")
    responses_latest = load_latest_json(RESPONSES_LATEST_PATH, f"{SCHEMA_PREFIX}_responses_status_v1")
    containers = container_health.get("containers") if isinstance(container_health.get("containers"), list) else []
    container_names = sorted(set(
        str(name)
        for item in containers if isinstance(item, dict)
        for name in (item.get("names") if isinstance(item.get("names"), list) else [item.get("name")])
        if name
    ))
    requirements: list[dict[str, Any]] = []
    stack_summary = stack.get("summary") if isinstance(stack.get("summary"), dict) else {}
