def self_awareness_working_stack_activation_smoke_complete(smoke: Any) -> bool:
    if not isinstance(smoke, dict):
        return False
    rows = smoke.get("rows") if isinstance(smoke.get("rows"), list) else []
    summary = smoke.get("summary") if isinstance(smoke.get("summary"), dict) else {}
    packets = smoke.get("stack_organ_use_packets") if isinstance(smoke.get("stack_organ_use_packets"), list) else []
    packet_by_service = smoke.get("stack_organ_use_packet_by_service") if isinstance(smoke.get("stack_organ_use_packet_by_service"), dict) else {}
    service_ids = [str(row.get("service")) for row in rows if isinstance(row, dict) and row.get("service")]
    summary_service_ids = [str(item) for item in (summary.get("service_ids") if isinstance(summary.get("service_ids"), list) else [])]
    expected_services = [str(item) for item in (summary.get("stack_organs_expected_services") if isinstance(summary.get("stack_organs_expected_services"), list) else [])]
    return (
        smoke.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_working_stack_activation_smoke_v1"
        and smoke.get("ok") is True
        and bool(smoke.get("run_id"))
        and bool(rows)
        and bool(packets)
        and bool(expected_services)
        and safe_int(summary.get("stack_organs_expected"), -1) == len(expected_services)
        and safe_int(summary.get("rows"), -1) == len(rows)
        and safe_int(summary.get("rows_ok"), -1) == len(rows)
        and safe_int(summary.get("stack_organ_use_packets"), -1) == len(rows)
        and safe_int(summary.get("stack_organ_use_packets_complete"), -1) == len(rows)
        and sorted(summary_service_ids) == sorted(service_ids)
        and len(packets) == len(rows)
        and set(service_ids) == set(expected_services)
        and set(str(item) for item in packet_by_service) == set(service_ids)
        and not summary.get("stack_organs_without_use_packets")
        and summary.get("all_stack_organs_have_use_packets") is True
        and all(self_awareness_stack_organ_use_packet_complete(packet) for packet in packets)
        and not summary.get("failed_services")
        and all(self_awareness_working_stack_activation_smoke_row_complete(row) for row in rows)
        and bool(smoke.get("evidence_refs"))
        and nested_get(smoke, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(smoke, ["policy", "executes_commands"]) is False
        and nested_get(smoke, ["policy", "action_execution"]) is False
        and nested_get(smoke, ["policy", "automatic_remediation"]) is False
    )


def self_awareness_activation_smoke_needs_refresh(smoke: dict[str, Any], activation_entries: list[dict[str, Any]], expected_services: Iterable[str] | None = None) -> bool:
    if not self_awareness_working_stack_activation_smoke_complete(smoke):
        return True
    rows = smoke.get("rows") if isinstance(smoke.get("rows"), list) else []
    row_by_service = {
        str(row.get("service")): row
        for row in rows
        if isinstance(row, dict) and row.get("service")
    }
    expected_service_set = {
        str(entry.get("service"))
        for entry in activation_entries
        if isinstance(entry, dict) and entry.get("service")
    }
    if expected_services is not None:
        expected_service_set = {str(service) for service in expected_services if service}
    if set(row_by_service) != expected_service_set:
        return True
    entry_by_service = {
        str(entry.get("service")): entry
        for entry in activation_entries
        if isinstance(entry, dict) and entry.get("service")
    }
    for service in set(row_by_service) & set(entry_by_service):
        entry = entry_by_service.get(service, {})
        if not isinstance(entry, dict) or not entry.get("service"):
            continue
        row = row_by_service.get(str(entry.get("service")), {})
        if (
            str(row.get("machine_usage_status") or "") != str(entry.get("machine_usage_status") or "")
            or str(row.get("working_stack_link_id") or "") != str(entry.get("working_stack_link_id") or "")
        ):
            return True
    return False


def self_awareness_activation_smoke(
    write_latest: bool = True,
    *,
    stack_closure_dossier_doc: dict[str, Any] | None = None,
    working_stack_doc: dict[str, Any] | None = None,
) -> dict[str, Any]:
    generated_at = now_iso()
    run_id = "saactsmoke-" + stable_hash_json({"at": generated_at, "host": platform.node(), "pid": os.getpid()}, length=16)
    working_stack_doc_supplied = isinstance(working_stack_doc, dict)
    stack_closure_dossier = stack_closure_dossier_doc if isinstance(stack_closure_dossier_doc, dict) else load_latest_json(SELF_AWARENESS_STACK_CLOSURE_DOSSIER_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_stack_closure_dossier_v1")
    if stack_closure_dossier.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_stack_closure_dossier_v1":
        stack_closure_dossier = self_awareness_stack_closure_dossier(write_latest=True)
    working_stack_doc = working_stack_doc if isinstance(working_stack_doc, dict) else load_latest_json(SELF_AWARENESS_WORKING_STACK_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_working_stack_inventory_v1")
    if working_stack_doc.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_working_stack_inventory_v1":
        working_stack_doc = self_awareness_working_stack_inventory(write_latest=True)
    working_stack_organs = [
        organ for organ in (working_stack_doc.get("organs") if isinstance(working_stack_doc.get("organs"), list) else [])
        if isinstance(organ, dict) and organ.get("service")
    ]
    expected_stack_organ_services = sorted(str(organ.get("service")) for organ in working_stack_organs)
    activation_dossier = stack_closure_dossier.get("working_stack_activation_dossier") if isinstance(stack_closure_dossier.get("working_stack_activation_dossier"), dict) else {}
    activation_entries = activation_dossier.get("entries") if isinstance(activation_dossier.get("entries"), list) else []
    activation_entry_by_service = {
        str(entry.get("service")): entry
        for entry in activation_entries
        if isinstance(entry, dict) and entry.get("service")
    }
    previous_smoke = load_latest_json(SELF_AWARENESS_ACTIVATION_SMOKE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_working_stack_activation_smoke_v1")
    previous_by_service = previous_smoke.get("by_service") if isinstance(previous_smoke.get("by_service"), dict) else {}
    episodes_doc = load_latest_json(SELF_AWARENESS_EPISODES_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_episodes_v1")
    episode_identity_missing_before_refresh = self_awareness_working_stack_activation_missing_episode_services(activation_entries, episodes_doc)
    episodes_refreshed_for_identity = False
    if (
        episodes_doc.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_episodes_v1"
        or safe_int(nested_get(episodes_doc, ["summary", "working_stack_gap_episodes"]), -1) < len(activation_entries)
        or episode_identity_missing_before_refresh
    ):
        if working_stack_doc_supplied:
            episodes_doc = self_awareness_episodes(write_latest=True, working_stack_doc=working_stack_doc)
        else:
            episodes_doc = self_awareness_episodes(write_latest=True)
        episodes_refreshed_for_identity = True
    episode_identity_missing_after_refresh = self_awareness_working_stack_activation_missing_episode_services(activation_entries, episodes_doc)

    rows: list[dict[str, Any]] = []
    for organ in working_stack_organs:
        if not isinstance(organ, dict) or not organ.get("service"):
            continue
        service = str(organ.get("service") or "")
        rows.append(self_awareness_working_stack_movement_smoke_row(
            organ,
            activation_entry_by_service.get(service),
            previous_by_service.get(service) if isinstance(previous_by_service.get(service), dict) else None,
            generated_at=generated_at,
            run_id=run_id,
        ))

    by_service = {
        str(row.get("service")): row
        for row in rows
        if isinstance(row, dict) and row.get("service")
    }
    stack_organ_use_packets = [
        row.get("stack_organ_use_packet")
        for row in rows
        if isinstance(row, dict) and isinstance(row.get("stack_organ_use_packet"), dict)
    ]
    stack_organ_use_packet_by_service = {
        str(packet.get("service")): packet
        for packet in stack_organ_use_packets
        if isinstance(packet, dict) and packet.get("service")
    }
    stack_organ_use_packet_services = sorted(str(service) for service in stack_organ_use_packet_by_service)
    stack_organs_without_use_packets = sorted(set(expected_stack_organ_services) - set(stack_organ_use_packet_services))
    all_stack_organs_have_use_packets = (
        bool(expected_stack_organ_services)
        and not stack_organs_without_use_packets
        and len(stack_organ_use_packets) == len(expected_stack_organ_services)
        and all(self_awareness_stack_organ_use_packet_complete(packet) for packet in stack_organ_use_packets)
    )
    failed_services = [str(row.get("service") or "unknown") for row in rows if not self_awareness_working_stack_activation_smoke_row_complete(row)]
    service_ids = [str(row.get("service")) for row in rows if isinstance(row, dict) and row.get("service")]
    selected_for_resident_reasoning = sorted(
        str(row.get("service"))
        for row in rows
        if nested_get(row, ["stack_organ_use_packet", "movement_selection", "selected_for_resident_reasoning"]) is True
    )
    selected_for_episode = sorted(
        str(row.get("service"))
        for row in rows
        if nested_get(row, ["stack_organ_use_packet", "movement_selection", "selected_for_episode"]) is True
    )
    movement_category_counts: dict[str, int] = {}
    for row in rows:
        categories = nested_get(row, ["stack_organ_use_packet", "movement_selection", "categories"])
        for category in categories if isinstance(categories, list) else []:
            key = str(category)
            movement_category_counts[key] = movement_category_counts.get(key, 0) + 1
    activation_gap_classifications = sorted({
        str(nested_get(packet, ["activation_gap", "classification"]))
        for packet in stack_organ_use_packets
        if nested_get(packet, ["activation_gap", "classification"])
    })
    data = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_working_stack_activation_smoke_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "run_id": run_id,
        "ok": bool(rows) and all_stack_organs_have_use_packets and not failed_services and set(service_ids) == set(expected_stack_organ_services),
        "status": "complete" if bool(rows) and all_stack_organs_have_use_packets and not failed_services and set(service_ids) == set(expected_stack_organ_services) else "incomplete",
        "summary": {
            "activation_entries": len([entry for entry in activation_entries if isinstance(entry, dict) and entry.get("service")]),
            "stack_organs_expected": len(expected_stack_organ_services),
            "stack_organs_expected_services": expected_stack_organ_services,
            "rows": len(rows),
            "rows_ok": sum(1 for row in rows if self_awareness_working_stack_activation_smoke_row_complete(row)),
            "actual_investigation_runs": sum(1 for row in rows if nested_get(row, ["investigation", "actual_run"]) is True),
            "actual_replay_runs": sum(1 for row in rows if nested_get(row, ["replay", "actual_run"]) is True),
            "stack_organ_use_packets": len(stack_organ_use_packets),
            "stack_organ_use_packets_complete": sum(1 for packet in stack_organ_use_packets if self_awareness_stack_organ_use_packet_complete(packet)),
            "stack_organ_use_packet_services": stack_organ_use_packet_services,
            "stack_organs_without_use_packets": stack_organs_without_use_packets,
            "all_stack_organs_have_use_packets": all_stack_organs_have_use_packets,
            "selected_for_episode": selected_for_episode,
            "selected_for_resident_reasoning": selected_for_resident_reasoning,
            "movement_category_counts": movement_category_counts,
            "activation_gap_classifications": activation_gap_classifications,
            "divergences": sum(safe_int(nested_get(row, ["replay", "divergences"]), 0) for row in rows),
            "failed_services": failed_services,
            "service_ids": service_ids,
            "open_activation_gaps": safe_int(nested_get(activation_dossier, ["summary", "open_activation_gaps"]), len(rows)),
            "episode_identity_missing_before_refresh": episode_identity_missing_before_refresh,
            "episodes_refreshed_for_identity": episodes_refreshed_for_identity,
            "episode_identity_missing_after_refresh": episode_identity_missing_after_refresh,
            "latest_artifact_overwrite_note": "investigate/latest.json and replay/latest.json contain the last row run; this matrix preserves every per-service thread and replay result.",
        },
        "rows": rows,
        "by_service": by_service,
        "stack_organ_use_packets": stack_organ_use_packets,
        "stack_organ_use_packet_by_service": stack_organ_use_packet_by_service,
        "compact_by_service": {
            service: self_awareness_working_stack_activation_smoke_compact(row)
            for service, row in by_service.items()
        },
        "activation_dossier_summary": activation_dossier.get("summary") if isinstance(activation_dossier.get("summary"), dict) else {},
        "source_commands": {
            "activation_smoke": "abyss-machine self-awareness activation-smoke --json",
            "stack_closure_dossier": "abyss-machine self-awareness stack-closure-dossier --json",
            "episodes": "abyss-machine self-awareness episodes --json",
            "investigate": "abyss-machine self-awareness investigate --episode-id EPISODE_ID --json",
            "replay": "abyss-machine self-awareness replay --thread-id THREAD_ID --json",
        },
        "evidence_refs": [
            {"path": str(SELF_AWARENESS_STACK_CLOSURE_DOSSIER_LATEST_PATH), "section": "working_stack_activation_dossier"},
            {"path": str(SELF_AWARENESS_EPISODES_LATEST_PATH), "section": "working_stack_gap_episodes"},
            *[
                {"path": str(SELF_AWARENESS_INVESTIGATE_LATEST_PATH), "thread_id": nested_get(row, ["investigation", "thread_id"]), "service": row.get("service")}
                for row in rows
                if nested_get(row, ["investigation", "thread_id"])
            ],
            *[
                {"path": str(SELF_AWARENESS_REPLAY_LATEST_PATH), "thread_id": nested_get(row, ["replay", "thread_id"]), "service": row.get("service")}
                for row in rows
                if nested_get(row, ["replay", "thread_id"])
            ],
        ],
        "policy": {
            "readmodel_smoke": True,
            "per_service_actual_investigate_replay": True,
            "read_only": True,
            "handoff_only": True,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
            "executes_commands": False,
            "action_execution": False,
            "automatic_remediation": False,
            "raw_secrets_included": False,
            "raw_private_content_included": False,
            "open_activation_gaps_are_unexhausted_potential_not_host_failures": True,
        },
    }
    data["complete"] = self_awareness_working_stack_activation_smoke_complete(data)
    if write_latest:
        errors = write_latest_and_history(data, SELF_AWARENESS_ACTIVATION_SMOKE_LATEST_PATH, SELF_AWARENESS_ACTIVATION_SMOKE_ROOT)
        if errors:
            data["ok"] = False
            data["complete"] = False
            data["write_errors"] = errors
    return data


def self_awareness_export_artifact_refs(exported: dict[str, Any], names: list[str]) -> dict[str, Any]:
    refs: dict[str, Any] = {}
    for name in names:
        artifact = exported.get(name)
        if not isinstance(artifact, dict):
            continue
        refs[name] = {
            "path": artifact.get("path"),
            "history_path": artifact.get("history_path"),
            "schema": artifact.get("schema") or artifact.get("expected_schema"),
            "sha256": artifact.get("sha256"),
            "artifact_status": artifact.get("artifact_status"),
            "evidence_ref": artifact.get("evidence_ref"),
        }
    return refs


def self_awareness_export_artifact_entry(name: str, path: Path, schema: str) -> dict[str, Any]:
    data = load_latest_json(path, schema)
    exists = path.exists()
    schema_ok = data.get("schema") == schema
    artifact_status = "missing" if not data.get("schema") else ("schema_mismatch" if not schema_ok else "present")
    daily_path = ai_daily_jsonl_path(path.parent)
    return {
        "name": name,
        "path": str(path),
        "history_path": str(daily_path),
        "exists": exists,
        "history_exists": daily_path.exists(),
        "expected_schema": schema,
        "schema": data.get("schema"),
        "schema_ok": schema_ok,
        "ok": data.get("ok"),
        "status": data.get("status"),
        "generated_at": data.get("generated_at"),
        "summary": data.get("summary"),
        "artifact_status": artifact_status,
        "size_bytes": path.stat().st_size if exists else None,
        "sha256": sha256_path(path) if exists else None,
        "evidence_ref": {"path": str(path), "schema": data.get("schema") or schema},
    }


def self_awareness_export_artifact_status_lists(exported: dict[str, Any]) -> tuple[list[str], list[str]]:
    missing = sorted(
        str(name)
        for name, artifact in exported.items()
        if isinstance(artifact, dict) and artifact.get("artifact_status") == "missing"
    )
    malformed = sorted(
        str(name)
        for name, artifact in exported.items()
        if isinstance(artifact, dict) and artifact.get("artifact_status") == "schema_mismatch"
    )
    return missing, malformed


def self_awareness_refresh_exported_artifacts(
    exported: dict[str, Any],
    artifact_specs: dict[str, tuple[Path, str]],
    names: list[str],
) -> tuple[list[dict[str, Any]], list[str], list[str]]:
    for name in names:
        spec = artifact_specs.get(name)
        if not spec:
            continue
        path, schema = spec
        exported[name] = self_awareness_export_artifact_entry(name, path, schema)
    artifact_list = sorted(
        [artifact for artifact in exported.values() if isinstance(artifact, dict)],
        key=lambda item: str(item.get("name") or ""),
    )
    missing, malformed = self_awareness_export_artifact_status_lists(exported)
    return artifact_list, missing, malformed


def self_awareness_include_coverage_audit_artifact(artifacts: dict[str, tuple[Path, str]]) -> None:
    artifacts["coverage_audit"] = (
        SELF_AWARENESS_COVERAGE_AUDIT_LATEST_PATH,
        f"{SCHEMA_PREFIX}_self_awareness_objective_coverage_audit_v1",
    )


def self_awareness_entity_event_document_map_issues(
    mapping: Any,
    *,
    expected_stack_organs: int | None = None,
    expected_machine_bridges: int | None = None,
) -> list[str]:
    issues: list[str] = []
    if not isinstance(mapping, dict):
        return ["map_missing"]
    summary = mapping.get("summary") if isinstance(mapping.get("summary"), dict) else {}
    automation = mapping.get("automation") if isinstance(mapping.get("automation"), dict) else {}
    validation_contract = automation.get("validation_contract") if isinstance(automation.get("validation_contract"), dict) else {}
    policy = mapping.get("policy") if isinstance(mapping.get("policy"), dict) else {}
    entities = mapping.get("entities") if isinstance(mapping.get("entities"), list) else []
    events = mapping.get("events") if isinstance(mapping.get("events"), list) else []
    documents = mapping.get("documents") if isinstance(mapping.get("documents"), list) else []
    stack_organ_entities = mapping.get("stack_organ_entities") if isinstance(mapping.get("stack_organ_entities"), list) else []
    machine_bridge_entities = mapping.get("machine_bridge_entities") if isinstance(mapping.get("machine_bridge_entities"), list) else []
    document_ids = {str(document.get("document_id")) for document in documents if isinstance(document, dict) and document.get("document_id")}

    if mapping.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_entity_event_document_map_v1":
        issues.append("schema")
    if mapping.get("ok") is not True or summary.get("automation_ready") is not True:
        issues.append("automation_not_ready")
    if policy.get("host_layer_mutates_stack") is not False or policy.get("executes_commands") is not False:
        issues.append("policy")
    if automation.get("runs_probe") is not False or automation.get("runs_cycle") is not False or automation.get("runs_indexing") is not False:
        issues.append("automation_runs_heavy_work")
    if automation.get("runs_stack_http_probes") is not False or automation.get("executes_verifiers") is not False:
        issues.append("automation_executes_verifiers_or_stack_probes")
    for key in (
        "every_action_has_entity",
        "every_action_has_event",
        "every_route_action_has_entity",
        "every_entity_has_document_refs",
        "every_entity_has_route",
        "every_stack_organ_has_entity",
        "every_machine_bridge_has_entity",
        "document_refs_resolve",
    ):
        if validation_contract.get(key) is not True:
            issues.append(f"validation_contract:{key}")
    if validation_contract.get("host_layer_mutates_stack") is not False:
        issues.append("validation_contract:host_layer_mutates_stack")
    if safe_int(summary.get("entities"), -1) != len(entities):
        issues.append("entity_count")
    if safe_int(summary.get("events"), -1) != len(events):
        issues.append("event_count")
    if safe_int(summary.get("documents"), -1) != len(documents):
        issues.append("document_count")
    if safe_int(summary.get("stack_organs"), -1) != len(stack_organ_entities):
        issues.append("stack_organ_count")
    if safe_int(summary.get("machine_bridges"), -1) != len(machine_bridge_entities):
        issues.append("machine_bridge_count")
    if safe_int(summary.get("body_surfaces"), -1) != len(stack_organ_entities) + len(machine_bridge_entities):
        issues.append("body_surface_count")
    if expected_stack_organs is not None and safe_int(summary.get("stack_organs"), -1) != expected_stack_organs:
        issues.append("expected_stack_organ_count")
    if expected_machine_bridges is not None and safe_int(summary.get("machine_bridges"), -1) != expected_machine_bridges:
        issues.append("expected_machine_bridge_count")
    for key in ("unmapped_actions", "unmapped_route_actions", "unmapped_stack_organs", "unmapped_machine_bridges", "unmapped_document_refs"):
        if summary.get(key):
            issues.append(key)
    for document in documents:
        if not isinstance(document, dict):
            issues.append("malformed_document")
            continue
        document_id = str(document.get("document_id") or "unknown")
        if document.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_entity_event_document_document_v1":
            issues.append(f"{document_id}:document_schema")
        if not document.get("document_path") or not document.get("path") or not document.get("role"):
            issues.append(f"{document_id}:document_identity")
        if nested_get(document, ["policy", "host_layer_mutates_stack"]) is not False or nested_get(document, ["policy", "executes_commands"]) is not False:
            issues.append(f"{document_id}:document_policy")
    event_ids = {str(event.get("event_id")) for event in events if isinstance(event, dict) and event.get("event_id")}
    for entity in entities:
        if not isinstance(entity, dict):
            issues.append("malformed_entity")
            continue
        entity_id = str(entity.get("entity_id") or "unknown")
        entity_document_ids = [str(document_id) for document_id in (entity.get("document_ids") if isinstance(entity.get("document_ids"), list) else [])]
        if entity.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_entity_event_document_entity_v1":
            issues.append(f"{entity_id}:entity_schema")
        if not entity.get("entity_path") or not entity.get("entity_kind") or not entity.get("event_id") or not entity.get("route_path"):
            issues.append(f"{entity_id}:entity_identity")
        if str(entity.get("event_id")) not in event_ids:
            issues.append(f"{entity_id}:event_ref")
        if not entity_document_ids:
            issues.append(f"{entity_id}:document_refs")
        if not set(entity_document_ids).issubset(document_ids):
            issues.append(f"{entity_id}:document_ref_resolution")
        if nested_get(entity, ["policy", "host_layer_mutates_stack"]) is not False or nested_get(entity, ["policy", "executes_commands"]) is not False:
            issues.append(f"{entity_id}:entity_policy")
        if entity.get("entity_kind") == "stack_organ" and (
            entity.get("route_path") != "body/stack-organs"
            or not nested_get(entity, ["subject", "service"])
            or not nested_get(entity, ["subject", "working_stack_link_id"])
            or not entity.get("evidence_refs")
        ):
            issues.append(f"{entity_id}:stack_organ_depth")
        if entity.get("entity_kind") == "machine_bridge" and (
            entity.get("route_path") != "body/machine-bridges"
            or not nested_get(entity, ["subject", "bridge_id"])
            or not nested_get(entity, ["artifact", "path"])
            or not nested_get(entity, ["artifact", "sha256"])
            or not entity.get("evidence_refs")
        ):
            issues.append(f"{entity_id}:machine_bridge_depth")
    entity_ids = {str(entity.get("entity_id")) for entity in entities if isinstance(entity, dict) and entity.get("entity_id")}
    for event in events:
        if not isinstance(event, dict):
            issues.append("malformed_event")
            continue
        event_id = str(event.get("event_id") or "unknown")
        event_document_ids = [str(document_id) for document_id in (event.get("document_ids") if isinstance(event.get("document_ids"), list) else [])]
        if event.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_entity_event_document_event_v1":
            issues.append(f"{event_id}:event_schema")
        if not event.get("event_path") or not event.get("event_kind") or str(event.get("entity_id") or "") not in entity_ids:
            issues.append(f"{event_id}:event_identity")
        if not event_document_ids or not set(event_document_ids).issubset(document_ids):
            issues.append(f"{event_id}:event_document_refs")
        if nested_get(event, ["policy", "host_layer_mutates_stack"]) is not False or nested_get(event, ["policy", "executes_commands"]) is not False:
            issues.append(f"{event_id}:event_policy")
    return sorted(set(issues))


def self_awareness_entity_event_document_map_complete(
    mapping: Any,
    *,
    expected_stack_organs: int | None = None,
    expected_machine_bridges: int | None = None,
) -> bool:
    return not self_awareness_entity_event_document_map_issues(
        mapping,
        expected_stack_organs=expected_stack_organs,
        expected_machine_bridges=expected_machine_bridges,
    )


def self_awareness_response_entity_event_document_context(
    *,
    completion_audit_doc: dict[str, Any] | None = None,
    episode: dict[str, Any] | None = None,
    source_event: dict[str, Any] | None = None,
    body_trace: dict[str, Any] | None = None,
) -> dict[str, Any]:
    completion_audit_doc = completion_audit_doc if isinstance(completion_audit_doc, dict) else load_latest_json(
        SELF_AWARENESS_COMPLETION_AUDIT_LATEST_PATH,
        f"{SCHEMA_PREFIX}_self_awareness_completion_audit_v1",
    )
    episode = episode if isinstance(episode, dict) else {}
    source_event = source_event if isinstance(source_event, dict) else {}
    body_trace = body_trace if isinstance(body_trace, dict) else {}
    mapping = completion_audit_doc.get("entity_event_document_map") if isinstance(completion_audit_doc.get("entity_event_document_map"), dict) else {}
    route_packets = completion_audit_doc.get("completion_route_packets") if isinstance(completion_audit_doc.get("completion_route_packets"), dict) else {}
    map_issues = self_awareness_entity_event_document_map_issues(mapping)
    entities = mapping.get("entities") if isinstance(mapping.get("entities"), list) else []
    events = mapping.get("events") if isinstance(mapping.get("events"), list) else []
    documents = mapping.get("documents") if isinstance(mapping.get("documents"), list) else []
    route_bindings = mapping.get("routes") if isinstance(mapping.get("routes"), list) else []

    def stable_segment(value: Any) -> str:
        raw = str(value or "unknown").strip()
        compact = re.sub(r"[^A-Za-z0-9._-]+", "-", raw)
        return compact.strip("-") or "unknown"

    episode_event_ids = {
        str(item)
        for item in (episode.get("event_ids") if isinstance(episode.get("event_ids"), list) else [])
        if item
    }
    if source_event.get("event_id"):
        episode_event_ids.add(str(source_event.get("event_id")))
    affected_services = {
        str(item)
        for item in (nested_get(body_trace, ["spatial", "affected_services"]) if isinstance(nested_get(body_trace, ["spatial", "affected_services"]), list) else [])
        if item
    }
    affected_services.update(
        str(node).split(":", 1)[1]
        for node in (nested_get(body_trace, ["spatial", "affected_spatial_nodes"]) if isinstance(nested_get(body_trace, ["spatial", "affected_spatial_nodes"]), list) else [])
        if str(node).startswith("service:")
    )
    for candidate_service in (
        nested_get(source_event, ["resource", "service"]),
        nested_get(episode, ["working_stack_gap", "service"]),
        episode.get("service"),
    ):
        if candidate_service:
            affected_services.add(str(candidate_service))

    selected_entity_ids: set[str] = set()
    requirement_id = str(episode.get("requirement_id") or "")
    if requirement_id:
        selected_entity_ids.add(f"stack.requirement.{stable_segment(requirement_id)}")
    for service in affected_services:
        selected_entity_ids.add(f"stack.service.{stable_segment(service)}")
        selected_entity_ids.add(f"stack.organ.{stable_segment(service)}")

    top_route_id = (
        nested_get(route_packets, ["summary", "top_route_id"])
        or nested_get(route_packets, ["top_packet", "route_id"])
        or nested_get(mapping, ["top_entity", "route_id"])
    )
    selected_route_ids = {str(top_route_id)} if top_route_id else set()
    selected_route_ids.update({"body.stack_organs", "body.machine_bridges"})

    selected_entities = [
        entity for entity in entities
        if isinstance(entity, dict)
        and (
            str(entity.get("entity_id") or "") in selected_entity_ids
            or str(entity.get("event_id") or "") in episode_event_ids
            or str(entity.get("route_id") or "") in selected_route_ids
            or str(nested_get(entity, ["subject", "service"]) or "") in affected_services
        )
    ]
    if not selected_entities and entities:
        selected_entities = [entity for entity in entities if isinstance(entity, dict)][:1]
    selected_event_ids = {str(entity.get("event_id")) for entity in selected_entities if entity.get("event_id")}
    selected_events = [
        event for event in events
        if isinstance(event, dict)
        and (
            str(event.get("event_id") or "") in selected_event_ids
            or str(event.get("event_id") or "") in episode_event_ids
            or str(event.get("route_id") or "") in selected_route_ids
        )
    ]
    selected_document_ids = sorted({
        str(document_id)
        for row in [*selected_entities, *selected_events]
        for document_id in (row.get("document_ids") if isinstance(row.get("document_ids"), list) else [])
        if document_id
    })
    selected_documents = [
        document for document in documents
        if isinstance(document, dict) and str(document.get("document_id") or "") in set(selected_document_ids)
    ]
    selected_route_bindings = [
        row for row in route_bindings
        if isinstance(row, dict)
        and (
            str(row.get("route_id") or "") in selected_route_ids
            or bool(set(str(item) for item in (row.get("entity_ids") if isinstance(row.get("entity_ids"), list) else [])) & {str(entity.get("entity_id")) for entity in selected_entities if entity.get("entity_id")})
        )
    ]
    if not selected_route_bindings:
        selected_route_bindings = [
            row for row in route_bindings
            if isinstance(row, dict)
            and str(row.get("route_id") or "") in {"body.stack_organs", "body.machine_bridges"}
        ][:2]

    policy = {
        "read_only": True,
        "latest_only_readmodel": True,
        "host_layer_mutates_stack": False,
        "writes_project_roots": False,
        "executes_commands": False,
        "actions_executed": False,
        "automatic_remediation": False,
    }
    complete = bool(
        not map_issues
        and selected_entities
        and selected_events
        and selected_documents
        and selected_route_bindings
        and nested_get(mapping, ["summary", "automation_ready"]) is True
        and nested_get(mapping, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(mapping, ["policy", "executes_commands"]) is False
    )
    data = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_response_entity_event_document_context_v1",
        "complete": complete,
        "issues": map_issues,
        "episode_id": episode.get("episode_id"),
        "episode_kind": episode.get("episode_kind") or nested_get(body_trace, ["episode_kind"]),
        "top_route_id": top_route_id,
        "summary": {
            "map_entities": nested_get(mapping, ["summary", "entities"]),
            "map_events": nested_get(mapping, ["summary", "events"]),
            "map_documents": nested_get(mapping, ["summary", "documents"]),
            "map_body_surfaces": nested_get(mapping, ["summary", "body_surfaces"]),
            "selected_entities": len(selected_entities),
            "selected_events": len(selected_events),
            "selected_documents": len(selected_documents),
            "selected_route_bindings": len(selected_route_bindings),
            "automation_ready": nested_get(mapping, ["summary", "automation_ready"]),
        },
        "entity_ids": [str(entity.get("entity_id")) for entity in selected_entities if entity.get("entity_id")],
        "event_ids": [str(event.get("event_id")) for event in selected_events if event.get("event_id")],
        "document_ids": selected_document_ids,
        "route_ids": [str(row.get("route_id")) for row in selected_route_bindings if row.get("route_id")],
        "top_entity": mapping.get("top_entity") if isinstance(mapping.get("top_entity"), dict) else {},
        "top_event": mapping.get("top_event") if isinstance(mapping.get("top_event"), dict) else {},
        "selected_entities": selected_entities[:12],
        "selected_events": selected_events[:12],
        "selected_documents": selected_documents[:16],
        "selected_route_bindings": selected_route_bindings[:12],
        "automation": {
            "mode": "latest_only_readmodel",
            "runs_probe": False,
            "runs_cycle": False,
            "runs_indexing": False,
            "runs_stack_http_probes": False,
            "executes_verifiers": False,
            "validation_source": "entity_event_document_map",
        },
        "policy": policy,
        "evidence_refs": [
            {"path": str(SELF_AWARENESS_COMPLETION_AUDIT_LATEST_PATH), "section": "entity_event_document_map"},
            {"path": str(SELF_AWARENESS_COMPLETION_AUDIT_LATEST_PATH), "section": "completion_route_packets"},
            {"path": str(SELF_AWARENESS_EVENTS_LATEST_PATH), "event_ids": sorted(episode_event_ids)},
        ],
    }
    return data


def self_awareness_response_entity_event_document_context_complete(context: Any) -> bool:
    if not isinstance(context, dict):
        return False
    return (
        context.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_response_entity_event_document_context_v1"
        and context.get("complete") is True
        and not context.get("issues")
        and safe_int(nested_get(context, ["summary", "selected_entities"]), 0) > 0
        and safe_int(nested_get(context, ["summary", "selected_events"]), 0) > 0
        and safe_int(nested_get(context, ["summary", "selected_documents"]), 0) > 0
        and safe_int(nested_get(context, ["summary", "selected_route_bindings"]), 0) > 0
        and nested_get(context, ["summary", "automation_ready"]) is True
        and bool(context.get("entity_ids"))
        and bool(context.get("event_ids"))
        and bool(context.get("document_ids"))
        and bool(context.get("route_ids"))
        and nested_get(context, ["automation", "runs_probe"]) is False
        and nested_get(context, ["automation", "runs_cycle"]) is False
        and nested_get(context, ["automation", "runs_indexing"]) is False
        and nested_get(context, ["automation", "runs_stack_http_probes"]) is False
        and nested_get(context, ["automation", "executes_verifiers"]) is False
        and nested_get(context, ["policy", "host_layer_mutates_stack"]) is False
        and nested_get(context, ["policy", "writes_project_roots"]) is False
        and nested_get(context, ["policy", "executes_commands"]) is False
        and bool(context.get("evidence_refs"))
    )


def self_awareness_completion_route_packet_issues(
    packet_index: Any,
    *,
    expected_routes: int | None = None,
    expected_actions: int | None = None,
) -> list[str]:
    issues: list[str] = []
    if not isinstance(packet_index, dict):
        return ["packet_index_missing"]
    summary = packet_index.get("summary") if isinstance(packet_index.get("summary"), dict) else {}
    automation = packet_index.get("automation") if isinstance(packet_index.get("automation"), dict) else {}
    validation_contract = automation.get("validation_contract") if isinstance(automation.get("validation_contract"), dict) else {}
    policy = packet_index.get("policy") if isinstance(packet_index.get("policy"), dict) else {}
    packets = packet_index.get("packets") if isinstance(packet_index.get("packets"), list) else []

    if packet_index.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_completion_route_packet_index_v1":
        issues.append("schema")
    if packet_index.get("ok") is not True or summary.get("automation_ready") is not True:
        issues.append("automation_not_ready")
    if policy.get("host_layer_mutates_stack") is not False or policy.get("executes_commands") is not False:
        issues.append("policy")
    if automation.get("runs_probe") is not False or automation.get("runs_cycle") is not False or automation.get("runs_indexing") is not False:
        issues.append("automation_runs_heavy_work")
    if automation.get("runs_stack_http_probes") is not False or automation.get("executes_verifiers") is not False:
        issues.append("automation_executes_verifiers_or_stack_probes")
    for key in (
        "every_completion_route_has_packet",
        "every_completion_action_has_route_packet",
        "every_packet_has_entities_events_documents",
    ):
        if validation_contract.get(key) is not True:
            issues.append(f"validation_contract:{key}")
    if validation_contract.get("host_layer_mutates_stack") is not False:
        issues.append("validation_contract:host_layer_mutates_stack")
    if safe_int(summary.get("packets"), -1) != len(packets):
        issues.append("packet_count")
    if safe_int(summary.get("packets_complete"), -1) != sum(1 for packet in packets if isinstance(packet, dict) and packet.get("complete") is True):
        issues.append("packet_complete_count")
    if expected_routes is not None and safe_int(summary.get("routes"), -1) != expected_routes:
        issues.append("expected_route_count")
    if expected_actions is not None and safe_int(summary.get("actions"), -1) != expected_actions:
        issues.append("expected_action_count")
    if summary.get("unmapped_actions"):
        issues.append("unmapped_actions")
    if summary.get("unmapped_routes"):
        issues.append("unmapped_routes")

    packet_by_route = packet_index.get("packet_by_route") if isinstance(packet_index.get("packet_by_route"), dict) else {}
    packet_route_ids = {str(packet.get("route_id")) for packet in packets if isinstance(packet, dict) and packet.get("route_id")}
    if set(str(route_id) for route_id in packet_by_route) != packet_route_ids:
        issues.append("packet_by_route")
    for packet in packets:
        if not isinstance(packet, dict):
            issues.append("malformed_packet")
            continue
        packet_id = str(packet.get("packet_id") or packet.get("route_id") or "unknown")
        action_ids = packet.get("action_ids") if isinstance(packet.get("action_ids"), list) else []
        actions = packet.get("actions") if isinstance(packet.get("actions"), list) else []
        entity_ids = packet.get("entity_ids") if isinstance(packet.get("entity_ids"), list) else []
        event_ids = packet.get("event_ids") if isinstance(packet.get("event_ids"), list) else []
        document_ids = packet.get("document_ids") if isinstance(packet.get("document_ids"), list) else []
        document_refs = packet.get("document_refs") if isinstance(packet.get("document_refs"), list) else []
        verifier_commands = packet.get("verifier_commands") if isinstance(packet.get("verifier_commands"), list) else []
        if packet.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_completion_route_packet_v1":
            issues.append(f"{packet_id}:schema")
        if packet.get("complete") is not True:
            issues.append(f"{packet_id}:incomplete")
        if not packet.get("route_id") or not packet.get("route_path") or not action_ids:
            issues.append(f"{packet_id}:identity")
        if len(actions) != len(action_ids):
            issues.append(f"{packet_id}:action_count")
        if len(entity_ids) != len(action_ids) or len(event_ids) != len(action_ids):
            issues.append(f"{packet_id}:entity_event_count")
        if not document_ids or not document_refs:
            issues.append(f"{packet_id}:documents")
        if not verifier_commands:
            issues.append(f"{packet_id}:verifier_commands")
        if not packet.get("evidence_refs"):
            issues.append(f"{packet_id}:evidence_refs")
        if nested_get(packet, ["automation", "runs_probe"]) is not False or nested_get(packet, ["automation", "runs_cycle"]) is not False or nested_get(packet, ["automation", "runs_indexing"]) is not False:
            issues.append(f"{packet_id}:automation_runs_heavy_work")
        if nested_get(packet, ["automation", "runs_stack_http_probes"]) is not False or nested_get(packet, ["automation", "executes_verifiers"]) is not False:
            issues.append(f"{packet_id}:automation_executes_verifiers_or_stack_probes")
        if nested_get(packet, ["policy", "host_layer_mutates_stack"]) is not False or nested_get(packet, ["policy", "executes_commands"]) is not False:
            issues.append(f"{packet_id}:policy")
        for action in actions:
            if not isinstance(action, dict):
                issues.append(f"{packet_id}:malformed_action")
                continue
            action_id = str(action.get("id") or "unknown")
            if nested_get(action, ["policy", "host_layer_mutates_stack"]) is not False or nested_get(action, ["policy", "executes_commands"]) is not False:
                issues.append(f"{packet_id}:{action_id}:action_policy")
    return sorted(set(issues))


def self_awareness_completion_route_packet_index_complete(
    packet_index: Any,
    *,
    expected_routes: int | None = None,
    expected_actions: int | None = None,
) -> bool:
    return not self_awareness_completion_route_packet_issues(
        packet_index,
        expected_routes=expected_routes,
        expected_actions=expected_actions,
    )


def self_awareness_stack_requirement_ids_for_doc(requirements_doc: dict[str, Any]) -> set[str]:
    handoff_rows = requirements_doc.get("stack_handoff") if isinstance(requirements_doc.get("stack_handoff"), list) else []
    ids = {
        str(item.get("id") or item.get("requirement_id"))
        for item in handoff_rows
        if isinstance(item, dict) and (item.get("id") or item.get("requirement_id"))
    }
    if ids:
        return ids
    requirement_rows = requirements_doc.get("requirements") if isinstance(requirements_doc.get("requirements"), list) else []
    return {
        str(item.get("id"))
        for item in requirement_rows
        if isinstance(item, dict) and item.get("owner") == "abyss-stack" and item.get("id")
    }


def self_awareness_requirement_probe_ids_for_doc(requirement_probes_doc: dict[str, Any]) -> set[str]:
    probe_rows = requirement_probes_doc.get("probes") if isinstance(requirement_probes_doc.get("probes"), list) else []
    return {
        str(item.get("requirement_id") or item.get("id"))
        for item in probe_rows
        if isinstance(item, dict) and (item.get("requirement_id") or item.get("id"))
    }


def self_awareness_requirement_probes_cover_requirements(
    requirements_doc: dict[str, Any],
    requirement_probes_doc: dict[str, Any],
) -> bool:
    requirement_ids = self_awareness_stack_requirement_ids_for_doc(requirements_doc)
    probe_ids = self_awareness_requirement_probe_ids_for_doc(requirement_probes_doc)
    if not requirement_ids:
        return not probe_ids
    return requirement_ids == probe_ids


def self_awareness_requirement_probes_export_ready(
    requirements_doc: dict[str, Any],
    requirement_probes_doc: dict[str, Any],
) -> bool:
    if requirement_probes_doc.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_requirement_probes_v1":
        return False
    if not self_awareness_requirement_probes_cover_requirements(requirements_doc, requirement_probes_doc):
        return False
    requirement_ids = self_awareness_stack_requirement_ids_for_doc(requirements_doc)
    probe_rows = requirement_probes_doc.get("probes") if isinstance(requirement_probes_doc.get("probes"), list) else []
    probe_by_id = {
        str(probe.get("requirement_id") or probe.get("id")): probe
        for probe in probe_rows
        if isinstance(probe, dict) and (probe.get("requirement_id") or probe.get("id"))
    }
    for requirement_id in requirement_ids:
        probe = probe_by_id.get(requirement_id)
        if not isinstance(probe, dict):
            return False
        contract = probe.get("acceptance_contract") if isinstance(probe.get("acceptance_contract"), dict) else {}
        closure_readiness = probe.get("closure_readiness") if isinstance(probe.get("closure_readiness"), dict) else {}
        acceptance_verifiers = probe.get("acceptance_verifiers") if isinstance(probe.get("acceptance_verifiers"), list) else []
        runbook_candidate = probe.get("runbook_candidate") if isinstance(probe.get("runbook_candidate"), dict) else {}
        policy = probe.get("policy") if isinstance(probe.get("policy"), dict) else {}
        if contract.get("schema") != f"{SCHEMA_PREFIX}_stack_requirement_acceptance_contract_v1":
            return False
        if (
            policy.get("read_only") is not True
            or policy.get("host_layer_mutates_stack") is not False
            or policy.get("executes_commands") is not False
            or policy.get("raw_secrets_included") is not False
        ):
            return False
        if not acceptance_verifiers:
            return False
        if closure_readiness.get("schema") != f"{SCHEMA_PREFIX}_stack_handoff_closure_readiness_v1":
            return False
        if not closure_readiness.get("verifier_commands"):
            return False
        if not self_awareness_stack_requirement_runbook_complete(runbook_candidate, requirement_id):
            return False
    return True


def self_awareness_export_stack_handoff(
    requirements_doc: dict[str, Any],
    requirement_probes_doc: dict[str, Any],
    exported: dict[str, Any],
    generated_at: str,
    stack_closure_dossier: dict[str, Any] | None = None,
    coverage_audit_doc: dict[str, Any] | None = None,
    activation_smoke_doc: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    stack_closure_dossier = stack_closure_dossier if isinstance(stack_closure_dossier, dict) else {}
    stack_owner_handoff = stack_closure_dossier.get("stack_owner_handoff") if isinstance(stack_closure_dossier.get("stack_owner_handoff"), dict) else {}
    dependency_graph = stack_closure_dossier.get("dependency_graph") if isinstance(stack_closure_dossier.get("dependency_graph"), dict) else {}
    dossier_summary = stack_closure_dossier.get("summary") if isinstance(stack_closure_dossier.get("summary"), dict) else {}
    working_stack_activation_dossier = stack_closure_dossier.get("working_stack_activation_dossier") if isinstance(stack_closure_dossier.get("working_stack_activation_dossier"), dict) else {}
    working_stack_activation_handoff = working_stack_activation_dossier.get("working_stack_activation_handoff") if isinstance(working_stack_activation_dossier.get("working_stack_activation_handoff"), dict) else stack_closure_dossier.get("working_stack_activation_handoff") if isinstance(stack_closure_dossier.get("working_stack_activation_handoff"), dict) else {}
    working_stack_activation_summary = working_stack_activation_dossier.get("summary") if isinstance(working_stack_activation_dossier.get("summary"), dict) else {}
    working_stack_activation_entries = working_stack_activation_dossier.get("entries") if isinstance(working_stack_activation_dossier.get("entries"), list) else []
    working_stack_activation_order = working_stack_activation_handoff.get("activation_order") if isinstance(working_stack_activation_handoff.get("activation_order"), list) else []
    working_stack_activation_service_ids = [
        str(item.get("service"))
        for item in working_stack_activation_entries
        if isinstance(item, dict) and item.get("service")
    ]
    working_stack_activation_entry_by_service = {
        str(item.get("service")): item
        for item in working_stack_activation_entries
        if isinstance(item, dict) and item.get("service")
    }
    dossier_entries = stack_closure_dossier.get("entries") if isinstance(stack_closure_dossier.get("entries"), list) else []
    dossier_entry_by_requirement = {
        str(item.get("requirement_id")): item
        for item in dossier_entries
        if isinstance(item, dict) and item.get("requirement_id")
    }
    dossier_closure_acceptance_matrix = stack_closure_dossier.get("closure_acceptance_matrix") if isinstance(stack_closure_dossier.get("closure_acceptance_matrix"), dict) else {}
    raw_closure_order = stack_owner_handoff.get("closure_order") if isinstance(stack_owner_handoff.get("closure_order"), list) else []
    closure_order = [
        {
            "requirement_id": item.get("requirement_id"),
            "order": item.get("order"),
            "blocking_check_keys": item.get("blocking_check_keys") if isinstance(item.get("blocking_check_keys"), list) else [],
            "depends_on_requirement_ids": item.get("depends_on_requirement_ids") if isinstance(item.get("depends_on_requirement_ids"), list) else [],
            "unblocks_requirement_ids": item.get("unblocks_requirement_ids") if isinstance(item.get("unblocks_requirement_ids"), list) else [],
            "runbook_candidate_id": item.get("runbook_candidate_id"),
            "closure_acceptance_id": item.get("closure_acceptance_id"),
            "compat_requirement_id": item.get("compat_requirement_id"),
            "safe_next_action": item.get("safe_next_action") if isinstance(item.get("safe_next_action"), dict) else {},
            "verifier_commands": item.get("verifier_commands") if isinstance(item.get("verifier_commands"), list) else [],
        }
        for item in raw_closure_order
        if isinstance(item, dict) and item.get("requirement_id")
    ]
    closure_order_ids = [str(item.get("requirement_id")) for item in closure_order if item.get("requirement_id")]
    dependency_graph_export = {
        "schema": dependency_graph.get("schema") or f"{SCHEMA_PREFIX}_self_awareness_export_stack_handoff_dependency_graph_v1",
        "ordered_requirement_ids": dependency_graph.get("ordered_requirement_ids") if isinstance(dependency_graph.get("ordered_requirement_ids"), list) else closure_order_ids,
        "open_requirement_ids": dependency_graph.get("open_requirement_ids") if isinstance(dependency_graph.get("open_requirement_ids"), list) else [],
        "closed_requirement_ids": dependency_graph.get("closed_requirement_ids") if isinstance(dependency_graph.get("closed_requirement_ids"), list) else [],
        "edges": dependency_graph.get("edges") if isinstance(dependency_graph.get("edges"), list) else [],
        "reverse_edges": dependency_graph.get("reverse_edges") if isinstance(dependency_graph.get("reverse_edges"), list) else [],
        "dependency_root_requirement_ids": dependency_graph.get("dependency_root_requirement_ids") if isinstance(dependency_graph.get("dependency_root_requirement_ids"), list) else [],
        "dependent_requirement_ids": dependency_graph.get("dependent_requirement_ids") if isinstance(dependency_graph.get("dependent_requirement_ids"), list) else [],
        "unblocking_requirement_ids": dependency_graph.get("unblocking_requirement_ids") if isinstance(dependency_graph.get("unblocking_requirement_ids"), list) else [],
        "policy": {
            "dependency_order_is_handoff_guidance": nested_get(dependency_graph, ["policy", "dependency_order_is_handoff_guidance"]) is not False,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
        },
    }
    requirement_rows = requirements_doc.get("requirements") if isinstance(requirements_doc.get("requirements"), list) else []
    stack_requirements = [
        item for item in requirement_rows
        if isinstance(item, dict) and item.get("owner") == "abyss-stack"
    ]
    requirement_by_id = {
        str(item.get("id")): item
        for item in stack_requirements
        if item.get("id")
    }
    handoff_rows = requirements_doc.get("stack_handoff") if isinstance(requirements_doc.get("stack_handoff"), list) else []
    handoff_by_id = {
        str(item.get("id") or item.get("requirement_id")): item
        for item in handoff_rows
        if isinstance(item, dict) and (item.get("id") or item.get("requirement_id"))
    }
    probe_rows = requirement_probes_doc.get("probes") if isinstance(requirement_probes_doc.get("probes"), list) else []
    probes = [
        probe for probe in probe_rows
        if isinstance(probe, dict) and (probe.get("id") or probe.get("requirement_id"))
    ]
    artifact_refs = self_awareness_export_artifact_refs(
        exported,
        ["requirements", "requirement_probes", "stack_closure_dossier", "working_stack", "capabilities", "failure_matrix", "coverage_audit", "activation_smoke", "cycle", "validate"],
    )
    coverage_audit_doc = coverage_audit_doc if isinstance(coverage_audit_doc, dict) else load_latest_json(SELF_AWARENESS_COVERAGE_AUDIT_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_objective_coverage_audit_v1")
    coverage_gap_rows = coverage_audit_doc.get("working_stack_gap_rows") if isinstance(coverage_audit_doc.get("working_stack_gap_rows"), list) else []
    working_stack_activation_synthetic_proofs = [
        self_awareness_export_overlay_working_stack_activation_proof(
            row.get("synthetic_proof"),
            working_stack_activation_entry_by_service,
            generated_at=generated_at,
        )
        for row in coverage_gap_rows
        if isinstance(row, dict) and isinstance(row.get("synthetic_proof"), dict)
    ]
    working_stack_activation_synthetic_proofs_complete = [
        proof for proof in working_stack_activation_synthetic_proofs
        if self_awareness_working_stack_activation_synthetic_proof_complete(proof)
    ]
    working_stack_activation_synthetic_proof_summary = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_export_working_stack_activation_synthetic_proof_summary_v1",
        "coverage_audit_generated_at": coverage_audit_doc.get("generated_at"),
        "coverage_audit_ref": artifact_refs.get("coverage_audit"),
        "proofs": len(working_stack_activation_synthetic_proofs),
        "proofs_complete": len(working_stack_activation_synthetic_proofs_complete),
        "services": [
            str(proof.get("service"))
            for proof in working_stack_activation_synthetic_proofs
            if isinstance(proof, dict) and proof.get("service")
        ],
        "failed_services": [
            str(proof.get("service"))
            for proof in working_stack_activation_synthetic_proofs
            if isinstance(proof, dict) and not self_awareness_working_stack_activation_synthetic_proof_complete(proof)
        ],
        "policy": {
            "handoff_only": True,
            "read_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "actions_executed": False,
            "raw_private_content_included": False,
        },
    }
    working_stack_activation_synthetic_proofs_by_service = {
        str(proof.get("service")): proof
        for proof in working_stack_activation_synthetic_proofs
        if isinstance(proof, dict) and proof.get("service")
    }
    activation_smoke_doc = activation_smoke_doc if isinstance(activation_smoke_doc, dict) else load_latest_json(SELF_AWARENESS_ACTIVATION_SMOKE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_working_stack_activation_smoke_v1")
    activation_smoke_rows = activation_smoke_doc.get("rows") if isinstance(activation_smoke_doc.get("rows"), list) else []
    activation_smoke_by_service = activation_smoke_doc.get("by_service") if isinstance(activation_smoke_doc.get("by_service"), dict) else {}
    activation_smoke_compact_by_service = activation_smoke_doc.get("compact_by_service") if isinstance(activation_smoke_doc.get("compact_by_service"), dict) else {
        str(row.get("service")): self_awareness_working_stack_activation_smoke_compact(row)
        for row in activation_smoke_rows
        if isinstance(row, dict) and row.get("service")
    }
    stack_organ_use_packets = activation_smoke_doc.get("stack_organ_use_packets") if isinstance(activation_smoke_doc.get("stack_organ_use_packets"), list) else [
        row.get("stack_organ_use_packet")
        for row in activation_smoke_rows
        if isinstance(row, dict) and isinstance(row.get("stack_organ_use_packet"), dict)
    ]
    stack_organ_use_packets = [packet for packet in stack_organ_use_packets if isinstance(packet, dict)]
    stack_organ_use_packet_by_service = activation_smoke_doc.get("stack_organ_use_packet_by_service") if isinstance(activation_smoke_doc.get("stack_organ_use_packet_by_service"), dict) else {
        str(packet.get("service")): packet
        for packet in stack_organ_use_packets
        if packet.get("service")
    }
    stack_organ_use_packet_summary = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_export_stack_organ_use_packet_summary_v1",
        "activation_smoke_generated_at": activation_smoke_doc.get("generated_at"),
        "activation_smoke_ref": artifact_refs.get("activation_smoke"),
        "packets": len(stack_organ_use_packets),
        "packets_complete": sum(1 for packet in stack_organ_use_packets if self_awareness_stack_organ_use_packet_complete(packet)),
        "services": [
            str(packet.get("service"))
            for packet in stack_organ_use_packets
            if packet.get("service")
        ],
        "classifications": sorted({
            str(nested_get(packet, ["activation_gap", "classification"]))
            for packet in stack_organ_use_packets
            if nested_get(packet, ["activation_gap", "classification"])
        }),
        "failed_services": [
            str(packet.get("service"))
            for packet in stack_organ_use_packets
            if packet.get("service") and not self_awareness_stack_organ_use_packet_complete(packet)
        ],
        "policy": {
            "handoff_only": True,
            "read_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "actions_executed": False,
            "raw_private_content_included": False,
        },
    }
    working_stack_activation_smoke_summary = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_export_working_stack_activation_smoke_summary_v1",
        "activation_smoke_generated_at": activation_smoke_doc.get("generated_at"),
        "activation_smoke_ref": artifact_refs.get("activation_smoke"),
        "rows": len(activation_smoke_rows),
        "rows_complete": sum(1 for row in activation_smoke_rows if self_awareness_working_stack_activation_smoke_row_complete(row)),
        "services": [
            str(row.get("service"))
            for row in activation_smoke_rows
            if isinstance(row, dict) and row.get("service")
        ],
        "failed_services": [
            str(row.get("service"))
            for row in activation_smoke_rows
            if isinstance(row, dict) and not self_awareness_working_stack_activation_smoke_row_complete(row)
        ],
        "policy": {
            "handoff_only": True,
            "read_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "actions_executed": False,
            "raw_private_content_included": False,
        },
    }

    def first_export_dict(*values: Any) -> dict[str, Any]:
        for value in values:
            if isinstance(value, dict) and value:
                return value
        return {}

    def compact_runbook(runbook: dict[str, Any]) -> dict[str, Any]:
        return {
            "schema": runbook.get("schema"),
            "id": runbook.get("id"),
            "requirement_id": runbook.get("requirement_id"),
            "status": runbook.get("status"),
            "machine_action": runbook.get("machine_action"),
            "source_command": runbook.get("source_command"),
            "host_layer_mutates_stack": runbook.get("host_layer_mutates_stack"),
            "machine_executes_stack_change": runbook.get("machine_executes_stack_change"),
            "stack_owner_may_mutate_stack": runbook.get("stack_owner_may_mutate_stack"),
            "operator_approval_required": runbook.get("operator_approval_required"),
            "proposed_stack_work": runbook.get("proposed_stack_work"),
            "acceptance_steps": runbook.get("acceptance_steps"),
            "acceptance_verifiers": runbook.get("acceptance_verifiers"),
            "risk": runbook.get("risk"),
            "blast_radius": runbook.get("blast_radius"),
            "rollback": runbook.get("rollback"),
            "evidence_refs": runbook.get("evidence_refs"),
            "policy": runbook.get("policy"),
        }

    entries: list[dict[str, Any]] = []
    for probe in probes:
        requirement_id = str(probe.get("id") or probe.get("requirement_id") or "")
        requirement = requirement_by_id.get(requirement_id, {})
        handoff = handoff_by_id.get(requirement_id, {})
        dossier_entry = dossier_entry_by_requirement.get(requirement_id, {})
        checks = probe.get("checks") if isinstance(probe.get("checks"), list) else []
        closure_blockers = [
            {
                "key": check.get("key"),
                "level": check.get("level"),
                "ok": check.get("ok"),
                "message": check.get("message"),
                "data": check.get("data"),
            }
            for check in checks
            if isinstance(check, dict)
            and (check.get("ok") is not True or str(check.get("level") or "").lower() in {"open", "warn", "fail"})
        ]
        ok_checks = sum(1 for check in checks if isinstance(check, dict) and check.get("ok") is True and check.get("level") == "ok")
        runbook = probe.get("runbook_candidate") if isinstance(probe.get("runbook_candidate"), dict) else {}
        acceptance_contract = first_export_dict(
            probe.get("acceptance_contract"),
            requirement.get("acceptance_contract"),
            handoff.get("acceptance_contract"),
        )
        machine_probe = first_export_dict(
            probe.get("machine_closure_probe"),
            acceptance_contract.get("probe_plan"),
            requirement.get("machine_closure_probe"),
            handoff.get("machine_closure_probe"),
        )
        acceptance_verifiers = (
            probe.get("acceptance_verifiers")
            if isinstance(probe.get("acceptance_verifiers"), list) and probe.get("acceptance_verifiers")
            else requirement.get("acceptance_verifiers")
            if isinstance(requirement.get("acceptance_verifiers"), list) and requirement.get("acceptance_verifiers")
            else handoff.get("acceptance_verifiers")
            if isinstance(handoff.get("acceptance_verifiers"), list) and handoff.get("acceptance_verifiers")
            else acceptance_contract.get("machine_verifiers")
            if isinstance(acceptance_contract.get("machine_verifiers"), list)
            else []
        )
        closure_readiness = probe.get("closure_readiness") if isinstance(probe.get("closure_readiness"), dict) else {}
        coverage_impact = first_export_dict(
            requirement.get("coverage_impact"),
            handoff.get("coverage_impact"),
            dossier_entry.get("coverage_impact") if isinstance(dossier_entry, dict) else {},
            closure_readiness.get("coverage_impact"),
        )
        if not self_awareness_stack_coverage_impact_complete(coverage_impact):
            coverage_impact = self_awareness_stack_requirement_coverage_impact(requirement_id)
        safe_next_action = first_export_dict(requirement.get("safe_next_action"), handoff.get("safe_next_action"), closure_readiness.get("safe_next_action"))
        current_state_digest = first_export_dict(requirement.get("current_state_digest"), handoff.get("current_state_digest"))
        if (
            current_state_digest.get("schema") != f"{SCHEMA_PREFIX}_self_awareness_requirement_current_state_digest_v1"
            or nested_get(current_state_digest, ["policy", "raw_payloads_included"]) is not False
            or nested_get(current_state_digest, ["policy", "raw_secrets_included"]) is not False
        ):
            current_state = probe.get("current_state") if isinstance(probe.get("current_state"), dict) else {}
            evidence_refs = probe.get("evidence_refs") if isinstance(probe.get("evidence_refs"), list) else []
            current_state_digest = {
                "schema": f"{SCHEMA_PREFIX}_self_awareness_requirement_current_state_digest_v1",
                "has_current_state": bool(current_state),
                "keys": sorted(str(key) for key in current_state.keys())[:80],
                "evidence_refs": len(evidence_refs),
                "policy": {
                    "raw_payloads_included": False,
                    "raw_secrets_included": False,
                    "host_layer_mutates_stack": False,
                },
            }
        closure_acceptance = first_export_dict(
            dossier_entry.get("closure_acceptance") if isinstance(dossier_entry, dict) else {},
            requirement.get("closure_acceptance"),
            handoff.get("closure_acceptance"),
        )
        handoff_contract_complete = bool(
            requirement.get("handoff_contract_complete") is True
            or handoff.get("handoff_contract_complete") is True
            or (
                isinstance(acceptance_contract, dict)
                and bool(acceptance_contract)
                and bool(machine_probe)
                and bool(acceptance_verifiers)
                and self_awareness_stack_coverage_impact_complete(coverage_impact)
                and current_state_digest.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_requirement_current_state_digest_v1"
                and nested_get(current_state_digest, ["policy", "raw_payloads_included"]) is False
                and nested_get(current_state_digest, ["policy", "raw_secrets_included"]) is False
            )
        )
        entry = {
            "id": requirement_id,
            "title": requirement.get("title") or requirement_id,
            "owner": probe.get("owner") or requirement.get("owner") or "abyss-stack",
            "status": probe.get("status"),
            "closed_by_current_probe": probe.get("closed_by_current_probe"),
            "probe_kind": probe.get("probe_kind"),
            "source_handoff_command": probe.get("source_handoff_command"),
            "machine_read_command": probe.get("machine_read_command"),
            "current_state": probe.get("current_state"),
            "closure_blockers": closure_blockers,
            "open_check_count": len(closure_blockers),
            "ok_check_count": ok_checks,
            "closure_readiness": closure_readiness,
            "expected_shape": requirement.get("expected_shape") or handoff.get("expected_shape"),
            "machine_closure_probe": {
                "kind": machine_probe.get("kind"),
                "candidate_routes": machine_probe.get("candidate_routes"),
                "required_fields": machine_probe.get("required_fields"),
                "success_predicates": machine_probe.get("success_predicates"),
                "redaction_rules": machine_probe.get("redaction_rules"),
                "boundedness": machine_probe.get("boundedness"),
            },
            "acceptance_contract": acceptance_contract,
            "acceptance_verifiers": acceptance_verifiers,
            "closure_semantics": probe.get("closure_semantics") if isinstance(probe.get("closure_semantics"), dict) else {},
            "required_fields": probe.get("required_fields") if isinstance(probe.get("required_fields"), list) else [],
            "success_predicates": probe.get("success_predicates") if isinstance(probe.get("success_predicates"), list) else [],
            "redaction_rules": probe.get("redaction_rules") if isinstance(probe.get("redaction_rules"), list) else [],
            "must_not": probe.get("must_not") if isinstance(probe.get("must_not"), list) else [],
            "evidence_refs": probe.get("evidence_refs"),
            "compat_contract": first_export_dict(requirement.get("compat_contract"), handoff.get("compat_contract")),
            "closure_acceptance": closure_acceptance,
            "coverage_impact": coverage_impact,
            "safe_next_action": safe_next_action,
            "current_state_digest": current_state_digest,
            "handoff_contract_complete": handoff_contract_complete,
            "runbook_candidate": compact_runbook(runbook) if runbook else None,
        }
        entries.append(entry)

    open_entries = [entry for entry in entries if entry.get("closed_by_current_probe") is not True]
    closed_entries = [entry for entry in entries if entry.get("closed_by_current_probe") is True]
    stack_requirement_closure_acceptance_packets = [
        entry.get("closure_acceptance")
        for entry in entries
        if isinstance(entry.get("closure_acceptance"), dict)
    ]
    stack_requirement_closure_acceptance_packets_by_requirement = {
        str(packet.get("requirement_id")): packet
        for packet in stack_requirement_closure_acceptance_packets
        if packet.get("requirement_id")
    }
    stack_requirement_closure_acceptance_summary = {
        "schema": f"{SCHEMA_PREFIX}_self_awareness_export_stack_requirement_closure_acceptance_summary_v1",
        "stack_closure_dossier_generated_at": stack_closure_dossier.get("generated_at"),
        "packets": len(stack_requirement_closure_acceptance_packets),
        "packets_complete": sum(1 for packet in stack_requirement_closure_acceptance_packets if self_awareness_stack_requirement_closure_acceptance_complete(packet)),
        "requirements": len(stack_requirement_closure_acceptance_packets_by_requirement),
        "compat_requirements": len({
            str(nested_get(packet, ["stack_compat_requirement", "requirement_id"]))
            for packet in stack_requirement_closure_acceptance_packets
            if nested_get(packet, ["stack_compat_requirement", "requirement_id"])
        }),
        "matrix_ok": dossier_closure_acceptance_matrix.get("ok") is True,
        "policy": {
            "handoff_only": True,
            "read_only": True,
            "host_layer_mutates_stack": False,
            "executes_commands": False,
            "actions_executed": False,
        },
    }
    stack_handoff_coverage_impacts = [
        {
            "schema": impact.get("schema"),
            "requirement_id": entry.get("id"),
            "organ": impact.get("organ"),
            "coverage_planes": impact.get("coverage_planes") if isinstance(impact.get("coverage_planes"), list) else [],
            "affected_stack_surfaces": impact.get("affected_stack_surfaces") if isinstance(impact.get("affected_stack_surfaces"), list) else [],
            "affected_machine_surfaces": impact.get("affected_machine_surfaces") if isinstance(impact.get("affected_machine_surfaces"), list) else [],
            "blocks_stack_usage_requirements": (
                impact.get("blocks_stack_usage_requirements")
                if isinstance(impact.get("blocks_stack_usage_requirements"), list)
                else []
            ),
            "closure_value": impact.get("closure_value"),
            "proof_commands": impact.get("proof_commands") if isinstance(impact.get("proof_commands"), list) else [],
            "policy": impact.get("policy") if isinstance(impact.get("policy"), dict) else {},
        }
        for entry in open_entries
        for impact in [entry.get("coverage_impact") if isinstance(entry.get("coverage_impact"), dict) else {}]
        if impact
    ]
    stack_handoff_coverage_impacts_by_requirement = {
        str(impact.get("requirement_id")): impact
        for impact in stack_handoff_coverage_impacts
        if impact.get("requirement_id")
    }
    stack_handoff_blocked_coverage_planes = sorted({
        str(plane)
        for impact in stack_handoff_coverage_impacts
        for plane in (impact.get("coverage_planes") if isinstance(impact.get("coverage_planes"), list) else [])
        if plane
    })
    stack_owner_verifier_matrix: list[dict[str, Any]] = []
    for entry in open_entries:
        requirement_id = str(entry.get("id") or "")
        closure_readiness = entry.get("closure_readiness") if isinstance(entry.get("closure_readiness"), dict) else {}
        compat_contract = entry.get("compat_contract") if isinstance(entry.get("compat_contract"), dict) else {}
        acceptance_contract = entry.get("acceptance_contract") if isinstance(entry.get("acceptance_contract"), dict) else {}
        coverage_impact = entry.get("coverage_impact") if isinstance(entry.get("coverage_impact"), dict) else {}
        post_close_verifiers = nested_get(compat_contract, ["machine_consumer_contract", "post_close_verifiers"])
        if not isinstance(post_close_verifiers, list):
            post_close_verifiers = acceptance_contract.get("machine_verifiers") if isinstance(acceptance_contract.get("machine_verifiers"), list) else []
        blocking_check_keys = closure_readiness.get("blocking_check_keys") if isinstance(closure_readiness.get("blocking_check_keys"), list) else [
            str(item.get("key"))
            for item in (entry.get("closure_blockers") if isinstance(entry.get("closure_blockers"), list) else [])
            if isinstance(item, dict) and item.get("key")
        ]
        verifier_commands = closure_readiness.get("verifier_commands") if isinstance(closure_readiness.get("verifier_commands"), list) else []
        stack_owner_verifier_matrix.append({
            "schema": f"{SCHEMA_PREFIX}_self_awareness_export_stack_owner_verifier_v1",
            "requirement_id": requirement_id,
            "owner": entry.get("owner") or "abyss-stack",
            "status": entry.get("status"),
            "closure_order": closure_order_ids.index(requirement_id) + 1 if requirement_id in closure_order_ids else None,
            "blocking_check_keys": blocking_check_keys,
            "missing_checks": closure_readiness.get("missing_checks") if isinstance(closure_readiness.get("missing_checks"), list) else entry.get("closure_blockers") if isinstance(entry.get("closure_blockers"), list) else [],
            "closure_evidence_needed": closure_readiness.get("closure_evidence_needed") if isinstance(closure_readiness.get("closure_evidence_needed"), list) else [],
            "verifier_commands": verifier_commands,
            "acceptance_verifiers": entry.get("acceptance_verifiers") if isinstance(entry.get("acceptance_verifiers"), list) else [],
            "post_close_verifiers": post_close_verifiers,
            "runbook_candidate_id": nested_get(entry, ["runbook_candidate", "id"]),
            "safe_next_action": entry.get("safe_next_action") if isinstance(entry.get("safe_next_action"), dict) else {},
            "coverage_planes": coverage_impact.get("coverage_planes") if isinstance(coverage_impact.get("coverage_planes"), list) else [],
            "coverage_impact": coverage_impact,
            "current_state_digest": entry.get("current_state_digest") if isinstance(entry.get("current_state_digest"), dict) else {},
            "evidence_refs": entry.get("evidence_refs") if isinstance(entry.get("evidence_refs"), list) else [],
            "policy": {
                "handoff_only": True,
                "host_layer_mutates_stack": False,
                "executes_commands": False,
                "actions_executed": False,
                "raw_secrets_included": False,
                "stack_owner_may_mutate_stack_after_operator_approval": True,
            },
        })
    stack_owner_verifier_matrix_by_requirement = {
        str(item.get("requirement_id")): item
        for item in stack_owner_verifier_matrix
        if item.get("requirement_id")
    }
    probe_summary = requirement_probes_doc.get("summary") if isinstance(requirement_probes_doc.get("summary"), dict) else {}
    requirements_summary = requirements_doc.get("summary") if isinstance(requirements_doc.get("summary"), dict) else {}
    internal_contract_failures = probe_summary.get("internal_contract_failures")
    if not isinstance(internal_contract_failures, list):
        internal_contract_failures = []
    secret_leaks = safe_int(probe_summary.get("secret_leaks"), 0)
    mutating_routes = safe_int(probe_summary.get("mutating_routes"), 0)
    verifier_steps = sum(
        len(entry.get("acceptance_verifiers") if isinstance(entry.get("acceptance_verifiers"), list) else [])
        for entry in entries
    )
    verifier_entry_count = sum(1 for entry in entries if isinstance(entry.get("acceptance_verifiers"), list) and entry.get("acceptance_verifiers"))
    coverage_impact_count = sum(1 for entry in entries if self_awareness_stack_coverage_impact_complete(entry.get("coverage_impact")))
    safe_next_action_count = sum(1 for entry in entries if isinstance(entry.get("safe_next_action"), dict) and entry.get("safe_next_action"))
