def stack_bridge_static_sync(write: bool = True, write_latest: bool = True) -> dict[str, Any]:
    extension_commands = stack_bridge_extension_commands()
    command_keys = set(extension_commands)
    bridge, bridge_error = load_json_document(MANIFEST_PATH)
    stack, stack_error = load_json_document(STACK_BRIDGE_CONFIG_PATH)
    before_bridge_commands = bridge.get("commands", {}) if isinstance(bridge, dict) and isinstance(bridge.get("commands"), dict) else {}
    before_stack_commands = stack.get("commands", {}) if isinstance(stack, dict) and isinstance(stack.get("commands"), dict) else {}
    before_stack_artifacts = stack.get("artifacts", {}) if isinstance(stack, dict) and isinstance(stack.get("artifacts"), dict) else {}
    before_resource_artifacts = before_stack_artifacts.get("resource", {}) if isinstance(before_stack_artifacts.get("resource"), dict) else {}
    before_nervous_artifacts = before_stack_artifacts.get("nervous", {}) if isinstance(before_stack_artifacts.get("nervous"), dict) else {}
    before_heartbeat_artifacts = before_stack_artifacts.get("heartbeats", {}) if isinstance(before_stack_artifacts.get("heartbeats"), dict) else {}
    before_observability_artifacts = before_stack_artifacts.get("observability", {}) if isinstance(before_stack_artifacts.get("observability"), dict) else {}
    before_self_awareness_artifacts = before_stack_artifacts.get("self_awareness", {}) if isinstance(before_stack_artifacts.get("self_awareness"), dict) else {}
    before = {
        "bridge_missing_commands": sorted(command_keys - set(before_bridge_commands)),
        "stack_missing_commands": sorted(command_keys - set(before_stack_commands)),
        "stack_missing_artifacts": [
            item for item, missing in {
                "artifacts.resource.orchestrator": "orchestrator" not in before_resource_artifacts,
                "artifacts.nervous.quality": "quality" not in before_nervous_artifacts,
                "artifacts.heartbeats.latest": "latest" not in before_heartbeat_artifacts,
                "artifacts.heartbeats.validate": "validate" not in before_heartbeat_artifacts,
            "artifacts.observability.stack_observability": "stack_observability" not in before_observability_artifacts,
                **{
                    f"artifacts.self_awareness.{name}": name not in before_self_awareness_artifacts
                    for name in (
                        "capabilities", "requirements", "requirement_probes", "events", "collect", "query", "correlation", "timeline",
                        "failure_matrix", "stack_closure_dossier", "trace_context", "spatial_graph", "context", "episodes", "alerts", "investigate", "replay", "activation_smoke", "brief", "probe", "cycle", "export", "validate"
                    )
                },
            }.items() if missing
        ],
        "stack_missing_static_compatibility": stack_bridge_static_compatibility_missing(stack) if isinstance(stack, dict) else [],
        "bridge_load_error": bridge_error,
        "stack_load_error": stack_error,
    }
    root_sync_handoff = stack_bridge_static_sync_change_ref()
    data = {
        "schema": f"{SCHEMA_PREFIX}_stack_bridge_static_sync_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": False,
        "write": write,
        "backup_policy": "pre-sync backups are written beside the root-owned static manifests before replacement",
        "paths": {
            "bridge": str(MANIFEST_PATH),
            "stack_bridge": str(STACK_BRIDGE_CONFIG_PATH),
            "latest": str(STACK_BRIDGE_STATIC_SYNC_LATEST_PATH),
        },
        "backup_paths": {},
        "before": before,
        "after": None,
        "pending_change": root_sync_handoff["path"],
        "root_sync_handoff": root_sync_handoff,
        "error": None,
    }
    if bridge_error or stack_error or not isinstance(bridge, dict) or not isinstance(stack, dict):
        data["error"] = "static manifests are missing or invalid JSON"
        return stack_bridge_static_sync_record(data, write_latest)
    if write and os.geteuid() != 0:
        data["error"] = "run as root with sudo after live operator authorization"
        return stack_bridge_static_sync_record(data, write_latest)

    bridge = dict(bridge)
    bridge_commands = bridge.setdefault("commands", {})
    if isinstance(bridge_commands, dict):
        bridge_commands.update(extension_commands)
    bridge["updated_at"] = now_iso()

    stack = dict(stack)
    stack_commands = stack.setdefault("commands", {})
    if isinstance(stack_commands, dict):
        stack_commands.update(extension_commands)
    artifacts = stack.setdefault("artifacts", {})
    if isinstance(artifacts, dict):
        artifacts.setdefault("resource", {})["orchestrator"] = {
            "path": str(RESOURCE_ORCHESTRATOR_LATEST_PATH),
            "schema": f"{SCHEMA_PREFIX}_resource_orchestrator_v2_v1",
            "truth_level": "latest_resource_orchestration_audit",
        }
        artifacts.setdefault("nervous", {})["quality"] = {
            "path": str(NERVOUS_QUALITY_LATEST_PATH),
            "schema": f"{SCHEMA_PREFIX}_nervous_quality_audit_v1",
            "truth_level": "latest_nervous_quality_audit",
        }
        heartbeat_artifacts = artifacts.setdefault("heartbeats", {})
        if isinstance(heartbeat_artifacts, dict):
            heartbeat_artifacts["latest"] = {
                "path": str(HEARTBEATS_LATEST_PATH),
                "schema": f"{SCHEMA_PREFIX}_heartbeat_pulse_v1",
                "truth_level": "latest_heartbeat_readmodel",
            }
            heartbeat_artifacts["validate"] = {
                "path": str(HEARTBEATS_VALIDATE_LATEST_PATH),
                "schema": f"{SCHEMA_PREFIX}_heartbeats_validate_v1",
                "truth_level": "latest_heartbeat_validation",
            }
        observability_artifacts = artifacts.setdefault("observability", {})
        if isinstance(observability_artifacts, dict):
            observability_artifacts["stack_observability"] = {
                "path": str(STACK_OBSERVABILITY_LATEST_PATH),
                "schema": f"{SCHEMA_PREFIX}_stack_observability_v1",
                "truth_level": "latest_stack_observability",
            }
        self_awareness_artifacts = artifacts.setdefault("self_awareness", {})
        if isinstance(self_awareness_artifacts, dict):
            for name, route in stack_bridge_artifact_routes().get("self_awareness", {}).items():
                self_awareness_artifacts[name] = route
    resource_bridge = stack.setdefault("resource_bridge", {})
    if isinstance(resource_bridge, dict):
        resource_bridge["orchestrator_latest"] = str(RESOURCE_ORCHESTRATOR_LATEST_PATH)
        resource_bridge.setdefault("commands", {})
        if isinstance(resource_bridge.get("commands"), dict):
            resource_bridge["commands"].update({
                "orchestrator": "abyss-machine resource orchestrator --json",
                "orchestrator_refresh_nervous": "abyss-machine resource orchestrator --refresh-nervous --json",
            })
    stack["nervous_quality_bridge"] = {
        "agent_entrypoint": str(NERVOUS_AGENTS_PATH),
        "quality_latest": str(NERVOUS_QUALITY_LATEST_PATH),
        "commands": {
            "quality_audit": "abyss-machine nervous quality-audit --json",
            "quality_audit_refresh": "abyss-machine nervous quality-audit --refresh --json",
            "quality_audit_refresh_index": "abyss-machine nervous quality-audit --refresh --refresh-index --json",
        },
        "contract": "Use the quality audit before relying on local memory, synthesis, or stack bridge handoff material.",
        "non_claim": "Quality audit is evidence-only; it does not execute user intent, mutate repositories, or take automatic actions.",
    }
    stack["heartbeat_bridge"] = stack_bridge_heartbeat_bridge_contract()
    stack["stack_observability_bridge"] = stack_bridge_observability_bridge_contract()
    stack["self_awareness_bridge"] = self_awareness_bridge_contract()
    for key, values in {
        "first_commands": [
            "abyss-machine stack-bridge observability --json",
            "abyss-machine self-awareness status --json",
            "abyss-machine self-awareness capabilities --json",
            "abyss-machine self-awareness requirements --json",
            "abyss-machine self-awareness requirement-probes --json",
            "abyss-machine self-awareness stack-closure-dossier --json",
            "abyss-machine self-awareness trace-context --json",
            "abyss-machine self-awareness correlate --json",
            "abyss-machine self-awareness investigate --query latest --json",
            "abyss-machine self-awareness replay --json",
            "abyss-machine self-awareness activation-smoke --json",
            "abyss-machine self-awareness autolink --json",
            "abyss-machine self-awareness failure-matrix --json",
            "abyss-machine self-awareness probe --json",
            "abyss-machine self-awareness cycle --json",
            "abyss-machine self-awareness export --json",
            "abyss-machine self-awareness validate --json",
            "abyss-machine resource orchestrator --json",
            "abyss-machine resource orchestrator --refresh-nervous --json",
            "abyss-machine nervous quality-audit --json",
            "abyss-machine nervous quality-audit --refresh --json",
            "abyss-machine nervous quality-audit --refresh --refresh-index --json",
            "abyss-machine heartbeats pulse --json",
            "abyss-machine heartbeats paths --json",
            "abyss-machine heartbeats validate --json",
        ],
        "validation_commands": [
            "abyss-machine stack-bridge observability --json",
            "abyss-machine self-awareness requirements --json",
            "abyss-machine self-awareness requirement-probes --json",
            "abyss-machine self-awareness stack-closure-dossier --json",
            "abyss-machine self-awareness trace-context --json",
            "abyss-machine self-awareness probe --json",
            "abyss-machine self-awareness replay --json",
            "abyss-machine self-awareness activation-smoke --json",
            "abyss-machine self-awareness autolink --json",
            "abyss-machine self-awareness failure-matrix --json",
            "abyss-machine self-awareness cycle --json",
            "abyss-machine self-awareness export --json",
            "abyss-machine self-awareness validate --json",
            "abyss-machine resource orchestrator --json",
            "abyss-machine nervous quality-audit --json",
            "abyss-machine heartbeats validate --json",
        ],
    }.items():
        current = stack.setdefault(key, [])
        if isinstance(current, list):
            seen = set(current)
            for value in values:
                if value not in seen:
                    current.append(value)
                    seen.add(value)
    stack["updated_at"] = now_iso()

    if write:
        try:
            stamp = dt.datetime.now(dt.UTC).strftime("%Y%m%dT%H%M%SZ")
            data["backup_paths"] = {
                "bridge": str(backup_static_manifest(MANIFEST_PATH, stamp)),
                "stack_bridge": str(backup_static_manifest(STACK_BRIDGE_CONFIG_PATH, stamp)),
            }
            atomic_write_json_preserve(MANIFEST_PATH, bridge)
            atomic_write_json_preserve(STACK_BRIDGE_CONFIG_PATH, stack)
        except OSError as exc:
            data["error"] = str(exc)
            return stack_bridge_static_sync_record(data, write_latest)
    else:
        stamp = dt.datetime.now(dt.UTC).strftime("%Y%m%dT%H%M%SZ")
        data["backup_paths"] = {
            "bridge": str(MANIFEST_PATH.with_name(f".{MANIFEST_PATH.name}.pre-sync-{stamp}.bak")),
            "stack_bridge": str(STACK_BRIDGE_CONFIG_PATH.with_name(f".{STACK_BRIDGE_CONFIG_PATH.name}.pre-sync-{stamp}.bak")),
        }

    after_bridge_commands = bridge.get("commands", {}) if isinstance(bridge.get("commands"), dict) else {}
    after_stack_commands = stack.get("commands", {}) if isinstance(stack.get("commands"), dict) else {}
    after_stack_artifacts = stack.get("artifacts", {}) if isinstance(stack.get("artifacts"), dict) else {}
    after_resource_artifacts = after_stack_artifacts.get("resource", {}) if isinstance(after_stack_artifacts.get("resource"), dict) else {}
    after_nervous_artifacts = after_stack_artifacts.get("nervous", {}) if isinstance(after_stack_artifacts.get("nervous"), dict) else {}
    after_heartbeat_artifacts = after_stack_artifacts.get("heartbeats", {}) if isinstance(after_stack_artifacts.get("heartbeats"), dict) else {}
    after_observability_artifacts = after_stack_artifacts.get("observability", {}) if isinstance(after_stack_artifacts.get("observability"), dict) else {}
    after_self_awareness_artifacts = after_stack_artifacts.get("self_awareness", {}) if isinstance(after_stack_artifacts.get("self_awareness"), dict) else {}
    after = {
        "bridge_missing_commands": sorted(command_keys - set(after_bridge_commands)),
        "stack_missing_commands": sorted(command_keys - set(after_stack_commands)),
        "stack_missing_artifacts": [
            item for item, missing in {
                "artifacts.resource.orchestrator": "orchestrator" not in after_resource_artifacts,
                "artifacts.nervous.quality": "quality" not in after_nervous_artifacts,
                "artifacts.heartbeats.latest": "latest" not in after_heartbeat_artifacts,
                "artifacts.heartbeats.validate": "validate" not in after_heartbeat_artifacts,
                "artifacts.observability.stack_observability": "stack_observability" not in after_observability_artifacts,
                **{
                    f"artifacts.self_awareness.{name}": name not in after_self_awareness_artifacts
                    for name in (
                        "capabilities", "requirements", "requirement_probes", "events", "collect", "query", "correlation", "timeline",
                        "failure_matrix", "spatial_graph", "context", "episodes", "alerts", "investigate", "replay", "brief", "probe", "cycle", "export", "validate"
                    )
                },
            }.items() if missing
        ],
        "stack_missing_static_compatibility": stack_bridge_static_compatibility_missing(stack),
    }
    data["after"] = after
    data["ok"] = (
        not after["bridge_missing_commands"]
        and not after["stack_missing_commands"]
        and not after["stack_missing_artifacts"]
        and not after["stack_missing_static_compatibility"]
    )
    return stack_bridge_static_sync_record(data, write_latest)


def stack_bridge_ref_status(route: dict[str, Any]) -> dict[str, Any]:
    path = Path(str(route.get("path") or ""))
    data, error = load_json_document(path)
    schema = data.get("schema") if isinstance(data, dict) else None
    expected_schema = route.get("schema")
    generated_at = data.get("generated_at") if isinstance(data, dict) else None
    if generated_at is None and isinstance(data, dict):
        generated_at = data.get("updated_at")
    return {
        "path": str(path),
        "exists": path.exists(),
        "ok": bool(data.get("ok", True)) if isinstance(data, dict) else False,
        "schema": schema,
        "expected_schema": expected_schema,
        "schema_ok": expected_schema is None or schema == expected_schema,
        "generated_at": generated_at,
        "summary": data.get("summary") if isinstance(data, dict) else None,
        "truth_level": route.get("truth_level"),
        "load_error": error,
    }


def stack_bridge_export(write_latest: bool = True) -> dict[str, Any]:
    manifest = stack_bridge_config()
    artifacts = manifest.get("artifacts") if isinstance(manifest.get("artifacts"), dict) else stack_bridge_artifact_routes()
    refs: dict[str, dict[str, Any]] = {}
    required_missing: list[dict[str, Any]] = []
    schema_mismatches: list[dict[str, Any]] = []
    for layer, routes in artifacts.items():
        if not isinstance(routes, dict):
            continue
        refs[layer] = {}
        for name, route in routes.items():
            if not isinstance(route, dict):
                continue
            status_item = stack_bridge_ref_status(route)
            refs[layer][name] = status_item
            required = route.get("truth_level") in {"contract", "host_contract", "change_ledger"}
            if required and not status_item.get("exists"):
                required_missing.append({"layer": layer, "name": name, "path": status_item.get("path")})
            if status_item.get("exists") and not status_item.get("schema_ok"):
                schema_mismatches.append({"layer": layer, "name": name, "expected": status_item.get("expected_schema"), "actual": status_item.get("schema")})

    bridge = bridge_manifest()
    commands = bridge.get("commands", {}) if isinstance(bridge.get("commands"), dict) else {}
    stack_command_keys = sorted(key for key in commands if key.startswith("stack_bridge_"))
    named_bridges = {
        key: manifest.get(key)
        for key in (
            "mode_bridge",
            "process_thermal_bridge",
            "memory_bridge",
            "resource_bridge",
            "nervous_quality_bridge",
            "typing_bridge",
            "heartbeat_bridge",
            "stack_observability_bridge",
            "self_awareness_bridge",
        )
        if isinstance(manifest.get(key), dict)
    }
    named_bridges["heartbeat_bridge"] = stack_bridge_heartbeat_bridge_contract()
    data = stack_bridge_contracts.export_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        root=STACK_BRIDGE_ROOT,
        latest_path=STACK_BRIDGE_LATEST_PATH,
        config_path=STACK_BRIDGE_CONFIG_PATH,
        config_exists=STACK_BRIDGE_CONFIG_PATH.exists(),
        manifest=manifest,
        paths=stack_bridge_paths(),
        stack_roots=stack_paths(),
        protected_roots=storage_protected_roots(),
        bridges=named_bridges,
        artifacts=artifacts,
        refs=refs,
        required_missing=required_missing,
        schema_mismatches=schema_mismatches,
        stack_command_keys=stack_command_keys,
    )
    if write_latest:
        errors = write_latest_and_history(data, STACK_BRIDGE_LATEST_PATH, STACK_BRIDGE_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def stack_bridge_latest() -> dict[str, Any]:
    data, error = load_json_document(STACK_BRIDGE_LATEST_PATH)
    return stack_bridge_contracts.latest_read_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        latest_path=STACK_BRIDGE_LATEST_PATH,
        data=data,
        error=error,
    )


def stack_bridge_validate(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    validation_add_path_exists(checks, "doc:stack_bridge_doc", STACK_BRIDGE_DOC_PATH, "file", required=True)
    validation_add_path_exists(checks, "doc:stack_bridge_agents", STACK_BRIDGE_AGENTS_PATH, "file", required=True)
    validation_add_path_exists(checks, "dir:stack_bridge_root", STACK_BRIDGE_ROOT, "dir", required=True)
    validation_add_path_exists(checks, "dir:hooks_etc_stack_bridge", STACK_BRIDGE_HOOKS_ETC_DIR, "dir", required=False)
    validation_add_path_exists(checks, "dir:hooks_srv_stack_bridge", STACK_BRIDGE_HOOKS_SRV_DIR, "dir", required=False)
    topology_validate_json_file(checks, "json:stack_bridge_config", STACK_BRIDGE_CONFIG_PATH, f"{SCHEMA_PREFIX}_stack_bridge_manifest_v1", required=True)
    topology_validate_json_file(checks, "json:main_bridge", MANIFEST_PATH, f"{SCHEMA_PREFIX}_bridge_v1", required=True)
    export = stack_bridge_export(write_latest=False)
    topology_validation_add(
        checks,
        "fail" if not export.get("ok") else "ok",
        "stack_bridge_export",
        "stack bridge export resolves required routes" if export.get("ok") else "stack bridge export has route issues",
        {"summary": export.get("summary"), "issues": export.get("issues")},
    )
    bridge = bridge_manifest()
    commands = bridge.get("commands", {}) if isinstance(bridge.get("commands"), dict) else {}
    required_commands = {
        "stack_bridge_json",
        "stack_bridge_paths_json",
        "stack_bridge_export_json",
        "stack_bridge_latest_json",
        "stack_bridge_validate_json",
        "stack_bridge_observability_json",
        "self_awareness_probe_json",
        "self_awareness_failure_matrix_json",
        "self_awareness_requirements_json",
        "self_awareness_requirement_probes_json",
        "self_awareness_stack_closure_dossier_json",
        "self_awareness_trace_context_json",
        "self_awareness_cycle_json",
        "self_awareness_validate_json",
    }
    missing_commands = sorted(required_commands - set(commands))
    topology_validation_add(
        checks,
        "fail" if missing_commands else "ok",
        "bridge_commands",
        "main bridge exposes stack bridge commands" if not missing_commands else "main bridge is missing stack bridge commands",
        {"missing": missing_commands},
    )
    export_artifacts = export.get("artifacts") if isinstance(export.get("artifacts"), dict) else {}
    heartbeat_artifacts = export_artifacts.get("heartbeats") if isinstance(export_artifacts.get("heartbeats"), dict) else {}
    heartbeat_latest = load_latest_json(HEARTBEATS_LATEST_PATH, f"{SCHEMA_PREFIX}_heartbeat_pulse_v1")
    heartbeat_validation = heartbeats_validate(strict=False, write_latest=False)
    heartbeat_readiness = stack_bridge_heartbeat_readiness(heartbeat_latest, heartbeat_validation, heartbeat_artifacts)
    topology_validation_add(
        checks,
        "fail" if heartbeat_readiness.get("missing_artifacts") else "ok",
        "heartbeat_bridge_artifacts",
        "stack bridge exposes heartbeat latest and validation artifacts" if not heartbeat_readiness.get("missing_artifacts") else "stack bridge is missing heartbeat artifacts",
        {
            "missing": heartbeat_readiness.get("missing_artifacts"),
            "non_readonly": heartbeat_readiness.get("non_readonly_artifacts"),
        },
    )
    topology_validation_add(
        checks,
        "fail" if heartbeat_readiness.get("missing_fields") else "ok",
        "heartbeat_bridge_stable_fields",
        "heartbeat bridge stable fields are present" if not heartbeat_readiness.get("missing_fields") else "heartbeat bridge stable fields are missing",
        {
            "stable_fields": heartbeat_readiness.get("stable_fields"),
            "missing": heartbeat_readiness.get("missing_fields"),
        },
    )
    topology_validation_add(
        checks,
        "fail" if not heartbeat_readiness.get("policy_ok") or heartbeat_readiness.get("non_readonly_artifacts") else "ok",
        "heartbeat_bridge_read_only",
        "heartbeat bridge is read-only and non-executing",
        {
            "policy_ok": heartbeat_readiness.get("policy_ok"),
            "policy": heartbeat_readiness.get("policy"),
            "non_readonly": heartbeat_readiness.get("non_readonly_artifacts"),
        },
    )
    topology_validation_add(
        checks,
        "fail" if not heartbeat_readiness.get("ok") else "ok",
        "heartbeat_bridge_validate_gate",
        "heartbeats validate proves bridge-stable fields" if heartbeat_readiness.get("ok") else "heartbeats validate does not yet prove bridge-stable fields",
        heartbeat_readiness,
    )
    causal_spine_expected = {
        "typing": ("events", "coverage", "process", "nervous_refresh", "validate"),
        "dictation": ("transcript", "validate"),
        "reactions": ("latest", "validate"),
        "responses": ("latest", "validate"),
    }
    causal_spine_missing: list[str] = []
    for layer, names in causal_spine_expected.items():
        layer_artifacts = export_artifacts.get(layer) if isinstance(export_artifacts.get(layer), dict) else {}
        for name in names:
            if not isinstance(layer_artifacts.get(name), dict):
                causal_spine_missing.append(f"artifacts.{layer}.{name}")
    topology_validation_add(
        checks,
        "fail" if causal_spine_missing else "ok",
        "causal_spine_artifacts",
        "stack bridge exposes typing, dictation, reactions, and responses evidence" if not causal_spine_missing else "stack bridge is missing causal spine artifacts",
        {"missing": causal_spine_missing},
    )
    expected_dynamic_commands = set(stack_bridge_extension_commands())
    static_bridge, static_bridge_error = load_json_document(MANIFEST_PATH)
    static_bridge_commands = static_bridge.get("commands", {}) if isinstance(static_bridge, dict) and isinstance(static_bridge.get("commands"), dict) else {}
    static_bridge_missing = sorted(expected_dynamic_commands - set(static_bridge_commands))
    static_stack, static_stack_error = load_json_document(STACK_BRIDGE_CONFIG_PATH)
    static_stack_commands = static_stack.get("commands", {}) if isinstance(static_stack, dict) and isinstance(static_stack.get("commands"), dict) else {}
    static_stack_artifacts = static_stack.get("artifacts", {}) if isinstance(static_stack, dict) and isinstance(static_stack.get("artifacts"), dict) else {}
    static_resource_artifacts = static_stack_artifacts.get("resource", {}) if isinstance(static_stack_artifacts.get("resource"), dict) else {}
    static_nervous_artifacts = static_stack_artifacts.get("nervous", {}) if isinstance(static_stack_artifacts.get("nervous"), dict) else {}
    static_heartbeat_artifacts = static_stack_artifacts.get("heartbeats", {}) if isinstance(static_stack_artifacts.get("heartbeats"), dict) else {}
    static_observability_artifacts = static_stack_artifacts.get("observability", {}) if isinstance(static_stack_artifacts.get("observability"), dict) else {}
    static_self_awareness_artifacts = static_stack_artifacts.get("self_awareness", {}) if isinstance(static_stack_artifacts.get("self_awareness"), dict) else {}
    static_stack_missing = sorted(expected_dynamic_commands - set(static_stack_commands))
    static_artifact_missing = []
    if "orchestrator" not in static_resource_artifacts:
        static_artifact_missing.append("artifacts.resource.orchestrator")
    if "quality" not in static_nervous_artifacts:
        static_artifact_missing.append("artifacts.nervous.quality")
    if "latest" not in static_heartbeat_artifacts:
        static_artifact_missing.append("artifacts.heartbeats.latest")
    if "validate" not in static_heartbeat_artifacts:
        static_artifact_missing.append("artifacts.heartbeats.validate")
    if "stack_observability" not in static_observability_artifacts:
        static_artifact_missing.append("artifacts.observability.stack_observability")
    for name in (
        "capabilities", "requirements", "requirement_probes", "events", "collect", "query", "correlation", "timeline",
        "failure_matrix", "stack_closure_dossier", "trace_context", "spatial_graph", "context", "episodes", "alerts", "investigate", "replay", "brief", "probe", "cycle", "export", "validate",
    ):
        if name not in static_self_awareness_artifacts:
            static_artifact_missing.append(f"artifacts.self_awareness.{name}")
    static_compatibility_missing = stack_bridge_static_compatibility_missing(static_stack) if isinstance(static_stack, dict) else []
    static_drift = bool(
        static_bridge_missing
        or static_stack_missing
        or static_artifact_missing
        or static_compatibility_missing
        or static_bridge_error
        or static_stack_error
    )
    root_sync_handoff = stack_bridge_static_sync_change_ref()
    topology_validation_add(
        checks,
        "warn" if static_drift else "ok",
        "static_bridge_sync",
        "static /etc bridge manifests match dynamic bridge routes" if not static_drift else "static /etc bridge manifests lag dynamic bridge routes",
        {
            "bridge": str(MANIFEST_PATH),
            "stack_bridge": str(STACK_BRIDGE_CONFIG_PATH),
            "bridge_missing_commands": static_bridge_missing,
            "stack_missing_commands": static_stack_missing,
            "stack_missing_artifacts": static_artifact_missing,
            "stack_missing_static_compatibility": static_compatibility_missing,
            "bridge_load_error": static_bridge_error,
            "stack_load_error": static_stack_error,
            "pending_change": root_sync_handoff["path"],
            "root_sync_handoff": root_sync_handoff,
        },
    )
    for path in (STACK_BRIDGE_ROOT, STACK_BRIDGE_LATEST_PATH):
        has_tail = nervous_path_has_symlink_tail(path, stop_at=STATE_DIR)
        topology_validation_add(
            checks,
            "fail" if has_tail else "ok",
            f"symlink_tail:{path}",
            f"{path} has no symlink tail" if not has_tail else f"{path} has a symlink tail",
            {"path": str(path)},
        )
    protected_write_claims: list[dict[str, Any]] = []
    for layer, routes in stack_bridge_artifact_routes().items():
        for name, route in routes.items():
            path_text = str(route.get("path") or "")
            if not path_text.startswith("/"):
                continue
            protection = storage_path_protection(Path(path_text))
            if protection.get("decision") == "deny" and route.get("write") is True:
                protected_write_claims.append({"layer": layer, "name": name, "path": path_text, "protection": protection})
    topology_validation_add(
        checks,
        "fail" if protected_write_claims else "ok",
        "protected_write_claims",
        "stack bridge has no writable claims on protected roots",
        {"claims": protected_write_claims},
    )
    observability_artifacts = export_artifacts.get("observability") if isinstance(export_artifacts.get("observability"), dict) else {}
    stack_observability_route = observability_artifacts.get("stack_observability") if isinstance(observability_artifacts.get("stack_observability"), dict) else {}
    stack_observability_latest = load_latest_json(STACK_OBSERVABILITY_LATEST_PATH, f"{SCHEMA_PREFIX}_stack_observability_v1")
    topology_validation_add(
        checks,
        "fail" if not stack_observability_route else "ok",
        "stack_observability_artifact",
        "stack bridge exposes stack observability readout" if stack_observability_route else "stack bridge is missing stack observability artifact",
        {"route": stack_observability_route},
    )
    topology_validation_add(
        checks,
        "ok" if stack_observability_latest.get("schema") == f"{SCHEMA_PREFIX}_stack_observability_v1" else "warn",
        "stack_observability_latest",
        "stack observability latest readout is present" if stack_observability_latest.get("schema") == f"{SCHEMA_PREFIX}_stack_observability_v1" else "stack observability latest readout has not been generated yet",
        {
            "path": str(STACK_OBSERVABILITY_LATEST_PATH),
            "schema": stack_observability_latest.get("schema"),
            "ok": stack_observability_latest.get("ok"),
            "summary": stack_observability_latest.get("summary"),
        },
    )
    self_awareness_artifacts = export_artifacts.get("self_awareness") if isinstance(export_artifacts.get("self_awareness"), dict) else {}
    self_awareness_missing = [
        name for name in (
            "capabilities", "requirements", "collect", "events", "query", "correlation", "timeline",
            "failure_matrix", "trace_context", "spatial_graph", "context", "episodes", "alerts", "investigate", "replay", "brief", "probe", "export", "validate"
        )
        if not isinstance(self_awareness_artifacts.get(name), dict)
    ]
    self_awareness_validation = load_latest_json(SELF_AWARENESS_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_validate_v1")
    topology_validation_add(
        checks,
        "fail" if self_awareness_missing else "ok",
        "self_awareness_artifacts",
        "stack bridge exposes self-awareness readmodels" if not self_awareness_missing else "stack bridge is missing self-awareness artifacts",
        {"missing": self_awareness_missing},
    )
    topology_validation_add(
        checks,
        "ok" if self_awareness_validation.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_validate_v1" and self_awareness_validation.get("ok") else "warn",
        "self_awareness_validate_latest",
        "self-awareness validate latest is green" if self_awareness_validation.get("ok") else "self-awareness validate latest has not passed yet",
        {
            "path": str(SELF_AWARENESS_VALIDATE_LATEST_PATH),
            "schema": self_awareness_validation.get("schema"),
            "ok": self_awareness_validation.get("ok"),
            "summary": self_awareness_validation.get("summary"),
        },
    )
    nervous_checks = {
        "nervous_index": nervous_index_validate(write_latest=False),
        "nervous_synthesis": nervous_synthesis_validate(write_latest=False),
        "nervous_eval": nervous_eval_validate(write_latest=False),
        "nervous_retention": nervous_retention_validate(write_latest=False),
    }
    for key, result in nervous_checks.items():
        topology_validation_add(
            checks,
            "fail" if not result.get("ok") else "ok",
            key,
            f"{key} validates" if result.get("ok") else f"{key} validation issues",
            result.get("summary"),
        )
    data = stack_bridge_validate_document_from_checks(
        checks,
        strict=strict,
        export_summary=export.get("summary") if isinstance(export.get("summary"), dict) else None,
        paths=stack_bridge_paths(),
    )
    if write_latest:
        errors = write_latest_and_history(data, STACK_BRIDGE_VALIDATE_LATEST_PATH, STACK_BRIDGE_VALIDATE_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def path_surface(path: Path) -> dict[str, Any]:
    try:
        stat = path.stat()
    except OSError:
        stat = None
    kind = "missing"
    if stat is not None:
        if path.is_dir():
            kind = "directory"
        elif path.is_file():
            kind = "file"
        elif path.is_symlink():
            kind = "symlink"
        else:
            kind = "other"
    return {
        "path": str(path),
        "exists": stat is not None,
        "kind": kind,
        "writable": os.access(path, os.W_OK) if stat is not None else os.access(path.parent, os.W_OK),
    }


