def topology_status(write_latest: bool = True) -> dict[str, Any]:
    paths = topology_paths()
    roots = {
        name: path_surface(Path(path))
        for name, path in paths["roots"].items()
        if isinstance(path, str) and path.startswith("/")
    }
    docs = {
        name: path_surface(Path(path))
        for name, path in paths["docs"].items()
        if isinstance(path, str) and path.startswith("/")
    }
    writable_roots = [
        str(ABYSS_MACHINE_ROOT),
        str(ABYSS_MACHINE_CACHE_ROOT),
        str(ABYSS_MACHINE_RUNTIME_ROOT),
        str(ABYSS_MACHINE_STORAGE_ROOT),
        str(ABYSS_MACHINE_TMP_ROOT),
        str(STATE_DIR),
    ]
    data = topology_contracts.status_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        paths=paths,
        docs=docs,
        roots=roots,
        writable_roots=writable_roots,
        surface_states=topology_surface_states(),
        protected_roots=storage_protected_roots(),
        stack_user_source_root=ABYSS_STACK_USER_SOURCE_ROOT,
    )
    if write_latest:
        latest_error = safe_atomic_write_json(TOPOLOGY_LATEST_PATH, data, 0o664)
        index_error = safe_atomic_write_json(TOPOLOGY_INDEX_PATH, topology_index_document(data), 0o664)
        errors = [error for error in (latest_error, index_error) if error]
        if errors:
            data["write_errors"] = errors
            data["ok"] = False
    return data


