def topology_validation_add(
    checks: list[dict[str, Any]],
    level: str,
    key: str,
    message: str,
    data: Any = None,
) -> None:
    item: dict[str, Any] = {"level": level, "key": key, "message": message}
    if data is not None:
        item["data"] = data
    checks.append(item)


def topology_validate_json_file(
    checks: list[dict[str, Any]],
    key: str,
    path: Path,
    expected_schema: str | None = None,
    required: bool = True,
) -> dict[str, Any] | None:
    data, error = load_json_document(path)
    if data is None:
        topology_validation_add(
            checks,
            "fail" if required else "warn",
            key,
            f"{path} missing or invalid JSON",
            {"path": str(path), "error": error},
        )
        return None
    schema = data.get("schema")
    if expected_schema and schema != expected_schema:
        topology_validation_add(
            checks,
            "fail",
            key,
            f"{path} schema mismatch",
            {"path": str(path), "expected_schema": expected_schema, "actual_schema": schema},
        )
    else:
        topology_validation_add(checks, "ok", key, f"{path} valid", {"path": str(path), "schema": schema})
    return data


def topology_text_contains(
    checks: list[dict[str, Any]],
    key: str,
    path: Path,
    required_patterns: list[str],
    required: bool = True,
) -> None:
    text = read_text(path)
    if text is None:
        topology_validation_add(
            checks,
            "fail" if required else "warn",
            key,
            f"{path} missing or unreadable",
            {"path": str(path)},
        )
        return
    missing = [pattern for pattern in required_patterns if pattern not in text]
    if missing:
        topology_validation_add(
            checks,
            "fail" if required else "warn",
            key,
            f"{path} missing required topology references",
            {"path": str(path), "missing": missing},
        )
    else:
        topology_validation_add(checks, "ok", key, f"{path} contains required topology references")


def topology_under_forbidden_root(path: str) -> str | None:
    return topology_contracts.under_forbidden_root(path)


def topology_jsonl_status(path: Path, max_lines: int = 5000) -> dict[str, Any]:
    if not path.exists():
        return {"exists": False, "lines": 0, "invalid": 0, "checked": 0}
    invalid: list[dict[str, Any]] = []
    checked = 0
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError as exc:
        return {"exists": True, "error": str(exc), "lines": None, "invalid": 1, "checked": 0}
    start = max(0, len(lines) - max_lines)
    for index, line in enumerate(lines[start:], start=start + 1):
        if not line.strip():
            continue
        checked += 1
        try:
            parsed = json.loads(line)
        except json.JSONDecodeError as exc:
            invalid.append({"line": index, "error": str(exc)})
            continue
        if not isinstance(parsed, dict):
            invalid.append({"line": index, "error": "record is not an object"})
    return {"exists": True, "lines": len(lines), "checked": checked, "invalid": len(invalid), "errors": invalid[:10]}


def topology_validate_change_records(checks: list[dict[str, Any]]) -> None:
    required_files = ["change.json", "intent.md", "actions.jsonl", "validation.md", "rollback.md", "closeout.md"]
    active_bad: list[dict[str, Any]] = []
    closed_bad: list[dict[str, Any]] = []
    active_count = 0
    closed_count = 0
    for root, expected_status, bucket in (
        (CHANGE_ACTIVE_ROOT, "active", active_bad),
        (CHANGE_CLOSED_ROOT, "closed", closed_bad),
    ):
        if not root.exists():
            if root == CHANGE_ACTIVE_ROOT:
                topology_validation_add(checks, "ok", "changes_active_root_absent", f"{root} absent with no active changes")
            else:
                topology_validation_add(checks, "warn", "changes_closed_root_absent", f"{root} missing; no closed change records yet")
            continue
        for item in sorted(root.iterdir(), key=lambda path: path.name):
            if not item.is_dir():
                continue
            if root == CHANGE_ACTIVE_ROOT:
                active_count += 1
            else:
                closed_count += 1
            data, error = load_json_document(item / "change.json")
            if not data:
                bucket.append({"id": item.name, "issue": error or "missing change.json"})
                continue
            status_value = data.get("status")
            if expected_status == "active" and status_value in {"closed", "cancelled", "superseded"}:
                bucket.append({"id": item.name, "issue": f"non-active status in active root: {status_value}"})
            if expected_status == "closed" and status_value != "closed":
                bucket.append({"id": item.name, "issue": f"closed root status is {status_value}"})
            missing = [name for name in required_files if not (item / name).exists()]
            if missing:
                bucket.append({"id": item.name, "issue": "missing files", "missing": missing})
            actions_status = topology_jsonl_status(item / "actions.jsonl")
            if actions_status.get("invalid"):
                bucket.append({"id": item.name, "issue": "invalid actions.jsonl", "details": actions_status})
    topology_validation_add(
        checks,
        "fail" if active_bad else "ok",
        "changes_active_lifecycle",
        "active change records are valid" if not active_bad else "active change lifecycle issues found",
        {"active_records": active_count, "issues": active_bad},
    )
    topology_validation_add(
        checks,
        "fail" if closed_bad else "ok",
        "changes_closed_lifecycle",
        "closed change records are valid" if not closed_bad else "closed change lifecycle issues found",
        {"closed_records": closed_count, "issues": closed_bad},
    )
    for history_file in sorted(CHANGE_HISTORY_ROOT.glob("*/*/*.jsonl"))[-10:] if CHANGE_HISTORY_ROOT.exists() else []:
        status = topology_jsonl_status(history_file)
        topology_validation_add(
            checks,
            "fail" if status.get("invalid") else "ok",
            f"changes_history_jsonl:{history_file.name}",
            f"{history_file} JSONL valid" if not status.get("invalid") else f"{history_file} JSONL invalid",
            {"path": str(history_file), **status},
        )


