def docs_markdown_headings(text: str) -> list[str]:
    return [line.strip() for line in text.splitlines() if line.startswith("#")]


def docs_agents_mesh_config() -> tuple[dict[str, Any] | None, str | None]:
    data, error = load_json_document(AGENTS_MESH_CONFIG_PATH)
    if data is None:
        return None, error or f"missing config: {AGENTS_MESH_CONFIG_PATH}"
    if not isinstance(data, dict):
        return None, f"{AGENTS_MESH_CONFIG_PATH} is not a JSON object"
    return data, None


def docs_agents_mesh_config_cards(config: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if config is None:
        config, _ = docs_agents_mesh_config()
    if not isinstance(config, dict):
        return []
    cards = config.get("cards")
    if not isinstance(cards, list):
        return []
    return [item for item in cards if isinstance(item, dict)]


def docs_agents_mesh_skip_root(path: Path) -> bool:
    skip_roots = docs_agents_mesh_subject_store_roots() + [
        ABYSS_MACHINE_STORAGE_ROOT,
        ABYSS_MACHINE_TMP_ROOT,
        ABYSS_MACHINE_ROOT / "tmp",
    ]
    path_text = str(path)
    if any(path_text == str(root) or path_text.startswith(str(root) + os.sep) for root in skip_roots):
        return True
    llama_runtime_root = ABYSS_MACHINE_ROOT / "runtimes" / "llama.cpp"
    try:
        rel = path.relative_to(llama_runtime_root)
    except ValueError:
        return False
    if len(rel.parts) >= 2 and (rel.parts[1] == "source" or rel.parts[1].startswith("build")):
        return True
    return False


def docs_agents_mesh_subject_store_roots() -> list[Path]:
    raw_roots: list[str] = []
    for name in ("ABYSS_MACHINE_ARTIFACT_SUBJECT_STORE_ROOTS", "ABYSS_MACHINE_ARTIFACT_SUBJECT_STORE_ROOT"):
        raw = os.environ.get(name)
        if not raw:
            continue
        if name.endswith("_ROOTS"):
            raw_roots.extend(item for item in raw.split(os.pathsep) if item)
        else:
            raw_roots.append(raw)
    raw_roots.extend(
        [
            str(ARTIFACTS_ROOT / "subjects"),
            str(getattr(artifact_bundles, "DEFAULT_ARTIFACT_SUBJECT_STORE_ROOT", "")),
        ]
    )
    roots: list[Path] = []
    seen: set[str] = set()
    for raw in raw_roots:
        if not raw:
            continue
        root = Path(raw).expanduser()
        key = str(root)
        if key in seen:
            continue
        seen.add(key)
        roots.append(root)
    return roots


def docs_agents_mesh_discovered_cards() -> list[str]:
    roots = [Path("/etc/abyss-machine"), STATE_DIR, ABYSS_MACHINE_ROOT]
    discovered: set[str] = set()
    for root in roots:
        if not root.exists() or docs_agents_mesh_skip_root(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root, topdown=True, onerror=None):
            current = Path(dirpath)
            dirnames[:] = [
                name for name in dirnames
                if not docs_agents_mesh_skip_root(current / name)
                and name not in {".git", "__pycache__", ".venv"}
            ]
            if "AGENTS.md" in filenames:
                path = current / "AGENTS.md"
                if not docs_agents_mesh_skip_root(path):
                    discovered.add(str(path))
    return sorted(discovered)


def docs_agents_mesh_card_record(card: dict[str, Any]) -> dict[str, Any]:
    path = Path(str(card.get("path") or ""))
    record: dict[str, Any] = {
        "path": str(path),
        "id": card.get("id") or docs_spec_id(path, "agents"),
        "kind": card.get("kind"),
        "role": card.get("role"),
        "required": bool(card.get("required", True)),
        "exists": path.exists(),
    }
    if not path.exists():
        return record
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
        stat = path.stat()
    except OSError as exc:
        record["read_error"] = str(exc)
        return record
    headings = docs_markdown_headings(text)
    markers = [str(item) for item in card.get("required_markers", []) if isinstance(item, str)]
    missing_markers = [marker for marker in markers if marker not in text]
    lines = text.count("\n") + (0 if not text else 1)
    max_lines = card.get("max_lines")
    record.update({
        "size_bytes": stat.st_size,
        "mtime": dt.datetime.fromtimestamp(stat.st_mtime, dt.timezone.utc).astimezone().isoformat(timespec="seconds"),
        "lines": lines,
        "sha256": hashlib.sha256(text.encode("utf-8", errors="replace")).hexdigest(),
        "headings": headings,
        "heading_count": len(headings),
        "first_heading": headings[0] if headings else None,
        "required_markers": markers,
        "missing_markers": missing_markers,
        "max_lines": max_lines,
        "line_limit_ok": not isinstance(max_lines, int) or lines <= max_lines,
        "has_heading": bool(headings),
    })
    return record


def docs_agents_mesh_index_document(config: dict[str, Any] | None = None) -> dict[str, Any]:
    if config is None:
        config, _ = docs_agents_mesh_config()
    cards = docs_agents_mesh_config_cards(config)
    records = [docs_agents_mesh_card_record(card) for card in cards]
    configured_paths = {str(record.get("path")) for record in records}
    discovered_paths = set(docs_agents_mesh_discovered_cards())
    unregistered = sorted(discovered_paths - configured_paths)
    missing_required = [
        record for record in records
        if record.get("required") and not record.get("exists")
    ]
    stale_shape = [
        record for record in records
        if record.get("exists") and (record.get("missing_markers") or not record.get("line_limit_ok") or not record.get("has_heading"))
    ]
    return {
        "schema": f"{SCHEMA_PREFIX}_docs_agents_mesh_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": not missing_required and not stale_shape and not unregistered and isinstance(config, dict),
        "config": str(AGENTS_MESH_CONFIG_PATH),
        "authority": config.get("authority") if isinstance(config, dict) else None,
        "policy": {
            "generated": True,
            "do_not_hand_edit": True,
            "source_config": str(AGENTS_MESH_CONFIG_PATH),
            "generated_facts_do_not_replace_source_cards": True,
        },
        "summary": {
            "cards": len(records),
            "required_cards": sum(1 for record in records if record.get("required")),
            "missing_required": len(missing_required),
            "shape_issues": len(stale_shape),
            "unregistered_cards": len(unregistered),
        },
        "cards": records,
        "unregistered_cards": unregistered,
    }


def docs_agents_mesh_build(write_latest: bool = True) -> dict[str, Any]:
    config, error = docs_agents_mesh_config()
    data = docs_agents_mesh_index_document(config)
    if error:
        data["ok"] = False
        data["config_error"] = error
    if write_latest:
        write_error = safe_atomic_write_json(DOCS_AGENTS_MESH_LATEST_PATH, data, 0o664)
        if write_error:
            data["ok"] = False
            data["write_errors"] = [write_error]
    return data


def docs_agents_mesh_validate_document_from_checks(
    checks: list[dict[str, Any]],
    *,
    strict: bool,
    current_summary: dict[str, Any] | None,
    generated_at: str | None = None,
) -> dict[str, Any]:
    return docs_contracts.agents_mesh_validate_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=generated_at or now_iso(),
        checks=checks,
        strict=strict,
        index_path=DOCS_AGENTS_MESH_LATEST_PATH,
        config_path=AGENTS_MESH_CONFIG_PATH,
        current_summary=current_summary,
    )


def docs_agents_mesh_validate(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    config, config_error = docs_agents_mesh_config()
    topology_validation_add(
        checks,
        "fail" if config_error else "ok",
        "config",
        f"{AGENTS_MESH_CONFIG_PATH} valid" if not config_error else f"{AGENTS_MESH_CONFIG_PATH} missing or invalid",
        {"error": config_error, "path": str(AGENTS_MESH_CONFIG_PATH)},
    )
    for key, path in {
        "design": DESIGN_DOC_PATH,
        "design_agents": DESIGN_AGENTS_DOC_PATH,
        "roadmap": ROADMAP_DOC_PATH,
        "changelog": CHANGELOG_DOC_PATH,
        "decisions_agents": DECISIONS_AGENTS_PATH,
        "decisions_readme": DECISIONS_README_PATH,
        "decisions_template": DECISIONS_TEMPLATE_PATH,
        "srv_design": SRV_DESIGN_DOC_PATH,
        "root_agents": ETC_AGENTS_PATH,
        "docs_contract": DOCS_DOC_PATH,
        "commands_catalog": COMMANDS_DOC_PATH,
    }.items():
        validation_add_path_exists(checks, f"doc:{key}", path, "file", required=True)

    current = docs_agents_mesh_index_document(config)
    current_cards = current.get("cards", []) if isinstance(current.get("cards"), list) else []
    for record in current_cards:
        path = str(record.get("path"))
        if record.get("required") and not record.get("exists"):
            topology_validation_add(checks, "fail", f"card_exists:{path}", f"{path} missing", record)
            continue
        if not record.get("exists"):
            topology_validation_add(checks, "warn", f"card_exists:{path}", f"{path} optional missing", record)
            continue
        topology_validation_add(checks, "ok", f"card_exists:{path}", f"{path} present", {"path": path})
        missing_markers = record.get("missing_markers") if isinstance(record.get("missing_markers"), list) else []
        topology_validation_add(
            checks,
            "fail" if missing_markers else "ok",
            f"card_markers:{path}",
            f"{path} has required route markers" if not missing_markers else f"{path} missing required route markers",
            {"missing": missing_markers},
        )
        topology_validation_add(
            checks,
            "fail" if not record.get("has_heading") else "ok",
            f"card_heading:{path}",
            f"{path} has markdown heading" if record.get("has_heading") else f"{path} missing markdown heading",
            {"first_heading": record.get("first_heading")},
        )
        if isinstance(record.get("max_lines"), int):
            topology_validation_add(
                checks,
                "fail" if not record.get("line_limit_ok") else "ok",
                f"card_line_limit:{path}",
                f"{path} within line budget" if record.get("line_limit_ok") else f"{path} exceeds line budget",
                {"lines": record.get("lines"), "max_lines": record.get("max_lines")},
            )

    unregistered = current.get("unregistered_cards") if isinstance(current.get("unregistered_cards"), list) else []
    topology_validation_add(
        checks,
        "fail" if unregistered else "ok",
        "all_discovered_cards_registered",
        "all discovered host AGENTS.md cards are registered" if not unregistered else "some discovered host AGENTS.md cards are not in the mesh config",
        {"unregistered": unregistered},
    )

    latest, latest_error = load_json_document(DOCS_AGENTS_MESH_LATEST_PATH)
    if latest_error:
        topology_validation_add(
            checks,
            "fail",
            "generated_index_exists",
            f"{DOCS_AGENTS_MESH_LATEST_PATH} missing or invalid",
            {"error": latest_error, "path": str(DOCS_AGENTS_MESH_LATEST_PATH)},
        )
    else:
        latest_cards = latest.get("cards", []) if isinstance(latest, dict) and isinstance(latest.get("cards"), list) else []
        latest_hashes = {str(item.get("path")): item.get("sha256") for item in latest_cards if isinstance(item, dict)}
        current_hashes = {str(item.get("path")): item.get("sha256") for item in current_cards if isinstance(item, dict)}
        drift = [
            {"path": path, "latest": latest_hashes.get(path), "current": current_hash}
            for path, current_hash in current_hashes.items()
            if latest_hashes.get(path) != current_hash
        ]
        topology_validation_add(
            checks,
            "fail" if drift else "ok",
            "generated_index_current",
            "generated AGENTS mesh index is current" if not drift else "generated AGENTS mesh index is stale",
            {"drift": drift, "path": str(DOCS_AGENTS_MESH_LATEST_PATH)},
        )

    data = docs_agents_mesh_validate_document_from_checks(
        checks,
        strict=strict,
        current_summary=current.get("summary") if isinstance(current.get("summary"), dict) else None,
    )
    if write_latest:
        errors = write_latest_and_history(data, DOCS_AGENTS_MESH_VALIDATE_LATEST_PATH, DOCS_AGENTS_MESH_VALIDATE_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


