def docs_read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


def docs_audit(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    specs = docs_document_specs()
    checks: list[dict[str, Any]] = []
    records = [docs_file_record(spec) for spec in specs]

    for record in records:
        required = bool(record.get("required"))
        exists = bool(record.get("exists"))
        level = "ok" if exists else ("fail" if required else "warn")
        topology_validation_add(
            checks,
            level,
            f"doc_exists:{record.get('id')}",
            f"{record.get('path')} present" if exists else f"{record.get('path')} missing",
            {"path": record.get("path"), "role": record.get("role"), "required": required},
        )

    text_requirements = [
        (
            "docs_contract_policy",
            DOCS_DOC_PATH,
            [
                "Source Hierarchy",
                "Do Not Duplicate",
                "abyss-machine docs audit --json",
                "abyss-machine docs mesh-validate --json",
                str(COMMANDS_DOC_PATH),
                str(TOPOLOGY_DOC_PATH),
                str(DESIGN_DOC_PATH),
                str(DESIGN_AGENTS_DOC_PATH),
                str(ROADMAP_DOC_PATH),
                str(CHANGELOG_DOC_PATH),
                str(DECISIONS_ROOT),
                str(SRV_DESIGN_DOC_PATH),
            ],
        ),
        (
            "agents_docs_route",
            ETC_AGENTS_PATH,
            [
                str(DOCS_DOC_PATH),
                "abyss-machine docs audit --json",
                "abyss-machine docs mesh-validate --json",
                str(COMMANDS_DOC_PATH),
                str(DESIGN_DOC_PATH),
                str(DESIGN_AGENTS_DOC_PATH),
                str(ROADMAP_DOC_PATH),
                str(DECISIONS_AGENTS_PATH),
                "## Post-change route review",
            ],
        ),
        (
            "srv_agents_design_route",
            ABYSS_MACHINE_ROOT / "AGENTS.md",
            [
                str(SRV_DESIGN_DOC_PATH),
                str(DESIGN_DOC_PATH),
                "abyss-machine docs mesh-validate --json",
                "## Boundaries",
            ],
        ),
        (
            "design_agents_route",
            DESIGN_AGENTS_DOC_PATH,
            [
                "AGENTS.md",
                str(AGENTS_MESH_CONFIG_PATH),
                "abyss-machine docs mesh-validate --json",
                "generated facts",
                str(ROADMAP_DOC_PATH),
                str(CHANGELOG_DOC_PATH),
                str(DECISIONS_ROOT),
            ],
        ),
        (
            "roadmap_direction_route",
            ROADMAP_DOC_PATH,
            [
                "Current Host Direction",
                "Horizon:",
                "When The Time Comes",
                "No roadmap history as change ledger truth",
                str(CHANGE_ROOT),
            ],
        ),
        (
            "decisions_route",
            DECISIONS_AGENTS_PATH,
            [
                "Decision Review Gate",
                "TEMPLATE.md",
                "Current source surfaces define what",
                "abyss-machine docs audit --json",
            ],
        ),
        (
            "decisions_readme_route",
            DECISIONS_README_PATH,
            [
                "Decisions explain why",
                "Current source surfaces define what",
                "Promotion Path",
                "TEMPLATE.md",
                str(DOCS_DECISIONS_INDEX_LATEST_PATH),
                "abyss-machine docs decisions-index --json",
            ],
        ),
        (
            "changelog_milestone_route",
            CHANGELOG_DOC_PATH,
            [
                "curated host-layer milestones",
                str(CHANGE_ROOT),
                "Do not record every probe",
                "ROADMAP.md",
                "decisions/",
            ],
        ),
        (
            "commands_docs_route",
            COMMANDS_DOC_PATH,
            [
                "abyss-machine docs audit --json",
                "abyss-machine docs mesh --json",
                "abyss-machine docs mesh-validate --json",
                str(DOCS_DOC_PATH),
                str(DOCS_LATEST_PATH),
                str(ROADMAP_DOC_PATH),
                str(CHANGELOG_DOC_PATH),
                str(DECISIONS_AGENTS_PATH),
                "abyss-machine docs decisions-index --json",
            ],
        ),
        (
            "readme_docs_route",
            README_DOC_PATH,
            [
                str(DOCS_DOC_PATH),
                str(ROADMAP_DOC_PATH),
                str(DECISIONS_AGENTS_PATH),
                str(DOCS_DECISIONS_INDEX_LATEST_PATH),
                "abyss-machine docs audit --json",
            ],
        ),
    ]
    for key, path, tokens in text_requirements:
        topology_text_contains(checks, key, path, tokens)

    top_level_commands = [
        "doctor",
        "facts",
        "status",
        "bridge",
        "enter",
        "modes",
        "snapshots",
        "topology",
        "graph",
        "maps",
        "rag",
        "stack-bridge",
        "changes",
        "storage",
        "memory",
        "resource",
        "heartbeats",
        "reactions",
        "responses",
        "processes",
        "nervous",
        "ai",
        "observability",
        "cooling",
        "mode",
        "dictation",
        "docs",
    ]
    commands_text = docs_read_text(COMMANDS_DOC_PATH)
    missing_commands = [
        command
        for command in top_level_commands
        if f"abyss-machine {command}" not in commands_text and not re.search(rf"^\s*{re.escape(command)}\b", commands_text, flags=re.MULTILINE)
    ]
    topology_validation_add(
        checks,
        "warn" if missing_commands else "ok",
        "commands_catalog_top_level_coverage",
        "commands catalog covers top-level CLI surfaces" if not missing_commands else "commands catalog misses top-level CLI surfaces",
        {"missing": missing_commands},
    )

    readme_text = docs_read_text(README_DOC_PATH)
    stale_readme_markers = [
        marker
        for marker in [
            "abyss-machine facts --json",
            "abyss-machine modes --json",
            "abyss-machine snapshots --json",
            "abyss-machine dictation toggle",
        ]
        if marker in readme_text and "Documentation Contract" not in readme_text
    ]
    topology_validation_add(
        checks,
        "warn" if stale_readme_markers else "ok",
        "installed_readme_not_second_catalog",
        "installed README is a short pointer, not a stale command catalog" if not stale_readme_markers else "installed README still carries stale command-catalog markers",
        {"markers": stale_readme_markers},
    )

    decisions_index_current = docs_decisions_index_document()
    decisions_bad = [
        record for record in decisions_index_current.get("records", [])
        if isinstance(record, dict) and not record.get("ok")
    ]
    topology_validation_add(
        checks,
        "fail" if not decisions_index_current.get("ok") else "ok",
        "decisions_index_source_records",
        "decision records parse into generated index" if decisions_index_current.get("ok") else "decision records have index issues",
        {"summary": decisions_index_current.get("summary"), "issues": decisions_bad},
    )
    latest_decisions_index, latest_decisions_error = load_json_document(DOCS_DECISIONS_INDEX_LATEST_PATH)
    if latest_decisions_error:
        topology_validation_add(
            checks,
            "fail",
            "decisions_index_exists",
            f"{DOCS_DECISIONS_INDEX_LATEST_PATH} missing or invalid",
            {"error": latest_decisions_error, "path": str(DOCS_DECISIONS_INDEX_LATEST_PATH)},
        )
    else:
        latest_records = latest_decisions_index.get("records", []) if isinstance(latest_decisions_index, dict) and isinstance(latest_decisions_index.get("records"), list) else []
        current_records = decisions_index_current.get("records", []) if isinstance(decisions_index_current.get("records"), list) else []
        latest_hashes = {str(item.get("path")): item.get("sha256") for item in latest_records if isinstance(item, dict)}
        current_hashes = {str(item.get("path")): item.get("sha256") for item in current_records if isinstance(item, dict)}
        drift = [
            {"path": path, "latest": latest_hashes.get(path), "current": current_hash}
            for path, current_hash in current_hashes.items()
            if latest_hashes.get(path) != current_hash
        ]
        topology_validation_add(
            checks,
            "fail" if drift else "ok",
            "decisions_index_current",
            "generated decision index is current" if not drift else "generated decision index is stale",
            {"drift": drift, "path": str(DOCS_DECISIONS_INDEX_LATEST_PATH)},
        )

    mesh_validation = docs_agents_mesh_validate(strict=False, write_latest=False)
    mesh_summary = mesh_validation.get("summary", {}) if isinstance(mesh_validation.get("summary"), dict) else {}
    topology_validation_add(
        checks,
        "fail" if mesh_summary.get("fails") else ("warn" if mesh_summary.get("warnings") else "ok"),
        "agents_mesh_validate",
        f"docs agent mesh validate {mesh_summary.get('status')}",
        {
            "summary": mesh_summary,
            "latest": str(DOCS_AGENTS_MESH_VALIDATE_LATEST_PATH),
            "command": "abyss-machine docs mesh-validate --json",
        },
    )

    summary = validation_summary(checks)
    data: dict[str, Any] = {
        "schema": f"{SCHEMA_PREFIX}_docs_audit_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": summary["fails"] == 0 and (not strict or summary["warnings"] == 0),
        "strict": strict,
        "summary": summary,
        "checks": checks,
        "documents": records,
        "paths": docs_paths(),
        "recommendations": [
            "Keep /etc/abyss-machine/DOCS.md as the documentation contract, not as a command catalog.",
            "Keep /etc/abyss-machine/commands.md as the command catalog; avoid copying the full list into AGENTS.md or README.md.",
            "Keep /etc/abyss-machine/DESIGN.md and /etc/abyss-machine/DESIGN.AGENTS.md as source contracts for host form and agent-surface form.",
            "Keep /etc/abyss-machine/ROADMAP.md as host-wide direction, not as a task list or change history.",
            "Keep /etc/abyss-machine/decisions/ as rationale only; current source surfaces define what.",
            "Keep /etc/abyss-machine/CHANGELOG.md sparse; exact host history belongs in /var/lib/abyss-machine/changes/.",
            "Treat /var/lib/abyss-machine/*/AGENTS.md and index.json as generated entrypoints/facts, not replacement source truth.",
        ],
        "non_claims": [
            "This audit checks documentation topology and freshness signals; it does not prove every prose sentence is semantically current.",
            "Warnings identify review work; they do not mutate project repositories.",
        ],
    }
    if write_latest:
        errors = write_latest_and_history(data, DOCS_LATEST_PATH, DOCS_HISTORY_ROOT)
        index_error = safe_atomic_write_json(DOCS_INDEX_PATH, docs_index_document(data), 0o664)
        if index_error:
            errors.append(index_error)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def print_docs_audit_text(data: dict[str, Any]) -> None:
    summary = data.get("summary", {}) if isinstance(data.get("summary"), dict) else {}
    print(f"docs audit: {summary.get('status')} ({summary.get('fails')} fail, {summary.get('warnings')} warn, {summary.get('checks')} checks)")
    for item in data.get("checks", []):
        if item.get("level") != "ok":
            print(f"{item.get('level')}: {item.get('key')}: {item.get('message')}")
    print(f"contract: {DOCS_DOC_PATH}")
    print(f"latest: {DOCS_LATEST_PATH}")


def subsystem_validate(name: str, strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    specs = subsystem_specs()
    if name not in specs:
        return {
            "schema": f"{SCHEMA_PREFIX}_subsystem_validate_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": "unknown subsystem",
            "known": sorted(specs),
        }
    spec = specs[name]
    checks: list[dict[str, Any]] = []
    if name == "dictation":
        checks.extend(dictation_validation_checks())
    if name == "typing":
        typing_validation = typing_validate(strict=False, write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not typing_validation.get("ok") else "ok",
            "typing_safe_intake_validate",
            "typing safe committed-text intake validates"
            if typing_validation.get("ok")
            else "typing safe committed-text intake has validation issues",
            typing_validation.get("summary"),
        )
    if name == "processes":
        game_cases = process_game_classifier_regression_cases()
        bad_game_cases = [case for case in game_cases if not case.get("ok")]
        topology_validation_add(
            checks,
            "fail" if bad_game_cases else "ok",
            "game_guard_classifier_regressions",
            "game guard classifier keeps platform and generic Wine utility signals separate from active games"
            if not bad_game_cases
            else "game guard classifier regression cases failed",
            {"cases": game_cases, "failed": bad_game_cases},
        )
    if name == "resource":
        resource_cases = resource_gate_regression_cases()
        bad_resource_cases = [case for case in resource_cases if not case.get("ok")]
        topology_validation_add(
            checks,
            "fail" if bad_resource_cases else "ok",
            "resource_thermal_game_gate_regressions",
            "resource gate keeps 100-105C active range and stale game-guard thermal evidence correctly separated"
            if not bad_resource_cases
            else "resource thermal/game gate regression cases failed",
            {"cases": resource_cases, "failed": bad_resource_cases},
        )
    for path in spec.get("docs", []):
        validation_add_path_exists(checks, f"doc:{path}", Path(path), "file", required=True)
    for path in spec.get("dirs", []):
        validation_add_path_exists(checks, f"dir:{path}", Path(path), "dir", required=False)
    for path in spec.get("executables", []):
        validation_add_path_exists(checks, f"executable:{path}", Path(path), "executable", required=False)
    paths_data: dict[str, Any] | None = None
    try:
        paths_data = spec["paths"]()
        topology_validation_add(checks, "ok", "paths_function", f"{name} paths resolved", {"schema": paths_data.get("schema")})
    except Exception as exc:
        topology_validation_add(checks, "fail", "paths_function", f"{name} paths failed", {"error": repr(exc)})
    for key, path, expected_schema, required in spec.get("json", []):
        validation_json_file(checks, f"json:{key}", Path(path), expected_schema, required=required)
    for scope, unit, required in spec.get("timers", []):
        state = user_systemd_unit(unit) if scope == "user" else systemd_unit(unit)
        active_ok = bool(state.get("is_active")) or unit.endswith(".service")
        enabled_ok = bool(state.get("is_enabled")) or unit.endswith(".service")
        level = "ok" if active_ok and enabled_ok else ("fail" if required else "warn")
        topology_validation_add(
            checks,
            level,
            f"unit:{scope}:{unit}",
            f"{unit} {state.get('active')}/{state.get('enabled')}",
            state,
        )
    bridge = bridge_manifest()
    commands = bridge.get("commands", {}) if isinstance(bridge.get("commands"), dict) else {}
    missing_bridge = [key for key in spec.get("bridge_commands", []) if key not in commands]
    topology_validation_add(
        checks,
        "warn" if missing_bridge else "ok",
        "bridge_commands",
        "bridge exposes expected subsystem commands" if not missing_bridge else "bridge missing optional subsystem commands",
        {"missing": missing_bridge},
    )
    if name in {"storage", "ai"}:
        env_hits = {
            key: value for key, value in storage_cache_env_routes().items()
            if isinstance(value, str) and topology_under_forbidden_root(value)
        }
        topology_validation_add(
            checks,
            "fail" if env_hits else "ok",
            "storage_routes",
            "cache/runtime routes avoid work roots" if not env_hits else "cache/runtime routes use work roots",
            env_hits,
        )
    if name == "artifacts":
        artifact_validation = artifacts_validate(strict=False, write_latest=False)
        topology_validation_add(
            checks,
            "fail" if artifact_validation.get("summary", {}).get("fails") else "ok",
            "artifacts_evidence_validate",
            "artifact evidence subsystem validates"
            if not artifact_validation.get("summary", {}).get("fails")
            else "artifact evidence subsystem has validation failures",
            artifact_validation.get("summary"),
        )
    if name == "ai":
        roots = [Path(path) for path in ai_model_roots()]
        mutation_hits = [str(path) for path in roots if storage_path_protection(path).get("decision") != "deny"]
        topology_validation_add(
            checks,
            "warn" if mutation_hits else "ok",
            "ai_model_roots_readonly",
            "AI model roots are treated as protected/read-only by host validators",
            {"roots": [str(path) for path in roots], "not_protected": mutation_hits},
        )
        token_self_test = ai_token_accounting_self_test()
        topology_validation_add(
            checks,
            "fail" if not token_self_test.get("ok") else "ok",
            "ai_token_accounting_self_test",
            "AI token accounting bridge privacy/read-only self-test passes"
            if token_self_test.get("ok")
            else "AI token accounting bridge privacy/read-only self-test failed",
            token_self_test.get("summary"),
        )
    if name == "nervous":
        derived_refresh_status = nervous_derived_refresh_status()
        topology_validation_add(
            checks,
            "fail" if not derived_refresh_status.get("ok") else "ok",
            "nervous_derived_refresh",
            "passive chronicle triggers derived refresh"
            if derived_refresh_status.get("ok")
            else "passive chronicle derived-refresh contract is incomplete",
            derived_refresh_status,
        )
        snapshot = nervous_validate_snapshot()
        topology_validation_add(
            checks,
            "fail" if not snapshot.get("ok") else "ok",
            "nervous_snapshot_validate",
            "latest nervous passive snapshot validates" if snapshot.get("ok") else "latest nervous passive snapshot has validation issues",
            snapshot.get("summary"),
        )
        events_validation = nervous_events_validate(write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not events_validation.get("ok") else "ok",
            "nervous_events_validate",
            "nervous event layer validates" if events_validation.get("ok") else "nervous event layer validation issues",
            events_validation.get("summary"),
        )
        episodes_validation = nervous_episodes_validate(write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not episodes_validation.get("ok") else "ok",
            "nervous_episodes_validate",
            "nervous episode layer validates" if episodes_validation.get("ok") else "nervous episode layer validation issues",
            episodes_validation.get("summary"),
        )
        index_validation = nervous_index_validate(write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not index_validation.get("ok") else "ok",
            "nervous_index_validate",
            "nervous local index validates" if index_validation.get("ok") else "nervous local index validation issues",
            index_validation.get("summary"),
        )
        synthesis_validation = nervous_synthesis_validate(write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not synthesis_validation.get("ok") else "ok",
            "nervous_synthesis_validate",
            "nervous synthesis candidates validate" if synthesis_validation.get("ok") else "nervous synthesis validation issues",
            synthesis_validation.get("summary"),
        )
        eval_validation = nervous_eval_validate(write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not eval_validation.get("ok") else "ok",
            "nervous_eval_validate",
            "nervous eval gate validates" if eval_validation.get("ok") else "nervous eval validation issues",
            eval_validation.get("summary"),
        )
        retention_validation = nervous_retention_validate(write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not retention_validation.get("ok") else "ok",
            "nervous_retention_validate",
            "nervous retention policy validates" if retention_validation.get("ok") else "nervous retention validation issues",
            retention_validation.get("summary"),
        )
        browser_latest, browser_error = load_json_document(NERVOUS_BROWSER_CONTENT_LATEST_PATH)
        browser_web_context = nested_get(browser_latest or {}, ["summary", "web_context_quality"]) if isinstance(browser_latest, dict) else None
        topology_validation_add(
            checks,
            "ok" if isinstance(browser_web_context, dict) and browser_web_context.get("schema") == f"{SCHEMA_PREFIX}_nervous_web_context_summary_v1" else "warn",
            "nervous_browser_web_context_quality",
            "browser content latest exposes web context quality"
            if isinstance(browser_web_context, dict)
            else "browser content latest should be refreshed to expose web context quality",
            {"path": str(NERVOUS_BROWSER_CONTENT_LATEST_PATH), "error": browser_error, "web_context_quality": browser_web_context},
        )
        web_perf_latest, web_perf_error = load_json_document(NERVOUS_WEB_PERFORMANCE_LATEST_PATH)
        if isinstance(web_perf_latest, dict):
            web_perf_policy = web_perf_latest.get("policy") if isinstance(web_perf_latest.get("policy"), dict) else {}
            topology_validation_add(
                checks,
                "ok" if (
                    web_perf_latest.get("schema") == f"{SCHEMA_PREFIX}_nervous_web_performance_diagnostic_v1"
                    and web_perf_policy.get("does_not_start_browser") is True
                    and web_perf_policy.get("does_not_keep_persistent_cdp_or_bidi_session") is True
                    and web_perf_policy.get("raw_url_query_fragment_omitted") is True
                ) else "fail",
                "nervous_web_performance_diagnostic_policy",
                "web performance diagnostic latest is bounded and opt-in",
                {"path": str(NERVOUS_WEB_PERFORMANCE_LATEST_PATH), "policy": web_perf_policy},
            )
        else:
            topology_validation_add(
                checks,
                "ok",
                "nervous_web_performance_diagnostic_empty",
                "no persisted web performance diagnostic yet; route remains opt-in",
                {"path": str(NERVOUS_WEB_PERFORMANCE_LATEST_PATH), "error": web_perf_error},
            )
    if name == "stack-bridge":
        bridge_validation = stack_bridge_validate(write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not bridge_validation.get("ok") else "ok",
            "stack_bridge_validate",
            "stack bridge handoff validates" if bridge_validation.get("ok") else "stack bridge handoff validation issues",
            bridge_validation.get("summary"),
        )
    if name == "mode":
        mode_validation = mode_validate(write_latest=False)
        topology_validation_add(
            checks,
            "fail" if not mode_validation.get("ok") else "ok",
            "mode_validate",
            "work-mode contract validates" if mode_validation.get("ok") else "work-mode contract validation issues",
            mode_validation.get("summary"),
        )
    data = subsystem_validate_document_from_checks(
        name,
        checks,
        strict=strict,
        paths=paths_data,
        latest=spec.get("latest"),
    )
    if write_latest:
        if name == "dictation":
            errors = write_dictation_validation_latest(data)
        else:
            latest = Path(spec["latest"])
            history = Path(spec["history"])
            errors = write_latest_and_history(data, latest, history)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def subsystem_validate_all(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    results = {name: subsystem_validate(name, strict=strict, write_latest=write_latest) for name in subsystem_specs()}
    checks = [
        {
            "level": "fail" if result.get("summary", {}).get("fails") else "warn" if result.get("summary", {}).get("warnings") else "ok",
            "key": f"subsystem:{name}",
            "message": f"{name} validator {result.get('summary', {}).get('status')}",
            "data": result.get("summary"),
        }
        for name, result in results.items()
    ]
    return subsystems_validate_document_from_checks(
        checks,
        strict=strict,
        results=results,
    )


