def machine_graph(write_latest: bool = True) -> dict[str, Any]:
    bridge = bridge_manifest()
    topology = topology_status(write_latest=True)
    specs = subsystem_specs()
    nodes: list[dict[str, Any]] = [
        graph_node("machine", "root", "Abyss Machine host layer"),
        graph_node("bridge", "contract", "bridge manifest", path=str(MANIFEST_PATH), required=True),
        graph_node("topology", "subsystem", "topology", latest=str(TOPOLOGY_LATEST_PATH), validate=str(TOPOLOGY_VALIDATE_LATEST_PATH)),
        graph_node("changes", "subsystem", "change ledger", latest=str(CHANGE_LATEST_PATH), index=str(CHANGE_INDEX_PATH)),
    ]
    edges: list[dict[str, Any]] = [
        graph_edge("machine", "bridge", "publishes"),
        graph_edge("machine", "topology", "owns"),
        graph_edge("machine", "changes", "records"),
    ]
    for key, path in topology_paths().get("roots", {}).items():
        if isinstance(path, str):
            node_id = f"root:{key}"
            nodes.append(graph_node(node_id, "path", key, path=path, required=key in {"stable_config", "durable_facts", "large_machine_root"}))
            edges.append(graph_edge("machine", node_id, "has_root"))
    for name, spec in specs.items():
        nodes.append(graph_node(f"subsystem:{name}", "subsystem", name, latest=str(spec["latest"]), validate_command=f"abyss-machine {name if name not in {'processes'} else 'processes'} validate --json"))
        edges.append(graph_edge("machine", f"subsystem:{name}", "has_subsystem"))
        try:
            paths_data = spec["paths"]()
        except Exception as exc:
            paths_data = {"error": repr(exc)}
        nodes.append(graph_node(f"paths:{name}", "paths", f"{name} paths", data=paths_data))
        edges.append(graph_edge(f"subsystem:{name}", f"paths:{name}", "describes_paths"))
        for json_item in spec.get("json", []):
            key, path, schema, required = json_item
            node_id = f"json:{name}:{key}"
            nodes.append(graph_node(node_id, "json", key, path=str(path), schema=schema, required=bool(required)))
            edges.append(graph_edge(f"subsystem:{name}", node_id, "reads"))
    commands = bridge.get("commands", {}) if isinstance(bridge.get("commands"), dict) else {}
    for key, command in sorted(commands.items()):
        node_id = f"command:{key}"
        nodes.append(graph_node(node_id, "command", key, argv=command))
        edges.append(graph_edge("bridge", node_id, "exposes"))
    data = {
        "schema": f"{SCHEMA_PREFIX}_graph_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "root": str(GRAPH_ROOT),
        "latest": str(GRAPH_LATEST_PATH),
        "index": str(GRAPH_INDEX_PATH),
        "summary": {
            "nodes": len(nodes),
            "edges": len(edges),
            "subsystems": sorted(specs),
            "bridge_commands": len(commands),
        },
        "nodes": nodes,
        "edges": edges,
        "source_inputs": {
            "bridge": str(MANIFEST_PATH),
            "topology": str(TOPOLOGY_LATEST_PATH),
            "subsystem_paths": "generated from abyss-machine * paths functions",
        },
        "policy": {
            "generated": True,
            "do_not_hand_edit": True,
            "optional_nodes_allowed": True,
        },
    }
    if write_latest:
        latest_error = safe_atomic_write_json(GRAPH_LATEST_PATH, data, 0o664)
        daily_error = safe_append_jsonl(ai_daily_jsonl_path(GRAPH_ROOT), data, 0o664)
        index_error = safe_atomic_write_json(GRAPH_INDEX_PATH, graph_index_document(data), 0o664)
        errors = [error for error in (latest_error, daily_error, index_error) if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


