def graph_validate(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    graph = machine_graph(write_latest=write_latest)
    checks: list[dict[str, Any]] = []
    validation_json_file(checks, "json:graph_latest", GRAPH_LATEST_PATH, f"{SCHEMA_PREFIX}_graph_v1", required=True)
    validation_json_file(checks, "json:graph_index", GRAPH_INDEX_PATH, f"{SCHEMA_PREFIX}_graph_index_v1", required=True)
    node_ids = {str(item.get("id")) for item in graph.get("nodes", []) if isinstance(item, dict)}
    required_nodes = {"machine", "bridge", "topology", "changes", "subsystem:maps", "subsystem:stack-bridge", "subsystem:mode", "subsystem:storage", "subsystem:ai", "subsystem:cooling", "subsystem:processes", "subsystem:nervous", "subsystem:typing", "subsystem:dictation"}
    missing_nodes = sorted(required_nodes - node_ids)
    topology_validation_add(
        checks,
        "fail" if missing_nodes else "ok",
        "required_nodes",
        "required graph nodes present" if not missing_nodes else "required graph nodes missing",
        {"missing": missing_nodes},
    )
    missing_paths: list[dict[str, Any]] = []
    for item in graph.get("nodes", []):
        if not isinstance(item, dict) or "path" not in item:
            continue
        if item.get("required") and not Path(str(item["path"])).exists():
            missing_paths.append({"id": item.get("id"), "path": item.get("path")})
    topology_validation_add(
        checks,
        "fail" if missing_paths else "ok",
        "required_paths",
        "required graph paths exist" if not missing_paths else "required graph paths missing",
        {"missing": missing_paths},
    )
    protected_write_claims: list[dict[str, Any]] = []
    for item in graph.get("nodes", []):
        if not isinstance(item, dict) or "path" not in item:
            continue
        path = str(item.get("path"))
        protection = storage_path_protection(Path(path))
        if protection.get("decision") == "deny" and item.get("writable"):
            protected_write_claims.append({"id": item.get("id"), "path": path, "protection": protection})
    topology_validation_add(
        checks,
        "fail" if protected_write_claims else "ok",
        "protected_write_claims",
        "graph has no writable claims on protected roots",
        {"claims": protected_write_claims},
    )
    bridge = bridge_manifest()
    command_nodes = [item for item in graph.get("nodes", []) if isinstance(item, dict) and item.get("kind") == "command"]
    command_count = len(bridge.get("commands", {})) if isinstance(bridge.get("commands"), dict) else 0
    topology_validation_add(
        checks,
        "fail" if len(command_nodes) < command_count else "ok",
        "bridge_commands_represented",
        "bridge commands represented in graph" if len(command_nodes) >= command_count else "graph missing bridge command nodes",
        {"bridge_commands": command_count, "command_nodes": len(command_nodes)},
    )
    data = graph_validate_document_from_checks(
        checks,
        strict=strict,
        graph_summary=graph.get("summary") if isinstance(graph.get("summary"), dict) else None,
    )
    if write_latest:
        errors = write_latest_and_history(data, GRAPH_VALIDATE_LATEST_PATH, GRAPH_VALIDATE_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


