def write_rag_index(trace: dict[str, Any] | None = None, eval_doc: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    latest_trace, trace_error = load_json_document(RAG_TRACE_LATEST_PATH)
    latest_eval, eval_error = load_json_document(RAG_EVAL_LATEST_PATH)
    if trace is None and isinstance(latest_trace, dict):
        trace = latest_trace
    if eval_doc is None and isinstance(latest_eval, dict):
        eval_doc = latest_eval
    data = context_contracts.rag_index_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        rag_root=RAG_ROOT,
        rag_latest_path=RAG_LATEST_PATH,
        trace_latest_path=RAG_TRACE_LATEST_PATH,
        eval_latest_path=RAG_EVAL_LATEST_PATH,
        refresh_latest_path=RAG_REFRESH_LATEST_PATH,
        validate_latest_path=RAG_VALIDATE_LATEST_PATH,
        rag_doc_path=RAG_DOC_PATH,
        rag_policy_path=RAG_POLICY_PATH,
        trace=trace,
        trace_error=trace_error,
        eval_doc=eval_doc,
        eval_error=eval_error,
        commands=rag_paths()["commands"],
    )
    return [error for error in [safe_atomic_write_json(RAG_INDEX_PATH, data, 0o664)] if error]


def rag_status(write_latest: bool = True) -> dict[str, Any]:
    latest_trace, trace_error = load_json_document(RAG_TRACE_LATEST_PATH)
    latest_eval, eval_error = load_json_document(RAG_EVAL_LATEST_PATH)
    data = context_contracts.rag_status_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        paths=rag_paths(),
        latest_trace_exists=RAG_TRACE_LATEST_PATH.exists(),
        trace_error=trace_error,
        latest_trace=latest_trace,
        latest_eval_exists=RAG_EVAL_LATEST_PATH.exists(),
        eval_error=eval_error,
        latest_eval=latest_eval,
        policy=rag_policy_document(),
    )
    if write_latest:
        errors = [error for error in [
            safe_atomic_write_json(RAG_LATEST_PATH, data, 0o664),
            *write_rag_index(latest_trace if isinstance(latest_trace, dict) else None, latest_eval if isinstance(latest_eval, dict) else None),
        ] if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def rag_trace(
    query: str,
    *,
    axis: str | None = None,
    reader_profile: str | None = None,
    limit: int | None = None,
    evidence_limit: int | None = None,
    write_latest: bool = True,
) -> dict[str, Any]:
    policy = rag_policy_document()
    limits = policy.get("limits") if isinstance(policy.get("limits"), dict) else {}
    axis_id = axis or str(policy.get("default_axis") or "by-rag-run")
    profile = reader_profile or str(policy.get("default_reader_profile") or "retrieval-context")
    bounded_limit = max(1, min(safe_int(limit, safe_int(limits.get("packet_entries"), 8)), 50))
    bounded_evidence_limit = max(1, min(safe_int(evidence_limit, safe_int(limits.get("evidence_refs"), 12)), 40))
    query_text = (query or "").strip() or "machine RAG trace"
    packet = maps_packet(axis=axis_id, query=query_text, reader_profile=profile, limit=bounded_limit)
    query_fallback = False
    if not packet.get("entries") and query_text:
        packet = maps_packet(axis=axis_id, query=None, reader_profile=profile, limit=bounded_limit)
        query_fallback = True
    refs = packet.get("evidence_refs") if isinstance(packet.get("evidence_refs"), list) else []
    evidence_snapshots = [
        rag_evidence_snapshot(
            ref,
            max_json_bytes=safe_int(limits.get("json_file_max_bytes"), 262144),
            max_text_bytes=safe_int(limits.get("text_file_max_bytes"), 65536),
            max_text_chars=safe_int(limits.get("text_excerpt_chars"), 4000),
            max_dir_entries=safe_int(limits.get("directory_entries"), 24),
        )
        for ref in refs[:bounded_evidence_limit]
        if isinstance(ref, dict)
    ]
    answer = rag_answer_from_trace_seed(query_text, packet, evidence_snapshots)
    trace = context_contracts.rag_trace_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        query_text=query_text,
        axis_id=axis_id,
        profile=profile,
        packet=packet,
        evidence_snapshots=evidence_snapshots,
        answer=answer,
        policy=policy,
        rag_doc_path=RAG_DOC_PATH,
        rag_policy_path=RAG_POLICY_PATH,
        maps_doc_path=MAPS_DOC_PATH,
        query_fallback=query_fallback,
    )
    eval_doc = rag_eval_document(trace)
    trace["eval"] = {
        "schema": eval_doc.get("schema"),
        "ok": eval_doc.get("ok"),
        "summary": eval_doc.get("summary"),
        "score": eval_doc.get("score"),
    }
    if write_latest:
        errors = [error for error in [
            safe_atomic_write_json(RAG_TRACE_LATEST_PATH, trace, 0o664),
            safe_append_jsonl(ai_daily_jsonl_path(RAG_TRACE_ROOT), trace, 0o664),
            safe_atomic_write_json(RAG_EVAL_LATEST_PATH, eval_doc, 0o664),
            safe_append_jsonl(ai_daily_jsonl_path(RAG_EVAL_ROOT), eval_doc, 0o664),
            *write_rag_index(trace, eval_doc),
        ] if error]
        status = rag_status(write_latest=True)
        if not status.get("ok"):
            errors.extend(status.get("write_errors") or [])
        if errors:
            trace["ok"] = False
            trace["write_errors"] = errors
    return trace


def rag_eval(write_latest: bool = True) -> dict[str, Any]:
    trace, error = load_json_document(RAG_TRACE_LATEST_PATH)
    if not isinstance(trace, dict):
        data = rag_eval_missing_trace_document(error)
    else:
        data = rag_eval_document(trace)
    if write_latest:
        errors = [error for error in [
            safe_atomic_write_json(RAG_EVAL_LATEST_PATH, data, 0o664),
            safe_append_jsonl(ai_daily_jsonl_path(RAG_EVAL_ROOT), data, 0o664),
            *write_rag_index(trace if isinstance(trace, dict) else None, data),
        ] if error]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def rag_refresh(
    query: str = "scheduled machine context refresh",
    *,
    axis: str | None = None,
    reader_profile: str | None = None,
    limit: int | None = None,
    evidence_limit: int | None = None,
    write_latest: bool = True,
) -> dict[str, Any]:
    maps_doc = machine_maps(write_latest=True)
    maps_check = maps_validate(strict=False, write_latest=True)
    trace = rag_trace(
        query=query,
        axis=axis or "by-rag-run",
        reader_profile=reader_profile or "retrieval-context",
        limit=limit,
        evidence_limit=evidence_limit,
        write_latest=True,
    )
    rag_check = rag_validate(strict=False, write_latest=True)
    data = context_contracts.rag_refresh_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        query=query,
        axis=axis or "by-rag-run",
        reader_profile=reader_profile or "retrieval-context",
        maps_doc=maps_doc,
        maps_check=maps_check,
        trace=trace,
        rag_check=rag_check,
        maps_latest_path=MAPS_LATEST_PATH,
        maps_validate_latest_path=MAPS_VALIDATE_LATEST_PATH,
        rag_trace_latest_path=RAG_TRACE_LATEST_PATH,
        rag_eval_latest_path=RAG_EVAL_LATEST_PATH,
        rag_validate_latest_path=RAG_VALIDATE_LATEST_PATH,
        paths=rag_paths(),
    )
    if write_latest:
        errors = [error for error in [
            safe_atomic_write_json(RAG_REFRESH_LATEST_PATH, data, 0o664),
            safe_append_jsonl(ai_daily_jsonl_path(RAG_REFRESH_ROOT), data, 0o664),
            *write_rag_index(trace if isinstance(trace, dict) else None, None),
        ] if error]
        status = rag_status(write_latest=True)
        if not status.get("ok"):
            errors.extend(status.get("write_errors") or [])
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def rag_validate(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    validation_add_path_exists(checks, "doc:rag_contract", RAG_DOC_PATH, "file", required=True)
    validation_json_file(checks, "json:rag_policy_source", RAG_POLICY_PATH, f"{SCHEMA_PREFIX}_maps_policy_v1", required=True)
    validation_add_path_exists(checks, "doc:rag_agents", RAG_AGENTS_PATH, "file", required=True)
    validation_add_path_exists(checks, "unit:context_refresh_service", MAPS_SERVICE_PATH, "file", required=True)
    validation_add_path_exists(checks, "unit:context_refresh_timer", MAPS_TIMER_PATH, "file", required=True)
    timer_state = user_systemd_unit(MAPS_TIMER)
    topology_validation_add(
        checks,
        "ok" if timer_state.get("is_enabled") else "warn",
        "unit:context_refresh_timer_enabled",
        "context refresh timer is enabled" if timer_state.get("is_enabled") else "context refresh timer is not enabled",
        timer_state,
    )
    if not RAG_TRACE_LATEST_PATH.exists():
        sample = rag_trace("machine rag validation", axis="by-rag-run", reader_profile="retrieval-context", limit=4, evidence_limit=6, write_latest=True)
    else:
        sample, _ = load_json_document(RAG_TRACE_LATEST_PATH)
        if not isinstance(sample, dict):
            sample = rag_trace("machine rag validation", axis="by-rag-run", reader_profile="retrieval-context", limit=4, evidence_limit=6, write_latest=True)
    validation_add_path_exists(checks, "json:rag_trace_latest", RAG_TRACE_LATEST_PATH, "file", required=True)
    validation_json_file(checks, "json:rag_refresh_latest", RAG_REFRESH_LATEST_PATH, f"{SCHEMA_PREFIX}_rag_refresh_v1", required=False)
    eval_doc = rag_eval_document(sample if isinstance(sample, dict) else {})
    topology_validation_add(
        checks,
        "ok" if isinstance(sample, dict) and sample.get("schema") == f"{SCHEMA_PREFIX}_rag_trace_v1" else "fail",
        "trace_contract",
        "latest/sample RAG trace schema is current",
        {"schema": sample.get("schema") if isinstance(sample, dict) else None},
    )
    topology_validation_add(
        checks,
        "ok" if isinstance(sample, dict) and nested_get(sample, ["summary", "packet_entries"]) else "fail",
        "trace_packet_entries",
        "RAG trace has packet entries",
        {"packet_entries": nested_get(sample, ["summary", "packet_entries"]) if isinstance(sample, dict) else None},
    )
    topology_validation_add(
        checks,
        "ok" if isinstance(sample, dict) and nested_get(sample, ["summary", "evidence_opened"]) else "fail",
        "trace_evidence_opened",
        "RAG trace opens bounded evidence summaries",
        {"evidence_opened": nested_get(sample, ["summary", "evidence_opened"]) if isinstance(sample, dict) else None},
    )
    topology_validation_add(
        checks,
        "ok" if eval_doc.get("ok") else "fail",
        "trace_eval",
        "RAG eval passes trace quality gates",
        {"summary": eval_doc.get("summary")},
    )
    policy = rag_policy_document().get("policy")
    topology_validation_add(
        checks,
        "ok" if isinstance(policy, dict) and policy.get("automatic_action") is False and policy.get("memory_writeback") is False and policy.get("proof_verdict") is False else "fail",
        "non_mutating_policy",
        "RAG policy disables action, response, memory writeback, proof, and KAG publication",
        policy,
    )
    data = rag_validate_document_from_checks(
        checks,
        strict=strict,
        paths=rag_paths(),
        latest_trace=sample if isinstance(sample, dict) else None,
        latest_eval=eval_doc if isinstance(eval_doc, dict) else None,
    )
    if write_latest:
        errors = [error for error in [
            safe_atomic_write_json(RAG_EVAL_LATEST_PATH, eval_doc, 0o664),
            safe_append_jsonl(ai_daily_jsonl_path(RAG_EVAL_ROOT), eval_doc, 0o664),
            safe_atomic_write_json(RAG_VALIDATE_LATEST_PATH, data, 0o664),
            safe_append_jsonl(ai_daily_jsonl_path(RAG_VALIDATE_ROOT), data, 0o664),
            *write_rag_index(sample if isinstance(sample, dict) else None, eval_doc),
        ] if error]
        status = rag_status(write_latest=True)
        if not status.get("ok"):
            errors.extend(status.get("write_errors") or [])
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def change_paths(include_index: bool = True) -> dict[str, Any]:
    today = ai_daily_jsonl_path(CHANGE_HISTORY_ROOT)
    indexed_summary = None
    index_exists = None
    index_load_error = None
    if include_index:
        indexed, error = load_json_document(CHANGE_INDEX_PATH)
        index_exists = CHANGE_INDEX_PATH.exists()
        index_load_error = error
        if indexed:
            indexed_summary = indexed.get("summary")
    return changes_contracts.paths_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        change_root=CHANGE_ROOT,
        agents_path=CHANGE_AGENTS_PATH,
        index_path=CHANGE_INDEX_PATH,
        latest_path=CHANGE_LATEST_PATH,
        active_root=CHANGE_ACTIVE_ROOT,
        closed_root=CHANGE_CLOSED_ROOT,
        history_root=CHANGE_HISTORY_ROOT,
        history_today=today,
        include_index=include_index,
        index_exists=index_exists,
        index_load_error=index_load_error,
        indexed_summary=indexed_summary,
    )


def change_id_valid(change_id: str) -> bool:
    return changes_contracts.change_id_valid(change_id)


def change_record_dir(change_id: str) -> Path:
    if not change_id_valid(change_id):
        raise ValueError("change id must be 2..121 chars: letters, digits, dot, underscore or dash; no path separators")
    return CHANGE_ACTIVE_ROOT / change_id


def change_existing_dir(change_id: str) -> Path | None:
    if not change_id_valid(change_id):
        raise ValueError("change id must be 2..121 chars: letters, digits, dot, underscore or dash; no path separators")
    for root in (CHANGE_ACTIVE_ROOT, CHANGE_CLOSED_ROOT):
        candidate = root / change_id
        if candidate.exists():
            return candidate
    return None


def write_text_if_missing(path: Path, text: str, mode: int = 0o664) -> dict[str, Any] | None:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists():
            path.write_text(text, encoding="utf-8")
            try:
                os.chmod(path, mode)
            except PermissionError:
                pass
            try:
                os.chown(path, -1, grp.getgrnam(MODE_STATE_GROUP).gr_gid)
            except (KeyError, PermissionError):
                pass
        return None
    except OSError as exc:
        return {"path": str(path), "error": str(exc)}


CHANGE_DECISION_REVIEW_CHOICES = changes_contracts.CHANGE_DECISION_REVIEW_CHOICES


def normalize_decision_ref(decision_ref: str | None) -> str | None:
    return changes_contracts.normalize_decision_ref(decision_ref, decisions_root=DECISIONS_ROOT)


def decision_review_payload(
    decision_review: str | None,
    decision_ref: str | None = None,
    decision_reason: str | None = None,
) -> tuple[dict[str, Any] | None, list[str]]:
    ref = normalize_decision_ref(decision_ref)
    return changes_contracts.decision_review_payload(
        decision_review,
        decision_ref,
        decision_reason,
        decisions_root=DECISIONS_ROOT,
        reviewed_at=now_iso(),
        decision_ref_exists=Path(ref).exists() if ref else None,
    )


def decision_review_closeout_text(payload: dict[str, Any]) -> str:
    return changes_contracts.decision_review_closeout_text(payload)


def change_record_summary(path: Path) -> dict[str, Any]:
    data, error = load_json_document(path / "change.json")
    return changes_contracts.record_summary(path, data, error)


def changes_index(write_latest: bool = True) -> dict[str, Any]:
    active_items: list[dict[str, Any]] = []
    if CHANGE_ACTIVE_ROOT.exists():
        for item in sorted(CHANGE_ACTIVE_ROOT.iterdir(), key=lambda path: path.name):
            if item.is_dir():
                active_items.append(change_record_summary(item))
    closed_items: list[dict[str, Any]] = []
    if CHANGE_CLOSED_ROOT.exists():
        for item in sorted(CHANGE_CLOSED_ROOT.iterdir(), key=lambda path: path.name):
            if item.is_dir():
                closed_items.append(change_record_summary(item))
    latest, latest_error = load_json_document(CHANGE_LATEST_PATH)
    history_files = sorted(CHANGE_HISTORY_ROOT.glob("*/*/*.jsonl")) if CHANGE_HISTORY_ROOT.exists() else []
    history_lines = sum(count_file_lines(path) or 0 for path in history_files[-30:])
    data = changes_contracts.index_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        paths=change_paths(include_index=False),
        active_items=active_items,
        closed_items=closed_items,
        latest=latest,
        latest_error=latest_error,
        history_file_count=len(history_files),
        recent_history_lines=history_lines,
        latest_exists=CHANGE_LATEST_PATH.exists(),
    )
    if write_latest:
        error = safe_atomic_write_json(CHANGE_INDEX_PATH, data, 0o664)
        if error:
            data["ok"] = False
            data["write_errors"] = [error]
    return data


def changes_status(write_latest: bool = True) -> dict[str, Any]:
    data = changes_index(write_latest=write_latest)
    return changes_contracts.status_document(data, schema_prefix=SCHEMA_PREFIX)


def change_record(
    change_id: str,
    title: str,
    intent: str,
    surfaces: list[str],
    note: str | None = None,
    status_value: str = "active",
    write_latest: bool = True,
) -> dict[str, Any]:
    try:
        root = change_record_dir(change_id)
    except ValueError as exc:
        return {
            "schema": f"{SCHEMA_PREFIX}_change_record_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": str(exc),
        }
    root.mkdir(parents=True, exist_ok=True)
    path = root / "change.json"
    existing, _error = load_json_document(path)
    created_at = existing.get("created_at") if existing else now_iso()
    updated_at = now_iso()
    record = changes_contracts.record_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        change_id=change_id,
        title=title,
        intent=intent,
        surfaces=surfaces,
        status_value=status_value,
        created_at=created_at,
        updated_at=updated_at,
        root=root,
        project_readonly_roots=["/srv/AbyssOS", "/srv/abyss-stack", str(ABYSS_STACK_USER_SOURCE_ROOT)],
    )
    errors = [error for error in [safe_atomic_write_json(path, record, 0o664)] if error]
    errors.extend(
        error for error in [
            write_text_if_missing(root / "intent.md", f"# Intent\n\n{intent}\n"),
            write_text_if_missing(root / "validation.md", "# Validation\n\nRecord checks here when the host change is verified.\n"),
            write_text_if_missing(root / "rollback.md", "# Rollback\n\nRecord rollback or recovery route here when one exists.\n"),
            write_text_if_missing(root / "closeout.md", "# Closeout\n\nRecord final state, checks, and remaining risk here.\n"),
        ]
        if error
    )
    event = changes_contracts.event_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        change_id=change_id,
        event="recorded" if existing else "created",
        title=title,
        status=status_value,
        surfaces=surfaces,
        note=note,
    )
    errors.extend(
        error for error in [
            safe_append_jsonl(root / "actions.jsonl", event, 0o664),
            safe_append_jsonl(ai_daily_jsonl_path(CHANGE_HISTORY_ROOT), event, 0o664),
        ]
        if error
    )
    data = changes_contracts.record_result_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        ok=not errors,
        created=not bool(existing),
        record=record,
        event=event,
        paths=change_paths(include_index=False),
    )
    if write_latest:
        latest_error = safe_atomic_write_json(CHANGE_LATEST_PATH, data, 0o664)
        index = changes_index(write_latest=True)
        errors.extend(error for error in [latest_error] if error)
        data["index_summary"] = index.get("summary")
    if errors:
        data["ok"] = False
        data["write_errors"] = errors
    return data


def change_close(
    change_id: str,
    note: str | None = None,
    decision_review: str | None = None,
    decision_ref: str | None = None,
    decision_reason: str | None = None,
    write_latest: bool = True,
) -> dict[str, Any]:
    try:
        active_root = change_record_dir(change_id)
    except ValueError as exc:
        return {
            "schema": f"{SCHEMA_PREFIX}_change_close_result_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": str(exc),
        }
    closed_root = CHANGE_CLOSED_ROOT / change_id
    if not active_root.exists():
        existing = closed_root.exists()
        return {
            "schema": f"{SCHEMA_PREFIX}_change_close_result_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": "change is already closed" if existing else "active change not found",
            "active_path": str(active_root),
            "closed_path": str(closed_root),
        }
    if closed_root.exists():
        return {
            "schema": f"{SCHEMA_PREFIX}_change_close_result_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": "closed target already exists",
            "closed_path": str(closed_root),
        }
    record, error = load_json_document(active_root / "change.json")
    if not record:
        return {
            "schema": f"{SCHEMA_PREFIX}_change_close_result_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": error or "missing change.json",
            "active_path": str(active_root),
        }
    review_payload, review_issues = decision_review_payload(decision_review, decision_ref, decision_reason)
    if review_issues:
        return {
            "schema": f"{SCHEMA_PREFIX}_change_close_result_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": "decision review required before closing host change",
            "issues": review_issues,
            "active_path": str(active_root),
            "record": {
                "id": record.get("id"),
                "title": record.get("title"),
                "surfaces": record.get("surfaces", []),
            },
            "required": {
                "decision_review": sorted(CHANGE_DECISION_REVIEW_CHOICES),
                "examples": [
                    "abyss-machine changes close --id ID --decision-review added --decision-ref 0008-example.md --note TEXT --json",
                    "abyss-machine changes close --id ID --decision-review existing --decision-ref 0008-example.md --note TEXT --json",
                    "abyss-machine changes close --id ID --decision-review no-record-needed --decision-reason 'pure generated refresh' --note TEXT --json",
                ],
            },
        }
    closed_at = now_iso()
    record = dict(record)
    record["status"] = "closed"
    record["closed_at"] = closed_at
    record["updated_at"] = closed_at
    record["path"] = str(closed_root)
    record["decision_review"] = review_payload
    if isinstance(record.get("files"), dict):
        files = dict(record["files"])
        for key, value in list(files.items()):
            if isinstance(value, str):
                files[key] = value.replace(str(active_root), str(closed_root))
        record["files"] = files
    event = changes_contracts.event_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=closed_at,
        change_id=change_id,
        event="closed",
        title=record.get("title"),
        status="closed",
        surfaces=record.get("surfaces", []),
        note=note,
        decision_review=review_payload,
    )
    errors = [error for error in [
        safe_atomic_write_json(active_root / "change.json", record, 0o664),
        safe_append_text(active_root / "closeout.md", decision_review_closeout_text(review_payload or {}), 0o664),
        safe_append_jsonl(active_root / "actions.jsonl", event, 0o664),
        safe_append_jsonl(ai_daily_jsonl_path(CHANGE_HISTORY_ROOT), event, 0o664),
    ] if error]
    if errors:
        return {
            "schema": f"{SCHEMA_PREFIX}_change_close_result_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "record": record,
            "event": event,
            "write_errors": errors,
        }
    CHANGE_CLOSED_ROOT.mkdir(parents=True, exist_ok=True)
    try:
        active_root.replace(closed_root)
    except OSError as exc:
        return {
            "schema": f"{SCHEMA_PREFIX}_change_close_result_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "record": record,
            "event": event,
            "error": str(exc),
        }
    data = {
        "schema": f"{SCHEMA_PREFIX}_change_close_result_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "ok": True,
        "record": record,
        "event": event,
        "closed_path": str(closed_root),
        "paths": change_paths(include_index=False),
    }
    if write_latest:
        latest_error = safe_atomic_write_json(CHANGE_LATEST_PATH, data, 0o664)
        index = changes_index(write_latest=True)
        if latest_error:
            data["ok"] = False
            data["write_errors"] = [latest_error]
        data["index_summary"] = index.get("summary")
    return data


def changes_latest() -> dict[str, Any]:
    data, error = load_json_document(CHANGE_LATEST_PATH)
