def snapshots_status() -> dict[str, Any]:
    root_config = Path("/etc/snapper/configs/root")
    data: dict[str, Any] = {
        "schema": f"{SCHEMA_PREFIX}_snapshots_v1",
        "version": VERSION,
        "generated_at": now_iso(),
        "snapper_available": command_exists("snapper"),
        "btrfs_assistant_available": command_exists("btrfs-assistant"),
        "root_config_exists": root_config.exists(),
        "root_snapshot_path": "/.snapshots",
        "root_snapshot_path_exists": Path("/.snapshots").exists(),
        "root_subvolume": "/",
        "srv_included": False,
        "home_included": True,
        "notes": [
            "/ is mounted from Btrfs subvolid=5, so this is snapshot coverage, not guaranteed boot-menu rollback.",
            "/home is not a separate mount or subvolume here, so root snapshots can retain home changes.",
            "/srv is a separate ext4 mount and is not covered by root Btrfs snapshots.",
        ],
        "timers": {
            "cleanup": systemd_unit("snapper-cleanup.timer"),
            "timeline": systemd_unit("snapper-timeline.timer"),
            "boot": systemd_unit("snapper-boot.timer"),
        },
    }

    if data["snapper_available"]:
        config = run(["snapper", "-c", "root", "get-config"], timeout=3.0)
        data["root_config_readable"] = config["ok"]

        listed = run(["snapper", "-c", "root", "--jsonout", "list"], timeout=5.0)
        data["list_ok"] = listed["ok"]
        if listed["ok"] and listed["stdout"]:
            try:
                parsed = json.loads(listed["stdout"])
                snapshots = parsed.get("root", [])
                data["count"] = len([item for item in snapshots if item.get("number") != 0])
                data["snapshots"] = snapshots
            except json.JSONDecodeError:
                data["list_error"] = "invalid snapper json"
        elif listed["stderr"]:
            data["list_error"] = listed["stderr"]

    return data


