def observability_paths() -> dict[str, Any]:
    today = dt.datetime.now(dt.timezone.utc).astimezone()
    year = f"{today.year:04d}"
    month = f"{today.month:02d}"
    date_name = today.strftime("%Y-%m-%d")
    return observability_contracts.paths_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        refs=observability_refs(),
        year=year,
        month=month,
        date_name=date_name,
    )


def count_file_lines(path: Path, max_bytes: int = 4_000_000) -> int | None:
    if not path.exists() or not path.is_file():
        return None
    try:
        if path.stat().st_size > max_bytes:
            out = run(["wc", "-l", str(path)], timeout=2.0)
            if out["ok"] and out["stdout"]:
                return int(out["stdout"].split()[0])
            return None
        with path.open("rb") as handle:
            return sum(1 for _ in handle)
    except (OSError, ValueError):
        return None


def parse_time(value: Any) -> dt.datetime | None:
    if not value:
        return None
    try:
        parsed = dt.datetime.fromisoformat(str(value))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=dt.datetime.now().astimezone().tzinfo)
    return parsed


def observability_latest() -> dict[str, Any]:
    latest_path = OBSERVABILITY_ROOT / "thermal-battery" / "latest.json"
    data, error = load_json_document(latest_path)
    return observability_contracts.latest_read_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        path=str(latest_path),
        data=data,
        error=error,
    )


def observability_manual_collect_probe(paths: dict[str, Any] | None = None) -> dict[str, Any]:
    paths = paths if isinstance(paths, dict) else observability_paths()
    thermal_paths = paths.get("thermal_battery") if isinstance(paths.get("thermal_battery"), dict) else {}
    summary_path = Path(str(thermal_paths.get("today_summary") or OBSERVABILITY_ROOT / "thermal-battery" / "summaries"))
    output_dirs = {
        "samples": Path(str(thermal_paths.get("today_samples") or OBSERVABILITY_ROOT / "thermal-battery" / "samples")).parent,
        "events": Path(str(thermal_paths.get("today_events") or OBSERVABILITY_ROOT / "thermal-battery" / "events")).parent,
        "summary": summary_path.parent,
        "latest": Path(str(thermal_paths.get("latest") or OBSERVABILITY_ROOT / "thermal-battery" / "latest.json")).parent,
        "state": Path(str(thermal_paths.get("state") or OBSERVABILITY_ROOT / "thermal-battery" / "state.json")).parent,
    }
    groups = {safe_int(os.getgid(), -1), *[safe_int(group, -1) for group in os.getgroups()]}
    directory_rows = []
    missing_or_unwritable = []
    for name, directory in output_dirs.items():
        row: dict[str, Any] = {"name": name, "path": str(directory), "exists": directory.exists()}
        try:
            stat_result = directory.stat()
            mode = stat_result.st_mode & 0o7777
            group_write = bool(mode & 0o020)
            owner_write = bool(mode & 0o200)
            other_write = bool(mode & 0o002)
            effective_write = os.access(directory, os.W_OK)
            row.update({
                "mode": oct(mode),
                "uid": stat_result.st_uid,
                "gid": stat_result.st_gid,
                "group": grp.getgrgid(stat_result.st_gid).gr_name,
                "current_user_is_owner": stat_result.st_uid == os.geteuid(),
                "current_user_in_group": stat_result.st_gid in groups,
                "owner_write": owner_write,
                "group_write": group_write,
                "other_write": other_write,
                "effective_write": effective_write,
            })
            if not effective_write:
                missing_or_unwritable.append(name)
        except (OSError, KeyError) as exc:
            row["error"] = str(exc)
            missing_or_unwritable.append(name)
        directory_rows.append(row)
    return observability_contracts.manual_collect_probe_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        collector=str(OBSERVABILITY_COLLECTOR),
        collector_exists=OBSERVABILITY_COLLECTOR.exists(),
        current_euid=os.geteuid(),
        current_egid=os.getegid(),
        current_groups=sorted(groups),
        missing_or_unwritable=missing_or_unwritable,
        directories=directory_rows,
    )


def observability_status() -> dict[str, Any]:
    paths = observability_paths()
    latest = observability_latest()
    manual_collect = observability_manual_collect_probe(paths)
    latest_at = parse_time(latest.get("updated_at")) if latest.get("ok", True) else None
    latest_age_sec = None
    if latest_at is not None:
        latest_age_sec = round((dt.datetime.now(dt.timezone.utc).astimezone() - latest_at).total_seconds(), 1)
    today_samples = Path(paths["thermal_battery"]["today_samples"])
    today_events = Path(paths["thermal_battery"]["today_events"])
    today_summary = Path(paths["thermal_battery"]["today_summary"])
    return observability_contracts.status_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        root_exists=OBSERVABILITY_ROOT.exists(),
        agent_entrypoint_exists=OBSERVABILITY_AGENTS_PATH.exists(),
        index_exists=OBSERVABILITY_INDEX_PATH.exists(),
        config_exists=OBSERVABILITY_CONFIG_PATH.exists(),
        collector_exists=OBSERVABILITY_COLLECTOR.exists(),
        timer=systemd_unit(OBSERVABILITY_TIMER),
        service=systemd_unit(OBSERVABILITY_SERVICE),
        manual_collect=manual_collect,
        paths=paths,
        latest=latest,
        latest_age_sec=latest_age_sec,
        today={
            "samples_path": str(today_samples),
            "events_path": str(today_events),
            "summary_path": str(today_summary),
            "samples": count_file_lines(today_samples),
            "events": count_file_lines(today_events),
            "summary_exists": today_summary.exists(),
        },
    )


def observability_recent_samples(limit: int = 12) -> list[dict[str, Any]]:
    paths = observability_paths()
    sample_path = Path(paths["thermal_battery"]["today_samples"])
    if not sample_path.exists():
        return []
    try:
        lines = sample_path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return []
    samples: list[dict[str, Any]] = []
    for line in lines[-max(1, int(limit)):]:
        try:
            item = json.loads(line)
        except json.JSONDecodeError:
            continue
        if isinstance(item, dict):
            samples.append(item)
    return samples


def observability_sample_temperature(sample: dict[str, Any]) -> float | None:
    return observability_contracts.sample_temperature(sample)


def observability_sample_time(sample: dict[str, Any]) -> dt.datetime | None:
    return parse_time(sample.get("generated_at"))


def ai_thermal_policy_snapshot(latest: dict[str, Any], thresholds: dict[str, Any]) -> dict[str, Any]:
    trend_min_delta = float(thresholds.get("falling_trend_min_c", 3.0))
    latest_sample = latest.get("sample") if isinstance(latest.get("sample"), dict) else {}
    direct = sensors_summary()
    direct_current = direct.get("temperature_c_max")
    direct_current_float = float(direct_current) if isinstance(direct_current, (int, float)) else None
    window = thermal_episode_observability_window(
        latest_sample,
        thresholds,
        direct_current=direct_current_float,
        direct_source="direct_sysfs_hwmon",
    )
    temps = [float(item["temperature_c_max"]) for item in window if isinstance(item.get("temperature_c_max"), (int, float))]
    current = temps[-1] if temps else None
    if current is None:
        current = observability_sample_temperature(latest_sample) if latest_sample else None
    if current is None and temps:
        current = temps[-1]
    if current is None and isinstance(direct_current, (int, float)):
        current = float(direct_current)

    rolling_avg = round(sum(temps) / len(temps), 1) if temps else (round(float(current), 1) if isinstance(current, (int, float)) else None)
    recent_peak = round(max(temps), 1) if temps else (round(float(current), 1) if isinstance(current, (int, float)) else None)
    trend = "unknown"
    delta = None
    if len(temps) >= 2:
        delta = round(temps[-1] - temps[0], 1)
        if delta <= -trend_min_delta:
            trend = "falling"
        elif delta >= trend_min_delta:
            trend = "rising"
        else:
            trend = "stable"

    hottest = nested_get(latest_sample, ["thermal", "sensors", "hottest"])
    episode = thermal_episode_classification(
        window,
        thresholds=thresholds,
        trend=trend,
        rolling_avg=rolling_avg,
        recent_peak=recent_peak,
        current=current,
        direct_current=direct_current_float,
        source="ai_policy",
    )
    return {
        "current_temperature_c": round(float(current), 1) if isinstance(current, (int, float)) else None,
        "rolling_avg_temperature_c": rolling_avg,
        "recent_peak_temperature_c": recent_peak,
        "trend": trend,
        "trend_delta_c": delta,
        "window_sec": float(thresholds.get("rolling_window_sec", 180)),
        "samples": window,
        "episode": episode,
        "latest_hottest_sensors": hottest if isinstance(hottest, list) else [],
        "direct_current": direct,
        "basis": "latest observability sample plus rolling window with fresh direct sysfs sample; direct sensors may raise or lower current classification when they differ from periodic telemetry",
    }


def observability_collect() -> dict[str, Any]:
    if not OBSERVABILITY_COLLECTOR.exists():
        return {
            "schema": f"{SCHEMA_PREFIX}_observability_collect_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": f"collector missing: {OBSERVABILITY_COLLECTOR}",
        }
    out = run([str(OBSERVABILITY_COLLECTOR), "--once", "--json"], timeout=10.0)
    if not out["ok"]:
        manual_collect = observability_manual_collect_probe()
        return {
            "schema": f"{SCHEMA_PREFIX}_observability_collect_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "status": manual_collect.get("status") if "PermissionError" in (out["stderr"] or out["stdout"]) else "collector_failed",
            "error": out["stderr"] or out["stdout"],
            "returncode": out["returncode"],
            "manual_collect": manual_collect,
            "latest": observability_latest(),
        }
    try:
        data = json.loads(out["stdout"])
    except json.JSONDecodeError:
        return {
            "schema": f"{SCHEMA_PREFIX}_observability_collect_v1",
            "version": VERSION,
            "generated_at": now_iso(),
            "ok": False,
            "error": "collector returned invalid JSON",
            "stdout_tail": out["stdout"][-1000:],
        }
    return data


