def mode_plan(write_latest: bool = True) -> dict[str, Any]:
    state = load_mode_state()
    inputs = mode_adapters.collect_plan_inputs(
        state=state,
        battery_summary=battery_summary,
        target_profile=mode_target_profile,
        profile_policy=mode_profile_policy,
        power_profile=power_profile,
        current_mode_from_power_profile=current_mode_from_power_profile,
        external_profile_guard=mode_external_power_profile_guard,
        cooling_recommend=lambda: cooling_recommend(write_latest=False),
        cooling_profile_targets=cooling_profile_targets,
        thermal_class_from_summary=mode_thermal_class_from_summary,
        cpu_thermal_map=lambda write_latest_value: ai_cpu_thermal_map(write_latest=write_latest_value),
        cpu_routed_heavy_policy=ai_cpu_routed_heavy_policy,
        load_json_document=load_json_document,
        storage_pressure_path=STORAGE_PRESSURE_LATEST_PATH,
        memory_plan_path=MEMORY_PLAN_LATEST_PATH,
        process_latest_path=PROCESS_LATEST_PATH,
        write_latest=write_latest,
    )
    data = mode_contracts.plan_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        selected=inputs["selected"],
        effective=inputs["effective"],
        state_file=str(MODE_STATE_FILE),
        policy_path=str(MODE_POLICY_PATH),
        profile=inputs["profile"],
        target_profile_name=inputs["target_profile_name"],
        current_profile=inputs["current_profile"],
        current_mode=inputs["current_mode"],
        external_profile_guard=inputs["external_profile_guard"],
        cooling=inputs["cooling"],
        cooling_normalized=inputs["cooling_normalized"],
        cooling_target=inputs["cooling_target"],
        temperature=inputs["temperature"],
        thermal_class=inputs["thermal_class"],
        battery=inputs["battery"],
        cpu_routed_heavy=inputs["cpu_routed_heavy"],
        degraded_reason=inputs["degraded_reason"],
        storage_pressure_latest=inputs["storage_pressure_latest"],
        memory_plan_latest=inputs["memory_plan_latest"],
        process_latest=inputs["process_latest"],
        policy=mode_policy_document(),
    )
    if write_latest:
        errors = [
            error for error in [
                safe_atomic_write_json(MODE_PLAN_LATEST_PATH, data, 0o664),
                safe_append_jsonl(ai_daily_jsonl_path(MODE_PLAN_ROOT), data, 0o664),
                safe_atomic_write_json(MODE_INDEX_PATH, mode_index_document(data), 0o664),
            ]
            if error
        ]
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def mode_status(write_latest: bool = True) -> dict[str, Any]:
    state = load_mode_state()
    inputs = mode_adapters.collect_status_inputs(
        state=state,
        battery_summary=battery_summary,
        target_profile=mode_target_profile,
        power_profile=power_profile,
        external_profile_guard=mode_external_power_profile_guard,
        ai_devices=ai_devices,
        sensors_summary=sensors_summary,
        mode_plan=lambda: mode_plan(write_latest=False),
    )

    data = mode_contracts.status_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        refs=mode_refs(),
        state=state,
        selected=inputs["selected"],
        effective=inputs["effective"],
        target_profile_name=inputs["target_profile_name"],
        current_profile=inputs["current_profile"],
        external_profile_guard=inputs["external_profile_guard"],
        degraded_reason=inputs["degraded_reason"],
        battery=inputs["battery"],
        sensors=inputs["sensors"],
        ai_ready=inputs["ai_ready"],
        ai=inputs["ai"],
        plan=inputs["plan"],
    )
    if write_latest:
        errors = [
            error for error in [
                safe_atomic_write_json(MODE_LATEST_PATH, data, 0o664),
                safe_atomic_write_json(MODE_INDEX_PATH, mode_index_document(data), 0o664),
            ]
            if error
        ]
        if errors:
            data["write_errors"] = errors
    return data


