def heartbeat_parse_user_jobs(text: str) -> list[dict[str, Any]]:
    return runtime_evidence_contracts.parse_user_jobs(text)


def heartbeat_user_jobs() -> dict[str, Any]:
    out = run(["systemctl", "--user", "list-jobs", "--all", "--no-pager"], timeout=2.0)
    jobs = heartbeat_parse_user_jobs(out.get("stdout", ""))
    heartbeat_jobs = [job for job in jobs if job.get("unit") in {HEARTBEAT_SERVICE, HEARTBEAT_TIMER}]
    return {
        "ok": bool(out.get("ok")),
        "returncode": out.get("returncode"),
        "error": out.get("stderr") or None,
        "jobs": jobs,
        "heartbeat_jobs": heartbeat_jobs,
        "waiting_heartbeat_jobs": [job for job in heartbeat_jobs if job.get("state") == "waiting"],
    }


def heartbeat_parse_timer_line(line: str) -> dict[str, Any]:
    return runtime_evidence_contracts.parse_timer_line(line, heartbeat_timer=HEARTBEAT_TIMER)


def heartbeat_timer_list_status() -> dict[str, Any]:
    out = run(["systemctl", "--user", "list-timers", HEARTBEAT_TIMER, "--all", "--no-pager"], timeout=2.0)
    lines = [line.strip() for line in str(out.get("stdout") or "").splitlines() if line.strip()]
    data: dict[str, Any] = {
        "ok": bool(out.get("ok")),
        "returncode": out.get("returncode"),
        "error": out.get("stderr") or None,
        "raw": out.get("stdout"),
        "next_beat_at": None,
        "left": None,
        "last_trigger": None,
        "passed": None,
    }
    for line in lines:
        if HEARTBEAT_TIMER not in line or line.startswith("NEXT "):
            continue
        data.update(heartbeat_parse_timer_line(line))
        break
    return data


