def heartbeat_compact_e2b_candidate(candidate: dict[str, Any]) -> dict[str, Any]:
    payload = candidate.get("payload") if isinstance(candidate.get("payload"), dict) else {}
    compact_payload: dict[str, Any] = {}
    for key in ("class", "classification", "allowed_use", "issue_type", "usefulness", "follow_up", "verdict", "next_action", "source_refs_missing"):
        if key in payload:
            compact_payload[key] = payload.get(key)
    source_ids = [
        str(item)
        for item in heartbeat_as_list(candidate.get("source_ids"))
        if str(item or "").strip()
    ][:6]
    return {
        "candidate_id": candidate.get("candidate_id"),
        "kind": candidate.get("kind"),
        "source_job": candidate.get("source_job"),
        "source_ids": source_ids,
        "title": str(candidate.get("title") or "")[:180],
        "route": candidate.get("route"),
        "risk": candidate.get("risk"),
        "review_required": bool(candidate.get("review_required")),
        "utility_score": safe_float(candidate.get("utility_score"), 0.0),
        "selection_score": safe_float(candidate.get("selection_score"), 0.0),
        "selection_tier": candidate.get("selection_tier"),
        "selection_lane": candidate.get("selection_lane"),
        "selection_reasons": heartbeat_as_list(candidate.get("selection_reasons"))[:8],
        "correctness_risk": candidate.get("correctness_risk"),
        "freshness_class": candidate.get("freshness_class"),
        "heartbeat_priority": safe_int(candidate.get("heartbeat_priority"), 0),
        "e4b_review_eligible": bool(candidate.get("e4b_review_eligible")),
        "source_generated_at": candidate.get("source_generated_at"),
        "source_age_sec": safe_float(candidate.get("source_age_sec")),
        "artifact_age_sec": safe_float(candidate.get("artifact_age_sec")),
        "expires_at": candidate.get("expires_at"),
        "payload": compact_payload,
    }


def heartbeat_e2b_previous_candidates(previous_latest: dict[str, Any] | None) -> dict[str, dict[str, Any]]:
    previous_current = nested_get(previous_latest or {}, ["e2b_breath", "candidate_delta", "current"])
    if not isinstance(previous_current, list):
        return {}
    return {
        str(item.get("candidate_id")): item
        for item in previous_current
        if isinstance(item, dict) and item.get("candidate_id")
    }


def heartbeat_e2b_staleness(candidates: list[dict[str, Any]], source_jobs: dict[str, dict[str, Any]]) -> dict[str, Any]:
    heartbeat_candidates = [
        item
        for item in candidates
        if safe_int(item.get("heartbeat_priority"), 0) > 0 and item.get("freshness_class") != "stale"
    ]
    model_backed = []
    for candidate in heartbeat_candidates:
        source_job = str(candidate.get("source_job") or "")
        job = source_jobs.get(source_job, {})
        model = job.get("model") if isinstance(job.get("model"), dict) else {}
        if model.get("used") is True:
            model_backed.append(candidate)
    def age_for(item: dict[str, Any]) -> float:
        age = safe_float(item.get("artifact_age_sec"))
        if age is None:
            age = heartbeat_age_seconds(item.get("source_generated_at"))
        return age if isinstance(age, (int, float)) else 999999999.0
    latest = min(model_backed, key=age_for) if model_backed else None
    latest_age = age_for(latest) if latest else None
    status = "missing"
    if isinstance(latest_age, (int, float)):
        status = "fresh" if latest_age <= 3600 else "aging" if latest_age <= 21600 else "stale"
    return {
        "status": status,
        "latest_model_backed_candidate_age_sec": round(latest_age, 1) if isinstance(latest_age, (int, float)) else None,
        "latest_model_backed_candidate": heartbeat_compact_e2b_candidate(latest) if latest else None,
        "model_backed_heartbeat_candidates": len(model_backed),
        "heartbeat_candidates": len(heartbeat_candidates),
    }


def heartbeat_e2b_degradation(
    *,
    policy_latest: dict[str, Any],
    evals_latest: dict[str, Any],
    source_jobs: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    degraded_statuses = {"ok_degraded", "ok_fallback", "ok_gate_fallback", "ok_deterministic_fallback", "ok_compact_fallback", "skipped", "error"}
    historical_jobs: list[dict[str, Any]] = []
    degraded_from_evals = nested_get(evals_latest, ["scorecard", "degraded_jobs"])
    if isinstance(degraded_from_evals, list):
        for row in degraded_from_evals:
            if not isinstance(row, dict):
                continue
            model = row.get("model") if isinstance(row.get("model"), dict) else {}
            policy = model.get("policy") if isinstance(model.get("policy"), dict) else model.get("gate", {}).get("policy") if isinstance(model.get("gate"), dict) else {}
            historical_jobs.append({
                "job": row.get("job"),
                "status": row.get("status"),
                "policy_decision": policy.get("decision") if isinstance(policy, dict) else None,
                "primary_reason": policy.get("primary_reason") if isinstance(policy, dict) else None,
                "model_used": model.get("used"),
                "fallback_used": model.get("fallback_used"),
            })
    if not historical_jobs:
        for job_name, job in source_jobs.items():
            status = str(job.get("status") or "")
            if status not in degraded_statuses:
                continue
            model = job.get("model") if isinstance(job.get("model"), dict) else {}
            model_policy = model.get("policy") if isinstance(model.get("policy"), dict) else {}
            historical_jobs.append({
                "job": job_name,
                "status": status,
                "policy_decision": model.get("policy_decision") or model_policy.get("decision"),
                "primary_reason": model.get("policy_reason") or model_policy.get("primary_reason"),
                "model_used": model.get("used"),
                "fallback_used": model.get("fallback_used"),
            })
    decision = str(policy_latest.get("decision") or "unknown")
    current_active = decision in {"degraded", "fallback", "blocked"}
    current = {
        "decision": decision,
        "primary_reason": policy_latest.get("primary_reason"),
        "generated_at": policy_latest.get("generated_at"),
        "age_sec": heartbeat_age_seconds(policy_latest.get("generated_at")),
        "request": policy_latest.get("request") if isinstance(policy_latest.get("request"), dict) else {},
        "warnings": heartbeat_as_list(policy_latest.get("warnings"))[:8],
        "thermal_class": nested_get(policy_latest, ["temperatures", "thermal_class"]),
        "package_temp_c": nested_get(policy_latest, ["temperatures", "package_temp_c"]),
        "memory_class": nested_get(policy_latest, ["inputs", "memory", "summary", "class"]),
        "active_game_processes": nested_get(policy_latest, ["inputs", "game_guard", "summary", "active_game_processes"]),
        "current_degradation": current_active,
    }
    if current_active:
        state = "current"
    elif historical_jobs:
        state = "historical_not_current"
    else:
        state = "none"
    return {
        "status": state,
        "current": current,
        "historical_jobs": historical_jobs[:12],
        "counts_by_status": heartbeat_count_by(historical_jobs, "status"),
        "reason": current.get("primary_reason") if current_active else ("historical_degraded_artifacts" if historical_jobs else "none"),
    }


def heartbeat_e2b_breath_from(
    *,
    candidates_latest: dict[str, Any],
    evals_latest: dict[str, Any],
    evals_validate: dict[str, Any],
    policy_latest: dict[str, Any],
    previous_latest: dict[str, Any] | None,
    rhythm: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    candidates = [
        item for item in heartbeat_as_list(candidates_latest.get("candidates"))
        if isinstance(item, dict)
    ]
    queues = candidates_latest.get("queues") if isinstance(candidates_latest.get("queues"), dict) else {}
    selected_for_heartbeat = [
        item for item in heartbeat_as_list(queues.get("selected_for_heartbeat"))
        if isinstance(item, dict)
    ]
    selected_for_e4b = [
        item for item in heartbeat_as_list(queues.get("selected_for_e4b_review"))
        if isinstance(item, dict)
    ]
    source_jobs_list = [
        item for item in heartbeat_as_list(candidates_latest.get("source_jobs"))
        if isinstance(item, dict) and item.get("job")
    ]
    source_jobs = {str(item.get("job")): item for item in source_jobs_list}
    all_heartbeat_candidates = [
        item for item in candidates
        if safe_int(item.get("heartbeat_priority"), 0) > 0
    ]
    heartbeat_candidates = selected_for_heartbeat or all_heartbeat_candidates
    current = [heartbeat_compact_e2b_candidate(item) for item in heartbeat_candidates]
    current_by_id = {
        str(item.get("candidate_id")): item
        for item in current
        if item.get("candidate_id")
    }
    previous_by_id = heartbeat_e2b_previous_candidates(previous_latest)
    new_ids = sorted(set(current_by_id) - set(previous_by_id))
    cleared_ids = sorted(set(previous_by_id) - set(current_by_id))
    persistent_ids = sorted(set(current_by_id) & set(previous_by_id))
    escalated = []
    deescalated = []
    for candidate_id in persistent_ids:
        current_item = current_by_id[candidate_id]
        previous_item = previous_by_id[candidate_id]
        current_priority = safe_int(current_item.get("heartbeat_priority"), 0)
        previous_priority = safe_int(previous_item.get("heartbeat_priority"), 0)
        if current_priority > previous_priority:
            escalated.append(current_item)
        elif current_priority < previous_priority:
            deescalated.append(current_item)
    stale_or_expired = []
    now_dt = heartbeat_parse_iso(generated_at)
    for item in candidates:
        expires_at = heartbeat_parse_iso(item.get("expires_at"))
        if item.get("freshness_class") == "stale" or (now_dt is not None and expires_at is not None and expires_at < now_dt):
            stale_or_expired.append(heartbeat_compact_e2b_candidate(item))
    broad_review_candidates = [
        item
        for item in candidates
        if item.get("review_required") is True or item.get("kind") == "action_card" or item.get("risk") not in {"none", "low"}
    ]
    review_source = selected_for_e4b or broad_review_candidates
    review_candidates = [heartbeat_compact_e2b_candidate(item) for item in review_source]
    if not selected_for_e4b:
        review_candidates = sorted(
            review_candidates,
            key=lambda item: (
                -(safe_float(item.get("selection_score"), 0.0) or 0.0),
                -safe_int(item.get("heartbeat_priority"), 0),
                -(safe_float(item.get("utility_score"), 0.0) or 0.0),
                str(item.get("candidate_id") or ""),
            ),
        )
    resident_quality = {
        "ok": bool(evals_latest.get("ok")) and bool(evals_validate.get("ok")),
        "status": evals_latest.get("status"),
        "generated_at": evals_latest.get("generated_at"),
        "age_sec": heartbeat_age_seconds(evals_latest.get("generated_at")),
        "validate_generated_at": evals_validate.get("generated_at"),
        "validate_age_sec": heartbeat_age_seconds(evals_validate.get("generated_at")),
        "overall_score": nested_get(evals_latest, ["summary", "overall_score"]),
        "families": nested_get(evals_latest, ["summary", "families"]) if isinstance(nested_get(evals_latest, ["summary", "families"]), dict) else {},
        "checks": nested_get(evals_latest, ["summary", "checks"]),
        "fails": nested_get(evals_latest, ["summary", "fails"]),
        "warnings": nested_get(evals_latest, ["summary", "warnings"]),
        "source_id_pass_ratio": nested_get(evals_latest, ["summary", "source_id_pass_ratio"]),
        "average_candidate_utility": nested_get(evals_latest, ["summary", "average_candidate_utility"]),
        "average_candidate_selection": nested_get(evals_latest, ["summary", "average_candidate_selection"]),
        "selected_candidates": nested_get(evals_latest, ["summary", "selected_candidates"]),
        "selected_for_heartbeat": nested_get(evals_latest, ["summary", "selected_for_heartbeat"]),
        "selected_for_e4b_review": nested_get(evals_latest, ["summary", "selected_for_e4b_review"]),
        "validate_summary": evals_validate.get("summary") if isinstance(evals_validate.get("summary"), dict) else {},
    }
    degradation_reason = heartbeat_e2b_degradation(
        policy_latest=policy_latest,
        evals_latest=evals_latest,
        source_jobs=source_jobs,
    )
    e2b_staleness = heartbeat_e2b_staleness(candidates, source_jobs)
    candidate_delta = {
        "schema": f"{SCHEMA_PREFIX}_heartbeat_e2b_candidate_delta_v1",
        "current": current,
        "new": [current_by_id[item] for item in new_ids[:24]],
        "cleared": [previous_by_id[item] for item in cleared_ids[:24]],
        "persistent": [current_by_id[item] for item in persistent_ids[:24]],
        "escalated": escalated[:12],
        "deescalated": deescalated[:12],
        "stale_or_expired": stale_or_expired[:24],
        "summary": {
            "current": len(current),
            "new": len(new_ids),
            "cleared": len(cleared_ids),
            "persistent": len(persistent_ids),
            "escalated": len(escalated),
            "deescalated": len(deescalated),
            "stale_or_expired": len(stale_or_expired),
            "all_heartbeat_candidates": len(all_heartbeat_candidates),
            "selected_for_heartbeat": len(selected_for_heartbeat),
            "by_kind": heartbeat_count_by(current, "kind"),
            "by_source_job": heartbeat_count_by(current, "source_job"),
            "by_selection_lane": heartbeat_count_by(current, "selection_lane"),
        },
    }
    operator_attention = {
        "count": len(review_candidates),
        "total_review_candidates": len(broad_review_candidates),
        "risk_count": len([item for item in review_candidates if item.get("risk") not in {"none", "low"}]),
        "action_cards": len([item for item in review_candidates if item.get("kind") == "action_card"]),
        "e4b_review_candidates": len([item for item in candidates if item.get("e4b_review_eligible") is True]),
        "selected_for_e4b_review": len(selected_for_e4b),
        "selection_schema": nested_get(candidates_latest, ["selection", "schema"]),
        "top": review_candidates[:12],
    }
    state_flags = {
        "blocked": not resident_quality["ok"] or candidates_latest.get("ok") is False or degradation_reason.get("status") == "current" and nested_get(degradation_reason, ["current", "decision"]) == "fallback",
        "degraded_current": degradation_reason.get("status") == "current",
        "degraded_historical": degradation_reason.get("status") == "historical_not_current",
        "review_needed": operator_attention["count"] > 0,
        "useful": len(current) > 0 and resident_quality.get("ok") is True,
        "stale": len(stale_or_expired) > 0 or e2b_staleness.get("status") == "stale",
    }
    if state_flags["blocked"]:
        pulse_state = "blocked"
    elif state_flags["degraded_current"]:
        pulse_state = "degraded"
    elif state_flags["review_needed"]:
        pulse_state = "review_needed"
    elif state_flags["useful"]:
        pulse_state = "useful"
    elif state_flags["stale"]:
        pulse_state = "observing"
    else:
        pulse_state = "quiet"
    what_changed = []
    for key in ("new", "cleared", "escalated", "deescalated", "stale_or_expired"):
        count = safe_int(candidate_delta["summary"].get(key), 0)
        if count:
            what_changed.append(f"{key}:{count}")
    if not what_changed:
        what_changed.append("candidate_surface_stable")
    if state_flags["degraded_current"]:
        what_changed.append(f"current_degradation:{nested_get(degradation_reason, ['current', 'decision'])}:{degradation_reason.get('reason')}")
    elif state_flags["degraded_historical"]:
        what_changed.append(f"historical_degraded_jobs:{len(degradation_reason.get('historical_jobs') or [])}")
    why_now = ["heartbeat_timer_pulse"]
    if operator_attention["count"]:
        why_now.append(f"operator_attention:{operator_attention['count']}")
    if resident_quality.get("overall_score") is not None:
        why_now.append(f"resident_quality_score:{resident_quality.get('overall_score')}")
    if e2b_staleness.get("status"):
        why_now.append(f"e2b_staleness:{e2b_staleness.get('status')}")
    return {
        "schema": f"{SCHEMA_PREFIX}_heartbeat_e2b_breath_v1",
        "generated_at": generated_at,
        "ok": True,
        "pulse_state": pulse_state,
        "next_breath_at": rhythm.get("next_beat_at"),
        "why_now": why_now,
        "what_changed": what_changed,
        "candidate_delta": candidate_delta,
        "resident_quality": resident_quality,
        "degradation_reason": degradation_reason,
        "e2b_staleness": e2b_staleness,
        "operator_attention": operator_attention,
        "state_flags": state_flags,
        "sources": {
            "candidates_latest": {"path": str(AI_LLM_RESIDENT_CANDIDATES_LATEST_PATH), "generated_at": candidates_latest.get("generated_at"), "age_sec": heartbeat_age_seconds(candidates_latest.get("generated_at"))},
            "evals_latest": {"path": str(AI_LLM_RESIDENT_EVALS_LATEST_PATH), "generated_at": evals_latest.get("generated_at"), "age_sec": heartbeat_age_seconds(evals_latest.get("generated_at"))},
            "evals_validate": {"path": str(AI_LLM_RESIDENT_EVALS_VALIDATE_LATEST_PATH), "generated_at": evals_validate.get("generated_at"), "age_sec": heartbeat_age_seconds(evals_validate.get("generated_at"))},
            "policy_latest": {"path": str(AI_LLM_RESIDENT_ROOT / "policy" / "latest.json"), "generated_at": policy_latest.get("generated_at"), "age_sec": heartbeat_age_seconds(policy_latest.get("generated_at"))},
        },
        "policy": {
            "read_model": True,
            "facts_only": True,
            "reads_latest_only": True,
            "automatic_action": False,
            "action_execution": False,
            "executes_candidates": False,
            "does_not_run_model": True,
            "does_not_run_jobs_batch": True,
            "does_not_mutate_stack": True,
        },
    }


def heartbeat_float(value: Any, default: float | None = None) -> float | None:
    if isinstance(value, bool) or value is None:
        return default
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def heartbeat_psi_line_summary(data: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(data, dict):
        return {"exists": False, "some": {}, "full": {}}
    return {
        "path": data.get("path"),
        "exists": bool(data.get("exists")),
        "some": data.get("some") if isinstance(data.get("some"), dict) else {},
        "full": data.get("full") if isinstance(data.get("full"), dict) else {},
    }


def heartbeat_psi_snapshot() -> dict[str, Any]:
    return {
        "cpu": heartbeat_psi_line_summary(memory_parse_pressure_file(Path("/proc/pressure/cpu"))),
        "memory": heartbeat_psi_line_summary(memory_parse_pressure_file(Path("/proc/pressure/memory"))),
        "io": heartbeat_psi_line_summary(memory_parse_pressure_file(Path("/proc/pressure/io"))),
    }


def heartbeat_pressure_rank(memory_class: Any, psi: dict[str, Any]) -> tuple[int, list[str]]:
    rank = memory_class_rank(str(memory_class or "green"))
    reasons: list[str] = []
    memory_some = heartbeat_float(nested_get(psi, ["memory", "some", "avg10"]), 0.0)
    memory_full = heartbeat_float(nested_get(psi, ["memory", "full", "avg10"]), 0.0)
    io_some = heartbeat_float(nested_get(psi, ["io", "some", "avg10"]), 0.0)
    io_full = heartbeat_float(nested_get(psi, ["io", "full", "avg10"]), 0.0)
    cpu_some = heartbeat_float(nested_get(psi, ["cpu", "some", "avg10"]), 0.0)
    for value, target, reason in (
        (memory_full, "critical", "memory_psi_full_avg10_critical"),
        (memory_some, "hot", "memory_psi_some_avg10_hot"),
        (io_full, "hot", "io_psi_full_avg10_hot"),
        (io_some, "warm", "io_psi_some_avg10_warm"),
        (cpu_some, "warm", "cpu_psi_some_avg10_warm"),
    ):
        if not isinstance(value, (int, float)):
            continue
        threshold = {
            "memory_psi_full_avg10_critical": 8.0,
            "memory_psi_some_avg10_hot": 8.0,
            "io_psi_full_avg10_hot": 2.0,
            "io_psi_some_avg10_warm": 10.0,
            "cpu_psi_some_avg10_warm": 40.0,
        }[reason]
        if value > threshold and memory_class_rank(target) > rank:
            rank = memory_class_rank(target)
            reasons.append(f"{reason}={value}>{threshold}")
    return rank, reasons


def heartbeat_pressure_route(status: str, *, game_active: bool = False) -> str:
    if status == "critical":
        return "block"
    if status == "hot":
        return "defer"
    if status == "warm":
        return "defer" if game_active else "soften"
    if status == "watch":
        return "observe"
    return "allow"


def heartbeat_compact_cgroup_entries(items: Any, limit: int = 3) -> list[dict[str, Any]]:
    if not isinstance(items, list):
        return []
    compact: list[dict[str, Any]] = []
    for item in items[: max(0, int(limit))]:
        if not isinstance(item, dict):
            continue
        compact.append({
            "unit": item.get("unit"),
            "names": item.get("names"),
            "workload_hint": item.get("workload_hint"),
            "capability_role": item.get("capability_role"),
            "protected": item.get("protected"),
            "route": item.get("route"),
            "memory_current_mib": item.get("memory_current_mib"),
            "swap_current_mib": item.get("swap_current_mib"),
            "container_name": item.get("container_name"),
            "compose_service": item.get("compose_service"),
        })
    return compact


def heartbeat_pressure_context_from(
    *,
    memory_pressure: dict[str, Any],
    memory_plan: dict[str, Any],
    resource_orchestrator: dict[str, Any],
    game_guard: dict[str, Any],
    psi: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    memory_summary = memory_pressure.get("summary") if isinstance(memory_pressure.get("summary"), dict) else {}
    pressure_reasons = memory_pressure.get("reasons") if isinstance(memory_pressure.get("reasons"), list) else []
    memory_class = str(memory_pressure.get("class") or memory_summary.get("class") or "unknown")
    rank, psi_reasons = heartbeat_pressure_rank(memory_class, psi)
    status = memory_class_name(rank) if memory_class != "unknown" else ("watch" if psi_reasons else "unknown")
    game_active = bool(game_guard.get("active") or nested_get(resource_orchestrator, ["inputs", "game_guard", "active"]))
    route = heartbeat_pressure_route(status, game_active=game_active)
    swap_used_percent = heartbeat_float(memory_summary.get("swap_used_percent"), 0.0)
    memory_psi_some = heartbeat_float(nested_get(psi, ["memory", "some", "avg10"]), 0.0)
    memory_psi_full = heartbeat_float(nested_get(psi, ["memory", "full", "avg10"]), 0.0)
    occupied_swap_without_stall = (
        isinstance(swap_used_percent, (int, float))
        and swap_used_percent >= 35.0
        and isinstance(memory_psi_some, (int, float))
        and isinstance(memory_psi_full, (int, float))
        and memory_psi_some <= 0.2
        and memory_psi_full <= 0.05
    )
    psi_missing = [name for name, item in psi.items() if not bool(item.get("exists"))]
    resource_inputs = resource_orchestrator.get("inputs") if isinstance(resource_orchestrator.get("inputs"), dict) else {}
    thermal_input = resource_inputs.get("thermal") if isinstance(resource_inputs.get("thermal"), dict) else {}
    desktop = nested_get(thermal_input, ["desktop_compositor", "summary"])
    process_top = memory_pressure.get("processes") if isinstance(memory_pressure.get("processes"), dict) else {}
    process_top = process_top.get("top") if isinstance(process_top.get("top"), dict) else {}
    return {
        "schema": f"{SCHEMA_PREFIX}_heartbeat_pressure_context_v1",
        "generated_at": generated_at,
        "ok": bool(memory_pressure.get("ok", True)),
        "status": status,
        "route": route,
        "reasons": list(pressure_reasons) + psi_reasons,
        "psi": psi,
        "memory": {
            "class": memory_class,
            "mem_available_mib": memory_summary.get("mem_available_mib"),
            "mem_available_percent": memory_summary.get("mem_available_percent"),
            "swap_used_mib": memory_summary.get("swap_used_mib"),
            "swap_used_percent": memory_summary.get("swap_used_percent"),
            "swap_free_mib": nested_get(memory_pressure, ["status", "swap", "summary", "free_mib"]),
            "zram_data_mib": memory_summary.get("zram_data_mib"),
            "zram_resident_mib": memory_summary.get("zram_resident_mib"),
            "zram_logical_to_memory_ratio": memory_summary.get("zram_logical_to_memory_ratio"),
            "occupied_swap_without_stall": occupied_swap_without_stall,
        },
        "attribution": {
            "top_cgroup_memory": heartbeat_compact_cgroup_entries(process_top.get("cgroup_memory")),
            "top_cgroup_swap": heartbeat_compact_cgroup_entries(process_top.get("cgroup_swap")),
            "top_cgroup_memory_total_mib": memory_summary.get("top_cgroup_memory_total_mib"),
            "top_cgroup_swap_total_mib": memory_summary.get("top_cgroup_swap_total_mib"),
            "processes": memory_summary.get("processes"),
        },
        "resource": {
            "status": nested_get(resource_orchestrator, ["summary", "status"]) or resource_orchestrator.get("status"),
            "thermal_class": nested_get(thermal_input, ["thermal", "class"]),
            "thermal_episode_class": nested_get(thermal_input, ["thermal", "episode", "class"]),
            "game_active": game_active,
            "desktop_compositor": {
                "classification": desktop.get("classification") if isinstance(desktop, dict) else None,
                "cpu_avg_one_core_percent": desktop.get("cpu_avg_one_core_percent") if isinstance(desktop, dict) else None,
                "route_guidance": desktop.get("route_guidance") if isinstance(desktop, dict) else None,
            },
        },
        "sources": {
            "memory_pressure": {"path": str(MEMORY_PRESSURE_LATEST_PATH), "generated_at": memory_pressure.get("generated_at"), "age_sec": heartbeat_age_seconds(memory_pressure.get("generated_at"))},
            "memory_plan": {"path": str(MEMORY_PLAN_LATEST_PATH), "generated_at": memory_plan.get("generated_at"), "age_sec": heartbeat_age_seconds(memory_plan.get("generated_at"))},
            "resource_orchestrator": {"path": str(RESOURCE_ORCHESTRATOR_LATEST_PATH), "generated_at": resource_orchestrator.get("generated_at"), "age_sec": heartbeat_age_seconds(resource_orchestrator.get("generated_at"))},
            "processes_game_guard": {"path": str(PROCESS_GAME_GUARD_LATEST_PATH), "generated_at": game_guard.get("generated_at"), "age_sec": heartbeat_age_seconds(game_guard.get("generated_at"))},
        },
        "classification_evidence": {
            "memory_class_source": "memory_pressure_latest",
            "psi_source": "live_proc_pressure",
            "psi_citation": "cpu,memory,io /proc/pressure avg10/avg60/avg300 totals",
            "psi_absent_reason": "missing:" + ",".join(psi_missing) if psi_missing else None,
            "route_vocabulary": ["allow", "observe", "soften", "defer", "block"],
        },
        "policy": {
            "facts_only": True,
            "does_not_kill_or_throttle_processes": True,
            "does_not_mutate_cgroups": True,
            "does_not_start_resource_work": True,
        },
    }


def heartbeat_pressure_context(
    memory_pressure: dict[str, Any],
    memory_plan: dict[str, Any],
    resource_orchestrator: dict[str, Any],
    game_guard: dict[str, Any],
    generated_at: str,
) -> dict[str, Any]:
    return heartbeat_pressure_context_from(
        memory_pressure=memory_pressure,
        memory_plan=memory_plan,
        resource_orchestrator=resource_orchestrator,
        game_guard=game_guard,
        psi=heartbeat_psi_snapshot(),
        generated_at=generated_at,
    )


def heartbeat_capture_health_from(
    *,
    capture_status: dict[str, Any],
    retention_plan: dict[str, Any],
    privacy_status: dict[str, Any],
    typing_status_data: dict[str, Any] | None = None,
    generated_at: str,
) -> dict[str, Any]:
    latest = capture_status.get("latest") if isinstance(capture_status.get("latest"), dict) else {}
    latest_summary = latest.get("summary") if isinstance(latest.get("summary"), dict) else {}
    storage = capture_status.get("storage") if isinstance(capture_status.get("storage"), dict) else {}
    browser = capture_status.get("browser_content_latest") if isinstance(capture_status.get("browser_content_latest"), dict) else {}
    browser_summary = browser.get("summary") if isinstance(browser.get("summary"), dict) else {}
    typing_state = typing_status_data if isinstance(typing_status_data, dict) else {}
    typing_summary = typing_state.get("summary") if isinstance(typing_state.get("summary"), dict) else {}
    typing_policy = typing_state.get("policy") if isinstance(typing_state.get("policy"), dict) else {}
    typing_latest = typing_state.get("latest") if isinstance(typing_state.get("latest"), dict) else {}
    typing_coverage = typing_state.get("coverage") if isinstance(typing_state.get("coverage"), dict) else {}
    typing_process = typing_state.get("process") if isinstance(typing_state.get("process"), dict) else {}
    typing_awareness = typing_process.get("awareness") if isinstance(typing_process.get("awareness"), dict) else {}
    typing_coverage_summary = typing_coverage.get("summary") if isinstance(typing_coverage.get("summary"), dict) else {}
    typing_coverage_policy = typing_coverage.get("policy") if isinstance(typing_coverage.get("policy"), dict) else {}
    typing_causal = typing_latest.get("causal_context") if isinstance(typing_latest.get("causal_context"), dict) else {}
    typing_causal_where = typing_causal.get("where") if isinstance(typing_causal.get("where"), dict) else {}
    typing_causal_recipient = typing_causal.get("recipient") if isinstance(typing_causal.get("recipient"), dict) else {}
    typing_causal_task = typing_causal.get("task") if isinstance(typing_causal.get("task"), dict) else {}
    browser_web_context = browser_summary.get("web_context_quality") if isinstance(browser_summary.get("web_context_quality"), dict) else {}
    if not browser_web_context:
        browser_captures = browser.get("captures") if isinstance(browser.get("captures"), list) else []
        browser_web_context = nervous_browser_capture_web_context_summary(browser_captures)
    retention_summary = retention_plan.get("summary") if isinstance(retention_plan.get("summary"), dict) else {}
    route_errors = safe_int(retention_summary.get("route_errors"), 0)
    retention_candidates = safe_int(retention_summary.get("candidates"), 0)
    sensitive_skips = safe_int(latest_summary.get("skipped"), 0) + safe_int(browser_summary.get("skipped_text"), 0)
    if not capture_status.get("ok"):
        status = "watch"
    elif route_errors > 0:
        status = "watch"
    elif isinstance(typing_awareness.get("average_score"), (int, float)) and float(typing_awareness.get("average_score")) < 0.75:
        status = "watch"
    elif retention_candidates > 0:
        status = "attention"
    else:
        status = "ok"
    retention_route_active = retention_candidates > 0
    return {
        "schema": f"{SCHEMA_PREFIX}_heartbeat_capture_health_v1",
        "generated_at": generated_at,
        "ok": bool(capture_status.get("ok")),
        "status": status,
        "volume": {
            "facts": latest_summary.get("facts"),
            "facts_ok": latest_summary.get("facts_ok"),
            "facts_missing_or_failed": latest_summary.get("facts_missing_or_failed"),
            "screenshots_count": storage.get("screenshots_count"),
            "screenshots_mib": bytes_to_mib(storage.get("screenshots_bytes")),
            "browser_content_jsonl_files": storage.get("browser_content_jsonl_files"),
            "browser_content_mib": bytes_to_mib(storage.get("browser_content_bytes")),
            "typed_text_recent_records": typing_summary.get("recent_records"),
            "typed_text_by_status": typing_summary.get("by_status") if isinstance(typing_summary.get("by_status"), dict) else {},
            "typed_text_by_adapter": typing_coverage.get("by_adapter") if isinstance(typing_coverage.get("by_adapter"), dict) else {},
            "typed_text_by_capture_gate": typing_coverage.get("by_capture_gate_decision") if isinstance(typing_coverage.get("by_capture_gate_decision"), dict) else {},
            "private_root_mib": bytes_to_mib(storage.get("private_root_bytes")),
        },
        "privacy": {
            "global_pause": bool(privacy_status.get("global_pause")),
            "private_mode": bool(privacy_status.get("private_mode")),
            "sensitive_skips": sensitive_skips,
            "browser_skipped": bool(browser.get("skipped")),
            "browser_skip_reason": browser.get("skip_reason"),
            "browser_accessibility_ok": browser_summary.get("accessibility_ok"),
            "browser_accessibility_skipped": browser_summary.get("accessibility_skipped"),
            "browser_bidi_attempted": browser_summary.get("bidi_attempted"),
            "browser_bidi_ok": browser_summary.get("bidi_ok"),
            "typed_text_enabled": typing_policy.get("enabled"),
            "typed_text_raw_keylogging": typing_policy.get("raw_keylogging"),
            "typed_text_password_fields_captured": typing_policy.get("password_fields_captured"),
            "typed_text_capture_gate_network_access": typing_coverage_policy.get("capture_gate_network_access"),
            "typed_text_unknown_surfaces_text_capture": typing_coverage_policy.get("unknown_surfaces_text_capture"),
            "raw_private_content": False,
        },
        "quality": {
            "browser_text_records": browser_summary.get("text_records"),
            "browser_captures": browser_summary.get("captures"),
            "browser_errors": browser_summary.get("errors"),
            "typed_text_latest_status": typing_latest.get("status"),
            "typed_text_latest_adapter": typing_latest.get("source_adapter"),
            "typed_text_coverage_status": typing_coverage.get("status"),
            "typed_text_coverage_gaps": typing_coverage_summary.get("gaps"),
            "typed_text_dominant_adapter": typing_coverage_summary.get("dominant_adapter"),
            "typed_text_dominant_adapter_ratio": typing_coverage_summary.get("dominant_ratio"),
            "typed_text_missing_capture_gate_records": typing_coverage_summary.get("missing_capture_gate_records"),
            "typed_text_latest_recipient": typing_causal_recipient.get("kind"),
            "typed_text_latest_project": nested_get(typing_causal_where, ["project", "id"]),
            "typed_text_latest_task_binding": typing_causal_task.get("binding"),
            "typed_text_latest_active_changes": len(typing_causal_task.get("active_changes") if isinstance(typing_causal_task.get("active_changes"), list) else []),
            "typed_text_causal_awareness_score": typing_awareness.get("average_score"),
            "typed_text_causal_awareness_by_state": typing_awareness.get("by_state") if isinstance(typing_awareness.get("by_state"), dict) else {},
            "typed_text_causal_awareness_top_gaps": typing_awareness.get("top_gaps") if isinstance(typing_awareness.get("top_gaps"), dict) else {},
            "typed_text_causal_awareness_axis_states": typing_awareness.get("axis_states") if isinstance(typing_awareness.get("axis_states"), dict) else {},
            "duplicate_ratio": browser_web_context.get("duplicate_ratio"),
            "low_signal_ratio": browser_web_context.get("low_signal_ratio"),
            "dedupe_note": "browser content capture deduplicates raw records before append; heartbeat does not scan raw JSONL bodies",
        },
        "web_context_quality": {
            "schema": f"{SCHEMA_PREFIX}_heartbeat_web_context_quality_v1",
            "captures": browser_web_context.get("captures", 0),
            "classes": browser_web_context.get("classes") if isinstance(browser_web_context.get("classes"), dict) else {},
            "attention_priorities": browser_web_context.get("attention_priorities") if isinstance(browser_web_context.get("attention_priorities"), dict) else {},
            "duplicate_ratio": browser_web_context.get("duplicate_ratio"),
            "low_signal_ratio": browser_web_context.get("low_signal_ratio"),
            "usable_count": browser_web_context.get("usable_count"),
            "sensitive_skips": browser_web_context.get("sensitive_skips"),
            "policy": {
                "raw_url_query_fragment_omitted": True,
                "sensitive_skips_are_expected_health_signal": True,
                "background_tabs_deprioritized": True,
                "does_not_open_browser_or_cdp": True,
            },
        },
        "retention": {
            "latest_path": str(NERVOUS_RETENTION_LATEST_PATH),
            "generated_at": retention_plan.get("generated_at"),
            "age_sec": heartbeat_age_seconds(retention_plan.get("generated_at")),
            "files": retention_summary.get("files"),
            "total_mib": bytes_to_mib(retention_summary.get("bytes")),
            "candidates": retention_candidates,
            "candidate_mib": bytes_to_mib(retention_summary.get("candidate_bytes")),
            "route_errors": route_errors,
            "facts_delete_behavior": nested_get(retention_plan, ["policy", "facts_delete_behavior"]),
            "default_apply": nested_get(retention_plan, ["policy", "default_apply"]),
        },
        "owner_gated_routes": [
            {
                "id": "nervous-retention-dry-run",
                "active": retention_route_active,
                "command": "abyss-machine nervous retention-apply --dry-run --json",
                "requires_owner_gate": True,
                "automatic": False,
                "executes_from_heartbeat": False,
                "reason": "retention candidates exist" if retention_route_active else "no retention candidates",
            }
        ],
        "sources": {
            "capture_latest": {"path": str(NERVOUS_CAPTURE_LATEST_PATH), "generated_at": latest.get("generated_at"), "age_sec": heartbeat_age_seconds(latest.get("generated_at")), "error": capture_status.get("latest_error")},
            "browser_content_latest": {"path": str(NERVOUS_BROWSER_CONTENT_LATEST_PATH), "generated_at": browser.get("generated_at"), "age_sec": heartbeat_age_seconds(browser.get("generated_at")), "error": capture_status.get("browser_content_latest_error")},
            "typing_latest": {"path": str(TYPING_EVENTS_LATEST_PATH), "generated_at": typing_latest.get("generated_at"), "age_sec": heartbeat_age_seconds(typing_latest.get("generated_at")), "error": None if typing_latest.get("ok") else typing_latest.get("error")},
            "retention_latest": {"path": str(NERVOUS_RETENTION_LATEST_PATH), "generated_at": retention_plan.get("generated_at"), "age_sec": heartbeat_age_seconds(retention_plan.get("generated_at"))},
        },
        "policy": {
            "facts_only": True,
            "does_not_scan_raw_content": True,
            "does_not_delete_or_forget": True,
            "cleanup_requires_owner_gate": True,
            "sensitive_skips_are_expected_health_signal": True,
        },
    }


