def heartbeat_self_awareness_breath(previous_latest: dict[str, Any] | None, generated_at: str) -> dict[str, Any]:
    autolink = load_latest_json(SELF_AWARENESS_AUTOLINK_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_autolink_v1")
    working_stack = load_latest_json(SELF_AWARENESS_WORKING_STACK_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_working_stack_inventory_v1")
    coverage_audit = load_latest_json(SELF_AWARENESS_COVERAGE_AUDIT_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_objective_coverage_audit_v1")
    stack_closure_dossier = load_latest_json(SELF_AWARENESS_STACK_CLOSURE_DOSSIER_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_stack_closure_dossier_v1")
    activation_smoke = load_latest_json(SELF_AWARENESS_ACTIVATION_SMOKE_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_working_stack_activation_smoke_v1")
    link_integrity = coverage_audit.get("working_stack_link_integrity") if isinstance(coverage_audit.get("working_stack_link_integrity"), dict) else {}
    activation_entries = nested_get(stack_closure_dossier, ["working_stack_activation_dossier", "entries"])
    activation_entries = activation_entries if isinstance(activation_entries, list) else []
    autolink_age_sec = heartbeat_age_seconds(autolink.get("generated_at"))
    refresh_after_sec = HEARTBEAT_EXPECTED_INTERVAL_SEC * 2
    autolink_complete = self_awareness_autolink_complete(autolink)
    autolink_stale = bool(autolink_age_sec is None or autolink_age_sec > refresh_after_sec)
    prerequisites_complete = (
        working_stack.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_working_stack_inventory_v1"
        and self_awareness_working_stack_link_integrity_matrix_complete(link_integrity)
        and stack_closure_dossier.get("schema") == f"{SCHEMA_PREFIX}_self_awareness_stack_closure_dossier_v1"
        and not self_awareness_activation_smoke_needs_refresh(activation_smoke, activation_entries)
    )
    refreshed = False
    refresh_reason = None
    refresh_skipped_reason = None
    if (not autolink_complete or autolink_stale) and prerequisites_complete:
        refresh_reason = "autolink_incomplete" if not autolink_complete else "autolink_stale"
        autolink = self_awareness_autolink(
            write_latest=True,
            working_stack_doc=working_stack,
            coverage_audit_doc=coverage_audit,
            stack_closure_dossier_doc=stack_closure_dossier,
            activation_smoke_doc=activation_smoke,
        )
        refreshed = True
        autolink_age_sec = heartbeat_age_seconds(autolink.get("generated_at"))
        autolink_complete = self_awareness_autolink_complete(autolink)
        autolink_stale = bool(autolink_age_sec is None or autolink_age_sec > refresh_after_sec)
    elif not autolink_complete or autolink_stale:
        refresh_skipped_reason = "prerequisites_need_deep_refresh"

    summary = autolink.get("summary") if isinstance(autolink.get("summary"), dict) else {}
    state_delta = autolink.get("state_delta") if isinstance(autolink.get("state_delta"), dict) else {}
    previous_breath = nested_get(previous_latest or {}, ["self_awareness_breath"])
    previous_breath = previous_breath if isinstance(previous_breath, dict) else {}
    previous_heartbeat_digest = previous_breath.get("state_digest")
    current_digest = autolink.get("state_digest")
    open_potential_services = [
        str(row.get("service"))
        for row in (autolink.get("organ_links") if isinstance(autolink.get("organ_links"), list) else [])
        if isinstance(row, dict) and row.get("usage_gap") and row.get("service")
    ]
    open_requirement_ids = [
        str(row.get("requirement_id"))
        for row in (autolink.get("stack_requirement_links") if isinstance(autolink.get("stack_requirement_links"), list) else [])
        if isinstance(row, dict) and row.get("automatic_link_state") == "open_stack_blocker" and row.get("requirement_id")
    ]
    status = "linked" if autolink_complete and not autolink_stale else ("aging" if autolink_complete else "watch")
    return {
        "schema": f"{SCHEMA_PREFIX}_heartbeat_self_awareness_breath_v1",
        "generated_at": generated_at,
        "ok": bool(autolink_complete),
        "status": status,
        "autolink": {
            "path": str(SELF_AWARENESS_AUTOLINK_LATEST_PATH),
            "generated_at": autolink.get("generated_at"),
            "age_sec": autolink_age_sec,
            "complete": autolink_complete,
            "stale": autolink_stale,
            "refreshed": refreshed,
            "refresh_reason": refresh_reason,
            "refresh_skipped_reason": refresh_skipped_reason,
        },
        "state_digest": current_digest,
        "previous_heartbeat_state_digest": previous_heartbeat_digest,
        "state_changed_since_previous_heartbeat": bool(previous_heartbeat_digest and previous_heartbeat_digest != current_digest),
        "state_delta": {
            "previous_seen": state_delta.get("previous_seen"),
            "state_changed": state_delta.get("state_changed"),
            "added_services": state_delta.get("added_services") if isinstance(state_delta.get("added_services"), list) else [],
            "removed_services": state_delta.get("removed_services") if isinstance(state_delta.get("removed_services"), list) else [],
            "changed_services": state_delta.get("changed_services") if isinstance(state_delta.get("changed_services"), list) else [],
            "added_requirements": state_delta.get("added_requirements") if isinstance(state_delta.get("added_requirements"), list) else [],
            "removed_requirements": state_delta.get("removed_requirements") if isinstance(state_delta.get("removed_requirements"), list) else [],
            "changed_requirements": state_delta.get("changed_requirements") if isinstance(state_delta.get("changed_requirements"), list) else [],
            "open_stack_requirements_delta": state_delta.get("open_stack_requirements_delta"),
            "working_stack_usage_gaps_delta": state_delta.get("working_stack_usage_gaps_delta"),
        },
        "summary": {
            "organ_links": summary.get("organ_links"),
            "organ_links_complete": summary.get("organ_links_complete"),
            "stack_requirement_links": summary.get("stack_requirement_links"),
            "stack_requirement_links_complete": summary.get("stack_requirement_links_complete"),
            "working_stack_usage_gaps": summary.get("working_stack_usage_gaps"),
            "open_stack_requirements": summary.get("open_stack_requirements"),
            "synthetic_scenarios": summary.get("synthetic_scenarios"),
            "synthetic_scenarios_complete": summary.get("synthetic_scenarios_complete"),
            "open_potential_services": open_potential_services[:24],
            "open_stack_requirement_ids": open_requirement_ids[:24],
        },
        "evidence_refs": [
            {"path": str(SELF_AWARENESS_AUTOLINK_LATEST_PATH), "schema": autolink.get("schema")},
            {"path": str(SELF_AWARENESS_WORKING_STACK_LATEST_PATH), "schema": working_stack.get("schema")},
            {"path": str(SELF_AWARENESS_COVERAGE_AUDIT_LATEST_PATH), "schema": coverage_audit.get("schema")},
            {"path": str(SELF_AWARENESS_STACK_CLOSURE_DOSSIER_LATEST_PATH), "schema": stack_closure_dossier.get("schema")},
        ],
        "policy": {
            "facts_only": True,
            "read_model": True,
            "refreshes_autolink_only_when_prerequisites_complete": True,
            "does_not_run_cycle": True,
            "does_not_run_probe": True,
            "does_not_run_model": True,
            "action_execution": False,
            "automatic_action": False,
            "host_layer_mutates_stack": False,
            "writes_project_roots": False,
        },
    }


def heartbeat_pulse(write_latest: bool = True, refresh_reactions: bool = True) -> dict[str, Any]:
    previous_latest_raw, _previous_latest_error = load_json_document(HEARTBEATS_LATEST_PATH)
    previous_latest = previous_latest_raw if isinstance(previous_latest_raw, dict) else None
    generated_at = now_iso()
    nervous_brief = load_latest_json(NERVOUS_BRIEF_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_brief_v1")
    nervous_events = load_latest_json(NERVOUS_EVENTS_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_events_build_v1")
    doctor_latest = load_latest_json(DOCTOR_LATEST_PATH, f"{SCHEMA_PREFIX}_doctor_v1")
    machine_report = load_latest_json(DOCTOR_MACHINE_REPORT_LATEST_PATH, f"{SCHEMA_PREFIX}_doctor_machine_report_v1")
    resource_orch = load_latest_json(RESOURCE_ORCHESTRATOR_LATEST_PATH, f"{SCHEMA_PREFIX}_resource_orchestrator_v2_v1")
    memory_pressure_latest = load_latest_json(MEMORY_PRESSURE_LATEST_PATH, f"{SCHEMA_PREFIX}_memory_pressure_v1")
    memory_plan_latest = load_latest_json(MEMORY_PLAN_LATEST_PATH, f"{SCHEMA_PREFIX}_memory_plan_v1")
    game_guard_latest = load_latest_json(PROCESS_GAME_GUARD_LATEST_PATH, f"{SCHEMA_PREFIX}_process_game_guard_v1")
    capture_status = nervous_capture_status()
    capture_latest = capture_status.get("latest") if isinstance(capture_status.get("latest"), dict) else {}
    browser_content_latest = capture_status.get("browser_content_latest") if isinstance(capture_status.get("browser_content_latest"), dict) else {}
    typing_state = typing_status(write_latest=False)
    typing_latest = typing_state.get("latest") if isinstance(typing_state.get("latest"), dict) else {}
    typing_coverage_latest = typing_state.get("coverage") if isinstance(typing_state.get("coverage"), dict) else load_latest_json(TYPING_COVERAGE_LATEST_PATH, f"{SCHEMA_PREFIX}_typing_coverage_v1")
    typing_process_latest = typing_state.get("process") if isinstance(typing_state.get("process"), dict) else load_latest_json(TYPING_PROCESS_LATEST_PATH, f"{SCHEMA_PREFIX}_typing_process_v1")
    typing_nervous_refresh_latest = load_latest_json(TYPING_NERVOUS_REFRESH_LATEST_PATH, f"{SCHEMA_PREFIX}_typing_nervous_refresh_v1")
    retention_latest = load_latest_json(NERVOUS_RETENTION_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_retention_plan_v1")
    ai_llm_validate = load_latest_json(AI_LLM_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_ai_llm_validate_v1")
    ai_resident_candidates = load_latest_json(AI_LLM_RESIDENT_CANDIDATES_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_spark_resident_candidate_readmodel_v2")
    ai_resident_evals = load_latest_json(AI_LLM_RESIDENT_EVALS_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_spark_resident_heartbeat_evals_v1")
    ai_workhorse_validate = load_latest_json(AI_LLM_WORKHORSE_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_workhorse_harness_validate_v1")
    ai_workhorse_review = load_latest_json(AI_LLM_WORKHORSE_REVIEW_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_workhorse_harness_review_v1")
    ai_resident_candidates_validate = load_latest_json(AI_LLM_RESIDENT_CANDIDATES_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_spark_resident_candidates_validate_v1")
    ai_resident_evals_validate = load_latest_json(AI_LLM_RESIDENT_EVALS_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_spark_resident_heartbeat_evals_validate_v1")
    ai_resident_policy = load_latest_json(AI_LLM_RESIDENT_ROOT / "policy" / "latest.json", f"{SCHEMA_PREFIX}_gemma4_spark_resident_policy_v1")
    reactions = reaction_status(write_latest=True) if refresh_reactions else load_latest_json(REACTIONS_LATEST_PATH, f"{SCHEMA_PREFIX}_reactions_status_v1")
    responses = response_status(write_latest=True, reactions=reactions, refresh_reactions=False)
    changes = load_latest_json(CHANGE_INDEX_PATH, f"{SCHEMA_PREFIX}_changes_index_v1")
    self_awareness_breath = heartbeat_self_awareness_breath(previous_latest, generated_at)
    heartbeat_timer = user_systemd_unit(HEARTBEAT_TIMER)
    heartbeat_service = user_systemd_unit(HEARTBEAT_SERVICE)
    reaction_candidates = reactions.get("candidates") if isinstance(reactions.get("candidates"), list) else []
    reaction_ids = [str(item.get("id")) for item in reaction_candidates if isinstance(item, dict) and item.get("id")]
    response_routes = responses.get("routes") if isinstance(responses.get("routes"), list) else []
    readiness = nervous_brief.get("readiness") if isinstance(nervous_brief.get("readiness"), dict) else {}
    heartbeat_inputs = {
        "nervous_brief": heartbeat_input_ref("nervous_brief", NERVOUS_BRIEF_LATEST_PATH, nervous_brief, readiness.get("status")),
        "nervous_events": heartbeat_input_ref("nervous_events", NERVOUS_EVENTS_LATEST_PATH, nervous_events),
        "doctor": heartbeat_input_ref("doctor", DOCTOR_LATEST_PATH, doctor_latest),
        "doctor_machine_report": heartbeat_input_ref("doctor_machine_report", DOCTOR_MACHINE_REPORT_LATEST_PATH, machine_report),
        "resource_orchestrator": heartbeat_input_ref("resource_orchestrator", RESOURCE_ORCHESTRATOR_LATEST_PATH, resource_orch),
        "memory_pressure": heartbeat_input_ref("memory_pressure", MEMORY_PRESSURE_LATEST_PATH, memory_pressure_latest),
        "memory_plan": heartbeat_input_ref("memory_plan", MEMORY_PLAN_LATEST_PATH, memory_plan_latest),
        "processes_game_guard": heartbeat_input_ref("processes_game_guard", PROCESS_GAME_GUARD_LATEST_PATH, game_guard_latest),
        "nervous_capture": heartbeat_input_ref("nervous_capture", NERVOUS_CAPTURE_LATEST_PATH, capture_latest, nested_get(capture_latest, ["summary", "facts"])),
        "nervous_browser_content": heartbeat_input_ref("nervous_browser_content", NERVOUS_BROWSER_CONTENT_LATEST_PATH, browser_content_latest, nested_get(browser_content_latest, ["summary", "text_records"])),
        "typing": heartbeat_input_ref("typing", TYPING_EVENTS_LATEST_PATH, typing_latest, typing_latest.get("status")),
        "typing_coverage": heartbeat_input_ref("typing_coverage", TYPING_COVERAGE_LATEST_PATH, typing_coverage_latest, typing_coverage_latest.get("status")),
        "typing_process": heartbeat_input_ref("typing_process", TYPING_PROCESS_LATEST_PATH, typing_process_latest, typing_process_latest.get("status")),
        "typing_nervous_refresh": heartbeat_input_ref("typing_nervous_refresh", TYPING_NERVOUS_REFRESH_LATEST_PATH, typing_nervous_refresh_latest, nested_get(typing_nervous_refresh_latest, ["summary", "status"])),
        "nervous_retention": heartbeat_input_ref("nervous_retention", NERVOUS_RETENTION_LATEST_PATH, retention_latest, nested_get(retention_latest, ["summary", "candidates"])),
        "ai_llm_validate": heartbeat_input_ref("ai_llm_validate", AI_LLM_VALIDATE_LATEST_PATH, ai_llm_validate, nested_get(ai_llm_validate, ["summary", "fails"])),
        "ai_resident_candidates": heartbeat_input_ref("ai_resident_candidates", AI_LLM_RESIDENT_CANDIDATES_LATEST_PATH, ai_resident_candidates, nested_get(ai_resident_candidates, ["summary", "heartbeat_candidates"])),
        "ai_resident_evals": heartbeat_input_ref("ai_resident_evals", AI_LLM_RESIDENT_EVALS_LATEST_PATH, ai_resident_evals, nested_get(ai_resident_evals, ["summary", "overall_score"])),
        "ai_workhorse_validate": heartbeat_input_ref("ai_workhorse_validate", AI_LLM_WORKHORSE_VALIDATE_LATEST_PATH, ai_workhorse_validate, nested_get(ai_workhorse_validate, ["summary", "fails"])),
        "ai_workhorse_review": heartbeat_input_ref("ai_workhorse_review", AI_LLM_WORKHORSE_REVIEW_LATEST_PATH, ai_workhorse_review, nested_get(ai_workhorse_review, ["summary", "fails"])),
        "ai_resident_candidates_validate": heartbeat_input_ref("ai_resident_candidates_validate", AI_LLM_RESIDENT_CANDIDATES_VALIDATE_LATEST_PATH, ai_resident_candidates_validate, nested_get(ai_resident_candidates_validate, ["summary", "fails"])),
        "ai_resident_evals_validate": heartbeat_input_ref("ai_resident_evals_validate", AI_LLM_RESIDENT_EVALS_VALIDATE_LATEST_PATH, ai_resident_evals_validate, nested_get(ai_resident_evals_validate, ["summary", "fails"])),
        "self_awareness_autolink": {
            "name": "self_awareness_autolink",
            "path": str(SELF_AWARENESS_AUTOLINK_LATEST_PATH),
            "ok": bool(self_awareness_breath.get("ok")),
            "status": self_awareness_breath.get("status"),
            "generated_at": nested_get(self_awareness_breath, ["autolink", "generated_at"]),
            "age_sec": nested_get(self_awareness_breath, ["autolink", "age_sec"]),
            "error": nested_get(self_awareness_breath, ["autolink", "refresh_skipped_reason"]),
        },
        "reactions": heartbeat_input_ref("reactions", REACTIONS_LATEST_PATH, reactions),
        "responses": heartbeat_input_ref("responses", RESPONSES_LATEST_PATH, responses),
        "changes": heartbeat_input_ref("changes", CHANGE_INDEX_PATH, changes, nested_get(changes, ["summary", "active_records"])),
    }
    source_freshness = heartbeat_source_freshness(heartbeat_inputs, previous_latest)
    heartbeat_jobs = heartbeat_user_jobs()
    job_causality = heartbeat_systemd_job_causality(heartbeat_jobs)
    rhythm = heartbeat_rhythm(previous_latest, heartbeat_timer, heartbeat_jobs, generated_at)
    candidate_lifecycle = heartbeat_candidate_lifecycle(reaction_candidates, previous_latest, generated_at)
    pressure_context = heartbeat_pressure_context(memory_pressure_latest, memory_plan_latest, resource_orch, game_guard_latest, generated_at)
    capture_health = heartbeat_capture_health_from(
        capture_status=capture_status,
        retention_plan=retention_latest,
        privacy_status=nervous_effective_privacy(write_latest=False),
        typing_status_data=typing_state,
        generated_at=generated_at,
    )
    ai_hygiene = heartbeat_ai_hygiene(ai_llm_validate, ai_workhorse_validate, ai_workhorse_review, ai_resident_candidates_validate, ai_resident_evals_validate, generated_at)
    e2b_breath = heartbeat_e2b_breath_from(
        candidates_latest=ai_resident_candidates,
        evals_latest=ai_resident_evals,
        evals_validate=ai_resident_evals_validate,
        policy_latest=ai_resident_policy,
        previous_latest=previous_latest,
        rhythm=rhythm,
        generated_at=generated_at,
    )
    status_value = heartbeat_status_from(
        nervous_brief=nervous_brief,
        doctor_latest=doctor_latest,
        machine_report=machine_report,
        reactions=reactions,
        changes=changes,
    )
    status_value = heartbeat_promote_status(status_value, pressure_context, capture_health, ai_hygiene)
    data: dict[str, Any] = {
        "schema": f"{SCHEMA_PREFIX}_heartbeat_pulse_v1",
        "version": VERSION,
        "generated_at": generated_at,
        "ok": True,
        "status": status_value,
        "summary": {
            "status": status_value,
            "reaction_candidates": len(reaction_candidates),
            "reaction_status": nested_get(reactions, ["summary", "status"]) or reactions.get("status"),
            "response_status": nested_get(responses, ["summary", "status"]) or responses.get("status"),
            "automatic_actions": int(nested_get(reactions, ["summary", "automatic_actions"]) or 0),
            "response_routes": len(response_routes),
            "automatic_responses": int(nested_get(responses, ["summary", "automatic_responses"]) or 0),
            "nervous_readiness": readiness.get("status"),
            "doctor_status": nested_get(doctor_latest, ["summary", "status"]),
            "machine_report_status": machine_report.get("status"),
            "resource_status": nested_get(resource_orch, ["summary", "status"]),
            "active_changes": int(nested_get(changes, ["summary", "active_records"]) or 0),
            "timer_active": bool(heartbeat_timer.get("is_active")),
            "timer_enabled": bool(heartbeat_timer.get("is_enabled")),
            "source_freshness_status": nested_get(source_freshness, ["summary", "status"]),
            "stale_sources": len(nested_get(source_freshness, ["summary", "stale_sources"]) or []),
            "aging_sources": len(nested_get(source_freshness, ["summary", "aging_sources"]) or []),
            "rhythm_status": rhythm.get("status"),
            "missed_beats": rhythm.get("missed_beats"),
            "waiting_heartbeat_job": rhythm.get("waiting_heartbeat_job"),
            "candidate_persistent": nested_get(candidate_lifecycle, ["summary", "persistent"]),
            "candidate_resolved": nested_get(candidate_lifecycle, ["summary", "recently_resolved"]),
            "pressure_status": pressure_context.get("status"),
            "pressure_route": pressure_context.get("route"),
            "psi_memory_some_avg10": nested_get(pressure_context, ["psi", "memory", "some", "avg10"]),
            "psi_memory_full_avg10": nested_get(pressure_context, ["psi", "memory", "full", "avg10"]),
            "mem_available_mib": nested_get(pressure_context, ["memory", "mem_available_mib"]),
            "swap_free_mib": nested_get(pressure_context, ["memory", "swap_free_mib"]),
            "capture_health_status": capture_health.get("status"),
            "capture_private_root_mib": nested_get(capture_health, ["volume", "private_root_mib"]),
            "retention_candidates": nested_get(capture_health, ["retention", "candidates"]),
            "privacy_sensitive_skips": nested_get(capture_health, ["privacy", "sensitive_skips"]),
            "web_context_classes": nested_get(capture_health, ["web_context_quality", "classes"]),
            "web_context_low_signal_ratio": nested_get(capture_health, ["web_context_quality", "low_signal_ratio"]),
            "typed_text_coverage_status": typing_coverage_latest.get("status"),
            "typed_text_process_status": typing_process_latest.get("status"),
            "typed_text_nervous_refresh_status": nested_get(typing_nervous_refresh_latest, ["summary", "status"]),
            "ai_hygiene_status": ai_hygiene.get("status"),
            "ai_workhorse_validate_fails": nested_get(ai_hygiene, ["summary", "workhorse_validate_fails"]),
            "ai_workhorse_source_id_failures": nested_get(ai_hygiene, ["summary", "source_id_failures"]),
            "ai_hollow_action_card_fail": nested_get(ai_hygiene, ["summary", "hollow_action_card_fail"]),
            "ai_workhorse_model_used": nested_get(ai_hygiene, ["summary", "workhorse_model_used"]),
            "pulse_state": e2b_breath.get("pulse_state"),
            "next_breath_at": e2b_breath.get("next_breath_at"),
            "e2b_candidates_current": nested_get(e2b_breath, ["candidate_delta", "summary", "current"]),
            "e2b_candidates_new": nested_get(e2b_breath, ["candidate_delta", "summary", "new"]),
            "e2b_candidates_cleared": nested_get(e2b_breath, ["candidate_delta", "summary", "cleared"]),
            "e2b_review_needed": nested_get(e2b_breath, ["operator_attention", "count"]),
            "e2b_quality_score": nested_get(e2b_breath, ["resident_quality", "overall_score"]),
            "e2b_degradation_status": nested_get(e2b_breath, ["degradation_reason", "status"]),
            "e2b_staleness_status": nested_get(e2b_breath, ["e2b_staleness", "status"]),
            "self_awareness_breath_status": self_awareness_breath.get("status"),
            "self_awareness_autolink_refreshed": nested_get(self_awareness_breath, ["autolink", "refreshed"]),
            "self_awareness_autolink_state_changed": self_awareness_breath.get("state_changed_since_previous_heartbeat"),
            "self_awareness_autolink_organ_links": nested_get(self_awareness_breath, ["summary", "organ_links"]),
            "self_awareness_open_stack_requirements": nested_get(self_awareness_breath, ["summary", "open_stack_requirements"]),
            "self_awareness_working_stack_usage_gaps": nested_get(self_awareness_breath, ["summary", "working_stack_usage_gaps"]),
        },
        "pulse": {
            "name": "OS Abyss recurring Heartbeat",
            "subsystem": "heartbeats",
            "record": "heartbeat_pulse",
            "meaning": "compact recurring pulse over current machine state and reaction candidates",
            "reaction_candidate_ids": reaction_ids,
            "response_route_ids": [str(item.get("id")) for item in response_routes if isinstance(item, dict) and item.get("id")],
        },
        "inputs": heartbeat_inputs,
        "source_freshness": source_freshness,
        "rhythm": rhythm,
        "candidate_lifecycle": candidate_lifecycle,
        "pressure_context": pressure_context,
        "capture_health": capture_health,
        "ai_hygiene": ai_hygiene,
        "e2b_breath": e2b_breath,
        "self_awareness_breath": self_awareness_breath,
        "systemd_user": {
            "service": heartbeat_service,
            "timer": heartbeat_timer,
            "jobs": heartbeat_jobs,
            "job_causality": job_causality,
            "paths": {
                "service": str(HEARTBEAT_SERVICE_PATH),
                "timer": str(HEARTBEAT_TIMER_PATH),
            },
        },
        "paths": heartbeats_paths(),
        "policy": {
            "read_model": True,
            "recurring": True,
            "evidence_first": True,
            "automatic_action": False,
            "automatic_repo_write": False,
            "executes_reaction_commands": False,
            "executes_response_commands": False,
            "executes_self_awareness_cycle": False,
            "executes_self_awareness_probe": False,
            "candidates_require_operator_or_owner_route": True,
        },
    }
    if write_latest:
        errors = write_latest_and_history(data, HEARTBEATS_LATEST_PATH, HEARTBEATS_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def heartbeats_validate(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    validation_add_path_exists(checks, "agent_card", HEARTBEATS_AGENTS_PATH, "file", required=True)
    validation_add_path_exists(checks, "root", HEARTBEATS_ROOT, "dir", required=False)
    validation_add_path_exists(checks, "service_file", HEARTBEAT_SERVICE_PATH, "file", required=True)
    validation_add_path_exists(checks, "timer_file", HEARTBEAT_TIMER_PATH, "file", required=True)
    latest = load_latest_json(HEARTBEATS_LATEST_PATH, f"{SCHEMA_PREFIX}_heartbeat_pulse_v1")
    topology_validation_add(
        checks,
        "ok" if latest.get("ok") else "warn",
        "latest",
        "heartbeat latest is readable" if latest.get("ok") else "heartbeat latest missing or invalid",
        {"path": str(HEARTBEATS_LATEST_PATH), "error": latest.get("error")},
    )
    policy = latest.get("policy") if isinstance(latest.get("policy"), dict) else {}
    if latest.get("ok"):
        topology_validation_add(
            checks,
            "ok" if (
                policy.get("automatic_action") is False
                and policy.get("executes_reaction_commands") is False
                and policy.get("executes_response_commands") is False
            ) else "fail",
            "policy_non_executing",
            "heartbeat policy is recurring but non-executing",
            {"policy": policy},
        )
    else:
        topology_validation_add(
            checks,
            "warn",
            "policy_non_executing",
            "heartbeat latest must be generated before policy can be checked",
            {"path": str(HEARTBEATS_LATEST_PATH), "error": latest.get("error")},
        )
    summary = latest.get("summary") if isinstance(latest.get("summary"), dict) else {}
    topology_validation_add(
        checks,
        "ok" if int(summary.get("automatic_actions") or 0) == 0 else "fail",
        "no_automatic_actions",
        "heartbeat exposes no automatic actions",
        {"automatic_actions": summary.get("automatic_actions")},
    )
    if latest.get("ok"):
        expected_sources = set(heartbeats_paths().get("inputs", {}).keys())
        source_freshness = latest.get("source_freshness") if isinstance(latest.get("source_freshness"), dict) else {}
        sources = source_freshness.get("sources") if isinstance(source_freshness.get("sources"), dict) else {}
        missing_sources = sorted(expected_sources - set(sources.keys()))
        invalid_source_items = [
            name
            for name, item in sources.items()
            if not isinstance(item, dict)
            or item.get("freshness_class") not in {"fresh", "aging", "stale", "missing", "invalid"}
            or "ttl_sec" not in item
            or "stale_streak" not in item
        ]
        topology_validation_add(
            checks,
            "ok" if source_freshness.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_source_freshness_v1" else "fail",
            "source_freshness_schema",
            "heartbeat latest exposes source freshness readmodel",
            {"schema": source_freshness.get("schema")},
        )
        topology_validation_add(
            checks,
            "ok" if not missing_sources else "fail",
            "source_freshness_sources",
            "source freshness covers heartbeat inputs" if not missing_sources else "source freshness misses heartbeat inputs",
            {"missing": missing_sources, "expected": sorted(expected_sources)},
        )
        topology_validation_add(
            checks,
            "ok" if not invalid_source_items else "fail",
            "source_freshness_items",
            "source freshness entries expose class, ttl, and streak",
            {"invalid": invalid_source_items},
        )
        rhythm = latest.get("rhythm") if isinstance(latest.get("rhythm"), dict) else {}
        missing_rhythm_fields = [
            field
            for field in ("timer_active", "timer_enabled", "missed_beats", "expected_interval_sec", "waiting_heartbeat_job")
            if field not in rhythm
        ]
        topology_validation_add(
            checks,
            "ok" if rhythm.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_rhythm_v1" and not missing_rhythm_fields else "fail",
            "rhythm_schema",
            "heartbeat latest exposes timer rhythm readmodel",
            {"schema": rhythm.get("schema"), "missing_fields": missing_rhythm_fields},
        )
        topology_validation_add(
            checks,
            "ok" if rhythm.get("expected_interval_sec") == HEARTBEAT_EXPECTED_INTERVAL_SEC else "fail",
            "rhythm_expected_interval",
            "heartbeat rhythm uses configured expected interval",
            {"expected_interval_sec": rhythm.get("expected_interval_sec")},
        )
        topology_validation_add(
            checks,
            "ok" if rhythm.get("timer_active") is True and rhythm.get("timer_enabled") is True else "fail",
            "rhythm_recurring_timer",
            "heartbeat recurring timer is active and enabled",
            {
                "timer_active": rhythm.get("timer_active"),
                "timer_enabled": rhythm.get("timer_enabled"),
                "timer_list": rhythm.get("timer_list"),
            },
        )
        topology_validation_add(
            checks,
            "ok" if safe_int(rhythm.get("missed_beats"), -1) == 0 else "fail",
            "rhythm_no_missed_beats",
            "heartbeat rhythm has no missed beats",
            {
                "missed_beats": rhythm.get("missed_beats"),
                "observed_interval_sec": rhythm.get("observed_interval_sec"),
                "expected_interval_sec": rhythm.get("expected_interval_sec"),
                "waiting_heartbeat_job": rhythm.get("waiting_heartbeat_job"),
            },
        )
        candidate_lifecycle = latest.get("candidate_lifecycle") if isinstance(latest.get("candidate_lifecycle"), dict) else {}
        lifecycle_active = candidate_lifecycle.get("active")
        lifecycle_summary = candidate_lifecycle.get("summary")
        topology_validation_add(
            checks,
            "ok" if (
                candidate_lifecycle.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_candidate_lifecycle_v1"
                and isinstance(lifecycle_active, list)
                and isinstance(lifecycle_summary, dict)
            ) else "fail",
            "candidate_lifecycle_schema",
            "heartbeat latest exposes reaction candidate lifecycle readmodel",
            {"schema": candidate_lifecycle.get("schema")},
        )
        systemd_user = latest.get("systemd_user") if isinstance(latest.get("systemd_user"), dict) else {}
        job_causality = systemd_user.get("job_causality") if isinstance(systemd_user.get("job_causality"), dict) else {}
        waiting_jobs = job_causality.get("waiting_heartbeat_jobs")
        waiting_jobs_list = waiting_jobs if isinstance(waiting_jobs, list) else []
        topology_validation_add(
            checks,
            "ok" if isinstance(job_causality, dict) and "status" in job_causality else "fail",
            "systemd_job_causality",
            "heartbeat latest exposes user systemd job causality readmodel",
            {"status": job_causality.get("status"), "waiting_jobs": len(waiting_jobs_list)},
        )
        topology_validation_add(
            checks,
            "ok" if not waiting_jobs_list or job_causality.get("status") == "waiting" else "fail",
            "systemd_waiting_job_status",
            "waiting heartbeat jobs are represented without execution",
            {"status": job_causality.get("status"), "waiting_jobs": waiting_jobs_list},
        )
        pressure_context = latest.get("pressure_context") if isinstance(latest.get("pressure_context"), dict) else {}
        pressure_route = pressure_context.get("route")
        pressure_psi = pressure_context.get("psi") if isinstance(pressure_context.get("psi"), dict) else {}
        psi_missing = [
            name for name in ("cpu", "memory", "io")
            if not isinstance(pressure_psi.get(name), dict)
        ]
        topology_validation_add(
            checks,
            "ok" if pressure_context.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_pressure_context_v1" else "fail",
            "pressure_context_schema",
            "heartbeat latest exposes PSI-backed pressure context",
            {"schema": pressure_context.get("schema")},
        )
        topology_validation_add(
            checks,
            "ok" if pressure_route in {"allow", "observe", "soften", "defer", "block"} else "fail",
            "pressure_context_route",
            "pressure context uses bounded route vocabulary",
            {"route": pressure_route},
        )
        classification_evidence = pressure_context.get("classification_evidence") if isinstance(pressure_context.get("classification_evidence"), dict) else {}
        topology_validation_add(
            checks,
            "ok" if (
                not psi_missing
                and (classification_evidence.get("psi_citation") or classification_evidence.get("psi_absent_reason"))
            ) else "fail",
            "pressure_context_psi_evidence",
            "pressure classification cites PSI or explains PSI absence",
            {"missing": psi_missing, "classification_evidence": classification_evidence},
        )
        pressure_policy = pressure_context.get("policy") if isinstance(pressure_context.get("policy"), dict) else {}
        topology_validation_add(
            checks,
            "ok" if (
                pressure_policy.get("facts_only") is True
                and pressure_policy.get("does_not_kill_or_throttle_processes") is True
                and pressure_policy.get("does_not_mutate_cgroups") is True
            ) else "fail",
            "pressure_context_non_mutating",
            "pressure context is facts-only and non-mutating",
            {"policy": pressure_policy},
        )
        capture_health = latest.get("capture_health") if isinstance(latest.get("capture_health"), dict) else {}
        capture_policy = capture_health.get("policy") if isinstance(capture_health.get("policy"), dict) else {}
        owner_gated_routes = capture_health.get("owner_gated_routes") if isinstance(capture_health.get("owner_gated_routes"), list) else []
        ungated_capture_routes = [
            item.get("id")
            for item in owner_gated_routes
            if isinstance(item, dict)
            and (not bool(item.get("requires_owner_gate")) or bool(item.get("automatic")) or bool(item.get("executes_from_heartbeat")))
        ]
        topology_validation_add(
            checks,
            "ok" if capture_health.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_capture_health_v1" else "fail",
            "capture_health_schema",
            "heartbeat latest exposes capture and privacy health",
            {"schema": capture_health.get("schema")},
        )
        web_context = capture_health.get("web_context_quality") if isinstance(capture_health.get("web_context_quality"), dict) else {}
        web_context_classes = web_context.get("classes") if isinstance(web_context.get("classes"), dict) else {}
        invalid_web_context_classes = [
            name for name in web_context_classes
            if str(name) not in WEB_CONTEXT_CLASSES
        ]
        web_context_policy = web_context.get("policy") if isinstance(web_context.get("policy"), dict) else {}
        topology_validation_add(
            checks,
            "ok" if (
                web_context.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_web_context_quality_v1"
                and not invalid_web_context_classes
                and web_context_policy.get("raw_url_query_fragment_omitted") is True
                and web_context_policy.get("sensitive_skips_are_expected_health_signal") is True
            ) else "fail",
            "capture_health_web_context_quality",
            "heartbeat exposes bounded web context classes without raw query or fragment authority",
            {"schema": web_context.get("schema"), "classes": web_context_classes, "invalid": invalid_web_context_classes, "policy": web_context_policy},
        )
        topology_validation_add(
            checks,
            "ok" if (
                capture_policy.get("facts_only") is True
                and capture_policy.get("does_not_scan_raw_content") is True
                and capture_policy.get("does_not_delete_or_forget") is True
            ) else "fail",
            "capture_health_non_mutating",
            "capture health does not scan raw content or delete records",
            {"policy": capture_policy},
        )
        topology_validation_add(
            checks,
            "ok" if not ungated_capture_routes else "fail",
            "capture_health_owner_gated_routes",
            "capture cleanup routes are owner-gated candidates only",
            {"ungated": ungated_capture_routes, "routes": owner_gated_routes},
        )
        ai_hygiene = latest.get("ai_hygiene") if isinstance(latest.get("ai_hygiene"), dict) else {}
        ai_hygiene_policy = ai_hygiene.get("policy") if isinstance(ai_hygiene.get("policy"), dict) else {}
        ai_routes = ai_hygiene.get("owner_gated_routes") if isinstance(ai_hygiene.get("owner_gated_routes"), list) else []
        ungated_ai_routes = [
            item.get("id")
            for item in ai_routes
            if isinstance(item, dict)
            and (not bool(item.get("requires_owner_gate")) or bool(item.get("automatic")) or bool(item.get("executes_from_heartbeat")))
        ]
        topology_validation_add(
            checks,
            "ok" if ai_hygiene.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_ai_hygiene_v1" else "fail",
            "ai_hygiene_schema",
            "heartbeat latest exposes AI output hygiene state",
            {"schema": ai_hygiene.get("schema")},
        )
        topology_validation_add(
            checks,
            "ok" if (
                ai_hygiene_policy.get("facts_only") is True
                and ai_hygiene_policy.get("reads_latest_only") is True
                and ai_hygiene_policy.get("does_not_run_model_eval") is True
                and ai_hygiene_policy.get("does_not_run_workhorse_review_model") is True
                and ai_hygiene_policy.get("does_not_execute_actions") is True
            ) else "fail",
            "ai_hygiene_non_executing",
            "AI hygiene readmodel does not run models or actions from heartbeat",
            {"policy": ai_hygiene_policy},
        )
        topology_validation_add(
            checks,
            "ok" if not ungated_ai_routes else "fail",
            "ai_hygiene_owner_gated_routes",
            "AI hygiene routes are owner-gated candidates only",
            {"ungated": ungated_ai_routes, "routes": ai_routes},
        )
        e2b_breath = latest.get("e2b_breath") if isinstance(latest.get("e2b_breath"), dict) else {}
        e2b_policy = e2b_breath.get("policy") if isinstance(e2b_breath.get("policy"), dict) else {}
        e2b_candidate_delta = e2b_breath.get("candidate_delta") if isinstance(e2b_breath.get("candidate_delta"), dict) else {}
        e2b_required_inputs = {"candidate_delta", "resident_quality", "degradation_reason", "e2b_staleness", "operator_attention"}
        missing_e2b_inputs = sorted(key for key in e2b_required_inputs if key not in e2b_breath)
        missing_e2b_outputs = [
            key for key in ("pulse_state", "next_breath_at", "why_now", "what_changed")
            if key not in e2b_breath
        ]
        topology_validation_add(
            checks,
            "ok" if e2b_breath.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_e2b_breath_v1" else "fail",
            "e2b_breath_schema",
            "heartbeat latest exposes E2B breath readmodel",
            {"schema": e2b_breath.get("schema")},
        )
        topology_validation_add(
            checks,
            "ok" if not missing_e2b_inputs and e2b_candidate_delta.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_e2b_candidate_delta_v1" else "fail",
            "e2b_breath_inputs",
            "E2B breath includes candidate delta, quality, degradation, staleness, and operator attention",
            {"missing": missing_e2b_inputs, "candidate_delta_schema": e2b_candidate_delta.get("schema")},
        )
        topology_validation_add(
            checks,
            "ok" if (
                not missing_e2b_outputs
                and e2b_breath.get("pulse_state") in {"quiet", "observing", "useful", "review_needed", "degraded", "blocked"}
                and isinstance(e2b_breath.get("why_now"), list)
                and isinstance(e2b_breath.get("what_changed"), list)
            ) else "fail",
            "e2b_breath_outputs",
            "E2B breath answers pulse state, next breath, why now, and what changed",
            {"missing": missing_e2b_outputs, "pulse_state": e2b_breath.get("pulse_state"), "why_now": e2b_breath.get("why_now"), "what_changed": e2b_breath.get("what_changed")},
        )
        topology_validation_add(
            checks,
            "ok" if (
                e2b_policy.get("facts_only") is True
                and e2b_policy.get("reads_latest_only") is True
                and e2b_policy.get("automatic_action") is False
                and e2b_policy.get("action_execution") is False
                and e2b_policy.get("executes_candidates") is False
                and e2b_policy.get("does_not_run_model") is True
                and e2b_policy.get("does_not_run_jobs_batch") is True
            ) else "fail",
            "e2b_breath_non_executing",
            "E2B breath is a latest-artifact readmodel and does not execute candidates or model jobs",
            {"policy": e2b_policy},
        )
        self_awareness_breath = latest.get("self_awareness_breath") if isinstance(latest.get("self_awareness_breath"), dict) else {}
        self_awareness_policy = self_awareness_breath.get("policy") if isinstance(self_awareness_breath.get("policy"), dict) else {}
        self_awareness_summary = self_awareness_breath.get("summary") if isinstance(self_awareness_breath.get("summary"), dict) else {}
        topology_validation_add(
            checks,
            "ok" if (
                self_awareness_breath.get("schema") == f"{SCHEMA_PREFIX}_heartbeat_self_awareness_breath_v1"
                and self_awareness_breath.get("ok") is True
                and nested_get(self_awareness_breath, ["autolink", "complete"]) is True
            ) else "fail",
            "self_awareness_breath_schema",
            "heartbeat latest exposes self-awareness autolink breath",
            {"schema": self_awareness_breath.get("schema"), "status": self_awareness_breath.get("status"), "autolink": self_awareness_breath.get("autolink")},
        )
        topology_validation_add(
            checks,
            "ok" if (
                safe_int(self_awareness_summary.get("organ_links"), -1)
                == safe_int(self_awareness_summary.get("organ_links_complete"), -2)
                and safe_int(self_awareness_summary.get("stack_requirement_links"), -1)
                == safe_int(self_awareness_summary.get("stack_requirement_links_complete"), -2)
                and safe_int(self_awareness_summary.get("synthetic_scenarios"), -1)
                == safe_int(self_awareness_summary.get("synthetic_scenarios_complete"), -2)
                and safe_int(self_awareness_summary.get("organ_links"), 0) > 0
            ) else "fail",
            "self_awareness_breath_counts",
            "self-awareness breath preserves complete organ, requirement, and synthetic autolink counts",
            {"summary": self_awareness_summary},
        )
        topology_validation_add(
            checks,
            "ok" if (
                self_awareness_policy.get("facts_only") is True
                and self_awareness_policy.get("refreshes_autolink_only_when_prerequisites_complete") is True
                and self_awareness_policy.get("does_not_run_cycle") is True
                and self_awareness_policy.get("does_not_run_probe") is True
                and self_awareness_policy.get("does_not_run_model") is True
                and self_awareness_policy.get("action_execution") is False
                and self_awareness_policy.get("automatic_action") is False
                and self_awareness_policy.get("host_layer_mutates_stack") is False
            ) else "fail",
            "self_awareness_breath_non_executing",
            "self-awareness breath refreshes only autolink and does not execute cycle, probe, models, actions, or stack mutation",
            {"policy": self_awareness_policy},
        )
    timer_state = user_systemd_unit(HEARTBEAT_TIMER)
    topology_validation_add(
        checks,
        "ok" if timer_state.get("is_enabled") else "warn",
        "timer_enabled",
        f"{HEARTBEAT_TIMER} enabled" if timer_state.get("is_enabled") else f"{HEARTBEAT_TIMER} is not enabled",
        {"timer": timer_state},
    )
    topology_validation_add(
        checks,
        "ok" if timer_state.get("is_active") else "warn",
        "timer_active",
        f"{HEARTBEAT_TIMER} active" if timer_state.get("is_active") else f"{HEARTBEAT_TIMER} is not active",
        {"timer": timer_state},
    )
    bridge = bridge_manifest()
    commands = bridge.get("commands") if isinstance(bridge.get("commands"), dict) else {}
    missing_commands = [
        key for key in ("heartbeats_pulse_json", "heartbeats_paths_json", "heartbeats_validate_json")
        if key not in commands
    ]
    topology_validation_add(
        checks,
        "fail" if missing_commands else "ok",
        "bridge_commands",
        "bridge exposes heartbeat commands" if not missing_commands else "bridge misses heartbeat commands",
        {"missing": missing_commands},
    )
    data = heartbeats_validate_document_from_checks(
        checks,
        strict=strict,
        paths=heartbeats_paths(),
    )
    if write_latest:
        errors = write_latest_and_history(data, HEARTBEATS_VALIDATE_LATEST_PATH, HEARTBEATS_VALIDATE_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def print_heartbeat_text(data: dict[str, Any]) -> None:
    summary = data.get("summary", {}) if isinstance(data.get("summary"), dict) else {}
    print(
        f"heartbeats: {summary.get('status')} "
        f"reactions={summary.get('reaction_candidates')} "
        f"nervous={summary.get('nervous_readiness')} "
        f"timer={summary.get('timer_active')}/{summary.get('timer_enabled')} "
        f"pressure={summary.get('pressure_route')} "
        f"capture={summary.get('capture_health_status')}"
    )


