def reaction_host_owner_gap_candidates(
    *,
    stack_bridge_validate_doc: dict[str, Any] | None = None,
    manual_collect_doc: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    stack_bridge_validate_doc = stack_bridge_validate_doc if isinstance(stack_bridge_validate_doc, dict) else stack_bridge_validate(strict=False, write_latest=True)
    manual_collect_doc = manual_collect_doc if isinstance(manual_collect_doc, dict) else observability_manual_collect_probe()
    candidates: list[dict[str, Any]] = []

    bridge_checks = stack_bridge_validate_doc.get("checks") if isinstance(stack_bridge_validate_doc.get("checks"), list) else []
    static_bridge_check = next(
        (
            check for check in bridge_checks
            if isinstance(check, dict)
            and (check.get("key") or check.get("id")) == "static_bridge_sync"
            and str(check.get("level") or check.get("status") or "").lower() in {"warn", "warning", "fail", "open"}
        ),
        None,
    )
    if static_bridge_check:
        candidate = reaction_candidate(
            "host-static-bridge-sync-root-review",
            title="Static stack bridge manifests need root-authorized sync",
            severity="warning",
            category="stack-bridge",
            reason="Dynamic bridge routes are ahead of root-owned /etc manifests; keep the host-owned root-sync route visible without mutating abyss-stack.",
            command="abyss-machine stack-bridge sync-static --dry-run --json",
            owner_route="abyss-machine:root-operator",
            action_mode="operator_authorized_host_sync",
            evidence=[
                {"path": str(STACK_BRIDGE_VALIDATE_LATEST_PATH), "summary": stack_bridge_validate_doc.get("summary")},
                {"path": str(STACK_BRIDGE_STATIC_SYNC_LATEST_PATH), "schema": f"{SCHEMA_PREFIX}_stack_bridge_static_sync_v1"},
                {"path": str(MANIFEST_PATH), "writable_by_current_user": os.access(MANIFEST_PATH, os.W_OK)},
                {"path": str(STACK_BRIDGE_CONFIG_PATH), "writable_by_current_user": os.access(STACK_BRIDGE_CONFIG_PATH, os.W_OK)},
                {"check": static_bridge_check},
            ],
        )
        candidate["host_owner_gap"] = {
            "schema": f"{SCHEMA_PREFIX}_host_owner_gap_v1",
            "kind": "static_bridge_sync",
            "status": "root_authorization_required",
            "owner_route": "abyss-machine:root-operator",
            "current_user_can_write_bridge": os.access(MANIFEST_PATH, os.W_OK),
            "current_user_can_write_stack_bridge": os.access(STACK_BRIDGE_CONFIG_PATH, os.W_OK),
            "missing": static_bridge_check.get("data"),
            "evidence_refs": [
                {"path": str(STACK_BRIDGE_VALIDATE_LATEST_PATH), "check": "static_bridge_sync"},
                {"path": str(STACK_BRIDGE_STATIC_SYNC_LATEST_PATH)},
            ],
            "policy": {
                "handoff_only": True,
                "read_only_candidate": True,
                "executes_commands": False,
                "host_layer_mutates_stack": False,
                "mutates_abyss_stack": False,
                "automatic_remediation": False,
            },
        }
        candidate["safe_next_action"] = {
            "kind": "root_authorized_static_bridge_sync_review",
            "owner_route": "abyss-machine:root-operator",
            "review_command": "abyss-machine stack-bridge sync-static --dry-run --json",
            "privileged_closure_command": "pkexec abyss-machine stack-bridge sync-static --json",
            "post_verifiers": [
                "abyss-machine stack-bridge validate --json",
                "abyss-machine reactions validate --json",
                "abyss-machine responses validate --json",
            ],
            "automatic": False,
            "requires_human_approval": True,
            "executes_commands": False,
            "host_layer_mutates_stack": False,
            "mutates_abyss_stack": False,
            "action_execution": False,
        }
        candidate["runbook_candidate"] = {
            "schema": f"{SCHEMA_PREFIX}_host_owner_gap_runbook_candidate_v1",
            "id": "host-runbook-static-bridge-sync",
            "owner_route": "abyss-machine:root-operator",
            "review_first": "abyss-machine stack-bridge sync-static --dry-run --json",
            "human_approved_command": "pkexec abyss-machine stack-bridge sync-static --json",
            "acceptance_verifiers": [
                "abyss-machine stack-bridge validate --json",
                "abyss-machine self-awareness validate --json",
            ],
            "rollback": "restore /etc/abyss-machine/*.pre-sync-*.bak backups created by sync-static; abyss-stack was not changed",
            "policy": {"host_layer_mutates_stack": False, "executes_commands": False, "automatic": False},
        }
        candidate["risk"] = {"risks": ["root-owned static manifest replacement requires live operator authorization"], "automatic": False}
        candidate["blast_radius"] = {"host_config": True, "stack_mutation": False, "project_roots": False}
        candidate["rollback"] = {"stack_rollback_required": False, "host_restore": "restore pre-sync /etc backups"}
        candidates.append(candidate)

    if manual_collect_doc.get("status") not in {None, "ready"}:
        candidate = reaction_candidate(
            "host-observability-manual-collect-permission-review",
            title="Observability manual collect needs root-owned permission normalization",
            severity="warning",
            category="observability",
            reason="Thermal/battery manual collect is visible as a body gap but current daily output directories are not group-writable for the operator.",
            command="abyss-machine observability status --json",
            owner_route="abyss-machine:root-operator",
            action_mode="operator_authorized_permission_normalization",
            evidence=[
                {"path": str(OBSERVABILITY_ROOT / "thermal-battery" / "latest.json")},
                {"manual_collect": manual_collect_doc},
            ],
        )
        candidate["host_owner_gap"] = {
            "schema": f"{SCHEMA_PREFIX}_host_owner_gap_v1",
            "kind": "observability_manual_collect_permission",
            "status": manual_collect_doc.get("status"),
            "owner_route": "abyss-machine:root-operator",
            "missing_or_unwritable": manual_collect_doc.get("missing_or_unwritable") if isinstance(manual_collect_doc.get("missing_or_unwritable"), list) else [],
            "directories": manual_collect_doc.get("directories") if isinstance(manual_collect_doc.get("directories"), list) else [],
            "evidence_refs": [{"path": str(OBSERVABILITY_ROOT / "thermal-battery"), "section": "manual_collect"}],
            "policy": {
                "handoff_only": True,
                "read_only_candidate": True,
                "executes_commands": False,
                "host_layer_mutates_stack": False,
                "mutates_abyss_stack": False,
                "automatic_remediation": False,
            },
        }
        candidate["safe_next_action"] = {
            "kind": "root_authorized_observability_permission_review",
            "owner_route": "abyss-machine:root-operator",
            "review_command": "abyss-machine observability status --json",
            "privileged_closure_command": "pkexec /srv/abyss-machine/tmp/root-sync-static-and-observability.py",
            "post_verifiers": [
                "abyss-machine observability status --json",
                "abyss-machine observability collect --json",
                "abyss-machine stack-bridge validate --json",
                "abyss-machine reactions validate --json",
                "abyss-machine responses validate --json",
            ],
            "automatic": False,
            "requires_human_approval": True,
            "executes_commands": False,
            "host_layer_mutates_stack": False,
            "mutates_abyss_stack": False,
            "action_execution": False,
        }
        candidate["runbook_candidate"] = {
            "schema": f"{SCHEMA_PREFIX}_host_owner_gap_runbook_candidate_v1",
            "id": "host-runbook-observability-permission-normalization",
            "owner_route": "abyss-machine:root-operator",
            "review_first": "abyss-machine observability status --json",
            "human_approved_command": "pkexec /srv/abyss-machine/tmp/root-sync-static-and-observability.py",
            "acceptance_verifiers": [
                "abyss-machine observability status --json",
                "abyss-machine observability collect --json",
                "abyss-machine self-awareness validate --json",
            ],
            "rollback": "restore collector backup if created and reset affected observability directories to the previous root-owned mode",
            "policy": {"host_layer_mutates_stack": False, "executes_commands": False, "automatic": False},
        }
        candidate["risk"] = {"risks": ["permission normalization changes host-owned observability output modes"], "automatic": False}
        candidate["blast_radius"] = {"host_observability": True, "stack_mutation": False, "project_roots": False}
        candidate["rollback"] = {"stack_rollback_required": False, "host_restore": "restore collector backup and previous directory modes"}
        candidates.append(candidate)

    return candidates


