def abyssvault_backup_plane_active_change(changes_doc: dict[str, Any] | None = None) -> dict[str, Any] | None:
    changes_doc = changes_doc if isinstance(changes_doc, dict) else load_latest_json(CHANGE_INDEX_PATH, f"{SCHEMA_PREFIX}_changes_index_v1")
    active_records = changes_doc.get("active") if isinstance(changes_doc.get("active"), list) else []
    for item in active_records:
        if isinstance(item, dict) and item.get("id") == ABYSSVAULT_BACKUP_PLANE_CHANGE_ID:
            return item
    return None


def abyssvault_backup_plane_blockers(backup_status: dict[str, Any]) -> list[str]:
    if not isinstance(backup_status, dict) or backup_status.get("schema") != "abyss_backup_latest_v1":
        return ["backup_status_missing"]
    blockers: list[str] = []
    if backup_status.get("vault_mounted") is not True:
        blockers.append("vault_not_mounted")
    if backup_status.get("restic_binary_exists") is not True:
        blockers.append("restic_binary_missing")
    if backup_status.get("restic_repo_initialized") is not True:
        blockers.append("restic_repo_not_initialized")
    privileged = backup_status.get("privileged_install") if isinstance(backup_status.get("privileged_install"), dict) else {}
    missing_privileged = [
        key
        for key in (
            "etc_policy_exists",
            "usr_local_command_exists",
            "system_timer_exists",
            "sessions_timer_exists",
            "sessions_checksum_timer_exists",
        )
        if privileged.get(key) is not True
    ]
    blockers.extend(f"privileged_install_missing:{key}" for key in missing_privileged)
    return blockers


def abyssvault_backup_plane_route(
    backup_status: dict[str, Any],
    active_change: dict[str, Any],
) -> dict[str, Any]:
    blockers = abyssvault_backup_plane_blockers(backup_status)
    status = "ready_for_backup_verify" if not blockers else "operator_mount_or_bootstrap_required"
    route = {
        "schema": f"{SCHEMA_PREFIX}_abyssvault_backup_plane_route_v1",
        "change_id": ABYSSVAULT_BACKUP_PLANE_CHANGE_ID,
        "status": status,
        "blockers": blockers,
        "active_change": {
            "id": active_change.get("id"),
            "title": active_change.get("title"),
            "status": active_change.get("status"),
            "path": active_change.get("path"),
            "surfaces": active_change.get("surfaces") if isinstance(active_change.get("surfaces"), list) else [],
            "updated_at": active_change.get("updated_at"),
        },
        "backup_status": {
            "path": str(BACKUP_LATEST_PATH),
            "generated_at": backup_status.get("generated_at") if isinstance(backup_status, dict) else None,
            "status": backup_status.get("status") if isinstance(backup_status, dict) else None,
            "vault": backup_status.get("vault") if isinstance(backup_status, dict) else "/abyss",
            "backup_root": backup_status.get("backup_root") if isinstance(backup_status, dict) else "/abyss/Backups",
            "vault_mounted": backup_status.get("vault_mounted") if isinstance(backup_status, dict) else None,
            "restic_binary": backup_status.get("restic_binary") if isinstance(backup_status, dict) else None,
            "restic_binary_exists": backup_status.get("restic_binary_exists") if isinstance(backup_status, dict) else None,
            "restic_repo": backup_status.get("restic_repo") if isinstance(backup_status, dict) else None,
            "restic_repo_initialized": backup_status.get("restic_repo_initialized") if isinstance(backup_status, dict) else None,
            "privileged_install": backup_status.get("privileged_install") if isinstance(backup_status.get("privileged_install"), dict) else {},
        },
        "safe_next_action": {
            "kind": "operator_mount_abyssvault_then_verify",
            "owner_route": "abyss-machine:backup-operator",
            "review_command": "abyss-backup status --json",
            "operator_prerequisites": [
                "unlock and mount ABYSSVAULT at /abyss",
                "confirm /abyss/Backups exists and carries the backup policy",
                "confirm /abyss/Backups/bin/restic exists before system backup verification",
            ],
            "post_mount_verifiers": [
                "abyss-backup status --json",
                "abyss-backup verify --json",
                "abyss-machine topology validate --json",
                "abyss-machine reactions validate --json",
                "abyss-machine responses validate --json",
            ],
            "closure_requires": [
                "vault_mounted=true",
                "restic_binary_exists=true",
                "restic_repo_initialized=true",
                "verify status ok",
                "active change validation and rollback notes filled before close",
            ],
            "automatic": False,
            "requires_operator": True,
            "requires_human_approval": True,
            "executes_commands": False,
            "host_layer_mutates_stack": False,
            "mutates_abyss_stack": False,
            "writes_abyss_vault": False,
            "runs_backup": False,
        },
        "runbook_candidate": {
            "schema": f"{SCHEMA_PREFIX}_abyssvault_backup_plane_runbook_candidate_v1",
            "id": "runbook-abyssvault-backup-plane-closeout",
            "owner_route": "abyss-machine:backup-operator",
            "review_first": "abyss-backup status --json",
            "operator_prerequisites": [
                "ABYSSVAULT mounted at /abyss",
                "restic binary present under /abyss/Backups/bin/restic",
                "restic repository initialized under /abyss/Backups/restic/system",
            ],
            "acceptance_verifiers": [
                "abyss-backup status --json",
                "abyss-backup verify --json",
                "abyss-machine topology validate --json",
            ],
            "rollback": "do not close the active change; unmount ABYSSVAULT or leave backup timers skipping when /abyss is absent",
            "policy": {
                "automatic_execution": False,
                "executes_commands": False,
                "host_layer_mutates_stack": False,
                "mutates_abyss_stack": False,
                "runs_backup": False,
            },
        },
        "evidence_refs": [
            {"path": str(BACKUP_LATEST_PATH), "schema": "abyss_backup_latest_v1"},
            {"path": str(CHANGE_INDEX_PATH), "change_id": ABYSSVAULT_BACKUP_PLANE_CHANGE_ID},
            {"path": str(CHANGE_ACTIVE_ROOT / ABYSSVAULT_BACKUP_PLANE_CHANGE_ID)},
        ],
        "policy": {
            "read_model": True,
            "operator_gated": True,
            "automatic_execution": False,
            "executes_commands": False,
            "host_layer_mutates_stack": False,
            "mutates_abyss_stack": False,
            "writes_abyss_vault": False,
            "runs_backup": False,
            "keeps_change_open_until_verified": True,
        },
    }
    route["complete"] = abyssvault_backup_plane_route_complete(route)
    return route


def abyssvault_backup_plane_route_complete(route: Any) -> bool:
    if not isinstance(route, dict):
        return False
    safe_next = route.get("safe_next_action") if isinstance(route.get("safe_next_action"), dict) else {}
    policy = route.get("policy") if isinstance(route.get("policy"), dict) else {}
    active_change = route.get("active_change") if isinstance(route.get("active_change"), dict) else {}
    backup_status = route.get("backup_status") if isinstance(route.get("backup_status"), dict) else {}
    return (
        route.get("schema") == f"{SCHEMA_PREFIX}_abyssvault_backup_plane_route_v1"
        and route.get("change_id") == ABYSSVAULT_BACKUP_PLANE_CHANGE_ID
        and active_change.get("id") == ABYSSVAULT_BACKUP_PLANE_CHANGE_ID
        and active_change.get("status") == "active"
        and bool(active_change.get("path"))
        and isinstance(active_change.get("surfaces"), list)
        and backup_status.get("path") == str(BACKUP_LATEST_PATH)
        and isinstance(route.get("blockers"), list)
        and bool(route.get("evidence_refs"))
        and safe_next.get("requires_operator") is True
        and safe_next.get("requires_human_approval") is True
        and safe_next.get("automatic") is False
        and safe_next.get("executes_commands") is False
        and safe_next.get("host_layer_mutates_stack") is False
        and safe_next.get("mutates_abyss_stack") is False
        and safe_next.get("writes_abyss_vault") is False
        and safe_next.get("runs_backup") is False
        and bool(safe_next.get("review_command"))
        and isinstance(safe_next.get("post_mount_verifiers"), list)
        and "abyss-backup verify --json" in safe_next.get("post_mount_verifiers", [])
        and policy.get("operator_gated") is True
        and policy.get("automatic_execution") is False
        and policy.get("executes_commands") is False
        and policy.get("host_layer_mutates_stack") is False
        and policy.get("mutates_abyss_stack") is False
        and policy.get("writes_abyss_vault") is False
        and policy.get("runs_backup") is False
        and policy.get("keeps_change_open_until_verified") is True
        and isinstance(route.get("runbook_candidate"), dict)
    )


def reaction_status(write_latest: bool = True) -> dict[str, Any]:
    candidates: list[dict[str, Any]] = []
    nervous_events = load_latest_json(NERVOUS_EVENTS_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_events_build_v1")
    nervous_brief = load_latest_json(NERVOUS_BRIEF_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_brief_v1")
    doctor_latest = load_latest_json(DOCTOR_LATEST_PATH, f"{SCHEMA_PREFIX}_doctor_v1")
    machine_report = load_latest_json(DOCTOR_MACHINE_REPORT_LATEST_PATH, f"{SCHEMA_PREFIX}_doctor_machine_report_v1")
    resource_orch = load_latest_json(RESOURCE_ORCHESTRATOR_LATEST_PATH, f"{SCHEMA_PREFIX}_resource_orchestrator_v2_v1")
    desktop_compositor_latest = load_latest_json(PROCESS_DESKTOP_COMPOSITOR_LATEST_PATH, f"{SCHEMA_PREFIX}_process_desktop_compositor_v1")
    retention_latest = load_latest_json(NERVOUS_RETENTION_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_retention_plan_v1")
    if retention_latest.get("schema") != f"{SCHEMA_PREFIX}_nervous_retention_plan_v1" or not isinstance(retention_latest.get("summary"), dict):
        retention_latest = nervous_retention_plan(write_latest=True)
    semantic_maintain_latest = load_latest_json(NERVOUS_SEMANTIC_MAINTAIN_LATEST_PATH, f"{SCHEMA_PREFIX}_nervous_semantic_maintain_v1")
    game_guard_latest = load_latest_json(PROCESS_GAME_GUARD_LATEST_PATH, f"{SCHEMA_PREFIX}_process_game_guard_v1")
    ai_workhorse_validate = load_latest_json(AI_LLM_WORKHORSE_VALIDATE_LATEST_PATH, f"{SCHEMA_PREFIX}_gemma4_workhorse_harness_validate_v1")
    self_awareness_alerts_latest = load_latest_json(SELF_AWARENESS_ALERTS_LATEST_PATH, f"{SCHEMA_PREFIX}_self_awareness_alerts_v1")
    changes_index = load_latest_json(CHANGE_INDEX_PATH, f"{SCHEMA_PREFIX}_changes_index_v1")
    backup_latest = load_latest_json(BACKUP_LATEST_PATH, "abyss_backup_latest_v1")
    alert_candidates = self_awareness_alerts_latest.get("candidates") if isinstance(self_awareness_alerts_latest.get("candidates"), list) else []
    if any(
        isinstance(item, dict)
        and item.get("category") == "self-awareness"
        and not self_awareness_reaction_candidate_response_depth_complete(item)
        for item in alert_candidates
    ):
        self_awareness_alerts_latest = self_awareness_alerts(write_latest=True)
    doctor_unit = user_systemd_unit(DOCTOR_SERVICE)
    doctor_unit_show = systemd_unit_properties(
        DOCTOR_SERVICE,
        ["ActiveState", "SubState", "Result", "ExecMainStatus", "StateChangeTimestamp", "FragmentPath"],
        user=True,
        timeout=2.0,
    )
    host_owner_gap_candidates = reaction_host_owner_gap_candidates()
    for candidate in host_owner_gap_candidates:
        reaction_add_candidate(candidates, candidate)

    backup_plane_change = abyssvault_backup_plane_active_change(changes_index)
    if backup_plane_change:
        backup_route = abyssvault_backup_plane_route(backup_latest, backup_plane_change)
        blockers = backup_route.get("blockers") if isinstance(backup_route.get("blockers"), list) else []
        candidate = reaction_candidate(
            "abyssvault-backup-plane-open",
            title="ABYSSVAULT backup plane remains open",
            severity="warning" if blockers else "notice",
            category="backup",
            reason=(
                "Backup-plane change is active and live backup status still has blockers: "
                + ", ".join(str(item) for item in blockers[:8])
                if blockers
                else "Backup-plane change is active; verify and close only after current vault/restic evidence is written into the change record."
            ),
            command="abyss-backup status --json",
            owner_route="abyss-machine:backup-operator",
            action_mode="operator_mount_and_verify",
            evidence=[
                {"path": str(BACKUP_LATEST_PATH), "generated_at": backup_latest.get("generated_at"), "status": backup_latest.get("status")},
                {"path": str(CHANGE_INDEX_PATH), "active_change": backup_plane_change},
            ],
        )
        candidate["backup_plane_route"] = backup_route
        candidate["safe_next_action"] = backup_route.get("safe_next_action")
        candidate["runbook_candidate"] = backup_route.get("runbook_candidate")
        candidate["risk"] = {
            "risks": ["backup closeout depends on external ABYSSVAULT mount and restic repository evidence"],
            "automatic": False,
        }
        candidate["blast_radius"] = {"backup_vault": True, "stack_mutation": False, "project_roots": False}
        candidate["rollback"] = {"stack_rollback_required": False, "host_restore": "leave active change open until backup verify evidence is current"}
        reaction_add_candidate(candidates, candidate)

    if str(doctor_unit.get("active")) == "failed":
        machine_ok = bool(machine_report.get("ok"))
        reaction_add_candidate(
            candidates,
            reaction_candidate(
                "doctor-user-unit-failed-state",
                title="Doctor user unit is in failed state",
                severity="notice" if machine_ok else "watch",
                category="systemd",
                reason=(
                    "Current machine report is readable, so the failed user-unit state may be stale."
                    if machine_ok
                    else "Doctor machine report is not currently clean; inspect before clearing the unit state."
                ),
                command=(
                    "systemctl --user reset-failed abyss-machine-doctor.service"
                    if machine_ok
                    else "abyss-machine doctor machine-report --json --no-thermal-sample"
                ),
                evidence=[
                    {"path": str(DOCTOR_MACHINE_REPORT_LATEST_PATH), "ok": machine_report.get("ok"), "status": machine_report.get("status"), "generated_at": machine_report.get("generated_at")},
                    {"unit": DOCTOR_SERVICE, "state": doctor_unit, "show": doctor_unit_show},
                ],
            ),
        )

    doctor_summary = doctor_latest.get("summary", {}) if isinstance(doctor_latest.get("summary"), dict) else {}
    if int(doctor_summary.get("warnings") or 0) > 0:
        non_ok = [
            {"key": item.get("key"), "level": item.get("level"), "message": item.get("message")}
            for item in doctor_latest.get("checks", [])
            if isinstance(item, dict) and item.get("level") != "ok"
        ][:6]
        route = doctor_warning_route(
            doctor_doc=doctor_latest,
            machine_report=machine_report,
            doctor_unit=doctor_unit,
            doctor_unit_show=doctor_unit_show,
        )
        candidate = reaction_candidate(
            "doctor-warnings-present",
            title="Doctor has warning-level checks",
            severity="warning",
            category="doctor",
            reason="Doctor status is usable but still carries warning checks that should remain visible.",
            command="abyss-machine doctor --json",
            evidence=[
                {"path": str(DOCTOR_LATEST_PATH), "summary": doctor_summary, "generated_at": doctor_latest.get("generated_at")},
                {"non_ok_checks": non_ok},
            ],
        )
        candidate["doctor_warning_route"] = route
        candidate["safe_next_action"] = route.get("safe_next_action")
        reaction_add_candidate(candidates, candidate)

    hotpath_evidence = memory_residency_hotpath_evidence()
    hotpath_status = str(hotpath_evidence.get("measurement_status") or "missing_required_before_persistent_cgroup_policy")
    if hotpath_status not in {"fresh_ok"}:
        hotpath_route = memory_hotpath_probe_route(hotpath_evidence)
        hotpath_candidate_meta = {
            "latest_failed": (
                "memory-hotpath-probe-failed",
                "Memory hot-path latency probe failed",
                "Latest hot-path latency probe is fresh but failed; residency decisions must carry the concrete TTS/swap/stall evidence before any persistent policy.",
            ),
            "stale": (
                "memory-hotpath-probe-stale",
                "Memory hot-path latency probe is stale",
                "Residency decisions should not depend on an old hot-path probe.",
            ),
            "fresh_watch": (
                "memory-hotpath-probe-watch",
                "Memory hot-path latency probe has watch findings",
                "Latest hot-path latency probe is fresh but has issues that should remain visible before persistent memory policy.",
            ),
        }
        candidate_id, title, reason = hotpath_candidate_meta.get(
            hotpath_status,
            (
                "memory-hotpath-probe-review",
                "Memory hot-path latency probe needs review",
                "Hot-path latency evidence is missing or inconclusive; residency decisions should preserve the measurement gap.",
            ),
        )
        candidate = reaction_candidate(
            candidate_id,
            title=title,
            severity="warning",
            category="memory",
            reason=reason,
            command=str(nested_get(hotpath_route, ["safe_next_action", "remeasure_command"]) or "abyss-machine memory hotpath-probe --json"),
            evidence=[
                {"path": str(MEMORY_HOTPATH_LATEST_PATH), "generated_at": hotpath_evidence.get("generated_at"), "measurement_status": hotpath_status},
                {"path": str(MEMORY_RESIDENCY_LATEST_PATH), "summary": {"hotpath_probe_status": hotpath_status}},
                {"path": str(DOCTOR_MACHINE_REPORT_LATEST_PATH), "generated_at": machine_report.get("generated_at")},
            ],
        )
        candidate["memory_hotpath_route"] = hotpath_route
        candidate["safe_next_action"] = hotpath_route.get("safe_next_action")
        reaction_add_candidate(candidates, candidate)

    readiness = nervous_brief.get("readiness", {}) if isinstance(nervous_brief.get("readiness"), dict) else {}
    if not nervous_brief.get("ok") or readiness.get("status") not in (None, "ready"):
        gate = nervous_semantic_resource_gate_evidence(
            nervous_brief=nervous_brief,
            readiness=readiness,
            semantic_maintain=semantic_maintain_latest,
            game_guard=game_guard_latest,
        )
        candidate = reaction_candidate(
            "nervous-readiness-not-ready",
            title="Nervous readiness is not ready",
            severity="watch",
            category="nervous",
            reason="Reaction quality depends on current nervous facts, derived records, index freshness, and resource-gated semantic maintenance.",
            command=str(nested_get(gate, ["safe_next_action", "review_command"]) or NERVOUS_SEMANTIC_MAINTAIN_REVIEW_COMMAND),
            evidence=[
                {"path": str(NERVOUS_BRIEF_LATEST_PATH), "ok": nervous_brief.get("ok"), "readiness": readiness, "generated_at": nervous_brief.get("generated_at")},
                {"gaps": nervous_brief.get("gaps")},
                {"semantic_resource_gate": gate},
            ],
        )
        candidate["resource_gate"] = gate
        candidate["safe_next_action"] = gate["safe_next_action"]
        candidate["runbook_candidate"] = {
            "schema": f"{SCHEMA_PREFIX}_nervous_resource_gate_runbook_candidate_v1",
            "id": "runbook-nervous-semantic-resource-gate-review",
            "title": "Review nervous semantic maintenance under resource gate",
            "steps": [
                gate["safe_next_action"]["review_command"],
                "abyss-machine resource status --json",
                "abyss-machine processes game-guard --json",
                gate["safe_next_action"]["retry_command"],
                "abyss-machine nervous semantic-status --json",
                "abyss-machine nervous quality-audit --json",
            ],
            "acceptance_verifiers": [
                "abyss-machine nervous semantic-status --json",
                "abyss-machine nervous quality-audit --json",
                "abyss-machine reactions validate --json",
                "abyss-machine responses validate --json",
                "abyss-machine self-awareness validate --json",
            ],
            "policy": {
                "resource_gated": True,
                "automatic_execution": False,
                "executes_commands": False,
                "host_layer_mutates_stack": False,
            },
        }
        candidate["risk"] = {
            "risks": ["semantic/index refresh is medium indexing work and can compete with active user/game workloads"],
            "automatic": False,
        }
        candidate["blast_radius"] = {"nervous_index": True, "resource_gate": True, "stack_mutation": False}
        candidate["rollback"] = {"stack_rollback_required": False, "host_restore": "do not apply maintenance automatically; re-run read-only status if gate stays blocked"}
        reaction_add_candidate(
            candidates,
            candidate,
        )
    elif bool(readiness.get("semantic_maintenance_needed")):
        gate = nervous_semantic_resource_gate_evidence(
            nervous_brief=nervous_brief,
            readiness=readiness,
            semantic_maintain=semantic_maintain_latest,
            game_guard=game_guard_latest,
        )
        candidate = reaction_candidate(
            "nervous-semantic-maintenance-needed",
            title="Nervous semantic maintenance is needed",
            severity="warning",
            category="nervous",
            reason="Semantic sidecar drift crossed maintenance thresholds and must pass resource gates before refresh.",
            command=NERVOUS_SEMANTIC_MAINTAIN_REVIEW_COMMAND,
            evidence=[
                {"path": str(NERVOUS_BRIEF_LATEST_PATH), "readiness": readiness, "generated_at": nervous_brief.get("generated_at")},
                {"next_actions": nervous_brief.get("next_actions")},
                {"semantic_resource_gate": gate},
            ],
        )
        candidate["resource_gate"] = gate
        candidate["safe_next_action"] = gate["safe_next_action"]
        reaction_add_candidate(
            candidates,
            candidate,
        )

    recommendations = resource_orch.get("recommendations") if isinstance(resource_orch.get("recommendations"), list) else []
    for item in recommendations:
        text = str(item)
        if "GNOME Shell compositor pressure" in text:
            route = desktop_compositor_pressure_route(
                desktop_doc=desktop_compositor_latest,
                resource_orch=resource_orch,
            )
            candidate = reaction_candidate(
                "desktop-compositor-pressure-review",
                title="Desktop compositor pressure should stay visible",
                severity="notice",
                category="desktop",
                reason=text,
                command="abyss-machine processes desktop-compositor --seconds 3 --interval 0.5 --json",
                owner_route="abyss-machine:desktop",
                action_mode="observe_only_review",
                evidence=[
                    {"path": str(RESOURCE_ORCHESTRATOR_LATEST_PATH), "generated_at": resource_orch.get("generated_at")},
                    {"path": str(PROCESS_DESKTOP_COMPOSITOR_LATEST_PATH), "generated_at": desktop_compositor_latest.get("generated_at"), "summary": desktop_compositor_latest.get("summary")},
                    {"recommendation": text},
                ],
            )
            candidate["desktop_compositor_route"] = route
            candidate["safe_next_action"] = route.get("safe_next_action")
            reaction_add_candidate(candidates, candidate)

    retention_candidates = int(nested_get(retention_latest, ["summary", "candidates"]) or 0)
    retention_route_errors = int(nested_get(retention_latest, ["summary", "route_errors"]) or 0)
    if retention_candidates > 0 or retention_route_errors > 0:
        severity = "warning" if retention_route_errors > 0 else "notice"
        route = nervous_retention_privacy_route(retention_latest)
        candidate = reaction_candidate(
            "nervous-retention-review",
            title="Nervous retention has cleanup review work",
            severity=severity,
            category="privacy",
            reason=(
                "Nervous retention route errors need review."
                if retention_route_errors > 0
                else "Nervous retention candidates exist; any cleanup must stay owner-gated."
            ),
            command="abyss-machine nervous retention-apply --dry-run --json",
            owner_route="abyss-machine:nervous-privacy",
            action_mode="owner_gated_retention_review",
            evidence=[
                {
                    "path": str(NERVOUS_RETENTION_LATEST_PATH),
                    "generated_at": retention_latest.get("generated_at"),
                    "summary": retention_latest.get("summary"),
                }
            ],
        )
        candidate["nervous_retention_route"] = route
        candidate["safe_next_action"] = route.get("safe_next_action")
        reaction_add_candidate(candidates, candidate)

    ai_workhorse_fails = int(nested_get(ai_workhorse_validate, ["summary", "fails"]) or 0)
    if ai_workhorse_fails > 0:
        non_ok = [
            {"key": item.get("key"), "level": item.get("level"), "message": item.get("message")}
            for item in ai_workhorse_validate.get("checks", [])
            if isinstance(item, dict) and item.get("level") != "ok"
        ][:8]
        reaction_add_candidate(
            candidates,
            reaction_candidate(
                "ai-workhorse-hygiene-review",
                title="AI workhorse hygiene validator has failures",
                severity="warning",
                category="ai",
                reason="Workhorse source-ID provenance or action-card hygiene is not clean; refresh deterministic review or inspect before promotion.",
                command="abyss-machine ai llm workhorse review --json",
                evidence=[
                    {
                        "path": str(AI_LLM_WORKHORSE_VALIDATE_LATEST_PATH),
                        "generated_at": ai_workhorse_validate.get("generated_at"),
                        "summary": ai_workhorse_validate.get("summary"),
                    },
                    {"non_ok_checks": non_ok},
                ],
            ),
        )

    latest_event = nervous_events.get("latest_event") if isinstance(nervous_events.get("latest_event"), dict) else {}
    latest_event_severity = str(latest_event.get("severity") or "")
    if latest_event_severity in {"warning", "watch"}:
        reaction_add_candidate(
            candidates,
            reaction_candidate(
                "latest-nervous-event-attention",
                title="Latest nervous event needs attention",
                severity="watch" if latest_event_severity == "watch" else "warning",
                category=str(latest_event.get("category") or "nervous"),
                reason=str(latest_event.get("title") or "Latest event is warning/watch severity."),
                command="abyss-machine nervous recall --query latest --json",
                evidence=[
                    {"path": str(NERVOUS_EVENTS_LATEST_PATH), "latest_event": latest_event, "generated_at": nervous_events.get("generated_at")},
                ],
            ),
        )

    for item in self_awareness_alerts_latest.get("candidates", []) if isinstance(self_awareness_alerts_latest.get("candidates"), list) else []:
        if not isinstance(item, dict):
            continue
        candidate = dict(item)
        candidate["automatic"] = False
        candidate.setdefault("action_mode", "operator_review")
        candidate.setdefault("owner_route", "abyss-machine:self-awareness")
        candidate.setdefault("category", "self-awareness")
        candidate.setdefault("command", "abyss-machine self-awareness brief --json")
        evidence = candidate.get("evidence") if isinstance(candidate.get("evidence"), list) else []
        evidence.append({"path": str(SELF_AWARENESS_ALERTS_LATEST_PATH), "generated_at": self_awareness_alerts_latest.get("generated_at")})
        candidate["evidence"] = evidence
        reaction_add_candidate(candidates, candidate)

    host_owner_gap_candidates_count = sum(1 for item in candidates if isinstance(item, dict) and isinstance(item.get("host_owner_gap"), dict))
    working_stack_activation_gap_candidates = [
        item for item in candidates
        if isinstance(item, dict) and self_awareness_working_stack_activation_gap_route_complete(item.get("activation_gap_route"))
    ]
    stack_requirement_handoff_candidates = [
        item for item in candidates
        if isinstance(item, dict) and self_awareness_stack_requirement_handoff_route_complete(item.get("stack_requirement_route"))
    ]
    memory_hotpath_candidates = [
        item for item in candidates
        if isinstance(item, dict) and memory_hotpath_probe_route_complete(item.get("memory_hotpath_route"))
    ]
    doctor_warning_candidates = [
        item for item in candidates
        if isinstance(item, dict) and doctor_warning_route_complete(item.get("doctor_warning_route"))
    ]
    desktop_compositor_pressure_candidates = [
        item for item in candidates
        if isinstance(item, dict) and desktop_compositor_pressure_route_complete(item.get("desktop_compositor_route"))
    ]
    nervous_retention_privacy_candidates = [
        item for item in candidates
        if isinstance(item, dict) and nervous_retention_privacy_route_complete(item.get("nervous_retention_route"))
    ]
    backup_plane_candidates = [
        item for item in candidates
        if isinstance(item, dict) and abyssvault_backup_plane_route_complete(item.get("backup_plane_route"))
    ]
    data: dict[str, Any] = runtime_evidence_contracts.reaction_status_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        candidates=candidates,
        inputs={
            "nervous_events": {"path": str(NERVOUS_EVENTS_LATEST_PATH), "ok": nervous_events.get("ok"), "generated_at": nervous_events.get("generated_at")},
            "nervous_brief": {"path": str(NERVOUS_BRIEF_LATEST_PATH), "ok": nervous_brief.get("ok"), "readiness": readiness, "generated_at": nervous_brief.get("generated_at")},
            "doctor": {"path": str(DOCTOR_LATEST_PATH), "ok": doctor_latest.get("ok"), "summary": doctor_summary, "generated_at": doctor_latest.get("generated_at")},
            "doctor_machine_report": {"path": str(DOCTOR_MACHINE_REPORT_LATEST_PATH), "ok": machine_report.get("ok"), "status": machine_report.get("status"), "generated_at": machine_report.get("generated_at")},
            "resource_orchestrator": {"path": str(RESOURCE_ORCHESTRATOR_LATEST_PATH), "ok": resource_orch.get("ok"), "summary": resource_orch.get("summary"), "generated_at": resource_orch.get("generated_at")},
            "desktop_compositor": {"path": str(PROCESS_DESKTOP_COMPOSITOR_LATEST_PATH), "ok": desktop_compositor_latest.get("ok"), "summary": desktop_compositor_latest.get("summary"), "generated_at": desktop_compositor_latest.get("generated_at")},
            "nervous_retention": {"path": str(NERVOUS_RETENTION_LATEST_PATH), "ok": retention_latest.get("ok"), "summary": retention_latest.get("summary"), "generated_at": retention_latest.get("generated_at")},
            "ai_workhorse_validate": {"path": str(AI_LLM_WORKHORSE_VALIDATE_LATEST_PATH), "ok": ai_workhorse_validate.get("ok"), "summary": ai_workhorse_validate.get("summary"), "generated_at": ai_workhorse_validate.get("generated_at")},
            "self_awareness_alerts": {"path": str(SELF_AWARENESS_ALERTS_LATEST_PATH), "ok": self_awareness_alerts_latest.get("ok"), "summary": self_awareness_alerts_latest.get("summary"), "generated_at": self_awareness_alerts_latest.get("generated_at")},
            "backup": {"path": str(BACKUP_LATEST_PATH), "ok": backup_latest.get("ok", True), "status": backup_latest.get("status"), "generated_at": backup_latest.get("generated_at")},
            "changes": {"path": str(CHANGE_INDEX_PATH), "active_records": nested_get(changes_index, ["summary", "active_records"]), "generated_at": changes_index.get("generated_at")},
            "host_owner_gaps": {"candidates": host_owner_gap_candidates_count},
            "doctor_unit": {"state": doctor_unit, "show": doctor_unit_show},
        },
        paths=reaction_paths(),
        metrics={
            "self_awareness_response_depth": sum(1 for item in candidates if isinstance(item, dict) and item.get("category") == "self-awareness" and self_awareness_reaction_candidate_response_depth_complete(item)),
            "working_stack_activation_gap_candidates": len(working_stack_activation_gap_candidates),
            "stack_requirement_handoff_candidates": len(stack_requirement_handoff_candidates),
            "memory_hotpath_candidates": len(memory_hotpath_candidates),
            "doctor_warning_candidates": len(doctor_warning_candidates),
            "desktop_compositor_pressure_candidates": len(desktop_compositor_pressure_candidates),
            "nervous_retention_privacy_candidates": len(nervous_retention_privacy_candidates),
            "abyssvault_backup_plane_candidates": len(backup_plane_candidates),
            "host_owner_gap_candidates": host_owner_gap_candidates_count,
        },
    )
    if write_latest:
        errors = write_latest_and_history(data, REACTIONS_LATEST_PATH, REACTIONS_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def reaction_validate(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    validation_add_path_exists(checks, "agent_card", REACTIONS_AGENTS_PATH, "file", required=True)
    validation_add_path_exists(checks, "root", REACTIONS_ROOT, "dir", required=False)
    latest = load_latest_json(REACTIONS_LATEST_PATH, f"{SCHEMA_PREFIX}_reactions_status_v1")
    topology_validation_add(
        checks,
        "ok" if latest.get("ok") else "warn",
        "latest",
        "reaction latest is readable" if latest.get("ok") else "reaction latest missing or invalid",
        {"path": str(REACTIONS_LATEST_PATH), "error": latest.get("error")},
    )
    auto_candidates = [
        item.get("id")
        for item in latest.get("candidates", [])
        if isinstance(item, dict) and bool(item.get("automatic"))
    ]
    topology_validation_add(
        checks,
        "fail" if auto_candidates else "ok",
        "no_automatic_candidates",
        "reaction candidates are non-executing" if not auto_candidates else "reaction candidates request automatic execution",
        {"automatic_candidate_ids": auto_candidates},
    )
    candidates = latest.get("candidates") if isinstance(latest.get("candidates"), list) else []
    self_awareness_candidates = [item for item in candidates if isinstance(item, dict) and item.get("category") == "self-awareness"]
    shallow_self_awareness = [
        item.get("id")
        for item in self_awareness_candidates
        if not self_awareness_reaction_candidate_response_depth_complete(item)
    ]
    topology_validation_add(
        checks,
        "fail" if shallow_self_awareness else "ok",
        "self_awareness_response_candidate_depth",
        "self-awareness reaction candidates carry episode lineage, response contract, entity-event-document context, risk, blast radius, rollback, and runbook candidate",
        {"shallow_candidate_ids": shallow_self_awareness, "self_awareness_candidates": len(self_awareness_candidates)},
    )
    missing_body_trace_candidates = [
        item.get("id")
        for item in self_awareness_candidates
        if not self_awareness_body_trace_complete(nested_get(item, ["response_contract", "body_trace"]))
    ]
    topology_validation_add(
        checks,
        "fail" if missing_body_trace_candidates else "ok",
        "self_awareness_response_candidate_body_trace",
        "self-awareness reaction candidates carry temporal, spatial, contextual, and host-body trace evidence",
        {"missing_body_trace_candidate_ids": missing_body_trace_candidates, "self_awareness_candidates": len(self_awareness_candidates)},
    )
    missing_entity_event_document_candidates = [
        item.get("id")
        for item in self_awareness_candidates
        if not self_awareness_response_entity_event_document_context_complete(nested_get(item, ["response_contract", "entity_event_document_context"]))
    ]
    topology_validation_add(
        checks,
        "fail" if missing_entity_event_document_candidates else "ok",
        "self_awareness_response_candidate_entity_event_document_context",
        "self-awareness reaction candidates carry automatic entity, event, document, and route bindings",
        {"missing_entity_event_document_candidate_ids": missing_entity_event_document_candidates, "self_awareness_candidates": len(self_awareness_candidates)},
    )
    working_stack_gap_candidates = [
        item for item in self_awareness_candidates
        if nested_get(item, ["response_contract", "validated_episode", "episode_kind"]) == "working_stack_usage_gap"
    ]
    working_stack_activation_gap_bad = [
        item.get("id")
        for item in working_stack_gap_candidates
        if (
            not self_awareness_working_stack_activation_gap_route_complete(item.get("activation_gap_route"))
            or item.get("activation_gap_route") != nested_get(item, ["response_contract", "activation_gap_route"])
            or nested_get(item, ["activation_gap_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["activation_gap_route", "policy", "executes_commands"]) is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if working_stack_activation_gap_bad else "ok",
        "working_stack_activation_gap_candidates",
        "working-stack activation-gap candidates preserve per-service classification, smoke lineage, and non-mutating owner handoff route",
        {
            "working_stack_gap_candidates": len(working_stack_gap_candidates),
            "activation_gap_candidate_routes": sum(1 for item in working_stack_gap_candidates if self_awareness_working_stack_activation_gap_route_complete(item.get("activation_gap_route"))),
            "bad_candidate_ids": working_stack_activation_gap_bad,
        },
    )
    stack_handoff_candidates = [
        item for item in self_awareness_candidates
        if nested_get(item, ["response_contract", "validated_episode", "episode_kind"]) == "stack_handoff_blocker"
    ]
    stack_requirement_handoff_bad = [
        item.get("id")
        for item in stack_handoff_candidates
        if (
            not self_awareness_stack_requirement_handoff_route_complete(item.get("stack_requirement_route"))
            or item.get("stack_requirement_route") != nested_get(item, ["response_contract", "stack_requirement_route"])
            or nested_get(item, ["stack_requirement_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["stack_requirement_route", "policy", "executes_commands"]) is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if stack_requirement_handoff_bad else "ok",
        "stack_requirement_handoff_candidates",
        "stack-owned requirement handoff candidates preserve typed closure route, replay lineage, and non-mutating owner handoff policy",
        {
            "stack_handoff_candidates": len(stack_handoff_candidates),
            "stack_requirement_handoff_routes": sum(1 for item in stack_handoff_candidates if self_awareness_stack_requirement_handoff_route_complete(item.get("stack_requirement_route"))),
            "bad_candidate_ids": stack_requirement_handoff_bad,
        },
    )
    memory_hotpath_candidates = [
        item for item in candidates
        if isinstance(item, dict) and str(item.get("id") or "").startswith("memory-hotpath-probe")
    ]
    memory_hotpath_bad = [
        item.get("id")
        for item in memory_hotpath_candidates
        if (
            not memory_hotpath_probe_route_complete(item.get("memory_hotpath_route"))
            or nested_get(item, ["memory_hotpath_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["memory_hotpath_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["memory_hotpath_route", "policy", "does_not_apply_cgroup_properties"]) is not True
            or item.get("safe_next_action") != nested_get(item, ["memory_hotpath_route", "safe_next_action"])
        )
    ]
    topology_validation_add(
        checks,
        "fail" if memory_hotpath_bad else "ok",
        "memory_hotpath_probe_candidates",
        "memory hot-path probe candidates preserve current measurement status, latency/swap evidence, and non-mutating measurement-only route",
        {
            "memory_hotpath_candidates": len(memory_hotpath_candidates),
            "memory_hotpath_routes": sum(1 for item in memory_hotpath_candidates if memory_hotpath_probe_route_complete(item.get("memory_hotpath_route"))),
            "bad_candidate_ids": memory_hotpath_bad,
        },
    )
    doctor_warning_candidates = [
        item for item in candidates
        if isinstance(item, dict) and item.get("id") == "doctor-warnings-present"
    ]
    doctor_warning_bad = [
        item.get("id")
        for item in doctor_warning_candidates
        if (
            not doctor_warning_route_complete(item.get("doctor_warning_route"))
            or nested_get(item, ["doctor_warning_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["doctor_warning_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["doctor_warning_route", "policy", "review_only"]) is not True
            or item.get("safe_next_action") != nested_get(item, ["doctor_warning_route", "safe_next_action"])
        )
    ]
    topology_validation_add(
        checks,
        "fail" if doctor_warning_bad else "ok",
        "doctor_warning_candidates",
        "doctor warning candidates preserve warning checks, machine-report context, and non-mutating review-only route",
        {
            "doctor_warning_candidates": len(doctor_warning_candidates),
            "doctor_warning_routes": sum(1 for item in doctor_warning_candidates if doctor_warning_route_complete(item.get("doctor_warning_route"))),
            "bad_candidate_ids": doctor_warning_bad,
        },
    )
    desktop_compositor_candidates = [
        item for item in candidates
        if isinstance(item, dict) and item.get("id") == "desktop-compositor-pressure-review"
    ]
    desktop_compositor_bad = [
        item.get("id")
        for item in desktop_compositor_candidates
        if (
            not desktop_compositor_pressure_route_complete(item.get("desktop_compositor_route"))
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "does_not_kill_or_throttle"]) is not True
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "does_not_toggle_gnome_extensions"]) is not True
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "does_not_lower_refresh_or_quality"]) is not True
            or nested_get(item, ["desktop_compositor_route", "policy", "observe_only"]) is not True
            or nested_get(item, ["desktop_compositor_route", "policy", "mutates_desktop_state"]) is not False
            or nested_get(item, ["desktop_compositor_route", "policy", "redacts_process_cmdline"]) is not True
            or item.get("safe_next_action") != nested_get(item, ["desktop_compositor_route", "safe_next_action"])
        )
    ]
    topology_validation_add(
        checks,
        "fail" if desktop_compositor_bad else "ok",
        "desktop_compositor_pressure_candidates",
        "desktop compositor pressure candidates preserve CPU/display/churn context and observe-only route policy",
        {
            "desktop_compositor_candidates": len(desktop_compositor_candidates),
            "desktop_compositor_routes": sum(1 for item in desktop_compositor_candidates if desktop_compositor_pressure_route_complete(item.get("desktop_compositor_route"))),
            "bad_candidate_ids": desktop_compositor_bad,
        },
    )
    nervous_retention_candidates = [
        item for item in candidates
        if isinstance(item, dict) and item.get("id") == "nervous-retention-review"
    ]
    nervous_retention_bad = [
        item.get("id")
        for item in nervous_retention_candidates
        if (
            not nervous_retention_privacy_route_complete(item.get("nervous_retention_route"))
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "requires_explicit_confirm_for_deletion"]) is not True
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "does_not_delete_facts"]) is not True
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "does_not_delete_project_roots"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "dry_run_first"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "default_apply_dry_run"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "facts_delete_behavior_explicit_forget_only"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "no_project_repo_mutation"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "raw_private_content"]) is not False
            or item.get("safe_next_action") != nested_get(item, ["nervous_retention_route", "safe_next_action"])
        )
    ]
    topology_validation_add(
        checks,
        "fail" if nervous_retention_bad else "ok",
        "nervous_retention_privacy_candidates",
        "nervous retention candidates preserve layer counts, dry-run-first owner gate, and no project/fact deletion policy",
        {
            "nervous_retention_candidates": len(nervous_retention_candidates),
            "nervous_retention_routes": sum(1 for item in nervous_retention_candidates if nervous_retention_privacy_route_complete(item.get("nervous_retention_route"))),
            "bad_candidate_ids": nervous_retention_bad,
        },
    )
    backup_plane_candidates = [
        item for item in candidates
        if isinstance(item, dict) and item.get("id") == "abyssvault-backup-plane-open"
    ]
    backup_plane_bad = [
        item.get("id")
        for item in backup_plane_candidates
        if (
            not abyssvault_backup_plane_route_complete(item.get("backup_plane_route"))
            or nested_get(item, ["backup_plane_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["backup_plane_route", "safe_next_action", "writes_abyss_vault"]) is not False
            or nested_get(item, ["backup_plane_route", "policy", "keeps_change_open_until_verified"]) is not True
            or item.get("safe_next_action") != nested_get(item, ["backup_plane_route", "safe_next_action"])
            or not item.get("runbook_candidate")
        )
    ]
    changes_index = load_latest_json(CHANGE_INDEX_PATH, f"{SCHEMA_PREFIX}_changes_index_v1")
    backup_plane_active = abyssvault_backup_plane_active_change(changes_index) is not None
    backup_plane_present_ids = {str(item.get("id")) for item in backup_plane_candidates if item.get("id")}
    missing_backup_plane_ids = []
    if backup_plane_active and "abyssvault-backup-plane-open" not in backup_plane_present_ids:
        missing_backup_plane_ids.append("abyssvault-backup-plane-open")
    topology_validation_add(
        checks,
        "fail" if backup_plane_bad or missing_backup_plane_ids else "ok",
        "abyssvault_backup_plane_candidates",
        "ABYSSVAULT backup-plane active change has an owner-gated, non-executing reaction route",
        {
            "backup_plane_active": backup_plane_active,
            "backup_plane_candidates": len(backup_plane_candidates),
            "bad_candidate_ids": backup_plane_bad,
            "missing_expected_candidate_ids": missing_backup_plane_ids,
        },
    )
    host_owner_gap_candidates = [item for item in candidates if isinstance(item, dict) and isinstance(item.get("host_owner_gap"), dict)]
    host_owner_gap_bad = [
        item.get("id")
        for item in host_owner_gap_candidates
        if (
            item.get("automatic") is not False
            or nested_get(item, ["safe_next_action", "requires_human_approval"]) is not True
            or nested_get(item, ["safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["host_owner_gap", "policy", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["host_owner_gap", "policy", "executes_commands"]) is not False
            or not item.get("runbook_candidate")
        )
    ]
    stack_bridge_validate_doc = stack_bridge_validate(strict=False, write_latest=True)
    static_bridge_open = any(
        isinstance(check, dict)
        and (check.get("key") or check.get("id")) == "static_bridge_sync"
        and str(check.get("level") or check.get("status") or "").lower() in {"warn", "warning", "fail", "open"}
        for check in (stack_bridge_validate_doc.get("checks") if isinstance(stack_bridge_validate_doc.get("checks"), list) else [])
    )
    manual_collect_doc = observability_manual_collect_probe()
    expected_host_gap_ids = []
    if static_bridge_open:
        expected_host_gap_ids.append("host-static-bridge-sync-root-review")
    if manual_collect_doc.get("status") not in {None, "ready"}:
        expected_host_gap_ids.append("host-observability-manual-collect-permission-review")
    present_host_gap_ids = {str(item.get("id")) for item in host_owner_gap_candidates if item.get("id")}
    missing_host_gap_ids = [item for item in expected_host_gap_ids if item not in present_host_gap_ids]
    topology_validation_add(
        checks,
        "fail" if host_owner_gap_bad or missing_host_gap_ids else "ok",
        "host_owner_gap_candidates",
        "host-owned root/operator blockers have non-executing owner-gated reaction candidates",
        {
            "host_owner_gap_candidates": len(host_owner_gap_candidates),
            "bad_candidate_ids": host_owner_gap_bad,
            "missing_expected_candidate_ids": missing_host_gap_ids,
            "static_bridge_open": static_bridge_open,
            "manual_collect_status": manual_collect_doc.get("status"),
        },
    )
    nervous_gate_candidates = [
        item for item in candidates
        if isinstance(item, dict) and item.get("id") in {"nervous-readiness-not-ready", "nervous-semantic-maintenance-needed"}
    ]
    nervous_gate_bad = [
        item.get("id")
        for item in nervous_gate_candidates
        if not nervous_resource_gate_complete(item)
    ]
    topology_validation_add(
        checks,
        "fail" if nervous_gate_bad else "ok",
        "nervous_resource_gate_candidates",
        "nervous semantic/readiness candidates preserve resource-gate denial evidence and non-bypass policy",
        {"nervous_gate_candidate_ids": [item.get("id") for item in nervous_gate_candidates], "bad_candidate_ids": nervous_gate_bad},
    )
    policy = latest.get("policy") if isinstance(latest.get("policy"), dict) else {}
    if latest.get("ok"):
        topology_validation_add(
            checks,
            "ok" if policy.get("automatic_action") is False and policy.get("executes_commands") is False else "fail",
            "policy_non_executing",
            "reaction policy is evidence-only and non-executing",
            {"policy": policy},
        )
    else:
        topology_validation_add(
            checks,
            "warn",
            "policy_non_executing",
            "reaction latest must be generated before policy can be checked",
            {"path": str(REACTIONS_LATEST_PATH), "error": latest.get("error")},
        )
    bridge = bridge_manifest()
    commands = bridge.get("commands") if isinstance(bridge.get("commands"), dict) else {}
    missing_commands = [
        key for key in ("reactions_status_json", "reactions_paths_json", "reactions_validate_json")
        if key not in commands
    ]
    topology_validation_add(
        checks,
        "fail" if missing_commands else "ok",
        "bridge_commands",
        "bridge exposes reaction commands" if not missing_commands else "bridge misses reaction commands",
        {"missing": missing_commands},
    )
    data = reactions_validate_document_from_checks(
        checks,
        strict=strict,
        paths=reaction_paths(),
    )
    if write_latest:
        errors = write_latest_and_history(data, REACTIONS_VALIDATE_LATEST_PATH, REACTIONS_VALIDATE_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def print_reaction_status_text(data: dict[str, Any]) -> None:
    summary = data.get("summary", {}) if isinstance(data.get("summary"), dict) else {}
    print(f"reactions: {summary.get('status')} candidates={summary.get('candidates')}")
    for item in data.get("candidates", [])[:8]:
        if not isinstance(item, dict):
            continue
        print(f"{item.get('severity'):<8} {item.get('id')}: {item.get('title')}")


def response_paths() -> dict[str, Any]:
    return runtime_evidence_contracts.response_paths_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        refs={
            "root": RESPONSES_ROOT,
            "agent_entrypoint": RESPONSES_AGENTS_PATH,
            "latest": RESPONSES_LATEST_PATH,
            "validate_root": RESPONSES_VALIDATE_ROOT,
            "validate_latest": RESPONSES_VALIDATE_LATEST_PATH,
        },
        inputs={
            "heartbeats": str(HEARTBEATS_LATEST_PATH),
            "reactions": str(REACTIONS_LATEST_PATH),
            "changes": str(CHANGE_INDEX_PATH),
        },
    )


def responses_validate_document_from_checks(
    checks: list[dict[str, Any]],
    *,
    strict: bool,
    paths: dict[str, Any],
    generated_at: str | None = None,
) -> dict[str, Any]:
    return runtime_evidence_contracts.responses_validate_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=generated_at or now_iso(),
        checks=checks,
        strict=strict,
        paths=paths,
    )


def response_command_profile(command: str | None) -> dict[str, Any]:
    return runtime_evidence_contracts.response_command_profile(command)


def response_route_from_candidate(candidate: dict[str, Any]) -> dict[str, Any]:
    return runtime_evidence_contracts.response_route_from_candidate(SCHEMA_PREFIX, candidate)


def response_status(
    write_latest: bool = True,
    *,
    reactions: dict[str, Any] | None = None,
    refresh_reactions: bool = True,
) -> dict[str, Any]:
    if reactions is None:
        if refresh_reactions:
            reactions = reaction_status(write_latest=True)
        else:
            reactions = load_latest_json(REACTIONS_LATEST_PATH, f"{SCHEMA_PREFIX}_reactions_status_v1")
    heartbeat = load_latest_json(HEARTBEATS_LATEST_PATH, f"{SCHEMA_PREFIX}_heartbeat_pulse_v1")
    changes = load_latest_json(CHANGE_INDEX_PATH, f"{SCHEMA_PREFIX}_changes_index_v1")
    candidates = reactions.get("candidates") if isinstance(reactions.get("candidates"), list) else []
    routes = [response_route_from_candidate(item) for item in candidates if isinstance(item, dict)]
    self_awareness_routes = [item for item in routes if isinstance(item, dict) and item.get("category") == "self-awareness"]
    self_awareness_body_trace_routes = [
        item for item in self_awareness_routes
        if self_awareness_body_trace_complete(nested_get(item, ["response_contract", "body_trace"]))
    ]
    self_awareness_entity_event_document_routes = [
        item for item in self_awareness_routes
        if self_awareness_response_entity_event_document_context_complete(nested_get(item, ["response_contract", "entity_event_document_context"]))
    ]
    working_stack_activation_gap_routes = [
        item for item in self_awareness_routes
        if self_awareness_working_stack_activation_gap_route_complete(item.get("activation_gap_route"))
    ]
    stack_requirement_handoff_routes = [
        item for item in self_awareness_routes
        if self_awareness_stack_requirement_handoff_route_complete(item.get("stack_requirement_route"))
    ]
    memory_hotpath_routes = [
        item for item in routes
        if isinstance(item, dict) and memory_hotpath_probe_route_complete(item.get("memory_hotpath_route"))
    ]
    doctor_warning_routes = [
        item for item in routes
        if isinstance(item, dict) and doctor_warning_route_complete(item.get("doctor_warning_route"))
    ]
    desktop_compositor_pressure_routes = [
        item for item in routes
        if isinstance(item, dict) and desktop_compositor_pressure_route_complete(item.get("desktop_compositor_route"))
    ]
    nervous_retention_privacy_routes = [
        item for item in routes
        if isinstance(item, dict) and nervous_retention_privacy_route_complete(item.get("nervous_retention_route"))
    ]
    backup_plane_routes = [
        item for item in routes
        if isinstance(item, dict) and abyssvault_backup_plane_route_complete(item.get("backup_plane_route"))
    ]
    data: dict[str, Any] = runtime_evidence_contracts.response_status_document(
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        generated_at=now_iso(),
        routes=routes,
        reactions=reactions,
        heartbeat=heartbeat,
        changes=changes,
        paths=response_paths(),
        metrics={
            "self_awareness_response_depth": sum(1 for item in self_awareness_routes if self_awareness_response_route_depth_complete(item)),
            "self_awareness_body_trace_route_ids": [str(item.get("id")) for item in self_awareness_body_trace_routes if item.get("id")],
            "self_awareness_entity_event_document_route_ids": [str(item.get("id")) for item in self_awareness_entity_event_document_routes if item.get("id")],
            "working_stack_activation_gap_routes": len(working_stack_activation_gap_routes),
            "stack_requirement_handoff_routes": len(stack_requirement_handoff_routes),
            "memory_hotpath_routes": len(memory_hotpath_routes),
            "doctor_warning_routes": len(doctor_warning_routes),
            "desktop_compositor_pressure_routes": len(desktop_compositor_pressure_routes),
            "nervous_retention_privacy_routes": len(nervous_retention_privacy_routes),
            "abyssvault_backup_plane_routes": len(backup_plane_routes),
            "heartbeats_path": str(HEARTBEATS_LATEST_PATH),
            "reactions_path": str(REACTIONS_LATEST_PATH),
            "changes_path": str(CHANGE_INDEX_PATH),
        },
        self_awareness_refs=[
                {"path": str(SELF_AWARENESS_ALERTS_LATEST_PATH), "section": "candidates.body_trace"},
                {"path": str(SELF_AWARENESS_COMPLETION_AUDIT_LATEST_PATH), "section": "entity_event_document_map"},
        ],
    )
    if write_latest:
        errors = write_latest_and_history(data, RESPONSES_LATEST_PATH, RESPONSES_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def response_validate(strict: bool = False, write_latest: bool = True) -> dict[str, Any]:
    checks: list[dict[str, Any]] = []
    validation_add_path_exists(checks, "agent_card", RESPONSES_AGENTS_PATH, "file", required=True)
    validation_add_path_exists(checks, "root", RESPONSES_ROOT, "dir", required=False)
    latest = load_latest_json(RESPONSES_LATEST_PATH, f"{SCHEMA_PREFIX}_responses_status_v1")
    changes = load_latest_json(CHANGE_INDEX_PATH, f"{SCHEMA_PREFIX}_changes_index_v1")
    topology_validation_add(
        checks,
        "ok" if latest.get("ok") else "warn",
        "latest",
        "responses latest is readable" if latest.get("ok") else "responses latest missing or invalid",
        {"path": str(RESPONSES_LATEST_PATH), "error": latest.get("error")},
    )
    routes = latest.get("routes") if isinstance(latest.get("routes"), list) else []
    automatic_routes = [
        item.get("id")
        for item in routes
        if isinstance(item, dict) and (bool(item.get("automatic")) or bool(item.get("executes")))
    ]
    topology_validation_add(
        checks,
        "fail" if automatic_routes else "ok",
        "no_automatic_routes",
        "response routes are non-executing" if not automatic_routes else "response routes request execution",
        {"automatic_route_ids": automatic_routes},
    )
    ungated_routes = [
        item.get("id")
        for item in routes
        if isinstance(item, dict) and not bool(nested_get(item, ["approval", "required"]))
    ]
    topology_validation_add(
        checks,
        "fail" if ungated_routes else "ok",
        "routes_owner_gated",
        "all response routes require owner/operator approval" if not ungated_routes else "some response routes are not owner-gated",
        {"ungated_route_ids": ungated_routes},
    )
    self_awareness_routes = [item for item in routes if isinstance(item, dict) and item.get("category") == "self-awareness"]
    shallow_self_awareness_routes = [
        item.get("id")
        for item in self_awareness_routes
        if not self_awareness_response_route_depth_complete(item)
    ]
    topology_validation_add(
        checks,
        "fail" if shallow_self_awareness_routes else "ok",
        "self_awareness_response_route_depth",
        "self-awareness response routes preserve validated episode lineage, replay evidence, risk, blast radius, rollback, and runbook candidate",
        {"shallow_route_ids": shallow_self_awareness_routes, "self_awareness_routes": len(self_awareness_routes)},
    )
    missing_body_trace_routes = [
        item.get("id")
        for item in self_awareness_routes
        if not self_awareness_body_trace_complete(nested_get(item, ["response_contract", "body_trace"]))
    ]
    topology_validation_add(
        checks,
        "fail" if missing_body_trace_routes else "ok",
        "self_awareness_response_body_trace",
        "self-awareness response routes preserve temporal, spatial, contextual, and host-body trace evidence for agent body reasoning",
        {"missing_body_trace_route_ids": missing_body_trace_routes, "self_awareness_routes": len(self_awareness_routes)},
    )
    missing_entity_event_document_routes = [
        item.get("id")
        for item in self_awareness_routes
        if not self_awareness_response_entity_event_document_context_complete(nested_get(item, ["response_contract", "entity_event_document_context"]))
    ]
    topology_validation_add(
        checks,
        "fail" if missing_entity_event_document_routes else "ok",
        "self_awareness_response_entity_event_document_context",
        "self-awareness response routes preserve automatic entity, event, document, and route bindings for body reasoning",
        {
            "missing_entity_event_document_route_ids": missing_entity_event_document_routes,
            "self_awareness_routes": len(self_awareness_routes),
            "response_summary": latest.get("summary") if isinstance(latest, dict) else None,
        },
    )
    working_stack_gap_routes = [
        item for item in self_awareness_routes
        if nested_get(item, ["response_contract", "validated_episode", "episode_kind"]) == "working_stack_usage_gap"
    ]
    working_stack_activation_gap_route_bad = [
        item.get("id")
        for item in working_stack_gap_routes
        if (
            not self_awareness_working_stack_activation_gap_route_complete(item.get("activation_gap_route"))
            or item.get("activation_gap_route") != nested_get(item, ["response_contract", "activation_gap_route"])
            or nested_get(item, ["activation_gap_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["activation_gap_route", "policy", "executes_commands"]) is not False
            or item.get("executes") is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if working_stack_activation_gap_route_bad else "ok",
        "working_stack_activation_gap_response_routes",
        "working-stack activation-gap response routes preserve per-service classification, smoke lineage, and non-mutating owner handoff route",
        {
            "working_stack_gap_routes": len(working_stack_gap_routes),
            "activation_gap_response_routes": sum(1 for item in working_stack_gap_routes if self_awareness_working_stack_activation_gap_route_complete(item.get("activation_gap_route"))),
            "bad_route_ids": working_stack_activation_gap_route_bad,
        },
    )
    stack_handoff_routes = [
        item for item in self_awareness_routes
        if nested_get(item, ["response_contract", "validated_episode", "episode_kind"]) == "stack_handoff_blocker"
    ]
    stack_requirement_handoff_route_bad = [
        item.get("id")
        for item in stack_handoff_routes
        if (
            not self_awareness_stack_requirement_handoff_route_complete(item.get("stack_requirement_route"))
            or item.get("stack_requirement_route") != nested_get(item, ["response_contract", "stack_requirement_route"])
            or nested_get(item, ["stack_requirement_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["stack_requirement_route", "policy", "executes_commands"]) is not False
            or item.get("executes") is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if stack_requirement_handoff_route_bad else "ok",
        "stack_requirement_handoff_response_routes",
        "stack-owned requirement handoff response routes preserve typed closure route, replay lineage, and non-mutating owner handoff policy",
        {
            "stack_handoff_routes": len(stack_handoff_routes),
            "stack_requirement_handoff_routes": sum(1 for item in stack_handoff_routes if self_awareness_stack_requirement_handoff_route_complete(item.get("stack_requirement_route"))),
            "bad_route_ids": stack_requirement_handoff_route_bad,
        },
    )
    memory_hotpath_routes = [
        item for item in routes
        if isinstance(item, dict) and str(item.get("candidate_id") or "").startswith("memory-hotpath-probe")
    ]
    memory_hotpath_route_bad = [
        item.get("id")
        for item in memory_hotpath_routes
        if (
            not memory_hotpath_probe_route_complete(item.get("memory_hotpath_route"))
            or nested_get(item, ["memory_hotpath_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["memory_hotpath_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["memory_hotpath_route", "policy", "does_not_apply_cgroup_properties"]) is not True
            or item.get("safe_next_action") != nested_get(item, ["memory_hotpath_route", "safe_next_action"])
            or nested_get(item, ["suggestion", "command_profile", "mutating_if_run"]) is not False
            or item.get("executes") is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if memory_hotpath_route_bad else "ok",
        "memory_hotpath_probe_response_routes",
        "memory hot-path probe response routes preserve current measurement status, latency/swap evidence, and non-mutating measurement-only route",
        {
            "memory_hotpath_routes": len(memory_hotpath_routes),
            "memory_hotpath_complete_routes": sum(1 for item in memory_hotpath_routes if memory_hotpath_probe_route_complete(item.get("memory_hotpath_route"))),
            "bad_route_ids": memory_hotpath_route_bad,
        },
    )
    doctor_warning_routes = [
        item for item in routes
        if isinstance(item, dict) and item.get("candidate_id") == "doctor-warnings-present"
    ]
    doctor_warning_route_bad = [
        item.get("id")
        for item in doctor_warning_routes
        if (
            not doctor_warning_route_complete(item.get("doctor_warning_route"))
            or nested_get(item, ["doctor_warning_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["doctor_warning_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["doctor_warning_route", "policy", "review_only"]) is not True
            or item.get("safe_next_action") != nested_get(item, ["doctor_warning_route", "safe_next_action"])
            or nested_get(item, ["suggestion", "command_profile", "mutating_if_run"]) is not False
            or item.get("executes") is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if doctor_warning_route_bad else "ok",
        "doctor_warning_response_routes",
        "doctor warning response routes preserve warning checks, machine-report context, and non-mutating review-only route",
        {
            "doctor_warning_routes": len(doctor_warning_routes),
            "doctor_warning_complete_routes": sum(1 for item in doctor_warning_routes if doctor_warning_route_complete(item.get("doctor_warning_route"))),
            "bad_route_ids": doctor_warning_route_bad,
        },
    )
    desktop_compositor_routes = [
        item for item in routes
        if isinstance(item, dict) and item.get("candidate_id") == "desktop-compositor-pressure-review"
    ]
    desktop_compositor_route_bad = [
        item.get("id")
        for item in desktop_compositor_routes
        if (
            not desktop_compositor_pressure_route_complete(item.get("desktop_compositor_route"))
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "does_not_kill_or_throttle"]) is not True
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "does_not_toggle_gnome_extensions"]) is not True
            or nested_get(item, ["desktop_compositor_route", "safe_next_action", "does_not_lower_refresh_or_quality"]) is not True
            or nested_get(item, ["desktop_compositor_route", "policy", "observe_only"]) is not True
            or nested_get(item, ["desktop_compositor_route", "policy", "mutates_desktop_state"]) is not False
            or nested_get(item, ["desktop_compositor_route", "policy", "redacts_process_cmdline"]) is not True
            or item.get("safe_next_action") != nested_get(item, ["desktop_compositor_route", "safe_next_action"])
            or nested_get(item, ["suggestion", "command_profile", "mutating_if_run"]) is not False
            or item.get("executes") is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if desktop_compositor_route_bad else "ok",
        "desktop_compositor_pressure_response_routes",
        "desktop compositor pressure response routes preserve CPU/display/churn context and remain observe-only",
        {
            "desktop_compositor_routes": len(desktop_compositor_routes),
            "desktop_compositor_complete_routes": sum(1 for item in desktop_compositor_routes if desktop_compositor_pressure_route_complete(item.get("desktop_compositor_route"))),
            "bad_route_ids": desktop_compositor_route_bad,
        },
    )
    nervous_retention_routes = [
        item for item in routes
        if isinstance(item, dict) and item.get("candidate_id") == "nervous-retention-review"
    ]
    nervous_retention_route_bad = [
        item.get("id")
        for item in nervous_retention_routes
        if (
            not nervous_retention_privacy_route_complete(item.get("nervous_retention_route"))
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "requires_explicit_confirm_for_deletion"]) is not True
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "does_not_delete_facts"]) is not True
            or nested_get(item, ["nervous_retention_route", "safe_next_action", "does_not_delete_project_roots"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "dry_run_first"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "default_apply_dry_run"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "facts_delete_behavior_explicit_forget_only"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "no_project_repo_mutation"]) is not True
            or nested_get(item, ["nervous_retention_route", "policy", "raw_private_content"]) is not False
            or item.get("safe_next_action") != nested_get(item, ["nervous_retention_route", "safe_next_action"])
            or nested_get(item, ["suggestion", "command_profile", "mutating_if_run"]) is not False
            or item.get("executes") is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if nervous_retention_route_bad else "ok",
        "nervous_retention_privacy_response_routes",
        "nervous retention response routes preserve dry-run-first privacy policy and remain non-executing",
        {
            "nervous_retention_routes": len(nervous_retention_routes),
            "nervous_retention_complete_routes": sum(1 for item in nervous_retention_routes if nervous_retention_privacy_route_complete(item.get("nervous_retention_route"))),
            "bad_route_ids": nervous_retention_route_bad,
        },
    )
    backup_plane_routes = [
        item for item in routes
        if isinstance(item, dict) and item.get("candidate_id") == "abyssvault-backup-plane-open"
    ]
    backup_plane_route_bad = [
        item.get("id")
        for item in backup_plane_routes
        if (
            not abyssvault_backup_plane_route_complete(item.get("backup_plane_route"))
            or nested_get(item, ["backup_plane_route", "safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["backup_plane_route", "safe_next_action", "writes_abyss_vault"]) is not False
            or nested_get(item, ["backup_plane_route", "policy", "keeps_change_open_until_verified"]) is not True
            or item.get("safe_next_action") != nested_get(item, ["backup_plane_route", "safe_next_action"])
            or nested_get(item, ["suggestion", "command_profile", "mutating_if_run"]) is not False
            or item.get("executes") is not False
        )
    ]
    backup_plane_active = abyssvault_backup_plane_active_change(changes) is not None
    backup_plane_present_route_ids = {str(item.get("id")) for item in backup_plane_routes if item.get("id")}
    missing_backup_plane_route_ids = []
    if backup_plane_active and "abyssvault-backup-plane-open-response-route" not in backup_plane_present_route_ids:
        missing_backup_plane_route_ids.append("abyssvault-backup-plane-open-response-route")
    topology_validation_add(
        checks,
        "fail" if backup_plane_route_bad or missing_backup_plane_route_ids else "ok",
        "abyssvault_backup_plane_response_routes",
        "ABYSSVAULT backup-plane response routes preserve operator-gated mount/verify evidence and remain non-executing",
        {
            "backup_plane_active": backup_plane_active,
            "backup_plane_routes": len(backup_plane_routes),
            "backup_plane_complete_routes": sum(1 for item in backup_plane_routes if abyssvault_backup_plane_route_complete(item.get("backup_plane_route"))),
            "bad_route_ids": backup_plane_route_bad,
            "missing_expected_route_ids": missing_backup_plane_route_ids,
        },
    )
    host_owner_gap_routes = [item for item in routes if isinstance(item, dict) and isinstance(item.get("host_owner_gap"), dict)]
    host_owner_gap_route_bad = [
        item.get("id")
        for item in host_owner_gap_routes
        if (
            item.get("automatic") is not False
            or item.get("executes") is not False
            or nested_get(item, ["approval", "required"]) is not True
            or nested_get(item, ["suggestion", "command_profile", "mutating_if_run"]) is not False
            or nested_get(item, ["safe_next_action", "requires_human_approval"]) is not True
            or nested_get(item, ["safe_next_action", "executes_commands"]) is not False
            or nested_get(item, ["safe_next_action", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["host_owner_gap", "policy", "host_layer_mutates_stack"]) is not False
            or nested_get(item, ["policy", "host_owner_gap_route"]) is not True
        )
    ]
    stack_bridge_validate_doc = stack_bridge_validate(strict=False, write_latest=True)
    static_bridge_open = any(
        isinstance(check, dict)
        and (check.get("key") or check.get("id")) == "static_bridge_sync"
        and str(check.get("level") or check.get("status") or "").lower() in {"warn", "warning", "fail", "open"}
        for check in (stack_bridge_validate_doc.get("checks") if isinstance(stack_bridge_validate_doc.get("checks"), list) else [])
    )
    manual_collect_doc = observability_manual_collect_probe()
    expected_host_gap_route_ids = []
    if static_bridge_open:
        expected_host_gap_route_ids.append("host-static-bridge-sync-root-review-response-route")
    if manual_collect_doc.get("status") not in {None, "ready"}:
        expected_host_gap_route_ids.append("host-observability-manual-collect-permission-review-response-route")
    present_host_gap_route_ids = {str(item.get("id")) for item in host_owner_gap_routes if item.get("id")}
    missing_host_gap_route_ids = [item for item in expected_host_gap_route_ids if item not in present_host_gap_route_ids]
    topology_validation_add(
        checks,
        "fail" if host_owner_gap_route_bad or missing_host_gap_route_ids else "ok",
        "host_owner_gap_response_routes",
        "host-owned root/operator blockers have non-executing owner-gated response routes",
        {
            "host_owner_gap_routes": len(host_owner_gap_routes),
            "bad_route_ids": host_owner_gap_route_bad,
            "missing_expected_route_ids": missing_host_gap_route_ids,
            "static_bridge_open": static_bridge_open,
            "manual_collect_status": manual_collect_doc.get("status"),
        },
    )
    nervous_gate_routes = [
        item for item in routes
        if isinstance(item, dict) and item.get("candidate_id") in {"nervous-readiness-not-ready", "nervous-semantic-maintenance-needed"}
    ]
    nervous_gate_route_bad = [
        item.get("id")
        for item in nervous_gate_routes
        if (
            not nervous_resource_gate_complete(item)
            or nested_get(item, ["suggestion", "command_profile", "mutating_if_run"]) is not False
            or item.get("executes") is not False
        )
    ]
    topology_validation_add(
        checks,
        "fail" if nervous_gate_route_bad else "ok",
        "nervous_resource_gate_response_routes",
        "nervous response routes preserve resource-gate denial evidence and remain non-executing",
        {"nervous_gate_route_ids": [item.get("id") for item in nervous_gate_routes], "bad_route_ids": nervous_gate_route_bad},
    )
    policy = latest.get("policy") if isinstance(latest.get("policy"), dict) else {}
    if latest.get("ok"):
        topology_validation_add(
            checks,
            "ok" if policy.get("automatic_action") is False and policy.get("executes_commands") is False else "fail",
            "policy_non_executing",
            "responses policy is owner-gated and non-executing",
            {"policy": policy},
        )
    else:
        topology_validation_add(
            checks,
            "warn",
            "policy_non_executing",
            "responses latest must be generated before policy can be checked",
            {"path": str(RESPONSES_LATEST_PATH), "error": latest.get("error")},
        )
    bridge = bridge_manifest()
    commands = bridge.get("commands") if isinstance(bridge.get("commands"), dict) else {}
    missing_commands = [
        key for key in ("responses_status_json", "responses_paths_json", "responses_validate_json")
        if key not in commands
    ]
    topology_validation_add(
        checks,
        "fail" if missing_commands else "ok",
        "bridge_commands",
        "bridge exposes response commands" if not missing_commands else "bridge misses response commands",
        {"missing": missing_commands},
    )
    data = responses_validate_document_from_checks(
        checks,
        strict=strict,
        paths=response_paths(),
    )
    if write_latest:
        errors = write_latest_and_history(data, RESPONSES_VALIDATE_LATEST_PATH, RESPONSES_VALIDATE_ROOT)
        if errors:
            data["ok"] = False
            data["write_errors"] = errors
    return data


def print_response_status_text(data: dict[str, Any]) -> None:
    summary = data.get("summary", {}) if isinstance(data.get("summary"), dict) else {}
    print(
        f"responses: {summary.get('status')} "
        f"routes={summary.get('routes')} "
        f"approval_required={summary.get('approval_required')}"
    )
    for item in data.get("routes", [])[:8]:
        if not isinstance(item, dict):
            continue
        print(f"{item.get('severity'):<8} {item.get('id')}: {item.get('title')}")


def dictation_config_get() -> dict[str, Any]:
    return dictation_profile_adapters.config_read_document(
        paths=dictation_config_paths(),
        config=dictation_config(),
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        now=now_iso,
        path_exists=Path.exists,
        path_writable=lambda path: os.access(path, os.W_OK),
    )


def dictation_config_set(dotted_key: str, raw_value: str) -> dict[str, Any]:
    config = dictation_config()
    config.pop("_load_error", None)
    config.pop("_invalid_config_path", None)
    value = parse_config_value(raw_value)
    set_nested_value(config, dotted_key, value)
    save_dictation_config(config, f"set:{dotted_key}")
    return dictation_config_get()


def dictation_config_reset() -> dict[str, Any]:
    save_dictation_config(default_dictation_config(), "reset")
    return dictation_config_get()


def dictation_profile_list() -> dict[str, Any]:
    profiles = dictation_profiles()
    config = dictation_config()
    return dictation_profile_adapters.profile_list_document(
        config=config,
        profiles=profiles,
        requested_default_profile=requested_dictation_profile_name(None),
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        now=now_iso,
    )


def dictation_profile_get(name: str) -> dict[str, Any]:
    profile, selection = dictation_profile(name, None)
    return dictation_profile_adapters.profile_get_document(
        requested=name,
        profile=profile,
        selection=selection,
        schema_prefix=SCHEMA_PREFIX,
        version=VERSION,
        now=now_iso,
    )


def print_json(data: dict[str, Any]) -> None:
    print(json.dumps(data, indent=2, sort_keys=False))


def print_doctor_text(data: dict[str, Any]) -> None:
    summary = data["summary"]
    print(
        f"abyss-machine doctor: {summary['status']} state={data.get('state')} "
        f"score={data.get('readiness_score')} ({summary['fails']} fail, {summary['warnings']} warn)"
    )
    for check in data["checks"]:
        print(f"{check['level']:<4} {check['key']:<24} {check['message']}")
    actions = [item for item in data.get("safe_actions", []) if isinstance(item, dict) and item.get("needed")]
    if actions:
        print("safe actions:")
        for action in actions:
            print(f"  {action.get('action')}: {action.get('command')}")


