def print_ai_cpu_launch_text(data: dict[str, Any]) -> None:
    request = data.get("request", {}) if isinstance(data.get("request"), dict) else {}
    route = data.get("route", {}) if isinstance(data.get("route"), dict) else {}
    route_obj = route.get("route", {}) if isinstance(route.get("route"), dict) else {}
    print(f"cpu launch: ok={data.get('ok')} dry_run={data.get('dry_run')} class={request.get('class')} cpus={route_obj.get('cpuset')}")
    print(f"blocked: {','.join(data.get('blocked_reasons', [])) or 'none'}")
    execution = data.get("execution", {}) if isinstance(data.get("execution"), dict) else {}
    if execution:
        print(f"returncode: {execution.get('returncode')} elapsed={data.get('elapsed_sec')}")


def print_ai_cpu_test_text(data: dict[str, Any]) -> None:
    print(f"cpu test: ok={data.get('ok')} profile={data.get('profile')} cpus={data.get('cpuset')} elapsed={data.get('elapsed_sec')}")
